package com.osrstelemetry.plugin;

import javax.inject.Singleton;

/**
 * Detects account switches so collectors can clear per-account
 * in-memory baselines (skill XP windows, quest lastKnown snapshots,
 * Slayer task identity, bank debounce state) rather than silently
 * carrying account A's state into account B's telemetry.
 *
 * -1 is the sentinel for "no account observed yet". The first real
 * accountHash seen is a seed, not a switch — there is nothing to
 * reset on plugin startup, only on an actual A -> B transition.
 */
@Singleton
public class AccountContext
{
	private static final long NONE = -1L;

	private volatile long currentAccountHash = NONE;

	/**
	 * @return the previously-current accountHash (NONE if this is the
	 * first observation), so callers can flush anything that needs to
	 * be attributed to the OLD account before resetting.
	 */
	public synchronized long update(long observedAccountHash)
	{
		long previous = currentAccountHash;
		currentAccountHash = observedAccountHash;
		return previous;
	}

	public boolean isRealSwitch(long previousAccountHash, long newAccountHash)
	{
		return previousAccountHash != NONE && previousAccountHash != newAccountHash;
	}

	public long getCurrentAccountHash()
	{
		return currentAccountHash;
	}
}

package com.osrstelemetry.plugin;

/**
 * Player-facing display setting: the vertical order of Current Session's
 * XP (skill cards) and LOOT sections. Presentation only -- read live by
 * CurrentSessionView on every render; affects nothing else (not the Loot
 * tab, not History, not any telemetry/session logic).
 */
public enum CurrentSessionSectionOrder
{
	XP_FIRST("XP first"),
	LOOT_FIRST("Loot first");

	private final String label;

	CurrentSessionSectionOrder(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrstelemetry.plugin;

/**
 * Guardians of the Rift: what Current Session's rift advice optimises for.
 * Interpretation only -- never changes any game or session data. Chosen in the
 * panel itself (Points · XP); remembered as a hidden config value.
 */
public enum GotrStrategy
{
	/** Even reward points, so searches are not wasted. */
	POINTS("Points"),
	/** Runecraft experience. */
	XP("XP");

	private final String label;

	GotrStrategy(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrstelemetry.plugin;

/**
 * ADDED (Current Session UI facelift, PART 10). Which price source the
 * Current Session loot section both displays and sorts by. See
 * {@link OsrsTelemetryConfig#lootValuationMode()}. Deliberately just
 * these two options, per the task's explicit "do not add unnecessary
 * valuation settings in this pass" instruction.
 */
public enum LootValuationMode
{
	GRAND_EXCHANGE("Grand Exchange"),
	HIGH_ALCH("High Alch");

	private final String label;

	LootValuationMode(String label)
	{
		this.label = label;
	}

	/** RuneLite's config UI renders enum dropdown options via toString(). */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.osrstelemetry.plugin;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Player-facing presentation settings only, each read live by the UI on
 * every render. Telemetry collection is deliberately not configurable:
 * every collector runs while Spyglass is enabled. The former collect*
 * keys were deleted, not hidden; values old profiles still store for them
 * are simply never read.
 */
@ConfigGroup("osrstelemetry")
public interface OsrsTelemetryConfig extends Config
{
	// Sections follow each setting's real consumers. "General" (key "shared")
	// = read by more than one tab. No setting is exclusive to the Loot
	// Tracker or History, so neither has a section. Section/item NAMES are
	// player-facing; the key names are storage and never change.

	@ConfigSection(
		name = "General",
		description = "Settings that apply across Spyglass.",
		position = 0
	)
	String SHARED_SECTION = "shared";

	@ConfigSection(
		name = "Current Session",
		description = "How the Session tab is laid out.",
		position = 1
	)
	String CURRENT_SESSION_SECTION = "currentSession";

	// Read by CurrentSessionView, LootTrackerView and HistoryDetailView;
	// drives both displayed gp values and loot sort order (see LootPricing).
	@ConfigItem(
		keyName = "lootValuationMode",
		name = "Loot valuation",
		description = "The price used to value and sort loot on the Session, Loot and History tabs.",
		position = 1,
		section = SHARED_SECTION
	)
	default LootValuationMode lootValuationMode()
	{
		return LootValuationMode.GRAND_EXCHANGE;
	}

	@ConfigItem(
		keyName = "currentSessionSectionOrder",
		name = "XP / Loot order",
		description = "Which section the Session tab shows first: XP, or Loot (Task History during Slayer).",
		position = 1,
		section = CURRENT_SESSION_SECTION
	)
	default CurrentSessionSectionOrder currentSessionSectionOrder()
	{
		return CurrentSessionSectionOrder.XP_FIRST;
	}

	@ConfigItem(
		keyName = "slayerXpScope",
		name = "Slayer XP scope",
		description = "What the Slayer XP section counts: every task this session, or only your current task. You can also switch this from the XP section itself. Display only.",
		position = 2,
		section = CURRENT_SESSION_SECTION
	)
	default SlayerXpScope slayerXpScope()
	{
		return SlayerXpScope.ALL_TASKS;
	}
}

package com.osrstelemetry.plugin;

import com.google.inject.Provides;
import com.osrstelemetry.plugin.collectors.ActivityKillCountCollector;
import com.osrstelemetry.plugin.collectors.BossActivityContextCollector;
import com.osrstelemetry.plugin.collectors.CollectionLogCollector;
import com.osrstelemetry.plugin.collectors.CombatAchievementCollector;
import com.osrstelemetry.plugin.collectors.ContainerCollector;
import com.osrstelemetry.plugin.collectors.IdentityCollector;
import com.osrstelemetry.plugin.collectors.KnownBossRegistry;
import com.osrstelemetry.plugin.collectors.LoadoutArchiveCollector;
