package com.osrstelemetry.plugin.activity;

import net.runelite.api.gameval.VarbitID;

/**
 * The six Barrows brothers and the game's own per-brother "killed this
 * run" varbits (the same ones RuneLite's core Barrows plugin reads for its
 * brothers overlay). The varbit is 1 once that brother has been defeated in
 * the current run and returns to 0 when the game starts a new run -- Spyglass
 * only mirrors it; it never decides by itself that a brother is cleared.
 *
 * {@link #getSchematicRow()}/{@link #getSchematicColumn()} place each mound on
 * a 3x3 grid by its real map position (north up), purely so the progress
 * block reads like the mound layout. It is not a map and not a route.
 */
public enum BarrowsBrother
{
	// Mound centres (RuneLite's BarrowsBrothers): Verac 3557,3298  Dharok 3575,3298
	// Torag 3553,3283  Ahrim 3566,3289  Guthan 3577,3283  Karil 3566,3275
	AHRIM("Ahrim", VarbitID.BARROWS_KILLED_AHRIM, 1, 1),
	DHAROK("Dharok", VarbitID.BARROWS_KILLED_DHAROK, 0, 2),
	GUTHAN("Guthan", VarbitID.BARROWS_KILLED_GUTHAN, 1, 2),
	KARIL("Karil", VarbitID.BARROWS_KILLED_KARIL, 2, 1),
	TORAG("Torag", VarbitID.BARROWS_KILLED_TORAG, 1, 0),
	VERAC("Verac", VarbitID.BARROWS_KILLED_VERAC, 0, 0);

	private final String displayName;
	private final int killedVarbit;
	private final int schematicRow;
	private final int schematicColumn;

	BarrowsBrother(String displayName, int killedVarbit, int schematicRow, int schematicColumn)
	{
		this.displayName = displayName;
		this.killedVarbit = killedVarbit;
		this.schematicRow = schematicRow;
		this.schematicColumn = schematicColumn;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getKilledVarbit()
	{
		return killedVarbit;
	}

	public int getSchematicRow()
	{
		return schematicRow;
	}

	public int getSchematicColumn()
	{
		return schematicColumn;
	}

	/** The brother whose "killed" varbit this is, or null. */
	public static BarrowsBrother forKilledVarbit(int varbitId)
	{
		for (BarrowsBrother brother : values())
		{
			if (brother.killedVarbit == varbitId)
			{
				return brother;
			}
		}
		return null;
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;
import java.util.function.IntUnaryOperator;

/**
 * Immutable snapshot of the CURRENT Barrows run's brothers, read straight
 * from the game's per-brother varbits (see {@link BarrowsBrother}). It is
 * the game's truth at the moment it was read: attaching mid-run shows the
 * brothers already defeated, and a new run shows 0 / 6 once the game resets
 * the varbits. Runtime-only presentation state: it never creates, resumes
 * or switches a session, and it is not persisted (a restart simply re-reads
 * the varbits).
 */
public final class BarrowsRunProgress
{
	private static final BarrowsRunProgress NONE_CLEARED = new BarrowsRunProgress(EnumSet.noneOf(BarrowsBrother.class));

	private final Set<BarrowsBrother> cleared;

	private BarrowsRunProgress(EnumSet<BarrowsBrother> cleared)
	{
		this.cleared = Collections.unmodifiableSet(cleared);
	}

	/** Reads all six varbits through {@code varbitValue} (varbit id -&gt; value). */
	public static BarrowsRunProgress read(IntUnaryOperator varbitValue)
	{
		EnumSet<BarrowsBrother> cleared = EnumSet.noneOf(BarrowsBrother.class);
		for (BarrowsBrother brother : BarrowsBrother.values())
		{
			if (varbitValue.applyAsInt(brother.getKilledVarbit()) > 0)
			{
				cleared.add(brother);
			}
		}
		return cleared.isEmpty() ? NONE_CLEARED : new BarrowsRunProgress(cleared);
	}

	public boolean isCleared(BarrowsBrother brother)
	{
		return cleared.contains(brother);
	}

	public int getClearedCount()
	{
		return cleared.size();
	}

	public static int total()
	{
		return BarrowsBrother.values().length;
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof BarrowsRunProgress && ((BarrowsRunProgress) o).cleared.equals(cleared);
	}

	@Override
	public int hashCode()
	{
		return cleared.hashCode();
	}

	@Override
	public String toString()
	{
		return "Brothers " + getClearedCount() + " / " + total() + " " + cleared;
	}
}

package com.osrstelemetry.plugin.activity;

import com.osrstelemetry.plugin.GotrStrategy;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Guardians of the Rift altar advice over EVERY altar the player can enter
 * right now (pure): the open rifts plus the altars of held portal talismans
 * ({@link GotrGameState#getCandidates()}). A talisman only widens the set of
 * candidates -- it is never recommended for being a talisman.
 *
 * CONFIDENCE RULE: the open rifts must be known and every candidate's
 * eligibility (level + quest, from the game) known; a candidate the player
 * cannot use is never recommended; and a winner is named only when the
 * game's mechanics make the difference meaningful. Otherwise the outcome
 * says so -- FOCUS a side, EITHER, CAPPED, NONE or INSUFFICIENT_EVIDENCE.
 *
 * POINTS (OSRS Wiki, Guardians of the Rift + Strategies): a search costs one
 * elemental AND one catalytic point. Every guardian stone gives 2 energy of
 * its type whatever the altar, so normally only the SIDE matters; the altar
 * matters only through the barrier cell it charges (cells feed BOTH types).
 * Hence the wiki's even-points order, applied as-is: Blood / Death, then
 * Fire / Earth (a SPECIFIC altar, when exactly one candidate holds the best
 * cell rank -- else FOCUS its side); otherwise FOCUS the side with fewer
 * points (known wallet + this game's energy / 100; this game alone when the
 * wallet is unknown). A type at the 1,000-energy cap is never advised; at
 * the 1,200 total cap nothing is.
 *
 * XP: guardian essence gives each rune's standard Runecraft XP, so the
 * candidate with the most XP per essence wins when at least
 * {@link #MIN_XP_ADVANTAGE} ahead of every other usable one; near-ties of
 * one type FOCUS that type, near-ties across types are EITHER.
 */
public final class GotrAdvice
{
	public enum Outcome
	{
		RECOMMEND_ELEMENTAL,
		RECOMMEND_CATALYTIC,
		/** Craft on this side; which altar of it does not matter. */
		FOCUS_ELEMENTAL,
		FOCUS_CATALYTIC,
		/** Every usable candidate is equally good for the chosen strategy. */
		EITHER,
		/** This game's energy is capped: crafting more earns no points. */
		CAPPED,
		/** Nothing the player can use is advisable. */
		NONE,
		/** Spyglass does not know enough to judge. */
		INSUFFICIENT_EVIDENCE
	}

	/** How a candidate cell is marked. */
	public enum Mark
	{
		BEST("\u2605 BEST"),
		FOCUS("\u2605 FOCUS"),
		NONE(null);

		private final String label;

		Mark(String label)
		{
			this.label = label;
		}

		/** Player-facing label; null for NONE. */
		public String getLabel()
		{
			return label;
		}
	}

	public static final int ENERGY_CAP_PER_TYPE = 1_000;
	public static final int ENERGY_CAP_TOTAL = 1_200;
	/** Points closer than this (half a point) count as even. */
	static final double EVEN_POINTS = 0.5;
	/** XP per essence closer than this counts as equal. */
	static final double MIN_XP_ADVANTAGE = 1.0;

	private static final GotrAdvice UNKNOWN = new GotrAdvice(Outcome.INSUFFICIENT_EVIDENCE, null, null, null, null);

	private final Outcome outcome;
	private final GotrAltar altar;
	private final GotrAltar.Type focus;
	private final String reason;
	private final String detail;

	private GotrAdvice(Outcome outcome, GotrAltar altar, GotrAltar.Type focus, String reason, String detail)
	{
		this.outcome = outcome;
		this.altar = altar;
		this.focus = focus;
		this.reason = reason;
		this.detail = detail;
	}

	public Outcome getOutcome()
	{
		return outcome;
	}

	/** The recommended altar; null unless RECOMMEND_*. */
	public GotrAltar getAltar()
	{
		return altar;
	}

	/** The side to focus; null unless FOCUS_*. */
	public GotrAltar.Type getFocus()
	{
		return focus;
	}

	/** One concise, cell-sized reason; null for NONE / INSUFFICIENT_EVIDENCE. */
	public String getReason()
	{
		return reason;
	}

	/** A fuller sentence for tooltips; null when there is nothing to say. */
	public String getDetail()
	{
		return detail;
	}

	public boolean isRecommendation()
	{
		return outcome == Outcome.RECOMMEND_ELEMENTAL || outcome == Outcome.RECOMMEND_CATALYTIC;
	}

	public boolean isFocus()
	{
		return outcome == Outcome.FOCUS_ELEMENTAL || outcome == Outcome.FOCUS_CATALYTIC;
	}

	/** The mark a candidate cell carries: BEST for the recommended altar, FOCUS for usable altars of the focused side. */
	public Mark markOf(GotrCandidate candidate)
	{
		if (candidate == null || !Boolean.TRUE.equals(candidate.getUsable()))
		{
			return Mark.NONE;
		}
		if (isRecommendation())
		{
			return candidate.getAltar() == altar ? Mark.BEST : Mark.NONE;
		}
		if (isFocus())
		{
			return candidate.getAltar().getType() == focus ? Mark.FOCUS : Mark.NONE;
		}
		return Mark.NONE;
	}

	public static GotrAdvice of(GotrStrategy strategy, GotrGameState game, GotrRewardWallet wallet)
	{
		if (game == null || game.getActiveElemental() == null || game.getActiveCatalytic() == null)
		{
			return UNKNOWN;
		}
		List<GotrCandidate> candidates = game.getCandidates();
		for (GotrCandidate c : candidates)
		{
			if (c.getUsable() == null)
			{
				return UNKNOWN;
			}
		}
		return strategy == GotrStrategy.XP ? xp(candidates) : points(game, candidates, wallet);
	}

	private static GotrAdvice points(GotrGameState game, List<GotrCandidate> candidates, GotrRewardWallet wallet)
	{
		Integer e = game.getElementalEnergy();
		Integer c = game.getCatalyticEnergy();
		if (e == null || c == null)
		{
			return UNKNOWN;
		}
		if (e + c >= ENERGY_CAP_TOTAL)
		{
			return new GotrAdvice(Outcome.CAPPED, null, null, "Energy capped",
				"This game's energy is capped (" + ENERGY_CAP_TOTAL + " total): more crafting earns no more points");
		}
		boolean elementalOpen = e < ENERGY_CAP_PER_TYPE;
		boolean catalyticOpen = c < ENERGY_CAP_PER_TYPE;
		List<GotrAltar> usable = new ArrayList<>();
		for (GotrCandidate k : candidates)
		{
			GotrAltar a = k.getAltar();
			if (k.getUsable() && (a.getType() == GotrAltar.Type.ELEMENTAL ? elementalOpen : catalyticOpen))
			{
				usable.add(a);
			}
		}
		if (usable.isEmpty())
		{
			return new GotrAdvice(Outcome.NONE, null, null, null, null);
		}

		// 1) The wiki's priority altars: best cells, which feed BOTH types.
		int bestRank = 0;
		for (GotrAltar a : usable)
		{
			bestRank = Math.max(bestRank, cellPriority(a));
		}
		if (bestRank > 0)
		{
			List<GotrAltar> top = new ArrayList<>();
			for (GotrAltar a : usable)
			{
				if (cellPriority(a) == bestRank)
				{
					top.add(a);
				}
			}
			String detail = "Its barrier cells give energy to both types (wiki order: Blood/Death, then Fire/Earth)";
			if (top.size() == 1)
			{
				return recommend(top.get(0), "Best cells", detail);
			}
			// Several share the best rank -- always one side (Blood/Death, Fire/Earth).
			return focus(top.get(0).getType(), "Best cells", detail);
		}

		// 2) Otherwise the side you have fewer points for -- any altar of it.
		double ePoints = (wallet == null ? 0 : wallet.getElemental()) + e / 100.0;
		double cPoints = (wallet == null ? 0 : wallet.getCatalytic()) + c / 100.0;
		double gap = Math.abs(ePoints - cPoints);
		if (gap < EVEN_POINTS)
		{
			return new GotrAdvice(Outcome.EITHER, null, null, "Points even",
				"Elemental and catalytic points are even: either side keeps them balanced");
		}
		GotrAltar.Type behind = ePoints < cPoints ? GotrAltar.Type.ELEMENTAL : GotrAltar.Type.CATALYTIC;
		boolean any = false;
		for (GotrAltar a : usable)
		{
			any |= a.getType() == behind;
		}
		if (!any)
		{
			return new GotrAdvice(Outcome.NONE, null, null, null, null);
		}
		int points = Math.max(1, (int) Math.round(gap));
		String label = behind.getLabel().toLowerCase(Locale.ROOT);
		return wallet == null
			? focus(behind, "Behind this game", label + " is behind this game (reward balance unknown)")
			: focus(behind, points + " behind", label + " is " + points + " point" + (points == 1 ? "" : "s")
				+ " behind: a search needs one of each");
	}

	/** 2 = Blood / Death, 1 = Fire / Earth (the wiki's order), 0 = no priority. */
	static int cellPriority(GotrAltar altar)
	{
		switch (altar)
		{
			case BLOOD:
			case DEATH:
				return 2;
			case FIRE:
			case EARTH:
				return 1;
			default:
				return 0;
		}
	}

	private static GotrAdvice xp(List<GotrCandidate> candidates)
	{
		List<GotrAltar> usable = new ArrayList<>();
		for (GotrCandidate k : candidates)
		{
			if (k.getUsable())
			{
				usable.add(k.getAltar());
			}
		}
		if (usable.isEmpty())
		{
			return new GotrAdvice(Outcome.NONE, null, null, null, null);
		}
		if (usable.size() == 1)
		{
			return recommend(usable.get(0), "Only usable", "The only altar you can enter right now");
		}
		GotrAltar best = usable.get(0);
		for (GotrAltar a : usable)
		{
			if (a.getXpPerEssence() > best.getXpPerEssence())
			{
				best = a;
			}
		}
		double nextBest = 0;
		boolean nearTieAcrossTypes = false;
		for (GotrAltar a : usable)
		{
			if (a == best)
			{
				continue;
			}
			nextBest = Math.max(nextBest, a.getXpPerEssence());
			if (best.getXpPerEssence() - a.getXpPerEssence() < MIN_XP_ADVANTAGE && a.getType() != best.getType())
			{
				nearTieAcrossTypes = true;
			}
		}
		double lead = best.getXpPerEssence() - nextBest;
		if (lead >= MIN_XP_ADVANTAGE)
		{
			return recommend(best, "+" + perEssence(lead),
				xpText(best.getXpPerEssence()) + " XP per essence, " + xpText(lead) + " more than any other altar you can enter");
		}
		if (nearTieAcrossTypes)
		{
			return new GotrAdvice(Outcome.EITHER, null, null, "Similar XP", "The best altars give similar XP per essence");
		}
		return focus(best.getType(), "Similar XP", "The best " + best.getType().getLabel().toLowerCase(Locale.ROOT)
			+ " altars give similar XP per essence");
	}

	/**
	 * Compact XP-per-essence for the strategy grid: one decimal and a spaced
	 * slash ("5.5 / ess", "+1.5 / ess"). XP mode already says it is XP, and
	 * the old "XP/ess" read as "XP less" in the RuneScape font.
	 */
	public static String perEssence(double xp)
	{
		return String.format(Locale.ROOT, "%.1f / ess", xp);
	}

	public static String xpText(double xp)
	{
		return String.format(Locale.ROOT, "%.1f", xp).replace(".0", "");
	}

	private static GotrAdvice recommend(GotrAltar altar, String reason, String detail)
	{
		return new GotrAdvice(altar.getType() == GotrAltar.Type.ELEMENTAL ? Outcome.RECOMMEND_ELEMENTAL : Outcome.RECOMMEND_CATALYTIC,
			altar, null, reason, detail);
	}

	private static GotrAdvice focus(GotrAltar.Type type, String reason, String detail)
	{
		return new GotrAdvice(type == GotrAltar.Type.ELEMENTAL ? Outcome.FOCUS_ELEMENTAL : Outcome.FOCUS_CATALYTIC,
			null, type, reason, detail);
	}
}

package com.osrstelemetry.plugin.activity;

import net.runelite.api.Quest;

/**
 * The twelve Guardians of the Rift rune altars, in the game's own guardian
 * order -- the order of the GotR HUD script's (5980) "active guardian"
 * arguments: elemental 1..4, catalytic 1..8.
 *
 * INDEX MAPPING (verified live, 2026-10-01): the player stepped through the
 * active rift into the Earth altar while the elemental index was 3, the Fire
 * altar at 4, and the Cosmic / Nature / Death altars while the catalytic index
 * was 3 / 5 / 7 -- exactly the game's guardian order below, which fixes the
 * remaining positions (Air 1, Water 2; Mind 1, Body 2, Chaos 4, Law 6, Blood 8).
 *
 * MECHANICS (OSRS Wiki, Guardians of the Rift / Guardian essence):
 * <ul>
 * <li>level / quest: the altar's Runecraft and quest requirement;</li>
 * <li>xpPerEssence: the rune's standard Runecraft experience per essence
 * (guardian essence is not flat -- it matches the rune);</li>
 * <li>cell tier: the barrier cell the altar's stones charge -- higher-tier
 * cells give more energy to BOTH types, which is why the wiki's even-points
 * strategy prioritises Blood/Death, then Fire/Earth.</li>
 * </ul>
 * Every guardian stone gives the same 2 energy of its type regardless of the
 * altar, so for points the altar matters only through its cell tier.
 */
public enum GotrAltar
{
	AIR(Type.ELEMENTAL, 1, "Air", 1, 5.0, CellTier.WEAK, null),
	WATER(Type.ELEMENTAL, 2, "Water", 5, 6.0, CellTier.MEDIUM, null),
	EARTH(Type.ELEMENTAL, 3, "Earth", 9, 6.5, CellTier.STRONG, null),
	FIRE(Type.ELEMENTAL, 4, "Fire", 14, 7.0, CellTier.OVERCHARGED, null),
	MIND(Type.CATALYTIC, 1, "Mind", 2, 5.5, CellTier.WEAK, null),
	BODY(Type.CATALYTIC, 2, "Body", 20, 7.5, CellTier.WEAK, null),
	COSMIC(Type.CATALYTIC, 3, "Cosmic", 27, 8.0, CellTier.MEDIUM, Quest.LOST_CITY),
	CHAOS(Type.CATALYTIC, 4, "Chaos", 35, 8.5, CellTier.MEDIUM, null),
	NATURE(Type.CATALYTIC, 5, "Nature", 44, 9.0, CellTier.STRONG, null),
	LAW(Type.CATALYTIC, 6, "Law", 54, 9.5, CellTier.STRONG, Quest.TROLL_STRONGHOLD),
	DEATH(Type.CATALYTIC, 7, "Death", 65, 10.0, CellTier.OVERCHARGED, Quest.MOURNINGS_END_PART_II),
	BLOOD(Type.CATALYTIC, 8, "Blood", 77, 10.5, CellTier.OVERCHARGED, Quest.SINS_OF_THE_FATHER);

	public enum Type
	{
		ELEMENTAL("Elemental"),
		CATALYTIC("Catalytic");

		private final String label;

		Type(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	public enum CellTier
	{
		WEAK,
		MEDIUM,
		STRONG,
		OVERCHARGED
	}

	private final Type type;
	private final int guardianIndex;
	private final String displayName;
	private final int runecraftLevel;
	private final double xpPerEssence;
	private final CellTier cellTier;
	private final Quest quest;

	GotrAltar(Type type, int guardianIndex, String displayName, int runecraftLevel, double xpPerEssence, CellTier cellTier, Quest quest)
	{
		this.type = type;
		this.guardianIndex = guardianIndex;
		this.displayName = displayName;
		this.runecraftLevel = runecraftLevel;
		this.xpPerEssence = xpPerEssence;
		this.cellTier = cellTier;
		this.quest = quest;
	}

	/** The altar for a HUD-script guardian index, or null when out of range (no game / no active guardian). */
	public static GotrAltar of(Type type, Integer guardianIndex)
	{
		if (type == null || guardianIndex == null)
		{
			return null;
		}
		for (GotrAltar a : values())
		{
			if (a.type == type && a.guardianIndex == guardianIndex)
			{
				return a;
			}
		}
		return null;
	}

	public Type getType()
	{
		return type;
	}

	public int getGuardianIndex()
	{
		return guardianIndex;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getRunecraftLevel()
	{
		return runecraftLevel;
	}

	public double getXpPerEssence()
	{
		return xpPerEssence;
	}

	public CellTier getCellTier()
	{
		return cellTier;
	}

	/** The quest the altar requires, or null. */
	public Quest getQuest()
	{
		return quest;
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Objects;

/**
 * One altar the player could enter right now in a Guardians of the Rift
 * game, and how: through its OPEN rift, or with a held portal TALISMAN of
 * that altar (OSRS Wiki: the talisman enters the guardian even while it is
 * inactive, and is consumed doing so unless the guardian is active).
 * {@code usable}: Runecraft level + quest, read from the game; null = unknown.
 */
public final class GotrCandidate
{
	public enum Access
	{
		OPEN("Open"),
		TALISMAN("Talisman");

		private final String label;

		Access(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	private final GotrAltar altar;
	private final Access access;
	private final Boolean usable;

	public GotrCandidate(GotrAltar altar, Access access, Boolean usable)
	{
		this.altar = Objects.requireNonNull(altar);
		this.access = Objects.requireNonNull(access);
		this.usable = usable;
	}

	public GotrAltar getAltar()
	{
		return altar;
	}

	public Access getAccess()
	{
		return access;
	}

	public Boolean getUsable()
	{
		return usable;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof GotrCandidate))
		{
			return false;
		}
		GotrCandidate that = (GotrCandidate) o;
		return altar == that.altar && access == that.access && Objects.equals(usable, that.usable);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(altar, access, usable);
	}

	@Override
	public String toString()
	{
		return altar + "/" + access + (usable == null ? "?" : usable ? "" : "(locked)");
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * The current Guardians of the Rift game as the game's own HUD reports it.
 * Presentation only -- never an event, never lifecycle evidence. Every field
 * is nullable and a null field is simply omitted (never guessed).
 *
 * SOURCES (RuneLite 1.13.1, all native -- no other plugin):
 * <ul>
 * <li>guardianPowerPercent: the GotR HUD's own update clientscript (5980),
 * whose arguments carry the Great Guardian's current and maximum power;
 * read via runelite-api's ScriptPreFired. Rounded down, clamped 0-100.</li>
 * <li>elementalEnergy / catalyticEnergy: varbits
 * GOTR_ELEMENTAL_EARNED_THIS_GAME (13686) / GOTR_CATALYTIC_EARNED_THIS_GAME
 * (13685) -- this player's energy earned in the current game.</li>
 * <li>activeElemental / activeCatalytic: the two guardians whose rifts are
 * open right now -- the same HUD script's guardian-index arguments (see
 * {@link GotrAltar} for the live-verified mapping). Null outside a game.</li>
 * <li>elementalUsable / catalyticUsable: whether this player can enter that
 * altar (Runecraft level and quest, read from the game); null = unknown.</li>
 * </ul>
 */
public final class GotrGameState
{
	private final Integer guardianPowerPercent;
	private final Integer elementalEnergy;
	private final Integer catalyticEnergy;
	private final GotrAltar activeElemental;
	private final GotrAltar activeCatalytic;
	private final Boolean elementalUsable;
	private final Boolean catalyticUsable;
	/** Held portal talismans (altar -> usable, null = unknown), in guardian order. */
	private final Map<GotrAltar, Boolean> talismans;

	private GotrGameState(Integer guardianPowerPercent, Integer elementalEnergy, Integer catalyticEnergy,
		GotrAltar activeElemental, GotrAltar activeCatalytic, Boolean elementalUsable, Boolean catalyticUsable,
		Map<GotrAltar, Boolean> talismans)
	{
		this.talismans = talismans;
		this.guardianPowerPercent = guardianPowerPercent;
		this.elementalEnergy = elementalEnergy;
		this.catalyticEnergy = catalyticEnergy;
		this.activeElemental = activeElemental;
		this.activeCatalytic = activeCatalytic;
		this.elementalUsable = activeElemental == null ? null : elementalUsable;
		this.catalyticUsable = activeCatalytic == null ? null : catalyticUsable;
	}

	/** Null when nothing at all is known. Negative energy values are treated as unknown. */
	public static GotrGameState of(Integer guardianPowerPercent, Integer elementalEnergy, Integer catalyticEnergy)
	{
		return of(guardianPowerPercent, elementalEnergy, catalyticEnergy, null, null, null, null);
	}

	/** As {@link #of(Integer, Integer, Integer)}, plus the active rifts and whether the player can use them. */
	public static GotrGameState of(Integer guardianPowerPercent, Integer elementalEnergy, Integer catalyticEnergy,
		GotrAltar activeElemental, GotrAltar activeCatalytic, Boolean elementalUsable, Boolean catalyticUsable)
	{
		Integer e = elementalEnergy == null || elementalEnergy < 0 ? null : elementalEnergy;
		Integer c = catalyticEnergy == null || catalyticEnergy < 0 ? null : catalyticEnergy;
		GotrAltar ae = activeElemental == null || activeElemental.getType() != GotrAltar.Type.ELEMENTAL ? null : activeElemental;
		GotrAltar ac = activeCatalytic == null || activeCatalytic.getType() != GotrAltar.Type.CATALYTIC ? null : activeCatalytic;
		if (guardianPowerPercent == null && e == null && c == null && ae == null && ac == null)
		{
			return null;
		}
		return new GotrGameState(guardianPowerPercent, e, c, ae, ac, elementalUsable, catalyticUsable, Collections.emptyMap());
	}

	/** As the 7-argument form, plus the portal talismans held (altar -> usable, null = unknown). */
	public static GotrGameState of(Integer guardianPowerPercent, Integer elementalEnergy, Integer catalyticEnergy,
		GotrAltar activeElemental, GotrAltar activeCatalytic, Boolean elementalUsable, Boolean catalyticUsable,
		Map<GotrAltar, Boolean> talismans)
	{
		GotrGameState base = of(guardianPowerPercent, elementalEnergy, catalyticEnergy, activeElemental, activeCatalytic,
			elementalUsable, catalyticUsable);
		if (base == null || talismans == null || talismans.isEmpty())
		{
			return base;
		}
		Map<GotrAltar, Boolean> held = new EnumMap<>(GotrAltar.class);
		for (Map.Entry<GotrAltar, Boolean> t : talismans.entrySet())
		{
			if (t.getKey() != null)
			{
				held.put(t.getKey(), t.getValue());
			}
		}
		return new GotrGameState(base.guardianPowerPercent, base.elementalEnergy, base.catalyticEnergy, base.activeElemental,
			base.activeCatalytic, base.elementalUsable, base.catalyticUsable, Collections.unmodifiableMap(held));
	}

	/**
	 * Every altar the player can enter right now: the open rifts first
	 * (elemental, catalytic), then each held portal talisman's altar that is
	 * not already open, in guardian order. Empty when nothing is known.
	 */
	public List<GotrCandidate> getCandidates()
	{
		List<GotrCandidate> out = new ArrayList<>();
		if (activeElemental != null)
		{
			out.add(new GotrCandidate(activeElemental, GotrCandidate.Access.OPEN, elementalUsable));
		}
		if (activeCatalytic != null)
		{
			out.add(new GotrCandidate(activeCatalytic, GotrCandidate.Access.OPEN, catalyticUsable));
		}
		for (Map.Entry<GotrAltar, Boolean> t : talismans.entrySet())
		{
			if (t.getKey() != activeElemental && t.getKey() != activeCatalytic)
			{
				out.add(new GotrCandidate(t.getKey(), GotrCandidate.Access.TALISMAN, t.getValue()));
			}
		}
		return out;
	}

	/** Altars of the portal talismans held (any order-stable view); empty when none. */
	public Map<GotrAltar, Boolean> getTalismans()
	{
		return talismans;
	}

	/** floor(current * 100 / max), clamped to 0..100; null when max is unknown or not positive. */
	public static Integer powerPercent(Integer current, Integer max)
	{
		if (current == null || max == null || max <= 0)
		{
			return null;
		}
		long pct = (long) Math.max(0, current) * 100L / max;
		return (int) Math.min(100L, pct);
	}

	public Integer getGuardianPowerPercent()
	{
		return guardianPowerPercent;
	}

	public Integer getElementalEnergy()
	{
		return elementalEnergy;
	}

	public Integer getCatalyticEnergy()
	{
		return catalyticEnergy;
	}

	/** The open elemental rift's altar, or null. */
	public GotrAltar getActiveElemental()
	{
		return activeElemental;
	}

	/** The open catalytic rift's altar, or null. */
	public GotrAltar getActiveCatalytic()
	{
		return activeCatalytic;
	}

	/** Whether the player can enter the open elemental altar; null when unknown. */
	public Boolean getElementalUsable()
	{
		return elementalUsable;
	}

	/** Whether the player can enter the open catalytic altar; null when unknown. */
	public Boolean getCatalyticUsable()
	{
		return catalyticUsable;
	}

	/** Elemental + catalytic energy (the game's own "total energy" notion), only when both are known. */
	public Integer getTotalEnergy()
	{
		return elementalEnergy == null || catalyticEnergy == null ? null : elementalEnergy + catalyticEnergy;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof GotrGameState))
		{
			return false;
		}
		GotrGameState that = (GotrGameState) o;
		return Objects.equals(guardianPowerPercent, that.guardianPowerPercent)
			&& Objects.equals(elementalEnergy, that.elementalEnergy)
			&& Objects.equals(catalyticEnergy, that.catalyticEnergy)
			&& activeElemental == that.activeElemental
			&& activeCatalytic == that.activeCatalytic
			&& Objects.equals(elementalUsable, that.elementalUsable)
			&& Objects.equals(catalyticUsable, that.catalyticUsable)
			&& talismans.equals(that.talismans);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(guardianPowerPercent, elementalEnergy, catalyticEnergy, activeElemental, activeCatalytic, elementalUsable, catalyticUsable, talismans);
	}

	@Override
	public String toString()
	{
		return "GotrGameState{power=" + guardianPowerPercent + "%, elemental=" + elementalEnergy + ", catalytic=" + catalyticEnergy
			+ ", rifts=" + activeElemental + "/" + activeCatalytic + ", talismans=" + talismans.keySet() + "}";
	}
}

package com.osrstelemetry.plugin.activity;

/**
 * Guardians of the Rift final-energy bookkeeping (pure; client thread only).
 *
 * SCORE = this player's total energy (elemental + catalytic, varbits 13686 /
 * 13685) in a WON game -- the game's own contribution measure (it gates the
 * end-of-game XP and converts to reward points). Captured when "Amount of
 * Rifts you have closed: N" arrives, which the game prints only for a closed
 * (won) rift: final = the larger of the last value observed during the game
 * and the value at the message, so it survives the varbits resetting first.
 *
 * PROVENANCE (same rule as Tempoross): a game is FULLY OBSERVED only if its
 * energy was seen at 0 after the previous game ended -- i.e. Spyglass watched
 * it from before anything was earned. A game first seen with energy already
 * above 0 (login / re-enable mid-game) is PARTIAL: it still counts as a game
 * (the completion count is authoritative) but never enters Avg/Best.
 *
 * FAILURE: "The Great Guardian was defeated" ends the game with no rifts
 * closed message, so no score is ever produced; the game's tracking is
 * dropped so nothing it earned can leak into the next one.
 *
 * WIN (live-verified 2026-10-01, in this order on one tick): "The Great
 * Guardian successfully closed the rift!", "Amount of rifts you have closed:
 * N.", "Elemental energy attuned: E. Catalytic energy attuned: C.", "Total
 * elemental energy: E. Total catalytic energy: C.". The count line is the
 * primary, deduplicated success evidence; the "successfully closed" line
 * corroborates it and stands in for it if it is ever missing.
 */
public final class GotrGameTracker
{
	static final String FAILED_MESSAGE = "The Great Guardian was defeated";
	static final String WON_MESSAGE = "The Great Guardian successfully closed the rift";
	/**
	 * Live-verified 2026-10-01: a closed rift the player did not contribute
	 * enough to is followed by this line and NO "Amount of rifts" count --
	 * the game does not credit it, so neither does Spyglass.
	 */
	static final String NO_CONTRIBUTION_MESSAGE = "You did not contribute enough to attune";

	/** Energy was observed at 0 since the last game ended (the current game is watched from its start). */
	private boolean zeroSeen;
	/** Highest total energy observed since that zero. */
	private int gameMax;
	/** Last observed total (detects a drop = the varbits reset for a new game). */
	private Integer lastTotal;

	public void reset()
	{
		zeroSeen = false;
		gameMax = 0;
		lastTotal = null;
	}

	/** One tick of the game's own energy varbits while the GotR HUD is loaded; otherwise call nothing. */
	public void onEnergy(int elemental, int catalytic)
	{
		if (elemental < 0 || catalytic < 0)
		{
			return;
		}
		int total = elemental + catalytic;
		if (total == 0)
		{
			zeroSeen = true;
			gameMax = 0;
		}
		else if (lastTotal != null && total < lastTotal)
		{
			// Dropped without passing 0 on a tick we saw: a new game we did
			// not watch from its start.
			zeroSeen = false;
			gameMax = total;
		}
		else
		{
			gameMax = Math.max(gameMax, total);
		}
		lastTotal = total;
	}

	/** True for the game's own failure message (tags already removed). */
	public static boolean isFailure(String message)
	{
		return message != null && message.contains(FAILED_MESSAGE);
	}

	/** True for the game's own success message (tags removed; any "@mes_..@" prefix ignored). */
	public static boolean isWin(String message)
	{
		return message != null && message.contains(WON_MESSAGE);
	}

	/** True when the rift closed but the game did not credit this player (no count, no points). */
	public static boolean isNoContribution(String message)
	{
		return message != null && message.contains(NO_CONTRIBUTION_MESSAGE);
	}

	/** A lost game: nothing it earned is ever scored, and the next game must prove its own start. */
	public void onFailure()
	{
		zeroSeen = false;
		gameMax = 0;
	}

	/**
	 * A won game ("Amount of Rifts you have closed: N", already deduplicated
	 * by the caller). Returns its final energy and provenance, then ends the
	 * game's tracking.
	 */
	public Result onCompletion(Integer riftsClosed, int elementalNow, int catalyticNow)
	{
		int now = elementalNow < 0 || catalyticNow < 0 ? 0 : elementalNow + catalyticNow;
		int finalEnergy = Math.max(gameMax, now);
		Result r = new Result(riftsClosed, finalEnergy > 0 ? finalEnergy : null, zeroSeen && finalEnergy > 0);
		zeroSeen = false;
		gameMax = 0;
		return r;
	}

	public static final class Result
	{
		private final Integer riftsClosed;
		private final Integer totalEnergy;
		private final boolean observedFromStart;

		Result(Integer riftsClosed, Integer totalEnergy, boolean observedFromStart)
		{
			this.riftsClosed = riftsClosed;
			this.totalEnergy = totalEnergy;
			this.observedFromStart = observedFromStart;
		}

		/** The game's own rifts-closed count, or null when only the "successfully closed" line was seen. */
		public Integer getRiftsClosed()
		{
			return riftsClosed;
		}

		/** Final total energy, or null when unknown / 0. */
		public Integer getTotalEnergy()
		{
			return totalEnergy;
		}

		public boolean isObservedFromStart()
		{
			return observedFromStart;
		}
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/**
 * Guardians of the Rift portal talismans, by native item id (resolved
 * RuneLite 1.13.1 gameval ItemID.GOTR_PORTAL_TALISMAN_*), one per altar.
 *
 * MECHANICS (OSRS Wiki, portal talisman pages; live log 2026-10-01): found
 * while crafting at an altar ("You discover a strange talisman during the
 * runecrafting process!"); stackable; used on that altar's guardian to enter
 * it even while its rift is closed ("The portal talisman shatters and you
 * find yourself at the altar it originated from") -- consumed unless the
 * guardian is active; cannot be kept after the game ends. Spyglass reads
 * which are HELD from the inventory container it already observes.
 */
public final class GotrPortalTalismans
{
	private GotrPortalTalismans()
	{
	}

	private static final Map<Integer, GotrAltar> BY_ITEM;

	static
	{
		Map<Integer, GotrAltar> m = new HashMap<>();
		m.put(ItemID.GOTR_PORTAL_TALISMAN_AIR, GotrAltar.AIR);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_WATER, GotrAltar.WATER);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_EARTH, GotrAltar.EARTH);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_FIRE, GotrAltar.FIRE);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_MIND, GotrAltar.MIND);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_BODY, GotrAltar.BODY);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_COSMIC, GotrAltar.COSMIC);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_CHAOS, GotrAltar.CHAOS);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_NATURE, GotrAltar.NATURE);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_LAW, GotrAltar.LAW);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_DEATH, GotrAltar.DEATH);
		m.put(ItemID.GOTR_PORTAL_TALISMAN_BLOOD, GotrAltar.BLOOD);
		BY_ITEM = Collections.unmodifiableMap(m);
	}

	/** The altar a portal talisman item leads to, or null for any other item. */
	public static GotrAltar altarOf(int itemId)
	{
		return BY_ITEM.get(itemId);
	}

	/** Altars with at least one portal talisman in these items (item id -> quantity). */
	public static Set<GotrAltar> heldIn(Map<Integer, Long> items)
	{
		Set<GotrAltar> held = EnumSet.noneOf(GotrAltar.class);
		if (items != null)
		{
			for (Map.Entry<Integer, Long> e : items.entrySet())
			{
				GotrAltar altar = e.getKey() == null ? null : BY_ITEM.get(e.getKey());
				if (altar != null && e.getValue() != null && e.getValue() > 0)
				{
					held.add(altar);
				}
			}
		}
		return held;
	}

	static int count()
	{
		return BY_ITEM.size();
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Guardians of the Rift reward points EARNED this session (pure; client
 * thread only).
 *
 * The game keeps two separate reward-point balances -- elemental and
 * catalytic -- that it never exposes as a varbit. They are only visible as:
 * <ul>
 * <li>the end-of-game game message "Total elemental energy: E. Total
 * catalytic energy: C." -- both balances AFTER that game's award;</li>
 * <li>the Rewards Guardian's "Check" answer "You have C catalytic energy and
 * E elemental energy..." -- both balances now;</li>
 * <li>each Rewards Guardian search ("You found some loot: ..."), which costs
 * one point of each.</li>
 * </ul>
 * (Message texts corroborated across independent Plugin Hub plugins; used
 * here as evidence of the game's text only -- Spyglass depends on none.)
 *
 * POINTS EARNED PER GAME (live-verified 2026-10-01): the game states them
 * itself, right before the totals: "Elemental energy attuned: E. Catalytic
 * energy attuned: C." (2 / 3 in the verified game, whose energy was 207 /
 * 283 -- energy/100 with the remainder rounded by chance). When that line
 * was seen, it IS the game's award -- no baseline needed, so the first game
 * of a session is counted exactly. Only without it does earned fall back to
 * positive changes of the observed balance, like Tempoross permits:
 * <ul>
 * <li>An unknown balance is only BASELINED by the first observation (login,
 * re-enable, account switch): a pre-session balance is never counted, and
 * the first game of a session whose balance was never seen before it is
 * undercounted, never overcounted.</li>
 * <li>A search moves the baseline down by one each (spending never reduces
 * "earned").</li>
 * <li>Each currency is tracked independently.</li>
 * </ul>
 */
public final class GotrRewardPointTracker
{
	static final Pattern TOTALS = Pattern.compile(
		"Total elemental energy:\\s*([\\d,]+)\\.?\\s*Total catalytic energy:\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE);
	static final Pattern ATTUNED = Pattern.compile(
		"Elemental energy attuned:\\s*([\\d,]+)\\.?\\s*Catalytic energy attuned:\\s*([\\d,]+)", Pattern.CASE_INSENSITIVE);
	static final Pattern CHECK = Pattern.compile(
		"You have ([\\d,]+) catalytic energy and ([\\d,]+) elemental energy", Pattern.CASE_INSENSITIVE);

	private Integer elemental;
	private Integer catalytic;
	/** This game's award from the "attuned" line, waiting for the totals line that follows it. */
	private Integer attunedElemental;
	private Integer attunedCatalytic;

	public void reset()
	{
		elemental = null;
		catalytic = null;
		attunedElemental = null;
		attunedCatalytic = null;
	}

	/** The reward wallet when both balances are known, else null. */
	public GotrRewardWallet wallet()
	{
		return GotrRewardWallet.of(elemental, catalytic);
	}

	/** End-of-game totals message (tags removed); null when the message is not one. */
	public Gains onGameMessage(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher attuned = ATTUNED.matcher(message);
		if (attuned.find())
		{
			attunedElemental = parse(attuned.group(1));
			attunedCatalytic = parse(attuned.group(2));
			return null;
		}
		Matcher m = TOTALS.matcher(message);
		if (!m.find())
		{
			return null;
		}
		int e = parse(m.group(1));
		int c = parse(m.group(2));
		Gains gains = attunedElemental != null
			? new Gains(attunedElemental, attunedCatalytic, e, c)
			: new Gains(gained(elemental, e), gained(catalytic, c), e, c);
		attunedElemental = null;
		attunedCatalytic = null;
		elemental = e;
		catalytic = c;
		return gains;
	}

	/** Rewards Guardian "Check" text (chat or message box); baseline only. True when it matched. */
	public boolean onCheckText(String text)
	{
		if (text == null)
		{
			return false;
		}
		Matcher m = CHECK.matcher(text.replace("<br>", " "));
		if (!m.find())
		{
			return false;
		}
		catalytic = parse(m.group(1));
		elemental = parse(m.group(2));
		return true;
	}

	/** One Rewards Guardian search: one point of each spent (baseline only). */
	public void onSearch()
	{
		elemental = elemental == null ? null : Math.max(0, elemental - 1);
		catalytic = catalytic == null ? null : Math.max(0, catalytic - 1);
	}

	Integer getElementalBalance()
	{
		return elemental;
	}

	Integer getCatalyticBalance()
	{
		return catalytic;
	}

	private static int gained(Integer known, int now)
	{
		return known == null ? 0 : Math.max(0, now - known);
	}

	private static int parse(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	public static final class Gains
	{
		private final int elementalGained;
		private final int catalyticGained;
		private final int elementalBalance;
		private final int catalyticBalance;

		Gains(int elementalGained, int catalyticGained, int elementalBalance, int catalyticBalance)
		{
			this.elementalGained = elementalGained;
			this.catalyticGained = catalyticGained;
			this.elementalBalance = elementalBalance;
			this.catalyticBalance = catalyticBalance;
		}

		public int getElementalGained()
		{
			return elementalGained;
		}

		public int getCatalyticGained()
		{
			return catalyticGained;
		}

		public int getElementalBalance()
		{
			return elementalBalance;
		}

		public int getCatalyticBalance()
		{
			return catalyticBalance;
		}
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Objects;

/**
 * The player's current Guardians of the Rift REWARD POINT balances (what the
 * Rewards Guardian spends), as last stated by the game itself: the end-of-game
 * "Total elemental energy: E. Total catalytic energy: C." line or the Rewards
 * Guardian "Check" answer, minus one of each per search since. Live only --
 * never persisted, never carried across logout, hop, re-enable or account
 * switch (the player could have spent points elsewhere). Distinct from
 * current-game ENERGY and from points EARNED this session.
 */
public final class GotrRewardWallet
{
	private final int elemental;
	private final int catalytic;

	private GotrRewardWallet(int elemental, int catalytic)
	{
		this.elemental = elemental;
		this.catalytic = catalytic;
	}

	/** Null unless BOTH balances are known. */
	public static GotrRewardWallet of(Integer elemental, Integer catalytic)
	{
		if (elemental == null || catalytic == null || elemental < 0 || catalytic < 0)
		{
			return null;
		}
		return new GotrRewardWallet(elemental, catalytic);
	}

	public int getElemental()
	{
		return elemental;
	}

	public int getCatalytic()
	{
		return catalytic;
	}

	/** Usable Rewards Guardian searches: each costs one point of each type. */
	public int searches()
	{
		return Math.min(elemental, catalytic);
	}

	/** The side limiting searches, or null when balanced. */
	public GotrAltar.Type limitingSide()
	{
		if (elemental == catalytic)
		{
			return null;
		}
		return elemental < catalytic ? GotrAltar.Type.ELEMENTAL : GotrAltar.Type.CATALYTIC;
	}

	/** How many points the limiting side is behind (0 when balanced). */
	public int imbalance()
	{
		return Math.abs(elemental - catalytic);
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof GotrRewardWallet))
		{
			return false;
		}
		GotrRewardWallet w = (GotrRewardWallet) o;
		return w.elemental == elemental && w.catalytic == catalytic;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(elemental, catalytic);
	}

	@Override
	public String toString()
	{
		return "GotrRewardWallet{elemental=" + elemental + ", catalytic=" + catalytic + "}";
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Guardians of the Rift rune production recipe. Input: guardian essence
 * (gameval ItemID.GOTR_GUARDIAN_ESSENCE), which exists only inside the
 * minigame -- consuming it is itself proof of a GotR altar craft. Output:
 * every (unnoted) rune item id, not just the twelve GotR altar runes, so a
 * legitimately crafted rune is never dropped for being unexpected; the
 * essence-consumption + Runecraft-XP gate is what keeps everything else out.
 */
public final class GotrRunes
{
	private GotrRunes()
	{
	}

	public static final Set<Integer> RUNE_ITEM_IDS = Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(
		ItemID.AIRRUNE, ItemID.WATERRUNE, ItemID.EARTHRUNE, ItemID.FIRERUNE,
		ItemID.MINDRUNE, ItemID.BODYRUNE, ItemID.COSMICRUNE, ItemID.CHAOSRUNE,
		ItemID.NATURERUNE, ItemID.LAWRUNE, ItemID.DEATHRUNE, ItemID.BLOODRUNE,
		ItemID.SOULRUNE, ItemID.WRATHRUNE, ItemID.ASTRALRUNE,
		ItemID.MISTRUNE, ItemID.DUSTRUNE, ItemID.MUDRUNE, ItemID.SMOKERUNE, ItemID.STEAMRUNE, ItemID.LAVARUNE,
		ItemID.SUNFIRERUNE, ItemID.AETHERRUNE)));

	public static final ProductionRecipe RECIPE = new ProductionRecipe(
		Collections.singleton(ItemID.GOTR_GUARDIAN_ESSENCE), RUNE_ITEM_IDS, "runecraft");

	/**
	 * Rune pouch / divine rune pouch slots (resolved RuneLite 1.13.1 gameval):
	 * slot i holds rune TYPE_i (an index into the game's RUNEPOUCH_RUNE enum)
	 * x QUANTITY_i. Six slots are defined; unused slots read 0.
	 */
	static final int[] RUNE_POUCH_TYPES = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6};
	static final int[] RUNE_POUCH_QUANTITIES = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6};

	public static boolean isRunePouchVarbit(int varbitId)
	{
		for (int i = 0; i < RUNE_POUCH_TYPES.length; i++)
		{
			if (RUNE_POUCH_TYPES[i] == varbitId || RUNE_POUCH_QUANTITIES[i] == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	/** The pouch's runes (item id -> quantity) from its slot varbits; unknown slot types are skipped. */
	public static Map<Integer, Long> readRunePouch(IntUnaryOperator varbit, IntUnaryOperator typeToItem)
	{
		Map<Integer, Long> out = new HashMap<>();
		for (int i = 0; i < RUNE_POUCH_TYPES.length; i++)
		{
			int type = varbit.applyAsInt(RUNE_POUCH_TYPES[i]);
			int qty = varbit.applyAsInt(RUNE_POUCH_QUANTITIES[i]);
			if (type <= 0 || qty <= 0)
			{
				continue;
			}
			int item = typeToItem.applyAsInt(type);
			if (item > 0)
			{
				out.merge(item, (long) qty, Long::sum);
			}
		}
		return out;
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * What one confirmed PRODUCTION action looks like, for {@link ProductionTracker}:
 * items consumed, items produced, and the skill whose XP must corroborate
 * the action. Produced items are activity OUTPUT -- deliberately a separate
 * concept from loot/rewards (things received), so later production skills
 * (smithing, cooking, ...) can reuse it without being modelled as loot.
 */
public final class ProductionRecipe
{
	private final Set<Integer> consumedItemIds;
	private final Set<Integer> producedItemIds;
	private final String corroboratingSkill;

	public ProductionRecipe(Set<Integer> consumedItemIds, Set<Integer> producedItemIds, String corroboratingSkill)
	{
		this.consumedItemIds = Collections.unmodifiableSet(new LinkedHashSet<>(consumedItemIds));
		this.producedItemIds = Collections.unmodifiableSet(new LinkedHashSet<>(producedItemIds));
		this.corroboratingSkill = corroboratingSkill;
	}

	public Set<Integer> getConsumedItemIds()
	{
		return consumedItemIds;
	}

	public Set<Integer> getProducedItemIds()
	{
		return producedItemIds;
	}

	/** Lower-case skill name (e.g. "runecraft"). */
	public String getCorroboratingSkill()
	{
		return corroboratingSkill;
	}

	boolean isTracked(int itemId)
	{
		return consumedItemIds.contains(itemId) || producedItemIds.contains(itemId);
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;

/**
 * Attributes PRODUCED items to confirmed production actions (pure; client
 * thread only). Never counts an item merely for appearing somewhere.
 *
 * <h3>Destinations</h3>
 * Output can land in more than one place: the inventory, and a secondary
 * store such as the rune pouch (crafted runes of a type the pouch already
 * holds go straight into it). Each destination is observed as a snapshot
 * (item id -> total quantity) and diffed against its own previous snapshot.
 * Moving items BETWEEN destinations is -N in one and +N in the other: it
 * nets to zero and is never production.
 *
 * <h3>Bounded per-tick correlation</h3>
 * Every observed change is booked into a small per-tick bucket: whether a
 * recipe input was consumed on that tick, the NET change of every output
 * across all destinations, and whether the corroborating skill gained XP.
 * Because each bucket is a sum of consecutive snapshot diffs, it is exact
 * whatever order the inventory, pouch and XP updates arrive in within the
 * tick. A bucket's positive net output is production only when:
 * <ol>
 * <li>an input was consumed on that tick or an adjacent one, in the
 * activity's own context (caller decides); and</li>
 * <li>the skill gained XP within {@link #XP_WINDOW_TICKS} of that
 * consumption.</li>
 * </ol>
 * One XP gain may corroborate several crafts on the same / adjacent ticks
 * (rapid craft -> essence-pouch refill -> craft), and a craft is never
 * missed because its XP arrived before, between or after the item updates.
 * Each bucket's output is emitted incrementally and at most once in total:
 * a later update on the same tick only emits what was not emitted yet, so
 * a craft split between inventory and pouch is +all, never twice. Buckets
 * older than the correlation window are dropped (bounded memory).
 *
 * Anything that adds outputs without consuming an input nearby -- reward
 * items, pick-ups, withdrawals, pouch transfers -- is never production, and
 * anything that removes outputs only moves the baseline: produced totals
 * never go down.
 *
 * Login / re-enable / account switch: {@link #reset()} -- the first
 * snapshot of each destination and the first XP value seen afterwards are
 * baseline only.
 */
public final class ProductionTracker
{
	/** XP may arrive on the same tick as the consumption, or one tick either side; outputs likewise. */
	static final int XP_WINDOW_TICKS = 1;
	/** A bucket can still be corroborated until this many ticks have passed (output -> input -> XP). */
	private static final int RETAIN_TICKS = 2 * XP_WINDOW_TICKS;

	private final ProductionRecipe recipe;
	private Map<Integer, Long> lastInventory;
	private Map<Integer, Long> lastPouch;
	private long lastSkillXp = -1;
	private final TreeMap<Integer, Bucket> buckets = new TreeMap<>();

	private static final class Bucket
	{
		boolean consumed;
		boolean xp;
		final Map<Integer, Long> net = new HashMap<>();
		final Map<Integer, Long> emitted = new HashMap<>();
	}

	public ProductionTracker(ProductionRecipe recipe)
	{
		this.recipe = recipe;
	}

	public void reset()
	{
		lastInventory = null;
		lastPouch = null;
		lastSkillXp = -1;
		buckets.clear();
	}

	/**
	 * One inventory snapshot (item id -> total quantity). Returns the produced
	 * items newly confirmed by this observation, else an empty map.
	 */
	public Map<Integer, Long> onInventory(Map<Integer, Long> inventory, int tick, boolean inContext)
	{
		Map<Integer, Long> tracked = trackedOf(inventory, true);
		Map<Integer, Long> previous = lastInventory;
		lastInventory = tracked;
		if (previous == null || !inContext)
		{
			return Collections.emptyMap();
		}
		Bucket b = bucket(tick);
		for (int id : recipe.getConsumedItemIds())
		{
			if (tracked.getOrDefault(id, 0L) < previous.getOrDefault(id, 0L))
			{
				b.consumed = true;
			}
		}
		bookOutputs(b, previous, tracked);
		return settle(tick);
	}

	/**
	 * One snapshot of a secondary output store (the rune pouch). Only outputs
	 * are read from it; its first snapshot after {@link #reset()} is baseline.
	 */
	public Map<Integer, Long> onSecondaryStore(Map<Integer, Long> store, int tick, boolean inContext)
	{
		Map<Integer, Long> tracked = trackedOf(store, false);
		Map<Integer, Long> previous = lastPouch;
		lastPouch = tracked;
		if (previous == null || !inContext || previous.equals(tracked))
		{
			return Collections.emptyMap();
		}
		bookOutputs(bucket(tick), previous, tracked);
		return settle(tick);
	}

	/** The corroborating skill's absolute XP. Returns produced items confirmed by this gain, else empty. */
	public Map<Integer, Long> onSkillXp(long xp, int tick)
	{
		boolean gained = lastSkillXp >= 0 && xp > lastSkillXp;
		lastSkillXp = xp;
		if (!gained)
		{
			return Collections.emptyMap();
		}
		bucket(tick).xp = true;
		return settle(tick);
	}

	/** Once per game tick: buckets past the correlation window expire (anything uncorroborated is never counted). */
	public void onTick(int tick)
	{
		buckets.headMap(tick - RETAIN_TICKS).clear();
	}

	public ProductionRecipe getRecipe()
	{
		return recipe;
	}

	/** Test/diagnostic: how many ticks are currently held for correlation. */
	int heldTicks()
	{
		return buckets.size();
	}

	private Bucket bucket(int tick)
	{
		// Bounded even if onTick is never called: drop anything outside the window.
		buckets.headMap(tick - RETAIN_TICKS).clear();
		return buckets.computeIfAbsent(tick, t -> new Bucket());
	}

	private void bookOutputs(Bucket b, Map<Integer, Long> previous, Map<Integer, Long> now)
	{
		for (int id : recipe.getProducedItemIds())
		{
			long delta = now.getOrDefault(id, 0L) - previous.getOrDefault(id, 0L);
			if (delta != 0)
			{
				b.net.merge(id, delta, Long::sum);
			}
		}
	}

	/** Emits, for every corroborated bucket around {@code tick}, the positive net output not emitted yet. */
	private Map<Integer, Long> settle(int tick)
	{
		Map<Integer, Long> out = null;
		for (Map.Entry<Integer, Bucket> e : buckets.subMap(tick - RETAIN_TICKS, true, tick + RETAIN_TICKS, true).entrySet())
		{
			Bucket b = e.getValue();
			if (b.net.isEmpty() || !corroborated(e.getKey()))
			{
				continue;
			}
			for (Map.Entry<Integer, Long> n : b.net.entrySet())
			{
				long already = b.emitted.getOrDefault(n.getKey(), 0L);
				long add = n.getValue() - already;
				if (add > 0)
				{
					b.emitted.put(n.getKey(), n.getValue());
					if (out == null)
					{
						out = new LinkedHashMap<>();
					}
					out.merge(n.getKey(), add, Long::sum);
				}
			}
		}
		return out == null ? Collections.emptyMap() : out;
	}

	/** An input was consumed within the window of this output tick, and XP was gained within the window of that consumption. */
	private boolean corroborated(int outputTick)
	{
		for (Iterator<Map.Entry<Integer, Bucket>> it = buckets.subMap(outputTick - XP_WINDOW_TICKS, true,
			outputTick + XP_WINDOW_TICKS, true).entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Integer, Bucket> c = it.next();
			if (!c.getValue().consumed)
			{
				continue;
			}
			for (Bucket x : buckets.subMap(c.getKey() - XP_WINDOW_TICKS, true, c.getKey() + XP_WINDOW_TICKS, true).values())
			{
				if (x.xp)
				{
					return true;
				}
			}
		}
		return false;
	}

	private Map<Integer, Long> trackedOf(Map<Integer, Long> items, boolean includeInputs)
	{
		Map<Integer, Long> tracked = new HashMap<>();
		if (items != null)
		{
			for (Map.Entry<Integer, Long> e : items.entrySet())
			{
				Integer id = e.getKey();
				if (id != null && e.getValue() != null
					&& (recipe.getProducedItemIds().contains(id) || includeInputs && recipe.isTracked(id)))
				{
					tracked.merge(id, e.getValue(), Long::sum);
				}
			}
		}
		return tracked;
	}
}

package com.osrstelemetry.plugin.activity;

/**
 * Recognition state of the structured activity the player is standing in.
 * Transient (never persisted): after a restart or relog the location
 * simply re-arms and real evidence has to activate it again.
 */
public enum RecognitionState
{
	/** Not in any registered structured-activity location. */
	OUTSIDE,
	/** In the location; nothing has happened yet. Never starts a session. */
	ARMED,
	/** First compatible gameplay evidence observed in the location. */
	ACTIVE,
	/** Enough distinct-tick confirmations for strong inertia. */
	LOCKED
}

package com.osrstelemetry.plugin.activity;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * The supported structured activities. Every entry was audited against
 * RuneLite 1.12.39's own data (see the project doc
 * "structured-activity-minigame-support.md"):
 *
 *  - region ids: DiscordGameEventType / BarrowsPlugin / WintertodtPlugin /
 *    LootTrackerPlugin template-region constants;
 *  - reward producers: the same game signals RuneLite's own Loot Tracker
 *    plugin reads (reward interface + container, or a region-bound claim
 *    message + the next inventory change), observed by Spyglass itself so
 *    nothing depends on that optional plugin being enabled;
 *  - completion strings: ChatCommandsPlugin's KILLCOUNT_PATTERN /
 *    GUARDIANS_OF_THE_RIFT_PATTERN, via this project's existing
 *    ActivityKillCountCollector where it already parses them.
 *
 * Deliberately absent: activities whose location or completion could not
 * be confirmed from local client data (e.g. Perilous Moons' arena
 * regions). Adding an activity is a data change here -- nothing else.
 */
public final class StructuredActivityCatalog
{
	private StructuredActivityCatalog()
	{
	}

	public static final String GUARDIANS_OF_THE_RIFT = "guardians_of_the_rift";
	public static final String TEMPOROSS = "tempoross";
	public static final String PEST_CONTROL = "pest_control";
	public static final String GIANTS_FOUNDRY = "giants_foundry";
	public static final String BARROWS = "barrows";
	public static final String WINTERTODT = "wintertodt";

	/** The reward-claim chat message RuneLite 1.12.39 itself keys GotR / Tempoross / Wintertodt rewards on. */
	static final String CLAIM_MESSAGE = "You found some loot: ";

	public static List<StructuredActivityDefinition> definitions()
	{
		return Collections.unmodifiableList(Arrays.asList(
			StructuredActivityDefinition.builder(GUARDIANS_OF_THE_RIFT, "Guardians of the Rift")
				.region(LocationPolicy.EXCLUSIVE, 14484)
				.expectedSkills("runecraft", "mining", "crafting")
				// ChatCommandsPlugin.GUARDIANS_OF_THE_RIFT_PATTERN, tags removed.
				// LIVE-VERIFIED TEXT (2026-10-01): "Amount of rifts you have closed:
				// <col=ff0000>87</col>." -- lowercase "rifts". The former capital-R
				// pattern never matched a real game, so wins were never counted.
				// Case-insensitive so a capitalisation change cannot break it again.
				.completionChat("(?i)^Amount of rifts you have closed: ([0-9,]+)\\.?$")
				// Rewards Guardian search: "You found some loot: ..." in the temple.
				.rewardClaimMessage("guardians_of_the_rift", "Guardians of the Rift", CLAIM_MESSAGE, true, new int[] {14484},
					"Rewards Guardian")
				.completionLabel("Games")
				.build(),
			StructuredActivityDefinition.builder(TEMPOROSS, "Tempoross")
				.region(LocationPolicy.EXCLUSIVE, 12076)
				// Tempoross Cove: where the reward pool is claimed after a game.
				.region(LocationPolicy.NON_EXCLUSIVE, 12588)
				.expectedSkills("fishing", "cooking", "construction")
				// "Your Tempoross kill count is: N" (BOSS_KILL) is one game.
				.completionBoss("Tempoross")
				// Reward pool in the cove. Caskets are opened anywhere: never a Tempoross reward.
				.rewardClaimMessage("tempoross_reward_pool", "Tempoross Reward Pool", CLAIM_MESSAGE, true, new int[] {12588},
					"Reward pool (Tempoross)")
				.completionLabel("Games")
				// TEMPOROSS_REWARDPERMITS: earned this session = positive changes only.
				.currencyLabel("Permits")
				.build(),
			StructuredActivityDefinition.builder(PEST_CONTROL, "Pest Control")
				.region(LocationPolicy.EXCLUSIVE, 10536)
				.combatExpected()
				// Adapter-isolated fallback: only a won, rewarded game prints this.
				.completionChat("awarded you [0-9,]+ Void Knight Commendation points?")
				.completionLabel("Games")
				.build(),
			StructuredActivityDefinition.builder(GIANTS_FOUNDRY, "Giants' Foundry")
				.region(LocationPolicy.EXCLUSIVE, 13491)
				.expectedSkills("smithing")
				// No confirmed per-sword completion signal: no completion metric.
				.build(),
			StructuredActivityDefinition.builder(BARROWS, "Barrows")
				.region(LocationPolicy.STRONG_CONTEXT, 14131)
				.region(LocationPolicy.EXCLUSIVE, 14231)
				.combatExpected()
				.subordinates("Ahrim the Blighted", "Dharok the Wretched", "Guthan the Infested",
					"Karil the Tainted", "Torag the Corrupted", "Verac the Defiled")
				// "Your Barrows chest count is: N" (ACTIVITY_COMPLETION).
				.completionCount("Barrows chest")
				// Chest reward interface (gameval InterfaceID.BARROWS_REWARD) and its
				// item container (InventoryID.TRAIL_REWARDINV -- only read while THIS
				// interface opens, since clue caskets share that container).
				.rewardInterface("barrows", "Barrows", 155, 141)
				.completionLabel("Chests")
				.build(),
			StructuredActivityDefinition.builder(WINTERTODT, "Wintertodt")
				.region(LocationPolicy.EXCLUSIVE, 6462)
				// Wintertodt camp: reward cart / crates, shared with banking and skilling.
				.region(LocationPolicy.NON_EXCLUSIVE, 6461)
				.expectedSkills("firemaking", "woodcutting", "fletching", "construction")
				// "Your subdued Wintertodt count is: N" (ACTIVITY_COMPLETION).
				.completionCount("subdued Wintertodt")
				// Reward cart in the camp. Supply crates are items opened anywhere:
				// never attributed to a Wintertodt session.
				.rewardClaimMessage("wintertodt_reward_cart", "Wintertodt Reward Cart", CLAIM_MESSAGE, false, new int[] {6461},
					"Reward cart (Wintertodt)")
				.completionLabel("Games")
				.build()));
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * Immutable, data-only description of one structured activity (minigame,
 * activity boss, repeatable arena). Everything the generic machinery needs
 * to know about an activity lives here, so adding an activity never means
 * touching the classifier, the lifecycle engine or the coordinator.
 *
 * RuneLite-free: regions are plain template region ids, skills are
 * lower-case skill names, NPC/boss/reward names are exact in-game strings
 * compared case-insensitively.
 */
public final class StructuredActivityDefinition
{
	private static final Set<String> COMBAT_SKILLS = Collections.unmodifiableSet(new LinkedHashSet<>(
		java.util.Arrays.asList("attack", "strength", "defence", "ranged", "magic", "hitpoints")));

	private final String key;
	private final String displayName;
	private final Map<Integer, LocationPolicy> regionPolicies;
	private final Set<String> expectedSkills;
	private final boolean combatExpected;
	private final Set<String> subordinateNames;
	private final Set<String> completionBossNames;
	private final Set<String> completionCountNames;
	private final Pattern completionChatPattern;
	private final java.util.List<StructuredRewardSource> rewardSources;
	private final String completionLabel;
	/** Player-facing name of the activity's native reward currency ("Permits"), or null. */
	private final String currencyLabel;

	private StructuredActivityDefinition(Builder b)
	{
		this.key = Objects.requireNonNull(b.key, "key");
		this.displayName = Objects.requireNonNull(b.displayName, "displayName");
		this.regionPolicies = Collections.unmodifiableMap(new LinkedHashMap<>(b.regionPolicies));
		this.expectedSkills = Collections.unmodifiableSet(new LinkedHashSet<>(b.expectedSkills));
		this.combatExpected = b.combatExpected;
		this.subordinateNames = Collections.unmodifiableSet(new LinkedHashSet<>(b.subordinateNames));
		this.completionBossNames = Collections.unmodifiableSet(new LinkedHashSet<>(b.completionBossNames));
		this.completionCountNames = Collections.unmodifiableSet(new LinkedHashSet<>(b.completionCountNames));
		this.completionChatPattern = b.completionChatPattern;
		java.util.List<StructuredRewardSource> sources = new java.util.ArrayList<>();
		for (RewardSpec r : b.rewardSpecs)
		{
			sources.add(r.build(b.key));
		}
		this.rewardSources = Collections.unmodifiableList(sources);
		this.completionLabel = b.completionLabel;
		this.currencyLabel = b.currencyLabel;
	}

	public static Builder builder(String key, String displayName)
	{
		return new Builder(key, displayName);
	}

	static String normalize(String s)
	{
		return s == null ? null : s.trim().toLowerCase(Locale.ROOT);
	}

	public String getKey()
	{
		return key;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public Map<Integer, LocationPolicy> getRegionPolicies()
	{
		return regionPolicies;
	}

	/** Null when the region is not part of this activity. */
	public LocationPolicy policyFor(int regionId)
	{
		return regionPolicies.get(regionId);
	}

	/** Expected XP: compatible evidence in the location, never fragments the activity. */
	public boolean isExpectedSkill(String skill)
	{
		String s = normalize(skill);
		return s != null && (expectedSkills.contains(s) || (combatExpected && COMBAT_SKILLS.contains(s)));
	}

	/** Bosses/NPCs that belong to the activity and never switch its identity. */
	public boolean isSubordinate(String name)
	{
		String n = normalize(name);
		return n != null && (subordinateNames.contains(n) || completionBossNames.contains(n));
	}

	/** A "Your X kill count is" boss whose kill IS one completion of this activity. */
	public boolean isCompletionBoss(String bossName)
	{
		return completionBossNames.contains(normalize(bossName));
	}

	/** A "Your X count is" completion counter that IS one completion of this activity. */
	public boolean isCompletionCount(String activityName)
	{
		return completionCountNames.contains(normalize(activityName));
	}

	/** This activity's own, isolated chat completion fallback (null when it has none). */
	public Pattern getCompletionChatPattern()
	{
		return completionChatPattern;
	}

	/** This activity's canonical reward sources (each with exactly one producer). */
	public java.util.List<StructuredRewardSource> getRewardSources()
	{
		return rewardSources;
	}

	/** Plural label for the completion metric ("Games"); null when no completion source is known. */
	public String getCompletionLabel()
	{
		return completionLabel;
	}

	public String getCurrencyLabel()
	{
		return currencyLabel;
	}

	public boolean hasCompletionSource()
	{
		return completionLabel != null
			&& (completionChatPattern != null || !completionBossNames.isEmpty() || !completionCountNames.isEmpty());
	}

	private interface RewardSpec
	{
		StructuredRewardSource build(String activityKey);
	}

	public static final class Builder
	{
		private final String key;
		private final String displayName;
		private final Map<Integer, LocationPolicy> regionPolicies = new LinkedHashMap<>();
		private final Set<String> expectedSkills = new LinkedHashSet<>();
		private boolean combatExpected;
		private final Set<String> subordinateNames = new LinkedHashSet<>();
		private final Set<String> completionBossNames = new LinkedHashSet<>();
		private final Set<String> completionCountNames = new LinkedHashSet<>();
		private Pattern completionChatPattern;
		private final java.util.List<RewardSpec> rewardSpecs = new java.util.ArrayList<>();
		private String completionLabel;
		private String currencyLabel;

		private Builder(String key, String displayName)
		{
			this.key = key;
			this.displayName = displayName;
		}

		public Builder region(LocationPolicy policy, int... regionIds)
		{
			for (int id : regionIds)
			{
				regionPolicies.put(id, policy);
			}
			return this;
		}

		public Builder expectedSkills(String... skills)
		{
			for (String s : skills)
			{
				expectedSkills.add(normalize(s));
			}
			return this;
		}

		public Builder combatExpected()
		{
			this.combatExpected = true;
			return this;
		}

		public Builder subordinates(String... names)
		{
			for (String n : names)
			{
				subordinateNames.add(normalize(n));
			}
			return this;
		}

		public Builder completionBoss(String... bossNames)
		{
			for (String n : bossNames)
			{
				completionBossNames.add(normalize(n));
			}
			return this;
		}

		public Builder completionCount(String... activityNames)
		{
			for (String n : activityNames)
			{
				completionCountNames.add(normalize(n));
			}
			return this;
		}

		/** Group 1, when present, must be the authoritative running count. */
		public Builder completionChat(String regex)
		{
			this.completionChatPattern = Pattern.compile(regex);
			return this;
		}

		/** A reward shown in a reward interface whose item container holds the exact reward. */
		public Builder rewardInterface(String sourceKey, String displayName, int interfaceId, int containerId, String... aliases)
		{
			rewardSpecs.add(activityKey -> StructuredRewardSource.rewardInterface(sourceKey, displayName, activityKey,
				interfaceId, containerId, aliasSet(displayName, aliases)));
			return this;
		}

		/**
		 * A reward announced by a claim message in one of {@code regions}
		 * (prefix match when {@code prefix}, else substring), whose items are
		 * the next bounded inventory addition.
		 */
		public Builder rewardClaimMessage(String sourceKey, String displayName, String message, boolean prefix, int[] regions, String... aliases)
		{
			Set<Integer> regionSet = new LinkedHashSet<>();
			for (int r : regions)
			{
				regionSet.add(r);
			}
			rewardSpecs.add(activityKey -> StructuredRewardSource.claimMessage(sourceKey, displayName, activityKey,
				message, prefix, regionSet, aliasSet(displayName, aliases)));
			return this;
		}

		private static Set<String> aliasSet(String displayName, String... aliases)
		{
			Set<String> set = new LinkedHashSet<>();
			set.add(normalize(displayName));
			for (String a : aliases)
			{
				set.add(normalize(a));
			}
			return set;
		}

		public Builder completionLabel(String label)
		{
			this.completionLabel = label;
			return this;
		}

		/** Names the activity's native reward currency (session stats: "Permits +11"). */
		public Builder currencyLabel(String label)
		{
			this.currencyLabel = label;
			return this;
		}

		public StructuredActivityDefinition build()
		{
			return new StructuredActivityDefinition(this);
		}
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;

/**
 * Indexes {@link StructuredActivityDefinition}s by template region id,
 * activity key and reward event name, so every lookup the per-tick
 * collector and the classifier make is a single hash lookup (no scans).
 * Immutable after construction; {@link #defaults()} is shared.
 */
public final class StructuredActivityRegistry
{
	private static final StructuredActivityRegistry DEFAULTS = new StructuredActivityRegistry(StructuredActivityCatalog.definitions());

	private final List<StructuredActivityDefinition> definitions;
	private final Map<Integer, StructuredActivityDefinition> byRegion = new HashMap<>();
	private final Map<String, StructuredActivityDefinition> byKey = new HashMap<>();
	private final Map<String, StructuredRewardSource> rewardByKeyOrAlias = new HashMap<>();
	private final Map<Integer, StructuredRewardSource> rewardByInterface = new HashMap<>();
	private final java.util.List<StructuredRewardSource> claimMessageRewards = new java.util.ArrayList<>();

	public StructuredActivityRegistry(List<StructuredActivityDefinition> definitions)
	{
		this.definitions = Collections.unmodifiableList(definitions);
		for (StructuredActivityDefinition d : definitions)
		{
			if (byKey.put(d.getKey(), d) != null)
			{
				throw new IllegalArgumentException("Duplicate structured activity key: " + d.getKey());
			}
			for (Integer region : d.getRegionPolicies().keySet())
			{
				if (byRegion.put(region, d) != null)
				{
					throw new IllegalArgumentException("Region " + region + " claimed by two structured activities");
				}
			}
			for (StructuredRewardSource reward : d.getRewardSources())
			{
				indexReward(reward.getKey(), reward);
				for (String alias : reward.getAliases())
				{
					indexReward(alias, reward);
				}
				if (reward.getProducer() == StructuredRewardSource.Producer.REWARD_INTERFACE
					&& rewardByInterface.put(reward.getInterfaceId(), reward) != null)
				{
					throw new IllegalArgumentException("Reward interface " + reward.getInterfaceId() + " claimed twice");
				}
				if (reward.getProducer() == StructuredRewardSource.Producer.CLAIM_MESSAGE)
				{
					claimMessageRewards.add(reward);
				}
			}
		}
	}

	public static StructuredActivityRegistry defaults()
	{
		return DEFAULTS;
	}

	public List<StructuredActivityDefinition> all()
	{
		return definitions;
	}

	public StructuredActivityDefinition forRegion(int regionId)
	{
		return byRegion.get(regionId);
	}

	public StructuredActivityDefinition byKey(String key)
	{
		return key == null ? null : byKey.get(key);
	}

	private void indexReward(String keyOrAlias, StructuredRewardSource reward)
	{
		StructuredRewardSource previous = rewardByKeyOrAlias.put(StructuredActivityDefinition.normalize(keyOrAlias), reward);
		if (previous != null && previous != reward)
		{
			throw new IllegalArgumentException("Reward source name " + keyOrAlias + " claimed twice");
		}
	}

	/**
	 * The canonical reward source for a canonical key, its display name or a
	 * declared alias (exact, case-insensitive). Anything else -- an unrelated
	 * chest, a casket, a supply crate -- is null: never guessed.
	 */
	public StructuredRewardSource rewardSource(String keyOrName)
	{
		return keyOrName == null ? null : rewardByKeyOrAlias.get(StructuredActivityDefinition.normalize(keyOrName));
	}

	/** The reward source whose reward interface this is, or null. */
	public StructuredRewardSource rewardForInterface(int interfaceId)
	{
		return rewardByInterface.get(interfaceId);
	}

	/** The reward source whose claim message this is, in this region, or null. */
	public StructuredRewardSource rewardForClaimMessage(String message, int regionId)
	{
		for (StructuredRewardSource reward : claimMessageRewards)
		{
			if (reward.isClaimMessage(message, regionId))
			{
				return reward;
			}
		}
		return null;
	}

	/** Completion label for a session's activity key, or null. */
	public String completionLabel(String activityKey)
	{
		StructuredActivityDefinition d = byKey(activityKey);
		return d == null ? null : d.getCompletionLabel();
	}

	/** A chat completion match: the owning definition plus its optional authoritative count. */
	public static final class ChatCompletion
	{
		private final StructuredActivityDefinition definition;
		private final Integer count;

		ChatCompletion(StructuredActivityDefinition definition, Integer count)
		{
			this.definition = definition;
			this.count = count;
		}

		public StructuredActivityDefinition getDefinition()
		{
			return definition;
		}

		public Integer getCount()
		{
			return count;
		}
	}

	/** Runs each activity's own isolated completion pattern against a tag-free game message. */
	public ChatCompletion matchCompletionChat(String message)
	{
		if (message == null)
		{
			return null;
		}
		for (StructuredActivityDefinition d : definitions)
		{
			if (d.getCompletionChatPattern() == null)
			{
				continue;
			}
			Matcher m = d.getCompletionChatPattern().matcher(message);
			if (m.find())
			{
				Integer count = null;
				if (m.groupCount() >= 1 && m.group(1) != null)
				{
					count = Integer.parseInt(m.group(1).replace(",", ""));
				}
				return new ChatCompletion(d, count);
			}
		}
		return null;
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.HashSet;
import java.util.Set;

/**
 * Transient ARMED / ACTIVE / LOCKED recognition for the structured activity
 * whose location the player is in. Owns no lifecycle: it only tells the
 * classifier how much inertia in-location evidence has earned.
 *
 *  - Location ARMS (and leaving drops back to OUTSIDE). Location is never a
 *    confirmation and never starts anything.
 *  - The first compatible gameplay evidence ACTIVATES.
 *  - {@link #LOCK_DISTINCT_CONFIRMATIONS} compatible confirmations on
 *    DISTINCT game ticks LOCK. Several signals on one tick (a multi-skill
 *    XP drop, a completion plus its XP) are one confirmation.
 *
 * One instance per account (it lives in the session ClassifierContext), so
 * a restart, relog or account switch starts OUTSIDE and must re-arm.
 */
public final class StructuredActivityTracker
{
	/** Activation plus two more distinct-tick confirmations. */
	public static final int LOCK_DISTINCT_CONFIRMATIONS = 3;

	private StructuredActivityDefinition definition;
	private LocationPolicy policy;
	private RecognitionState state = RecognitionState.OUTSIDE;
	private final Set<Long> confirmationTicks = new HashSet<>();

	/**
	 * A location observation. {@code def == null} means "not in any
	 * structured-activity location". Moving between regions of the SAME
	 * activity keeps its recognition (e.g. Tempoross game -> reward cove);
	 * entering a different activity, or re-entering after leaving, re-arms.
	 */
	public void onLocation(StructuredActivityDefinition def, LocationPolicy regionPolicy)
	{
		if (def == null)
		{
			clear();
			return;
		}
		boolean sameActivity = definition != null && definition.getKey().equals(def.getKey()) && state != RecognitionState.OUTSIDE;
		definition = def;
		policy = regionPolicy;
		if (!sameActivity)
		{
			state = RecognitionState.ARMED;
			confirmationTicks.clear();
		}
	}

	/**
	 * Records one compatible confirmation for the armed activity.
	 * {@code tickKey} identifies the game tick; repeats of the same key are
	 * one confirmation.
	 */
	public void confirm(long tickKey)
	{
		if (state == RecognitionState.OUTSIDE || state == RecognitionState.LOCKED)
		{
			// LOCKED is terminal until the location changes: no need to keep
			// remembering ticks for as long as the player stays.
			return;
		}
		confirmationTicks.add(tickKey);
		if (confirmationTicks.size() >= LOCK_DISTINCT_CONFIRMATIONS)
		{
			state = RecognitionState.LOCKED;
		}
		else
		{
			state = RecognitionState.ACTIVE;
		}
	}

	public void clear()
	{
		definition = null;
		policy = null;
		state = RecognitionState.OUTSIDE;
		confirmationTicks.clear();
	}

	/** The armed activity, or null when OUTSIDE. */
	public StructuredActivityDefinition getDefinition()
	{
		return state == RecognitionState.OUTSIDE ? null : definition;
	}

	public LocationPolicy getPolicy()
	{
		return state == RecognitionState.OUTSIDE ? null : policy;
	}

	public RecognitionState getState()
	{
		return state;
	}

	public int getDistinctConfirmations()
	{
		return confirmationTicks.size();
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Objects;
import java.util.Set;

/**
 * One canonical reward source of a structured activity (the Barrows chest,
 * the Tempoross reward pool, ...). {@link #getKey()} is the stable identity
 * used everywhere (telemetry, Current Session, Loot Tracker); the display
 * name is presentation only; aliases let older observations of the SAME
 * causal source (e.g. RuneLite's "Reward pool (Tempoross)" event name
 * written by an earlier build) canonicalize to the same key.
 *
 * How the reward is observed is data too (see {@link Producer}), so the
 * collector interprets every source generically and each source has
 * exactly ONE producer -- one claim, one event.
 */
public final class StructuredRewardSource
{
	/** How Spyglass itself observes the claim -- never via another plugin. */
	public enum Producer
	{
		/**
		 * The game opens a reward interface whose item container holds the
		 * exact reward (e.g. the Barrows chest): WidgetLoaded(interfaceId),
		 * then read containerId.
		 */
		REWARD_INTERFACE,

		/**
		 * The game prints a claim message inside the reward region; the
		 * reward is the items ADDED by the next inventory change within a
		 * few ticks (one bounded, one-shot correlation -- never an open-ended
		 * inventory watch).
		 */
		CLAIM_MESSAGE
	}

	private final String key;
	private final String displayName;
	private final String activityKey;
	private final Producer producer;
	private final int interfaceId;
	private final int containerId;
	private final String claimMessage;
	private final boolean claimMessageIsPrefix;
	private final Set<Integer> claimRegions;
	private final Set<String> aliases;

	private StructuredRewardSource(String key, String displayName, String activityKey, Producer producer, int interfaceId, int containerId,
		String claimMessage, boolean claimMessageIsPrefix, Set<Integer> claimRegions, Set<String> aliases)
	{
		this.key = Objects.requireNonNull(key, "key");
		this.displayName = Objects.requireNonNull(displayName, "displayName");
		this.activityKey = Objects.requireNonNull(activityKey, "activityKey");
		this.producer = Objects.requireNonNull(producer, "producer");
		this.interfaceId = interfaceId;
		this.containerId = containerId;
		this.claimMessage = claimMessage;
		this.claimMessageIsPrefix = claimMessageIsPrefix;
		this.claimRegions = Collections.unmodifiableSet(new LinkedHashSet<>(claimRegions));
		this.aliases = Collections.unmodifiableSet(new LinkedHashSet<>(aliases));
	}

	static StructuredRewardSource rewardInterface(String key, String displayName, String activityKey, int interfaceId, int containerId,
		Set<String> aliases)
	{
		return new StructuredRewardSource(key, displayName, activityKey, Producer.REWARD_INTERFACE, interfaceId, containerId,
			null, false, Collections.<Integer>emptySet(), aliases);
	}

	static StructuredRewardSource claimMessage(String key, String displayName, String activityKey, String message, boolean prefix,
		Set<Integer> regions, Set<String> aliases)
	{
		return new StructuredRewardSource(key, displayName, activityKey, Producer.CLAIM_MESSAGE, -1, -1, message, prefix, regions, aliases);
	}

	public String getKey()
	{
		return key;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/** The structured activity this reward belongs to. */
	public String getActivityKey()
	{
		return activityKey;
	}

	public Producer getProducer()
	{
		return producer;
	}

	public int getInterfaceId()
	{
		return interfaceId;
	}

	public int getContainerId()
	{
		return containerId;
	}

	public Set<Integer> getClaimRegions()
	{
		return claimRegions;
	}

	Set<String> getAliases()
	{
		return aliases;
	}

	/** True when a tag-free game message, seen in {@code regionId}, is this source's claim message. */
	public boolean isClaimMessage(String message, int regionId)
	{
		if (producer != Producer.CLAIM_MESSAGE || message == null || !claimRegions.contains(regionId))
		{
			return false;
		}
		return claimMessageIsPrefix ? message.startsWith(claimMessage) : message.contains(claimMessage);
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Immutable snapshot of the CURRENT Tempoross game, read from the game
 * itself while its in-game HUD is up: Energy / Essence / Storm Intensity
 * from the HUD's own text widgets (gameval InterfaceID.TemporossHud), and
 * the player's points from the game's varbit (VarbitID.TEMPOROSS_CURRENT_POINTS).
 * A value that cannot be read is null and simply not shown -- never guessed.
 * Runtime-only presentation state: no events, not persisted, not lifecycle
 * evidence.
 */
public final class TemporossGameState
{
	private static final Pattern PERCENT = Pattern.compile("(\\d{1,3})\\s*%");

	private final Integer energy;
	private final Integer essence;
	private final Integer storm;
	private final Integer points;

	private TemporossGameState(Integer energy, Integer essence, Integer storm, Integer points)
	{
		this.energy = energy;
		this.essence = essence;
		this.storm = storm;
		this.points = points;
	}

	/** Null when nothing at all could be read. */
	public static TemporossGameState of(Integer energy, Integer essence, Integer storm, Integer points)
	{
		if (energy == null && essence == null && storm == null && points == null)
		{
			return null;
		}
		return new TemporossGameState(energy, essence, storm, points);
	}

	/** The percentage in a HUD text such as "Energy: 87%" (0-100), or null when the text holds none. */
	public static Integer percentOf(String text)
	{
		if (text == null)
		{
			return null;
		}
		Matcher m = PERCENT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		int value = Integer.parseInt(m.group(1));
		return value <= 100 ? value : null;
	}

	public Integer getEnergy()
	{
		return energy;
	}

	public Integer getEssence()
	{
		return essence;
	}

	public Integer getStorm()
	{
		return storm;
	}

	public Integer getPoints()
	{
		return points;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof TemporossGameState))
		{
			return false;
		}
		TemporossGameState s = (TemporossGameState) o;
		return Objects.equals(energy, s.energy) && Objects.equals(essence, s.essence)
			&& Objects.equals(storm, s.storm) && Objects.equals(points, s.points);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(energy, essence, storm, points);
	}

	@Override
	public String toString()
	{
		return "Tempoross{energy=" + energy + ", essence=" + essence + ", storm=" + storm + ", points=" + points + "}";
	}
}

package com.osrstelemetry.plugin.activity;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure, client-thread bookkeeping behind Tempoross's session-summary
 * evidence, fed only with the game's own native state (the points and
 * reward-permit varbits, whether the game HUD interface is loaded, the
 * location, and the kill-count game message). No RuneLite plugin, overlay
 * or UI is involved, and nothing here touches session state: the collector
 * turns the results into Spyglass events.
 *
 * FINAL POINTS. There is no authoritative "game started" signal, so each
 * game's provenance is decided from what was actually observed:
 *  - the HUD interface appearing (or the points varbit resetting) with
 *    points at 0 marks the game OBSERVED FROM START;
 *  - first seeing a game with points already above 0 (plugin enabled /
 *    login mid-game) marks it PARTIAL.
 * On "Your Tempoross kill count is: N" (success only -- a failed game has
 * no such message) the game's final points are the last observed value
 * (points only ever rise within a game; the varbit may already have reset
 * by then, so the larger of the two is used). Only an observed-from-start
 * game with a known, positive final value is trusted for Avg/Best; the
 * completion itself still counts as a game either way. Duplicate kill
 * counts are ignored.
 *
 * REWARD PERMITS. TEMPOROSS_REWARDPERMITS is the player's current permit
 * balance at the reward pool: it rises when a game awards permits and
 * falls when they are spent. "Earned" is therefore the sum of positive
 * changes observed inside the Tempoross location -- a spend only moves the
 * baseline down. The first value seen (after login / re-enable / account
 * switch, and on each entry to the location) is only a baseline, and the
 * first SETTLE_TICKS ticks after a reset only re-baseline, so the login
 * sync of an existing balance is never mistaken for a gain. Undercounting
 * a gain in that window is possible; overcounting is not.
 */
public final class TemporossGameTracker
{
	/** Ticks after a reset during which permit reads only set the baseline. */
	public static final int SETTLE_TICKS = 5;

	private static final Pattern KILL_COUNT = Pattern.compile("Your Tempoross kill count is: ([\\d,]+)");

	/** Last observed points of the game in view (null = no game observed). */
	private Integer lastPoints;
	private boolean observedFromStart;
	private boolean hudWasLoaded;
	private Integer lastScoredKillCount;

	private Integer permitBaseline;
	private int settleTicksLeft = SETTLE_TICKS;

	/** Login / logout / hop / plugin re-enable / account switch: forget everything observed. */
	public void reset()
	{
		clearGame();
		hudWasLoaded = false;
		permitBaseline = null;
		settleTicksLeft = SETTLE_TICKS;
		lastScoredKillCount = null;
	}

	private void clearGame()
	{
		lastPoints = null;
		observedFromStart = false;
	}

	/**
	 * One game tick while logged in.
	 *
	 * @param inTempoross the player is in a Tempoross region (arena or reward cove)
	 * @param hudLoaded   the Tempoross game HUD interface is loaded (a game is in progress)
	 * @param points      TEMPOROSS_CURRENT_POINTS
	 * @param permits     TEMPOROSS_REWARDPERMITS
	 * @return permits gained this tick (&gt; 0), or 0
	 */
	public int onTick(boolean inTempoross, boolean hudLoaded, int points, int permits)
	{
		if (!inTempoross)
		{
			clearGame();
			hudWasLoaded = false;
			permitBaseline = null;
			settleTicksLeft = Math.max(0, settleTicksLeft - 1);
			return 0;
		}
		observePoints(hudLoaded, points);
		return observePermits(permits);
	}

	private void observePoints(boolean hudLoaded, int points)
	{
		if (!hudLoaded)
		{
			// Keep the last value: the kill-count message can arrive after
			// the HUD closes. The next game's HUD starts a fresh observation.
			hudWasLoaded = false;
			return;
		}
		if (!hudWasLoaded || lastPoints == null)
		{
			hudWasLoaded = true;
			lastPoints = points;
			observedFromStart = points == 0;
			return;
		}
		if (points == 0 && lastPoints > 0)
		{
			// The game reset its points: a new game seen from its start.
			lastPoints = 0;
			observedFromStart = true;
			return;
		}
		if (points < lastPoints)
		{
			// Never expected within one game: treat as a game we did not see start.
			lastPoints = points;
			observedFromStart = false;
			return;
		}
		lastPoints = points;
	}

	private int observePermits(int permits)
	{
		if (settleTicksLeft > 0)
		{
			settleTicksLeft--;
			permitBaseline = permits;
			return 0;
		}
		if (permitBaseline == null)
		{
			permitBaseline = permits;
			return 0;
		}
		int gained = permits - permitBaseline;
		permitBaseline = permits;
		return Math.max(0, gained);
	}

	/**
	 * A game message. Returns the completed game's result when it is the
	 * Tempoross kill-count message for a new kill count, else null.
	 *
	 * @param currentPoints TEMPOROSS_CURRENT_POINTS at the message
	 */
	public Result onGameMessage(String message, int currentPoints)
	{
		Integer killCount = killCountOf(message);
		if (killCount == null)
		{
			return null;
		}
		if (lastScoredKillCount != null && killCount <= lastScoredKillCount)
		{
			return null;
		}
		lastScoredKillCount = killCount;
		int best = Math.max(lastPoints == null ? 0 : lastPoints, currentPoints);
		Integer finalPoints = best > 0 ? best : null;
		Result result = new Result(killCount, finalPoints, observedFromStart && finalPoints != null);
		// The next game must prove its own start.
		clearGame();
		return result;
	}

	static Integer killCountOf(String message)
	{
		if (message == null)
		{
			return null;
		}
		Matcher m = KILL_COUNT.matcher(message);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** One successful game: its kill count, final points (null = unknown), and whether they are trusted. */
	public static final class Result
	{
		private final int killCount;
		private final Integer points;
		private final boolean observedFromStart;

		Result(int killCount, Integer points, boolean observedFromStart)
		{
			this.killCount = killCount;
			this.points = points;
			this.observedFromStart = observedFromStart;
		}

		public int getKillCount()
		{
			return killCount;
		}

		public Integer getPoints()
		{
			return points;
		}

		public boolean isObservedFromStart()
		{
			return observedFromStart;
		}
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.model.ActivityState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Deliberately generic, not a per-boss enum.
 *
 * A "completion count" message alone does not by itself imply
 * RAID_COMPLETION. Only the three verified raids
 * (Chambers of Xeric, Theatre of Blood, Tombs of Amascut) get that
 * event type; the Corrupted Gauntlet, minigames, and anything else
 * that happens to print a completion-count line get the generic
 * ACTIVITY_COMPLETION type instead. RAID_IDS is intentionally a small,
 * explicit allowlist rather than a guess at what "sounds like" a raid.
 */
public class ActivityKillCountCollector
{
	private static final Pattern BOSS_KC =
		Pattern.compile("Your (.+?) kill count is:? (\\d[\\d,]*)\\.?");

	private static final Pattern COMPLETION_COUNT =
		Pattern.compile("Your (?:completed )?(.+?) (?:completion )?count is:? (\\d[\\d,]*)\\.?");

	/**
	 * Slugs (see slugify()) for the only three activities this
	 * collector will ever label RAID_COMPLETION. VERIFY: exact
	 * in-game wording for each (e.g. Challenge Mode variants) may
	 * slugify differently than assumed here — check against real
	 * completion messages during manual testing and extend this set
	 * rather than loosening the classification logic itself.
	 */
	static final Set<String> RAID_IDS = new HashSet<>();
	static
	{
		RAID_IDS.add("chambers_of_xeric");
		RAID_IDS.add("theatre_of_blood");
		RAID_IDS.add("tombs_of_amascut");
	}

	private final Client client;
	private final LocalStateStore store;
	private final EventLedger eventLedger;
	private final KnownBossRegistry knownBossRegistry;

	/**
	 * eventId uniqueness only protects against uploading the same event
	 * twice — it does nothing to
	 * stop this collector from OBSERVING and emitting the same real
	 * game event twice in the first place (e.g. two chat messages
	 * with an identical count due to a client redraw, or genuinely
	 * re-processing the same message). Tracked per accountHash so one
	 * account's kill counts never suppress another's, and cleared on
	 * account switch (see resetForAccountSwitch()).
	 */
	private final Map<String, Integer> lastObservedCount = new ConcurrentHashMap<>();

	@Inject
	public ActivityKillCountCollector(Client client, LocalStateStore store, EventLedger eventLedger, KnownBossRegistry knownBossRegistry)
	{
		this.client = client;
		this.store = store;
		this.eventLedger = eventLedger;
		this.knownBossRegistry = knownBossRegistry;
	}

	public void resetForAccountSwitch()
	{
		lastObservedCount.clear();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());

		Matcher bossMatch = BOSS_KC.matcher(message);
		if (bossMatch.find())
		{
			recordKillCount(bossMatch.group(1), parseCount(bossMatch.group(2)));
			return;
		}

		Matcher completionMatch = COMPLETION_COUNT.matcher(message);
		if (completionMatch.find())
		{
			recordCompletionCount(completionMatch.group(1), parseCount(completionMatch.group(2)));
		}
	}

	/** Pure — unit-testable without a Client. Stable and idempotent:
	 * the same display name always slugifies to the same activityId,
	 * so re-observing the same message (e.g. after a client restart)
	 * updates the same activity file rather than creating a duplicate. */
	static String slugify(String displayName)
	{
		return displayName.trim().toLowerCase().replaceAll("[^a-z0-9]+", "_");
	}

	/** Pure — unit-testable without a Client. */
	static EventType classifyCompletion(String activityId)
	{
		return RAID_IDS.contains(activityId) ? EventType.RAID_COMPLETION : EventType.ACTIVITY_COMPLETION;
	}

	private int parseCount(String raw)
	{
		return Integer.parseInt(raw.replace(",", ""));
	}

	private void recordKillCount(String rawDisplayName, int count)
	{
		String displayName = rawDisplayName.trim();
		String activityId = slugify(displayName);

		// Task 5: recorded BEFORE the countAdvanced() early-return below --
		// a real, authoritative kill-count message confirms this boss name
		// for BossActivityContextCollector's resolution regardless of
		// whether the count itself advanced (e.g. a duplicate/redraw
		// re-observation of the same message is still genuine confirmation
		// that this boss name is real for this account, even though it is
		// not new forward progress for the KC state file/BOSS_KILL event
		// below). See KnownBossRegistry's own javadoc.
		knownBossRegistry.recordConfirmedBoss(client.getAccountHash(), displayName);

		if (!countAdvanced(activityId, count))
		{
			return;
		}

		writeState(activityId, displayName, count);
		eventLedger.append(
			client.getAccountHash(),
			EventType.BOSS_KILL,
			new EventPayloads.BossKill(activityId, displayName, count, "AUTHORITATIVE")
		);
	}

	private void recordCompletionCount(String rawDisplayName, int count)
	{
		String displayName = rawDisplayName.trim();
		String activityId = slugify(displayName);

		if (!countAdvanced(activityId, count))
		{
			return;
		}

		writeState(activityId, displayName, count);

		EventType eventType = classifyCompletion(activityId);
		Object payload = eventType == EventType.RAID_COMPLETION
			? new EventPayloads.RaidCompletion(activityId, displayName, count, "AUTHORITATIVE")
			: new EventPayloads.ActivityCompletion(activityId, displayName, count, "AUTHORITATIVE");

		eventLedger.append(client.getAccountHash(), eventType, payload);
	}

	/**
	 * @return true if this observation represents real forward
	 * progress (count strictly greater than the last one seen for
	 * this activity) and should therefore produce state/event output.
	 * A duplicate or non-advancing observation (same count seen
	 * again, or a stale/out-of-order lower count) is silently ignored
	 * — not written, not emitted.
	 */
	private boolean countAdvanced(String activityId, int count)
	{
		String key = client.getAccountHash() + ":" + activityId;
		Integer previous = lastObservedCount.get(key);
		if (!isAdvancing(previous, count))
		{
			return false;
		}
		lastObservedCount.put(key, count);
		return true;
	}

	/** Pure — unit-testable without a Client. previous == null means
	 * "never seen before", which always counts as advancing (it's new
	 * information, not a duplicate). */
	static boolean isAdvancing(Integer previous, int newCount)
	{
		return previous == null || newCount > previous;
	}

	private void writeState(String activityId, String displayName, int count)
	{
		ActivityState state = new ActivityState(activityId);
		state.setDisplayName(displayName);
		state.setSource(ActivityState.Source.AUTHORITATIVE);
		state.setKillCount(count);
		state.setLastUpdatedAt(Instant.now().toString());

		store.write(
			TelemetryPaths.activityFile(client.getAccountHash(), activityId),
			state
		);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Duration;
import java.time.Instant;
import java.util.List;

/**
 * Deduplication baseline for immutable bank snapshots. Deliberately
 * split into two independent pieces:
 *
 * 1. shouldWriteNewSnapshot() — pure, no I/O, no Client — the actual
 *    decision rule, unit-testable in isolation.
 * 2. loadFrom() — the only piece that touches disk, isolated so it can
 *    fail open cleanly and be tested with just a LocalStateStore
 *    (no RuneLite Client needed either, since it only needs the raw
 *    accountHash long, not a live game session).
 *
 * "Absent" (items == null, createdAt == null) represents both cases
 * where no valid baseline exists: never observed before, AND a failed
 * or corrupt load. Both must behave identically — always write a new
 * snapshot rather than risk suppressing a real one — which is why
 * there's a single isPresent() check rather than separate flags for
 * "never loaded" vs "load failed".
 *
 * The baseline also carries the snapshotId of the immutable file it
 * was built from -- an earlier version of this class tracked only
 * items/createdAt, so nothing in memory remembered which immutable
 * snapshot bank.json's pointer
 * should keep referencing between real snapshots. ContainerCollector
 * uses getSnapshotId() to re-stamp bank.json's latestSnapshotId on
 * every ordinary write (Path A) and on dedup-skip refreshes (Path B),
 * instead of leaving the field null (and therefore omitted by Gson)
 * whenever an immutable snapshot isn't being written on that exact
 * observation.
 */
final class BankSnapshotBaseline
{
	private final List<StorageState.StorageItem> items;
	private final Instant createdAt;
	private final String snapshotId;

	private BankSnapshotBaseline(List<StorageState.StorageItem> items, Instant createdAt, String snapshotId)
	{
		this.items = items;
		this.createdAt = createdAt;
		this.snapshotId = snapshotId;
	}

	static BankSnapshotBaseline absent()
	{
		return new BankSnapshotBaseline(null, null, null);
	}

	/**
	 * Convenience overload for tests/call sites that don't care about
	 * snapshotId tracking (pure decision-rule tests A-F). snapshotId is
	 * left null in that case — fine, since shouldWriteNewSnapshot()
	 * never reads it.
	 */
	static BankSnapshotBaseline of(List<StorageState.StorageItem> items, Instant createdAt)
	{
		return of(items, createdAt, null);
	}

	static BankSnapshotBaseline of(List<StorageState.StorageItem> items, Instant createdAt, String snapshotId)
	{
		return new BankSnapshotBaseline(items, createdAt, snapshotId);
	}

	boolean isPresent()
	{
		return items != null && createdAt != null;
	}

	/**
	 * The immutable snapshot id this baseline was built from — the
	 * value bank.json's latestSnapshotId should keep pointing at until
	 * a NEW immutable snapshot is successfully written and replaces it.
	 * Null when isPresent() is false; callers must check isPresent()
	 * (or tolerate null) before relying on this.
	 */
	String getSnapshotId()
	{
		return snapshotId;
	}

	/** Package-private test hook — production code has no legitimate
	 * reason to read this back (the whole point of the pure decision
	 * rule is that callers pass "now" in and get a boolean out), but
	 * tests need it to assert the createdAt clock genuinely didn't
	 * advance across a run of refresh-only observations. */
	Instant getCreatedAt()
	{
		return createdAt;
	}

	/**
	 * Loads the persisted baseline for one account: bank.json's
	 * latestSnapshotId, then that snapshot file's items/lastObservedAt.
	 * Fails open (returns absent()) on literally anything unexpected —
	 * missing pointer, missing/unset latestSnapshotId, missing
	 * snapshot file, missing/malformed fields, a timestamp that
	 * doesn't parse. A failed load must never be distinguishable from
	 * "never observed before" in terms of behavior — both mean "write
	 * a fresh snapshot," per the project's existing "unknown is not
	 * zero" principle applied here to "unknown baseline is not a
	 * matching baseline."
	 */
	static BankSnapshotBaseline loadFrom(LocalStateStore store, long accountHash)
	{
		try
		{
			StorageState pointer = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
			if (pointer == null || pointer.getLatestSnapshotId() == null)
			{
				return absent();
			}

			StorageState snapshot = store.readIfExists(
				TelemetryPaths.bankSnapshotFile(accountHash, pointer.getLatestSnapshotId()), StorageState.class);
			if (snapshot == null || snapshot.getItems() == null || snapshot.getLastObservedAt() == null)
			{
				return absent();
			}

			return of(snapshot.getItems(), Instant.parse(snapshot.getLastObservedAt()), pointer.getLatestSnapshotId());
		}
		catch (Exception e)
		{
			// Instant.parse can throw on a malformed timestamp; treat
			// exactly like every other failure mode here — fail open.
			return absent();
		}
	}

	/**
	 * Pure decision rule — no I/O, no Client, fully unit-testable.
	 *
	 *   shouldWrite = no valid baseline
	 *              OR bank contents changed
	 *              OR baseline is >= maxAge old
	 *
	 * Content equality is plain List.equals() on StorageItem, which
	 * (being @Data) already compares slot/itemId/name/quantity/
	 * equipmentSlot per element — reordering changes which item sits
	 * at which slot, which List.equals() correctly detects without
	 * needing any custom comparison logic.
	 *
	 * baseline.createdAt means "timestamp of the most recent
	 * SUCCESSFULLY WRITTEN immutable snapshot" — NOT "timestamp of the
	 * most recent bank observation." Callers must only ever advance it
	 * via a successful snapshot write (see ContainerCollector's
	 * recordBankBaseline(), called exclusively from a write's
	 * onWritten/writeAndWait-success callback), never from an ordinary
	 * refresh-only observation. This method has no way to enforce that
	 * itself — it only ever reads baseline.createdAt — so the guarantee
	 * lives entirely in when/where the caller constructs a new
	 * baseline.
	 */
	static boolean shouldWriteNewSnapshot(
		BankSnapshotBaseline baseline,
		List<StorageState.StorageItem> candidateItems,
		Instant now,
		Duration maxAge)
	{
		if (!baseline.isPresent())
		{
			return true;
		}
		if (!baseline.items.equals(candidateItems))
		{
			return true;
		}
		return Duration.between(baseline.createdAt, now).compareTo(maxAge) >= 0;
	}
}

package com.osrstelemetry.plugin.collectors;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Bounds disk usage for one account's bank_snapshots/ directory.
 *
 * EVENT/FILE CONSISTENCY CONTRACT ("Option A" chosen — the simplest of
 * the considered options):
 *
 *   Historical BANK_SNAPSHOT events in events.jsonl may reference an
 *   immutable snapshot file that retention has since pruned. This
 *   project does not emit a tombstone/pruned record (Option B) or
 *   maintain a separate retained/pruned manifest (Option C).
 *
 *   WHY: events.jsonl is already explicitly documented (see
 *   EventPayloads.BankSnapshot's javadoc) as "a pointer only... the
 *   actual delta calculation is a backend job... against the
 *   corresponding bank.json snapshot" — i.e. downstream consumption of
 *   a BANK_SNAPSHOT event was never specified to require every
 *   historical snapshot file to still exist forever. A downstream
 *   consumer reading an old BANK_SNAPSHOT event whose snapshotId no
 *   longer resolves to a file under bank_snapshots/ should treat that
 *   specific historical snapshot as pruned/unavailable — exactly the
 *   same shape of "fail open on missing data" this project already
 *   uses everywhere else (see BankSnapshotBaseline.loadFrom()'s own
 *   fail-open contract for the CURRENT pointer). Recovering full
 *   historical fidelity forever would require either unbounded
 *   storage (the thing Phase 3 exists to bound) or a schema/event
 *   redesign (tombstones or a manifest) that Phase 3 was told to
 *   avoid unless a clean minimal option didn't exist. One does:
 *   "missing means pruned" needs no new event type, no new file
 *   format, and no change to any existing reader's happy path.
 *
 * WHAT IS NEVER PRUNED: the immutable snapshot currently referenced by
 * bank.json's latestSnapshotId — pruning it would make the CURRENT
 * pointer itself dangling, which is a materially different (and worse)
 * failure than an old historical event referencing a pruned file. If
 * protecting that one file means the directory stays slightly above
 * the 90MB target, that is accepted (see pruneIfNeeded() javadoc) —
 * never deleting the live pointer's target takes priority over hitting
 * the target exactly.
 */
@Slf4j
final class BankSnapshotRetention
{
	private BankSnapshotRetention()
	{
	}

	static final long DEFAULT_MAX_BYTES = 100L * 1024 * 1024;
	static final long DEFAULT_TARGET_BYTES = 90L * 1024 * 1024;

	/**
	 * Prunes oldest-first from snapshotsDir until total size is at or
	 * under targetBytes, but ONLY if the current total exceeds
	 * maxBytes in the first place (the 100MB/90MB gap is deliberate
	 * hysteresis — see class javadoc — so a directory sitting at 91MB
	 * doesn't get pruned every single time a new snapshot nudges it
	 * up, only once it actually crosses 100MB).
	 *
	 * Must be called ONLY after the caller has confirmed a new
	 * immutable snapshot was successfully and durably written — never
	 * speculatively, and never before that write's success is known
	 * (see ContainerCollector call sites). protectedSnapshotId (the
	 * CURRENT bank.json.latestSnapshotId — normally the snapshot that
	 * was just written) is never deleted, even if every other file is
	 * gone and the directory is still above targetBytes as a result.
	 *
	 * Ordering source: each file's last-modified time — these are
	 * immutable snapshot files, written exactly once and never modified
	 * again, so mtime is a reliable proxy for "when was this snapshot
	 * taken" without needing to parse each file's JSON body (which
	 * would also make pruning itself fail-prone on a corrupt file).
	 * Ties (rare — millisecond-resolution writes) are broken by
	 * filename for fully deterministic ordering.
	 *
	 * Safety: only files matching *.json under snapshotsDir count
	 * toward size or are eligible for deletion — anything else
	 * (unexpected files, subdirectories, partial .tmp files left by an
	 * interrupted write elsewhere) is silently ignored, never counted,
	 * never deleted, never crashes pruning. Each individual size/mtime
	 * read or delete failure is caught, logged, and skipped — pruning
	 * continues with the next file rather than aborting, and a
	 * deletion failure never invalidates the snapshot that was just
	 * successfully written.
	 */
	static void pruneIfNeeded(Filepath snapshotsDir, String protectedSnapshotId, long maxBytes, long targetBytes)
	{
		try
		{
			List<Filepath> listed;
			// walk(1): snapshotsDir itself (depth 0) plus its immediate
			// children (depth 1) only, filtered to files -- matches the
			// old File.listFiles()'s flat, single-level, files-and-dirs
			// listing, minus the directories (filtered below exactly as
			// before). A missing directory is exactly the old
			// "listFiles() == null" no-op case.
			try (Stream<Filepath> walk = snapshotsDir.walk(1))
			{
				listed = walk.filter(Filepath::isFile).collect(Collectors.toList());
			}
			catch (IOException e)
			{
				return;
			}
			if (listed.isEmpty())
			{
				return;
			}

			List<Filepath> snapshotFiles = new ArrayList<>();
			long total = 0;
			for (Filepath f : listed)
			{
				if (!f.getFileName().endsWith(".json"))
				{
					// Malformed/unexpected entries (a stray .tmp from an
					// interrupted write elsewhere, OS metadata files,
					// etc.) are simply not part of the accounting.
					continue;
				}
				total += sizeOrZero(f);
				snapshotFiles.add(f);
			}

			if (total <= maxBytes)
			{
				return;
			}

			snapshotFiles.sort(Comparator
				.comparingLong(BankSnapshotRetention::lastModifiedMillisOrZero)
				.thenComparing(Filepath::getFileName));

			for (Filepath f : snapshotFiles)
			{
				if (total <= targetBytes)
				{
					break;
				}
				String snapshotId = stripJsonExtension(f.getFileName());
				if (snapshotId.equals(protectedSnapshotId))
				{
					// Never delete the file bank.json currently points
					// at — accept staying above target instead (see
					// class javadoc).
					continue;
				}

				long length = sizeOrZero(f);
				boolean deleted;
				try
				{
					f.delete();
					deleted = true;
				}
				catch (IOException | SecurityException e)
				{
					deleted = false;
					log.warn("Failed deleting old bank snapshot {} during retention pruning", f, e);
				}

				if (deleted)
				{
					total -= length;
				}
				else
				{
					log.warn("Could not delete old bank snapshot {} during retention pruning; leaving it in place", f);
				}
			}
		}
		catch (Exception e)
		{
			// Retention pruning must never be able to take down a
			// caller that just successfully wrote a new snapshot —
			// fail safe/non-fatal on literally anything unexpected.
			log.warn("Bank snapshot retention pruning failed unexpectedly for {}; leaving files as-is", snapshotsDir, e);
		}
	}

	/**
	 * Filepath.size()/getLastModifiedTime() throw IOException where
	 * File.length()/lastModified() silently returned 0 -- these two
	 * helpers restore that exact fail-safe-to-zero behavior so a single
	 * unreadable file's size/mtime can never abort the whole pruning
	 * pass (the outer try/catch would otherwise turn one bad file into
	 * "leaving files as-is" for every file).
	 */
	private static long sizeOrZero(Filepath f)
	{
		try
		{
			return f.size();
		}
		catch (IOException e)
		{
			log.warn("Failed reading size of {} during retention pruning; treating as 0 bytes", f, e);
			return 0;
		}
	}

	private static long lastModifiedMillisOrZero(Filepath f)
	{
		try
		{
			return f.getLastModifiedTime().toMillis();
		}
		catch (IOException e)
		{
			log.warn("Failed reading last-modified time of {} during retention pruning; sorting as oldest", f, e);
			return 0;
		}
	}

	private static String stripJsonExtension(String fileName)
	{
		return fileName.endsWith(".json") ? fileName.substring(0, fileName.length() - ".json".length()) : fileName;
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Emits the non-authoritative EventType.BOSS_ACTIVITY_CONTEXT signal --
 * see that constant's javadoc for the full rationale and the exact
 * distinction from BOSS_KILL.
 *
 * SIGNAL SELECTED: net.runelite.api.events.InteractingChanged, filtered
 * to event.getSource() == client.getLocalPlayer() and
 * event.getTarget() instanceof NPC -- this choice rests on
 * well-established RuneLite API knowledge (InteractingChanged/
 * Actor#getInteracting()) plus this codebase's own prior source-level
 * reference to the exact same technique: NpcDeathCollector's class
 * javadoc already discusses `npc.getInteracting() == local player` as
 * a real, known filtering technique, previously considered and
 * rejected there for a DIFFERENT purpose (kill attribution -- too
 * strong a claim for that event). The purpose here is narrower and
 * different: activity CONTEXT evidence for session identity, not kill
 * or damage attribution, which is exactly what this technique is
 * suited for.
 *
 * NOT location-based: this collector never reads a WorldPoint or
 * region as primary proof of anything -- see class javadoc on
 * EventType.BOSS_ACTIVITY_CONTEXT.
 *
 * DEDUP / HEARTBEAT DESIGN: InteractingChanged already only fires when
 * RuneLite observes the interaction target actually change (not once
 * per game tick), so this collector is not defending against a raw
 * per-tick flood. What it DOES defend against is a single continuous
 * boss fight producing MANY InteractingChanged deliveries for the
 * SAME resolved boss -- real OSRS bosses routinely swap NPC instances/
 * sub-targets mid-fight (phase transitions, multi-NPC encounters like
 * Grotesque Guardians switching between Dawn and Dusk, a boss briefly
 * losing and regaining a valid interacting target). decide() tracks,
 * per account, the canonical boss name the player is CURRENTLY
 * understood to be engaging (lastTrackedBossByAccount) and only emits
 * when that resolved value actually CHANGES -- including changing to
 * null when the interaction ends or moves to an unresolved NPC. This
 * is deliberately NOT "emit once ever per account": clearing the
 * tracked value on a break means re-engaging the SAME boss later
 * (e.g. after fully disengaging, or after the fight moved through
 * unrelated trash NPCs) emits a fresh BOSS_ACTIVITY_CONTEXT signal,
 * which matters for genuinely resuming a SUSPENDED BOSSING session via
 * ActivitySignalClassifier.decideCombatBranch()'s own exact-identity-
 * match fast path -- not merely for the very first encounter.
 *
 * Like every collector, runs unconditionally while the plugin is enabled
 * (see OsrsTelemetryConfig).
 */
public class BossActivityContextCollector
{
	private final Client client;
	private final KnownBossRegistry knownBossRegistry;
	private final EventLedger eventLedger;

	/**
	 * Per-account "what boss (if any) is the local player currently
	 * understood to be engaging" -- see class javadoc's DEDUP /
	 * HEARTBEAT DESIGN section. Absent/null means "not currently
	 * engaging a known boss."
	 */
	private final Map<Long, String> lastTrackedBossByAccount = new ConcurrentHashMap<>();

	@Inject
	public BossActivityContextCollector(Client client, KnownBossRegistry knownBossRegistry, EventLedger eventLedger)
	{
		this.client = client;
		this.knownBossRegistry = knownBossRegistry;
		this.eventLedger = eventLedger;
	}

	public void resetForAccountSwitch(long accountHash)
	{
		lastTrackedBossByAccount.remove(accountHash);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Actor source = event.getSource();
		boolean sourceIsLocalPlayer = source != null && source == client.getLocalPlayer();
		if (!sourceIsLocalPlayer)
		{
			// Not the local player's own interaction (another player or
			// NPC interacting with something) -- irrelevant, and left
			// untouched: see decide()'s own doc for why this branch never
			// mutates tracked state either.
			return;
		}

		Actor target = event.getTarget();
		String npcName = (target instanceof NPC) ? ((NPC) target).getName() : null;

		long accountHash = client.getAccountHash();
		String candidate = decide(true, npcName, knownBossRegistry, accountHash, lastTrackedBossByAccount);
		if (candidate == null)
		{
			return;
		}

		eventLedger.append(accountHash, EventType.BOSS_ACTIVITY_CONTEXT, new EventPayloads.BossActivityContext(candidate));
	}

	/**
	 * Pure core decision, factored out for the same reason as
	 * NpcDeathCollector.buildPayload(): unit-testable without mocking
	 * RuneLite's EventBus/Client/Actor/NPC types (this project has no
	 * Mockito dependency). Takes already-read primitive/plain-object
	 * values only -- KnownBossRegistry is itself RuneLite-API-free (see
	 * its own class javadoc), so this method never touches RuneLite at
	 * all.
	 *
	 * `trackedByAccount` is mutated as a side effect (updated to the new
	 * resolved value, or removed on a break) -- deliberately not a pure
	 * function in the strictest sense, but this mirrors how the
	 * production caller (onInteractingChanged()) actually needs to use
	 * it, and keeps a single source of truth for the dedup/heartbeat
	 * decision rather than splitting it across two methods that could
	 * drift out of sync. A plain java.util.Map (e.g. a HashMap) is
	 * sufficient for tests -- no RuneLite type is required.
	 *
	 * @return the canonical boss display name to emit as a new
	 * BOSS_ACTIVITY_CONTEXT signal, or null if nothing should be emitted
	 * for this call (source not the local player, target not a
	 * recognized boss NPC, or the resolved boss is unchanged from what
	 * is already tracked for this account).
	 */
	static String decide(
		boolean sourceIsLocalPlayer,
		String npcName,
		KnownBossRegistry registry,
		long accountHash,
		Map<Long, String> trackedByAccount)
	{
		if (!sourceIsLocalPlayer)
		{
			return null;
		}

		String resolved = npcName == null ? null : registry.resolveCandidateBossName(accountHash, npcName);
		String previouslyTracked = trackedByAccount.get(accountHash);

		if (resolved == null)
		{
			// Interaction ended, or target is not a recognized boss NPC --
			// clear tracked state so a later re-engagement with a
			// genuinely-known boss (including the SAME one) is treated as
			// fresh evidence rather than deduped away.
			trackedByAccount.remove(accountHash);
			return null;
		}

		if (resolved.equals(previouslyTracked))
		{
			return null;
		}

		trackedByAccount.put(accountHash, resolved);
		return resolved;
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Two distinct data paths, deliberately not conflated:
 *
 * 1. NEW-ITEM NOTIFICATION (implemented here): the game prints "New
 *    item added to your collection log: <item name>" as a game
 *    message when you receive a log item, live, regardless of whether
 *    you've ever opened the collection log interface.
 *
 *    NOTE: this message's presence depends on the player's in-game
 *    "Collection log - New item"
 *    chat notification setting being turned on. If that setting is
 *    off, this collector observes nothing for that item — and,
 *    consistent with "unknown is not zero" throughout this project,
 *    the ABSENCE of this message must never be read as "no new item
 *    occurred." It only proves a new item occurred when it fires; it
 *    proves nothing when it doesn't.
 *
 *    Message text can carry RuneScape formatting tags (e.g. colour
 *    tags) — stripped via Text.removeTags() before matching, per the
 *    same utility RuneLite's own core plugins use for this.
 *
 * 2. FULL PAGE STATE (still NOT implemented): reconstructing a
 *    complete page (every item on e.g. the "Zulrah" page, obtained or
 *    not, with quantities) requires reading the collection log
 *    widget/script output when the player opens that page in-game. I
 *    still do not have confirmed, current widget/script IDs for this
 *    interface, and am not willing to guess them. RuneLite's own
 *    built-in net.runelite.client.plugins.collectionlog is the
 *    reference implementation to read before building this — that
 *    read has not happened yet; it remains an honest
 *    gap, not a silent one. Unseen/unopened pages must remain
 *    represented as unknown, never as "nothing obtained".
 */
public class CollectionLogCollector
{
	private static final Pattern NEW_ITEM =
		Pattern.compile("New item added to your collection log: (.+)");

	private final Client client;
	private final EventLedger eventLedger;

	@Inject
	public CollectionLogCollector(Client client, EventLedger eventLedger)
	{
		this.client = client;
		this.eventLedger = eventLedger;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		Matcher matcher = NEW_ITEM.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String itemName = matcher.group(1).trim();
		// itemId is deliberately null — the chat message doesn't carry
		// one, and resolving name -> ID by guessing would be worse than
		// leaving it unresolved (see EventPayloads.CollectionLogNewItem
		// javadoc). Fill this in once the full-page widget read exists.
		eventLedger.append(
			client.getAccountHash(),
			EventType.COLLECTION_LOG_NEW_ITEM,
			new EventPayloads.CollectionLogNewItem(null, itemName)
		);
	}
}

package com.osrstelemetry.plugin.collectors;

import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Individual task completion fires live as a chat message and is
 * reliable to detect that way (VERIFY exact current wording — this is
 * the kind of string Jagex has tweaked before). Tags stripped via
 * Text.removeTags() same as the collection log collector.
 *
 * totalPoints and unlockedTier are NOT derivable from this message —
 * they live in the Combat Achievements interface (varbit or widget,
 * not yet verified). Left unimplemented here rather than invented;
 * the completion EVENT below is real and doesn't depend on that gap.
 */
public class CombatAchievementCollector
{
	private static final Pattern TASK_COMPLETED =
		Pattern.compile("Congratulations, you(?:'ve| have) completed an? (\\w+) combat task: (.+)\\.");

	private final Client client;
	private final EventLedger eventLedger;

	@Inject
	public CombatAchievementCollector(Client client, EventLedger eventLedger)
	{
		this.client = client;
		this.eventLedger = eventLedger;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		Matcher matcher = TASK_COMPLETED.matcher(message);
		if (!matcher.find())
		{
			return;
		}

		String tier = matcher.group(1);
		String taskName = matcher.group(2).trim();

		eventLedger.append(
			client.getAccountHash(),
			EventType.COMBAT_ACHIEVEMENT_COMPLETED,
			new EventPayloads.CombatAchievementCompleted(tier, taskName)
		);
	}
}

