/**
 * Normalized evidence for structured activities (see
 * activity.StructuredActivityRegistry). Emits three generic events and
 * never touches session state:
 *
 *  - STRUCTURED_ACTIVITY_STATE when the resolved (activity, policy) of the
 *    player's TEMPLATE region changes. One int compare per tick; the
 *    registry lookup runs only when the region id itself changes. Instances
 *    resolve through WorldPoint.fromLocalInstance, so instanced arenas map to
 *    their template region. Logging out / hopping forgets the location, so
 *    the first tick after login re-emits it (re-arm) -- and nothing else.
 *  - STRUCTURED_ACTIVITY_COMPLETION from an activity's own isolated chat
 *    pattern, deduplicated by the game's running count when it has one.
 *  - STRUCTURED_REWARD for each claim of a declared reward source, observed
 *    here from the game itself -- NOT from RuneLite's optional Loot Tracker
 *    plugin (its LootReceived event is posted only by that plugin, so it
 *    silently disappears when the plugin is disabled). Each source has one
 *    producer (see activity.StructuredRewardSource.Producer):
 *      REWARD_INTERFACE -- WidgetLoaded for the source's reward interface,
 *        then the exact contents of its item container (Barrows chest);
 *      CLAIM_MESSAGE -- the source's claim message in one of its regions
 *        arms ONE inventory correlation: the items added by the next
 *        inventory change within CLAIM_WINDOW_TICKS become the reward, then
 *        it disarms (GotR rewards guardian, Tempoross reward pool,
 *        Wintertodt reward cart). This is the same signal pair RuneLite's
 *        own plugin keys these rewards on; there is no open-ended inventory
 *        watch and no item-name rule. Unrelated chests, caskets and supply
 *        crates have no declared source and are never emitted.
 *
 * All of this runs on the client thread (RuneLite event dispatch); only
 * plain item ids/names/quantities leave it, inside the appended event.
 */
public class StructuredActivityCollector
{
	private static final int NO_REGION = Integer.MIN_VALUE;

	private final Client client;
	/** Item id -> name, read on the client thread (ItemManager in production). */
	private final IntFunction<String> itemNames;
	private final EventLedger eventLedger;
	private final StructuredActivityRegistry registry;

	private int lastRegionId = NO_REGION;
	private String lastActivityKey;
	private LocationPolicy lastPolicy;
	private Long lastAccountHash;
	private final Map<String, Integer> lastCompletionCount = new HashMap<>();
	/** Tick of the last count-less completion per activity; see onGameMessage. */
	private final Map<String, Integer> lastCountlessCompletionTick = new HashMap<>();
	/** Two identical count-less completion texts this close together are one game (e.g. game message + message box). */
	static final int COUNTLESS_COMPLETION_DEDUPE_TICKS = 2;

	/** A claim message arms one inventory correlation for at most this many ticks (RuneLite's own window is 10). */
	static final int CLAIM_WINDOW_TICKS = 10;

	/**
	 * BARROWS CURRENT RUN: the game's own per-brother "killed this run"
	 * varbits, mirrored for presentation only (see BarrowsRunProgress).
	 * Null = not read yet / logged out. Written on the client thread,
	 * read by the UI; never an event, never lifecycle evidence.
	 */
	private volatile BarrowsRunProgress barrowsProgress;
	/**
	 * TEMPOROSS CURRENT GAME, read from the game's own HUD / points varbit
	 * while inside the Tempoross location with its HUD up; null otherwise
	 * (lobby, reward cove, left, logged out). Presentation only.
	 */
	private volatile TemporossGameState temporossGame;
	private volatile Runnable progressListener;
	/** Tempoross final points / permits bookkeeping (client thread only). */
	private final TemporossGameTracker temporossTracker = new TemporossGameTracker();

	/**
	 * GUARDIANS OF THE RIFT CURRENT GAME (Guardian Power and the open rifts from
	 * the HUD's own update script, energy from the game's earned-this-game
	 * varbits) while a game is in progress; null otherwise. Presentation only.
	 *
	 * STABILITY (live QA 2026-10-01): the HUD widget is briefly absent while a
	 * region loads (stepping through a rift into an altar, and back), yet the
	 * game goes on -- its update script kept firing inside the altars. The
	 * state is therefore KEPT (last known) through a short gap instead of
	 * blinking out, and cleared only when the game ends (win / loss), the
	 * player leaves the game for longer than the gap, logs out, hops, switches
	 * account or re-enables the plugin. Between games (after a win or loss,
	 * until the next game's Guardian Power rises from 0) there is no current
	 * game, so the previous game's values never leak into the next.
	 */
	private volatile GotrGameState gotrGame;
	/** GotR HUD update clientscript; its args carry the Great Guardian's power (no gameval constant exists). */
	static final int GOTR_HUD_UPDATE_SCRIPT = 5980;
	static final int GOTR_SCRIPT_ARG_CURRENT_POWER = 3;
	static final int GOTR_SCRIPT_ARG_MAX_POWER = 4;
	/** The HUD script's open-rift guardian indices: elemental 1-4, catalytic 1-8 (see GotrAltar). */
	static final int GOTR_SCRIPT_ARG_ACTIVE_ELEMENTAL = 6;
	static final int GOTR_SCRIPT_ARG_ACTIVE_CATALYTIC = 7;
	/** Ticks the game state survives with neither the HUD nor GOTR_IS_PLAYING (a region load), ~5 s. */
	static final int GOTR_IN_GAME_GRACE_TICKS = 8;
	/** Ticks the "successfully closed the rift" line waits for its rifts-closed count before standing in for it. */
	static final int GOTR_WIN_CORROBORATION_TICKS = 2;
	/** Last Guardian Power reported by the HUD script (client thread). */
	private Integer gotrPowerCurrent;
	private Integer gotrPowerMax;
	private GotrAltar gotrActiveElemental;
	private GotrAltar gotrActiveCatalytic;
	/** Last tick the game was confirmed in progress (HUD loaded or GOTR_IS_PLAYING); null = not in a game. */
	private Integer gotrLastInGameTick;
	/** The last game ended (win / loss); no current game until the next one's power rises from 0. */
	private boolean gotrGameEnded;
	private boolean gotrEndedPowerReset;
	/** Tick of a "successfully closed the rift" line still waiting for its count; null = none. */
	private Integer gotrPendingWinTick;
	/** Tick a count-less win was recorded (so a late count line for the same game is not a second game). */
	private Integer gotrCountlessWinTick;
	/** Whether this player can enter an altar (level + quest, read from the game); replaceable in tests. */
	private java.util.function.Predicate<GotrAltar> gotrAltarUsable = this::readAltarUsable;
	private final Map<GotrAltar, Boolean> gotrUsableCache = new java.util.EnumMap<>(GotrAltar.class);
	private int gotrUsableLevel = -1;
	private volatile GotrRewardWallet gotrWallet;
	/** Altars of the portal talismans in the inventory (from the INV container already observed). */
	private Set<GotrAltar> gotrTalismans = EnumSet.noneOf(GotrAltar.class);
	/** GotR game context on the last tick (HUD loaded, GOTR_IS_PLAYING, or the GotR location): crafting attribution only. */
	private boolean gotrContext;
	private final GotrGameTracker gotrTracker = new GotrGameTracker();
	private final GotrRewardPointTracker gotrPoints = new GotrRewardPointTracker();
	private final ProductionTracker gotrRunes = new ProductionTracker(GotrRunes.RECIPE);
	/**
	 * Rune pouch slot type (varbit value) -> rune item id, via the game's own
	 * RUNEPOUCH_RUNE enum; replaceable in tests. Returns <= 0 when unknown.
	 */
	private java.util.function.IntUnaryOperator runePouchRuneItem = this::runePouchRuneItemFromEnum;

	private StructuredRewardSource pendingClaim;
	private Map<Integer, Long> claimSnapshot = new HashMap<>();
	private int claimTicksLeft;

	@Inject
	public StructuredActivityCollector(Client client, ItemManager itemManager, EventLedger eventLedger)
	{
		this(client, id -> itemManager.getItemComposition(id).getName(), eventLedger, StructuredActivityRegistry.defaults());
	}

	StructuredActivityCollector(Client client, IntFunction<String> itemNames, EventLedger eventLedger, StructuredActivityRegistry registry)
	{
		this.client = client;
		this.itemNames = itemNames;
		this.eventLedger = eventLedger;
		this.registry = registry;
	}

	/**
	 * Plugin re-enable: a reward claim armed before the disable must never
	 * be correlated with inventory changes made while the plugin was off.
	 * The remembered location is deliberately KEPT: if the player left the
	 * activity while disabled, the first region observed afterwards differs
	 * from it and the usual exit (disarm) event is sent.
	 */
	public void disarmPendingClaim()
	{
		disarmClaim();
		// Whatever changed while disabled is unknown: re-baseline permits,
		// and a game in progress can no longer be proven observed from start.
		temporossTracker.reset();
		resetGotrTracking();
	}

	/** GotR: balances, game provenance, Guardian Power, open rifts and the rune baseline are all unknown again. */
	private void resetGotrTracking()
	{
		gotrTracker.reset();
		gotrPoints.reset();
		gotrRunes.reset();
		gotrPowerCurrent = null;
		gotrPowerMax = null;
		gotrActiveElemental = null;
		gotrActiveCatalytic = null;
		gotrContext = false;
		gotrLastInGameTick = null;
		gotrGameEnded = false;
		gotrEndedPowerReset = false;
		gotrPendingWinTick = null;
		gotrCountlessWinTick = null;
		gotrUsableCache.clear();
		gotrUsableLevel = -1;
		gotrTalismans = EnumSet.noneOf(GotrAltar.class);
		refreshGotrWallet();
	}

	/** The player's GotR reward wallet when the game has stated both balances this login; null = unknown. */
	public GotrRewardWallet getGotrWallet()
	{
		return gotrWallet;
	}

	private void refreshGotrWallet()
	{
		GotrRewardWallet w = gotrPoints.wallet();
		if (!Objects.equals(w, gotrWallet))
		{
			gotrWallet = w;
			notifyProgressListener();
		}
	}

	/** Test seam: altar eligibility without a live client. */
	void setGotrAltarUsable(java.util.function.Predicate<GotrAltar> usable)
	{
		this.gotrAltarUsable = usable;
		gotrUsableCache.clear();
	}

	/** Runecraft level (boosts count at altars) and the altar's quest, from the game itself. Client thread. */
	private boolean readAltarUsable(GotrAltar altar)
	{
		if (client.getBoostedSkillLevel(Skill.RUNECRAFT) < altar.getRunecraftLevel())
		{
			return false;
		}
		return altar.getQuest() == null || altar.getQuest().getState(client) == net.runelite.api.QuestState.FINISHED;
	}

	/** Cached per altar until the Runecraft level changes; null when it cannot be read. */
	private Boolean altarUsable(GotrAltar altar)
	{
		if (altar == null)
		{
			return null;
		}
		int level = client.getBoostedSkillLevel(Skill.RUNECRAFT);
		if (level != gotrUsableLevel)
		{
			gotrUsableCache.clear();
			gotrUsableLevel = level;
		}
		Boolean cached = gotrUsableCache.get(altar);
		if (cached != null)
		{
			return cached;
		}
		try
		{
			boolean usable = gotrAltarUsable.test(altar);
			gotrUsableCache.put(altar, usable);
			return usable;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** A win or loss ended the current game: no current game until the next one starts. */
	private void endGotrGame()
	{
		gotrGameEnded = true;
		gotrEndedPowerReset = false;
		setGotrGame(null);
	}

	public void resetForAccountSwitch()
	{
		setBarrowsProgress(null);
		setTemporossGame(null);
		temporossTracker.reset();
		setGotrGame(null);
		resetGotrTracking();
		forgetLocation();
		disarmClaim();
		lastCompletionCount.clear();
		lastCountlessCompletionTick.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			// Disarm (for the account that was inside), then forget, so the
			// next login re-arms from scratch instead of inheriting a lock.
			if (lastActivityKey != null && lastAccountHash != null)
			{
				eventLedger.append(lastAccountHash, EventType.STRUCTURED_ACTIVITY_STATE,
					new EventPayloads.StructuredActivityState(null, null, lastRegionId));
			}
			forgetLocation();
			disarmClaim();
			setBarrowsProgress(null);
			setTemporossGame(null);
			temporossTracker.reset();
			setGotrGame(null);
			resetGotrTracking();
		}
	}

	/** The current Tempoross game as the game's HUD reports it, or null when not in a game. */
	public TemporossGameState getTemporossGame()
	{
		return temporossGame;
	}

	/**
	 * Client thread, once per game tick while in the Tempoross location:
	 * three widget texts and one varbit (cheap). Publishes only on change.
	 * Outside the location, or without the game HUD, the game state is
	 * cleared -- never kept as stale bars.
	 *
	 * SOURCE: interface 437 (TemporossHud) is Jagex's own game HUD. Each bar
	 * is a layer (ENERGY / ESSENCE / STORM_INTENSITY -- no text of its own)
	 * whose *_TITLE text component carries "Energy: 70%" etc.; the fill
	 * width is presentation only and is not read. The gate is the interface
	 * being LOADED, not visible: another plugin hiding the vanilla HUD must
	 * never blank Spyglass (the game keeps updating the hidden text).
	 */
	void readTemporossGame()
	{
		if (!StructuredActivityCatalog.TEMPOROSS.equals(lastActivityKey) || !temporossHudLoaded())
		{
			setTemporossGame(null);
			return;
		}
		setTemporossGame(TemporossGameState.of(
			TemporossGameState.percentOf(widgetText(InterfaceID.TemporossHud.ENERGY_TITLE)),
			TemporossGameState.percentOf(widgetText(InterfaceID.TemporossHud.ESSENCE_TITLE)),
			TemporossGameState.percentOf(widgetText(InterfaceID.TemporossHud.STORM_INTENSITY_TITLE)),
			client.getVarbitValue(VarbitID.TEMPOROSS_CURRENT_POINTS)));
	}

	private boolean temporossHudLoaded()
	{
		return client.getWidget(InterfaceID.TemporossHud.CONTENT) != null;
	}

	private String widgetText(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget == null ? null : widget.getText();
	}

	/**
	 * Client thread, once per logged-in tick: Tempoross permits earned and
	 * game provenance (see TemporossGameTracker). Two varbit reads and one
	 * widget lookup, only inside the Tempoross location.
	 */
	void trackTemporossTick()
	{
		boolean inTempoross = StructuredActivityCatalog.TEMPOROSS.equals(lastActivityKey);
		int gained = inTempoross
			? temporossTracker.onTick(true, temporossHudLoaded(), client.getVarbitValue(VarbitID.TEMPOROSS_CURRENT_POINTS),
				client.getVarbitValue(VarbitID.TEMPOROSS_REWARDPERMITS))
			: temporossTracker.onTick(false, false, 0, 0);
		if (gained > 0)
		{
			eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_CURRENCY,
				new EventPayloads.StructuredActivityCurrency(StructuredActivityCatalog.TEMPOROSS, "reward_permits", gained,
					client.getVarbitValue(VarbitID.TEMPOROSS_REWARDPERMITS)));
		}
	}

	private void setTemporossGame(TemporossGameState state)
	{
		if (Objects.equals(state, temporossGame))
		{
			return;
		}
		temporossGame = state;
		notifyProgressListener();
	}

	/** The current Guardians of the Rift game as the game's HUD reports it, or null when not in a game. */
	public GotrGameState getGotrGame()
	{
		return gotrGame;
	}

	/**
	 * GotR HUD update script (5980): the Great Guardian's current / maximum
	 * power are its arguments 3 and 4 (layout corroborated by two independent
	 * Plugin Hub plugins; evidence only -- none is used). Read from the
	 * arguments, never from the HUD's power TEXT, which other plugins are
	 * known to overwrite. Every other script returns at once.
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != GOTR_HUD_UPDATE_SCRIPT || event.getScriptEvent() == null)
		{
			return;
		}
		onGotrHudScript(event.getScriptEvent().getArguments());
	}

	void onGotrHudScript(Object[] args)
	{
		Integer current = intArg(args, GOTR_SCRIPT_ARG_CURRENT_POWER);
		Integer max = intArg(args, GOTR_SCRIPT_ARG_MAX_POWER);
		if (current == null || max == null)
		{
			return;
		}
		gotrPowerCurrent = current;
		gotrPowerMax = max;
		gotrActiveElemental = GotrAltar.of(GotrAltar.Type.ELEMENTAL, intArg(args, GOTR_SCRIPT_ARG_ACTIVE_ELEMENTAL));
		gotrActiveCatalytic = GotrAltar.of(GotrAltar.Type.CATALYTIC, intArg(args, GOTR_SCRIPT_ARG_ACTIVE_CATALYTIC));
		if (gotrGameEnded)
		{
			// The ended game's power drops to 0; the next game's rises from it.
			if (current <= 0)
			{
				gotrEndedPowerReset = true;
			}
			else if (gotrEndedPowerReset)
			{
				gotrGameEnded = false;
				gotrEndedPowerReset = false;
			}
		}
	}

	static Integer intArg(Object[] args, int index)
	{
		if (args == null || index < 0 || index >= args.length || args[index] == null)
		{
			return null;
		}
		Object v = args[index];
		if (v instanceof Integer)
		{
			return (Integer) v;
		}
		try
		{
			return Integer.parseInt(v.toString().trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private boolean gotrHudLoaded()
	{
		return client.getWidget(InterfaceID.GotrHud.CONTENT) != null;
	}

	/**
	 * Client thread, once per logged-in tick: the GotR current game (see the
	 * gotrGame field's STABILITY note), final-energy provenance, a pending
	 * win line's corroboration window, the Rewards Guardian "Check" message
	 * box, and the crafting-candidate window. Two varbit reads, at most two
	 * widget lookups, and an altar-eligibility read only when the open rifts
	 * change (cached).
	 */
	void trackGotrTick()
	{
		int tick = client.getTickCount();
		boolean hudLoaded = gotrHudLoaded();
		boolean playing = client.getVarbitValue(VarbitID.GOTR_IS_PLAYING) == 1;
		// Crafting context: the game HUD, the game's own "playing" varbit, or
		// the GotR location -- the altars are outside the temple region, so
		// the HUD/varbit (not the region) is what covers an altar trip.
		gotrContext = hudLoaded || playing || StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(lastActivityKey);
		gotrRunes.onTick(tick);
		if (gotrPendingWinTick != null && tick - gotrPendingWinTick >= GOTR_WIN_CORROBORATION_TICKS)
		{
			// "Successfully closed the rift" with no count line after it.
			recordGotrWin(null);
		}
		if (hudLoaded || playing)
		{
			gotrLastInGameTick = tick;
		}
		else if (gotrLastInGameTick == null || tick - gotrLastInGameTick > GOTR_IN_GAME_GRACE_TICKS)
		{
			// Really out of the game: nothing is kept.
			gotrLastInGameTick = null;
			gotrPowerCurrent = null;
			gotrPowerMax = null;
			gotrActiveElemental = null;
			gotrActiveCatalytic = null;
			setGotrGame(null);
			return;
		}
		else
		{
			// A short gap (region load): keep the last known game as it is.
			return;
		}
		int elemental = client.getVarbitValue(VarbitID.GOTR_ELEMENTAL_EARNED_THIS_GAME);
		int catalytic = client.getVarbitValue(VarbitID.GOTR_CATALYTIC_EARNED_THIS_GAME);
		gotrTracker.onEnergy(elemental, catalytic);
		if (gotrGameEnded)
		{
			setGotrGame(null);
		}
		else
		{
			setGotrGame(GotrGameState.of(GotrGameState.powerPercent(gotrPowerCurrent, gotrPowerMax), elemental, catalytic,
				gotrActiveElemental, gotrActiveCatalytic, altarUsable(gotrActiveElemental), altarUsable(gotrActiveCatalytic),
				talismanCandidates()));
		}
		if (hudLoaded && StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(lastActivityKey))
		{
			// Rewards Guardian "Check" answer, if its message box is up: baseline only.
			gotrPoints.onCheckText(widgetText(InterfaceID.Messagebox.TEXT));
			refreshGotrWallet();
		}
	}

	/** Held portal talismans -> whether this player can use that altar (cached eligibility); empty when none. */
	private Map<GotrAltar, Boolean> talismanCandidates()
	{
		if (gotrTalismans.isEmpty())
		{
			return java.util.Collections.emptyMap();
		}
		Map<GotrAltar, Boolean> out = new java.util.EnumMap<>(GotrAltar.class);
		for (GotrAltar altar : gotrTalismans)
		{
			out.put(altar, altarUsable(altar));
		}
		return out;
	}

	private void setGotrGame(GotrGameState state)
	{
		if (Objects.equals(state, gotrGame))
		{
			return;
		}
		gotrGame = state;
		notifyProgressListener();
	}

	/** Runecraft XP corroborates a GotR altar craft (see ProductionTracker). */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.RUNECRAFT)
		{
			return;
		}
		emitProduction(gotrRunes.onSkillXp(event.getXp(), client.getTickCount()));
	}

	/** RUNES CRAFTED: one confirmed GotR altar craft's exact rune output. */
	private void emitProduction(Map<Integer, Long> produced)
	{
		if (produced == null || produced.isEmpty())
		{
			return;
		}
		List<EventPayloads.ProducedItem> items = new ArrayList<>(produced.size());
		for (Map.Entry<Integer, Long> e : produced.entrySet())
		{
			items.add(new EventPayloads.ProducedItem(e.getKey(), itemNames.apply(e.getKey()),
				(int) Math.min(Integer.MAX_VALUE, e.getValue())));
		}
		eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_PRODUCTION,
			new EventPayloads.StructuredActivityProduction(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT, items));
	}

	/** Brother-killed varbits only; every other varbit change is ignored at once. */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (BarrowsBrother.forKilledVarbit(event.getVarbitId()) != null)
		{
			readBarrowsProgress();
		}
		else if (GotrRunes.isRunePouchVarbit(event.getVarbitId()))
		{
			// Crafted runes of a type the pouch holds go straight into it.
			observeRunePouch();
		}
	}

	/**
	 * RUNES CRAFTED, second destination: the rune pouch (also the divine
	 * rune pouch -- same varbits), read natively from its slot varbits.
	 * Twelve varbit reads; only output deltas correlated with a confirmed
	 * craft ever count (see ProductionTracker).
	 */
	private void observeRunePouch()
	{
		emitProduction(gotrRunes.onSecondaryStore(readRunePouch(), client.getTickCount(), gotrContext));
	}

	Map<Integer, Long> readRunePouch()
	{
		return GotrRunes.readRunePouch(client::getVarbitValue, runePouchRuneItem);
	}

	private int runePouchRuneItemFromEnum(int type)
	{
		net.runelite.api.EnumComposition runes = client.getEnum(net.runelite.api.EnumID.RUNEPOUCH_RUNE);
		return runes == null ? -1 : runes.getIntValue(type);
	}

	/** Test seam: the pouch slot type -> rune item mapping (the game enum is not available headless). */
	void setRunePouchRuneItem(java.util.function.IntUnaryOperator mapping)
	{
		this.runePouchRuneItem = mapping;
	}

	/** Client thread: re-reads all six brother varbits (cheap) and publishes a change. */
	void readBarrowsProgress()
	{
		setBarrowsProgress(BarrowsRunProgress.read(client::getVarbitValue));
	}

	/** The current Barrows run as the game reports it, or null when unknown (not read yet / logged out). */
	public BarrowsRunProgress getBarrowsProgress()
	{
		return barrowsProgress;
	}

	/** Called (client thread) whenever the mirrored activity progress changes; UI invalidation only. */
	public void setProgressListener(Runnable listener)
	{
		this.progressListener = listener;
	}

	private void setBarrowsProgress(BarrowsRunProgress progress)
	{
		if (Objects.equals(progress, barrowsProgress))
		{
			return;
		}
		barrowsProgress = progress;
		notifyProgressListener();
	}

	private void notifyProgressListener()
	{
		Runnable listener = progressListener;
		if (listener != null)
		{
			try
			{
				listener.run();
			}
			catch (RuntimeException e)
			{
				// Presentation only: never let the UI affect collection.
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickClaimWindow();
		if (barrowsProgress == null && client.getGameState() == GameState.LOGGED_IN)
		{
			// First read after login / enable: the varbits are already synced,
			// so a run in progress shows its real brothers at once.
			readBarrowsProgress();
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		LocalPoint local = player.getLocalLocation();
		if (local == null)
		{
			return;
		}
		WorldPoint template = WorldPoint.fromLocalInstance(client, local);
		if (template == null)
		{
			return;
		}
		onRegion(template.getRegionID());
		readTemporossGame();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			trackTemporossTick();
			trackGotrTick();
		}
	}

	/** Region -> at most one STRUCTURED_ACTIVITY_STATE, only when the resolved activity/policy changes. */
	void onRegion(int regionId)
	{
		if (regionId == lastRegionId)
		{
			return;
		}
		boolean firstObservation = lastRegionId == NO_REGION;
		lastRegionId = regionId;

		StructuredActivityDefinition def = registry.forRegion(regionId);
		String key = def == null ? null : def.getKey();
		LocationPolicy policy = def == null ? null : def.policyFor(regionId);
		boolean changed = !Objects.equals(key, lastActivityKey) || policy != lastPolicy;
		lastActivityKey = key;
		lastPolicy = policy;
		// Outside on the first observation: nothing to disarm, nothing to say.
		if (!changed || (firstObservation && key == null))
		{
			return;
		}
		lastAccountHash = client.getAccountHash();
		eventLedger.append(lastAccountHash, EventType.STRUCTURED_ACTIVITY_STATE,
			new EventPayloads.StructuredActivityState(key, policy == null ? null : policy.name(), regionId));
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.MESBOX)
		{
			return;
		}
		onGameMessage(Text.removeTags(event.getMessage()));
	}

	void onGameMessage(String message)
	{
		TemporossGameTracker.Result game = temporossTracker.onGameMessage(message, client.getVarbitValue(VarbitID.TEMPOROSS_CURRENT_POINTS));
		if (game != null)
		{
			// The completion itself arrives as BOSS_KILL ("Tempoross"); this is
			// only that game's final score, for Avg / Best.
			eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_SCORE,
				new EventPayloads.StructuredActivityScore(StructuredActivityCatalog.TEMPOROSS, game.getKillCount(), game.getPoints(),
					game.isObservedFromStart()));
		}
		onGotrGameMessage(message);
		StructuredRewardSource claim = registry.rewardForClaimMessage(message, lastRegionId);
		if (claim != null)
		{
			if (StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(claim.getActivityKey()))
			{
				// A Rewards Guardian search spends one point of each.
				gotrPoints.onSearch();
				refreshGotrWallet();
			}
			armClaim(claim, itemsOf(client.getItemContainer(InventoryID.INV)));
			return;
		}
		StructuredActivityRegistry.ChatCompletion match = registry.matchCompletionChat(message);
		if (match == null)
		{
			return;
		}
		String key = match.getDefinition().getKey();
		Integer count = match.getCount();
		if (StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(key))
		{
			onGotrRiftsClosed(count);
			return;
		}
		if (count != null)
		{
			Integer previous = lastCompletionCount.get(key);
			if (previous != null && count <= previous)
			{
				return;
			}
			lastCompletionCount.put(key, count);
		}
		else
		{
			// No running count to dedupe on (Pest Control): the same text
			// reaching us through two accepted chat types for one game must
			// not become two games.
			int tick = client.getTickCount();
			Integer previousTick = lastCountlessCompletionTick.get(key);
			if (previousTick != null && tick - previousTick >= 0 && tick - previousTick <= COUNTLESS_COMPLETION_DEDUPE_TICKS)
			{
				return;
			}
			lastCountlessCompletionTick.put(key, tick);
		}
		eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_COMPLETION,
			new EventPayloads.StructuredActivityCompletion(key, count, "CHAT"));
	}

	/**
	 * "Amount of rifts you have closed: N." -- a WON game, exactly once: a
	 * repeat of the same count (two chat types, a re-delivered line) is
	 * ignored, and a count arriving after its "successfully closed" line
	 * already stood in for it only records the count.
	 */
	private void onGotrRiftsClosed(Integer count)
	{
		String key = StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT;
		if (count != null)
		{
			Integer previous = lastCompletionCount.get(key);
			if (previous != null && count <= previous)
			{
				return;
			}
			lastCompletionCount.put(key, count);
		}
		if (gotrCountlessWinTick != null && client.getTickCount() - gotrCountlessWinTick <= GOTR_IN_GAME_GRACE_TICKS)
		{
			// This game was already counted from its "successfully closed" line.
			gotrCountlessWinTick = null;
			return;
		}
		recordGotrWin(count);
	}

	/** One won game: its final energy for Avg / Best, then the completion that counts it. */
	private void recordGotrWin(Integer count)
	{
		String key = StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT;
		gotrPendingWinTick = null;
		gotrCountlessWinTick = count == null ? client.getTickCount() : null;
		GotrGameTracker.Result won = gotrTracker.onCompletion(count,
			client.getVarbitValue(VarbitID.GOTR_ELEMENTAL_EARNED_THIS_GAME),
			client.getVarbitValue(VarbitID.GOTR_CATALYTIC_EARNED_THIS_GAME));
		eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_SCORE,
			new EventPayloads.StructuredActivityScore(key, won.getRiftsClosed(), won.getTotalEnergy(), won.isObservedFromStart()));
		eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_COMPLETION,
			new EventPayloads.StructuredActivityCompletion(key, count, "CHAT"));
		endGotrGame();
	}

	/** GotR win / failure lines, end-of-game reward points, and the "Check" answer if it reaches chat. */
	void onGotrGameMessage(String message)
	{
		if (GotrGameTracker.isFailure(message) || GotrGameTracker.isNoContribution(message))
		{
			// Lost, or closed without crediting this player: not a game won,
			// and it cancels a "successfully closed" line still waiting.
			gotrTracker.onFailure();
			gotrPendingWinTick = null;
			endGotrGame();
			return;
		}
		if (GotrGameTracker.isWin(message))
		{
			// Corroborates the count line that follows on the same tick; stands
			// in for it only if it never comes (see trackGotrTick).
			if (gotrPendingWinTick == null)
			{
				gotrPendingWinTick = client.getTickCount();
			}
			return;
		}
		if (gotrPoints.onCheckText(message))
		{
			refreshGotrWallet();
			return;
		}
		GotrRewardPointTracker.Gains gains = gotrPoints.onGameMessage(message);
		refreshGotrWallet();
		if (gains == null)
		{
			return;
		}
		if (gains.getElementalGained() > 0)
		{
			eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_CURRENCY,
				new EventPayloads.StructuredActivityCurrency(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT,
					GOTR_ELEMENTAL_POINTS, gains.getElementalGained(), gains.getElementalBalance()));
		}
		if (gains.getCatalyticGained() > 0)
		{
			eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_ACTIVITY_CURRENCY,
				new EventPayloads.StructuredActivityCurrency(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT,
					GOTR_CATALYTIC_POINTS, gains.getCatalyticGained(), gains.getCatalyticBalance()));
		}
	}

	public static final String GOTR_ELEMENTAL_POINTS = "elemental_points";
	public static final String GOTR_CATALYTIC_POINTS = "catalytic_points";

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		StructuredRewardSource reward = registry.rewardForInterface(event.getGroupId());
		if (reward == null)
		{
			return;
		}
		onRewardInterface(reward, itemsOf(client.getItemContainer(reward.getContainerId())), itemNames);
	}

	/** REWARD_INTERFACE producer: the container's exact contents are the reward. */
	void onRewardInterface(StructuredRewardSource reward, Map<Integer, Long> containerItems, IntFunction<String> itemName)
	{
		emitReward(reward, containerItems, itemName);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		Map<Integer, Long> inventory = itemsOf(event.getItemContainer());
		// The pouch is read first so its baseline exists before any craft
		// (it may not have changed since login).
		observeRunePouch();
		// Portal talismans held: extra altars the player can enter (STRATEGY).
		gotrTalismans = GotrPortalTalismans.heldIn(inventory);
		// RUNES CRAFTED: guardian essence consumed + runes gained, in the GotR
		// game (HUD loaded) -- confirmed by Runecraft XP (ProductionTracker).
		emitProduction(gotrRunes.onInventory(inventory, client.getTickCount(), gotrContext));
		if (pendingClaim == null)
		{
			return;
		}
		onInventoryChanged(inventory, itemNames);
	}

	/**
	 * CLAIM_MESSAGE producer, second half: the ONE inventory change after an
	 * armed claim is consumed -- whatever it added (possibly nothing) -- and
	 * the correlation disarms.
	 */
	void onInventoryChanged(Map<Integer, Long> inventory, IntFunction<String> itemName)
	{
		StructuredRewardSource reward = pendingClaim;
		if (reward == null)
		{
			return;
		}
		Map<Integer, Long> added = new LinkedHashMap<>();
		for (Map.Entry<Integer, Long> e : inventory.entrySet())
		{
			long before = claimSnapshot.getOrDefault(e.getKey(), 0L);
			if (e.getValue() > before)
			{
				added.put(e.getKey(), e.getValue() - before);
			}
		}
		disarmClaim();
		emitReward(reward, added, itemName);
	}

	/** CLAIM_MESSAGE producer, first half: arm (or keep) the correlation for this source. */
	void armClaim(StructuredRewardSource reward, Map<Integer, Long> inventoryNow)
	{
		if (pendingClaim != reward)
		{
			pendingClaim = reward;
			claimSnapshot = new HashMap<>(inventoryNow);
		}
		claimTicksLeft = CLAIM_WINDOW_TICKS;
	}

	/** One game tick of the claim window; an unanswered claim expires silently. */
	void tickClaimWindow()
	{
		if (pendingClaim != null && --claimTicksLeft <= 0)
		{
			disarmClaim();
		}
	}

	boolean isClaimArmed()
	{
		return pendingClaim != null;
	}

	private void disarmClaim()
	{
		pendingClaim = null;
		claimSnapshot = new HashMap<>();
		claimTicksLeft = 0;
	}

	private void emitReward(StructuredRewardSource reward, Map<Integer, Long> items, IntFunction<String> itemName)
	{
		if (items.isEmpty())
		{
			return;
		}
		List<EventPayloads.StructuredRewardItem> payloadItems = new ArrayList<>(items.size());
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			payloadItems.add(new EventPayloads.StructuredRewardItem(e.getKey(), itemName.apply(e.getKey()), (int) Math.min(Integer.MAX_VALUE, e.getValue())));
		}
		eventLedger.append(client.getAccountHash(), EventType.STRUCTURED_REWARD,
			new EventPayloads.StructuredReward(reward.getActivityKey(), reward.getKey(), reward.getDisplayName(), payloadItems));
	}

	/** Item id -> total quantity, first-seen order; empty slots skipped. */
	static Map<Integer, Long> itemsOf(ItemContainer container)
	{
		Map<Integer, Long> items = new LinkedHashMap<>();
		if (container == null)
		{
			return items;
		}
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				items.merge(item.getId(), (long) item.getQuantity(), Long::sum);
			}
		}
		return items;
	}

	private void forgetLocation()
	{
		lastRegionId = NO_REGION;
		lastActivityKey = null;
		lastPolicy = null;
	}
}

package com.osrstelemetry.plugin.events;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.UUID;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Append-only, one JSON object per line, per account.
 *
 * Same two fixes as LocalStateStore, for the same reasons (see its
 * javadoc): the envelope (including the payload) is built and
 * serialized to a String synchronously in append(), before handing
 * off to the background executor — a payload object's fields are
 * final/immutable by construction (see EventPayloads), but building
 * the JSON string synchronously means there is never a window where a
 * caller could observe or mutate anything after the fact and get a
 * different result than what's on disk. start()/shutdown() are
 * explicit lifecycle methods rather than constructor/finalizer, so
 * enable -> disable -> enable within one client process gets a fresh
 * working executor every time instead of reusing a shut-down one.
 */
@Slf4j
@Singleton
public class EventLedger
{
	private final Gson gson;
	private ExecutorService executor;
	private volatile String sessionId = UUID.randomUUID().toString();

	@Inject
	public EventLedger(Gson gson)
	{
		this.gson = gson;
	}

	// See TelemetryEventListener's javadoc for the full contract.
	// CopyOnWriteArrayList: registration/
	// unregistration (plugin enable/disable) is rare, notification (every
	// append()) is frequent -- optimizing the common case for lock-free
	// reads, matching this project's existing preference for simple,
	// well-understood concurrency primitives over anything bespoke.
	private final List<TelemetryEventListener> listeners = new CopyOnWriteArrayList<>();

	/**
	 * Registration must be paired with removeListener() on plugin
	 * disable/shutDown() -- this list is NOT cleared by start()/
	 * shutdown() (those only manage the write executor), so a caller
	 * that adds itself again on every re-enable without ever removing
	 * itself would silently accumulate duplicate listeners and receive
	 * every event more than once. This is the exact same class of bug
	 * the client-thread lifecycle audit found and fixed for EventBus
	 * registration -- see OsrsTelemetryPlugin's own startUp()/shutDown()
	 * pairing for the established, already-correct pattern to mirror.
	 */
	public void addListener(TelemetryEventListener listener)
	{
		listeners.add(listener);
	}

	public void removeListener(TelemetryEventListener listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Synchronous, on the calling thread, by design -- see
	 * TelemetryEventListener's javadoc. Every listener is isolated from
	 * every other and from the durable write: an ordinary listener
	 * failure is logged and swallowed here, never allowed to prevent or
	 * corrupt the append this notification accompanies ("session routing
	 * failure must not corrupt/drop the durable telemetry event").
	 *
	 * FAILURE-ISOLATION CONTRACT: this is the ONLY boundary in
	 * this class that separates a telemetry COLLECTOR (the caller of
	 * append()/appendAndWait(), e.g. SkillsCollector, ContainerCollector)
	 * from a session-runtime LISTENER (e.g. SessionRuntimeCoordinator).
	 * A broken listener must not be able to unwind into an unrelated
	 * collector's own control flow -- that includes both RuntimeException
	 * AND AssertionError (a real, previously-observed failure mode in
	 * this project's RuneLite development, and NOT a RuntimeException),
	 * so both are caught and isolated below.
	 *
	 * This does NOT extend to genuine JVM-fatal conditions --
	 * VirtualMachineError (OutOfMemoryError, StackOverflowError, and
	 * their siblings) and ThreadDeath. An earlier pass caught
	 * `Throwable` unconditionally, which was too broad: silently
	 * swallowing a condition that means the JVM itself is dying (or a
	 * thread is being deliberately, cooperatively stopped via
	 * ThreadDeath) hides a failure this method has no ability to
	 * meaningfully isolate or recover from, and every other component
	 * sharing this same JVM is about to be affected by it regardless of
	 * what this catch block does. Those conditions are deliberately
	 * re-thrown -- allowed to propagate out of notifyListeners() and out
	 * of append()/appendAndWait() -- rather than logged and suppressed.
	 * This is the standard "catch broadly, but never swallow VM-fatal
	 * conditions" idiom: `catch (Throwable t)` combined with an explicit
	 * rethrow for the fatal subset, since Java's multi-catch syntax
	 * cannot express "Throwable except VirtualMachineError/ThreadDeath"
	 * directly.
	 *
	 * Rethrowing here does not put the already-durably-accepted write at
	 * risk: by the time notifyListeners() runs, the write has already
	 * been submitted to the single-writer executor (see append()'s/
	 * appendAndWait()'s own ordering comments) -- an Error propagating
	 * out of this method at that point can no longer cancel, prevent, or
	 * otherwise affect that already-submitted durable write; it only
	 * affects whether THIS method call returns normally to its caller.
	 */
	private void notifyListeners(long accountHash, EventType type, Object payload, Instant observedAt, String eventId)
	{
		for (TelemetryEventListener listener : listeners)
		{
			try
			{
				listener.onEvent(accountHash, type, payload, observedAt, eventId);
			}
			catch (VirtualMachineError | ThreadDeath fatal)
			{
				// Genuine JVM-fatal conditions are never swallowed --
				// see the class-level rationale above. Deliberately
				// rethrown before the broader catch below can absorb it.
				throw fatal;
			}
			catch (Throwable t)
			{
				// Everything else -- ordinary RuntimeExceptions AND
				// AssertionError -- is isolated here. This runs AFTER the
				// durable write has already been accepted (see append()/
				// appendAndWait()), so nothing caught here can still
				// reach back and prevent/cancel/corrupt that acceptance.
				log.warn("Telemetry event listener threw while handling {}; durable write is unaffected", type, t);
			}
		}
	}

	public synchronized void start()
	{
		if (executor != null && !executor.isShutdown())
		{
			return;
		}
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-event-ledger");
			t.setDaemon(true);
			return t;
		});
	}

	/**
	 * A "session" is one run of the client with this plugin active,
	 * not one game-account login — see plugin startUp(). Also called
	 * on an account switch (see AccountContext) so events from
	 * different accounts in the same client run never share a
	 * sessionId.
	 */
	public void startNewSession()
	{
		sessionId = UUID.randomUUID().toString();
	}

	public void append(long accountHash, EventType type, Object payload)
	{
		ExecutorService executor = this.executor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("append() called while EventLedger is not started; dropping event {}", type);
			return;
		}

		Instant observedAt = Instant.now();
		String eventId = UUID.randomUUID().toString();
		String json = buildEnvelopeJson(eventId, accountHash, type, payload, observedAt);

		// Durable acceptance FIRST, structurally -- see class-level
		// ordering note above. If this event isn't even accepted for a
		// durable write, listeners are never told about it either.
		try
		{
			executor.submit(() -> appendNow(accountHash, json));
		}
		catch (RejectedExecutionException e)
		{
			log.warn("append() rejected while EventLedger is shutting down; dropping event {}", type);
			return;
		}

		notifyListeners(accountHash, type, payload, observedAt, eventId);
	}

	/**
	 * Synchronous/waitable counterpart to append(), for shutdown-critical
	 * callers that must know an event actually reached disk before they
	 * can safely return -- e.g. ContainerCollector.finalizeBankSnapshotBlocking().
	 * The fire-and-forget append() above relies on shutdown()'s graceful
	 * drain, which is not guaranteed to complete an append still
	 * queued-but-not-yet-run when shutdown() tears the executor down --
	 * this method removes that reliance entirely for the one call site
	 * that cannot tolerate it.
	 *
	 * Builds and serializes the IDENTICAL TelemetryEvent envelope
	 * append() does -- same fresh random eventId, the ledger's current
	 * sessionId, same schema/payload shape, same Gson serializer -- and
	 * submits it through the SAME single-writer executor, so ordering
	 * relative to every other append()/appendAndWait() call is fully
	 * preserved (this is not a second, parallel write path). The only
	 * difference is that the calling thread then blocks (bounded by
	 * timeoutMs) until that specific submitted write has actually run
	 * and reports its own success/failure, instead of returning the
	 * instant the task is merely queued.
	 *
	 * This is deliberately NOT a replacement for append() in ordinary
	 * gameplay event handling -- it exists only for the narrow set of
	 * callers (currently: shutdown-time bank finalization) that cannot
	 * proceed without a durable answer.
	 *
	 * @return true only if this specific event was confirmed written to
	 * disk before timeoutMs elapsed. false covers every other outcome
	 * -- not started, rejected because shutdown is already underway,
	 * a genuine write failure, a timeout, or this thread being
	 * interrupted while waiting -- and callers must treat all of them
	 * identically: the event did not durably happen, full stop.
	 */
	public boolean appendAndWait(long accountHash, EventType type, Object payload, long timeoutMs)
	{
		ExecutorService executor = this.executor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("appendAndWait() called while EventLedger is not started; dropping event {}", type);
			return false;
		}

		Instant observedAt = Instant.now();
		String eventId = UUID.randomUUID().toString();
		String json = buildEnvelopeJson(eventId, accountHash, type, payload, observedAt);

		// EXACT ENFORCED ORDER: (1) submit the durable write --
		// durably ACCEPTED onto the single-writer executor; (2)
		// synchronous listener notification, on this calling thread,
		// isolated per-listener by notifyListeners()'s own Throwable
		// catch; (3) THEN, and only then, wait (bounded by timeoutMs) for
		// the durable future submitted in step (1) to actually complete.
		// The durable future's own success/failure was already decided
		// independently back in step (1) -- it does not depend on
		// listener success in any way -- but this method, being
		// synchronous, still executes all of step (2)'s listener work
		// before it ever reaches step (3)'s durability wait. A slow or
		// misbehaving listener therefore delays how soon THIS caller
		// observes the durability result, even though it can never change
		// what that result is.
		Future<Boolean> future;
		try
		{
			future = executor.submit(() -> appendNow(accountHash, json));
		}
		catch (RejectedExecutionException e)
		{
			log.warn("appendAndWait() rejected while EventLedger is shutting down; dropping event {}", type);
			return false;
		}

		notifyListeners(accountHash, type, payload, observedAt, eventId);

		try
		{
			return Boolean.TRUE.equals(future.get(timeoutMs, TimeUnit.MILLISECONDS));
		}
		catch (InterruptedException e)
		{
			log.warn("appendAndWait() interrupted while waiting to append {}; treating as not durably written", type);
			return false;
		}
		catch (ExecutionException | TimeoutException e)
		{
			log.warn("appendAndWait() failed or timed out appending {}", type, e);
			return false;
		}
	}

	/**
	 * Shared envelope construction for append()/appendAndWait() --
	 * factored out so the two entry points can never drift in
	 * sessionId/eventId/schema semantics from one another. Building
	 * and serializing here, synchronously on the calling thread before
	 * either method touches the executor, mirrors this class's
	 * existing documented discipline (see class javadoc).
	 */
	private String buildEnvelopeJson(String eventId, long accountHash, EventType type, Object payload, Instant observedAt)
	{
		TelemetryEvent event = new TelemetryEvent(
			eventId,
			Long.toString(accountHash),
			type,
			observedAt.toString(),
			sessionId,
			payload
		);
		return gson.toJson(event);
	}

	/** @return true if this event line was successfully and durably
	 * appended to disk. */
	private boolean appendNow(long accountHash, String json)
	{
		try
		{
			TelemetryPaths.eventsFile(accountHash).write(
				(json + System.lineSeparator()).getBytes(StandardCharsets.UTF_8),
				StandardOpenOption.CREATE, StandardOpenOption.APPEND
			);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Failed appending telemetry event for account {}", accountHash, e);
			return false;
		}
	}

	/**
	 * Graceful drain — same reasoning as LocalStateStore.shutdown().
	 */
	public void shutdown()
	{
		ExecutorService executor = this.executor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("EventLedger writer did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the EventLedger writer; leaving it to keep draining in the background");
		}
	}
}

package com.osrstelemetry.plugin.events;

import lombok.Data;

/**
 * Bundled in one file (rather than one file per payload, unlike the
 * model/ package) because these are pure inert data shapes with no
 * behavior — splitting them wouldn't aid readability, just add file
 * count. Each mirrors a payload example from the telemetry schema.
 */
public final class EventPayloads
{
	private EventPayloads()
	{
	}

	@Data
	public static class XpChange
	{
		private final String skill;
		private final int previousXp;
		private final int newXp;
		private final int delta;
		private final String windowStart;
		private final String windowEnd;
	}

	@Data
	public static class LevelUp
	{
		private final String skill;
		private final int previousLevel;
		private final int newLevel;
		private final int xp;
	}

	@Data
	public static class QuestCompleted
	{
		private final int questId;
		private final String questKey;
		private final String questName;
	}

	@Data
	public static class CombatAchievementCompleted
	{
		private final String tier;
		private final String taskName;
	}

	/**
	 * itemId is null here — see CollectionLogCollector javadoc, the
	 * chat message this is built from doesn't carry an item ID and I'm
	 * not resolving name->ID by guessing. Fill this in once the
	 * full-page widget read (still unimplemented) provides a real
	 * source for it.
	 */
	@Data
	public static class CollectionLogNewItem
	{
		private final Integer itemId;
		private final String itemName;
	}

	/**
	 * Renamed from LootDrop/LOOT_DROP. Built from
	 * net.runelite.client.events.NpcLootReceived, produced by
	 * net.runelite.client.game.LootManager, which attributes an
	 * item stack to an NPC by pure tile + same-game-tick correlation to
	 * the NPC's despawn (LootManager.onItemSpawned() adds every
	 * ItemSpawned to a per-tile map unconditionally;
	 * getItemStacksFromAreas() then just reads whatever TileItem(s) are
	 * on the death tile(s), converting by id+quantity only —
	 * TileItem#getOwnership()/isPrivate() are never read anywhere in
	 * that file). This does NOT prove the item was awarded to or owned
	 * by the local player specifically — it can genuinely include
	 * another visible player's drop sharing the same tile in the same
	 * tick. Hence the field/class name change from "Drop" (which reads
	 * as "my loot") to "LootAttributed" (RuneLite's attribution of an
	 * observed stack to an NPC, nothing stronger). See
	 * NpcDeathCollector's own class javadoc for the full source-audit
	 * evidence, including why the newer, likely
	 * player-owned-loot-capable net.runelite.client.events.ServerNpcLoot
	 * was deliberately NOT switched to as this event's source.
	 *
	 * No field on this payload claims local-player ownership, kill
	 * attribution, or Slayer-task attribution — sourceType/sourceName/
	 * sourceId identify the NPC RuneLite attributed the stack to;
	 * itemId/itemName/quantity identify the item stack itself. Nothing
	 * here was renamed at the field level (no field ever claimed
	 * ownership) — only the class/event name, which previously implied
	 * more than the source proves.
	 */
	@Data
	public static class NpcLootAttributed
	{
		private final String sourceType;
		private final String sourceName;
		private final int sourceId;
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}

	@Data
	public static class BossKill
	{
		private final String activityId;
		private final String displayName;
		private final int killCount;
		private final String source;
	}

	/**
	 * Backs EventType.BOSS_ACTIVITY_CONTEXT -- see that constant's javadoc for
	 * the full source audit and the reason this is deliberately
	 * NON-authoritative. Intentionally a single-field payload:
	 * bossName is the canonical boss display name KnownBossRegistry
	 * resolved (already alias-mapped, e.g. "Dawn" -> "Grotesque
	 * Guardians" -- never the raw, un-resolved NPC name). No
	 * reliableCount/killCount field exists here, unlike BossKill --
	 * this payload structurally cannot carry kill-count authority.
	 */
	@Data
	public static class BossActivityContext
	{
		private final String bossName;
	}

	@Data
	public static class RaidCompletion
	{
		private final String activityId;
		private final String displayName;
		private final int completionCount;
		private final String source;
	}

	/**
	 * Everything that prints a "completion count" line but is NOT one
	 * of the three verified raids (see ActivityKillCountCollector's
	 * RAID_IDS) — Corrupted Gauntlet, minigames, and any other
	 * activity with a completion counter. Kept schema-identical to
	 * RaidCompletion deliberately (same fields) so downstream summary
	 * code can treat them uniformly if it wants to, while the event
	 * TYPE itself still keeps "raid" meaning something specific rather
	 * than "any repeatable content with a counter".
	 */
	@Data
	public static class ActivityCompletion
	{
		private final String activityId;
		private final String displayName;
		private final int completionCount;
		private final String source;
	}

	@Data
	public static class SlayerTaskAssigned
	{
		private final String monster;
		private final int amount;
		private final String location;
		private final int masterId;
	}

	/** See EventType.SLAYER_BRACELET_EFFECT. effect: "SLAUGHTER" or "EXPEDITIOUS". */
	@Data
	public static class SlayerBraceletEffect
	{
		private final String effect;
	}

	@Data
	public static class SlayerTaskCompleted
	{
		private final String monster;
		private final int streak;
		private final String streakLabel;
		private final int points;
		/**
		 * True when the task was cleared WITHOUT being finished -- cancelled
		 * or blocked for Slayer points (points went down, the completed-tasks
		 * streak did not go up). Null (absent from the JSON) for a real
		 * completion and for every event written before this field existed.
		 */
		private Boolean cancelled;
	}

	/**
	 * Task IDENTITY fields (taskName/taskLocation) are included for correlation only
	 * — this event never fires across an identity change (see
	 * SlayerCollector.evaluateSlayerTransition()); it always describes
	 * the SAME assignment's count changing. initialAmount/masterId are
	 * included only because they're already known/available on the
	 * current observation when this fires (the task has amountRemaining
	 * > 0 in both cases progress is computed from) — never fabricated
	 * for an observation where they wouldn't naturally be present.
	 *
	 * Deliberately NOT a kill count: remainingDelta/taskUnitsConsumed
	 * describe the observed change in the task's remaining-count field,
	 * not a verified NPC death count — see EventType.SLAYER_TASK_PROGRESS's
	 * javadoc for why those aren't provably equivalent.
	 */
	@Data
	public static class SlayerTaskProgress
	{
		private final String taskName;
		private final String taskLocation;
		private final int previousRemaining;
		private final int currentRemaining;
		private final int remainingDelta;
		private final int taskUnitsConsumed;
		private final int initialAmount;
		private final int masterId;
	}

	/**
	 * Built from net.runelite.api.events.ActorDeath filtered to actor
	 * instanceof NPC — see NpcDeathCollector's class javadoc for the full
	 * signal selection audit.
	 *
	 * Renamed NpcKill -> NpcDeath (matching EventType.NPC_KILL ->
	 * NPC_DEATH): ActorDeath proves only that RuneLite observed this NPC
	 * die, never that the local player caused the death, received kill
	 * credit, or that the NPC counted toward an active Slayer
	 * assignment — "Kill" read as a player-attribution claim the source
	 * signal cannot back up. Nothing about the field set changed; only
	 * the class/event name, which previously implied more than the
	 * source proves.
	 *
	 * npcName/npcId are the primary NPC identity, read directly off the
	 * NPC object at the moment of death — never fabricated/defaulted.
	 * npcId is nullable: NPC#getId() is documented to be able to return
	 * -1 for an NPC with no valid composition (e.g. a mid-transform
	 * frame); when that happens this field is left null rather than
	 * storing a sentinel that looks like a real ID. combatLevel is
	 * similarly nullable for the same reason (Actor#getCombatLevel()
	 * gives no documented guarantee it always reflects a real NPC
	 * combat level in every case) — see NpcDeathCollector for exactly
	 * when each is left null.
	 *
	 * worldLocation is the actor's server-side WorldPoint (per
	 * Actor#getWorldLocation()'s own javadoc: "not affected by things
	 * such as animations," i.e. authoritative, not a render-position
	 * guess), serialized as "x,y,plane".
	 *
	 * activeSlayerTaskName/activeSlayerTaskLocation are a LIVE read of
	 * whatever Slayer assignment (if any) is active at the moment of
	 * this death — contextual metadata only, not a claim that the dead
	 * NPC belongs to that assignment, and not a claim that the local
	 * player caused this death. There is deliberately NO onSlayerTask
	 * boolean on this payload: no defensible RuneLite/Jagex mechanism
	 * was found for mapping a specific dead NPC to
	 * a specific active Slayer assignment (e.g. a random rat dying while
	 * Gargoyles is active must not read as a Slayer kill just because a
	 * task happens to be active) — see NpcDeathCollector's javadoc for
	 * the full reasoning. Both fields are null when no task is active.
	 */
	@Data
	public static class NpcDeath
	{
		private final String npcName;
		private final Integer npcId;
		private final Integer combatLevel;
		private final String worldLocation;
		private final String activeSlayerTaskName;
		private final String activeSlayerTaskLocation;
	}

	/**
	 * Pointer only, per the spec — no per-item diff event. itemCount
	 * is a cheap sanity signal for downstream consumers; the actual
	 * delta calculation is a backend job against the
	 * corresponding bank.json snapshot, not something computed here.
	 */
	@Data
	public static class BankSnapshot
	{
		private final String storageId;
		private final String snapshotId;
		private final int itemCount;
	}

	/**
	 * See EventType.SEED_VAULT_SNAPSHOT's javadoc for the full audit. Pointer
	 * only — deliberately mirrors BankSnapshot's shape minus snapshotId
	 * (Seed Vault has no immutable per-observation snapshot file the way
	 * Bank does).
	 * The real itemId+quantity+name list lives in seed_vault.json, not
	 * here — same "pointer, not a per-item diff event" precedent
	 * BankSnapshot already established.
	 */
	@Data
	public static class SeedVaultSnapshot
	{
		private final String storageId;
		private final int itemCount;
	}

	/**
	 * Backs EventType.SERVER_NPC_LOOT — see that enum constant's javadoc for
	 * the full source audit and naming rationale. Built from
	 * net.runelite.client.events.ServerNpcLoot (composition + items),
	 * after ServerNpcLootCollector's pickpocket-tick filter has already
	 * rejected the notification (a suppressed notification never
	 * reaches buildPayload() at all — see that collector).
	 *
	 * sourceId is nullable: NPCComposition#getId() carries no documented
	 * guarantee of always returning a real, usable value (mirroring the
	 * same "do not fabricate missing values" treatment
	 * NpcDeathCollector.buildPayload() already applies to NPC#getId()) —
	 * any non-positive raw id is left null rather than stored as a
	 * misleading not-actually-real id.
	 *
	 * items is a small typed list (ServerNpcLootItem), not an
	 * unstructured map, and deliberately preserves every item stack from
	 * one ServerNpcLoot notification together in one payload — this is
	 * what lets a future aggregation layer reconstruct one individual-
	 * drop record, source-grouped totals, and item-grouped totals within
	 * a source, all from this one event. No NPC instance/world-location
	 * field exists on this payload: ServerNpcLoot does not provide one
	 * (only NPCComposition, not a live NPC instance — see the enum
	 * javadoc), and none is fabricated here.
	 *
	 * Deliberately absent from this payload, by design (see
	 * EventType.SERVER_NPC_LOOT's independence rationale and
	 * ServerNpcLootCollector's class javadoc): any kill/death reference,
	 * any Slayer-task field, any "ownedByLocalPlayer"-style boolean.
	 * This payload states only what RuneLite's ServerNpcLoot event
	 * itself carries, nothing this project inferred on top of it.
	 */
	@Data
	public static class ServerNpcLoot
	{
		private final String sourceName;
		private final Integer sourceId;
		private final java.util.List<ServerNpcLootItem> items;
	}

	/**
	 * One item stack within a ServerNpcLoot notification. A small typed
	 * shape (itemId/itemName/quantity) rather than an unstructured
	 * map/array-pair, matching how every other multi-field payload in
	 * this file is represented. itemName is resolved the same way
	 * LootCollector already resolves NPC_LOOT_ATTRIBUTED item names
	 * (ItemManager#getItemComposition(itemId).getName()) — never
	 * fabricated when the lookup can't resolve.
	 */
	@Data
	public static class ServerNpcLootItem
	{
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}

	/**
	 * Backs EventType.NPC_INTERACTION_TARGET — see that constant's javadoc for
	 * the full source audit. npcName is read directly off the NPC's own
	 * (transformed) NPCComposition at interaction time — never
	 * fabricated/guessed, never looked up in any hand-maintained table.
	 * npcId mirrors NpcDeath.npcId's own nullability precedent (NPC#getId()
	 * is documented to be able to return -1 for an NPC with no valid
	 * composition, e.g. a mid-transform frame — left null rather than
	 * stored as a misleading not-actually-real id). No reliableCount/
	 * killCount/combat-proof field exists here, unlike BossKill — this
	 * payload structurally cannot carry kill or damage-attribution
	 * authority (see NpcInteractionTargetCollector — it only ever builds
	 * this payload after confirming the target NPC's composition/actions
	 * genuinely include "Attack", so this is never emitted for a
	 * banker/shopkeeper/other merely-talked-to NPC in the first place).
	 */
	@Data
	public static class NpcInteractionTarget
	{
		private final Integer npcId;
		private final String npcName;
	}

	/**
	 * See EventType.RAW_COMBAT_XP_OBSERVED's own javadoc. skillName is
	 * the RuneLite Skill enum's own name() (matching
	 * XpChange.skillName's own convention exactly) -- deliberately NO
	 * xp/delta/level field of any kind, so this payload is structurally
	 * incapable of ever being mistaken for or merged into an XP metric.
	 */
	@Data
	public static class RawCombatXpObserved
	{
		private final String skillName;
	}

	/** Backs EventType.STRUCTURED_ACTIVITY_STATE. activityKey/locationPolicy are null when outside. */
	@Data
	public static class StructuredActivityState
	{
		private final String activityKey;
		private final String locationPolicy;
		private final int regionId;
	}

	/** Backs EventType.STRUCTURED_ACTIVITY_COMPLETION. completionCount is the game's running count, or null. */
	@Data
	public static class StructuredActivityCompletion
	{
		private final String activityKey;
		private final Integer completionCount;
		private final String source;
	}

	/**
	 * Backs EventType.STRUCTURED_REWARD: one reward claim. sourceKey is the
	 * canonical reward-source id (activity.StructuredRewardSource#getKey --
	 * "barrows", "tempoross_reward_pool", ...), sourceName its player-facing
	 * name. No valuation: GP is presentation-time only. An event written by
	 * an earlier build may lack sourceKey; consumers canonicalize its
	 * sourceName through the registry's declared aliases, never by guessing.
	 */
	@Data
	public static class StructuredReward
	{
		private final String activityKey;
		private final String sourceKey;
		private final String sourceName;
		private final java.util.List<StructuredRewardItem> items;
	}

	/** Backs EventType.STRUCTURED_ACTIVITY_SCORE. points null = final score not known. */
	@Data
	public static class StructuredActivityScore
	{
		private final String activityKey;
		private final Integer completionCount;
		private final Integer points;
		private final boolean observedFromStart;
	}

	/** Backs EventType.STRUCTURED_ACTIVITY_CURRENCY. gained &gt; 0; balance is the game's value after it. */
	@Data
	public static class StructuredActivityCurrency
	{
		private final String activityKey;
		private final String currency;
		private final int gained;
		private final int balance;
	}

	/** Backs EventType.STRUCTURED_ACTIVITY_PRODUCTION: exact produced quantities of one confirmed action. */
	@Data
	public static class StructuredActivityProduction
	{
		private final String activityKey;
		private final java.util.List<ProducedItem> items;
	}

	/** One produced item and its exact quantity. Output, not loot. */
	@Data
	public static class ProducedItem
	{
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}

	@Data
	public static class StructuredRewardItem
	{
		private final int itemId;
		private final String itemName;
		private final int quantity;
	}
}

package com.osrstelemetry.plugin.events;

import lombok.Data;

/**
 * eventId is client-generated (UUIDv4) and is the natural idempotency
 * key for anything that later consumes this stream (a retried write
 * keyed on the same eventId is a no-op, not a duplicate). Nothing about
 * idempotency needs to happen locally — this ledger is a single local
 * producer appending once per real event.
 */
@Data
public class TelemetryEvent
{
	private final String eventId;
	private final String accountHash;
	private final EventType eventType;
	private final String occurredAt;
	private final String sessionId;
	private final int schemaVersion = 1;
	private final Object payload;
}

package com.osrstelemetry.plugin.history;

import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns {@link HistoryIndex}'s lifecycle and keeps every bit of its file IO
 * off the Swing EDT (spec Part T/U) -- a dedicated single-thread
 * daemon executor, the same restartability contract (start()/
 * shutdown(), safe across repeated plugin enable/disable) already
 * established by LootTrackerCoordinator/LocalStateStore/EventLedger
 * in this codebase.
 *
 * READ MODEL: getRecentEntries() (called from the EDT) NEVER blocks: it
 * returns whatever HistoryIndex currently has cached in memory. Newly
 * finalized sessions are picked up by a background refresh() requested
 * when a finalized session file has actually been written (see
 * SessionPersistence's finalized-write listener, wired by the plugin),
 * on account load, and when the player opens History -- never by
 * polling, and never with file IO on the EDT. A changed entry list is
 * announced through the optional change listener.
 *
 * DELIBERATELY INDEPENDENT of SessionRuntimeCoordinator: this class
 * owns its own SessionPersistence instance (constructed with the
 * single-arg, no-archive constructor -- see that constructor's own
 * javadoc for why that is fully supported, not merely a test shim).
 * HistoryCoordinator only ever READS already-finalized session files
 * (loadFinalized()); it never persists a current/finalized session
 * itself, so it has no need of a LoadoutArchive -- loadout resolution
 * already happened once, at original finalization time, inside
 * SessionRuntimeCoordinator's own SessionPersistence, and is already
 * baked into the JSON file this class reads.
 *
 * ACCOUNT ISOLATION (spec Part S): ensureAccountLoaded() on a real
 * switch installs a BRAND NEW, empty HistoryIndex synchronously
 * (cheap -- no IO) before any background refresh for the new account
 * can run, so there is no window where the old account's cached
 * entries could be read under the new account's identity. A scan that
 * was already running for the old account reads its (account, index)
 * pair together at its start and publishes only if that index is still
 * current, so its result is dropped rather than shown or indexed under
 * the new account; the new account's own scan follows.
 *
 * DETAIL LOADING (spec Part R -- lazy): loadDetail() is a direct,
 * uncached SessionPersistence.loadFinalized() read, run on the same
 * background executor -- full aggregates/loadout are only ever
 * parsed here, when a specific entry is actually opened, never as
 * part of the lightweight list refresh (see HistoryEntry's own
 * javadoc).
 */
@Slf4j
@Singleton
public class HistoryCoordinator
{
	/** Spec's own "~10 day display window" -- filters HistoryIndex's snapshot at read time; never deletes anything on disk (spec Part A: display-only retention). */
	private static final Duration DISPLAY_WINDOW = Duration.ofDays(10);

	private final SessionPersistence persistence;

	private ExecutorService executor;
	private volatile HistoryIndex index = new HistoryIndex();
	private volatile long currentAccountHash;
	private volatile boolean accountLoaded = false;
	private final AtomicBoolean refreshInFlight = new AtomicBoolean(false);
	private final AtomicBoolean refreshRequestedAgain = new AtomicBoolean(false);
	/** Guards the (account, index, published list) triple; never held during disk I/O. */
	private final Object publishLock = new Object();
	private volatile List<HistoryEntry> cachedSnapshot = Collections.emptyList();
	/** True once the CURRENT account's sessions have been scanned at least once (reset on account switch). */
	private volatile boolean initialScanComplete;

	@Inject
	public HistoryCoordinator(LocalStateStore store)
	{
		this.persistence = new SessionPersistence(store);
	}

	public void start()
	{
		if (executor != null && !executor.isShutdown())
		{
			return;
		}
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-history-index");
			t.setDaemon(true);
			return t;
		});
	}

	public void shutdown()
	{
		ExecutorService toShutdown = this.executor;
		if (toShutdown == null)
		{
			return;
		}
		toShutdown.shutdown();
		try
		{
			if (!toShutdown.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("HistoryCoordinator index executor did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the HistoryCoordinator index executor; leaving it to keep draining in the background");
		}
	}

	/**
	 * Called from OsrsTelemetryPlugin.handleLogin() on every LOGGED_IN
	 * transition, same as every other per-account coordinator here --
	 * a same-account call (fresh start already loaded, or a world
	 * hop/relog) is a no-op.
	 */
	public void ensureAccountLoaded(long accountHash)
	{
		if (accountLoaded && accountHash == currentAccountHash)
		{
			return;
		}
		synchronized (publishLock)
		{
			// Swapped together with the published list under the same lock a
			// refresh publishes under, so a refresh that scanned the OLD
			// account can never publish into the new one (see runRefreshes).
			currentAccountHash = accountHash;
			accountLoaded = true;
			index = new HistoryIndex();
			cachedSnapshot = Collections.emptyList();
			initialScanComplete = false;
		}
		notifyChanged();
		triggerBackgroundRefresh();
	}

	/**
	 * Called from the EDT. A pure, never-blocking read of the cached
	 * entries. Reads no longer kick a refresh (that re-scanned the sessions
	 * directory once a second); refreshes happen on account load, when a
	 * finalized session file is written ({@link #requestRefresh()}, wired
	 * from the session runtime) and when the player opens History.
	 */
	public List<HistoryEntry> getRecentEntries()
	{
		return cachedSnapshot;
	}

	/**
	 * Whether the current account's History has been scanned at least once,
	 * so an empty {@link #getRecentEntries()} really means "no sessions"
	 * rather than "not loaded yet" (logged out, or the first scan still
	 * running). Used only to decide the first-use welcome state.
	 */
	public boolean isInitialScanComplete()
	{
		return accountLoaded && initialScanComplete;
	}

	/** Re-scan finalized sessions in the background; coalesces with one already running. */
	public void requestRefresh()
	{
		triggerBackgroundRefresh();
	}

	private volatile Runnable changeListener;

	/** Best-effort notification (history executor thread) that the recent-entries list changed. */
	public void setChangeListener(Runnable listener)
	{
		this.changeListener = listener;
	}

	private void notifyChanged()
	{
		Runnable listener = changeListener;
		if (listener == null)
		{
			return;
		}
		try
		{
			listener.run();
		}
		catch (RuntimeException e)
		{
			log.debug("History change listener failed; the index is unaffected", e);
		}
	}

	private static boolean sameEntries(List<HistoryEntry> a, List<HistoryEntry> b)
	{
		if (a.size() != b.size())
		{
			return false;
		}
		for (int i = 0; i < a.size(); i++)
		{
			if (!a.get(i).getSessionId().equals(b.get(i).getSessionId()))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Requests one scan of the CURRENT account (read when the scan starts,
	 * never captured at request time). At most one worker runs; requests
	 * made while it runs are served by it re-scanning once more, so none is
	 * ever lost -- the request flag is raised BEFORE claiming the worker,
	 * and the worker re-checks it after releasing (see runRefreshes).
	 */
	private void triggerBackgroundRefresh()
	{
		if (!accountLoaded)
		{
			// Nothing to scan yet (and never the "account 0" directory).
			return;
		}
		refreshRequestedAgain.set(true);
		startWorkerIfIdle();
	}

	private void startWorkerIfIdle()
	{
		ExecutorService currentExecutor = this.executor;
		if (currentExecutor == null || currentExecutor.isShutdown())
		{
			return;
		}
		if (!refreshInFlight.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			currentExecutor.submit(this::runRefreshes);
		}
		catch (RejectedExecutionException e)
		{
			// Shut down between the check and the submit: release the worker
			// slot so a restarted coordinator is never stuck "in flight".
			refreshInFlight.set(false);
		}
	}

	private void runRefreshes()
	{
		try
		{
			while (refreshRequestedAgain.getAndSet(false))
			{
				long accountHash;
				HistoryIndex scanned;
				synchronized (publishLock)
				{
					accountHash = currentAccountHash;
					scanned = index;
				}
				try
				{
					List<HistoryEntry> refreshed = scanned.refresh(accountHash, persistence, DISPLAY_WINDOW, Instant.now());
					boolean changed;
					synchronized (publishLock)
					{
						if (scanned != index)
						{
							// The account changed while scanning: this result
							// belongs to the old account and is dropped (its own
							// ensureAccountLoaded already requested a new scan).
							continue;
						}
						changed = !sameEntries(cachedSnapshot, refreshed) || !initialScanComplete;
						cachedSnapshot = refreshed;
						initialScanComplete = true;
					}
					if (changed)
					{
						notifyChanged();
					}
				}
				catch (Exception e)
				{
					log.warn("History index refresh failed for account {}", accountHash, e);
				}
			}
		}
		finally
		{
			refreshInFlight.set(false);
			// A request raised after the loop's last check but before the
			// release above found the worker busy: serve it now.
			if (refreshRequestedAgain.get())
			{
				startWorkerIfIdle();
			}
		}
	}

	/**
	 * Lazy full-detail load for one entry (spec Part R) -- run on the
	 * background executor, never the EDT. `onLoaded` is invoked on
	 * that same background thread; callers touching Swing state from
	 * it must marshal back onto the EDT themselves (e.g.
	 * SwingUtilities.invokeLater()), the same obligation any other
	 * background-thread callback in this codebase already carries.
	 * Passes null to `onLoaded` if the file is missing/malformed (fail
	 * open, spec Part Y) or the executor is not currently running.
	 */
	public void loadDetail(long accountHash, String sessionId, Consumer<Session> onLoaded)
	{
		ExecutorService currentExecutor = this.executor;
		if (currentExecutor == null || currentExecutor.isShutdown())
		{
			onLoaded.accept(null);
			return;
		}
		try
		{
			currentExecutor.submit(() ->
			{
				try
				{
					onLoaded.accept(persistence.loadFinalized(accountHash, sessionId));
				}
				catch (Exception e)
				{
					log.warn("Failed to load History detail for session {}", sessionId, e);
					onLoaded.accept(null);
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			onLoaded.accept(null);
		}
	}

	/**
	 * Convenience overload using this coordinator's own already-tracked
	 * {@link #currentAccountHash}
	 * -- lets {@code OsrsTelemetryPanel} (which, like every other tab's
	 * view, has no reason to track an account hash of its own) trigger a
	 * detail load from a bare sessionId alone, the same way
	 * {@link #getRecentEntries()} needs no accountHash parameter either.
	 * Same off-EDT/background-thread contract as the 3-arg overload.
	 */
	public void loadDetail(String sessionId, Consumer<Session> onLoaded)
	{
		loadDetail(currentAccountHash, sessionId, onLoaded);
	}
}

package com.osrstelemetry.plugin.history;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionAggregates;
import java.util.Map;
import lombok.Getter;

/**
 * A lightweight, list-row-sized summary of one finalized session --
 * everything History's recent-activity list needs to render a row
 * WITHOUT holding this session's full aggregates/loadout data in
 * memory for every entry in the index. Built once per session, the
 * first time {@link HistoryIndex} discovers its file -- a finalized
 * session file is immutable, so this summary never needs to be
 * recomputed for a sessionId already indexed.
 *
 * Deliberately excludes the full xpGainedBySkill map, the full
 * lootDrops list, and starting/ending loadout entirely -- all of that
 * is read lazily, only when a specific entry is opened (see
 * HistoryCoordinator.loadDetail(), which re-reads the full Session
 * record via SessionPersistence.loadFinalized()), per spec Part R.
 * The few derived numbers here (totalXpGained, lootDropCount) are
 * cheap summaries computed once at discovery time, not a second
 * source of truth -- the detail view always renders from the
 * session's own already-persisted aggregates directly, never from
 * these fields (spec Part D/G/H: never re-derived, never mixed with
 * another source).
 */
@Getter
public final class HistoryEntry
{
	private final String sessionId;
	private final ActivityIdentity activityIdentity;
	private final String startedAt;
	private final String finalizedAt;
	private final long accumulatedActiveDurationMillis;
	private final long totalXpGained;
	private final SessionAggregates.ReliableCount reliableCount;
	private final int lootDropCount;
	private final boolean hasStartingLoadout;
	private final boolean hasEndingLoadout;
	/**
	 * Persisted Slayer assignment INSTANCES in this session (same-name tasks
	 * counted separately, skipped ones included); 0 for non-Slayer sessions
	 * and legacy files without a ledger. Presentation only -- see
	 * {@link #displayTitle}.
	 */
	private final int slayerAssignmentCount;
	/** Structured-activity completions this session; null when the session has no completion metric. */
	private final Integer activityCompletionCount;

	/** Title of a Slayer session that spanned more than one assignment. */
	public static final String MULTI_TASK_SLAYER_TITLE = "Slayer Session";

	private HistoryEntry(String sessionId, ActivityIdentity activityIdentity, String startedAt, String finalizedAt,
		long accumulatedActiveDurationMillis, long totalXpGained, SessionAggregates.ReliableCount reliableCount,
		int lootDropCount, boolean hasStartingLoadout, boolean hasEndingLoadout, int slayerAssignmentCount,
		Integer activityCompletionCount)
	{
		this.activityCompletionCount = activityCompletionCount;
		this.sessionId = sessionId;
		this.activityIdentity = activityIdentity;
		this.startedAt = startedAt;
		this.finalizedAt = finalizedAt;
		this.accumulatedActiveDurationMillis = accumulatedActiveDurationMillis;
		this.totalXpGained = totalXpGained;
		this.reliableCount = reliableCount;
		this.lootDropCount = lootDropCount;
		this.hasStartingLoadout = hasStartingLoadout;
		this.hasEndingLoadout = hasEndingLoadout;
		this.slayerAssignmentCount = slayerAssignmentCount;
	}

	/**
	 * Builds a summary from a fully-parsed finalized Session. Returns
	 * null (never throws) if the session is missing a field a valid
	 * finalized record must have (sessionId, activityIdentity,
	 * finalizedAt) -- HistoryIndex treats a null result as "skip this
	 * file, log it, move on" (spec Part Y), never a crash.
	 */
	public static HistoryEntry from(Session session)
	{
		if (session == null || session.getSessionId() == null || session.getActivityIdentity() == null
			|| session.getFinalizedAt() == null)
		{
			return null;
		}

		SessionAggregates aggregates = session.getAggregates();
		long totalXp = 0L;
		int lootDropCount = 0;
		SessionAggregates.ReliableCount reliableCount = null;
		if (aggregates != null)
		{
			Map<String, Long> xpBySkill = aggregates.getXpGainedBySkill();
			if (xpBySkill != null)
			{
				for (Long delta : xpBySkill.values())
				{
					if (delta != null)
					{
						totalXp += delta;
					}
				}
			}
			lootDropCount = aggregates.getLootDrops() != null ? aggregates.getLootDrops().size() : 0;
			reliableCount = aggregates.getReliableCount();
		}

		return new HistoryEntry(session.getSessionId(), session.getActivityIdentity(), session.getStartedAt(),
			session.getFinalizedAt(), session.getAccumulatedActiveDurationMillis(), totalXp, reliableCount,
			lootDropCount, session.getStartingLoadout() != null, session.getEndingLoadout() != null,
			slayerAssignmentCount(session),
			session.getActivityIdentity().getActivityType() == ActivityType.STRUCTURED_ACTIVITY
				? (aggregates == null || aggregates.getActivityCompletions() == null ? 0 : aggregates.getActivityCompletions().getSessionCompletions())
				: null);
	}

	/**
	 * Number of persisted Slayer assignment records, or 0 when the session
	 * is not a Slayer session or has no ledger (never inferred from loot).
	 */
	public static int slayerAssignmentCount(Session session)
	{
		if (session == null || session.getActivityIdentity() == null
			|| session.getActivityIdentity().getActivityType() != ActivityType.SLAYER
			|| session.getAggregates() == null || session.getAggregates().getSlayerAssignments() == null)
		{
			return 0;
		}
		return session.getAggregates().getSlayerAssignments().size();
	}

	/**
	 * History's title for a finalized session. A Slayer session that spanned
	 * several assignments is a "Slayer Session", never just its final task;
	 * everything else (including a single-task Slayer session and every
	 * legacy file) keeps its activity's own display name. Presentation only:
	 * the session's persisted identity and ID never change.
	 */
	public static String displayTitle(ActivityIdentity identity, int slayerAssignmentCount)
	{
		if (slayerAssignmentCount > 1)
		{
			return MULTI_TASK_SLAYER_TITLE;
		}
		return identity == null || identity.getDisplayName() == null ? "Unknown activity" : identity.getDisplayName();
	}

	/** "1 task" / "6 tasks". */
	public static String taskCountText(int count)
	{
		return count + (count == 1 ? " task" : " tasks");
	}
}

package com.osrstelemetry.plugin.history;

import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.io.IOException;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * History's discovery/index (spec Part R): a lightweight, in-memory cache
 * of {@link HistoryEntry} summaries, one per finalized session, kept
 * current by comparing a cheap directory listing of sessions/ against
 * sessionIds already known -- NEVER a full per-tick re-parse of every
 * session file.
 *
 * ADAPTED FROM, NOT COPIED FROM, LootTrackerIndex/LootTrackerPersistence:
 * that pair's rebuild logic streams one append-only events.jsonl file
 * line-by-line. History's canonical source is instead a DIRECTORY of
 * many small immutable per-session JSON files (spec Part B), so
 * "rebuild" here means "list the directory, diff against what's
 * already indexed, parse only the files that are genuinely new."
 * Every already-indexed file is immutable (a finalized session record
 * is never rewritten -- see SessionPersistence's own javadoc) and is
 * therefore NEVER re-parsed once indexed -- the one part this DOES
 * share with LootTrackerIndex's own design: once accepted, a record
 * is never re-read from disk.
 *
 * OFF THE EDT (spec Part T/U): refresh() does real file IO (a
 * directory listing plus, for each newly-discovered session, one
 * SessionPersistence.loadFinalized() read) and must never be called
 * from the Swing EDT -- see HistoryCoordinator, which owns the
 * background thread this runs on.
 *
 * BACKWARD COMPATIBILITY / ERROR HANDLING (spec Parts X/Y): a single
 * malformed or partial session file (any I/O or parse failure --
 * SessionPersistence.loadFinalized() already fails open, returning
 * null -- or a file that parses but is missing required fields, per
 * HistoryEntry.from()'s own null-return contract) is logged and
 * skipped, never thrown, and never crashes the rest of the refresh --
 * every other file continues to be indexed normally, and a skipped
 * file is retried on the NEXT refresh() call (it is never marked
 * "seen" unless HistoryEntry.from() actually returned a real entry),
 * so a transiently-locked file (e.g. mid-write) self-heals on a later
 * refresh (the next finalized-session write or History tab open) rather
 * than being permanently skipped.
 *
 * ACCOUNT ISOLATION (spec Part S): one HistoryIndex instance is
 * strictly single-account for its own in-memory cache's lifetime --
 * HistoryCoordinator constructs a fresh one on every real account
 * switch rather than clearing this one in place, so there is no
 * "leftover key from the old account" class of bug to guard against
 * here at all.
 */
@Slf4j
public final class HistoryIndex
{
	private final Map<String, HistoryEntry> entries = new ConcurrentHashMap<>();
	/**
	 * Session files that could not be indexed (corrupt, partial, or not a
	 * finalized session), keyed by id, valued by the file's last-modified
	 * time when rejected. Without this a bad file was re-read and re-logged
	 * on EVERY scan (each History open, each finalize); now it is retried
	 * only after it changes on disk.
	 */
	private final Map<String, Object> rejected = new ConcurrentHashMap<>();
	private static final Object UNKNOWN_STAMP = new Object();

	/**
	 * Lists sessions/ (cheap: filesystem metadata only), parses any
	 * sessionId not already in `entries`, and returns a filtered,
	 * newest-first snapshot within `window` of `now`. Safe to call
	 * repeatedly (every finalized-session write, every History tab open) --
	 * the cost of a call where nothing changed is one directory
	 * listing plus a HashMap containsKey() per existing file, no
	 * parsing at all.
	 */
	public List<HistoryEntry> refresh(long accountHash, SessionPersistence persistence, Duration window, Instant now)
	{
		List<Filepath> files;
		// walk(1): the sessions/ directory itself (depth 0) plus its
		// immediate children (depth 1) only -- never recurses into a
		// subdirectory, matching the old File.listFiles()'s flat,
		// single-level listing exactly. A missing/unreadable directory
		// (NoSuchFileException or any other IOException) is treated
		// exactly like the old File.listFiles() == null case: nothing
		// new to index this pass, not a failure.
		try (Stream<Filepath> walk = TelemetryPaths.sessionsDir(accountHash).walk(1))
		{
			files = walk.filter(Filepath::isFile)
				.filter(f -> f.getFileName().endsWith(".json"))
				.collect(Collectors.toList());
		}
		catch (IOException e)
		{
			files = java.util.Collections.emptyList();
		}

		for (Filepath file : files)
		{
			String sessionId = stripJsonExtension(file.getFileName());
			if (sessionId == null || entries.containsKey(sessionId))
			{
				continue;
			}
			Object stamp = lastModified(file);
			if (stamp.equals(rejected.get(sessionId)))
			{
				// Rejected before and unchanged since: never re-read.
				continue;
			}
			Session session = persistence.loadFinalized(accountHash, sessionId);
			HistoryEntry entry = HistoryEntry.from(session);
			if (entry == null)
			{
				rejected.put(sessionId, stamp);
				log.warn("Skipping unparseable/incomplete session file for History: {}", file.getFileName());
				continue;
			}
			rejected.remove(sessionId);
			entries.put(sessionId, entry);
		}
		return snapshot(window, now);
	}

	private static Object lastModified(Filepath file)
	{
		try
		{
			Object time = file.getLastModifiedTime();
			return time == null ? UNKNOWN_STAMP : time;
		}
		catch (Exception e)
		{
			return UNKNOWN_STAMP;
		}
	}

	private static String stripJsonExtension(String filename)
	{
		if (!filename.endsWith(".json"))
		{
			return null;
		}
		return filename.substring(0, filename.length() - ".json".length());
	}

	private List<HistoryEntry> snapshot(Duration window, Instant now)
	{
		Instant cutoff = now.minus(window);
		List<HistoryEntry> result = new ArrayList<>();
		for (HistoryEntry entry : entries.values())
		{
			Instant finalizedAt = parseInstantOrNull(entry.getFinalizedAt());
			// A file whose finalizedAt somehow fails to parse is kept
			// (never silently dropped from the list) rather than
			// excluded by an unparseable date -- see HistoryEntry.from(),
			// which already guarantees finalizedAt is non-null for any
			// entry that made it into `entries` at all; this null-check
			// is a pure defensive fallback.
			if (finalizedAt != null && finalizedAt.isBefore(cutoff))
			{
				continue;
			}
			result.add(entry);
		}
		// Newest first by the real instant: Instant.toString() drops trailing
		// zero fraction digits, so string order is wrong within one second
		// ("...:05Z" would sort after "...:05.123Z").
		result.sort(Comparator.comparing((HistoryEntry e) -> parseInstantOrNull(e.getFinalizedAt()),
			Comparator.nullsLast(Comparator.reverseOrder())));
		return result;
	}

	private static Instant parseInstantOrNull(String value)
	{
		if (value == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(value);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/** Test/diagnostic visibility -- how many sessions are currently indexed in memory (the ~10 day window filter is NOT applied here; this is the raw indexed count). */
	int indexedCount()
	{
		return entries.size();
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The Loot Tracker's own top-level runtime coordinator -- registered as a
 * {@link TelemetryEventListener} exactly like {@code
 * SessionRuntimeCoordinator} (see OsrsTelemetryPlugin's own
 * startUp()/shutDown() wiring for the paired addListener()/
 * removeListener() this class requires too), but otherwise entirely
 * UNRELATED to it: this class has no session/lifecycle/classifier
 * dependency of any kind (the spec's "independence from session
 * lifecycle" requirement), and owns its own {@link LootTrackerIndex}
 * rather than sharing or reading from {@code SessionAggregates}.
 *
 * ACCOUNT LOADING (mirrors SessionRuntimeCoordinator.ensureAccountLoaded()'s
 * own idempotency contract -- see its javadoc): a same-account call
 * (fresh plugin start already loaded, or a world hop/relog) is a
 * deliberate no-op; a genuine account change installs a brand-new,
 * empty index immediately (so the panel never shows one account's loot
 * under another's identity, even briefly) and kicks off a background
 * durable rebuild (see below) to repopulate it from that account's own
 * events.jsonl.
 *
 * WHY THE REBUILD RUNS ON A BACKGROUND THREAD, NOT THE CALLER'S: unlike
 * {@code SessionPersistence.loadCurrent()} (one small JSON file),
 * {@link LootTrackerPersistence#rebuild} reads this account's ENTIRE
 * events.jsonl -- potentially every telemetry event this account has
 * ever produced, not just loot. {@code ensureAccountLoaded()} is called
 * from {@code OsrsTelemetryPlugin.handleLogin()} via
 * {@code ClientThread.invokeLater()} (see that method's own javadoc for
 * why Client-thread-marshalled login handling exists at all) -- running
 * a potentially large sequential file read there would block the
 * client thread, exactly the class of mistake
 * {@code TelemetryEventListener}'s own javadoc warns listeners against.
 * {@link LootTrackerIndex} is fully thread-safe (synchronized methods),
 * so installing the fresh (initially empty) index synchronously and
 * then populating it progressively from a background thread is safe:
 * an EDT poll mid-rebuild simply sees a partially-populated, still
 * internally-consistent snapshot, never a torn/corrupted one.
 *
 * LIVE UPDATES: {@link #onEvent} applies every canonical loot event --
 * {@code SERVER_NPC_LOOT} and {@code STRUCTURED_REWARD} (see
 * {@link LootTrackerEvents}) -- directly to the CURRENT index (the same one
 * {@code ensureAccountLoaded()} installed/is populating), with no file
 * IO of its own -- cheap enough to run synchronously on whatever thread
 * {@code EventLedger} calls listeners from (normally the RuneLite
 * client thread), matching every other lightweight listener in this
 * project.
 *
 * CANONICAL eventId END TO END: EventLedger passes each listener the
 * durable envelope's own eventId, and live records use it -- the same id
 * the rebuild reads back off disk -- so an event delivered live while an
 * account-load rebuild is also reading it from events.jsonl is applied
 * once ({@link LootTrackerIndex}'s eventId dedup). A synthetic UUID is
 * used only by a direct caller with no envelope id.
 */
@Slf4j
@Singleton
public final class LootTrackerCoordinator implements TelemetryEventListener
{
	/**
	 * Spec: "~365 day retention (display only, raw telemetry never
	 * deleted)". Bounds what {@link #ensureAccountLoaded} loads into the
	 * LIVE in-memory index -- see LootTrackerPersistence's own javadoc
	 * for why this never touches anything on disk.
	 */
	public static final int RETENTION_DAYS = 365;

	private static final long NO_ACCOUNT = -1L;

	private final LootTrackerPersistence persistence;

	private volatile LootTrackerIndex index = new LootTrackerIndex();
	private volatile long currentAccountHash = NO_ACCOUNT;
	private ExecutorService rebuildExecutor;

	@Inject
	public LootTrackerCoordinator(Gson gson)
	{
		this.persistence = new LootTrackerPersistence(gson);
	}

	/** Paired with {@link #shutdown()} -- same start()/shutdown() lifecycle convention as EventLedger/LocalStateStore. */
	public synchronized void start()
	{
		if (rebuildExecutor != null && !rebuildExecutor.isShutdown())
		{
			return;
		}
		rebuildExecutor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-loot-tracker-rebuild");
			t.setDaemon(true);
			return t;
		});
	}

	public synchronized void shutdown()
	{
		ExecutorService executor = this.rebuildExecutor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("LootTrackerCoordinator rebuild executor did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the LootTrackerCoordinator rebuild executor; leaving it to keep draining in the background");
		}
	}

	/**
	 * Called from {@code OsrsTelemetryPlugin.handleLogin()} on every
	 * LOGGED_IN transition, exactly like
	 * {@code SessionRuntimeCoordinator.ensureAccountLoaded()} -- see
	 * class javadoc for the full idempotency/threading contract.
	 */
	public synchronized void ensureAccountLoaded(long accountHash)
	{
		if (accountHash == currentAccountHash)
		{
			return;
		}

		// Index first, then the account: a live event for the new account
		// that passes onEvent's account check can only see the new index.
		LootTrackerIndex fresh = new LootTrackerIndex();
		index = fresh;
		currentAccountHash = accountHash;

		ExecutorService executor = this.rebuildExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("ensureAccountLoaded() called while LootTrackerCoordinator is not started; Loot Tracker will remain empty for account {}", accountHash);
			return;
		}
		Instant cutoff = Instant.now().minus(RETENTION_DAYS, ChronoUnit.DAYS);
		executor.submit(() ->
		{
			int applied = persistence.rebuild(accountHash, fresh, cutoff);
			log.debug("Loot Tracker rebuild for account {} applied {} record(s)", accountHash, applied);
			notifyChanged();
		});
		notifyChanged();
	}

	@Override
	public void onEvent(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		onEvent(accountHash, type, payload, observedAt, null);
	}

	/**
	 * Live path. Records carry the durable envelope's own eventId (EventLedger
	 * passes it), so a live record and the same event read back by a
	 * concurrent account-load rebuild dedupe to one; a synthetic id is used
	 * only when a caller has no envelope id.
	 *
	 * Canonical inputs: SERVER_NPC_LOOT (NPC loot) and STRUCTURED_REWARD
	 * (structured activity reward claims). Both are raw telemetry, consumed
	 * independently of Current Session: a reward the session declines to own
	 * is still recorded here, exactly once.
	 */
	@Override
	public void onEvent(long accountHash, EventType type, Object payload, Instant observedAt, String eventId)
	{
		if (accountHash != currentAccountHash)
		{
			// Another account's event (an account switch in flight): it is in
			// that account's events.jsonl and is picked up by its own rebuild;
			// it must never land in this account's index.
			return;
		}
		String id = eventId != null ? eventId : UUID.randomUUID().toString();
		LootTrackerRecord record = null;
		if (type == EventType.SERVER_NPC_LOOT && payload instanceof EventPayloads.ServerNpcLoot)
		{
			record = LootTrackerEvents.fromServerNpcLoot(id, (EventPayloads.ServerNpcLoot) payload, observedAt);
		}
		else if (type == EventType.STRUCTURED_REWARD && payload instanceof EventPayloads.StructuredReward)
		{
			record = LootTrackerEvents.fromStructuredReward(id, (EventPayloads.StructuredReward) payload, observedAt);
		}
		if (record != null && index.apply(record))
		{
			notifyChanged();
		}
	}

	private volatile Runnable changeListener;

	/**
	 * Best-effort, downstream notification that the index changed (a live
	 * record applied, an account switch, a rebuild finished). Called on
	 * whichever thread made the change; must be cheap. The index never
	 * depends on a listener existing or succeeding.
	 */
	public void setChangeListener(Runnable listener)
	{
		this.changeListener = listener;
	}

	private void notifyChanged()
	{
		Runnable listener = changeListener;
		if (listener == null)
		{
			return;
		}
		try
		{
			listener.run();
		}
		catch (RuntimeException e)
		{
			log.debug("Loot Tracker change listener failed; the index is unaffected", e);
		}
	}

	/** The current account's live index -- see class javadoc for why this reference can change on an account switch. */
	public LootTrackerIndex getIndex()
	{
		return index;
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.activity.StructuredRewardSource;
import com.osrstelemetry.plugin.events.EventPayloads;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

/**
 * The ONE conversion from a canonical loot telemetry event to a
 * {@link LootTrackerRecord}, shared by the live listener and the
 * events.jsonl rebuild so both produce identical records (same eventId,
 * same key, same items) and {@link LootTrackerIndex}'s eventId dedup can
 * collapse a live and a rebuilt copy of one event.
 */
final class LootTrackerEvents
{
	private LootTrackerEvents()
	{
	}

	static LootTrackerRecord fromServerNpcLoot(String eventId, EventPayloads.ServerNpcLoot loot, Instant observedAt)
	{
		List<LootTrackerItem> items = new ArrayList<>();
		if (loot.getItems() != null)
		{
			for (EventPayloads.ServerNpcLootItem item : loot.getItems())
			{
				items.add(new LootTrackerItem(item.getItemId(), item.getItemName(), item.getQuantity()));
			}
		}
		return new LootTrackerRecord(eventId, loot.getSourceName(), loot.getSourceId(), observedAt, items);
	}

	/**
	 * A structured reward, under its canonical reward source. The source is
	 * the payload's canonical key or -- for an event written before keys
	 * existed -- a declared alias of its name; anything the registry does not
	 * declare is skipped (null), never guessed into some source.
	 */
	static LootTrackerRecord fromStructuredReward(String eventId, EventPayloads.StructuredReward reward, Instant observedAt)
	{
		StructuredRewardSource source = StructuredActivityRegistry.defaults()
			.rewardSource(reward.getSourceKey() != null ? reward.getSourceKey() : reward.getSourceName());
		if (source == null)
		{
			return null;
		}
		List<LootTrackerItem> items = new ArrayList<>();
		if (reward.getItems() != null)
		{
			for (EventPayloads.StructuredRewardItem item : reward.getItems())
			{
				items.add(new LootTrackerItem(item.getItemId(), item.getItemName(), item.getQuantity()));
			}
		}
		if (items.isEmpty())
		{
			return null;
		}
		return new LootTrackerRecord(eventId, source.getDisplayName(), null, observedAt, items,
			LootTrackerIndex.structuredSourceKey(source.getKey()));
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The one durable, in-memory read-model the Loot Tracker feature is
 * built on: a pure, RuneLite/Swing
 * -independent accumulator of {@link LootTrackerRecord}s, keyed by
 * STABLE source identity. Deliberately its own class, entirely
 * independent of {@code Session}/{@code SessionAggregates}/{@code
 * SessionLifecycleEngine} -- the spec's explicit "independence from
 * session lifecycle" requirement: this index has no concept of a
 * session at all, and is updated from EVERY {@code SERVER_NPC_LOOT}
 * event this account ever produces, whether or not a session happens to
 * be active at the time.
 *
 * SOLE AUTHORITATIVE SOURCE: only {@code EventType.SERVER_NPC_LOOT}
 * ever feeds this index (via {@link LootTrackerCoordinator} for live
 * events, {@link LootTrackerPersistence} for durable rebuild) -- never
 * {@code NPC_LOOT_ATTRIBUTED} (diagnostic-only, never proof of player
 * ownership -- see that SignalKind's own javadoc) and never any
 * session/XP/kill-count signal.
 *
 * HONEST KILL-COUNT SEMANTICS: each
 * {@link LootTrackerRecord} is exactly one real {@code
 * net.runelite.client.events.ServerNpcLoot} notification (see
 * ServerNpcLootCollector's own class javadoc for the verified-against-
 * source confirmation that this fires once per {@code addLoot(...)}
 * call in RuneLite's OWN core {@code LootTrackerPlugin}). Counting
 * records per source is therefore not an invented/approximated kill
 * count -- it is the exact same per-NPC-name occurrence count RuneLite's
 * own official Loot Tracker plugin already displays as that NPC's kill
 * count. This is never derived from NPC_DEATH (which this index never
 * even reads).
 *
 * STABLE SOURCE IDENTITY: keyed by (sourceName, sourceId) together --
 * see {@link #sourceKey(String, Integer)}. Two different sourceIds
 * under the same display name (e.g. a reskinned/instanced variant) are
 * DIFFERENT sources and are never merged, exactly per spec; a null
 * sourceId (see EventPayloads.ServerNpcLoot's own nullability javadoc)
 * is its own stable identity too, distinct from any real numeric id
 * sharing the same name.
 *
 * DEDUP: {@link #apply(LootTrackerRecord)} skips (returns false for) a
 * record whose non-null eventId has already been applied -- this is
 * what makes {@link LootTrackerPersistence}'s durable rebuild safe to
 * re-run without double-counting, and defends against a theoretically
 * corrupted/duplicated events.jsonl line. A record with a null eventId
 * is NEVER dedup-skipped (see LootTrackerRecord's own javadoc for why
 * this is fail-safe, not a real gap in practice).
 *
 * THREAD-SAFETY: {@code synchronized} methods -- the same simple,
 * well-understood concurrency primitive this project already prefers
 * over anything bespoke (see SessionRuntimeCoordinator's own
 * synchronized accessor). apply() is called from whatever thread
 * EventLedger's synchronous listener notification runs on (normally the
 * RuneLite client thread) or from the one-time durable-rebuild pass
 * (a plugin-startup background thread); {@link #snapshotSources()} is
 * called from the EDT on every panel poll tick. Neither call is
 * expensive enough for synchronized contention to matter in practice.
 */
public final class LootTrackerIndex
{
	private final Map<String, String> sourceNameByKey = new LinkedHashMap<>();
	private final Map<String, Integer> sourceIdByKey = new LinkedHashMap<>();
	private final Map<String, List<LootTrackerRecord>> recordsByKey = new LinkedHashMap<>();
	private final Set<String> appliedEventIds = new HashSet<>();

	/**
	 * @return true if this record was newly applied; false if it was
	 * skipped as an already-seen eventId (see class javadoc). Never
	 * throws on malformed input -- a record with a null/blank
	 * sourceName is still applied (grouped under a stable "unknown
	 * source" key) rather than dropped, matching this project's
	 * existing "never silently discard real telemetry" discipline.
	 */
	public synchronized boolean apply(LootTrackerRecord record)
	{
		if (record == null)
		{
			return false;
		}
		if (record.getEventId() != null && !appliedEventIds.add(record.getEventId()))
		{
			return false;
		}

		String key = record.getSourceKey() != null ? record.getSourceKey() : sourceKey(record.getSourceName(), record.getSourceId());
		sourceNameByKey.putIfAbsent(key, record.getSourceName());
		sourceIdByKey.putIfAbsent(key, record.getSourceId());
		recordsByKey.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
		return true;
	}

	/**
	 * A fresh, immutable snapshot of every source currently known, in
	 * first-observed order. Cheap enough for an EDT poll tick (a handful
	 * of list copies, no file IO -- see LootTrackerPersistence for the
	 * one place any file IO happens) but still a real copy, never a live
	 * view, so a caller iterating this list is never affected by a
	 * concurrent apply().
	 */
	/** True when no record has been applied (cheap; no copying). */
	public synchronized boolean isEmpty()
	{
		return recordsByKey.isEmpty();
	}

		public synchronized List<LootTrackerSource> snapshotSources()
	{
		List<LootTrackerSource> sources = new ArrayList<>();
		for (Map.Entry<String, List<LootTrackerRecord>> entry : recordsByKey.entrySet())
		{
			String key = entry.getKey();
			if (entry.getValue().isEmpty())
			{
				continue;
			}
			sources.add(new LootTrackerSource(key, sourceNameByKey.get(key), sourceIdByKey.get(key), entry.getValue()));
		}
		return sources;
	}

	/**
	 * One source's snapshot by key, or null if unknown -- used by
	 * per-source operations (reset watermark, hide-item lookups) that
	 * already know which source they mean rather than re-scanning
	 * {@link #snapshotSources()}.
	 */
	public synchronized LootTrackerSource snapshotSource(String sourceKey)
	{
		List<LootTrackerRecord> records = recordsByKey.get(sourceKey);
		if (records == null || records.isEmpty())
		{
			return null;
		}
		return new LootTrackerSource(sourceKey, sourceNameByKey.get(sourceKey), sourceIdByKey.get(sourceKey), records);
	}

	/** Prefix of every structured-reward source key; see {@link #structuredSourceKey}. */
	public static final String STRUCTURED_KEY_PREFIX = "structured:";

	/**
	 * Key of a structured reward source ("structured:barrows"). It never
	 * contains the NUL separator every NPC key has, so the two namespaces
	 * can never collide, and existing NPC keys (and every preference stored
	 * under them) are unchanged.
	 */
	public static String structuredSourceKey(String rewardSourceKey)
	{
		return STRUCTURED_KEY_PREFIX + rewardSourceKey;
	}

	/** True for a key made by {@link #structuredSourceKey}. */
	public static boolean isStructuredSourceKey(String key)
	{
		return key != null && key.startsWith(STRUCTURED_KEY_PREFIX) && key.indexOf('\u0000') < 0;
	}

	/**
	 * Stable identity key: sourceName and sourceId joined by a single
	 * NUL character (U+0000, written as an escape below; these keys are
	 * persisted in preferences, so the separator must never change), with
	 * the id ALWAYS rendered last as either decimal digits or the literal
	 * word "null" -- see class javadoc for why the two are never merged
	 * independently. An NPC name never contains NUL, so the split between
	 * name and id stays unambiguous even when sourceName contains spaces
	 * or digits -- e.g. name="A 2" id=3 can never collide with name="A"
	 * id=23. A null sourceId becomes the literal
	 * string "null" (distinct from a real id, which can never
	 * legitimately render as that word), and a null sourceName becomes
	 * "" (empty) -- deterministic, and never fabricates a fallback
	 * display value itself; that is the caller's concern.
	 */
	public static String sourceKey(String sourceName, Integer sourceId)
	{
		String namePart = sourceName == null ? "" : sourceName;
		String idPart = sourceId == null ? "null" : sourceId.toString();
		return namePart + '\u0000' + idPart;
	}
}

package com.osrstelemetry.plugin.loottracker;

/**
 * One item stack within one atomic {@code SERVER_NPC_LOOT} drop record -- the Loot
 * Tracker's own equivalent of {@code EventPayloads.ServerNpcLootItem},
 * kept as a SEPARATE, package-independent type rather than reusing that
 * events-package payload class directly. This mirrors the existing
 * project convention of a durable telemetry payload (events package)
 * being distinct from the pure UI/domain shape derived from it (see
 * CurrentSessionSnapshot.LootEntry vs SessionAggregates.LootItemAggregate)
 * -- the Loot Tracker's own domain model must not take on a compile-time
 * dependency on the telemetry envelope shape, so a future change to one
 * never silently breaks the other.
 *
 * Immutable value type -- plain equals/hashCode by field, no Lombok
 * dependency needed for a type this small.
 */
public final class LootTrackerItem
{
	private final int itemId;
	private final String itemName;
	private final long quantity;

	public LootTrackerItem(int itemId, String itemName, long quantity)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.quantity = quantity;
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getItemName()
	{
		return itemName;
	}

	public long getQuantity()
	{
		return quantity;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof LootTrackerItem))
		{
			return false;
		}
		LootTrackerItem other = (LootTrackerItem) o;
		return itemId == other.itemId
			&& quantity == other.quantity
			&& java.util.Objects.equals(itemName, other.itemName);
	}

	@Override
	public int hashCode()
	{
		return java.util.Objects.hash(itemId, itemName, quantity);
	}

	@Override
	public String toString()
	{
		return "LootTrackerItem{itemId=" + itemId + ", itemName=" + itemName + ", quantity=" + quantity + "}";
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonSyntaxException;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Durable rebuild: reads this account's {@code events.jsonl} directly (the SAME
 * append-only file {@code EventLedger} writes -- see
 * TelemetryPaths.eventsFile()'s own javadoc), extracts every
 * {@code SERVER_NPC_LOOT} and {@code STRUCTURED_REWARD} line (converted by
 * the same {@link LootTrackerEvents} the live path uses), and applies each one to a
 * {@link LootTrackerIndex}. This is what lets the Loot Tracker survive
 * a client restart with its full history intact, entirely independent
 * of any session-state file (Phase 2's "independence from session
 * lifecycle" requirement) and without needing a second, competing
 * persisted-state format of its own -- events.jsonl already IS the
 * durable source of truth for every loot event this account has
 * ever produced.
 *
 * PERFORMANCE (spec requirement -- "no full events.jsonl reread per
 * Swing tick"): this rebuild is a ONE-TIME cost, run exactly once at
 * plugin startup (see LootTrackerCoordinator), never on any Swing
 * Timer tick. After rebuild completes, every live update flows through
 * {@link LootTrackerIndex#apply(LootTrackerRecord)} directly (O(1)
 * amortized, no file IO) and every panel read flows through
 * {@link LootTrackerIndex#snapshotSources()} (an in-memory copy, no
 * file IO) -- this class is never touched again until the next full
 * plugin restart.
 *
 * RETENTION (spec requirement -- "~365 day retention, display only,
 * raw telemetry never deleted"): {@code minObservedAt} bounds what this
 * rebuild loads into the LIVE in-memory index -- lines older than that
 * are simply not parsed into a LootTrackerRecord at all. This is a
 * memory-bounding decision for the live read-model only; events.jsonl
 * ITSELF is never read destructively (a plain sequential read, never a
 * rewrite) and nothing on disk is ever deleted, trimmed, or modified by
 * this class. A caller wanting a longer effective retention window
 * simply passes an earlier {@code minObservedAt} (or {@code null} for
 * "no bound, load everything") -- the bound lives entirely at the call
 * site, not hardcoded here.
 *
 * DEDUP: relies entirely on {@link LootTrackerIndex#apply}'s own
 * eventId-based dedup (see that method's javadoc) -- this class does no
 * deduplication of its own, so re-running a rebuild against the same
 * index is always safe (idempotent) by construction.
 *
 * FAILURE HANDLING: matches this project's established
 * {@code LocalStateStore.readIfExists()} fail-open discipline -- a
 * missing events.jsonl, an unreadable file, or an individual malformed
 * line never crashes plugin startup. A malformed/unparseable LINE is
 * skipped and logged (the rest of the file is still processed); a
 * missing file simply yields an empty index (a brand new account, or
 * telemetry collection never enabled yet).
 */
@Slf4j
public final class LootTrackerPersistence
{
	private final Gson gson;

	/**
	 * @param gson RuneLite's injected Gson (passed down from
	 * LootTrackerCoordinator's own constructor injection) -- this class
	 * is not itself Guice-managed, so it is not annotated {@code @Inject}.
	 */
	public LootTrackerPersistence(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Reads {@code events.jsonl} for {@code accountHash} line by line
	 * (streamed, never loading the whole file into memory at once --
	 * this file can grow to contain every telemetry event this account
	 * has ever produced, not just loot) and applies every qualifying
	 * loot record (NPC loot and structured rewards) to {@code index}.
	 *
	 * @param minObservedAt records observed strictly before this instant
	 * are not loaded (retention bound -- see class javadoc); pass null
	 * for no bound.
	 * @return the number of records newly applied (post-dedup) -- purely
	 * informational, for startup logging.
	 */
	public int rebuild(long accountHash, LootTrackerIndex index, Instant minObservedAt)
	{
		Filepath eventsFile = TelemetryPaths.eventsFile(accountHash);
		if (!eventsFile.exists())
		{
			return 0;
		}

		int applied = 0;
		int lineNumber = 0;
		try (BufferedReader reader = new BufferedReader(
			new InputStreamReader(eventsFile.openInputStream(), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				lineNumber++;
				if (line.isEmpty())
				{
					continue;
				}
				LootTrackerRecord record = parseIfLoot(line, lineNumber, minObservedAt);
				if (record != null && index.apply(record))
				{
					applied++;
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed reading events.jsonl for account {} during Loot Tracker rebuild; proceeding with whatever was applied so far", accountHash, e);
		}

		return applied;
	}

	/**
	 * Minimal envelope shape -- ONLY the fields this rebuild actually
	 * needs (eventId, eventType, occurredAt), plus the payload kept as a
	 * raw {@link JsonElement} so it is only deserialized into a concrete
	 * {@code EventPayloads.ServerNpcLoot} for lines that actually are
	 * one. Deliberately does NOT reuse {@code events.TelemetryEvent}
	 * itself as the read-side type: that class's {@code payload} field
	 * is typed {@code Object}, which Gson cannot deserialize back into a
	 * concrete payload class on its own (it would produce a raw
	 * {@code LinkedTreeMap}, not an {@code EventPayloads.ServerNpcLoot})
	 * -- reading a polymorphic envelope back is a fundamentally different
	 * operation from writing one, so a separate, read-side-only shape is
	 * the correct fix, not a shared type.
	 */
	private static final class RawEnvelope
	{
		String eventId;
		EventType eventType;
		String occurredAt;
		JsonElement payload;
	}

	private LootTrackerRecord parseIfLoot(String line, int lineNumber, Instant minObservedAt)
	{
		RawEnvelope envelope;
		try
		{
			envelope = gson.fromJson(line, RawEnvelope.class);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Skipping malformed events.jsonl line {} during Loot Tracker rebuild", lineNumber, e);
			return null;
		}

		if (envelope == null || envelope.payload == null
			|| (envelope.eventType != EventType.SERVER_NPC_LOOT && envelope.eventType != EventType.STRUCTURED_REWARD))
		{
			return null;
		}

		Instant observedAt = parseInstantOrNull(envelope.occurredAt);
		if (observedAt != null && minObservedAt != null && observedAt.isBefore(minObservedAt))
		{
			return null;
		}

		try
		{
			if (envelope.eventType == EventType.STRUCTURED_REWARD)
			{
				EventPayloads.StructuredReward reward = gson.fromJson(envelope.payload, EventPayloads.StructuredReward.class);
				return reward == null ? null : LootTrackerEvents.fromStructuredReward(envelope.eventId, reward, observedAt);
			}
			EventPayloads.ServerNpcLoot loot = gson.fromJson(envelope.payload, EventPayloads.ServerNpcLoot.class);
			return loot == null ? null : LootTrackerEvents.fromServerNpcLoot(envelope.eventId, loot, observedAt);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Skipping events.jsonl line {} with malformed {} payload during Loot Tracker rebuild", lineNumber, envelope.eventType, e);
			return null;
		}
	}

	private static Instant parseInstantOrNull(String occurredAt)
	{
		if (occurredAt == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(occurredAt);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}
}

package com.osrstelemetry.plugin.loottracker;

import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Every piece of Loot Tracker UI PREFERENCE state that must survive a
 * restart, kept entirely SEPARATE from {@link LootTrackerIndex} (pure
 * telemetry-derived truth) -- the same "durable telemetry vs. durable
 * UI preference" split TelemetryPaths already draws between
 * {@code events.jsonl} and every {@code stateFile()} document. Nothing
 * in this class is telemetry: losing this file loses favorites/hidden
 * items/collapsed cards/reset points, never any actual loot history
 * (that always survives, unconditionally, in events.jsonl).
 *
 * FAVORITES ARE SOURCES, NOT ITEMS (spec requirement): {@link #favoriteSourceKeys}
 * holds {@link LootTrackerIndex#sourceKey} values.
 *
 * HIDDEN ITEMS ARE SOURCE-SPECIFIC (spec requirement): "hide" removes
 * one item from one source's PRESENTATION only -- see
 * {@link #isItemHidden}/{@link #hideItem}. Hidden loot still counts
 * toward every total (this class has no opinion on totals at all; it
 * only answers "hidden or not" -- the UI/valuation layer is what
 * decides whether to still include a hidden item's value, and the spec
 * requires that it does).
 *
 * RESET IS A LOGICAL WATERMARK, NEVER A DELETE (spec requirement):
 * {@link #getResetWatermark}/{@link #resetSource} store a per-source
 * Instant, "forget everything AT OR BEFORE this point" for DISPLAY
 * purposes only. {@link LootTrackerIndex} itself is never told about
 * this and never has anything removed from it -- the watermark is
 * applied at the UI-facing snapshot layer (see the Loot Tracker view
 * model), which is what makes a reset survive a full durable rebuild
 * (a rebuild re-applies every historical record exactly as before; the
 * watermark alone is what keeps them display-suppressed) without this
 * class or {@link LootTrackerIndex} needing to coordinate rebuild
 * ordering with each other at all.
 *
 * PERSISTENCE: one small JSON document, {@code loot_tracker_preferences.json},
 * written via the existing {@link LocalStateStore} (async, atomic
 * rename -- same durability guarantees every other state document in
 * this project already gets). An in-memory copy is kept authoritative
 * between writes (read-your-own-write consistency for the UI, which
 * reads this class far more often than any write actually happens;
 * a click updates the UI first and the write is asynchronous, and a bulk
 * change is one write via the collection setters) --
 * mirrors LiveXpTracker/lastKnownAbsoluteXpBySkill's own "authoritative
 * in-memory, asynchronously durable" split elsewhere in this project.
 */
@Singleton
public final class LootTrackerPreferences
{
	private static final String CATEGORY = "loot_tracker_preferences";

	/** The exact document persisted to disk -- a plain data holder, deliberately with no behavior of its own. */
	static final class Document
	{
		Set<String> favoriteSourceKeys = new HashSet<>();
		Map<String, Set<Integer>> hiddenItemIdsBySourceKey = new HashMap<>();
		Set<String> collapsedSourceKeys = new HashSet<>();
		/** sourceKey -> ISO-8601 Instant string (this project's established timestamp convention). */
		Map<String, String> resetWatermarkBySourceKey = new HashMap<>();
		/** Spec: "Show hidden" toggle, default OFF. */
		boolean showHidden = false;
	}

	private static final long NO_ACCOUNT = -1L;

	private final LocalStateStore store;
	private long accountHash = NO_ACCOUNT;
	private Document document = new Document();

	@Inject
	public LootTrackerPreferences(LocalStateStore store)
	{
		this.store = store;
	}

	/**
	 * Loads this account's persisted preferences (or starts a fresh,
	 * all-default document if none exist yet -- a brand-new account, or
	 * a pre-Phase-2 install that never had this file). Safe to call on
	 * EVERY {@code OsrsTelemetryPlugin.handleLogin()} transition
	 * unconditionally (mirrors {@code SessionRuntimeCoordinator.
	 * ensureAccountLoaded()}'s own same-account-is-a-no-op contract): a
	 * same-account call (a world hop/relog, or a duplicate fresh-start
	 * call) is a deliberate no-op, so an in-flight but not-yet-durably-
	 * written preference mutation from just before the hop is never
	 * discarded by re-reading a possibly-stale copy off disk. A best-
	 * effort synchronous read (see LocalStateStore.readIfExists()'s own
	 * fail-open javadoc), acceptable here for the exact same reason it's
	 * already acceptable there: a single small JSON document, read at
	 * most once per genuine account change, not on any hot path.
	 */
	public synchronized void loadForAccount(long accountHash)
	{
		if (accountHash == this.accountHash)
		{
			return;
		}
		this.accountHash = accountHash;
		Document loaded = store.readIfExists(TelemetryPaths.stateFile(accountHash, CATEGORY), Document.class);
		this.document = loaded != null ? loaded : new Document();
		if (document.favoriteSourceKeys == null)
		{
			document.favoriteSourceKeys = new HashSet<>();
		}
		if (document.hiddenItemIdsBySourceKey == null)
		{
			document.hiddenItemIdsBySourceKey = new HashMap<>();
		}
		if (document.collapsedSourceKeys == null)
		{
			document.collapsedSourceKeys = new HashSet<>();
		}
		if (document.resetWatermarkBySourceKey == null)
		{
			document.resetWatermarkBySourceKey = new HashMap<>();
		}
	}

	private synchronized void persist()
	{
		store.write(TelemetryPaths.stateFile(accountHash, CATEGORY), document);
	}

	public synchronized boolean isFavorite(String sourceKey)
	{
		return document.favoriteSourceKeys.contains(sourceKey);
	}

	public synchronized void setFavorite(String sourceKey, boolean favorite)
	{
		if (favorite)
		{
			document.favoriteSourceKeys.add(sourceKey);
		}
		else
		{
			document.favoriteSourceKeys.remove(sourceKey);
		}
		persist();
	}

	public synchronized boolean isItemHidden(String sourceKey, int itemId)
	{
		Set<Integer> hidden = document.hiddenItemIdsBySourceKey.get(sourceKey);
		return hidden != null && hidden.contains(itemId);
	}

	public synchronized void setItemHidden(String sourceKey, int itemId, boolean hidden)
	{
		if (hidden)
		{
			document.hiddenItemIdsBySourceKey.computeIfAbsent(sourceKey, k -> new HashSet<>()).add(itemId);
		}
		else
		{
			Set<Integer> set = document.hiddenItemIdsBySourceKey.get(sourceKey);
			if (set != null)
			{
				set.remove(itemId);
				if (set.isEmpty())
				{
					document.hiddenItemIdsBySourceKey.remove(sourceKey);
				}
			}
		}
		persist();
	}

	public synchronized boolean isShowHidden()
	{
		return document.showHidden;
	}

	public synchronized void setShowHidden(boolean showHidden)
	{
		document.showHidden = showHidden;
		persist();
	}

	public synchronized boolean isCollapsed(String sourceKey)
	{
		return document.collapsedSourceKeys.contains(sourceKey);
	}

	public synchronized void setCollapsed(String sourceKey, boolean collapsed)
	{
		if (collapsed)
		{
			document.collapsedSourceKeys.add(sourceKey);
		}
		else
		{
			document.collapsedSourceKeys.remove(sourceKey);
		}
		persist();
	}

	/**
	 * Batch form of {@link #setCollapsed(String, boolean)}: every key in
	 * one in-memory update and ONE persisted write (Collapse All / Open All,
	 * or one card that represents several raw source keys).
	 */
	public synchronized void setCollapsed(java.util.Collection<String> sourceKeys, boolean collapsed)
	{
		if (collapsed)
		{
			document.collapsedSourceKeys.addAll(sourceKeys);
		}
		else
		{
			document.collapsedSourceKeys.removeAll(sourceKeys);
		}
		persist();
	}

	/** Batch form of {@link #setFavorite(String, boolean)}: one persisted write. */
	public synchronized void setFavorite(java.util.Collection<String> sourceKeys, boolean favorite)
	{
		if (favorite)
		{
			document.favoriteSourceKeys.addAll(sourceKeys);
		}
		else
		{
			document.favoriteSourceKeys.removeAll(sourceKeys);
		}
		persist();
	}

	/** Null if this source has never been reset. */
	public synchronized Instant getResetWatermark(String sourceKey)
	{
		String iso = document.resetWatermarkBySourceKey.get(sourceKey);
		if (iso == null)
		{
			return null;
		}
		try
		{
			return Instant.parse(iso);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	/**
	 * Requires the CALLER to have already obtained user confirmation
	 * (spec requirement -- "requires confirmation"); this method itself
	 * performs the reset unconditionally once called. {@code at} is
	 * normally {@code Instant.now()} -- passed in rather than computed
	 * here so this stays unit-testable with a fixed clock, matching this
	 * project's existing style (see CurrentSessionSnapshotTest's own
	 * fixed-Instant convention).
	 */
	public synchronized void resetSource(String sourceKey, Instant at)
	{
		document.resetWatermarkBySourceKey.put(sourceKey, at.toString());
		persist();
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.time.Instant;
import java.util.Collections;
import java.util.List;

/**
 * ONE atomic loot notification ({@code SERVER_NPC_LOOT}, or one
 * {@code STRUCTURED_REWARD} claim under its explicit {@link #getSourceKey()}), exactly as it happened -- the
 * Loot Tracker's fundamental unit of truth. Deliberately preserves the
 * SAME atomic event boundary {@code EventPayloads.ServerNpcLoot}
 * itself carries (one record = one real {@code net.runelite.client.
 * events.ServerNpcLoot} notification, i.e. one RuneLite-Loot-Tracker-
 * equivalent "kill" -- see LootTrackerIndex's own javadoc for the full
 * honest-kill-count audit) -- a "grouped" view is always a DERIVED
 * aggregation over a list of these records, never a replacement
 * representation, so the individual-drop view (spec requirement) can
 * always reconstruct real event boundaries rather than fabricating
 * them.
 *
 * eventId is the durable-rebuild dedup key (see LootTrackerPersistence):
 * the SAME UUID TelemetryEvent/EventLedger already generates for every
 * durably-appended envelope. It is nullable ONLY for the narrow case of
 * a live-applied record arriving through TelemetryEventListener, which
 * (by that interface's own existing contract -- see its javadoc) does
 * not currently pass the envelope's eventId through to listeners.
 * LootTrackerCoordinator synthesizes a fresh, process-local, guaranteed-
 * unique id for that case (see its own javadoc for why this is still
 * exact-once-safe) rather than leaving eventId genuinely null, so in
 * practice every record this project ever constructs has a real,
 * non-null eventId -- null is only ever a theoretical/defensive state
 * for this class's own dedup logic to fail safe against (treated as
 * "never dedup-skip" -- see LootTrackerIndex.apply()).
 */
public final class LootTrackerRecord
{
	private final String eventId;
	private final String sourceName;
	private final Integer sourceId;
	private final Instant observedAt;
	private final List<LootTrackerItem> items;
	/**
	 * Canonical source key for a non-NPC source (a structured reward:
	 * {@link LootTrackerIndex#structuredSourceKey}); null for NPC loot, whose
	 * key stays the historical (sourceName, sourceId) key.
	 */
	private final String sourceKey;

	public LootTrackerRecord(String eventId, String sourceName, Integer sourceId, Instant observedAt, List<LootTrackerItem> items)
	{
		this(eventId, sourceName, sourceId, observedAt, items, null);
	}

	public LootTrackerRecord(String eventId, String sourceName, Integer sourceId, Instant observedAt, List<LootTrackerItem> items,
		String sourceKey)
	{
		this.sourceKey = sourceKey;
		this.eventId = eventId;
		this.sourceName = sourceName;
		this.sourceId = sourceId;
		this.observedAt = observedAt;
		this.items = Collections.unmodifiableList(new java.util.ArrayList<>(items));
	}

	/** Explicit canonical key (structured rewards), or null for NPC loot. */
	public String getSourceKey()
	{
		return sourceKey;
	}

	public String getEventId()
	{
		return eventId;
	}

	public String getSourceName()
	{
		return sourceName;
	}

	public Integer getSourceId()
	{
		return sourceId;
	}

	public Instant getObservedAt()
	{
		return observedAt;
	}

	/** Immutable -- the exact item stacks from one real drop notification, in original order. */
	public List<LootTrackerItem> getItems()
	{
		return items;
	}
}

package com.osrstelemetry.plugin.loottracker;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * One immutable snapshot of everything observed for one STABLE source identity
 * (sourceName + sourceId -- see LootTrackerIndex.sourceKey()'s own
 * javadoc for why the two are never merged even when only one of them
 * differs). Produced fresh by {@link LootTrackerIndex#snapshotSources()}
 * every time it is called; never itself mutated afterward -- the same
 * "immutable snapshot built fresh from mutable live state" split this
 * project's Current Session architecture already uses
 * (SessionAggregates -> CurrentSessionSnapshot).
 *
 * {@link #getRecords()} preserves the exact atomic
 * {@code SERVER_NPC_LOOT} event boundaries in observation order --
 * required by the spec's individual-drop view, which must reconstruct
 * real event boundaries rather than a fabricated one. {@link #getItemTotals()}
 * is a SEPARATE, derived aggregation over those same records for the
 * grouped view -- both views read from the same underlying records, so
 * they can never disagree with each other.
 */
public final class LootTrackerSource
{
	private final String sourceKey;
	private final String sourceName;
	private final Integer sourceId;
	private final List<LootTrackerRecord> records;

	LootTrackerSource(String sourceKey, String sourceName, Integer sourceId, List<LootTrackerRecord> records)
	{
		this.sourceKey = sourceKey;
		this.sourceName = sourceName;
		this.sourceId = sourceId;
		this.records = Collections.unmodifiableList(new ArrayList<>(records));
	}

	public String getSourceKey()
	{
		return sourceKey;
	}

	/** A structured activity reward source (Barrows, Tempoross Reward Pool, ...) rather than an NPC. */
	public boolean isStructuredReward()
	{
		return LootTrackerIndex.isStructuredSourceKey(sourceKey);
	}

	public String getSourceName()
	{
		return sourceName;
	}

	public Integer getSourceId()
	{
		return sourceId;
	}

	/** Every atomic drop record observed for this source, in observation order. Never empty (a source with zero records is never surfaced -- see LootTrackerIndex). */
	public List<LootTrackerRecord> getRecords()
	{
		return records;
	}

	/**
	 * The one reliable "kill count" for this source: the number of
	 * distinct atomic {@code SERVER_NPC_LOOT} notifications observed --
	 * exactly RuneLite's own core Loot Tracker's kill-count semantics
	 * (see LootTrackerIndex's own javadoc for the full source audit).
	 * Never derived from NPC_DEATH or any other signal.
	 */
	public int getKillCount()
	{
		return records.size();
	}

	/**
	 * Earliest / latest observedAt over every record. Not list position:
	 * a live record applied while an account-load rebuild is still reading
	 * older records from disk lands BEFORE them in the list.
	 */
	public Instant getFirstObservedAt()
	{
		Instant first = null;
		for (LootTrackerRecord record : records)
		{
			Instant at = record.getObservedAt();
			if (at != null && (first == null || at.isBefore(first)))
			{
				first = at;
			}
		}
		return first;
	}

	public Instant getLastObservedAt()
	{
		Instant last = null;
		for (LootTrackerRecord record : records)
		{
			Instant at = record.getObservedAt();
			if (at != null && (last == null || at.isAfter(last)))
			{
				last = at;
			}
		}
		return last;
	}

	/**
	 * A new snapshot containing only records strictly AFTER
	 * {@code afterExclusive} (or this exact object, unfiltered, if
	 * {@code afterExclusive} is null) -- used by the UI-facing snapshot
	 * layer to apply a per-source RESET WATERMARK (see
	 * LootTrackerPreferences's own javadoc) without this class or
	 * {@link LootTrackerIndex} needing any concept of "reset" baked into
	 * their own pure telemetry-derivation logic. A reset is "forget
	 * everything AT OR BEFORE this point," so a record with
	 * {@code observedAt} exactly equal to {@code afterExclusive} is
	 * excluded too. A record with a null {@code observedAt} is always
	 * KEPT -- never silently dropped by a filter it has no timestamp to
	 * compare against.
	 */
	public LootTrackerSource filteredAfter(Instant afterExclusive)
	{
		if (afterExclusive == null)
		{
			return this;
		}
		List<LootTrackerRecord> filtered = new ArrayList<>();
		for (LootTrackerRecord record : records)
		{
			if (record.getObservedAt() == null || record.getObservedAt().isAfter(afterExclusive))
			{
				filtered.add(record);
			}
		}
		return new LootTrackerSource(sourceKey, sourceName, sourceId, filtered);
	}

	/**
	 * Grouped view: one entry per distinct itemId, quantity summed
	 * across every record, in FIRST-SEEN item order (a stable,
	 * deterministic base order -- callers doing value-based sorting,
	 * e.g. LootPricing, re-sort this themselves; this method makes no
	 * value/price assumption of its own).
	 */
	public List<LootTrackerItem> getItemTotals()
	{
		Map<Integer, Long> quantityByItemId = new LinkedHashMap<>();
		Map<Integer, String> nameByItemId = new LinkedHashMap<>();
		for (LootTrackerRecord record : records)
		{
			for (LootTrackerItem item : record.getItems())
			{
				quantityByItemId.merge(item.getItemId(), item.getQuantity(), Long::sum);
				nameByItemId.putIfAbsent(item.getItemId(), item.getItemName());
			}
		}

		List<LootTrackerItem> totals = new ArrayList<>();
		for (Map.Entry<Integer, Long> entry : quantityByItemId.entrySet())
		{
			totals.add(new LootTrackerItem(entry.getKey(), nameByItemId.get(entry.getKey()), entry.getValue()));
		}
		return totals;
	}
}

package com.osrstelemetry.plugin.model;

import lombok.Data;

/**
 * Identity document. accountHash is the stable primary key (survives
 * display-name changes) — see net.runelite.api.Client#getAccountHash().
 * displayName is mutable and carried only for human readability.
 */
@Data
public class AccountIdentity
{
	private final String accountHash;
	private String displayName;
	private String accountType;
	private final int schemaVersion = 1;
	private String capturedAt;
}

package com.osrstelemetry.plugin.model;

import lombok.Data;

/**
 * One document per activityId (a boss, raid, or repeatable encounter).
 * activityId is a free-form slug, not an enum — a new boss added to the
 * game needs zero code change here, just a new document.
 *
 * The authoritative/inferred distinction is load-bearing (see Step 3
 * audit): where Jagex prints an official count line in the chatbox or
 * reward interface, source=AUTHORITATIVE and killCount is set.
 * Otherwise source=INFERRED and killCountEstimate is set instead —
 * deliberately a different field name so nothing downstream can read
 * an estimate as a hard number by accident.
 */
@Data
public class ActivityState
{
	public enum Source
	{
		AUTHORITATIVE,
		INFERRED
	}

	private final String activityId;
	private String displayName;
	private Source source;

	// set only when source == AUTHORITATIVE
	private Integer killCount;

	// set only when source == INFERRED
	private Integer killCountEstimate;
	private String trackingStartedAt;
	private String note;

	private String lastUpdatedAt;
}

package com.osrstelemetry.plugin.model;

import java.util.List;
import lombok.Data;

/**
 * One document per collection-log page. A page with no document on
 * disk at all means "never opened" — that is a distinct state from
 * "opened and empty," and callers must be able to tell them apart.
 * Do not synthesize a document with obtained=false for unseen pages.
 */
@Data
public class CollectionLogPageState
{
	@Data
	public static class LogItem
	{
		private final int itemId;
		private final String name;
		private final boolean obtained;
		private final int quantity;
	}

	private final String category;
	private final String page;
	private List<LogItem> items;
	private String lastObservedAt;
}

package com.osrstelemetry.plugin.model;

import java.util.List;
import lombok.Data;

/**
 * Extraction relies on the same signals RuneLite's own BankPlugin
 * uses: ScriptID.POTIONSTORE_BUILD/DOSE_CHANGE,
 * InterfaceID.Bankmain.POTIONSTORE_ITEMS, EnumID.POTIONSTORE_POTIONS/
 * UNFINISHED_POTIONS, the "groups of five, item at i+1, dose text at
 * i+3" widget layout, and the "Doses: N" / "Quantity: N" text format.
 *
 * itemId/itemName describe the CURRENTLY DISPLAYED withdrawal-dose
 * variant for that potion type (e.g. "Super strength(4)"), not a
 * dose-independent potion identity — the real game doesn't have one.
 * totalDoses is the raw dose count, which is the actual "how much do
 * I own" signal independent of which variant happens to be displayed.
 * withdrawalDoseCount records which dose-variant (1-4) itemId
 * corresponds to, mirroring the real plugin's own withdrawDoses
 * calculation (including its fallback-to-4-if-unmatched quirk, kept
 * faithfully rather than "fixed" since it's their behavior being
 * mirrored, not this project's own design).
 */
@Data
public class PotionStorageState
{
	@Data
	public static class PotionStorageItem
	{
		private final int itemId;
		private final String itemName;
		private final int totalDoses;
		private final int withdrawalDoseCount;
	}

	private List<PotionStorageItem> items;
	private String lastObservedAt;
	private final boolean continuouslyObservable = false;
}

package com.osrstelemetry.plugin.model;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;

/**
 * RuneLite's net.runelite.api.Quest enum exposes a stable numeric id
 * (@Getter int id) and a proper display name (@Getter String name).
 * quest.name() (the Java enum constant name, e.g.
 * DESERT_TREASURE_II__THE_FALLEN_EMPIRE) is kept as "key" since it's a
 * convenient stable map key, but it is NOT the user-facing name — id
 * is authoritative, and name ("Desert Treasure II - The Fallen
 * Empire") is what a human or an AI summary should ever display.
 */
@Data
public class QuestsState
{
	@Data
	public static class QuestEntry
	{
		private final int id;
		private final String key;
		private final String name;
		private final String state;
	}

	private final Map<String, QuestEntry> questsByKey = new LinkedHashMap<>();
	private String lastUpdated;
}

