 * natively by Spyglass (SlayerNativeTaskReader: Slayer varps + the game
 * cache's Slayer DB tables) -- never from another RuneLite plugin. Chat
 * text is not used for any current-state field here.
 *
 * masterId is the raw varbit value and is always trustworthy.
 * streak/streakLabel: the streak that belongs to the current master --
 * Krystilia (7) SLAYER_WILDERNESS_TASKS_COMPLETED ("WILDERNESS"), Mortimer
 * (10) varp SLAYER_MORTIMER_TASKS_COMPLETED ("MORTIMER"), every other master
 * SLAYER_TASKS_COMPLETED ("NORMAL") -- the same selection RuneLite 1.13.1's
 * own SlayerPlugin.addCounter() makes. The streak feeds
 * SlayerCollector.looksCancelled(), which only ever compares two
 * observations with the SAME label.
 *
 * modifierId/modifierValue/modifierNegative: the raw task-modifier varbits
 * (Mortimer's "mortifiers"). Additive and nullable -- absent from older
 * slayer.json files. Presentation decides which ids it can name reliably.
 */
@Data
public class SlayerState
{
	private String taskName;
	private String taskLocation;
	private int amountRemaining;
	private int initialAmount;
	/**
	 * Raw varp SLAYER_COUNT_ORIGINAL at this observation (before any quantity
	 * modifier). Diagnostic only -- not part of task identity. Recorded so
	 * live QA can show whether it changes on a direct same-name
	 * reassignment before it is ever trusted as identity evidence.
	 */
	private Integer nativeCountOriginal;

	/** Raw varbit SLAYER_MODIFIER_ID (0 = none). Nullable for older files. */
	private Integer modifierId;
	/** Raw varbit SLAYER_MODIFIER_VALUE. */
	private Integer modifierValue;
	/** Raw varbit SLAYER_MODIFIER_NEGATIVE == 1. */
	private Boolean modifierNegative;

	private int masterId;
	private int points;
	private int streak;
	private String streakLabel;
	private boolean streakSourceVerified;

	private String lastUpdated;
}

package com.osrstelemetry.plugin.model;

import java.util.List;
import lombok.Data;

/**
 * One document per storage container. storageId is a free string
 * ("bank", "inventory", "equipment", "seed_vault", "group_storage",
 * ...) so a newly-discovered container type never requires a schema
 * change.
 *
 * Equipment items always include slot position and a semantic slot
 * name, and empty equipment slots are
 * included explicitly (itemId -1) rather than filtered out — an
 * equipment container is fully continuously observable, so "slot 3 is
 * absent from this list" and "slot 3 is confirmed empty" must not be
 * collapsed into the same representation. Inventory items also carry
 * their slot index (cheap to keep, useful for reconstructing layout)
 * but empty inventory slots are still omitted, since an inventory slot
 * being empty isn't an identity the way an equipment slot is.
 *
 * lastObservedAt is mandatory and load-bearing: for containers that
 * only populate while their interface is open (bank, seed vault,
 * group storage), a stale lastObservedAt is the ONLY thing telling a
 * caller this data is not live. Never omit it, never treat an old
 * snapshot as current.
 */
@Data
public class StorageState
{
	@Data
	public static class StorageItem
	{
		private final int slot;
		private final int itemId;
		private final String name;
		private final int quantity;
		/** Only set for the equipment container (e.g. "WEAPON", "HEAD"). Null everywhere else. */
		private final String equipmentSlot;
	}

	private final String storageId;
	private List<StorageItem> items;
	private String lastObservedAt;

	/**
	 * Set only for storageId="bank": the id of the immutable snapshot
	 * file (bank_snapshots/{latestSnapshotId}.json) that corresponds
	 * to this observation, once the debounce window has settled. May
	 * lag slightly behind lastObservedAt/items — see ContainerCollector.
	 */
	private String latestSnapshotId;

	/**
	 * True only for containers RuneLite can see continuously
	 * (inventory, equipment). False for anything gated behind opening
	 * an interface (bank, seed vault, group storage). Lets the read
	 * API distinguish "live" from "as of last look" without the
	 * caller needing to know per-storageId semantics.
	 */
	private boolean continuouslyObservable;
}

package com.osrstelemetry.plugin.session;

import java.util.Objects;

/**
 * A small,
 * immutable value describing "what counts as the same activity" for
 * lifecycle resume/switch decisions — nothing more. This class does
 * NOT implement the gameplay logic that produces these (no
 * XP_CHANGE-means-Woodcutting, no SERVER_NPC_LOOT-means-this-boss
 * heuristics anywhere in this class or elsewhere); the
 * engine only ever receives already-classified identities from a
 * separate classifier/router.
 *
 * activityKey is the stable semantic identity ("gargoyles:catacombs",
 * "zulrah", "woodcutting") — the thing that must match for a resume to
 * be considered "the same activity." displayName ("Gargoyles",
 * "Zulrah", "Woodcutting") is presentation-only and deliberately
 * EXCLUDED from equals()/hashCode(): two ActivityIdentity instances
 * with the same activityType+activityKey but a different displayName
 * (e.g. a future localization or a refined display label) must still
 * compare equal for resume purposes, per the explicit instruction that
 * "equality for resume/switch decisions must use stable semantic
 * identity, not display text alone." This is written out by hand
 * (not Lombok @Data/@EqualsAndHashCode) specifically so that
 * exclusion is impossible to silently break by an unrelated Lombok
 * annotation edit later.
 */
public final class ActivityIdentity
{
	private final ActivityType activityType;
	private final String activityKey;
	private final String displayName;

	public ActivityIdentity(ActivityType activityType, String activityKey, String displayName)
	{
		this.activityType = Objects.requireNonNull(activityType, "activityType");
		this.activityKey = Objects.requireNonNull(activityKey, "activityKey");
		this.displayName = displayName;
	}

	public ActivityType getActivityType()
	{
		return activityType;
	}

	public String getActivityKey()
	{
		return activityKey;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/**
	 * Deliberately activityType + activityKey ONLY — see class javadoc.
	 * displayName never participates in equality.
	 */
	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof ActivityIdentity))
		{
			return false;
		}
		ActivityIdentity other = (ActivityIdentity) o;
		return activityType == other.activityType && activityKey.equals(other.activityKey);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(activityType, activityKey);
	}

	@Override
	public String toString()
	{
		return "ActivityIdentity{" + activityType + ":" + activityKey + " (" + displayName + ")}";
	}
}

package com.osrstelemetry.plugin.session;

/**
 * Specificity
 * precedence among ActivityType constants, used ONLY to decide
 * whether a later signal is allowed to REFINE (not switch) an
 * existing session's identity -- see ActivitySignalClassifier and
 * SessionLifecycleEngine.refineIdentity(). This ordering carries no
 * lifecycle meaning by itself: it never decides suspend/resume/
 * finalize, only whether "generic -> more specific" is a legal
 * refinement direction within the combat branch.
 *
 * BOSSING is more specific than SLAYER, which is more
 * specific than COMBAT (a Slayer task is fought with combat XP; a
 * boss kill is often, but not always, also part of a Slayer task or
 * plain combat). SKILLING is a deliberately separate branch with no
 * defined precedence relationship to the other three at all -- a
 * skilling identity is never compatible with a combat/slayer/bossing
 * identity in either direction, and code must never call
 * combatBranchRank(SKILLING).
 */
final class ActivityPrecedence
{
	private ActivityPrecedence()
	{
	}

	/**
	 * Higher number = more specific. Only meaningful for comparing two
	 * types within the combat branch (COMBAT/SLAYER/BOSSING).
	 */
	static int combatBranchRank(ActivityType type)
	{
		switch (type)
		{
			case COMBAT:
				return 0;
			case SLAYER:
				return 1;
			case BOSSING:
				return 2;
			default:
				throw new IllegalArgumentException("Not part of the combat specificity branch: " + type);
		}
	}

	static boolean isCombatBranch(ActivityType type)
	{
		return type == ActivityType.COMBAT || type == ActivityType.SLAYER || type == ActivityType.BOSSING;
	}

	/**
	 * True only when both types are in the combat branch and candidate
	 * strictly outranks current. SKILLING (or any future non-combat
	 * type) on either side always returns false -- it is never "more
	 * specific" or "less specific" than a combat-branch type, it is
	 * simply incomparable, which callers treat as a real switch.
	 */
	static boolean isMoreSpecific(ActivityType candidate, ActivityType current)
	{
		if (!isCombatBranch(candidate) || !isCombatBranch(current))
		{
			return false;
		}
		return combatBranchRank(candidate) > combatBranchRank(current);
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * The pure signal-to-decision classifier. Translates one SessionSignal
 * at a time (plus the current
 * Session, if any, and a per-account ClassifierContext) into a
 * SignalClassification. Never touches RuneLite, never subscribes to
 * anything, never reads Instant.now() -- every decision is a pure
 * function of its three arguments.
 *
 * BATCH RESOLUTION: this
 * classifier is intentionally stateless across calls -- it always
 * classifies ONE signal against whatever Session snapshot it is given,
 * never against other signals from the same real-world game action. A
 * future runtime coordinator MUST group same-tick signals (see
 * SessionSignalBatchResolver's gameTick key) and resolve them
 * together: when several of this classifier's independent outputs
 * disagree about identity (e.g. combat XP proposes generic COMBAT
 * while a same-tick SLAYER_TASK_PROGRESS proposes SLAYER), the
 * strongest, most specific COMPATIBLE identity must win regardless of
 * which signal happened to be classified first -- SessionSignalBatchResolver
 * implements that resolution deterministically and order-independently;
 * it replaces an earlier, incorrect "first classification
 * wins" policy.
 *
 * MULTI-SKILL XP: a different-skill
 * XP_CHANGE than the current SKILLING session's identity is still
 * classified here as a real switch, taken alone (e.g.
 * SKILLING/Woodcutting -> SKILLING/Mining) -- there is no per-skill
 * "incidental secondary XP" table here (no exhaustive multi-skill
 * mapping). What actually prevents Barbarian Fishing's incidental
 * Strength/Agility XP from fragmenting a session is
 * SessionSignalBatchResolver's same-tick stickiness rule, not this
 * method: those events share one real game tick, and the resolver
 * prefers whichever proposal matches the session's own current
 * identity when multiple proposals tie for a tick's "strongest"
 * identity. Secondary XP genuinely arriving on a DIFFERENT tick than
 * its primary skill's XP remains an open, unsolved edge case,
 * deliberately left undecided rather than guessed at.
 *
 * GG -&gt; Gargoyles activity-switch: decideCombatBranch()'s ACTIVE-session "never downgrade"
 * rule previously applied unconditionally to ANY less-specific
 * candidate identity, generic or specific alike -- correct for GENERIC
 * combat evidence (it carries no information about what is actually
 * being fought), but wrong for a lifecycle-carrying signal that
 * SPECIFICALLY identifies a genuinely different activity. Live
 * evidence: ACTIVE BOSSING/Grotesque Guardians, then repeated
 * SLAYER_TASK_PROGRESS events naming taskName "Gargoyles" from killing
 * ordinary Gargoyles (not the boss) never switched the session away
 * from Grotesque Guardians -- the boss session kept silently
 * accumulating normal Gargoyle loot and Slayer progress. Root cause:
 * classifySlayerTaskProgress()'s own proposed identity was relabeled
 * back to the stale BOSSING identity by decideCombatBranch()'s
 * lessSpecific branch before it ever reached SessionSignalBatchResolver,
 * so the resolver's own batch-level tie-break machinery never even saw
 * the real Gargoyles identity to weigh it.
 *
 * NARROWLY SCOPED, EXACTLY to classifySlayerTaskProgress()'s own call
 * into decideCombatBranch() (the new `fromAuthoritativeTaskProgress`
 * parameter, true only there): a SLAYER_TASK_PROGRESS event is direct,
 * per-kill telemetry about a specific task actually being worked on --
 * unlike combat-skill XP_CHANGE under a merely-tracked Slayer task
 * (classifyXpChange() above, `fromAuthoritativeTaskProgress` always
 * false there), which is inferred/incidental and must NOT gain this new
 * power (see
 * SessionRuntimeCoordinatorTest.zulrah_bossActivityContextEstablishesBossingSessionBeforeBossKill_sameSessionThroughout,
 * which relies on exactly that XP_CHANGE case still being protected).
 * When this flag is true and the new identity is less specific than an
 * ACTIVE current identity, the new identity is now proposed honestly
 * (a real switch) instead of being relabeled as the old one --
 * SessionSignalBatchResolver's own combat-branch rank tie-break
 * is still what correctly keeps a SAME-TICK
 * BOSS_KILL-plus-its-own-task-decrement resolved to the boss (BOSSING
 * outranks SLAYER when both appear in one batch), so a boss's own kill
 * -- which always also reports SLAYER_TASK_PROGRESS for whatever task it
 * counts toward -- is unaffected; only a SLAYER_TASK_PROGRESS arriving
 * with no corroborating same-tick BOSS_KILL now honestly proposes its
 * own specific identity.
 *
 * BOSS SELF-CONSUMPTION OF ITS OWN SLAYER TASK: the paragraph above assumed
 * a boss's own kill ALWAYS reports its task decrement in the SAME tick
 * as its BOSS_KILL/loot -- live evidence proved that false for Grotesque
 * Guardians specifically (the kill-count message and chest loot are
 * delayed several seconds behind the task decrement, behind a real
 * in-game chest-interaction step), so "no corroborating same-tick
 * BOSS_KILL" is NOT proof of a real switch when the current boss is
 * confirmed (see BossTaskAffinity) to consume its own named task.
 * classifySlayerTaskProgress() now suppresses the switch by default in
 * exactly that one case and defers to actual disambiguating evidence,
 * however many ticks later it arrives -- see that method's own javadoc,
 * ClassifierContext's pending boss-task candidate, classifyBossKill()/
 * classifyServerNpcLoot() (the confirm/abort halves), and
 * SessionSignalBatchResolver.applyBossSelfConsumptionCorroboration() (the
 * same-tick half) for the complete, corrected design. Every OTHER
 * SLAYER_TASK_PROGRESS case this paragraph originally described is
 * completely unaffected.
 *
 * CANDIDATE-METRIC BUFFERING (avoids an ambiguous kill's own
 * progress metric being stranded on the boss session after a later-confirmed
 * real switch): the paragraph above's own suppressed
 * SLAYER_TASK_PROGRESS metric is now BUFFERED in ClassifierContext,
 * never applied to any session while the candidate is pending -- see
 * ClassifierContext's own javadoc for the full lifecycle, and
 * classifyBossKill()/classifyServerNpcLoot()'s own comments for exactly
 * where a resolved candidate's buffered metric is finally applied
 * (self-consumption: the same, never-left BOSSING session; a real
 * switch: the brand-new Slayer session, immediately, not waiting for a
 * second kill). A candidate that never resolves (the boss session
 * itself ends for an unrelated reason) is flushed by
 * SessionRuntimeCoordinator.flushAbandonedBossTaskCandidateIfMatching()
 * rather than silently discarded.
 */
public final class ActivitySignalClassifier
{
	private static final Set<String> COMBAT_SKILLS = new HashSet<>();

	static
	{
		COMBAT_SKILLS.add("attack");
		COMBAT_SKILLS.add("strength");
		COMBAT_SKILLS.add("defence");
		COMBAT_SKILLS.add("ranged");
		COMBAT_SKILLS.add("magic");
		COMBAT_SKILLS.add("hitpoints");
	}

	private final StructuredActivityClassifier structuredActivities =
		new StructuredActivityClassifier(com.osrstelemetry.plugin.activity.StructuredActivityRegistry.defaults());

	public SignalClassification classify(SessionSignal signal, Session current, ClassifierContext context)
	{
		// Structured activities first: null means "not structured-activity
		// business" and the ordinary rules below decide unchanged.
		SignalClassification structured = structuredActivities.classify(signal, current, context);
		if (structured != null)
		{
			return structured;
		}

		switch (signal.getKind())
		{
			case XP_CHANGE:
				return classifyXpChange(signal, current, context);
			case SLAYER_TASK_ASSIGNED:
				context.onSlayerTaskAssigned(signal.getSlayerTaskName(), signal.getSlayerTaskLocation());
				return SignalClassification.ignore();
			case NPC_INTERACTION_TARGET:
				// Context
				// only -- see SignalKind.NPC_INTERACTION_TARGET's own
				// javadoc and ClassifierContext.onNpcInteractionTarget().
				// Never itself a START_OR_HEARTBEAT/REFINE: an interaction
				// alone is not proof of combat (misclicks, bosses with
				// adds, bankers/shopkeepers already filtered out by the
				// collector before this signal is even built).
				context.onNpcInteractionTarget(signal.getNpcId(), signal.getNpcName(), signal.getGameTick(), signal.getObservedAt());
				return SignalClassification.ignore();
			case RAW_COMBAT_XP_OBSERVED:
				// See SignalKind.RAW_COMBAT_XP_OBSERVED's
				// own javadoc.
				return classifyRawCombatXpObserved(signal, current, context);
			case SLAYER_TASK_PROGRESS:
				return classifySlayerTaskProgress(signal, current, context);
			case SLAYER_BRACELET_EFFECT:
				// Annotation of the current Slayer assignment only: never lifecycle
				// evidence, never credited to a non-Slayer session.
				if (current != null && current.getState() != SessionState.FINALIZED
					&& current.getActivityIdentity().getActivityType() == ActivityType.SLAYER
					&& signal.getSlayerBraceletEffect() != null)
				{
					return SignalClassification.metricOnly(MetricUpdate.slayerBracelet(signal.getSlayerBraceletEffect())
						.withReferenceTime(signal.getObservedAt()));
				}
				return SignalClassification.ignore();
			case SLAYER_TASK_COMPLETED:
				// Session-annotation only -- never its own standalone
				// Recent Activity entry by itself
				// -- see classifySlayerTaskCompleted()'s own javadoc.
				return classifySlayerTaskCompleted(signal, current, context);
			case BOSS_KILL:
				return classifyBossKill(signal, current, context);
			case BOSS_ACTIVITY_CONTEXT:
				return classifyBossActivityContext(signal, current);
			case RAID_COMPLETION:
			case ACTIVITY_COMPLETION:
			case QUEST_COMPLETED:
				// These ARE genuinely standalone completions.
				// Their own authoritative completion-count messages are
				// NOT attached to the current combat/slayer/skilling
				// session's aggregates here -- raids/activities have no
				// modeled ActivityIdentity of their own currently, so
				// there is no honest linkage to attach a session-scoped
				// count to; that is deferred to future work that
				// actually models raid/activity identity (see
				// SessionAggregates.ReliableCountKind.COMPLETIONS).
				return SignalClassification.completionOnly(CompletionNature.STANDALONE_ACTIVITY, null);
			case NPC_DEATH:
			case NPC_LOOT_ATTRIBUTED:
				return SignalClassification.ignore();
			case SERVER_NPC_LOOT:
				return classifyServerNpcLoot(signal, current, context);
			case COLLECTION_LOG_NEW_ITEM:
			case COMBAT_ACHIEVEMENT_COMPLETED:
				// No SessionAggregates field exists for these yet --
				// session-irrelevant for now
				// rather than inventing a speculative field.
				return SignalClassification.ignore();
			case STORAGE_SNAPSHOT:
				return SignalClassification.ignore();
			default:
				return SignalClassification.ignore();
		}
	}

	private SignalClassification classifyXpChange(SessionSignal signal, Session current, ClassifierContext context)
	{
		// DELAYED DURABLE-XP SESSION-OWNERSHIP: ROOT CAUSE: XP_CHANGE's own `observedAt` is this event's
		// FLUSH time (when SkillsCollector's slow, ~30s-aggregated
		// window finally closed) -- NOT when the underlying XP was
		// actually earned. Every branch below (Magic's unconditional
		// METRIC_ONLY, ordinary combat-skill evidence, Slayer XP,
		// ordinary skilling XP) ultimately lets its MetricUpdate ride
		// onto whichever session is CURRENT at the moment this signal is
		// classified -- correct when the window and the current session
		// genuinely overlap, but WRONG the instant a real session switch
		// (e.g. an authoritative BOSS_KILL, or a genuine new Slayer
		// task/target) has already happened strictly BETWEEN this
		// window's own start and its eventual flush: the XP was earned
		// under the OLD (by now already-finalized-and-persisted)
		// session, yet nothing previously stopped it from being credited
		// to the NEW one merely because it happened to be PROCESSED
		// after the switch. LIVE EVIDENCE: Zulrah -> Vorkath switch, then
		// a delayed RANGED XP_CHANGE for the Zulrah fight lands on
		// Vorkath; likewise Pyrefiends -> Banshees (new Slayer
		// assignment), then delayed Strength/Hitpoints/Magic/Slayer XP
		// from the finished Pyrefiend fight lands on Banshees.
		//
		// FIX: SessionEventMapper now threads EventPayloads.XpChange's
		// own windowStart through as signal.getXpWindowStart() -- the
		// STRONGEST already-existing timing information available (see
		// SessionSignal's own xpWindowStart javadoc), previously
		// discarded entirely. If this window's own start is BEFORE the
		// current session's own startedAt, the XP was unambiguously
		// earned before this exact session/identity even began -- it
		// cannot honestly belong to it. There is no live handle on the
		// OLD session left to reattach it to by this point (a real
		// switch FINALIZES and durably persists the old session
		// synchronously, at the moment of the switch -- see
		// SessionLifecycleEngine's own "real switch" branches -- so it is
		// already gone from memory long before a separately-batched,
		// later-arriving delayed XP_CHANGE like this one is ever
		// classified); rather than fabricate a new ownership-reassignment
		// mechanism for an already-immutable, already-persisted record
		// (out of scope for this fix), this is classified as a plain
		// IGNORE_FOR_SESSION: no metric anywhere, no identity effect, and
		// -- since SessionRuntimeCoordinator.applyMetrics() only ever
		// reconciles LiveXpTracker for a metric that actually gets
		// applied -- the new session's own live-pending XP is left
		// completely untouched by it (see LiveXpDisplayIntegrationTest's
		// own "delayed XP_CHANGE after a switch" tests).
		//
		// SCOPE: only guards against a window that predates the CURRENT
		// session's own startedAt. `current == null` (nothing to compare
		// against) and a null xpWindowStart (every pre-existing
		// caller/test, which never opted into this field) both leave
		// this guard a complete no-op -- every other branch below is
		// entirely unaffected, and the false-Slayer-promotion fix,
		// EvidenceStrength/T2-candidate semantics, and boss/Slayer
		// affinity logic are untouched.
		//
		// XP_CHANGE WINDOW/SESSION-BOUNDARY SPLIT: a window starting before the current
		// session's own startedAt is not always ENTIRELY stale -- the
		// aggregation window can SPAN the switch (open under the OLD
		// session, close/flush after the new one is already current),
		// in which case some of its delta was genuinely earned AFTER the
		// switch and legitimately belongs here. ClassifierContext holds
		// an exact per-skill "XP at session start" baseline, captured by
		// SessionRuntimeCoordinator at the precise instant this exact
		// session began (see ClassifierContext.noteSessionSwitchXpBaseline()'s
		// own javadoc). Given that baseline and this event's own absolute
		// newXp (signal.getXpNewValue()), the portion earned after the
		// switch is EXACTLY `newXp - xpAtSessionStart` -- never a
		// proportional/time-based guess (we deliberately do not know
		// when within the window the XP was earned, only the two exact
		// endpoints this comparison needs).
		if (spansSessionStart(signal, current))
		{
			String spanningSkill = signal.getSkill();
			Long xpAtSessionStart = context.getXpAtSessionStart(current.getSessionId(), spanningSkill);
			if (xpAtSessionStart == null || signal.getXpNewValue() == null)
			{
				// No exact baseline available for this skill/session (an
				// older/synthetic caller that never opted into
				// xpNewValue, or this skill was never observed via a raw
				// StatChanged pulse before the switch happened) -- an
				// exact split is impossible without guessing, so this
				// conservatively falls back to the whole-window drop.
				// Rare in real play (RuneLite
				// fires StatChanged on every XP gain, so any skill that
				// actually gained XP under the old session would already
				// have seeded this baseline), but honestly acknowledged
				// rather than silently assumed away.
				return SignalClassification.ignore();
			}
			long postSwitchDelta = signal.getXpNewValue() - xpAtSessionStart;
			if (postSwitchDelta <= 0)
			{
				// The entire window's XP was earned at or before the
				// switch (case A: wholly stale) -- nothing here
				// legitimately belongs to the current session.
				return SignalClassification.ignore();
			}
			// Case B (spanning): only the EXACT post-switch portion is
			// credited, as a metric only -- this XP already occurred
			// under whatever identity the current session already has
			// (established by the real evidence that caused the switch
			// itself), so it never needs to re-propose/refine identity,
			// exactly like classifySlayerXp()'s own METRIC_ONLY pattern
			// for evidence that is real but not itself lifecycle-carrying.
			return SignalClassification.metricOnly(MetricUpdate.xp(spanningSkill, postSwitchDelta));
		}

		String skill = signal.getSkill();
		MetricUpdate metric = xpMetric(signal);

		if (isCombatSkill(skill))
		{
			// MAGIC XP IS LIFECYCLE-AMBIGUOUS, NOT LIFECYCLE PROOF.
			// Two live incidents established this:
			// first, a POH-teleport MAGIC +30 XP_CHANGE with a Slayer task
			// merely ASSIGNED fabricated a brand-new SLAYER/<task> session
			// (Magic never again computes
			// slayerIdentity() from tracked-task context alone). Second,
			// with NO current session at all, that same bare MAGIC +30
			// was still found to independently start a fresh generic
			// COMBAT session -- also false: a teleport, alchemy cast,
			// enchantment, or other utility spell is not proof of combat
			// either. MAGIC is the one COMBAT_SKILLS member with
			// substantial non-combat XP sources; ATTACK/STRENGTH/DEFENCE/
			// RANGED/HITPOINTS are audited and unaffected below -- they
			// remain reliably combat-sourced and keep the ordinary
			// slayerIdentity()/genericCombatIdentity() + decideCombatBranch()
			// path exactly as before.
			//
			// THE RULE: Magic XP by itself is a METRIC, never lifecycle
			// proof. It must never independently start COMBAT, start
			// SLAYER, resume a SUSPENDED COMBAT/SLAYER/BOSSING session, or
			// heartbeat/extend an ACTIVE session's duration purely because
			// Magic XP appeared -- whether or not a Slayer task is
			// tracked. So Magic XP is classified as METRIC_ONLY
			// unconditionally here: it is NEVER added to
			// SessionSignalBatchResolver's byIdentity map (only
			// START_OR_HEARTBEAT/REFINE classifications are), so it can
			// never itself win, extend, or resume a batch's lifecycle
			// outcome -- but its MetricUpdate is never null, so
			// SessionSignalBatchResolver still collects it into every
			// batch's metricUpdates unconditionally (its own
			// unconditional-metrics rule), and SessionRuntimeCoordinator's
			// existing RESOLVED/NO_EVIDENCE/AMBIGUOUS dispatch (completely
			// unchanged by this fix) already does exactly the right thing
			// with it in every case:
			//   - Same batch as trustworthy combat evidence (e.g. real
			//     HITPOINTS XP) that RESOLVES the batch to a winning
			//     identity: Magic's metric rides along in that same
			//     batch's metricUpdates and is credited to the newly-
			//     established/continued session exactly once, via
			//     engine.onQualifyingActivity()/refineIdentity()'s own
			//     metricsForCurrent handling.
			//   - No winning identity this batch (Magic is the ONLY
			//     evidence, or all evidence is otherwise ambiguous): a
			//     NO_EVIDENCE/AMBIGUOUS outcome, so no lifecycle transition
			//     happens at all -- the current session (if any) keeps its
			//     exact state, lastActiveAt untouched, ACTIVE stays ACTIVE
			//     and SUSPENDED stays SUSPENDED -- and the metric is
			//     credited directly to whatever session is ALREADY current
			//     (never fabricating one; silently dropped, exactly like
			//     classifySlayerXp()'s own no-session precedent, when
			//     there is no current session at all to attach it to).
			// No new code was needed in SessionSignalBatchResolver,
			// SessionLifecycleEngine, or SessionRuntimeCoordinator -- this
			// is the narrowest fix: purely how classifyXpChange()
			// classifies one skill.
			if (isMagicXpSkill(skill))
			{
				return SignalClassification.metricOnly(metric);
			}
			// GENERIC NPC RECOGNITION: when no fresh
			// recent NPC target is tracked, this falls back to the single
			// fixed genericCombatIdentity() ("Combat"). Otherwise it
			// prefers a NAMED generic identity for whatever attackable
			// NPC the player most recently, and still RECENTLY, interacted
			// with (see ClassifierContext.peekRecentTargetNpcNameIfFresh()
			// for the exact bounded/sliding-window rule) -- with ZERO
			// hand-maintained NPC name/ID table anywhere: the name comes
			// straight from RuneLite's own NPCComposition at interaction
			// time (see NpcInteractionTargetCollector), and
			// genericNpcCombatIdentity() below does nothing but normalize
			// it exactly the way bossIdentity()/slayerIdentity() already
			// normalize their own display names.
			//
			// FALSE SLAYER PROMOTION FROM ASSIGNMENT CONTEXT.
			// REMOVED: this branch used to prefer
			// slayerIdentity(context.getActiveSlayerTaskName(), ...)
			// whenever context.hasReliableActiveSlayerTask() was true --
			// i.e. whenever ANY Slayer task was merely ASSIGNED, however
			// long ago, regardless of what the player was actually
			// fighting. LIVE EVIDENCE: task assigned = Gargoyles, player
			// fighting a Desert Wolf then a Goat (correctly recognized as
			// COMBAT/Desert Wolf, then COMBAT/Goat, via genuine recent-NPC-
			// target evidence) -- ordinary combat XP_CHANGE for the Goat
			// fight nonetheless computed identity = SLAYER/Gargoyles here,
			// which decideCombatBranch() then REFINED into immediately
			// (generic-COMBAT -> SLAYER is an unconditional refine, no
			// candidate arm/confirm gate applies to a REFINE), silently
			// converting the whole session to a bogus SLAYER/Gargoyles
			// session -- with zero Gargoyles ever fought. A currently
			// assigned Slayer task is CONTEXT ONLY (see
			// ClassifierContext.hasReliableActiveSlayerTask()'s own
			// javadoc) -- it must never, by itself, promote ordinary
			// combat XP into that task's SLAYER identity. Only genuine,
			// specific Slayer lifecycle evidence -- SLAYER_TASK_PROGRESS,
			// handled entirely separately by classifySlayerTaskProgress()
			// below, completely unaffected by this fix -- may ever
			// establish/upgrade a SLAYER identity. This is exactly the
			// same "context/interaction alone is never proof" principle
			// NPC_INTERACTION_TARGET already enforces for generic NPC
			// recognition (see that SignalKind's own javadoc) -- an
			// assigned-but-not-yet-progressed Slayer task is no more
			// proof of current activity than a stale interaction target
			// is. context.hasReliableActiveSlayerTask()/getActiveSlayerTaskName()/
			// getActiveSlayerTaskLocation() are UNCHANGED and still
			// populated from SLAYER_TASK_ASSIGNED/SLAYER_TASK_PROGRESS --
			// this fix removes this method's own (sole) READ of them, not
			// the tracking itself; the active task remains available as
			// context for anything that legitimately needs it elsewhere
			// (e.g. SlayerCollector's own persisted current-task state and
			// NpcDeathCollector's activeSlayerTaskName annotation, both
			// entirely independent of ClassifierContext/this classifier).
			ActivityIdentity identity = genericCombatOrNpcIdentity(context, signal.getGameTick(), signal.getObservedAt());
			// EVIDENCE STRENGTH: ORDINARY
			// -- inferred combat XP, never itself proof of a specific
			// identity (see EvidenceStrength's own javadoc). This is the
			// SAME tier ordinary skilling XP gets below, deliberately: both
			// are provisional, non-authoritative telemetry. `false` here
			// (fromAuthoritativeTaskProgress) for the same reason as
			// always -- this is never a direct, per-event authoritative
			// claim; only classifySlayerTaskProgress() below passes `true`.
			return decideCombatBranch(identity, current, singleMetric(metric), false, EvidenceStrength.ORDINARY);
		}

		// Live evidence: a
		// delayed SLAYER XP_CHANGE (Slayer's own skill XP -- distinct
		// from SLAYER_TASK_PROGRESS, which is raw task-decrement
		// telemetry, never Slayer's XP skill) arrived after a
		// BOSS_KILL had already established a fresh BOSSING session,
		// and independently proposed SKILLING/slayer as a real switch
		// -- destroying the just-created BOSSING session. Root cause:
		// "slayer" is a real OSRS skill (it has its own XP), so it is
		// NOT in COMBAT_SKILLS above, and previously fell straight
		// into classifyNonCombatXp() exactly like Woodcutting or
		// Mining -- treating it as ordinary, identity-establishing
		// SKILLING lifecycle evidence. Slayer XP is frequently DELAYED
		// telemetry associated with combat/Slayer/bossing that has
		// already been correctly classified from stronger evidence
		// (SLAYER_TASK_PROGRESS, BOSS_KILL, combat XP) -- it must never
		// independently create or switch to SKILLING/slayer, and must
		// never be treated as equivalent to SLAYER_TASK_PROGRESS (task
		// identity is never inferred from it).
		if (isSlayerXpSkill(skill))
		{
			return classifySlayerXp(metric, current);
		}

		return classifyNonCombatXp(skill, metric, current);
	}

	/**
	 * Slayer XP is always a
	 * valid XP metric, but is NEVER sufficient lifecycle evidence on
	 * its own. If a combat-branch (COMBAT/SLAYER/BOSSING) session is
	 * already current -- ACTIVE or SUSPENDED, mirroring
	 * decideCombatBranch()'s own "SUSPENDED still counts" treatment of
	 * FINALIZED as the only non-current state -- the XP attaches to it
	 * as a metric only, never touching identity (e.g. an
	 * ACTIVE BOSSING/SLAYER session with delayed Slayer XP remains
	 * exactly as it was). With no compatible combat-branch session
	 * (none at all, a FINALIZED one, or a current SKILLING session),
	 * Slayer XP alone starts and switches nothing -- it is simply
	 * dropped for session purposes (SLAYER
	 * XP alone with no session does not create SKILLING/slayer).
	 */
	/** True when an XP window began before the current session did (see classifyXpChange). */
	static boolean spansSessionStart(SessionSignal signal, Session current)
	{
		return current != null && signal.getXpWindowStart() != null
			&& signal.getXpWindowStart().isBefore(current.startedAtInstant());
	}

	/**
	 * The XP metric one (non-spanning) XP_CHANGE contributes. Reference time
	 * = the XP window's own start (when this XP began accruing), else the
	 * event time -- see MetricUpdate#referenceTime.
	 */
	static MetricUpdate xpMetric(SessionSignal signal)
	{
		long delta = signal.getXpDelta() == null ? 0L : signal.getXpDelta();
		return MetricUpdate.xp(signal.getSkill(), delta)
			.withReferenceTime(signal.getXpWindowStart() != null ? signal.getXpWindowStart() : signal.getObservedAt());
	}

	private SignalClassification classifySlayerXp(MetricUpdate metric, Session current)
	{
		if (current != null
			&& current.getState() != SessionState.FINALIZED
			&& ActivityPrecedence.isCombatBranch(current.getActivityIdentity().getActivityType()))
		{
			return SignalClassification.metricOnly(metric);
		}
		return SignalClassification.ignore();
	}

	/**
	 * "slayer" is Slayer's own OSRS skill (distinct from Attack/
	 * Strength/etc combat skills, and distinct from the raw
	 * SLAYER_TASK_PROGRESS/SLAYER_TASK_ASSIGNED/SLAYER_TASK_COMPLETED
	 * event types) -- deliberately its own small check rather than
	 * folded into COMBAT_SKILLS, since it must NOT go through
	 * decideCombatBranch()'s refine/switch machinery like a real
	 * combat skill would; see classifySlayerXp()'s own javadoc for the
	 * fix this exists for.
	 */
	static boolean isSlayerXpSkill(String skill)
	{
		return skill != null && "slayer".equals(skill.trim().toLowerCase(Locale.ROOT));
	}

	/**
	 * Guards against utility Magic XP fabricating a specific Slayer
	 * session: "magic" is the one COMBAT_SKILLS member with substantial
	 * non-combat XP sources (teleports, alchemy, enchanting, other
	 * utility spellcasting) -- see classifyXpChange()'s own audit note
	 * for the live bug this exists to fix. Deliberately its own small
	 * check, mirroring isSlayerXpSkill()'s style, rather than a
	 * broader/implicit rule -- Attack/Strength/Defence/Ranged/Hitpoints
	 * are audited and unaffected: they remain reliable enough to be
	 * promoted straight to an assigned Slayer task's specific identity.
	 */
	static boolean isMagicXpSkill(String skill)
	{
		return skill != null && "magic".equals(skill.trim().toLowerCase(Locale.ROOT));
	}

	private SignalClassification classifyNonCombatXp(String skill, MetricUpdate metric, Session current)
	{
		// EVIDENCE STRENGTH: ordinary
		// skill XP is ORDINARY by definition -- consistent with
		// incidental (never itself-proof) evidence, and this is the exact
		// signal kind the live bug (one incidental AGILITY tick
		// finalizing an ACTIVE combat-branch session) was made of. This is
		// the ONE tag that actually alters observable behavior --
		// everywhere else, EvidenceStrength is
		// plumbing that reproduces the existing gate, not a new
		// gate. See SessionLifecycleEngine's own javadoc for how this tag
		// is consumed.
		ActivityIdentity identity = skillingIdentity(skill);
		if (current != null && current.getState() != SessionState.FINALIZED && identity.equals(current.getActivityIdentity()))
		{
			return SignalClassification.startOrHeartbeat(identity, metric, EvidenceStrength.ORDINARY);
		}
		// Different skill (or no current session): the earlier example
		// (Woodcutting -> Mining) is a real switch, not a refinement --
		// SKILLING has no internal specificity hierarchy. See this
		// class's javadoc for the same-tick-batching caveat that is
		// what actually protects incidental secondary XP from
		// fragmenting a session, not this method.
		return SignalClassification.startOrHeartbeat(identity, metric, EvidenceStrength.ORDINARY);
	}

	private SignalClassification classifySlayerTaskProgress(SessionSignal signal, Session current, ClassifierContext context)
	{
		// Threads this
		// event's own currentRemaining through to ClassifierContext so
		// classifySlayerTaskCompleted() below can later reconcile a
		// final task unit RuneLite never reports its own trailing
		// SLAYER_TASK_PROGRESS for -- see that method's own javadoc.
		context.onSlayerTaskProgress(signal.getSlayerTaskName(), signal.getSlayerTaskLocation(), signal.getSlayerCurrentRemaining());
		ActivityIdentity identity = slayerIdentity(signal.getSlayerTaskName(), signal.getSlayerTaskLocation());
		// signal.getSlayerUnitsConsumed() carries this ONE
		// event's own taskUnitsConsumed (see SessionSignal.slayerTaskProgress()'s
		// javadoc) -- passed straight through unmodified, never
		// re-derived from any absolute remaining/initial value here.
		// Slayer "task remaining" display: signal.getSlayerCurrentRemaining()
		// carries this same event's own authoritative currentRemaining
		// (nullable -- absent for older/synthetic callers), threaded
		// through into the same MetricUpdate so SessionAggregateUpdater
		// can retain the latest value for the player-facing display,
		// completely independent of the accumulated slayerProgressDelta
		// below.
		// Reference time = the event's own time: if this progress reaches
		// remaining 0 it IS the completion, and the record's completedAt
		// (which bounds final-kill XP crediting) must be stamped from it.
		MetricUpdate metric = signal.getSlayerUnitsConsumed() == null
			? null
			: MetricUpdate.slayerProgress(signal.getSlayerUnitsConsumed(), signal.getSlayerCurrentRemaining())
				.withReferenceTime(signal.getObservedAt());

		// BOSS SELF-CONSUMPTION OF ITS OWN SLAYER TASK -- a regression
		// introduced by the GG ->
		// Gargoyles fix below: that fix made ANY differently-named
		// SLAYER_TASK_PROGRESS switch an ACTIVE BOSSING session away
		// unconditionally -- correct for a genuinely different NPC (a
		// real Gargoyle kill after leaving Grotesque Guardians), but
		// WRONG for Grotesque Guardians' OWN kills, which ALSO decrement
		// the Gargoyles Slayer task (GG is a Slayer-task boss for
		// Gargoyles). Both cases produce an IDENTICAL event -- there is
		// no way to tell them apart from this one signal alone. See
		// BossTaskAffinity's own javadoc for the general (not
		// GG-specific) boss-owns-task data this relies on.
		//
		// SUSPENDED boss-own-task reactivation: live-persisted repro: a
		// SUSPENDED BOSSING/Shellbane Gryphon session, still well inside
		// its 30-minute resume window, received its own confirmed task's
		// SLAYER_TASK_PROGRESS ("Gryphons") and was immediately FINALIZED
		// -- creating the exact same zero-duration SLAYER bridge session
		// the ACTIVE-path fix above already eliminates, just crossing the
		// SUSPENDED lifecycle boundary instead. Root cause: this guard
		// previously required `current.getState() == ACTIVE` before ever
		// consulting BossTaskAffinity at all, so a SUSPENDED boss session
		// fell straight through to the unconditional-switch path at the
		// bottom of this method (`true` below), which decideCombatBranch()
		// then resolves via its own SUSPENDED "specific-vs-specific"
		// branch -- correctly treating GENUINELY different specific
		// evidence as a real switch while SUSPENDED (see that branch's
		// own "FOLLOW-UP FIX" comment), but with no way to know THIS
		// evidence was already-verified self-consumption, since it was
		// never given the chance to check.
		//
		// The fix widens this guard to ACTIVE OR SUSPENDED (both are
		// "still in progress" from BossTaskAffinity's point of view --
		// SessionRuntimeCoordinator/SessionLifecycleEngine never hand a
		// SUSPENDED session whose resume window has already expired to
		// the classifier at all; see decideCombatBranch()'s own
		// null/FINALIZED fast path and this class's expiredUnrelatedSession
		// test for that guarantee), and -- rather than routing through
		// decideCombatBranch()'s shared, STATE-DEPENDENT default -- returns
		// a heartbeat of the current boss identity directly. For ACTIVE
		// this is byte-for-byte the classification decideCombatBranch()
		// already produced here (its own lessSpecific/ACTIVE "never
		// downgrade" fallthrough, since fromAuthoritativeTaskProgress is
		// false and metrics is empty), so ACTIVE behavior is completely
		// unchanged. For SUSPENDED, this makes the already-verified
		// self-consumption case independent of decideCombatBranch()'s
		// SUSPENDED default entirely -- SessionLifecycleEngine's own
		// exact-identity-match resume path (onQualifyingActivity()'s
		// SUSPENDED branch: `identity.equals(current.getActivityIdentity())`)
		// is what actually reactivates the SUSPENDED session back to
		// ACTIVE, preserving its sessionId, startedAt, and every prior
		// aggregate untouched -- exactly like any other same-identity
		// resume, with zero new timers or confirmation-count logic.
		//
		// When the current ACTIVE or (still resumable) SUSPENDED session
		// is BOSSING for a boss confirmed to consume its own named task,
		// this progress no longer gets suppressed and buffered pending
		// disambiguation (the historical behavior described above): under
		// boss-on-task Slayer ownership the session is refined in place into
		// the Slayer identity -- see the branch body below. The
		// ClassifierContext boss-task candidate and its consumers
		// (classifyBossKill(), classifyServerNpcLoot(),
		// SessionSignalBatchResolver.applyBossSelfConsumptionCorroboration())
		// are retained but are no longer armed by this path.
		//
		// Every OTHER SLAYER_TASK_PROGRESS -- naming a task the current
		// boss is NOT confirmed to consume itself, or arriving with no
		// current ACTIVE/SUSPENDED BOSSING session at all -- is
		// completely unaffected and keeps the exact immediate-switch
		// behavior the prior fix established (`true` below, unchanged):
		// a SUSPENDED boss session receiving genuinely unrelated Slayer
		// progress, or a SUSPENDED unrelated boss receiving this boss's
		// task progress, still transitions normally.
		if (current != null
			&& (current.getState() == SessionState.ACTIVE || current.getState() == SessionState.SUSPENDED)
			&& current.getActivityIdentity().getActivityType() == ActivityType.BOSSING
			&& BossTaskAffinity.isBossOwnTask(current.getActivityIdentity().getActivityKey(), signal.getSlayerTaskName()))
		{
			// BOSS-ON-TASK SLAYER OWNERSHIP (supersedes the earlier
			// suppress-and-disambiguate buffering for this case). The product
			// rule is now: when the player's active Slayer assignment is
			// compatible with a boss (the boss is a member of that task's
			// family -- BossTaskAffinity), SLAYER owns the encounter. This
			// progress names exactly such an assignment, so the old ambiguity
			// ("was this the boss's own kill or a different NPC on the same
			// task?") no longer changes the owner: either way the kill belongs
			// to that Slayer assignment. The boss session is therefore REFINED
			// in place into the Slayer identity -- same sessionId, same
			// startedAt, same aggregates (its boss loot seeds the assignment
			// ledger on the next applyMetrics) -- never finalized, never
			// replaced by a fresh session. This progress' own metric rides
			// along immediately; nothing is buffered. Covers the cold-start
			// case (a boss kill seen before any Slayer session exists, e.g.
			// right after login). Same-tick boss evidence is folded into this
			// refine by SessionSignalBatchResolver.applyBossOnTaskSlayerOwnership().
			context.clearBossTaskCandidate();
			return SignalClassification.refine(identity, singleMetric(metric), EvidenceStrength.SPECIFIC);
		}

		// GG -> Gargoyles activity-switch: `true`
		// here -- see this class's own javadoc for the full rationale.
		// SLAYER_TASK_PROGRESS is direct, per-kill telemetry naming a
		// specific task; it is allowed to switch an ACTIVE, more-specific
		// (BOSSING) session away, unlike inferred combat-XP-under-a-
		// tracked-task evidence (classifyXpChange() above, which always
		// passes `false`).
		// EVIDENCE STRENGTH: SPECIFIC -- direct, per-kill telemetry naming
		// this specific task, not itself a completion (that's BOSS_KILL's
		// own AUTHORITATIVE tier below).
		return decideCombatBranch(identity, current, singleMetric(metric), true, EvidenceStrength.SPECIFIC);
	}

	/**
	 * Reproducible SLAYER_TASK_COMPLETED remaining=1 bug. Live evidence:
	 * task progress counts down normally (e.g. 2 -&gt; 1), then RuneLite
	 * emits SLAYER_TASK_COMPLETED with NO final 1 -&gt; 0
	 * SLAYER_TASK_PROGRESS ever observed -- so, without this handling,
	 * latestSlayerCurrentRemaining would stay stuck at 1 forever and
	 * slayerProgressDelta would permanently miss the task's final unit.
	 *
	 * For a RELIABLY MATCHING current Slayer session/task only --
	 * `current` is non-FINALIZED, its own ActivityIdentity is SLAYER, it
	 * equals slayerIdentity(context's own currently-tracked task/
	 * location), AND this completion event's own taskName (raw, from the
	 * real RuneLite event -- see SessionSignal.slayerTaskCompleted()'s
	 * own javadoc; NOTE the real production event carries no
	 * taskLocation at all, which is exactly why this match is done by
	 * NAME against context's own tracked task rather than by comparing
	 * ActivityIdentity keys directly) names that SAME tracked task --
	 * this emits a MetricUpdate.slayerProgress() that:
	 *   - forces latestSlayerCurrentRemaining to exactly 0 (a task is
	 *     unconditionally fully done on SLAYER_TASK_COMPLETED), and
	 *   - adds context's own last-known currentRemaining (from the most
	 *     recent SLAYER_TASK_PROGRESS for this task, 0 when none was ever
	 *     observed) to slayerProgressDelta EXACTLY ONCE -- the exact
	 *     outstanding unit(s) no trailing PROGRESS event ever reported.
	 * If a normal PROGRESS event already reached 0 before this
	 * completion arrives, the last-known remaining is already 0, so this
	 * adds zero -- no double-counting.
	 *
	 * When the match is NOT reliable (no current session, a different
	 * task/location, a non-SLAYER or FINALIZED current identity -- e.g.
	 * an ACTIVE boss self-consuming its own task, see BossTaskAffinity)
	 * no metric is emitted at all: remaining/delta are left completely
	 * untouched rather than inventing a count for a session this event
	 * cannot be reliably shown to belong to. This never finalizes
	 * `current` itself -- ordinary lifecycle/suspend/resume logic is
	 * completely unchanged; final-kill loot/XP may still legitimately
	 * arrive after this event.
	 *
	 * context.onSlayerTaskCompleted() is called AFTER the match/metric
	 * computation above (never before) so this method can still read
	 * context's own pre-completion tracked task/location/remaining.
	 */
	private SignalClassification classifySlayerTaskCompleted(SessionSignal signal, Session current, ClassifierContext context)
	{
		MetricUpdate metric = null;
		// A cancelled/blocked task was never finished: no outstanding units
		// are credited and remaining is not forced to 0 (so the record is
		// never COMPLETED); the next real assignment marks it Skipped.
		if (!signal.isSlayerTaskCancelled()
			&& current != null
			&& current.getState() != SessionState.FINALIZED
			&& current.getActivityIdentity().getActivityType() == ActivityType.SLAYER
			&& context.hasReliableActiveSlayerTask()
			&& current.getActivityIdentity().equals(slayerIdentity(context.getActiveSlayerTaskName(), context.getActiveSlayerTaskLocation()))
			&& normalizedSlayerTaskNamesEqual(signal.getSlayerTaskName(), context.getActiveSlayerTaskName()))
		{
			Integer lastKnownRemaining = context.getLastKnownSlayerCurrentRemaining();
			int outstandingUnits = lastKnownRemaining == null ? 0 : Math.max(0, lastKnownRemaining);
			metric = MetricUpdate.slayerProgress(outstandingUnits, 0).withReferenceTime(signal.getObservedAt());
		}
		context.onSlayerTaskCompleted();
		return SignalClassification.completionOnly(CompletionNature.SESSION_ANNOTATION_ONLY, metric);
	}

	private static boolean normalizedSlayerTaskNamesEqual(String a, String b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		return a.trim().toLowerCase(Locale.ROOT).equals(b.trim().toLowerCase(Locale.ROOT));
	}

	private SignalClassification classifyBossKill(SessionSignal signal, Session current, ClassifierContext context)
	{
		ActivityIdentity identity = bossIdentity(signal.getBossOrActivitySource());
		// Boss self-consumption of its own Slayer task: a
		// same-boss authoritative BOSS_KILL is exactly the disconfirming
		// evidence that proves a pending boss-task candidate (see
		// ClassifierContext's own javadoc) was genuine self-consumption,
		// not a real different NPC -- abort it.
		//
		// CANDIDATE-METRIC BUFFERING: the candidate's own
		// buffered metric(s) (the ambiguous kill's Slayer progress delta
		// + currentRemaining, never applied anywhere while pending) are
		// retrieved BEFORE clearing and combined with this SAME kill's
		// own reliableCount metric -- both are destined for the SAME
		// session (this boss never left BOSSING, so this is a
		// delayed-but-correct application, never a retroactive
		// correction of anything already applied elsewhere).
		List<MetricUpdate> bufferedProgress = Collections.<MetricUpdate>emptyList();
		if (context.hasBossTaskCandidateFor(identity))
		{
			bufferedProgress = context.getPendingBossTaskCandidateMetrics();
			context.clearBossTaskCandidate();
		}
		MetricUpdate killMetric = signal.getReliableCount() == null
			? null
			: MetricUpdate.reliableCount(SessionAggregates.ReliableCountKind.KILLS, identity.getActivityKey(), signal.getReliableCount());
		// EVIDENCE STRENGTH: AUTHORITATIVE -- a hard completion signal for
		// exactly this identity. Always switches/refines immediately,
		// never gated by any candidate mechanism.
		return decideCombatBranch(slayerOwnerOrBoss(identity, current), current, combineMetrics(bufferedProgress, killMetric), false, EvidenceStrength.AUTHORITATIVE);
	}

	/**
	 * The
	 * signal's ENTIRE session-lifecycle contribution: build the
	 * candidate boss identity via the SAME bossIdentity() canonicalization
	 * BOSS_KILL already uses (no duplicated normalization logic), then
	 * hand it to the SAME shared decideCombatBranch() refine-vs-switch-
	 * vs-ignore machinery XP_CHANGE, SLAYER_TASK_PROGRESS, and BOSS_KILL
	 * already go through -- no new session-lifecycle logic is introduced
	 * here or anywhere else. This is what lets an already-tracked SLAYER
	 * session correctly be outranked/refined into BOSSING by this signal
	 * exactly as it already is by a real BOSS_KILL (ActivityPrecedence:
	 * BOSSING rank 2 &gt; SLAYER rank 1).
	 *
	 * `metric` is passed as null UNCONDITIONALLY -- never derived from
	 * signal.getReliableCount() the way classifyBossKill() does, since
	 * SessionSignal.bossActivityContext() never sets reliableCount in
	 * the first place (see its own javadoc). This structurally
	 * guarantees this signal can never produce a
	 * MetricUpdate.reliableCount(...) instance, and therefore can never
	 * touch SessionAggregates' reliableCount -- not merely by
	 * convention, but because no code path from this method ever
	 * constructs one.
	 */
	private SignalClassification classifyBossActivityContext(SessionSignal signal, Session current)
	{
		ActivityIdentity identity = bossIdentity(signal.getBossOrActivitySource());
		// EVIDENCE STRENGTH: SPECIFIC -- direct, per-event telemetry that
		// specifically names this boss, but is not itself a completion
		// (see EvidenceStrength's own javadoc example, which is this
		// exact case).
		return decideCombatBranch(slayerOwnerOrBoss(identity, current), current, Collections.<MetricUpdate>emptyList(), false, EvidenceStrength.SPECIFIC);
	}

	/**
	 * BOSS-ON-TASK SLAYER OWNERSHIP. Returns the identity that owns evidence
	 * naming `bossIdentity`: the CURRENT Slayer session's identity when that
	 * session is still in progress (ACTIVE, or SUSPENDED inside its resume
	 * window -- the classifier is never handed an expired one) and its
	 * assignment is compatible with the boss (the boss belongs to that
	 * task's family per BossTaskAffinity / SlayerTaskFamilyRegistry -- e.g.
	 * Kraken on Cave kraken, Cerberus on Hellhounds, Vorkath on Blue
	 * dragons); otherwise `bossIdentity` itself, unchanged.
	 *
	 * Root cause this closes: decideCombatBranch() deliberately treats
	 * SLAYER -&gt; BOSSING as a real switch ("unknown compatibility means
	 * switch"). With no compatibility check, the first Kraken evidence on a
	 * Cave kraken assignment displaced the broader Slayer session -- parked
	 * it when ACTIVE, and FINALIZED it into History when it was SUSPENDED
	 * (SessionLifecycleEngine finalizes, never parks, on specific evidence
	 * against a SUSPENDED session) -- and minted a standalone boss session.
	 * Returning the Slayer identity instead makes the boss evidence an
	 * ordinary same-identity heartbeat (or SUSPENDED resume) of that
	 * session. Generic membership lookup only -- no boss name appears here.
	 */
	private static ActivityIdentity slayerOwnerOrBoss(ActivityIdentity bossIdentity, Session current)
	{
		if (current != null
			&& (current.getState() == SessionState.ACTIVE || current.getState() == SessionState.SUSPENDED)
			&& current.getActivityIdentity().getActivityType() == ActivityType.SLAYER
			&& BossTaskAffinity.isBossOwnTask(bossIdentity.getActivityKey(), current.getActivityIdentity().getDisplayName()))
		{
			return current.getActivityIdentity();
		}
		return bossIdentity;
	}

	private SignalClassification classifyServerNpcLoot(SessionSignal signal, Session current, ClassifierContext context)
	{
		// Metric-only for an ALREADY-compatible ACTIVE session;
		// never starts/resumes/refines by itself. "Compatible" here
		// simply means "there is a currently ACTIVE session to attach
		// this loot to" -- SERVER_NPC_LOOT carries no ActivityIdentity
		// of its own to compare against.
		if (current == null || current.getState() != SessionState.ACTIVE)
		{
			return SignalClassification.ignore();
		}
		if (signal.getLootDrops() == null || signal.getLootDrops().isEmpty())
		{
			return SignalClassification.ignore();
		}

		// Boss self-consumption of its own Slayer task, combined with
		// CANDIDATE-METRIC BUFFERING: this
		// loot's own sourceName is exactly the disambiguating evidence a
		// pending boss-task candidate (see ClassifierContext's own
		// javadoc) has been waiting for, WHEN it is genuinely NOT the
		// boss itself (nor one of its known multi-NPC aliases -- see
		// BossTaskAffinity.isBossOwnNpcName()). That proves the earlier
		// suppressed SLAYER_TASK_PROGRESS came from a real, different NPC
		// -- confirm the candidate now: the switch happens here, anchored
		// at THIS loot's own observedAt. The earlier progress event's own
		// metric was never applied anywhere while pending (see
		// classifySlayerTaskProgress()) -- it is retrieved from the
		// candidate here and combined with this loot's own confirming
		// metric, both riding onto the brand-new Slayer session below.
		// This is what closes the former "stranded on the boss session"
		// limitation: the ambiguous kill's own progress now belongs to
		// the session it actually turned out to be.
		if (current.getActivityIdentity().getActivityType() == ActivityType.BOSSING
			&& context.hasBossTaskCandidateFor(current.getActivityIdentity())
			&& !BossTaskAffinity.isBossOwnNpcName(current.getActivityIdentity().getActivityKey(), signal.getBossOrActivitySource()))
		{
			// CANDIDATE-METRIC BUFFERING: the candidate's
			// own buffered metric(s) -- the ambiguous kill's Slayer
			// progress delta + currentRemaining, never applied anywhere
			// while pending -- are retrieved BEFORE clearing and combined
			// with THIS loot's own confirming metric, both destined for
			// the brand-new Slayer session: it now correctly shows
			// slayerProgressDelta/latestSlayerCurrentRemaining immediately
			// upon confirmation, never waiting for a second kill.
			ActivityIdentity candidate = context.getPendingBossTaskCandidateSlayerIdentity();
			List<MetricUpdate> bufferedProgress = context.getPendingBossTaskCandidateMetrics();
			context.clearBossTaskCandidate();
			MetricUpdate confirmingMetric = MetricUpdate.loot(signal.getBossOrActivitySource(), signal.getObservedAt(), signal.getLootDrops());
			// EVIDENCE STRENGTH: SPECIFIC -- this loot's own sourceName is
			// direct, per-kill corroboration of a genuinely different NPC,
			// confirming the real switch (not itself a completion signal
			// the way an authoritative BOSS_KILL/reliable count is).
			return SignalClassification.startOrHeartbeat(candidate, combineMetrics(bufferedProgress, confirmingMetric), EvidenceStrength.SPECIFIC);
		}

		// OFF-TASK LOOT: a Slayer session does not OWN loot whose source NPC
		// is provably another task's target (KNOWN_MISMATCH). Loot is never
		// lifecycle evidence, so this cannot switch or suspend anything; it is
		// a Current Session ownership decision only (the raw event and Loot
		// Tracker are separate EventLedger consumers). The identity stays the
		// just-completed task through AWAITING_TASK, so a final kill's loot
		// arriving after completion still validates. MATCH and UNKNOWN keep
		// the existing crediting (a false rejection would silently lose loot).
		// rejectOwnership(), not ignore(): see SignalClassification#ownershipRejected.
		if (current.getActivityIdentity().getActivityType() == ActivityType.SLAYER
			&& SlayerTaskFamilyRegistry.lootSourceCompatibility(current.getActivityIdentity().getDisplayName(), signal.getBossOrActivitySource())
				== SlayerTaskFamilyRegistry.LootSourceCompatibility.KNOWN_MISMATCH)
		{
			return SignalClassification.rejectOwnership();
		}

		MetricUpdate metric = MetricUpdate.loot(signal.getBossOrActivitySource(), signal.getObservedAt(), signal.getLootDrops());
		return SignalClassification.metricOnly(metric);
	}

	/**
	 * The shared refine-vs-switch-vs-ignore decision for any
	 * combat-branch (COMBAT/SLAYER/BOSSING) candidate identity against
	 * whatever session, if any, is currently in progress. Used by
	 * combat XP_CHANGE, SLAYER_TASK_PROGRESS, and BOSS_KILL alike --
	 * all three are combat-branch-qualifying signals.
	 *
	 * `fromAuthoritativeTaskProgress` (see this class's own javadoc for the
	 * full GG -&gt; Gargoyles activity-switch rationale): true ONLY when the caller is
	 * classifySlayerTaskProgress() -- i.e. this candidate identity comes
	 * directly from a SLAYER_TASK_PROGRESS event naming a specific task,
	 * not from combat XP under a merely-tracked task. Consulted ONLY in
	 * the ACTIVE + lessSpecific branch below; every other branch
	 * (moreSpecific, same-identity, SUSPENDED, incompatible-branch,
	 * same-rank-different-key) is completely unaffected by this
	 * parameter.
	 *
	 * `strength`: the calling
	 * signal's own EvidenceStrength, threaded straight through to every
	 * SignalClassification this method produces -- never re-derived or
	 * altered here from newIdentity/currentIdentity. See EvidenceStrength's
	 * own javadoc.
	 */
	private SignalClassification decideCombatBranch(ActivityIdentity newIdentity, Session current, List<MetricUpdate> metrics, boolean fromAuthoritativeTaskProgress, EvidenceStrength strength)
	{
		if (current == null || current.getState() == SessionState.FINALIZED)
		{
			return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
		}

		ActivityIdentity currentIdentity = current.getActivityIdentity();
		if (currentIdentity.equals(newIdentity))
		{
			return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
		}

		if (!ActivityPrecedence.isCombatBranch(currentIdentity.getActivityType())
			|| !ActivityPrecedence.isCombatBranch(newIdentity.getActivityType()))
		{
			// SKILLING (or any future non-combat type) on either side is
			// never compatible with the combat branch -- a real switch.
			return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
		}

		boolean currentIsGenericCombat = currentIdentity.getActivityType() == ActivityType.COMBAT;
		boolean moreSpecific = ActivityPrecedence.isMoreSpecific(newIdentity.getActivityType(), currentIdentity.getActivityType());
		boolean lessSpecific = ActivityPrecedence.isMoreSpecific(currentIdentity.getActivityType(), newIdentity.getActivityType());

		if (moreSpecific)
		{
			if (currentIsGenericCombat)
			{
				// generic COMBAT -> SLAYER or COMBAT -> BOSSING: refine.
				return SignalClassification.refine(newIdentity, metrics, strength);
			}
			// SLAYER -> BOSSING (or any other
			// more-specific jump from an already-specific identity) is
			// a REAL SWITCH, not a preserved heartbeat of the old
			// identity. There is no boss-to-Slayer-task compatibility
			// evidence available (no mapping database,
			// deliberately out of scope) -- an earlier "stay in
			// the Slayer session" choice was too permissive: it would
			// silently keep an unrelated Slayer session alive (and
			// attribute the boss kill's time to it) purely because a
			// Slayer task happened to still be tracked. The corrected,
			// conservative rule is: unknown compatibility means
			// switch, not merge -- finalize the old session and start a
			// fresh BOSSING one for the authoritative boss identity. A
			// future change with verified boss/task compatibility evidence
			// may choose to REFINE selected cases instead of switching.
			return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
		}

		if (lessSpecific)
		{
			// Magic XP / mixed-batch false resume. Live
			// evidence: two POH teleports' Magic XP (genericCombatIdentity()
			// -- no active Slayer task was tracked) arrived while a
			// SUSPENDED BOSSING/Zulrah session was still well inside its
			// resume window. Under an earlier, unconditional "never
			// downgrade -> treat as a heartbeat of
			// currentIdentity" rule, that generic evidence was relabeled AS
			// Zulrah itself before ever reaching SessionLifecycleEngine or
			// SessionSignalBatchResolver -- so the engine's own SUSPENDED
			// same-identity path saw what looked like genuine matching
			// evidence and resumed Zulrah unconditionally, with zero actual
			// proof Zulrah (rather than any other combat activity, or
			// nothing at all) was what the player was doing. Magic XP is
			// not trustworthy proof of combat by itself -- it can come from
			// teleporting, utility spellcasting, alchemy, enchanting, or
			// actual combat -- so it must never be strong enough to
			// resurrect a SPECIFIC suspended session on its own.
			//
			// NARROWLY SCOPED, EXACTLY to: current is SUSPENDED (an
			// ACTIVE session's own duration/heartbeat semantics --
			// "aggregate without changing identity" -- are completely
			// unaffected and unchanged below), AND newIdentity is the
			// GENERIC COMBAT identity specifically (never a real,
			// specifically-named identity -- a SLAYER_TASK_PROGRESS or
			// Slayer-task-context combat XP always proposes a genuine
			// slayerIdentity(), never genericCombatIdentity(), so this
			// carve-out never touches SLAYER_TASK_PROGRESS's own
			// "never downgrade an established BOSSING session" behavior --
			// that stays exactly as it was). Generic evidence against a
			// SUSPENDED session is reclassified as METRIC_ONLY -- a valid
			// XP contribution, but making no identity claim at all -- so it
			// can never independently resume/prove BOSSING, SLAYER, or any
			// other specific suspended activity; SessionSignalBatchResolver
			// then never sees it as a lifecycle candidate, closing the
			// mixed-batch loophole too (a same-tick specific SKILLING
			// signal resolves on its own, with nothing left to falsely tie
			// against via current-session stickiness). A currently-SUSPENDED
			// session's own aggregates still receive this metric directly
			// (SessionRuntimeCoordinator's existing NO_EVIDENCE/AMBIGUOUS
			// handling already credits every batch metric to whatever
			// session is already current) -- the XP is never lost, only its
			// false lifecycle claim is removed.
			if (current.getState() == SessionState.SUSPENDED)
			{
				if (newIdentity.getActivityType() == ActivityType.COMBAT)
				{
					// Generic combat evidence makes no identity claim at
					// all -- see the comment above.
					return SignalClassification.metricOnly(metrics);
				}

				// Suspended specific-vs-specific. The
				// carve-out above only covers GENERIC combat evidence.
				// newIdentity here is a genuinely SPECIFIC lower-rank
				// identity (e.g. a real slayerIdentity() from
				// SLAYER_TASK_PROGRESS, arriving while current is a
				// SUSPENDED higher-rank BOSSING identity) -- trustworthy,
				// named evidence for a DIFFERENT activity than the one
				// that is suspended. Relabeling it as currentIdentity
				// (the old unconditional behavior below) would silently
				// resurrect the wrong suspended session purely because of
				// ActivityPrecedence ranking, with zero evidence the
				// player ever returned to it. A suspended identity is
				// only resumable when evidence actually supports THAT
				// identity (see the exact-identity-match fast path
				// above) -- so specific different evidence must not be
				// pre-emptively relabeled here. Propose it honestly as
				// newIdentity instead; SessionLifecycleEngine's own
				// authoritative-different-identity-while-suspended logic
				// (isWeakEvidenceAgainstEstablishedSession() and its
				// caller) decides what happens next -- both SLAYER and
				// BOSSING are combat-branch, so this is never "weak"
				// evidence, and the suspended session is finalized while
				// the new specific identity starts cleanly, exactly like
				// any other authoritative different-identity evidence
				// against a suspended session.
				return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
			}

			// ACTIVE. GG -> Gargoyles activity-switch (see this
			// class's own javadoc): a SLAYER_TASK_PROGRESS
			// event (fromAuthoritativeTaskProgress == true) directly and
			// specifically identifies a genuinely different activity --
			// it must not be silently relabeled as the old, more-specific
			// identity merely because of ActivityPrecedence ranking. This
			// mirrors the SUSPENDED branch's own specific-vs-specific
			// carve-out above, but scoped by SIGNAL ORIGIN rather than by
			// ActivityType alone: combat XP inferred from a merely-tracked
			// Slayer task (fromAuthoritativeTaskProgress == false) is NOT
			// included here and keeps the exact "never downgrade" behavior
			// below (see classifyXpChange()'s own comment for why -- an
			// ACTIVE boss fight with an unrelated Slayer task tracked in
			// the background must not be destroyed by that fight's own
			// ordinary combat XP).
			if (fromAuthoritativeTaskProgress)
			{
				return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
			}

			// SLAYER TASK-FAMILY MEMBERSHIP. newIdentity here is
			// always ActivityType.COMBAT when currentIdentity is
			// ActivityType.SLAYER (COMBAT is the only type ranked below
			// SLAYER -- see ActivityPrecedence), i.e. ordinary combat XP or
			// RAW_COMBAT_XP_OBSERVED naming a specific (or unnamed generic
			// fallback) NPC. This is no longer unconditionally absorbed by
			// the "never downgrade" rule below -- see
			// SlayerTaskFamilyRegistry's own javadoc. A genuine ON-TASK
			// alternative/superior/boss-form NPC for the assigned task
			// (e.g. Flaming pyrelord for Pyrefiends), or the unnamed
			// genericCombatIdentity() fallback (no fresh recent NPC target
			// at all -- no evidence either way), still falls straight
			// through to "never downgrade" immediately below. A genuinely OFF-TASK, specifically-named
			// NPC is instead now honestly proposed as newIdentity, so
			// deliberate, SUSTAINED off-task combat can still escape the
			// Slayer session via the SAME EvidenceStrength.ORDINARY "weak
			// evidence" ACTIVE-candidate gate SessionLifecycleEngine
			// already applies to classifyNonCombatXp()'s SKILLING evidence
			// (see isWeakEvidenceAgainstEstablishedSession()) -- a single
			// incidental off-task tick (a cannon splash, a stray NPC
			// death, which never reaches this classifier as combat XP at
			// all) never switches anything by itself; only a SECOND,
			// coherent, confirming observation of the SAME off-task
			// identity does. Never consulted for a BOSSING currentIdentity
			// (e.g. Grotesque Guardians) -- that precedence remains
			// entirely governed by BossTaskAffinity, untouched here.
			if (currentIdentity.getActivityType() == ActivityType.SLAYER
				&& !isOnTaskFamilyOrUnknownNpc(currentIdentity, newIdentity))
			{
				return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
			}

			// Never downgrade: generic (or inferred-specific,
			// non-authoritative) later evidence continues the
			// already-more-specific compatible session instead of
			// erasing it. This concerns only LESS-specific evidence
			// arriving against an already-specific identity, never
			// more-specific evidence (see the moreSpecific branch above,
			// which is a real switch). Unchanged for an
			// ACTIVE session ("aggregate without changing
			// identity") for every case except the
			// fromAuthoritativeTaskProgress carve-out immediately above.
			// EVIDENCE STRENGTH: this classification continues
			// currentIdentity, not newIdentity -- `strength` still
			// describes THIS signal's own provenance and is carried
			// through unchanged; it is never re-derived from
			// currentIdentity/its ActivityType.
			return SignalClassification.startOrHeartbeat(currentIdentity, metrics, strength);
		}

		// Same specificity rank, different key (BOSSING/Zulrah vs
		// BOSSING/Vorkath, SLAYER/Gargoyles vs SLAYER/Abyssal demons):
		// always a real switch, never a refinement.
		return SignalClassification.startOrHeartbeat(newIdentity, metrics, strength);
	}

	/**
	 * SLAYER TASK-FAMILY MEMBERSHIP. True when `candidateIdentity`
	 * (always ActivityType.COMBAT -- see call site) carries no real NPC
	 * name at all (the unnamed genericCombatIdentity() fallback -- no
	 * fresh recent NPC target was tracked, so there is no evidence
	 * either way, on-task or off), OR its own NPC display name is a
	 * confirmed member of `slayerIdentity`'s own assigned task family
	 * per SlayerTaskFamilyRegistry.belongsToTaskFamily(). False only for
	 * a SPECIFICALLY-named NPC confirmed NOT to belong to that task.
	 */
	private static boolean isOnTaskFamilyOrUnknownNpc(ActivityIdentity slayerIdentity, ActivityIdentity candidateIdentity)
	{
		if (candidateIdentity.getActivityKey().equals(genericCombatIdentity().getActivityKey()))
		{
			return true;
		}
		return SlayerTaskFamilyRegistry.belongsToTaskFamily(slayerIdentity.getDisplayName(), candidateIdentity.getDisplayName());
	}

	private static List<MetricUpdate> singleMetric(MetricUpdate metric)
	{
		return metric == null ? Collections.<MetricUpdate>emptyList() : Collections.singletonList(metric);
	}

	/**
	 * CANDIDATE-METRIC BUFFERING: concatenates a
	 * previously-buffered candidate metric list (see ClassifierContext)
	 * with this signal's own metric (nullable), preserving order --
	 * buffered-first, this event's own metric last. Used by
	 * classifyBossKill() and classifyServerNpcLoot() to combine a
	 * resolved candidate's buffered progress metric(s) with the
	 * resolving signal's own metric, both destined for the same
	 * winning identity.
	 */
	private static List<MetricUpdate> combineMetrics(List<MetricUpdate> buffered, MetricUpdate ownMetric)
	{
		List<MetricUpdate> combined = new ArrayList<>(buffered);
		if (ownMetric != null)
		{
			combined.add(ownMetric);
		}
		return combined;
	}

	static boolean isCombatSkill(String skill)
	{
		return skill != null && COMBAT_SKILLS.contains(skill.trim().toLowerCase(Locale.ROOT));
	}

	static ActivityIdentity genericCombatIdentity()
	{
		// Deliberately broad, stable, never guessed from
		// NPC_DEATH/NPC_LOOT_ATTRIBUTED/nearby NPCs.
		return new ActivityIdentity(ActivityType.COMBAT, "combat", "Combat");
	}

	/**
	 * PEEKS rather than CONSUMES. The
	 * ONLY caller is classifyXpChange()'s combat branch, and ONLY when
	 * no reliable Slayer task is tracked (a tracked task always wins via
	 * slayerIdentity() -- this method is never even consulted then).
	 * Reads ClassifierContext's own short-lived recent-target watch (see
	 * its javadoc for the exact bounded rule) WITHOUT refreshing it --
	 * XP_CHANGE is SkillsCollector's own slow, aggregated signal (see
	 * ClassifierContext's TEMPORAL-DESIGN javadoc section)
	 * and must never itself be trusted to extend the watch's freshness,
	 * only RAW_COMBAT_XP_OBSERVED's own classification (see
	 * classifyRawCombatXpObserved() below) does that now. Falls back to
	 * the plain, unnamed genericCombatIdentity() when there is no fresh
	 * recent target.
	 */
	static ActivityIdentity genericCombatOrNpcIdentity(ClassifierContext context, Long currentTick, Instant currentObservedAt)
	{
		String recentTargetName = context.peekRecentTargetNpcNameIfFresh(currentTick, currentObservedAt);
		if (recentTargetName == null)
		{
			return genericCombatIdentity();
		}
		return genericNpcCombatIdentity(recentTargetName);
	}

	/**
	 * Handles SignalKind.RAW_COMBAT_XP_OBSERVED -- see
	 * that constant's own javadoc for the full rationale (closing the
	 * gap between a fresh interaction and XP_CHANGE's slow aggregated
	 * cadence).
	 *
	 * Defense-in-depth skill filter, even though the production
	 * collector (SkillsCollector.onStatChanged()) already only ever
	 * emits this kind for a genuine combat skill, never Magic: this
	 * method independently re-checks isCombatSkill()/isMagicXpSkill()
	 * against the SAME COMBAT_SKILLS set/exclusion classifyXpChange()
	 * itself uses, so a future collector regression could never smuggle
	 * an unreliable (e.g. Magic, or a non-combat) skill's raw pulse into
	 * proposing a session identity.
	 *
	 * Consumes (reads AND refreshes -- see
	 * ClassifierContext.consumeRecentTargetNpcNameIfFresh()) the
	 * recent-target watch. When nothing is fresh, this signal has
	 * nothing useful to contribute and is IGNORED outright -- it
	 * deliberately never falls back to the plain, unnamed
	 * genericCombatIdentity() the way classifyXpChange()'s combat branch
	 * does, so a raw pulse with no NPC context never floods the
	 * ACTIVE-candidate machinery with generic-COMBAT noise on every
	 * single hit; XP_CHANGE remains the one path that ever proposes the
	 * plain fallback identity.
	 *
	 * ALWAYS EvidenceStrength.ORDINARY and ALWAYS an EMPTY metrics list
	 * -- see SignalKind.RAW_COMBAT_XP_OBSERVED's own "NEVER AN XP
	 * METRIC" section: this is lifecycle-only evidence, structurally
	 * incapable of contributing to SessionAggregates.
	 */
	private SignalClassification classifyRawCombatXpObserved(SessionSignal signal, Session current, ClassifierContext context)
	{
		String skill = signal.getSkill();
		if (!isCombatSkill(skill) || isMagicXpSkill(skill))
		{
			return SignalClassification.ignore();
		}

		String recentTargetName = context.consumeRecentTargetNpcNameIfFresh(signal.getGameTick(), signal.getObservedAt());
		if (recentTargetName == null)
		{
			return SignalClassification.ignore();
		}

		ActivityIdentity identity = genericNpcCombatIdentity(recentTargetName);
		return decideCombatBranch(identity, current, Collections.<MetricUpdate>emptyList(), false, EvidenceStrength.ORDINARY);
	}

	/**
	 * Public entry point for
	 * SessionRuntimeCoordinator.reEvaluateCurrentSession() ONLY -- the
	 * player-triggered "Re-evaluate Session" button's backend hook. Reuses
	 * this class's own decideCombatBranch() precedence/refine/switch rules
	 * verbatim (never-downgrade-a-more-specific-ACTIVE-session via generic
	 * evidence, the SUSPENDED specific-vs-specific carve-out, the SLAYER
	 * task-family-membership handling -- every one of them completely
	 * unchanged) for a manually-observed, right-now NPC interaction
	 * target, with a CALLER-SUPPLIED EvidenceStrength instead of the fixed
	 * ORDINARY every other combat-branch caller uses. Threading a stronger
	 * strength through -- and ONLY that -- is what lets a manual
	 * re-evaluation bypass SessionLifecycleEngine's weak-evidence
	 * candidate/stickiness gate for this one observation (see
	 * EvidenceStrength's own javadoc: SPECIFIC "always switches/refines
	 * immediately"); decideCombatBranch()'s own branch selection never
	 * consults `strength` at all (see its own javadoc: "threaded straight
	 * through ... never re-derived or altered here"), so every existing
	 * identity-precedence protection applies exactly as it does for any
	 * other caller. This is a pure additive overload -- classifyXpChange(),
	 * classifySlayerTaskProgress(), classifyBossKill(), and
	 * classifyRawCombatXpObserved() are completely unaffected.
	 *
	 * Never itself resolves an NPC name to a boss or Slayer identity --
	 * exactly like classifyRawCombatXpObserved(), this always proposes a
	 * generic, name-keyed COMBAT identity (genericNpcCombatIdentity()) for
	 * whatever NPC name the caller supplies, with an always-empty metrics
	 * list (a manual re-evaluation never fabricates XP/loot -- see the
	 * coordinator's own javadoc). A currently-tracked Slayer task is never
	 * consulted here, matching the "Slayer assignment alone must never
	 * establish a Slayer session" rule exactly as classifyXpChange()'s own
	 * combat branch already enforces it (see that method's Magic XP
	 * comment) -- only genuine SLAYER_TASK_PROGRESS/BOSS_KILL/
	 * BOSS_ACTIVITY_CONTEXT evidence, processed through the ordinary
	 * signal pipeline exactly as before, may ever refine this into
	 * SLAYER/BOSSING.
	 */
	public SignalClassification classifyManualNpcTarget(String npcName, Session current, EvidenceStrength strength)
	{
		ActivityIdentity identity = genericNpcCombatIdentity(npcName);
		return decideCombatBranch(identity, current, Collections.<MetricUpdate>emptyList(), false, strength);
	}

	/**
	 * A stable,
	 * name-based generic COMBAT identity for a SPECIFIC attackable NPC
	 * (e.g. "Abyssal spectre", "Hill Giant") -- deliberately still
	 * ActivityType.COMBAT (rank 0 in ActivityPrecedence's combat-branch
	 * ordering), never a new ActivityType, so every existing
	 * SLAYER/BOSSING precedence, refinement, and "never downgrade an
	 * ACTIVE more-specific session" rule in decideCombatBranch() and
	 * SessionSignalBatchResolver already applies to it completely
	 * unchanged. Keyed by normalized NPC NAME only (mirroring
	 * bossIdentity()'s own name-based canonicalization) -- deliberately
	 * NOT by NPC id, so a boss/monster that legitimately changes runtime
	 * NPC id mid-fight (phase transitions, transformed forms) does not
	 * fragment one continuous generic-combat session into several. No
	 * hand-maintained NPC table is consulted here or anywhere in this
	 * method: npcName is trusted verbatim from whatever
	 * NpcInteractionTargetCollector already filtered to a genuinely
	 * attackable NPC.
	 */
	static ActivityIdentity genericNpcCombatIdentity(String npcName)
	{
		String key = npcName.trim().toLowerCase(Locale.ROOT);
		return new ActivityIdentity(ActivityType.COMBAT, key, npcName);
	}

	static ActivityIdentity slayerIdentity(String taskName, String taskLocation)
	{
		// Stable key from taskName + taskLocation ONLY -- never
		// amountRemaining/initialAmount/points/streak/masterId, which
		// are progress/metadata and must never split a session.
		String normalizedName = taskName == null ? "unknown" : taskName.trim().toLowerCase(Locale.ROOT);
		String key = (taskLocation == null || taskLocation.trim().isEmpty())
			? normalizedName
			: normalizedName + "@" + taskLocation.trim().toLowerCase(Locale.ROOT);
		String displayName = taskName == null ? "Slayer task" : taskName;
		return new ActivityIdentity(ActivityType.SLAYER, key, displayName);
	}

	static ActivityIdentity bossIdentity(String bossName)
	{
		// Authoritative source name only -- never current KC,
		// display formatting, or timestamp; the same boss across
		// consecutive authoritative kills always yields the same key.
		String key = bossName == null ? "unknown" : bossName.trim().toLowerCase(Locale.ROOT);
		String displayName = bossName == null ? "Boss" : bossName;
		return new ActivityIdentity(ActivityType.BOSSING, key, displayName);
	}

	static ActivityIdentity structuredActivityIdentity(com.osrstelemetry.plugin.activity.StructuredActivityDefinition definition)
	{
		return new ActivityIdentity(ActivityType.STRUCTURED_ACTIVITY, definition.getKey(), definition.getDisplayName());
	}

	static ActivityIdentity skillingIdentity(String skill)
	{
		// Small, stable per-skill identity, not an exhaustive
		// method database.
		String key = skill == null ? "unknown" : skill.trim().toLowerCase(Locale.ROOT);
		String displayName = skill == null ? "Skilling" : capitalize(skill);
		return new ActivityIdentity(ActivityType.SKILLING, key, displayName);
	}

	private static String capitalize(String s)
	{
		String trimmed = s.trim();
		if (trimmed.isEmpty())
		{
			return trimmed;
		}
		return Character.toUpperCase(trimmed.charAt(0)) + trimmed.substring(1).toLowerCase(Locale.ROOT);
	}
}

package com.osrstelemetry.plugin.session;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * Small, explicit, project-owned DATA describing the one thing
 * boss self-consumption of its own Slayer task needs that no other
 * class in this codebase already models:
 * which bosses ALSO count toward their own Slayer task assignment (a
 * boss kill that itself consumes that task's units, exactly like an
 * ordinary member of the task), and which NPC name(s) actually
 * constitute that boss for loot-source-name comparison purposes.
 *
 * ROOT CAUSE THIS EXISTS TO FIX: an earlier fix made
 * ActivitySignalClassifier.decideCombatBranch() let an
 * authoritative SLAYER_TASK_PROGRESS switch an ACTIVE, more-specific
 * BOSSING session away -- correct for a genuinely different NPC (a real
 * Gargoyle kill after leaving Grotesque Guardians), but WRONG for
 * Grotesque Guardians' OWN kills, which also decrement the Gargoyles
 * Slayer task. Both cases produce an IDENTICAL SLAYER_TASK_PROGRESS
 * event (same taskName, same shape) -- there is no way to tell them
 * apart from that one event alone. This class supplies the one piece of
 * missing, GENERAL evidence: Jagex's own boss-to-Slayer-task mapping is
 * a small, fixed, well-known table, not something that needs to be
 * inferred or guessed per account.
 *
 * DELIBERATELY DATA, NOT CODE: every consumer of this class
 * (ActivitySignalClassifier, SessionSignalBatchResolver) asks it a pure
 * yes/no question -- neither branches on a boss's name directly anywhere
 * else. Extend BOSS_OWN_TASK_NORMALIZED (and, if the boss also has a
 * multi-NPC encounter like Grotesque Guardians' Dawn/Dusk, BOSS_NPC_NAMES_NORMALIZED)
 * as more such bosses are confirmed -- Shellbane Gryphon/Gryphons is the
 * second confirmed entry (live-reproduced regression, identical shape to
 * Grotesque Guardians/Gargoyles); still-unconfirmed candidates like
 * Kurask/Kurasks, Kree'arra/Aviansies remain future additions -- rather
 * than adding a per-boss branch anywhere else in this codebase.
 *
 * BOSS_NPC_NAMES_NORMALIZED deliberately duplicates (in miniature) the
 * SHAPE of KnownBossRegistry's own NPC_NAME_ALIASES table (Dawn/Dusk ->
 * "Grotesque Guardians"), but is NOT the same table and is not shared
 * with it: KnownBossRegistry lives in the collectors package, is an
 * account-scoped @Singleton with per-account confirmed-boss state, and
 * solves a different problem (resolving an InteractingChanged NPC name
 * into a BOSS_ACTIVITY_CONTEXT candidate). This class is a pure,
 * dependency-free, per-JVM-static table answering a narrower, different
 * question (loot SOURCE NAME identity for self-consumption
 * corroboration) for the classifier/resolver pair, which must remain
 * free of any RuneLite/collectors dependency. If the two tables ever
 * diverge for the same boss, that is a real bug to fix by hand in both
 * places -- there are only ever a handful of entries in either.
 */
final class BossTaskAffinity
{
	private BossTaskAffinity()
	{
	}

	/**
	 * normalized boss display name -&gt; normalized Slayer task name that
	 * boss's OWN kills also count toward. Only bosses confirmed to have
	 * this property belong here -- most bosses have no Slayer-task
	 * affinity at all and simply return false/null below.
	 */
	private static final Map<String, String> BOSS_OWN_TASK_NORMALIZED;

	static
	{
		Map<String, String> ownTask = new HashMap<>();
		ownTask.put(normalize("Grotesque Guardians"), normalize("Gargoyles"));
		// Shellbane Gryphon canonical-identity churn:
		// IDENTICAL SHAPE to Grotesque Guardians/Gargoyles above: Shellbane
		// Gryphon's own kill also decrements the "Gryphons" Slayer task,
		// so an authoritative SLAYER_TASK_PROGRESS naming "Gryphons" while
		// ACTIVE BOSSING/Shellbane Gryphon is genuinely ambiguous (self-
		// consumption vs. a real, separate ordinary Gryphon) and must not
		// switch by itself -- see this class's own javadoc, and
		// ActivitySignalClassifier.classifySlayerTaskProgress()'s use of
		// isBossOwnTask() below. This is a DATA addition only, exactly the
		// "extend as more such bosses are confirmed" extension point this
		// class's own javadoc already invites -- no new code, no
		// Shellbane-specific branch anywhere else in the codebase. Single-
		// NPC encounter (unlike Grotesque Guardians' Dawn/Dusk), so no
		// corresponding BOSS_NPC_NAMES_NORMALIZED entry is needed --
		// isBossOwnNpcName()'s direct-equality fallback already handles it
		// correctly for BOSS_KILL/SERVER_NPC_LOOT corroboration.
		ownTask.put(normalize("Shellbane Gryphon"), normalize("Gryphons"));
		BOSS_OWN_TASK_NORMALIZED = Collections.unmodifiableMap(ownTask);
	}

	/**
	 * normalized boss display name -&gt; the normalized NPC name(s) that
	 * constitute an actual kill of that boss (for comparing against a
	 * SERVER_NPC_LOOT signal's own sourceName). A boss with no entry here
	 * falls back to direct name equality (see isBossOwnNpcName()) -- only
	 * multi-NPC encounters like Grotesque Guardians (Dawn AND Dusk) need
	 * an explicit entry.
	 */
	private static final Map<String, Set<String>> BOSS_NPC_NAMES_NORMALIZED;

	static
	{
		Map<String, Set<String>> npcNames = new HashMap<>();
		npcNames.put(normalize("Grotesque Guardians"), Collections.unmodifiableSet(new HashSet<>(
			Arrays.asList(normalize("Dawn"), normalize("Dusk"), normalize("Grotesque Guardians")))));
		BOSS_NPC_NAMES_NORMALIZED = Collections.unmodifiableMap(npcNames);
	}

	/**
	 * @return true if `bossActivityKey` (an already-normalized
	 * ActivityIdentity.getActivityKey() value from bossIdentity() -- see
	 * ActivitySignalClassifier) is a boss confirmed to consume its own
	 * Slayer task's units, AND `taskName` (raw, not yet normalized) names
	 * exactly that task.
	 */
	static boolean isBossOwnTask(String bossActivityKey, String taskName)
	{
		if (bossActivityKey == null || taskName == null)
		{
			return false;
		}
		String ownTask = BOSS_OWN_TASK_NORMALIZED.get(bossActivityKey);
		if (ownTask != null && ownTask.equals(normalize(taskName)))
		{
			return true;
		}
		// GENERIC BOSS-ON-MATCHING-TASK RULE (Kraken / Cave Kraken live
		// regression). The explicit table above only covers bosses whose
		// Slayer-task family data does NOT already name them (Grotesque
		// Guardians is catalogued under its Dawn/Dusk NPCs; Shellbane
		// Gryphon is not a "Gryphons" family member). Every other boss
		// that the existing, RuneLite-derived SlayerTaskFamilyRegistry
		// already lists as a member of the named task's family (Kraken
		// under "Cave kraken", Cerberus under "Hellhounds", Vorkath under
		// "Blue dragons", ...) is, by that same data, a boss whose own
		// kills consume that task -- so its SLAYER_TASK_PROGRESS is the
		// identical, ambiguous self-consumption event and must go through
		// the same suppress-and-disambiguate path, never an immediate
		// switch to the regular Slayer identity. No per-boss name branch:
		// one membership lookup against data this codebase already owns.
		// bossActivityKey is ActivitySignalClassifier.bossIdentity()'s own
		// trimmed/lowercased boss name -- the same normalization
		// belongsToTaskFamily() applies to its NPC-name argument.
		return SlayerTaskFamilyRegistry.belongsToTaskFamily(taskName, bossActivityKey);
	}

	/**
	 * @return true if `npcSourceName` (raw, not yet normalized -- e.g. a
	 * SERVER_NPC_LOOT signal's own sourceName) identifies the boss itself
	 * (`bossActivityKey`, an already-normalized activityKey) rather than
	 * some other, genuinely different NPC. Bosses with no explicit
	 * multi-NPC entry fall back to direct equality against the boss's own
	 * key -- correct for every single-NPC boss encounter.
	 */
	static boolean isBossOwnNpcName(String bossActivityKey, String npcSourceName)
	{
		if (bossActivityKey == null)
		{
			return false;
		}
		String normalizedSource = npcSourceName == null ? "" : normalize(npcSourceName);
		Set<String> knownNames = BOSS_NPC_NAMES_NORMALIZED.get(bossActivityKey);
		if (knownNames != null)
		{
			return knownNames.contains(normalizedSource);
		}
		return bossActivityKey.equals(normalizedSource);
	}

	private static String normalize(String s)
	{
		return s.trim().toLowerCase(Locale.ROOT);
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The small, explicit, account-specific transient state
 * ActivitySignalClassifier needs beyond the current Session itself --
 * today, "is there a reliable active Slayer task, and what is it" plus
 * (boss self-consumption of its own Slayer task) a single pending
 * "boss task candidate" watch. Deliberately:
 *
 *   - NOT a static/global -- one instance per account, owned by
 *     whatever runtime coordinator wires the classifier to real
 *     events. Two accounts must never share one
 *     ClassifierContext instance.
 *   - NOT backed by SlayerState.json or any other on-disk file, and
 *     NEVER reads Python/account_state.json -- this is purely
 *     in-memory classifier working state, populated only from the
 *     SessionSignal stream the classifier itself already processes.
 *   - Reset()-able so a future account switch can cleanly discard one
 *     account's classifier context and start a fresh one for another,
 *     exactly as SessionLifecycleEngine/SessionPersistence already do
 *     per account.
 *
 * PENDING BOSS TASK CANDIDATE (boss
 * self-consumption of its own Slayer task; extended by the
 * CANDIDATE-METRIC BUFFERING section below -- see
 * BossTaskAffinity and ActivitySignalClassifier.classifySlayerTaskProgress()'s
 * own javadoc for the full rationale): armed when a SLAYER_TASK_PROGRESS
 * names the currently-ACTIVE boss's OWN known Slayer task -- an event
 * that could EITHER be that boss's own kill (self-consumption -- the
 * session must stay BOSSING) OR a genuinely different, ordinary NPC for
 * that same task (a real switch to SLAYER). Both produce an identical
 * event, so neither can be told apart from that one signal alone; the
 * disambiguating evidence (a same-boss BOSS_KILL confirming
 * self-consumption, or a different-NPC SERVER_NPC_LOOT confirming a
 * real switch) arrives separately, sometimes several seconds and one or
 * more game ticks later -- see ActivitySignalClassifier.classifyBossKill()/
 * classifyServerNpcLoot() for the two ways this is resolved, and
 * SessionSignalBatchResolver.applyBossSelfConsumptionCorroboration() for
 * the SAME-tick, order-independent half of the same fix.
 *
 * CANDIDATE-METRIC BUFFERING ("ambiguous kill's own
 * progress metric stranded on the boss session after a later-confirmed
 * real switch"): the originating SLAYER_TASK_PROGRESS event's own
 * MetricUpdate (the Slayer progress delta + currentRemaining) is now
 * held HERE, in pendingBossTaskCandidateMetrics, rather than being
 * applied to any session at the moment it arrives. It is applied
 * EXACTLY ONCE, by whichever caller resolves the candidate:
 *   - self-consumption confirmed (classifyBossKill()): combined with
 *     that same-boss kill's own metric and applied to the session that
 *     never left BOSSING -- a delayed-but-correct application, never a
 *     retroactive correction of anything.
 *   - a real switch confirmed (classifyServerNpcLoot() /
 *     applyBossSelfConsumptionCorroboration()): combined with the
 *     confirming loot's own metric and applied to the brand-new Slayer
 *     session -- so that session's slayerProgressDelta/latestSlayerCurrentRemaining
 *     are correct immediately upon confirmation, never waiting for a
 *     second kill.
 *   - never resolved (the boss session ends for an unrelated reason --
 *     times out to SUSPENDED, or the plugin/account switches -- before
 *     either half above arrives): SessionRuntimeCoordinator commits
 *     these buffered metrics, exactly once, to whatever session is
 *     legitimately current at that point (see its own
 *     flushAbandonedBossTaskCandidateIfMatching()), mirroring
 *     SessionLifecycleEngine's own pendingCandidateMetrics precedent for
 *     its unrelated (SUSPENDED weak-evidence) candidate mechanism. This
 *     is a plain List, not a single value, for the same reason: a
 *     second own-task progress event can legitimately arrive before the
 *     first is resolved (kill-message delay is exactly what this whole
 *     fix is about) -- armBossTaskCandidate() APPENDS to this list for
 *     the SAME boss rather than replacing it, so no earlier kill's own
 *     metric is ever silently dropped.
 *
 * Holding only ONE candidate WATCH at a time (the identity pair is
 * armed/replaced, never a list) is intentional: a boss is fought one
 * kill at a time, and each kill's own progress event is independently
 * resolved (confirmed or aborted) well before the next one in ordinary
 * play -- but its buffered METRICS (plural) accumulate for as long as
 * the watch stays open, so consecutive own-task-progress events before
 * resolution are never lost (see above).
 */
public final class ClassifierContext
{
	/**
	 * STRUCTURED ACTIVITY: ARMED/ACTIVE/LOCKED recognition of the structured
	 * activity whose location the player is in. Transient by design -- a
	 * fresh context (restart, relog into a new runtime, account switch)
	 * starts OUTSIDE and must re-arm from the next location signal.
	 */
	private final com.osrstelemetry.plugin.activity.StructuredActivityTracker structuredActivity =
		new com.osrstelemetry.plugin.activity.StructuredActivityTracker();

	com.osrstelemetry.plugin.activity.StructuredActivityTracker getStructuredActivity()
	{
		return structuredActivity;
	}

	private String activeSlayerTaskName;
	private String activeSlayerTaskLocation;

	/**
	 * Fixes a reproducible SLAYER_TASK_COMPLETED remaining=1 bug. The most
	 * recently observed authoritative currentRemaining for
	 * activeSlayerTaskName/activeSlayerTaskLocation above (from the
	 * latest SLAYER_TASK_PROGRESS that carried one -- see
	 * onSlayerTaskProgress() below), or null when no PROGRESS event for
	 * the currently-tracked task has ever carried a currentRemaining.
	 * Consulted ONLY by ActivitySignalClassifier.classifySlayerTaskCompleted()
	 * to reconcile the exact outstanding task unit(s) no trailing
	 * PROGRESS event ever reported -- see that method's own javadoc for
	 * the full rationale. Cleared (never carried across tasks) whenever
	 * the tracked task itself changes (a fresh SLAYER_TASK_ASSIGNED) or
	 * completes (onSlayerTaskCompleted()).
	 */
	private Integer lastKnownSlayerCurrentRemaining;

	/**
	 * The exact ABSOLUTE XP value of every skill at the
	 * precise moment the CURRENTLY-current session (xpBoundaryOwnerSessionId)
	 * itself began -- i.e. a per-skill "session start baseline," captured
	 * ONCE by SessionRuntimeCoordinator (see its own
	 * noteSessionSwitchXpBaseline() call site) at the exact instant a
	 * real session switch is detected, from whatever absolute XP values
	 * it has most recently observed via SkillsCollector's raw
	 * StatChanged stream (the SAME underlying observations LiveXpTracker's
	 * own pending deltas are built from -- see SessionRuntimeCoordinator's
	 * own lastKnownAbsoluteXpBySkill javadoc).
	 *
	 * WHY THIS EXISTS: an XP_CHANGE's own aggregation window can SPAN a
	 * real session switch (window opens under the OLD session, the
	 * switch happens mid-window, the window doesn't close/flush until
	 * AFTER it) -- see classifyXpChange()'s own javadoc for the full
	 * boundary-ownership rule this baseline makes possible. Given this
	 * baseline (xp at the moment THIS session started) and the flushed
	 * event's own absolute newXp (SessionSignal#getXpNewValue()), the
	 * portion of that window's delta earned AFTER the switch is exactly
	 * `newXp - xpAtSessionStart` -- never a proportional/time-based
	 * guess, and never assigning any pre-switch XP to this session.
	 *
	 * SINGLE-OWNER MODEL (mirrors LiveXpTracker's own ownerSessionId
	 * discipline): holds a baseline for exactly ONE session id at a
	 * time -- the most recent session a real switch established. A
	 * refineIdentity() re-key (the SAME continuous session, same id)
	 * never touches this; only a genuine new-session-id switch replaces
	 * it (see SessionRuntimeCoordinator's own call site). Never
	 * persisted, never durable -- purely in-memory classifier working
	 * state, reset() on account switch exactly like every other field on
	 * this class.
	 */
	private String xpBoundaryOwnerSessionId;
	private final Map<String, Long> xpAtSessionStartBySkill = new HashMap<>();

	private ActivityIdentity pendingBossTaskCandidateBossIdentity;
	private ActivityIdentity pendingBossTaskCandidateSlayerIdentity;
	private final List<MetricUpdate> pendingBossTaskCandidateMetrics = new ArrayList<>();

	/**
	 * A small, bounded,
	 * SLIDING-WINDOW "what attackable NPC did the local player most
	 * recently interact with" watch, populated only from
	 * SignalKind.NPC_INTERACTION_TARGET (see that constant's own
	 * javadoc) -- never itself lifecycle-carrying, never persisted
	 * (same "purely in-memory working state" discipline as
	 * activeSlayerTaskName/activeSlayerTaskLocation above).
	 *
	 * WHY SLIDING, NOT A FIXED TTL FROM THE ORIGINAL CLICK: a genuinely
	 * continuous fight against one stationary NPC target does not
	 * necessarily re-fire InteractingChanged at all (RuneLite only
	 * posts it when Actor#getInteracting() actually CHANGES) -- a fixed
	 * TTL anchored at the original interaction would then silently
	 * expire mid-fight even though the player never disengaged. Every
	 * combat-skill RAW_COMBAT_XP_OBSERVED event that actually CONSUMES
	 * this context (see consumeRecentTargetNpcNameIfFresh() below,
	 * called only from ActivitySignalClassifier's RAW_COMBAT_XP_OBSERVED
	 * branch) refreshes recentTargetLastSeenTick/At to that event's own
	 * tick/instant -- exactly the same sliding-window idea
	 * SessionLifecycleEngine's own lastActiveAt/SUSPEND_TIMEOUT already
	 * uses for session activity, just applied to this much smaller,
	 * short-lived piece of context.
	 *
	 * WHY XP_CHANGE NO LONGER REFRESHES THIS WATCH: XP_CHANGE is SkillsCollector's own AGGREGATED event,
	 * only emitted on its slow flush cadence (XP_FLUSH_INTERVAL_TICKS --
	 * ~50 ticks / ~30 real seconds), which can easily span a genuine
	 * target change or a genuine disengagement. Letting a signal on that
	 * coarse a cadence REFRESH this watch's freshness allowed a stale
	 * NPC identity to self-perpetuate for cycle after cycle even once
	 * the player had genuinely stopped fighting it -- a real bug. Only
	 * RAW_COMBAT_XP_OBSERVED (immediate, per-hit-cadence, tightly
	 * coupled to real, current combat activity -- see its own javadoc)
	 * is trusted to refresh this watch now; XP_CHANGE's own combat
	 * branch (ActivitySignalClassifier.classifyXpChange()) instead calls
	 * peekRecentTargetNpcNameIfFresh() below, a READ-ONLY twin that can
	 * still see a still-fresh watch (typically kept fresh by
	 * RAW_COMBAT_XP_OBSERVED pulses arriving throughout the same fight)
	 * but can never itself extend its life.
	 *
	 * THE BOUNDED RULE (documented here, exercised in
	 * ClassifierContextTest / ActivitySignalClassifierTest): valid for
	 * RECENT_TARGET_MAX_AGE_TICKS (20 game ticks, ~12 seconds at
	 * 0.6s/tick) since it was last established/refreshed, compared via
	 * gameTick WHENEVER both the stored watch and the querying signal
	 * carry one (the normal, real-runtime case -- SessionRuntimeCoordinator
	 * tags every real signal with client.getTickCount()). When EITHER
	 * side lacks a gameTick (a synthetic/test signal, or a real signal
	 * built off the client thread -- see SessionRuntimeCoordinator.safeTickCount()),
	 * the same ~12-second bound (RECENT_TARGET_MAX_AGE) is applied to
	 * wall-clock observedAt instead. This is generous enough to survive
	 * a normal weapon's attack-speed gap between hits (even a slow ~6-7
	 * tick weapon) and any brief tick or two where RuneLite reports no
	 * interacting target between individual attacks, while still being
	 * short enough that combat XP arriving long after the player
	 * genuinely moved on is never mislabeled with a stale NPC name.
	 * Deliberately NOT a probabilistic/decaying score -- a single hard
	 * bound, checked the same way every time.
	 */
	static final long RECENT_TARGET_MAX_AGE_TICKS = 20L;
	static final Duration RECENT_TARGET_MAX_AGE = Duration.ofSeconds(12);

	private Integer recentTargetNpcId;
	private String recentTargetNpcName;
	private Long recentTargetLastSeenTick;
	private Instant recentTargetLastSeenAt;

	/**
	 * CONTEXT ONLY. Tracks the account's currently-assigned/
	 * currently-progressing Slayer task purely as background context --
	 * it is NOT, by itself, evidence of what the player is presently
	 * doing. The bug this fixes: ActivitySignalClassifier's
	 * classifyXpChange() used to read this state directly and promote
	 * ANY ordinary combat XP into that task's own SLAYER identity
	 * whenever a task was merely assigned -- so a player who had
	 * Gargoyles assigned, then fought an unrelated Desert Wolf and Goat,
	 * had their session silently hijacked into SLAYER/Gargoyles with zero
	 * Gargoyles ever fought. That read has been REMOVED (see
	 * classifyXpChange()'s own javadoc); this state is no longer
	 * consulted by ActivitySignalClassifier at all. It remains here,
	 * updated exactly as before, purely because it is harmless,
	 * genuinely transient context that some future consumer of
	 * ClassifierContext could legitimately want -- the account's own
	 * "currently assigned task" is ALSO independently tracked outside
	 * this classifier entirely (SlayerCollector's own persisted state
	 * backs the Slayer panel UI, and NpcDeathCollector annotates
	 * NPC_DEATH payloads with it) -- those paths are untouched by this
	 * fix and remain the source of truth for "what task is assigned"
	 * wherever that context is legitimately needed. The ONLY path that
	 * may ever establish or upgrade a SLAYER identity is genuine,
	 * specific Slayer lifecycle evidence -- SLAYER_TASK_PROGRESS, via
	 * classifySlayerTaskProgress() -- never mere assignment/tracking.
	 */
	public void onSlayerTaskAssigned(String taskName, String taskLocation)
	{
		this.activeSlayerTaskName = taskName;
		this.activeSlayerTaskLocation = taskLocation;
		// A fresh assignment is a DIFFERENT task -- any
		// remaining tracked for whatever task preceded it must never
		// leak into this new task's own completion reconciliation.
		this.lastKnownSlayerCurrentRemaining = null;
	}

	/**
	 * `currentRemaining` (nullable -- absent for older/synthetic
	 * callers) is this SAME progress event's own authoritative
	 * currentRemaining, retained here exactly like
	 * SessionAggregates.latestSlayerCurrentRemaining is at the
	 * aggregate layer -- OVERWRITTEN with the latest value, never
	 * summed. A null currentRemaining leaves whatever was already
	 * tracked untouched (never reset to null just because a later
	 * event happened not to carry one).
	 */
	public void onSlayerTaskProgress(String taskName, String taskLocation, Integer currentRemaining)
	{
		this.activeSlayerTaskName = taskName;
		this.activeSlayerTaskLocation = taskLocation;
		if (currentRemaining != null)
		{
			this.lastKnownSlayerCurrentRemaining = currentRemaining;
		}
	}

	/** The task is done -- clear the tracked context. */
	public void onSlayerTaskCompleted()
	{
		this.activeSlayerTaskName = null;
		this.activeSlayerTaskLocation = null;
		this.lastKnownSlayerCurrentRemaining = null;
	}

	/**
	 * See onSlayerTaskAssigned()'s own javadoc: CONTEXT ONLY, no longer
	 * read anywhere in ActivitySignalClassifier. Retained/updated for any future legitimate
	 * consumer; never a substitute for genuine SLAYER_TASK_PROGRESS
	 * evidence.
	 */
	public boolean hasReliableActiveSlayerTask()
	{
		return activeSlayerTaskName != null;
	}

	/** See hasReliableActiveSlayerTask()'s own javadoc. */
	public String getActiveSlayerTaskName()
	{
		return activeSlayerTaskName;
	}

	/** See hasReliableActiveSlayerTask()'s own javadoc. */
	public String getActiveSlayerTaskLocation()
	{
		return activeSlayerTaskLocation;
	}

	/**
	 * See lastKnownSlayerCurrentRemaining's own field javadoc. Null
	 * when no PROGRESS event for the currently-tracked task has ever
	 * carried a currentRemaining.
	 */
	public Integer getLastKnownSlayerCurrentRemaining()
	{
		return lastKnownSlayerCurrentRemaining;
	}

	/**
	 * Called ONLY from
	 * SessionRuntimeCoordinator, exactly once, at the precise moment it
	 * detects a genuine session-identity switch (a brand-new session id
	 * becoming current) -- never for a refineIdentity() re-key of the
	 * SAME session. Replaces whatever baseline was previously held
	 * (single-owner model -- see this class's own xpBoundaryOwnerSessionId
	 * javadoc) with a defensive copy of `xpBySkill`, owned by
	 * `sessionId` from this point on.
	 */
	void noteSessionSwitchXpBaseline(String sessionId, Map<String, Long> xpBySkill)
	{
		this.xpBoundaryOwnerSessionId = sessionId;
		this.xpAtSessionStartBySkill.clear();
		if (xpBySkill != null)
		{
			this.xpAtSessionStartBySkill.putAll(xpBySkill);
		}
	}

	/**
	 * The exact absolute XP value `skill` had at the moment `sessionId`
	 * itself began -- see this class's own xpBoundaryOwnerSessionId
	 * javadoc -- or null when `sessionId` is not the currently tracked
	 * boundary owner, or no baseline was ever captured for that exact
	 * skill (e.g. it was never observed via a raw StatChanged pulse
	 * before the switch -- see classifyXpChange()'s own javadoc for how
	 * this honest "no exact baseline" case is handled).
	 */
	Long getXpAtSessionStart(String sessionId, String skill)
	{
		if (sessionId == null || !sessionId.equals(xpBoundaryOwnerSessionId))
		{
			return null;
		}
		return xpAtSessionStartBySkill.get(skill);
	}

	/**
	 * Moves {@code sessionId}'s start-of-session baseline for {@code skill}
	 * back to {@code xpBefore} when the gain that STARTED the session (a
	 * STRUCTURED_LIVE_XP that switched to it in the same batch) is already
	 * included in the baseline captured at the switch. The later durable
	 * window then credits that first gain to the session it started -- once.
	 */
	void lowerXpAtSessionStart(String sessionId, String skill, long xpBefore)
	{
		if (sessionId == null || !sessionId.equals(xpBoundaryOwnerSessionId) || skill == null)
		{
			return;
		}
		Long current = xpAtSessionStartBySkill.get(skill);
		if (current == null || xpBefore < current)
		{
			xpAtSessionStartBySkill.put(skill, xpBefore);
		}
	}

	/**
	 * Arms (or, for the SAME boss identity, extends) the pending boss
	 * task candidate -- see class javadoc. Called only from
	 * classifySlayerTaskProgress() when the current ACTIVE boss's own
	 * known Slayer task is named by a fresh SLAYER_TASK_PROGRESS event.
	 * `metric` (nullable -- the originating event's own MetricUpdate) is
	 * BUFFERED here, never applied to any session by this call; see
	 * class javadoc's CANDIDATE-METRIC BUFFERING section. A second call
	 * for the SAME bossIdentity APPENDS its metric to the existing
	 * buffer rather than replacing it, so an earlier still-unresolved
	 * kill's own metric is never dropped by a later one.
	 */
	void armBossTaskCandidate(ActivityIdentity bossIdentity, ActivityIdentity candidateSlayerIdentity, MetricUpdate metric)
	{
		this.pendingBossTaskCandidateBossIdentity = bossIdentity;
		this.pendingBossTaskCandidateSlayerIdentity = candidateSlayerIdentity;
		if (metric != null)
		{
			this.pendingBossTaskCandidateMetrics.add(metric);
		}
	}

	/** Clears the pending candidate (identity watch AND its buffered metrics) -- called on confirm (real switch), abort (self-consumption), an explicit forced-resolution flush, or reset(). */
	void clearBossTaskCandidate()
	{
		this.pendingBossTaskCandidateBossIdentity = null;
		this.pendingBossTaskCandidateSlayerIdentity = null;
		this.pendingBossTaskCandidateMetrics.clear();
	}

	/** True only when a candidate is pending for EXACTLY this boss identity. */
	boolean hasBossTaskCandidateFor(ActivityIdentity bossIdentity)
	{
		return pendingBossTaskCandidateBossIdentity != null && pendingBossTaskCandidateBossIdentity.equals(bossIdentity);
	}

	/** The candidate Slayer identity a pending watch would switch to if confirmed, or null if none is pending. */
	ActivityIdentity getPendingBossTaskCandidateSlayerIdentity()
	{
		return pendingBossTaskCandidateSlayerIdentity;
	}

	/**
	 * The buffered MetricUpdate(s) -- possibly from more than one
	 * still-unresolved own-task-progress event -- a pending candidate is
	 * holding, as a defensive copy (never null, empty when nothing is
	 * pending). See class javadoc's CANDIDATE-METRIC BUFFERING section
	 * for exactly when/where these are ultimately applied.
	 */
	List<MetricUpdate> getPendingBossTaskCandidateMetrics()
	{
		return new ArrayList<>(pendingBossTaskCandidateMetrics);
	}

	/**
	 * Called only from
	 * ActivitySignalClassifier.classify()'s NPC_INTERACTION_TARGET
	 * branch. ARMS (a fresh target) or REPLACES (a different target) the
	 * watch, always refreshing the "last seen" tick/instant to THIS
	 * observation's own -- a genuinely new interaction target is itself
	 * evidence the player is right now engaging it. npcName is expected
	 * non-null in practice (the production collector never emits this
	 * signal for a null-named target -- see NpcInteractionTargetCollector),
	 * but this method does not itself validate that; it simply stores
	 * whatever it is given, mirroring onSlayerTaskAssigned()/
	 * onSlayerTaskProgress()'s own "trust the caller" discipline.
	 */
	void onNpcInteractionTarget(Integer npcId, String npcName, Long gameTick, Instant observedAt)
	{
		this.recentTargetNpcId = npcId;
		this.recentTargetNpcName = npcName;
		this.recentTargetLastSeenTick = gameTick;
		this.recentTargetLastSeenAt = observedAt;
	}

	/**
	 * Called only from
	 * ActivitySignalClassifier.classifyXpChange()'s combat branch, for
	 * the one and only signal kind allowed to actually CONSUME (read
	 * AND refresh) this context -- see the field javadoc above for why
	 * this is a sliding window rather than a fixed TTL. Returns the
	 * tracked NPC's display name when the watch is still fresh as of
	 * (currentTick, currentObservedAt) -- refreshing its own last-seen
	 * tick/instant to these as a side effect -- or null when nothing is
	 * tracked, or the tracked watch has aged past RECENT_TARGET_MAX_AGE_TICKS/
	 * RECENT_TARGET_MAX_AGE. A null return leaves the stale watch's
	 * fields untouched (never actively cleared here) -- a fresh
	 * InteractingChanged for a genuinely new target will overwrite them
	 * via onNpcInteractionTarget() regardless, and there is no other
	 * reader of this state that a stale value could mislead in the
	 * meantime.
	 */
	String consumeRecentTargetNpcNameIfFresh(Long currentTick, Instant currentObservedAt)
	{
		if (recentTargetNpcName == null || !isRecentTargetFresh(currentTick, currentObservedAt))
		{
			return null;
		}
		if (currentTick != null)
		{
			this.recentTargetLastSeenTick = currentTick;
		}
		if (currentObservedAt != null)
		{
			this.recentTargetLastSeenAt = currentObservedAt;
		}
		return recentTargetNpcName;
	}

	/**
	 * Called ONLY from
	 * ActivitySignalClassifier.classifyXpChange()'s combat branch (via
	 * genericCombatOrNpcIdentity()) -- the READ-ONLY twin of
	 * consumeRecentTargetNpcNameIfFresh() above. Same exact freshness
	 * rule (see isRecentTargetFresh()), but never mutates
	 * recentTargetLastSeenTick/At as a side effect: the slow, aggregated
	 * XP_CHANGE cadence must be able to SEE a still-fresh watch (kept
	 * fresh by real-time RAW_COMBAT_XP_OBSERVED pulses) without itself
	 * being trusted to EXTEND that freshness -- see the class javadoc's
	 * TEMPORAL-DESIGN FOLLOW-UP FIX section for the full rationale (this
	 * is what stops a stale NPC identity from self-perpetuating merely
	 * because delayed XP_CHANGE events keep arriving after the player
	 * has genuinely stopped fighting).
	 */
	String peekRecentTargetNpcNameIfFresh(Long currentTick, Instant currentObservedAt)
	{
		if (recentTargetNpcName == null || !isRecentTargetFresh(currentTick, currentObservedAt))
		{
			return null;
		}
		return recentTargetNpcName;
	}

	/**
	 * See consumeRecentTargetNpcNameIfFresh()'s and the RECENT_TARGET_MAX_AGE*
	 * field javadoc for the exact bounded rule. Prefers a tick-based
	 * comparison whenever BOTH the stored watch and the query carry a
	 * gameTick (the normal real-runtime case); falls back to a
	 * wall-clock Duration comparison otherwise. An out-of-order query
	 * (currentTick/currentObservedAt earlier than what is already
	 * stored) is conservatively treated as NOT fresh, mirroring
	 * SessionLifecycleEngine's own out-of-order handling elsewhere in
	 * this package.
	 */
	private boolean isRecentTargetFresh(Long currentTick, Instant currentObservedAt)
	{
		if (recentTargetLastSeenTick != null && currentTick != null)
		{
			long ageTicks = currentTick - recentTargetLastSeenTick;
			return ageTicks >= 0 && ageTicks <= RECENT_TARGET_MAX_AGE_TICKS;
		}
		if (recentTargetLastSeenAt == null || currentObservedAt == null)
		{
			return false;
		}
		Duration age = Duration.between(recentTargetLastSeenAt, currentObservedAt);
		return !age.isNegative() && age.compareTo(RECENT_TARGET_MAX_AGE) <= 0;
	}

	/**
	 * The NPC id last
	 * associated with the current recent-target watch, retained purely
	 * as metadata (see EventType.NPC_INTERACTION_TARGET's own javadoc --
	 * ordinary session identity never requires this) -- null when
	 * nothing is currently tracked. Not freshness-gated: callers that
	 * need to know whether the watch is still valid should go through
	 * consumeRecentTargetNpcNameIfFresh() instead.
	 */
	Integer getRecentTargetNpcId()
	{
		return recentTargetNpcId;
	}

	/** Explicit reset for a future account switch. */
	public void reset()
	{
		this.activeSlayerTaskName = null;
		this.activeSlayerTaskLocation = null;
		this.lastKnownSlayerCurrentRemaining = null;
		clearBossTaskCandidate();
		this.recentTargetNpcId = null;
		this.recentTargetNpcName = null;
		this.recentTargetLastSeenTick = null;
		this.recentTargetLastSeenAt = null;
		this.xpBoundaryOwnerSessionId = null;
		this.xpAtSessionStartBySkill.clear();
		this.structuredActivity.clear();
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Instant;
import lombok.AccessLevel;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

/**
 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A). The additive,
 * account-scoped persistence record for the ONE interrupted/resumable
 * prior session, if any -- see SessionLifecycleEngine's own
 * interruptedCandidate field javadoc for the full feature. Written and
 * read exclusively by SessionPersistence, via
 * TelemetryPaths.interruptedCandidateFile(accountHash), as a small
 * SEPARATE file rather than any change to session_state.json's own
 * shape or the finalized sessions/{sessionId}.json document format --
 * both of those remain byte-for-byte exactly as they were before this
 * feature existed. Absence of this file (a missing/malformed/`null`
 * read -- see LocalStateStore.readIfExists()'s existing fail-open
 * contract, reused here unchanged) means "nothing parked," which is
 * both the correct steady-state answer for every account and the
 * correct answer for an account that predates this feature entirely --
 * full backward compatibility, no migration.
 *
 * Deliberately a plain additive DTO, not a change to Session itself:
 * `session` below is the parked candidate's own full, unmodified
 * Session document (same sessionId/startedAt/aggregates/state it had
 * the instant it was parked -- still logically ACTIVE, never given a
 * new SessionState value; see SessionState's own closed-3-value
 * javadoc for why no 4th "PARKED" state was added anywhere in this
 * project). `interruptedAt`/`expiresAt` mirror
 * SessionLifecycleEngine's own in-memory
 * interruptedCandidateInterruptedAt/interruptedCandidateExpiresAt
 * fields exactly, so a restart can reconstruct identical in-memory
 * state via SessionLifecycleEngine.rehydrate()'s 5-arg overload.
 *
 * TIMESTAMP CONVENTION: same nullable ISO-8601 String fields as
 * Session (see its own javadoc) -- Gson-friendly, no custom
 * TypeAdapter required.
 */
@Getter
@Setter(AccessLevel.PACKAGE)
@ToString
@EqualsAndHashCode
@NoArgsConstructor
public class InterruptedCandidateRecord
{
	private Session session;
	private String interruptedAt;
	private String expiresAt;

	InterruptedCandidateRecord(Session session, Instant interruptedAt, Instant expiresAt)
	{
		this.session = session;
		this.interruptedAt = interruptedAt == null ? null : interruptedAt.toString();
		this.expiresAt = expiresAt == null ? null : expiresAt.toString();
	}

	Instant interruptedAtInstant()
	{
		return interruptedAt == null ? null : Instant.parse(interruptedAt);
	}

	Instant expiresAtInstant()
	{
		return expiresAt == null ? null : Instant.parse(expiresAt);
	}
}

package com.osrstelemetry.plugin.session;

import java.util.Collections;
import java.util.List;

/**
 * The return value of every SessionLifecycleEngine
 * transition method. Two original, both-nullable pieces of
 * information:
 *
 *   - current: the session now considered "in progress" (ACTIVE or
 *     SUSPENDED), or null if there is none (e.g. right after a
 *     timeout-finalization with no new activity to replace it).
 *   - finalized: a session that was JUST transitioned to FINALIZED as
 *     a side effect of this call, or null if nothing finalized. This
 *     is the exact, and only, signal a caller needs to know "write an
 *     immutable sessions/{sessionId}.json record now" (see
 *     SessionPersistence.persistFinalized()) — a Session is never
 *     returned here more than once, since the engine always replaces
 *     its internal `current` reference with a different object before
 *     returning.
 *
 * PLUS three fields that
 * exist ONLY because a weak-evidence candidate can leave a calling
 * signal's own metrics in a genuinely undecided state -- see
 * SessionLifecycleEngine's own candidate-lifecycle javadoc for the
 * full design:
 *
 *   - metricsForCurrent: metrics the caller should apply to
 *     getCurrent()'s aggregates right now (never null -- empty when
 *     there is nothing to apply, e.g. this call only armed or
 *     replaced a pending candidate, buffering its metrics instead of
 *     applying them anywhere yet).
 *   - contextualMetricsTarget / contextualMetrics: an ABANDONED
 *     candidate's previously-buffered metrics, committed EXACTLY ONCE
 *     to whichever session was the established one BEFORE this call
 *     (contextualMetricsTarget is that same Session object -- it is
 *     always either the just-returned getCurrent() unchanged, or the
 *     just-returned getFinalized(), never a third object) -- as plain
 *     aggregate contributions, with no lifecycle side effects
 *     whatsoever (SessionAggregateUpdater, the only thing a caller
 *     ever applies these through, never touches state/lastActiveAt/
 *     activityIdentity/duration). contextualMetricsTarget is null,
 *     and contextualMetrics empty, whenever there was no abandoned
 *     candidate to commit.
 *
 * PLUS one field from the interrupted-activity-resume feature --
 * see {@link #getAdditionalFinalized()}'s own javadoc: a second,
 * independently-finalized session that can legitimately co-occur
 * with {@link #getFinalized()} in the same call, since the one
 * parked interrupted-prior-session candidate runs on its own
 * lifecycle clock, separate from `current`'s.
 *
 * Deliberately a plain immutable value rather than reusing Session
 * itself with booleans bolted on — keeping "what to treat as
 * current", "what to durably persist as finalized", and "which
 * metrics go where" as clearly separate questions a caller must
 * handle independently.
 */
public final class LifecycleResult
{
	private final Session current;
	private final Session finalized;
	private final List<MetricUpdate> metricsForCurrent;
	private final Session contextualMetricsTarget;
	private final List<MetricUpdate> contextualMetrics;
	private final Session additionalFinalized;

	private LifecycleResult(Session current, Session finalized, List<MetricUpdate> metricsForCurrent,
		Session contextualMetricsTarget, List<MetricUpdate> contextualMetrics, Session additionalFinalized)
	{
		this.current = current;
		this.finalized = finalized;
		this.metricsForCurrent = metricsForCurrent == null ? Collections.emptyList() : metricsForCurrent;
		this.contextualMetricsTarget = contextualMetricsTarget;
		this.contextualMetrics = contextualMetrics == null ? Collections.emptyList() : contextualMetrics;
		this.additionalFinalized = additionalFinalized;
	}

	/** No metrics involved at all (e.g. advanceTime()'s ordinary, no-candidate path). */
	static LifecycleResult of(Session current, Session finalized)
	{
		return new LifecycleResult(current, finalized, null, null, null, null);
	}

	/** This call's own metrics apply directly to the returned `current` -- no candidate involved. */
	static LifecycleResult withMetrics(Session current, Session finalized, List<MetricUpdate> metricsForCurrent)
	{
		return new LifecycleResult(current, finalized, metricsForCurrent, null, null, null);
	}

	/** Full form: both this call's own metrics AND an abandoned candidate's committed-once metrics. */
	static LifecycleResult withMetricsAndContextual(Session current, Session finalized,
		List<MetricUpdate> metricsForCurrent, Session contextualMetricsTarget, List<MetricUpdate> contextualMetrics)
	{
		return new LifecycleResult(current, finalized, metricsForCurrent, contextualMetricsTarget, contextualMetrics, null);
	}

	public Session getCurrent()
	{
		return current;
	}

	public Session getFinalized()
	{
		return finalized;
	}

	List<MetricUpdate> getMetricsForCurrent()
	{
		return metricsForCurrent;
	}

	Session getContextualMetricsTarget()
	{
		return contextualMetricsTarget;
	}

	List<MetricUpdate> getContextualMetrics()
	{
		return contextualMetrics;
	}

	/**
	 * ADDED (interrupted-activity-resume feature). A SECOND session
	 * finalized as a side effect of this SAME call, independent of
	 * {@link #getFinalized()} -- exists only because the one parked
	 * interrupted-prior-session candidate (see SessionLifecycleEngine's
	 * own "INTERRUPTED-RESUME CANDIDATE" section) has its own
	 * independent lifecycle clock from `current`'s, so a single call
	 * can legitimately finalize BOTH `current`'s own session (via the
	 * ordinary ACTIVE/SUSPENDED machinery this class already documented)
	 * AND the parked candidate (its own resume window independently
	 * expiring, or a second real switch permanently displacing it) in
	 * the same instant. Never the same object as {@link #getFinalized()}
	 * (there are only ever two distinct finalizable sessions in play at
	 * once: `current`'s own, and the one parked candidate's). Null in
	 * every case where nothing about the parked candidate changed this
	 * call.
	 */
	public Session getAdditionalFinalized()
	{
		return additionalFinalized;
	}

	/**
	 * Attaches a second, independently-finalized session (see
	 * {@link #getAdditionalFinalized()}) to an already-built result.
	 * `additionalFinalized == null` is a safe no-op (returns `this`
	 * unchanged) so every call site can use this unconditionally.
	 */
	LifecycleResult withAdditionalFinalized(Session additionalFinalized)
	{
		if (additionalFinalized == null)
		{
			return this;
		}
		return new LifecycleResult(current, finalized, metricsForCurrent, contextualMetricsTarget, contextualMetrics, additionalFinalized);
	}

	/**
	 * Attaches contextual metrics (see {@link #getContextualMetricsTarget()})
	 * to an already-built result that did not otherwise need to carry
	 * any -- used by the interrupted-resume real-switch path, whose
	 * contextual-metrics target may be the session that was JUST parked
	 * as the interrupted candidate rather than {@link #getFinalized()}
	 * itself (a legitimate third possibility this class's original
	 * contract predates -- {@code contextualMetricsTarget} is always
	 * some Session object this same call is returning a live reference
	 * to, in whichever capacity: current, finalized, additionalFinalized,
	 * or the newly-parked candidate).
	 */
	LifecycleResult withContextualMetrics(Session contextualMetricsTarget, List<MetricUpdate> contextualMetrics)
	{
		return new LifecycleResult(current, finalized, metricsForCurrent, contextualMetricsTarget, contextualMetrics, additionalFinalized);
	}
}

package com.osrstelemetry.plugin.session;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * A small, purely in-memory, NON-DURABLE ledger of "XP
 * gained since the last XP_CHANGE flush for this skill," scoped to
 * whichever session currently owns it. This exists SOLELY to close the
 * player-visible latency gap between a real XP gain (immediate,
 * per-skill, via raw StatChanged) and SkillsCollector's own slow,
 * aggregated XP_CHANGE flush (~30s cadence, unchanged by this class --
 * see SkillsCollector.closeXpWindowsIfDue()) actually reaching the
 * session's durable {@link SessionAggregates#getXpGainedBySkill()}.
 *
 * HARD RULE: this class NEVER becomes durable, NEVER writes to
 * SessionAggregates, NEVER is persisted, and NEVER causes a second XP
 * MetricUpdate to be applied anywhere. It is consulted ONLY when
 * building a read-only {@link SessionSnapshot} for the player-facing
 * panel (see {@link SessionRuntimeCoordinator#getCurrentSessionSnapshot()}).
 * The one and only durable/canonical XP accounting path remains exactly
 * as it was: raw StatChanged -&gt; SkillsCollector's own
 * windowBaselineXp/windowStart -&gt; XP_CHANGE event (~30s cadence) -&gt;
 * SessionEventMapper -&gt; classifyXpChange() -&gt; MetricUpdate.xp() -&gt;
 * SessionAggregateUpdater.apply() -&gt; SessionAggregates.xpGainedBySkill.
 * This class is never in that chain.
 *
 * OWNERSHIP MODEL (see recordDelta()'s own javadoc for the exact rule):
 * this tracker holds pending XP for exactly ONE "owner" session id at a
 * time -- whichever session was current the last time a delta was
 * recorded. The moment a delta arrives for a DIFFERENT session id (a
 * genuine session switch -- the old session finalized/abandoned, a new
 * one now current), every previously-tracked pending amount is
 * discarded before tracking restarts fresh for the new owner. This is
 * deliberately simpler than a multi-session map: the old session's own
 * truth is never at risk (its real XP still reaches its own durable
 * aggregates via the ordinary XP_CHANGE path, on its own schedule,
 * completely independent of this class), and nothing durable is ever
 * lost by discarding a stale LIVE-ONLY figure that is no longer even
 * being displayed (only the CURRENT session's snapshot is ever built).
 * A SUSPENDED session that later RESUMES keeps the SAME sessionId
 * throughout (see SessionLifecycleEngine), so an ordinary suspend/
 * resume never triggers this discard -- only a genuine identity switch
 * (a new/different session becoming current) does.
 *
 * RECONCILIATION (see reconcile()'s own javadoc): the moment a REAL
 * XP_CHANGE-derived MetricUpdate is applied to this tracker's current
 * owner session for some skill, that durable application now fully
 * represents the raw gains that window carried -- so exactly that much
 * of the live, "not yet represented" portion for that (session, skill)
 * pair is removed (clamped at zero; gains made after the window closed
 * stay pending for the next one). This is what guarantees the exact-once
 * DISPLAY total the task requires: T0 canonical=100; T1 a live +40 gain
 * makes the panel show 140 (100 durable + 40 live-pending); T2 XP_CHANGE
 * flushes the same +40 into the durable aggregate (canonical becomes 140)
 * AND this tracker's pending amount for that skill drops by 40 to 0 in
 * the SAME reconcile() call -- so the panel's own displayed total (140
 * durable + 0 pending) never jumps to 180, and never dips either. See
 * CurrentSessionSnapshotTest/SessionSnapshotTest for the exact assertions.
 */
final class LiveXpTracker
{
	private String ownerSessionId;
	private final Map<String, Long> pendingXpBySkill = new HashMap<>();

	/**
	 * Records an immediate, live XP gain of {@code delta} for
	 * {@code skill}, attributed to {@code sessionId}.
	 *
	 * <p>{@code sessionId == null} means there is no current session at
	 * all to attach this gain to -- dropped, never buffered
	 * speculatively for some future session (there is no honest
	 * ownership to assign it to yet; see class javadoc).
	 *
	 * <p>{@code delta <= 0} is always ignored -- this layer must never
	 * fabricate positive live XP from a decrease, a reset, or a
	 * first-observation reseed (those are the caller's -- SkillsCollector's
	 * own evaluateLiveXpDelta() -- responsibility to have already
	 * filtered out before calling this method at all; this is a second,
	 * defense-in-depth guarantee).
	 *
	 * <p>A {@code sessionId} different from the currently tracked owner
	 * is treated as a genuine session switch: every previously pending
	 * amount is discarded (see class javadoc's OWNERSHIP MODEL) before
	 * this delta is recorded as the new owner's first entry.
	 */
	void recordDelta(String sessionId, String skill, long delta)
	{
		if (sessionId == null || skill == null || delta <= 0)
		{
			return;
		}
		if (!sessionId.equals(ownerSessionId))
		{
			pendingXpBySkill.clear();
			ownerSessionId = sessionId;
		}
		Long existing = pendingXpBySkill.get(skill);
		pendingXpBySkill.put(skill, (existing == null ? 0L : existing) + delta);
	}

	/**
	 * Called once a real, durable XP metric for {@code skill} has just
	 * been applied to {@code sessionId}'s own canonical aggregates
	 * (see {@link SessionRuntimeCoordinator}'s applyMetrics()). Resets
	 * the live pending amount for that exact (session, skill) pair to
	 * zero -- see class javadoc's RECONCILIATION section for why this
	 * is what guarantees an exact-once display total.
	 *
	 * <p>A no-op whenever {@code sessionId} is not the currently
	 * tracked owner: that XP metric belongs to some OTHER session's own
	 * reconciliation (an abandoned/finalized session's delayed XP_CHANGE
	 * finally arriving after this tracker has already moved on to a new
	 * current owner) -- never this tracker's live view of the session
	 * that is actually current right now.
	 */
	void reconcile(String sessionId, String skill)
	{
		reconcile(sessionId, skill, null);
	}

	/**
	 * As {@link #reconcile(String, String)}, but removes only the XP the
	 * applied durable window actually carried ({@code appliedDelta}; null =
	 * everything). A window is resolved one tick after it closes, and the
	 * StatChanged gains of that next tick are already pending by then --
	 * they belong to the NEXT window and must stay visible, otherwise the
	 * displayed total dips until the next flush. Clamped at zero, so it
	 * can never make the display count anything twice.
	 */
	void reconcile(String sessionId, String skill, Long appliedDelta)
	{
		if (sessionId == null || skill == null || !sessionId.equals(ownerSessionId))
		{
			return;
		}
		Long pending = pendingXpBySkill.get(skill);
		if (pending == null)
		{
			return;
		}
		long left = appliedDelta == null ? 0L : pending - Math.max(0L, appliedDelta);
		if (left > 0L)
		{
			pendingXpBySkill.put(skill, left);
		}
		else
		{
			pendingXpBySkill.remove(skill);
		}
	}

	/**
	 * The live pending XP for {@code skill} under {@code sessionId} --
	 * {@code 0} whenever {@code sessionId} is not the currently tracked
	 * owner, or no live delta has been recorded for that skill since
	 * the last reconcile()/session switch.
	 */
	long getPending(String sessionId, String skill)
	{
		if (sessionId == null || !sessionId.equals(ownerSessionId))
		{
			return 0L;
		}
		Long pending = pendingXpBySkill.get(skill);
		return pending == null ? 0L : pending;
	}

	/**
	 * Every skill with a nonzero live pending amount currently tracked
	 * for {@code sessionId} -- an unmodifiable, defensively-copied
	 * snapshot (never a live view over this tracker's own internal
	 * map). Empty whenever {@code sessionId} is not the currently
	 * tracked owner.
	 */
	Map<String, Long> getPendingForSession(String sessionId)
	{
		if (sessionId == null || !sessionId.equals(ownerSessionId))
		{
			return Collections.emptyMap();
		}
		return Collections.unmodifiableMap(new HashMap<>(pendingXpBySkill));
	}

	/**
	 * Clears all tracked state -- called on account switch (see
	 * {@link SessionRuntimeCoordinator#ensureAccountLoaded(long)}), so
	 * a brand-new account never inherits a stale owner/pending amount
	 * left over from the previous account.
	 */
	void reset()
	{
		ownerSessionId = null;
		pendingXpBySkill.clear();
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import java.time.Duration;
import java.time.Instant;

/**
 * The
 * pure resolution ladder described by {@link LoadoutProvenance}'s own
 * javadoc, implemented against whatever short-lived in-memory
 * {@link LoadoutArchive} this plugin process currently holds. Owned by
 * SessionPersistence (see its "resolver" field); never called
 * directly by SessionRuntimeCoordinator/SessionLifecycleEngine -- see
 * Session's own javadoc on why the integration point is
 * SessionPersistence, not the lifecycle/classifier machinery.
 *
 * NULL-SAFE BY CONSTRUCTION: a null archive (SessionPersistence's
 * single-arg constructor, kept for backward compatibility with
 * existing callers/tests that never had a loadout archive to pass)
 * makes every resolution honestly UNAVAILABLE rather than throwing --
 * this resolver is always safe to call unconditionally.
 */
public final class LoadoutResolver
{
	/**
	 * How far before the resolution TARGET instant (see
	 * {@link #STARTING_LOADOUT_TARGET_OFFSET}) this resolver will still
	 * trust a state-history observation as genuinely representative of
	 * what the player had at that target point. Comfortably inside
	 * LoadoutArchive.MAX_AGE, so a qualifying observation is never
	 * pruned out from under a resolution attempt that would otherwise
	 * have found it. This is the "reliable" cutoff this resolver
	 * means by "no reliable state exists for that target point" --
	 * beyond this window, an observation is treated as too stale to
	 * honestly claim as the target instant's state, and resolution
	 * falls through to the fallback step instead of fabricating
	 * accuracy.
	 */
	static final Duration PRE_START_LOOKBACK = Duration.ofMinutes(5);

	/**
	 * A starting
	 * loadout is meant to represent the player's loadout from
	 * approximately this long BEFORE the session actually began, not
	 * the instant the session began -- see {@link #resolveStarting}'s
	 * own javadoc for the full rationale and the worked example this
	 * offset exists to satisfy.
	 */
	static final Duration STARTING_LOADOUT_TARGET_OFFSET = Duration.ofSeconds(30);

	private final LoadoutArchive archive;

	public LoadoutResolver(LoadoutArchive archive)
	{
		this.archive = archive;
	}

	/**
	 * Resolve a STARTING loadout for a session whose startedAt is
	 * `startedAt`.
	 *
	 * TARGET-TIME, NOT STARTED-AT: a starting loadout should represent
	 * the player's loadout from approximately
	 * {@link #STARTING_LOADOUT_TARGET_OFFSET} (30s) BEFORE the session
	 * began, not whatever was observed nearest to startedAt itself.
	 * `target = startedAt - 30s` is computed once and is the single
	 * reference instant the rest of this method reasons about.
	 *
	 * STATE HISTORY, NOT AN EXACT-INSTANT SNAPSHOT REQUIREMENT: this
	 * does NOT require an observation to have been physically captured
	 * exactly at `target`. {@link LoadoutArchive#latestAtOrBefore} finds
	 * the most recent COMPLETE inventory+equipment state already in
	 * effect at or before `target` -- i.e. loadout snapshots are treated
	 * as state history (a state holds until the next observed change),
	 * not point samples. Worked example from the spec: a player equips
	 * gear at T-2min, nothing changes afterward, and the session begins
	 * at T (target = T-30s) -- the T-2min observation is still the
	 * state in effect at T-30s, so it is correctly used, even though no
	 * observation happened to land exactly on T-30s itself.
	 *
	 * Ladder: (1) the most recent complete observation at or before
	 * `target`, IF it falls within {@link #PRE_START_LOOKBACK} of
	 * `target` (the "reliable" cutoff -- see that field's own javadoc)
	 * -- PRE_START; (2) else the earliest complete observation at or
	 * after `target` -- FALLBACK_AT_OR_AFTER_START, the honest
	 * fallback for "no reliable state exists for that target point",
	 * re-anchored to `target` rather than
	 * `startedAt` so it is answering the same question step (1) asked,
	 * not a different one; (3) else UNAVAILABLE.
	 * No new persisted/noisy snapshot machinery is introduced -- this
	 * refines the existing {@link LoadoutArchive} query surface only,
	 * preferring to use/refine the existing LoadoutArchive over adding new machinery.
	 */
	public LoadoutSnapshot resolveStarting(Instant startedAt)
	{
		if (archive == null || startedAt == null)
		{
			return LoadoutSnapshot.unavailable();
		}

		Instant target = startedAt.minus(STARTING_LOADOUT_TARGET_OFFSET);

		LoadoutArchive.Entry atOrBeforeTarget = archive.latestAtOrBefore(target);
		if (atOrBeforeTarget != null && !atOrBeforeTarget.getObservedAt().isBefore(target.minus(PRE_START_LOOKBACK)))
		{
			return toSnapshot(atOrBeforeTarget, LoadoutProvenance.PRE_START);
		}

		LoadoutArchive.Entry fallback = archive.earliestAtOrAfter(target);
		if (fallback != null)
		{
			return toSnapshot(fallback, LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);
		}

		return LoadoutSnapshot.unavailable();
	}

	/**
	 * Resolve an OPTIONAL ENDING loadout as of `referenceInstant`
	 * -- ordinarily a session's finalizedAt, i.e.
	 * essentially "now" at the moment finalization happens. PRE_START
	 * is never produced here -- see LoadoutProvenance's own javadoc:
	 * there is no "before finalization" preference the way there is a
	 * "before the session started" preference for the starting
	 * loadout, so both the at-or-before and the (rare) after case are
	 * labeled FALLBACK_AT_OR_AFTER_START. Ladder: (1) the most recent
	 * complete observation at or before referenceInstant; (2) else the
	 * earliest complete observation after it (covers the narrow race
	 * where the final container observation lags slightly behind the
	 * finalization decision); (3) else UNAVAILABLE -- never blocks
	 * finalization either way.
	 */
	public LoadoutSnapshot resolveEnding(Instant referenceInstant)
	{
		if (archive == null || referenceInstant == null)
		{
			return LoadoutSnapshot.unavailable();
		}

		LoadoutArchive.Entry atOrBefore = archive.latestAtOrBefore(referenceInstant);
		if (atOrBefore != null)
		{
			return toSnapshot(atOrBefore, LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);
		}

		LoadoutArchive.Entry after = archive.earliestAtOrAfter(referenceInstant);
		if (after != null)
		{
			return toSnapshot(after, LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);
		}

		return LoadoutSnapshot.unavailable();
	}

	private static LoadoutSnapshot toSnapshot(LoadoutArchive.Entry entry, LoadoutProvenance provenance)
	{
		return new LoadoutSnapshot(entry.getInventory(), entry.getEquipment(), entry.getObservedAt().toString(), provenance);
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.model.StorageState;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

/**
 * An
 * immutable, slot-exact inventory+equipment snapshot, persisted as a
 * finalized {@link Session}'s starting and/or ending loadout.
 *
 * SLOT-EXACT (non-optional core requirement):
 * {@code inventory} always carries exactly {@link #INVENTORY_SIZE}
 * entries, one per slot 0..27, INCLUDING explicit empty-slot entries
 * (itemId=-1, name=null, quantity=0) -- never a sparse occupied-only
 * list. {@code equipment} carries one entry per equipment slot, same
 * convention. Both reuse {@link StorageState.StorageItem} directly
 * rather than inventing a parallel item-shape class, since that
 * shape (slot / itemId / name / quantity / equipmentSlot) already
 * matches exactly what a loadout slot needs, and is already the
 * shape ContainerCollector.buildEquipmentItems() produces for
 * equipment today. The actual slot-complete CAPTURE logic (reading a
 * live ItemContainer into this shape for inventory too, which
 * ContainerCollector does not currently do -- see its own class
 * javadoc on buildSparseItems()) is handled elsewhere; this class is
 * purely the persisted/immutable data shape.
 *
 * IMMUTABILITY: both lists are defensively copied and wrapped
 * unmodifiable at construction, matching SessionSnapshot's existing
 * capture-time defensive-copy convention elsewhere in this package --
 * a caller can never mutate a persisted loadout through a reference
 * handed back by a getter. Note this guarantee is a CAPTURE-time
 * guarantee, same as every other model in this project: Gson's
 * reflective deserialization (LocalStateStore, no registered
 * TypeAdapters -- see its own javadoc) does not invoke this
 * constructor and will hand back plain (mutable) ArrayLists on a
 * round-trip from disk. That is accepted and consistent with how
 * every other persisted model in this codebase already behaves
 * (Session, SessionAggregates, StorageState itself) -- nothing else
 * in this codebase mutates a record freshly read back from an
 * immutable historical file.
 *
 * EMPTY-BUT-NEVER-NULL FOR UNAVAILABLE: when provenance is
 * UNAVAILABLE, inventory/equipment are empty lists (never null) and
 * capturedAt is null -- see {@link #unavailable()}. This keeps every
 * consumer (Gson, the History UI) able to treat the two list fields
 * uniformly regardless of provenance; only the provenance field
 * itself needs a branch.
 *
 * BACKWARD COMPATIBILITY: this type is entirely new, so
 * an old sessions/{id}.json written before this type existed has no
 * startingLoadout/endingLoadout field at all. Gson leaves both as
 * null on the deserialized Session (its ordinary missing-field
 * behavior -- see Session's own javadoc), which the History UI must
 * treat identically to an explicit {@link #unavailable()} snapshot.
 * This class itself never has to parse or migrate an old shape; see
 * SessionLoadoutBackwardCompatibilityTest for the round-trip proof.
 */
@Getter
@ToString
@EqualsAndHashCode
public final class LoadoutSnapshot
{
	/** Fixed OSRS inventory slot count -- a LoadoutSnapshot with real inventory data always carries exactly this many entries. */
	public static final int INVENTORY_SIZE = 28;

	private final List<StorageState.StorageItem> inventory;
	private final List<StorageState.StorageItem> equipment;

	/**
	 * ISO-8601 Instant#toString() of the moment this snapshot was
	 * actually observed -- deliberately NOT the session's own
	 * startedAt/finalizedAt, which may differ from this by however
	 * far the resolution ladder had to fall back (see
	 * {@link LoadoutProvenance}). Null only when provenance is
	 * UNAVAILABLE.
	 */
	private final String capturedAt;

	private final LoadoutProvenance provenance;

	public LoadoutSnapshot(List<StorageState.StorageItem> inventory, List<StorageState.StorageItem> equipment,
		String capturedAt, LoadoutProvenance provenance)
	{
		this.inventory = Collections.unmodifiableList(new ArrayList<>(inventory));
		this.equipment = Collections.unmodifiableList(new ArrayList<>(equipment));
		this.capturedAt = capturedAt;
		this.provenance = provenance;
	}

	/**
	 * The canonical "nothing could be resolved" instance -- never
	 * fabricates placeholder items, never leaves the lists null.
	 */
	public static LoadoutSnapshot unavailable()
	{
		return new LoadoutSnapshot(Collections.emptyList(), Collections.emptyList(), null, LoadoutProvenance.UNAVAILABLE);
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Instant;
import java.util.List;

/**
 * A pure description of an
 * aggregate change -- distinguishing the authoritative-value vs.
 * session-occurrences reliable-count split, and, for the
 * slayer-progress kind, optionally carrying the originating event's
 * own authoritative currentRemaining -- kept entirely separate from SignalDecisionKind's
 * lifecycle decision so a whole game-tick batch's metrics can all be
 * applied together regardless of which single classification (if any)
 * governed the lifecycle transition for that tick (see
 * SessionSignalBatchResolver).
 *
 * Exactly one of the four kinds of update is populated per instance
 * (see the static factories) -- never a general-purpose bag of every
 * field at once. slayerCurrentRemaining rides ALONGSIDE
 * slayerProgressValue as part of the SAME slayer-progress kind (both
 * originate from the same SLAYER_TASK_PROGRESS event) rather than being
 * a fifth, separate kind.
 */
final class MetricUpdate
{
	private final String xpSkill;
	private final Long xpDelta;

	private final String lootSourceName;
	private final String lootObservedAt;
	private final List<SessionSignal.LootDrop> lootDrops;

	private final SessionAggregates.ReliableCountKind reliableCountKind;
	private final String reliableCountSourceKey;
	private final Integer reliableCountAuthoritativeValue;

	private final Integer slayerProgressValue;
	private final Integer slayerCurrentRemaining;

	/**
	 * SMART SLAYER: when this metric's underlying game event happened (an
	 * XP window's own START, or the observing signal's time), used only to
	 * credit it to the right Slayer assignment record -- e.g. a final
	 * kill's XP whose window began before the task completed. Null =
	 * unknown (credited to the current, unfinished assignment only).
	 * Never affects session-wide aggregation.
	 */
	/** One structured-activity completion (activity key) and the game's running count, if known. */
	private String activityCompletionKey;
	private Integer activityCompletionAuthoritativeValue;

	/** STRUCTURED ACTIVITY STATS (see SessionAggregates.ActivitySessionStats); key non-null = a stats update. */
	private String activityStatsKey;
	private Long currencyGained;
	/** Which currency currencyGained is for (null = the activity's single currency). */
	private String currencyKey;
	/** Produced items (output, never loot) for the activity's own session. */
	private List<SessionSignal.LootDrop> producedItems;
	private Integer score;
	private Integer scoreCompletionCount;
	private boolean scoreTrusted;
	private boolean scoreUpdate;

	private Instant referenceTime;

	/** SLAYER_BRACELET_EFFECT: "SLAUGHTER" / "EXPEDITIOUS" -- one proc for the assignment current at referenceTime. */
	private String slayerBraceletEffect;

	private MetricUpdate(
		String xpSkill,
		Long xpDelta,
		String lootSourceName,
		String lootObservedAt,
		List<SessionSignal.LootDrop> lootDrops,
		SessionAggregates.ReliableCountKind reliableCountKind,
		String reliableCountSourceKey,
		Integer reliableCountAuthoritativeValue,
		Integer slayerProgressValue,
		Integer slayerCurrentRemaining)
	{
		this.xpSkill = xpSkill;
		this.xpDelta = xpDelta;
		this.lootSourceName = lootSourceName;
		this.lootObservedAt = lootObservedAt;
		this.lootDrops = lootDrops;
		this.reliableCountKind = reliableCountKind;
		this.reliableCountSourceKey = reliableCountSourceKey;
		this.reliableCountAuthoritativeValue = reliableCountAuthoritativeValue;
		this.slayerProgressValue = slayerProgressValue;
		this.slayerCurrentRemaining = slayerCurrentRemaining;
	}

	/** This same metric with its game-event reference time set (see referenceTime). */
	MetricUpdate withReferenceTime(Instant referenceTime)
	{
		MetricUpdate copy = new MetricUpdate(xpSkill, xpDelta, lootSourceName, lootObservedAt, lootDrops,
			reliableCountKind, reliableCountSourceKey, reliableCountAuthoritativeValue, slayerProgressValue, slayerCurrentRemaining);
		copy.referenceTime = referenceTime;
		copy.activityCompletionKey = activityCompletionKey;
		copy.activityCompletionAuthoritativeValue = activityCompletionAuthoritativeValue;
		copy.activityStatsKey = activityStatsKey;
		copy.currencyGained = currencyGained;
		copy.currencyKey = currencyKey;
		copy.producedItems = producedItems;
		copy.score = score;
		copy.scoreCompletionCount = scoreCompletionCount;
		copy.scoreTrusted = scoreTrusted;
		copy.scoreUpdate = scoreUpdate;
		copy.slayerBraceletEffect = slayerBraceletEffect;
		return copy;
	}

	Instant getReferenceTime()
	{
		return referenceTime;
	}

	static MetricUpdate xp(String skill, long delta)
	{
		return new MetricUpdate(skill, delta, null, null, null, null, null, null, null, null);
	}

	static MetricUpdate loot(String sourceName, Instant observedAt, List<SessionSignal.LootDrop> drops)
	{
		return new MetricUpdate(null, null, sourceName, observedAt.toString(), drops, null, null, null, null, null);
	}

	/**
	 * `authoritativeValue` is the raw absolute account-wide
	 * number a game message reported (e.g. account KC) -- NOT a
	 * session-scoped kill count. SessionAggregateUpdater is solely
	 * responsible for deriving how many of those are attributable to
	 * the current session.
	 */
	static MetricUpdate reliableCount(SessionAggregates.ReliableCountKind kind, String sourceKey, int authoritativeValue)
	{
		return new MetricUpdate(null, null, null, null, null, kind, sourceKey, authoritativeValue, null, null);
	}

	/**
	 * `unitsConsumed` is this ONE observed Slayer progress
	 * event's own taskUnitsConsumed (see
	 * SessionSignal.slayerTaskProgress()'s javadoc) -- the observed
	 * decrease in the assignment's authoritative remaining-count value
	 * for this one event, NOT a physical NPC-kill count. It is not
	 * generally 1: game mechanics can make a single physical kill
	 * consume more than one task unit (e.g. an expeditious-bracelet-
	 * style proc) or zero (e.g. a bracelet-of-slaughter-style save),
	 * independent of any missed-observation reconciliation. Deliberately
	 * never an absolute task-state number
	 * (currentRemaining/previousRemaining/initialAmount) and never
	 * converted into a generic "kill" -- see SessionAggregateUpdater.apply(),
	 * which is solely responsible for accumulating these per-event values
	 * into SessionAggregates.slayerProgressDelta (a TASK-UNIT total,
	 * never a kill count) across the whole session.
	 *
	 * `currentRemaining` is this SAME event's own authoritative
	 * currentRemaining, nullable, threaded through unmodified so
	 * SessionAggregateUpdater can retain the LATEST observed value
	 * (never accumulated/summed, unlike unitsConsumed) for the
	 * player-facing display -- see SessionAggregates.latestSlayerCurrentRemaining's
	 * own javadoc.
	 */
	static MetricUpdate activityCompletion(String activityKey, Integer authoritativeValue)
	{
		MetricUpdate m = new MetricUpdate(null, null, null, null, null, null, null, null, null, null);
		m.activityCompletionKey = activityKey;
		m.activityCompletionAuthoritativeValue = authoritativeValue;
		return m;
	}

	static MetricUpdate activityCurrency(String activityKey, long gained)
	{
		return activityCurrency(activityKey, null, gained);
	}

	static MetricUpdate activityCurrency(String activityKey, String currencyKey, long gained)
	{
		MetricUpdate m = new MetricUpdate(null, null, null, null, null, null, null, null, null, null);
		m.activityStatsKey = activityKey;
		m.currencyGained = gained;
		m.currencyKey = currencyKey;
		return m;
	}

	/** Produced items for the activity's own session (routed by activityStatsKey, like the other session stats). */
	static MetricUpdate activityProduction(String activityKey, List<SessionSignal.LootDrop> items)
	{
		MetricUpdate m = new MetricUpdate(null, null, null, null, null, null, null, null, null, null);
		m.activityStatsKey = activityKey;
		m.producedItems = items;
		return m;
	}

	String getCurrencyKey()
	{
		return currencyKey;
	}

	List<SessionSignal.LootDrop> getProducedItems()
	{
		return producedItems;
	}

	/** One completed game's final score; untrusted / unknown scores still consume the completion count (dedupe). */
	static MetricUpdate activityScore(String activityKey, Integer completionCount, Integer score, boolean trusted)
	{
		MetricUpdate m = new MetricUpdate(null, null, null, null, null, null, null, null, null, null);
		m.activityStatsKey = activityKey;
		m.scoreUpdate = true;
		m.scoreCompletionCount = completionCount;
		m.score = score;
		m.scoreTrusted = trusted;
		return m;
	}

	String getActivityStatsKey()
	{
		return activityStatsKey;
	}

	Long getCurrencyGained()
	{
		return currencyGained;
	}

	boolean isScoreUpdate()
	{
		return scoreUpdate;
	}

	Integer getScore()
	{
		return score;
	}

	Integer getScoreCompletionCount()
	{
		return scoreCompletionCount;
	}

	boolean isScoreTrusted()
	{
		return scoreTrusted;
	}

	String getActivityCompletionKey()
	{
		return activityCompletionKey;
	}

	Integer getActivityCompletionAuthoritativeValue()
	{
		return activityCompletionAuthoritativeValue;
	}

	static MetricUpdate slayerBracelet(String effect)
	{
		MetricUpdate m = new MetricUpdate(null, null, null, null, null, null, null, null, null, null);
		m.slayerBraceletEffect = effect;
		return m;
	}

	String getSlayerBraceletEffect()
	{
		return slayerBraceletEffect;
	}

	static MetricUpdate slayerProgress(int unitsConsumed, Integer currentRemaining)
	{
		return new MetricUpdate(null, null, null, null, null, null, null, null, unitsConsumed, currentRemaining);
	}

	String getXpSkill()
	{
		return xpSkill;
	}

	Long getXpDelta()
	{
		return xpDelta;
	}

	String getLootSourceName()
	{
		return lootSourceName;
	}

	String getLootObservedAt()
	{
		return lootObservedAt;
	}

	List<SessionSignal.LootDrop> getLootDrops()
	{
		return lootDrops;
	}

	SessionAggregates.ReliableCountKind getReliableCountKind()
	{
		return reliableCountKind;
	}

	String getReliableCountSourceKey()
	{
		return reliableCountSourceKey;
	}

	Integer getReliableCountAuthoritativeValue()
	{
		return reliableCountAuthoritativeValue;
	}

	Integer getSlayerProgressValue()
	{
		return slayerProgressValue;
	}

	/** This event's own authoritative currentRemaining, or null. */
	Integer getSlayerCurrentRemaining()
	{
		return slayerCurrentRemaining;
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Instant;
import lombok.AccessLevel;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.Setter;
import lombok.ToString;

/**
 * The typed
 * session record — both the in-memory working object the lifecycle
 * engine mutates AND the exact document persisted to
 * session_state.json / sessions/{sessionId}.json (see
 * SessionPersistence). One object serves both purposes deliberately,
 * matching this project's existing model-class convention (StorageState,
 * SlayerState, ActivityState all double as their own persisted
 * document) rather than inventing a parallel DTO.
 *
 * TIMESTAMP CONVENTION: every timestamp field is a nullable ISO-8601
 * String (Instant#toString()/Instant#parse()), matching every other
 * timestamp field in this project (StorageState.lastObservedAt,
 * SlayerState.lastUpdated, TelemetryEvent.occurredAt) rather than a
 * java.time.Instant field directly. This is a deliberate choice, not
 * an oversight: LocalStateStore serializes with RuneLite's own
 * injected Gson (derived via `gson.newBuilder().setPrettyPrinting()
 * .create()` -- see its own javadoc), which has no registered
 * TypeAdapters for java.time.Instant, and Gson cannot reliably
 * round-trip java.time.Instant by reflection alone across JDK
 * versions. Storing Strings keeps Session directly compatible with
 * LocalStateStore's existing write()/writeAndWait()/readIfExists()
 * with zero changes to that class. The convenience *Instant()
 * accessors below exist so SessionLifecycleEngine/SessionPersistence
 * never have to sprinkle Instant.parse()/toString() calls inline.
 *
 * MUTATION IS PACKAGE-PRIVATE BY DESIGN — state cannot
 * make illegal transition paths through public API: setters are
 * `@Setter(AccessLevel.PACKAGE)`, so nothing outside
 * com.osrstelemetry.plugin.session can mutate state/timestamps/
 * accumulatedActiveDurationMillis directly. The only code that may
 * legally transition a Session is SessionLifecycleEngine (and
 * SessionPersistence's rehydration path, which delegates the actual
 * transition logic back to SessionLifecycleEngine.rehydrate() rather
 * than mutating fields itself). External code (a future UI/classifier)
 * can only read a Session, never force it into an illegal state.
 * Gson's field-reflection deserialization is unaffected by setter
 * visibility — it never calls setters at all.
 *
 * startingLoadout / endingLoadout below extend this same persisted
 * document with an optional, slot-exact inventory+equipment snapshot
 * (see LoadoutSnapshot). Both are nullable and additive: an old
 * sessions/{sessionId}.json written before these fields existed simply has
 * neither field, and Gson's default missing-field behavior leaves
 * them null on deserialization -- no migration, no rewriting of old
 * files, no risk to existing persistence (see LoadoutSnapshot's own
 * javadoc, "BACKWARD COMPATIBILITY"). Mutated the same
 * package-private way as every other field here -- only code in
 * com.osrstelemetry.plugin.session may attach a resolved loadout,
 * never SessionRuntimeCoordinator/
 * SessionLifecycleEngine, and never in a way that replaces an
 * already-attached startingLoadout (identity refinement
 * within the same sessionId must not replace the starting loadout --
 * satisfied automatically by resolving it at most once, the first
 * time this Session is persisted, and skipping resolution whenever
 * startingLoadout is already non-null).
 */
@Getter
@Setter(AccessLevel.PACKAGE)
@ToString
@EqualsAndHashCode
public class Session
{
	private String sessionId;
	private ActivityIdentity activityIdentity;
	private SessionState state;

	private LoadoutSnapshot startingLoadout;
	private LoadoutSnapshot endingLoadout;

	private String startedAt;
	private String lastActiveAt;
	private String suspendedAt;
	private String resumeWindowExpiresAt;
	private String finalizedAt;

	/**
	 * Sum of (qualifying-heartbeat-to-qualifying-heartbeat) elapsed
	 * time for the SAME activity while ACTIVE, per the exact rule in
	 * SessionLifecycleEngine's javadoc. Never includes any idle/
	 * suspended/offline interval. This is the only quantity future
	 * rate calculations (XP/hr, GP/hr) may divide by — never
	 * (now - startedAt).
	 */
	private long accumulatedActiveDurationMillis;

	private SessionAggregates aggregates = new SessionAggregates();

	Instant startedAtInstant()
	{
		return parse(startedAt);
	}

	Instant lastActiveAtInstant()
	{
		return parse(lastActiveAt);
	}

	Instant suspendedAtInstant()
	{
		return parse(suspendedAt);
	}

	Instant resumeWindowExpiresAtInstant()
	{
		return parse(resumeWindowExpiresAt);
	}

	/**
	 * Same
	 * nullable-String-to-Instant convenience as the four accessors
	 * above, added for LoadoutResolver's ending-loadout resolution
	 * (SessionPersistence.persistFinalized()) -- finalizedAt itself
	 * was already a field, this is only a missing accessor.
	 */
	Instant finalizedAtInstant()
	{
		return parse(finalizedAt);
	}

	private static Instant parse(String value)
	{
		return value == null ? null : Instant.parse(value);
	}
}

package com.osrstelemetry.plugin.session;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Pure, deterministic
 * application of a MetricUpdate onto a Session's SessionAggregates.
 *
 * Never deduplicates or drops anything by timestamp -- every
 * MetricUpdate handed to apply() is applied in full, unconditionally.
 * The "at most one lifecycle heartbeat per tick" rule lives entirely
 * in SessionSignalBatchResolver; metrics themselves must each still be
 * credited even when several arrive in the same batch.
 */
final class SessionAggregateUpdater
{
	private SessionAggregateUpdater()
	{
	}

	static void apply(SessionAggregates aggregates, MetricUpdate update)
	{
		if (update == null)
		{
			return;
		}

		if (update.getXpSkill() != null)
		{
			long delta = update.getXpDelta() == null ? 0L : update.getXpDelta();
			aggregates.getXpGainedBySkill().merge(update.getXpSkill(), delta, Long::sum);

			// SMART SLAYER: the same XP, once, into the record it belongs to
			// by its own reference time (see xpRecordFor()).
			SessionAggregates.SlayerAssignmentRecord xpRecord = xpRecordFor(aggregates, update.getReferenceTime());
			if (xpRecord != null && xpRecord.getXpGainedBySkill() != null)
			{
				xpRecord.getXpGainedBySkill().merge(update.getXpSkill(), delta, Long::sum);
			}
		}

		if (update.getLootDrops() != null)
		{
			SessionAggregates.LootDropGroup group = new SessionAggregates.LootDropGroup();
			group.setSourceName(update.getLootSourceName());
			group.setObservedAt(update.getLootObservedAt());
			List<SessionAggregates.LootItemAggregate> items = new ArrayList<>();
			for (SessionSignal.LootDrop drop : update.getLootDrops())
			{
				SessionAggregates.LootItemAggregate item = new SessionAggregates.LootItemAggregate();
				item.setItemId(drop.getItemId());
				item.setItemName(drop.getItemName());
				item.setQuantity(drop.getQuantity());
				items.add(item);
			}
			group.setItems(items);
			aggregates.getLootDrops().add(group);

			// SMART SLAYER: the same drop, once, into the current assignment
			// record (if any). Ownership was decided upstream; this only
			// partitions loot the session already owns.
			SessionAggregates.SlayerAssignmentRecord current = currentSlayerAssignment(aggregates);
			if (current != null)
			{
				for (SessionSignal.LootDrop drop : update.getLootDrops())
				{
					mergeItem(current.getItems(), drop.getItemId(), drop.getItemName(), drop.getQuantity());
				}
			}
		}

		if (update.getReliableCountAuthoritativeValue() != null)
		{
			applyReliableCount(aggregates, update);
		}

		if (update.getActivityCompletionKey() != null)
		{
			applyActivityCompletion(aggregates, update);
		}

		if (update.getActivityStatsKey() != null)
		{
			applyActivityStats(aggregates, update);
		}

		if (update.getSlayerBraceletEffect() != null)
		{
			// Same attribution rule as XP (the record current and unfinished at
			// the activation's own time), except that the completing kill's own
			// proc may share the completion instant: the end is inclusive here.
			SessionAggregates.SlayerAssignmentRecord record = xpRecordFor(aggregates, update.getReferenceTime());
			SessionAggregates.SlayerAssignmentRecord latest = currentSlayerAssignment(aggregates);
			if (record == null && latest != null && update.getReferenceTime() != null
				&& latest.getEndReason() == SlayerAssignmentEndReason.COMPLETED
				&& update.getReferenceTime().toString().equals(latest.getCompletedAt()))
			{
				record = latest;
			}
			if (record != null)
			{
				if ("SLAUGHTER".equals(update.getSlayerBraceletEffect()))
				{
					record.setSlaughterProcs((record.getSlaughterProcs() == null ? 0 : record.getSlaughterProcs()) + 1);
				}
				else if ("EXPEDITIOUS".equals(update.getSlayerBraceletEffect()))
				{
					record.setExpeditiousProcs((record.getExpeditiousProcs() == null ? 0 : record.getExpeditiousProcs()) + 1);
				}
			}
		}

		if (update.getSlayerProgressValue() != null)
		{
			// Live evidence: session_state.json's
			// slayerProgressDelta was observed holding an ABSOLUTE
			// remaining count instead of an accumulated total. This value
			// (see MetricUpdate.slayerProgress()/SessionSignal.slayerTaskProgress())
			// is always ONE event's own taskUnitsConsumed, never an absolute
			// remaining/initial value -- so, exactly like the XP accumulation
			// immediately above, it must be ADDED to whatever was already
			// credited this session, never used to overwrite it. Overwriting
			// here was the root cause of the live bug (slayerProgressDelta
			// ending up equal to the raw currentRemaining of the latest
			// event instead of the sum of units actually consumed).
			int alreadyCredited = aggregates.getSlayerProgressDelta() == null ? 0 : aggregates.getSlayerProgressDelta();
			aggregates.setSlayerProgressDelta(alreadyCredited + update.getSlayerProgressValue());

			// SMART SLAYER: the same authoritative units, once, into the
			// current assignment's own completed-unit count.
			SessionAggregates.SlayerAssignmentRecord current = currentSlayerAssignment(aggregates);
			if (current != null && current.getUnitsCompleted() != null)
			{
				current.setUnitsCompleted(current.getUnitsCompleted() + update.getSlayerProgressValue());
			}
		}

		if (update.getSlayerCurrentRemaining() != null)
		{
			// The OPPOSITE rule from slayerProgressDelta immediately
			// above -- this is an ABSOLUTE task-state number (the game's
			// own currentRemaining as of this one event), so it must be
			// OVERWRITTEN with the latest value, never summed/accumulated.
			// An update with no slayerCurrentRemaining (this branch simply
			// not entered) leaves whatever was already recorded untouched
			// -- it is never reset to null just because a later event
			// happened not to carry one.
			aggregates.setLatestSlayerCurrentRemaining(update.getSlayerCurrentRemaining());
			SessionAggregates.SlayerAssignmentRecord current = currentSlayerAssignment(aggregates);
			if (current != null)
			{
				current.setLatestRemaining(update.getSlayerCurrentRemaining());
				// COMPLETED: remaining reached 0, via SLAYER_TASK_COMPLETED's
				// reconciliation metric or a final PROGRESS to 0 (RuneLite can
				// report amount 0 before the task name clears); both carry the
				// event time as reference time. The record stays current
				// (AWAITING_TASK) until a genuinely new assignment is installed.
				if (update.getSlayerCurrentRemaining() == 0 && current.getEndReason() == null)
				{
					current.setEndReason(SlayerAssignmentEndReason.COMPLETED);
					current.setCompletedAt(update.getReferenceTime() == null ? null : update.getReferenceTime().toString());
				}
			}
		}
	}

	/**
	 * Which assignment record an XP metric belongs to, by its own
	 * reference time t (XP window start / event time):
	 * the newest record that had started by t (a bootstrapped record has
	 * no known start and accepts anything up to its own end); then only
	 * while that record was still unfinished at t -- XP from a window that
	 * began at/after completion (travel, teleports) or after a replacement
	 * boundary is never credited to the ended record. t unknown: only the
	 * current, still-unfinished record. Null = credit no record.
	 */
	static SessionAggregates.SlayerAssignmentRecord xpRecordFor(SessionAggregates aggregates, java.time.Instant t)
	{
		List<SessionAggregates.SlayerAssignmentRecord> ledger = aggregates.getSlayerAssignments();
		if (ledger == null || ledger.isEmpty())
		{
			return null;
		}
		if (t == null)
		{
			SessionAggregates.SlayerAssignmentRecord newest = ledger.get(ledger.size() - 1);
			return newest.getEndReason() == null ? newest : null;
		}
		for (int i = ledger.size() - 1; i >= 0; i--)
		{
			SessionAggregates.SlayerAssignmentRecord r = ledger.get(i);
			java.time.Instant start = parse(r.getAssignedAt());
			if (start != null && t.isBefore(start))
			{
				continue;
			}
			java.time.Instant end = r.getEndReason() == SlayerAssignmentEndReason.COMPLETED
				? parse(r.getCompletedAt())
				: parse(r.getEndedAt());
			if (r.getEndReason() == SlayerAssignmentEndReason.COMPLETED && end == null)
			{
				return null;
			}
			return end == null || t.isBefore(end) ? r : null;
		}
		return null;
	}

	private static java.time.Instant parse(String iso)
	{
		return iso == null ? null : java.time.Instant.parse(iso);
	}

	/** The session's current (latest) Slayer assignment instance, or null when it has no ledger. */
	static SessionAggregates.SlayerAssignmentRecord currentSlayerAssignment(SessionAggregates aggregates)
	{
		List<SessionAggregates.SlayerAssignmentRecord> ledger = aggregates.getSlayerAssignments();
		return ledger == null || ledger.isEmpty() ? null : ledger.get(ledger.size() - 1);
	}

	/**
	 * Ledger bootstrap. When `assignment` is a SLAYER identity and the
	 * session has no ledger yet (created/established mid-task, refined into
	 * Slayer, or a pre-ledger session file), creates record #1 seeded with
	 * ALL loot the session already owns, so the ledger partitions the
	 * complete session loot from the start. No-op when a ledger exists
	 * (never a duplicate record) or for a non-Slayer identity.
	 *
	 * `sessionActiveDurationMillis` (the session's accumulated active time)
	 * becomes the record's task-time start. Also upgrades a record written
	 * before XP/time tracking existed: the CURRENT unfinished record starts
	 * tracking from now. Bootstrapped units = every unit this session
	 * already observed (exact: a pre-ledger session never spanned an
	 * assignment change); bootstrapped XP/time start at 0 (conservative --
	 * Spyglass cannot know which earlier session XP was this task's).
	 *
	 * @return true when record #1 was created by this call
	 */
	static boolean ensureSlayerAssignmentLedger(SessionAggregates aggregates, ActivityIdentity assignment, long sessionActiveDurationMillis)
	{
		if (aggregates == null || assignment == null || assignment.getActivityType() != ActivityType.SLAYER)
		{
			return false;
		}
		if (aggregates.getSlayerAssignments() != null && !aggregates.getSlayerAssignments().isEmpty())
		{
			SessionAggregates.SlayerAssignmentRecord current = currentSlayerAssignment(aggregates);
			if (current.getXpGainedBySkill() == null && current.getEndReason() == null)
			{
				current.setXpGainedBySkill(new java.util.LinkedHashMap<>());
				current.setActiveDurationStartMillis(sessionActiveDurationMillis);
			}
			return false;
		}
		SessionAggregates.SlayerAssignmentRecord first = newAssignment(1, assignment);
		first.setBootstrapped(true);
		first.setLatestRemaining(aggregates.getLatestSlayerCurrentRemaining());
		first.setUnitsCompleted(aggregates.getSlayerProgressDelta() == null ? 0 : aggregates.getSlayerProgressDelta());
		first.setActiveDurationStartMillis(sessionActiveDurationMillis);
		if (aggregates.getLootDrops() != null)
		{
			for (SessionAggregates.LootDropGroup group : aggregates.getLootDrops())
			{
				if (group == null || group.getItems() == null)
				{
					continue;
				}
				for (SessionAggregates.LootItemAggregate item : group.getItems())
				{
					if (item != null)
					{
						mergeItem(first.getItems(), item.getItemId(), item.getItemName(), item.getQuantity());
					}
				}
			}
		}
		first.setXpGainedBySkill(new java.util.LinkedHashMap<>());
		if (first.getUnitsCompleted() == 0)
		{
			// Units seeded from an older file were counted before bracelet
			// tracking existed: those records never claim a kill count.
			startBraceletTracking(first);
		}
		List<SessionAggregates.SlayerAssignmentRecord> ledger = new ArrayList<>();
		ledger.add(first);
		aggregates.setSlayerAssignments(ledger);
		return true;
	}

	/**
	 * Installs a NEW assignment instance (authoritative ASSIGNED on a
	 * retained Slayer session); the caller bootstraps the ledger first. The
	 * previous record is closed (endedAt; its task time ends at
	 * `sessionActiveDurationMillis`, where the new one's starts), never
	 * merged or cleared; the new one starts with no loot. The previous
	 * record gets REPLACED_EARLY only when it had not already COMPLETED and
	 * its real remaining is known and &gt; 0 -- unknown remaining leaves the
	 * end reason null (never a guessed skip). Its remaining, units and loot
	 * are never altered.
	 */
	static SessionAggregates.SlayerAssignmentRecord beginSlayerAssignment(SessionAggregates aggregates, ActivityIdentity assignment, java.time.Instant observedAt, Integer amount, long sessionActiveDurationMillis)
	{
		List<SessionAggregates.SlayerAssignmentRecord> ledger = aggregates.getSlayerAssignments();
		if (ledger == null)
		{
			ledger = new ArrayList<>();
			aggregates.setSlayerAssignments(ledger);
		}
		int ordinal = 1;
		if (!ledger.isEmpty())
		{
			SessionAggregates.SlayerAssignmentRecord previous = ledger.get(ledger.size() - 1);
			if (previous.getEndedAt() == null)
			{
				previous.setEndedAt(observedAt.toString());
			}
			if (previous.getEndReason() == null && previous.getLatestRemaining() != null && previous.getLatestRemaining() > 0)
			{
				previous.setEndReason(SlayerAssignmentEndReason.REPLACED_EARLY);
			}
			if (previous.getActiveDurationEndMillis() == null)
			{
				previous.setActiveDurationEndMillis(sessionActiveDurationMillis);
			}
			ordinal = previous.getOrdinal() + 1;
		}
		SessionAggregates.SlayerAssignmentRecord next = newAssignment(ordinal, assignment);
		next.setAssignedAt(observedAt.toString());
		next.setInitialAmount(amount);
		next.setLatestRemaining(amount);
		next.setUnitsCompleted(0);
		next.setXpGainedBySkill(new java.util.LinkedHashMap<>());
		next.setActiveDurationStartMillis(sessionActiveDurationMillis);
		startBraceletTracking(next);
		ledger.add(next);
		return next;
	}

	/** Bracelet procs (and therefore observed kills) are counted from this record's start. */
	private static void startBraceletTracking(SessionAggregates.SlayerAssignmentRecord record)
	{
		record.setSlaughterProcs(0);
		record.setExpeditiousProcs(0);
	}

	private static SessionAggregates.SlayerAssignmentRecord newAssignment(int ordinal, ActivityIdentity assignment)
	{
		SessionAggregates.SlayerAssignmentRecord a = new SessionAggregates.SlayerAssignmentRecord();
		a.setOrdinal(ordinal);
		a.setTaskName(assignment.getDisplayName());
		a.setAssignmentKey(assignment.getActivityKey());
		return a;
	}

	/** Same item-identity rule Current Session uses to aggregate loot: item ID when known, else name. */
	private static void mergeItem(List<SessionAggregates.LootItemAggregate> items, Integer itemId, String itemName, long quantity)
	{
		for (SessionAggregates.LootItemAggregate existing : items)
		{
			boolean same = itemId != null
				? itemId.equals(existing.getItemId())
				: existing.getItemId() == null && Objects.equals(itemName, existing.getItemName());
			if (same)
			{
				existing.setQuantity(existing.getQuantity() + quantity);
				return;
			}
		}
		SessionAggregates.LootItemAggregate item = new SessionAggregates.LootItemAggregate();
		item.setItemId(itemId);
		item.setItemName(itemName);
		item.setQuantity(quantity);
		items.add(item);
	}

	/**
	 * Keeps `authoritativeCurrentValue` (the raw account-wide
	 * number a game message reported) strictly separate from
	 * `sessionOccurrences` (how many of those are attributable to THIS
	 * session).
	 *
	 * First qualifying observation for this exact source+kind within
	 * this session (no ReliableCount yet, or the session's activity was
	 * refined/switched to a different source): there is no in-session
	 * baseline to diff against, so the HONEST rule is that the
	 * authoritative signal that just arrived represents the
	 * kill/completion that just happened -- it is counted as exactly 1
	 * session occurrence, regardless of how large the account-wide
	 * absolute value is.
	 *
	 * Subsequent observation for the SAME source+kind: the session
	 * delta is `newAuthoritativeValue - previousAuthoritativeValue`.
	 * If the producer's real observed jump is larger than 1 (e.g. a
	 * missed chat message caused two prior kills to go unobserved),
	 * that real delta is preserved rather than assumed to be 1. A
	 * non-advancing or duplicate observation (delta <= 0) contributes
	 * zero -- it must never subtract from what was already credited.
	 */
	/** One completion; a different activity key (never expected within one session) starts over. */
	private static void applyActivityCompletion(SessionAggregates aggregates, MetricUpdate update)
	{
		SessionAggregates.ActivityCompletionCount count = aggregates.getActivityCompletions();
		if (count == null || !update.getActivityCompletionKey().equals(count.getActivityKey()))
		{
			count = new SessionAggregates.ActivityCompletionCount();
			count.setActivityKey(update.getActivityCompletionKey());
			aggregates.setActivityCompletions(count);
		}
		count.setSessionCompletions(count.getSessionCompletions() + 1);
		if (update.getActivityCompletionAuthoritativeValue() != null)
		{
			count.setLatestAuthoritativeValue(update.getActivityCompletionAuthoritativeValue());
		}
	}

	/**
	 * Currency: only positive gains accrue (a spend never produces an
	 * update, and a non-positive amount is ignored), so the total never goes
	 * backwards. Score: a completion count already scored is a duplicate and
	 * changes nothing; only a TRUSTED score (game observed from its start,
	 * final value known and positive) enters Avg/Best.
	 */
	private static void applyActivityStats(SessionAggregates aggregates, MetricUpdate update)
	{
		SessionAggregates.ActivitySessionStats stats = aggregates.getActivityStats();
		if (stats == null || !update.getActivityStatsKey().equals(stats.getActivityKey()))
		{
			stats = new SessionAggregates.ActivitySessionStats();
			stats.setActivityKey(update.getActivityStatsKey());
			aggregates.setActivityStats(stats);
		}
		if (update.getCurrencyGained() != null && update.getCurrencyGained() > 0)
		{
			stats.setCurrencyGained(stats.getCurrencyGained() + update.getCurrencyGained());
			if (update.getCurrencyKey() != null)
			{
				if (stats.getCurrencyGainedByKey() == null)
				{
					stats.setCurrencyGainedByKey(new java.util.LinkedHashMap<>());
				}
				stats.getCurrencyGainedByKey().merge(update.getCurrencyKey(), update.getCurrencyGained(), Long::sum);
			}
		}
		if (update.getProducedItems() != null)
		{
			applyProducedItems(aggregates, update.getProducedItems());
		}
		if (!update.isScoreUpdate())
		{
			return;
		}
		Integer count = update.getScoreCompletionCount();
		Integer last = stats.getLastScoredCompletionCount();
		if (count != null && last != null && count <= last)
		{
			return;
		}
		if (count != null)
		{
			stats.setLastScoredCompletionCount(count);
		}
		Integer score = update.getScore();
		if (update.isScoreTrusted() && score != null && score > 0)
		{
			stats.setScoredCompletions(stats.getScoredCompletions() + 1);
			stats.setScoreTotal(stats.getScoreTotal() + score);
			stats.setBestScore(stats.getBestScore() == null ? score : Math.max(stats.getBestScore(), score));
		}
	}

	/** Cumulative per item (id when known, else name); non-positive quantities ignored. Never subtracts. */
	private static void applyProducedItems(SessionAggregates aggregates, List<SessionSignal.LootDrop> items)
	{
		for (SessionSignal.LootDrop item : items)
		{
			if (item == null || item.getQuantity() <= 0)
			{
				continue;
			}
			if (aggregates.getProducedItems() == null)
			{
				aggregates.setProducedItems(new ArrayList<>());
			}
			SessionAggregates.ProducedItemAggregate existing = null;
			for (SessionAggregates.ProducedItemAggregate p : aggregates.getProducedItems())
			{
				if (item.getItemId() != null ? item.getItemId().equals(p.getItemId())
					: p.getItemId() == null && Objects.equals(item.getItemName(), p.getItemName()))
				{
					existing = p;
					break;
				}
			}
			if (existing == null)
			{
				existing = new SessionAggregates.ProducedItemAggregate();
				existing.setItemId(item.getItemId());
				existing.setItemName(item.getItemName());
				aggregates.getProducedItems().add(existing);
			}
			if (existing.getItemName() == null && item.getItemName() != null)
			{
				existing.setItemName(item.getItemName());
			}
			existing.setQuantity(existing.getQuantity() + item.getQuantity());
		}
	}

	private static void applyReliableCount(SessionAggregates aggregates, MetricUpdate update)
	{
		SessionAggregates.ReliableCount existing = aggregates.getReliableCount();
		int authoritativeValue = update.getReliableCountAuthoritativeValue();

		boolean isNewSource = existing == null
			|| existing.getKind() != update.getReliableCountKind()
			|| !Objects.equals(existing.getSourceKey(), update.getReliableCountSourceKey());

		if (isNewSource)
		{
			SessionAggregates.ReliableCount fresh = new SessionAggregates.ReliableCount();
			fresh.setKind(update.getReliableCountKind());
			fresh.setSourceKey(update.getReliableCountSourceKey());
			fresh.setAuthoritativeCurrentValue(authoritativeValue);
			fresh.setSessionOccurrences(1);
			aggregates.setReliableCount(fresh);
			return;
		}

		int previousValue = existing.getAuthoritativeCurrentValue() == null ? authoritativeValue : existing.getAuthoritativeCurrentValue();
		int delta = authoritativeValue - previousValue;
		if (delta > 0)
		{
			existing.setSessionOccurrences(existing.getSessionOccurrences() + delta);
		}
		existing.setAuthoritativeCurrentValue(authoritativeValue);
	}
}

package com.osrstelemetry.plugin.session;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * Typed containers for future aggregate metrics. Still NOT wired to
 * any live scheduler or RuneLite events -- SessionAggregateUpdater
 * (pure, unit-tested) is what knows how to fold a MetricUpdate into
 * these fields, but nothing calls it from a real event yet.
 *
 * CORRECTION: `reliableCount` was previously a bare `Integer`,
 * which silently conflated two DIFFERENT numbers -- (A) the
 * authoritative account-wide value a game message reports (e.g. "Your
 * Zulrah kill count is: 812") and (B) how many of those kills/
 * completions actually happened DURING this session. Displaying (A)
 * labeled as "Kills" for a session would be wrong the moment a player
 * had killed a boss they already had hundreds of prior kills on.
 * `reliableCount` is now a `ReliableCount` object that keeps both
 * numbers distinct -- see its own javadoc for exactly how
 * `sessionOccurrences` is derived (SessionAggregateUpdater).
 */
@Data
public class SessionAggregates
{
	/** Skill name -> XP delta accumulated while this session was ACTIVE. Empty, never populated outside tests. */
	private Map<String, Long> xpGainedBySkill = new HashMap<>();

	/** One entry per atomic SERVER_NPC_LOOT notification observed while this session was ACTIVE. Empty, never populated outside tests. */
	private List<LootDropGroup> lootDrops = new ArrayList<>();

	/**
	 * The one "Reliable Count" metric for this session's activity, per
	 * the Kills/Completions/Task progress/no row policy -- null (no row)
	 * until a qualifying authoritative signal
	 * (currently only BOSS_KILL) has been observed for this session.
	 * See ReliableCount's own javadoc for the authoritative-value vs.
	 * session-occurrences distinction.
	 */
	private ReliableCount reliableCount;

	/**
	 * The total number of Slayer TASK UNITS consumed while this
	 * session was ACTIVE -- the SUM of each SLAYER_TASK_PROGRESS
	 * event's own taskUnitsConsumed, which is the observed decrease in
	 * the assignment's authoritative remaining-count value for that one
	 * event -- see EventPayloads.SlayerTaskProgress and
	 * SessionAggregateUpdater.apply(). This is NOT a physical NPC-kill
	 * count and must never be labeled "kills" anywhere player-facing:
	 * game mechanics (e.g. an expeditious-bracelet-style proc, or a
	 * bracelet-of-slaughter-style save) can make one physical kill
	 * consume more than one task unit, or zero, independent of any
	 * missed-observation reconciliation. This is NEVER an absolute
	 * task-state number either -- never currentRemaining,
	 * previousRemaining, or initialAmount from any single event. The
	 * field name is kept as-is (no persisted-document migration
	 * needed; see {@link #getSlayerTaskUnitsConsumed()} for an
	 * additive, honestly-named accessor) but the VALUE it stores has
	 * been corrected: it previously (incorrectly) held the most
	 * recently observed absolute amountRemaining, which made it
	 * collapse to whatever the latest event's remaining count happened
	 * to be instead of reflecting how much progress actually occurred
	 * during the session.
	 *
	 * Still retained: useful for session/
	 * history analytics even though the player-facing panel's PRIMARY
	 * live number is now latestSlayerCurrentRemaining below, not this
	 * field -- see CurrentSessionView's own javadoc.
	 */
	private Integer slayerProgressDelta;

	/**
	 * Honestly-named alias for {@link #getSlayerProgressDelta()} --
	 * same value, same TASK-UNIT semantics (never a physical NPC-kill
	 * count). The persisted field/Lombok accessor is kept as
	 * `slayerProgressDelta` to avoid a persisted-document migration;
	 * new call sites that want a self-documenting name should prefer
	 * this method over the raw getter.
	 */
	public Integer getSlayerTaskUnitsConsumed()
	{
		return slayerProgressDelta;
	}

	/**
	 * The LATEST observed authoritative currentRemaining from
	 * the most recent SLAYER_TASK_PROGRESS event this session has seen
	 * -- an ABSOLUTE task-state number, deliberately the opposite of
	 * slayerProgressDelta above: this is never summed/accumulated, only
	 * ever OVERWRITTEN by SessionAggregateUpdater.apply() with each new
	 * event's own value (when that event actually carries one -- an
	 * event with no currentRemaining leaves this field exactly as it
	 * was, it never resets to null). null until the first
	 * SLAYER_TASK_PROGRESS event carrying a currentRemaining has been
	 * observed this session; the UI must never invent a number when
	 * this is null (see CurrentSessionSnapshot/CurrentSessionView).
	 */
	private Integer latestSlayerCurrentRemaining;

	/**
	 * SMART SLAYER. One Slayer session can span several assignments;
	 * slayerProgressDelta and Slayer XP stay SESSION-wide totals. These
	 * record both values when the CURRENT assignment was installed, so the
	 * "~XP remaining" estimate uses this assignment's own units/XP only
	 * (never blended across monsters). Both null = only one assignment so
	 * far (including every older session file) -- the session totals are
	 * then the assignment's own. Additive/nullable: old JSON loads unchanged.
	 */
	private Integer slayerAssignmentBaselineProgressDelta;
	private Long slayerAssignmentBaselineSlayerXp;

	/**
	 * SMART SLAYER ASSIGNMENT LEDGER, oldest -&gt; newest; the LAST record is
	 * the current assignment. Its loot items are a PARTITION of this
	 * session's canonical {@link #lootDrops}, never an independent store:
	 * every drop the session is credited with is also added to the last
	 * record, so the records' items sum to the session-wide loot.
	 *
	 * Null/empty for non-Slayer sessions and every session file written
	 * before this field existed. A Slayer session without one is
	 * bootstrapped (SessionAggregateUpdater.ensureSlayerAssignmentLedger())
	 * with one record seeded from ALL its existing loot -- exact, since
	 * released sessions never spanned a task rollover. Item IDs/names/
	 * quantities only; GP is priced at render time.
	 */
	private List<SlayerAssignmentRecord> slayerAssignments;

	/**
	 * STRUCTURED ACTIVITY: generic completion metric (games, chests, ...)
	 * for a STRUCTURED_ACTIVITY session. Additive and nullable -- absent on
	 * every other session and in every pre-existing JSON file. The label
	 * ("Games") is not persisted; it comes from the activity registry.
	 */
	private ActivityCompletionCount activityCompletions;

	/**
	 * STRUCTURED ACTIVITY: session-summary stats an activity's own native
	 * state supports (Tempoross: reward permits earned, final points of
	 * fully observed games). Additive and nullable -- absent on every other
	 * session and in every pre-existing JSON file. No transient game state
	 * (energy / essence / storm / live points) is ever stored here.
	 */
	private ActivitySessionStats activityStats;

	/**
	 * Items this session's activity PRODUCED (confirmed production only --
	 * e.g. GotR runes crafted at its altars), cumulative per item, first-
	 * produced order. Never loot; never reduced by dropping or spending.
	 * Additive/nullable: older sessions load with null.
	 */
	private List<ProducedItemAggregate> producedItems;

	/**
	 * One Slayer assignment INSTANCE within a session: its boundaries and
	 * end reason, task-unit count, and the slices of the session's loot,
	 * XP and active time it owns. {@code ordinal} is a 1-based sequence
	 * unique within the session (never reused, never derived from the task
	 * name) -- two consecutive assignments of the same task are two
	 * instances. Fields from endReason on are additive/nullable: older
	 * records load with them null and are treated conservatively.
	 */
	@Data
	public static class SlayerAssignmentRecord
	{
		private int ordinal;
		/** Player-facing task name (the assignment identity's display name). */
		private String taskName;
		/** The assignment's ActivityIdentity key (task@location, normalized). */
		private String assignmentKey;
		/** ISO-8601; when the authoritative ASSIGNED was observed. Null when bootstrapped mid-task. */
		private String assignedAt;
		/** Authoritative assigned amount when observed via ASSIGNED; null when bootstrapped mid-task. */
		private Integer initialAmount;
		/**
		 * The game's own original size of this assignment (varp
		 * SLAYER_COUNT_ORIGINAL adjusted by any quantity modifier, read
		 * natively) -- ASSIGNMENT METADATA ONLY. Recorded for a bootstrapped
		 * record, where Spyglass joined mid-task and initialAmount stays
		 * null. Knowing the task was originally 180 does not mean Spyglass
		 * observed the first 107 units: this is never used to derive
		 * unitsCompleted, XP, active duration or any other session-owned
		 * metric, never changes bootstrapped provenance, and never replaces
		 * initialAmount (whose meaning, "amount when the ASSIGNED was
		 * observed", is unchanged). Null when unknown and on older records.
		 */
		private Integer assignedInitialAmount;
		/** Latest authoritative remaining for this assignment (0 = completed). */
		private Integer latestRemaining;
		/** ISO-8601; when a newer assignment superseded this one (completion or replacement). Null while current. */
		private String endedAt;
		/** True when created from existing session state rather than an observed ASSIGNED (mid-task start / legacy file). */
		private boolean bootstrapped;
		private List<LootItemAggregate> items = new ArrayList<>();

		/**
		 * How this assignment ended; null while current/in progress, and
		 * for any assignment whose end Spyglass did not authoritatively
		 * observe (session ended mid-task, legacy record). COMPLETED: the
		 * authoritative completion path set remaining to 0. REPLACED_EARLY:
		 * a genuinely new authoritative assignment replaced it while it
		 * still had remaining &gt; 0 (shown to players as "Skipped").
		 */
		private SlayerAssignmentEndReason endReason;
		/** ISO-8601; when the authoritative completion was observed. Null unless COMPLETED. */
		private String completedAt;
		/**
		 * Authoritative Slayer task units Spyglass observed being consumed
		 * while this was the session's current assignment (every
		 * SLAYER_TASK_PROGRESS unit, plus the completion reconciliation of a
		 * final unit RuneLite reports no trailing progress for). For a
		 * fully observed assignment this equals initialAmount - remaining;
		 * for one bootstrapped mid-task it counts only from Spyglass's own
		 * observation onward -- never pre-observation progress. Null only on
		 * legacy records.
		 */
		private Integer unitsCompleted;
		/**
		 * XP (per skill, same keys as SessionAggregates#xpGainedBySkill)
		 * this session gained while this was the current, unfinished
		 * assignment -- a non-destructive slice of the canonical session
		 * XP, credited by each XP metric's own reference time (so a final
		 * kill's XP whose window began before completion still counts, and
		 * XP after completion/replacement never does). Null = not tracked
		 * (legacy record; installed conservatively from 0 on load).
		 */
		private Map<String, Long> xpGainedBySkill;
		/** Session accumulatedActiveDurationMillis when this assignment's XP/time tracking began. */
		private Long activeDurationStartMillis;
		/** Session accumulatedActiveDurationMillis when it ended (completion or replacement); null while current and unfinished. */
		private Long activeDurationEndMillis;

		/**
		 * The Slayer master varbit value this assignment came from (1 Turael/Aya
		 * ... 10 Mortimer), from the authoritative ASSIGNED, or -- for a record
		 * Spyglass joined mid-task -- the first observed progress of the same
		 * assignment. Null when unknown and on older records.
		 */
		private Integer masterId;
		/**
		 * Native Bracelet of slaughter / Expeditious bracelet activations
		 * (the game's own chat confirmation) seen while this was the current
		 * assignment. Null on older records = not tracked (never shown as 0).
		 */
		private Integer slaughterProcs;
		private Integer expeditiousProcs;

		/**
		 * Kills Spyglass observed for this assignment: task units it saw
		 * consumed, minus extra units an Expeditious bracelet consumed, plus
		 * kills a Bracelet of slaughter kept from consuming a unit. Never
		 * {@code initial - remaining}; subordinate NPCs that consume no unit
		 * never count. Null when units are unknown (legacy) or when bracelet
		 * tracking did not exist for this record (pre-tracking file: the
		 * unit count alone cannot be called kills). Derived, not persisted.
		 */
		public Integer observedKills()
		{
			if (unitsCompleted == null || slaughterProcs == null || expeditiousProcs == null)
			{
				return null;
			}
			return Math.max(0, unitsCompleted - expeditiousProcs + slaughterProcs);
		}

		/**
		 * The player-facing "xN": this record's own observed unit count; for a
		 * legacy record without one, initialAmount - remaining when both are
		 * authoritatively known (a fully observed assignment); otherwise null
		 * (unknown -- no count is shown rather than a guess). Never negative.
		 * Derived, not persisted (Gson serializes fields only).
		 */
		public Integer observedUnitsCompleted()
		{
			if (unitsCompleted != null)
			{
				return Math.max(0, unitsCompleted);
			}
			if (!bootstrapped && initialAmount != null && latestRemaining != null)
			{
				return Math.max(0, initialAmount - latestRemaining);
			}
			return null;
		}
	}

	@Data
	public static class ActivityCompletionCount
	{
		/** Structured activity key the count belongs to. */
		private String activityKey;
		/** Completions observed during this session (never fabricated). */
		private int sessionCompletions;
		/** The game's own latest running count, when the source carries one. */
		private Integer latestAuthoritativeValue;
	}

	@Data
	public static class ActivitySessionStats
	{
		/** Structured activity key the stats belong to. */
		private String activityKey;
		/** Native reward currency gained this session (sum of positive changes; spending never subtracts). */
		private long currencyGained;
		/**
		 * Per-currency breakdown of currencyGained (e.g. GotR "elemental_points"
		 * / "catalytic_points"), in first-earned order. Additive/nullable:
		 * older sessions load with null and fall back to currencyGained.
		 */
		private java.util.Map<String, Long> currencyGainedByKey;
		/** Completed games whose final score was trustworthy (observed from start); the Avg/Best population. */
		private int scoredCompletions;
		/** Sum of those games' final scores. */
		private long scoreTotal;
		/** Highest of those games' final scores, or null when none. */
		private Integer bestScore;
		/** The game's running count of the last scored completion (duplicate-evidence guard), or null. */
		private Integer lastScoredCompletionCount;

		/** Arithmetic mean over scoredCompletions, or null when there are none. */
		public Long averageScore()
		{
			return scoredCompletions <= 0 ? null : Math.round(scoreTotal / (double) scoredCompletions);
		}
	}

	/**
	 * One item an activity PRODUCED this session (e.g. GotR runes crafted)
	 * and its cumulative exact quantity. Output -- deliberately separate from
	 * loot (LootDropGroup / LootItemAggregate), which is what was received.
	 */
	@Data
	public static class ProducedItemAggregate
	{
		private Integer itemId;
		private String itemName;
		private long quantity;
	}

	@Data
	public static class LootDropGroup
	{
		private String sourceName;
		/** ISO-8601 String, matching this project's timestamp convention (see Session's own javadoc). */
		private String observedAt;
		private List<LootItemAggregate> items = new ArrayList<>();
	}

	@Data
	public static class LootItemAggregate
	{
		private Integer itemId;
		private String itemName;
		private long quantity;
	}

	/**
	 * Which kind of
	 * authoritative count this is. COMPLETIONS is defined now for
	 * RAID_COMPLETION/ACTIVITY_COMPLETION's own authoritative
	 * completion-count messages, even
	 * though nothing populates it yet -- those signals are not
	 * yet linked to any modeled ActivityIdentity/session (raids have no
	 * ActivityType of their own), so attaching a session-occurrences
	 * count to "whatever combat session happens to be active" would be
	 * a fabricated linkage. That linkage is deferred until raid/
	 * activity identity is actually modeled.
	 */
	public enum ReliableCountKind
	{
		KILLS,
		COMPLETIONS
	}

	/**
	 * Keeps the
	 * authoritative, account-wide absolute value a game message reports
	 * (`authoritativeCurrentValue`) strictly separate from how many of
	 * those kills/completions this SPECIFIC session can claim
	 * (`sessionOccurrences`). `sourceKey` records which activity's
	 * identity key this count applies to (e.g. a boss's activityKey),
	 * so SessionAggregateUpdater can tell a genuinely new source (reset
	 * the session-occurrences baseline) apart from the same source
	 * advancing further (compute a real delta) -- see that class for
	 * the exact algorithm, including how the very first occurrence in a
	 * session is honestly counted and how an observed jump greater than
	 * 1 is preserved rather than assumed to be exactly 1.
	 */
	@Data
	public static class ReliableCount
	{
		private ReliableCountKind kind;
		private String sourceKey;
		private Integer authoritativeCurrentValue;
		private int sessionOccurrences;
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

/**
 * The
 * ONLY class in this package that imports com.osrstelemetry.plugin.events
 * -- everything else in this package (SignalKind's own javadoc says so
 * explicitly) is deliberately decoupled from EventType. This is that
 * decoupling's one required seam: a pure, static, Client-independent
 * translation from an already-normalized telemetry fact (EventType +
 * payload + the wall-clock instant it was durably recorded) to the
 * classifier's own SessionSignal vocabulary, or null when an EventType
 * carries no session-lifecycle meaning at all.
 *
 * Deliberately does NOT attach a gameTick -- that requires
 * `client.getTickCount()`, a Client-only read, and this class must
 * stay exactly as Client-free as every other pure class in this
 * package; tick context is attached at the safe ClientThread ingestion
 * point instead. SessionRuntimeCoordinator
 * calls this, then calls withGameTick(...) itself when it is safely on
 * the client thread.
 *
 * NO DUPLICATED TRUTH LOGIC: every field
 * read here is copied verbatim from the payload a collector already
 * produced -- nothing is independently re-derived from any RuneLite
 * API, and no EventType is reclassified into a stronger claim than its
 * own collector already made (NPC_DEATH remains NPC_DEATH-shaped,
 * never a kill; SLAYER_TASK_PROGRESS remains task-unit metadata, never
 * a kill count; NPC_LOOT_ATTRIBUTED remains non-authoritative and is
 * mapped only so the classifier can explicitly ignore it, exactly as
 * ActivitySignalClassifier.classify() already does for that kind).
 */
final class SessionEventMapper
{
	private SessionEventMapper()
	{
	}

	static SessionSignal map(EventType type, Object payload, Instant observedAt)
	{
		switch (type)
		{
			case XP_CHANGE:
			{
				// p.getWindowStart() is threaded through as
				// this signal's own xpWindowStart, so classifyXpChange()
				// can tell "when this XP was actually earned" apart from
				// `observedAt` (this event's own flush/processing time).
				// Parsed defensively: a malformed/absent windowStart
				// (older/synthetic payloads) yields null, which is
				// completely equivalent to leaving it absent (see
				// SessionSignal's own xpWindowStart javadoc) -- never an
				// exception that could drop this durable XP event
				// entirely.
				//
				// p.getNewXp() -- this window's own
				// absolute new XP value, always present (a primitive int
				// on this payload, never absent/malformed) -- is also
				// threaded through as this signal's own xpNewValue, so a
				// window that SPANS a session switch can be split exactly
				// (see SessionSignal's own xpNewValue javadoc and
				// classifyXpChange()'s boundary-ownership rule).
				EventPayloads.XpChange p = (EventPayloads.XpChange) payload;
				Instant windowStart = parseInstantSafely(p.getWindowStart());
				return SessionSignal.xpChange(observedAt, p.getSkill(), p.getDelta(), windowStart, (long) p.getNewXp());
			}
			case QUEST_COMPLETED:
			{
				EventPayloads.QuestCompleted p = (EventPayloads.QuestCompleted) payload;
				return SessionSignal.questCompleted(observedAt, p.getQuestName());
			}
			case COMBAT_ACHIEVEMENT_COMPLETED:
			{
				EventPayloads.CombatAchievementCompleted p = (EventPayloads.CombatAchievementCompleted) payload;
				return SessionSignal.combatAchievementCompleted(observedAt, p.getTaskName());
			}
			case COLLECTION_LOG_NEW_ITEM:
			{
				EventPayloads.CollectionLogNewItem p = (EventPayloads.CollectionLogNewItem) payload;
				return SessionSignal.collectionLogNewItem(observedAt, p.getItemName());
			}
			case NPC_LOOT_ATTRIBUTED:
				// Mapped (not null) so the classifier's own, already-correct
				// ignore() branch for NPC_LOOT_ATTRIBUTED is what decides
				// this is session-irrelevant -- not a second, silent
				// decision made here. No fields are needed: the classifier
				// never reads any of them for this kind.
				return SessionSignal.npcLootAttributed(observedAt);
			case NPC_DEATH:
				// Same reasoning as NPC_LOOT_ATTRIBUTED -- mapped so the
				// classifier's own ignore() branch is the single place this
				// is decided. MUST NOT become a kill/session-start signal
				// (DO NOT DO list).
				return SessionSignal.npcDeath(observedAt);
			case BOSS_KILL:
			{
				EventPayloads.BossKill p = (EventPayloads.BossKill) payload;
				return SessionSignal.bossKill(observedAt, p.getDisplayName(), p.getKillCount());
			}
			case BOSS_ACTIVITY_CONTEXT:
			{
				// Mapped verbatim, same discipline as BOSS_KILL below --
				// nothing re-derived, nothing upgraded to a stronger claim.
				// The classifier's own classifyBossActivityContext() is the
				// single place this signal's non-authoritative, never-
				// reliableCount treatment is decided.
				EventPayloads.BossActivityContext p = (EventPayloads.BossActivityContext) payload;
				return SessionSignal.bossActivityContext(observedAt, p.getBossName());
			}
			case RAID_COMPLETION:
			{
				EventPayloads.RaidCompletion p = (EventPayloads.RaidCompletion) payload;
				return SessionSignal.raidCompletion(observedAt, p.getDisplayName());
			}
			case ACTIVITY_COMPLETION:
			{
				EventPayloads.ActivityCompletion p = (EventPayloads.ActivityCompletion) payload;
				return SessionSignal.activityCompletion(observedAt, p.getDisplayName(), p.getCompletionCount());
			}
			case SLAYER_TASK_ASSIGNED:
			{
				EventPayloads.SlayerTaskAssigned p = (EventPayloads.SlayerTaskAssigned) payload;
				return SessionSignal.slayerTaskAssigned(observedAt, p.getMonster(), p.getLocation(), p.getAmount(), p.getMasterId() > 0 ? p.getMasterId() : null);
			}
			case SLAYER_TASK_PROGRESS:
			{
				// Live evidence: session_state.json's
				// slayerProgressDelta was observed holding an ABSOLUTE
				// remaining count, e.g. 118, instead of the accumulated
				// number of task units actually consumed across the
				// session. Root cause was here: this previously passed
				// p.getCurrentRemaining() -- raw, absolute Slayer task
				// state -- straight into the session signal. Must be
				// p.getTaskUnitsConsumed() instead: how many task units
				// THIS ONE observed progress event itself consumed
				// (normally 1, legitimately >1 for a missed intermediate
				// observation -- see EventPayloads.SlayerTaskProgress's
				// own javadoc), never previousRemaining/currentRemaining/
				// initialAmount or any other absolute task-state number.
				// SessionAggregateUpdater.apply() is what then accumulates
				// these per-event values across the whole session.
				//
				// p.getCurrentRemaining() is ALSO threaded
				// through, but as a SEPARATE, additive field on the
				// signal (slayerCurrentRemaining) -- never merged into or
				// substituted for taskUnitsConsumed above. This does not
				// revive the defect described above: taskUnitsConsumed is still
				// exactly what is summed into slayerProgressDelta;
				// currentRemaining is a completely separate, OVERWRITE-
				// latest-value field (see SessionAggregateUpdater.apply()'s
				// own handling of MetricUpdate.getSlayerCurrentRemaining()).
				EventPayloads.SlayerTaskProgress p = (EventPayloads.SlayerTaskProgress) payload;
				// p.getInitialAmount() (the task's native original size) rides
				// along as assignment metadata only -- 0 means "not synced yet"
				// and is passed as null, never as a real amount.
				return SessionSignal.slayerTaskProgress(
					observedAt, p.getTaskName(), p.getTaskLocation(), p.getTaskUnitsConsumed(), p.getCurrentRemaining(),
					p.getInitialAmount() > 0 ? p.getInitialAmount() : null, p.getMasterId() > 0 ? p.getMasterId() : null);
			}
			case SLAYER_BRACELET_EFFECT:
			{
				EventPayloads.SlayerBraceletEffect p = (EventPayloads.SlayerBraceletEffect) payload;
				return SessionSignal.slayerBraceletEffect(observedAt, p.getEffect());
			}
			case SLAYER_TASK_COMPLETED:
			{
				EventPayloads.SlayerTaskCompleted p = (EventPayloads.SlayerTaskCompleted) payload;
				// No location field exists on this payload (see
				// EventPayloads.SlayerTaskCompleted) -- never fabricated.
				return SessionSignal.slayerTaskCompleted(observedAt, p.getMonster(), null, Boolean.TRUE.equals(p.getCancelled()));
			}
			case SERVER_NPC_LOOT:
			{
				EventPayloads.ServerNpcLoot p = (EventPayloads.ServerNpcLoot) payload;
				List<SessionSignal.LootDrop> drops = new ArrayList<>(p.getItems().size());
				for (EventPayloads.ServerNpcLootItem item : p.getItems())
				{
					drops.add(new SessionSignal.LootDrop(item.getItemId(), item.getItemName(), item.getQuantity()));
				}
				// The whole atomic
				// notification is passed as one grouped list -- never split
				// into independent per-item signals -- so
				// SessionAggregateUpdater.apply() preserves it as one
				// LootDropGroup (source/timestamp/items together).
				return SessionSignal.serverNpcLoot(observedAt, p.getSourceName(), drops);
			}
			case NPC_INTERACTION_TARGET:
			{
				// Mapped
				// verbatim, same discipline as BOSS_ACTIVITY_CONTEXT above
				// -- nothing re-derived, nothing upgraded to a stronger
				// claim. ActivitySignalClassifier's own NPC_INTERACTION_TARGET
				// branch is the single place this signal's context-only,
				// never-lifecycle-carrying treatment is decided.
				EventPayloads.NpcInteractionTarget p = (EventPayloads.NpcInteractionTarget) payload;
				return SessionSignal.npcInteractionTarget(observedAt, p.getNpcId(), p.getNpcName());
			}
			case RAW_COMBAT_XP_OBSERVED:
			{
				// Mapped verbatim -- skillName
				// only, never an xp value (EventPayloads.RawCombatXpObserved
				// structurally has no such field). See
				// SignalKind.RAW_COMBAT_XP_OBSERVED's own javadoc.
				EventPayloads.RawCombatXpObserved p = (EventPayloads.RawCombatXpObserved) payload;
				return SessionSignal.rawCombatXpObserved(observedAt, p.getSkillName());
			}
			case STRUCTURED_ACTIVITY_STATE:
			{
				EventPayloads.StructuredActivityState p = (EventPayloads.StructuredActivityState) payload;
				return SessionSignal.structuredActivityLocation(observedAt, p.getActivityKey(), p.getRegionId());
			}
			case STRUCTURED_ACTIVITY_COMPLETION:
			{
				EventPayloads.StructuredActivityCompletion p = (EventPayloads.StructuredActivityCompletion) payload;
				return SessionSignal.structuredActivityCompletion(observedAt, p.getActivityKey(), p.getCompletionCount());
			}
			case STRUCTURED_ACTIVITY_SCORE:
			{
				EventPayloads.StructuredActivityScore p = (EventPayloads.StructuredActivityScore) payload;
				return SessionSignal.structuredActivityScore(observedAt, p.getActivityKey(), p.getCompletionCount(), p.getPoints(),
					p.isObservedFromStart());
			}
			case STRUCTURED_ACTIVITY_CURRENCY:
			{
				EventPayloads.StructuredActivityCurrency p = (EventPayloads.StructuredActivityCurrency) payload;
				return p.getGained() > 0
					? SessionSignal.structuredActivityCurrency(observedAt, p.getActivityKey(), p.getCurrency(), p.getGained())
					: null;
			}
			case STRUCTURED_ACTIVITY_PRODUCTION:
			{
				EventPayloads.StructuredActivityProduction p = (EventPayloads.StructuredActivityProduction) payload;
				if (p.getItems() == null || p.getItems().isEmpty())
				{
					return null;
				}
				List<SessionSignal.LootDrop> produced = new ArrayList<>(p.getItems().size());
				for (EventPayloads.ProducedItem item : p.getItems())
				{
					if (item != null && item.getQuantity() > 0)
					{
						produced.add(new SessionSignal.LootDrop(item.getItemId(),
							item.getItemName() == null ? "Item " + item.getItemId() : item.getItemName(), item.getQuantity()));
					}
				}
				return produced.isEmpty() ? null : SessionSignal.structuredActivityProduction(observedAt, p.getActivityKey(), produced);
			}
			case STRUCTURED_REWARD:
			{
				EventPayloads.StructuredReward p = (EventPayloads.StructuredReward) payload;
				List<SessionSignal.LootDrop> drops = new ArrayList<>(p.getItems().size());
				for (EventPayloads.StructuredRewardItem item : p.getItems())
				{
					drops.add(new SessionSignal.LootDrop(item.getItemId(), item.getItemName(), item.getQuantity()));
				}
				return SessionSignal.structuredReward(observedAt, p.getActivityKey(), canonicalRewardSourceKey(p), drops);
			}
			case BANK_SNAPSHOT:
			case SEED_VAULT_SNAPSHOT:
				// Storage snapshots carry no session lifecycle activity --
				// mapped to the explicit
				// STORAGE_SNAPSHOT kind, which the classifier already
				// ignores, rather than returning null, so the same "every
				// EventType is at least considered" discipline applies here
				// too.
				return SessionSignal.storageSnapshot(observedAt);
			case LEVEL_UP:
				// LEVEL_UP has no corresponding SignalKind (see SignalKind's
				// closed enum) -- it is a milestone annotation over the same
				// XP data XP_CHANGE already reports; mapping it would either
				// require inventing a new SignalKind (out of scope: "do not
				// redesign the already-tested session model") or silently
				// double-counting XP already captured via XP_CHANGE. Not
				// session-relevant.
				return null;
			default:
				return null;
		}
	}

	/**
	 * Defensive ISO-8601 parse for
	 * EventPayloads.XpChange#getWindowStart() -- null/blank/malformed
	 * input yields null (never an exception), matching this signal
	 * field's own "null means the ownership guard is a no-op" contract
	 * (see SessionSignal's xpWindowStart javadoc).
	 */
	/**
	 * The payload's canonical reward-source key; an older payload without one
	 * canonicalizes its sourceName through the registry's declared aliases.
	 * An unknown name passes through unchanged and is then owned by nobody.
	 */
	static String canonicalRewardSourceKey(EventPayloads.StructuredReward p)
	{
		if (p.getSourceKey() != null)
		{
			return p.getSourceKey();
		}
		com.osrstelemetry.plugin.activity.StructuredRewardSource source =
			com.osrstelemetry.plugin.activity.StructuredActivityRegistry.defaults().rewardSource(p.getSourceName());
		return source == null ? p.getSourceName() : source.getKey();
	}

	private static Instant parseInstantSafely(String value)
	{
		if (value == null || value.isEmpty())
		{
			return null;
		}
		try
		{
			return Instant.parse(value);
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import lombok.extern.slf4j.Slf4j;

/**
 * I/O
 * orchestration around SessionLifecycleEngine, built entirely on the
 * existing LocalStateStore ("do not redesign LocalStateStore
 * unless genuinely necessary"; it wasn't). Every method takes an
 * explicit accountHash and reads/writes only that account's directory
 * via TelemetryPaths, so callers get account isolation for free —
 * there is no shared/static state anywhere in this class.
 *
 * WRITE ORDERING (reusing the lesson already established by
 * Bank snapshot persistence — see LocalStateStore's own javadoc and
 * ContainerCollector's bank-snapshot-then-pointer-update chaining):
 * persistFinalized() writes the immutable sessions/{sessionId}.json
 * record FIRST and session_state.json SECOND, as one queued writer task
 * (LocalStateStore.writeChained(); both documents serialized on the
 * caller's thread). If the immutable write fails, session_state.json is
 * not touched by that task, so it still holds whatever was last durably
 * written for this account (typically the same session in its
 * pre-finalization shape) -- a restart BEFORE the next ordinary
 * persistCurrent() re-evaluates that session from it. The in-memory
 * lifecycle has already moved on, though, so the next persistCurrent()
 * overwrites it: a failed finalized write is logged by LocalStateStore,
 * and that one session is then missing from History (never duplicated,
 * never double-finalized).
 */
@Slf4j
public final class SessionPersistence
{
	private final LocalStateStore store;
	private final LoadoutResolver resolver;

	/**
	 * Preserved
	 * for backward compatibility with every existing caller/test that
	 * constructs a SessionPersistence with just a store -- delegates
	 * to the two-arg constructor below with a null archive, which
	 * LoadoutResolver treats as "always resolve to unavailable" (see
	 * its own javadoc) rather than throwing. Production wiring
	 * (SessionRuntimeCoordinator) uses the two-arg constructor so
	 * loadout resolution actually has real data to work with.
	 */
	public SessionPersistence(LocalStateStore store)
	{
		this(store, null);
	}

	/**
	 * `loadoutArchive` may be null (see the single-arg constructor
	 * above) -- LoadoutResolver is null-safe by construction.
	 */
	/**
	 * Optional, best-effort notification that a FINALIZED session file has
	 * actually reached disk (called on the store's writer thread). Lets the
	 * History index refresh exactly when a new file exists instead of
	 * polling the sessions directory. Never part of persistence correctness.
	 */
	private volatile Runnable finalizedWriteListener;

	public void setFinalizedWriteListener(Runnable listener)
	{
		this.finalizedWriteListener = listener;
	}

	private void notifyFinalizedWritten()
	{
		Runnable listener = finalizedWriteListener;
		if (listener == null)
		{
			return;
		}
		try
		{
			listener.run();
		}
		catch (RuntimeException e)
		{
			log.debug("finalized-session write listener failed; persistence is unaffected", e);
		}
	}

	public SessionPersistence(LocalStateStore store, LoadoutArchive loadoutArchive)
	{
		this.store = store;
		this.resolver = new LoadoutResolver(loadoutArchive);
	}

	/**
	 * Best-effort load of the current (non-finalized) session for this
	 * account. Fails open (returns null) on a missing file, malformed
	 * JSON, or a file whose content is the literal JSON `null` written
	 * by persistCurrent(null) below — all three mean the same thing:
	 * "no current session," never distinguished from each other, per
	 * this project's established fail-open convention (see
	 * BankSnapshotBaseline.loadFrom()/LocalStateStore.readIfExists()).
	 */
	public Session loadCurrent(long accountHash)
	{
		return store.readIfExists(TelemetryPaths.sessionStateFile(accountHash), Session.class);
	}

	/**
	 * Best-effort load of one specific finalized session by id, for
	 * History's detail view -- same fail-open contract as
	 * loadCurrent() above (null on a missing file, malformed JSON, or
	 * any other read failure; never throws). This is a pure read of
	 * the immutable sessions/{sessionId}.json record persistFinalized()
	 * already writes -- no new file, no new write path, and it is
	 * safe to call from any thread (see LocalStateStore.readIfExists()'s
	 * own javadoc), though a caller doing this in bulk (History's
	 * discovery/index) is still responsible for keeping
	 * that bulk work off the Swing EDT.
	 */
	public Session loadFinalized(long accountHash, String sessionId)
	{
		return store.readIfExists(TelemetryPaths.sessionFile(accountHash, sessionId), Session.class);
	}

	/**
	 * Persist the current in-progress session as session_state.json.
	 * Pass null to represent "no current session" — this writes the
	 * literal JSON `null` rather than deleting the file (LocalStateStore
	 * has no delete primitive, and this project prefers not to add one
	 * just for this), which loadCurrent() above already treats
	 * identically to an absent file.
	 */
	public void persistCurrent(long accountHash, Session current)
	{
		attachStartingLoadoutIfNeeded(current);
		store.write(TelemetryPaths.sessionStateFile(accountHash), current);
	}

	/**
	 * Resolves and attaches a session's starting
	 * loadout AT MOST ONCE per Session object: a no-op the instant
	 * startingLoadout is already non-null. Since this runs on every
	 * ordinary persistCurrent() call, and a brand-new Session is
	 * persisted within about one tick of actually starting (see
	 * SessionRuntimeCoordinator's own tick-batch-closure javadoc), the
	 * FIRST call this method ever sees for a given session happens
	 * while LoadoutArchive still holds fresh, close-to-startedAt
	 * observations -- satisfying the "resolve close to session start"
	 * requirement without any hook into SessionRuntimeCoordinator/
	 * SessionLifecycleEngine's own establishment logic.
	 *
	 * This is also exactly what ensures that identity
	 * refinement within the same sessionId never replaces the
	 * starting loadout: refineIdentity()-style updates never produce
	 * a different sessionId or a different Session object's
	 * startingLoadout field going from non-null back to being
	 * re-resolved -- once set, this guard skips it forever.
	 */
	private void attachStartingLoadoutIfNeeded(Session session)
	{
		if (session == null || session.getStartingLoadout() != null)
		{
			return;
		}
		session.setStartingLoadout(resolver.resolveStarting(session.startedAtInstant()));
	}

	/**
	 * Resolved once, at finalization time -- the natural
	 * "session end" instant -- against whatever LoadoutArchive still
	 * holds. Optional by design: resolveEnding() always returns a
	 * value (falling back to LoadoutSnapshot.unavailable() rather than
	 * null), so this can never block or fail finalization.
	 */
	private void attachEndingLoadoutIfNeeded(Session session)
	{
		if (session == null || session.getEndingLoadout() != null)
		{
			return;
		}
		session.setEndingLoadout(resolver.resolveEnding(session.finalizedAtInstant()));
	}

	/**
	 * Durably persist a just-finalized session as its own immutable,
	 * never-again-mutated record, and only once that succeeds, update
	 * session_state.json to reflect whatever LifecycleResult.getCurrent()
	 * returned alongside it (may be null, may be a freshly-started
	 * replacement session for a different activity) — see class javadoc
	 * for the full ordering rationale. Callers should pass exactly the
	 * (finalized, current) pair from one LifecycleResult.
	 */
	public void persistFinalized(long accountHash, Session finalized, Session newCurrent)
	{
		// Fallback safety net (should ordinarily already be non-null via
		// persistCurrent() above) plus the ending-loadout resolution
		// that only ever makes sense exactly here, at finalization time.
		attachStartingLoadoutIfNeeded(finalized);
		attachEndingLoadoutIfNeeded(finalized);
		attachStartingLoadoutIfNeeded(newCurrent);
		// One queued task, both documents serialized now on the caller's
		// thread: the writer never reads a live Session the client thread is
		// still mutating, no later persistCurrent() can be overtaken by this
		// one, and History hears about the finalized file as soon as it is
		// durable (even if the session_state write then fails).
		store.writeChained(
			TelemetryPaths.sessionFile(accountHash, finalized.getSessionId()), finalized,
			TelemetryPaths.sessionStateFile(accountHash), newCurrent,
			this::notifyFinalizedWritten);
	}

	/**
	 * Synchronous counterpart to persistCurrent(),
	 * for the one caller that cannot tolerate the ordinary fire-and-
	 * forget write's timing -- SessionRuntimeCoordinator's ClientShutdown
	 * handler, mirroring the exact same durability reasoning already
	 * established for ContainerCollector's Bank snapshot shutdown path
	 * (see EventLedger.appendAndWait()'s javadoc for the same pattern
	 * applied to the event ledger). Not used anywhere in ordinary
	 * per-tick persistence -- see persistCurrent() above for that.
	 *
	 * @return true only if this write was confirmed durable before
	 * timeoutMs elapsed.
	 */
	public boolean persistCurrentAndWait(long accountHash, Session current, long timeoutMs)
	{
		attachStartingLoadoutIfNeeded(current);
		return store.writeAndWait(TelemetryPaths.sessionStateFile(accountHash), current, timeoutMs);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A). Durably
	 * persist a session that finalized WITHOUT becoming
	 * session_state.json's new "current" -- the interrupted candidate's
	 * own resolution, whether by displacement (a second real switch
	 * superseded it) or by eligibility-window expiry. Deliberately does
	 * NOT touch session_state.json at all (unlike persistFinalized()
	 * above): session_state.json must keep reflecting whatever is
	 * genuinely `current` right now, which this finalization is
	 * completely independent of -- see class/feature javadoc on the two
	 * sessions' separate lifecycle clocks. Ending-loadout resolution
	 * still runs, against this session's own finalizedAt (its true
	 * interruption instant T1 -- callers must have already set that via
	 * SessionLifecycleEngine.finalizeSession() before this is called),
	 * never the later moment this method happens to run.
	 */
	public void persistAdditionalFinalized(long accountHash, Session additionalFinalized)
	{
		if (additionalFinalized == null)
		{
			return;
		}
		attachStartingLoadoutIfNeeded(additionalFinalized);
		attachEndingLoadoutIfNeeded(additionalFinalized);
		store.write(TelemetryPaths.sessionFile(accountHash, additionalFinalized.getSessionId()), additionalFinalized,
			this::notifyFinalizedWritten);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A). Best-effort
	 * load of the ONE persisted interrupted-candidate record for this
	 * account, or null if none exists -- a missing file, malformed
	 * JSON, or literal JSON `null` (see clearInterruptedCandidate()
	 * below) are all treated identically, same fail-open contract as
	 * loadCurrent() above.
	 */
	public InterruptedCandidateRecord loadInterruptedCandidate(long accountHash)
	{
		return store.readIfExists(TelemetryPaths.interruptedCandidateFile(accountHash), InterruptedCandidateRecord.class);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A). Persist the
	 * ONE parked interrupted candidate additively -- called whenever
	 * SessionLifecycleEngine reports a non-null getInterruptedCandidate()
	 * after a lifecycle call, so a client crash/restart can never
	 * silently lose it (see SessionLifecycleEngine's own
	 * interruptedCandidate field javadoc). `candidate` is persisted
	 * exactly as SessionLifecycleEngine holds it -- no loadout
	 * resolution here; it is still logically an in-progress session,
	 * not a finalized one, so its own eventual starting/ending loadout
	 * resolution happens through the ordinary persistCurrent()/
	 * persistFinalized()/persistAdditionalFinalized() paths once it
	 * resumes or finalizes, exactly like any other Session.
	 */
	public void persistInterruptedCandidate(long accountHash, Session candidate, java.time.Instant interruptedAt, java.time.Instant expiresAt)
	{
		store.write(TelemetryPaths.interruptedCandidateFile(accountHash), new InterruptedCandidateRecord(candidate, interruptedAt, expiresAt));
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A). Clears the
	 * persisted interrupted-candidate record -- called once the ONE
	 * candidate has been resumed, displaced, or expired, so a stale
	 * record is never left behind to be mistakenly rehydrated later.
	 * Same "write the literal JSON `null`, never delete the file"
	 * convention as persistCurrent(accountHash, null) above -- see its
	 * own javadoc; loadInterruptedCandidate() already treats that
	 * identically to an absent file.
	 */
	public void clearInterruptedCandidate(long accountHash)
	{
		store.write(TelemetryPaths.interruptedCandidateFile(accountHash), null);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A) -- RESTART
	 * DURABILITY. Blocking counterpart of persistInterruptedCandidate()/
	 * clearInterruptedCandidate() for the real ClientShutdown path only
	 * (same bounded-wait pattern as persistCurrentAndWait() above): the
	 * JVM may exit as soon as that shutdown future completes, so an
	 * ordinary async write queued there is not guaranteed to reach
	 * disk. `candidate` null writes the literal JSON `null` (identical
	 * to clearInterruptedCandidate()).
	 *
	 * @return true only if this write was confirmed durable before
	 * timeoutMs elapsed.
	 */
	public boolean persistInterruptedCandidateAndWait(long accountHash, Session candidate,
		java.time.Instant interruptedAt, java.time.Instant expiresAt, long timeoutMs)
	{
		Object document = candidate == null ? null : new InterruptedCandidateRecord(candidate, interruptedAt, expiresAt);
		return store.writeAndWait(TelemetryPaths.interruptedCandidateFile(accountHash), document, timeoutMs);
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;

/**
 * The narrow runtime orchestration component: receives already-normalized
 * telemetry facts (via TelemetryEventListener, registered on
 * EventLedger), attaches account/tick/time context, converts them to
 * SessionSignal objects (via SessionEventMapper), batches same-tick
 * signals, resolves them (SessionSignalBatchResolver), updates
 * lifecycle (SessionLifecycleEngine), updates aggregates
 * (SessionAggregateUpdater), and persists the result
 * (SessionPersistence). Lives inside com.osrstelemetry.plugin.session
 * specifically because SessionSignalBatchResolver, its BatchResolution,
 * and MetricUpdate are package-private.
 *
 * THREADING MODEL: every method that touches currentAccountHash, engine,
 * classifierContext, or pendingSignals is `synchronized` on this
 * instance. This is a single, coherent ownership model -- "all
 * coordinator state mutation is serialized through one monitor" --
 * rather than field-by-field locking. It is required, not merely
 * defensive: onEvent() is NOT always called from the RuneLite client
 * thread (SkillsCollector's final XP-window flush can call
 * EventLedger.append() from shutDown() on the AWT thread -- see its own
 * audit note), onGameTick()/ensureAccountLoaded() run on the client
 * thread, and finalizeForClientShutdownBlocking() runs on RuneLite's
 * shared scheduledExecutor thread via the ClientShutdown hook below.
 * Without one shared monitor, `engine`/`classifierContext` -- plain
 * fields reassigned on one thread and read on another with no
 * synchronization at all -- would be a genuine, unguarded data race
 * (not just "stale value": no happens-before edge existed at all in the
 * pre-hardening version of this class). None of these methods block on
 * I/O while holding the monitor except finalizeForClientShutdownBlocking()'s
 * one bounded, synchronous persistCurrentAndWait() call, which happens
 * only once, at genuine client shutdown, and calls nothing that could
 * ever need this same monitor back -- no deadlock risk.
 *
 * DOES NOT RE-PARSE events.jsonl, DOES NOT DUPLICATE COLLECTOR TRUTH
 * LOGIC -- unchanged from the original design; see SessionEventMapper's
 * own javadoc.
 *
 * TICK-BATCH CLOSURE: the original version resolved every pending signal on every
 * GameTick, on the assumption that "GameTick fires after all of that
 * tick's other events." That assumption covers ordinary state-change
 * events (StatChanged, VarbitChanged, ActorDeath, NpcLootReceived,
 * ServerNpcLoot -- all confirmed posted before GameTick), but NOT
 * telemetry emitted from within ANOTHER subscriber's OWN onGameTick()
 * handler for the very same tick -- e.g. this plugin's own periodic
 * skillsCollector.closeXpWindowsIfDue()/questCollector.checkAndFlush()
 * calls, both invoked from OsrsTelemetryPlugin.onGameTick(). RuneLite's
 * EventBus does not guarantee this coordinator's onGameTick() runs
 * AFTER every other subscriber's onGameTick() for the same event, so a
 * same-tick XP_CHANGE emitted that way could have been enqueued into
 * pendingSignals AFTER this coordinator had already drained and
 * resolved that same tick -- silently deferring it into the WRONG
 * (next) tick's batch and reproducing exactly the "transient wrong
 * activity before the real one" bug the whole batching design exists
 * to prevent.
 *
 * FIX: a signal is only ever resolved once a STRICTLY LATER tick number
 * has actually been observed (see processTick()/isClosed()) -- never
 * merely because "a GameTick callback started." RuneLite only posts
 * GameTick for tick N+1 after every subscriber's handling of tick N
 * (including any telemetry emitted mid-handling) is completely done, so
 * observing tick N+1 is a genuine, structural proof that tick N is
 * closed -- no sleep, no subscriber-order assumption. This defers
 * ordinary per-tick resolution by at most one tick (~600ms), which is
 * an explicitly acceptable trade-off (no test in this project requires
 * zero-latency resolution). At real shutdown/ClientShutdown, nothing
 * more can ever arrive for any tick, so flushPendingAndShutdown()/
 * finalizeForClientShutdownBlocking() flush EVERYTHING unconditionally
 * via flushAllPendingSignals(), bypassing the closed-tick wait entirely
 * -- never lose the final pending batch merely because the client stops.
 */
@Slf4j
@Singleton
public final class SessionRuntimeCoordinator implements TelemetryEventListener
{
	private static final long NO_ACCOUNT = -1L;

	// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A) -- lifecycle
	// distinction between a REAL client shutdown and a manual plugin
	// disable. Set (never by timing inference) the moment RuneLite's
	// ClientShutdown event reaches this coordinator; flushPendingAndShutdown()
	// reads it so a Plugin.shutDown() that follows a client shutdown does
	// not finalize/clear the candidate ClientShutdown just preserved for
	// the next process. Never reset: nothing in this process runs after
	// ClientShutdown except exit. Guarded by this instance's monitor.
	private boolean clientShutdownBegun;

	@Inject
	private Client client;

	@Inject
	private ScheduledExecutorService scheduledExecutor;

	private final SessionPersistence persistence;
	private final ActivitySignalClassifier classifier = new ActivitySignalClassifier();
	private List<SessionSignal> pendingSignals = new ArrayList<>();

	private long currentAccountHash = NO_ACCOUNT;
	private SessionLifecycleEngine engine = new SessionLifecycleEngine();
	private ClassifierContext classifierContext = new ClassifierContext();

	/**
	 * See {@link LiveXpTracker}'s own javadoc for the full
	 * contract. Owned here (never durable, never persisted) alongside
	 * `engine`/`classifierContext` -- reset on account switch (see
	 * ensureAccountLoaded()), fed by recordLiveXpDelta() (raw
	 * StatChanged, via SkillsCollector), reconciled inside
	 * applyMetrics() whenever a real durable XP metric lands, and read
	 * by getCurrentSessionSnapshot() under this same monitor.
	 */
	private final LiveXpTracker liveXpTracker = new LiveXpTracker();

	/**
	 * The most recently observed ABSOLUTE XP value for every
	 * skill, fed continuously by SkillsCollector's own raw StatChanged
	 * stream (see noteAbsoluteXp()'s own javadoc) -- the SAME underlying
	 * observations LiveXpTracker's own pending deltas are built from,
	 * just kept as running absolute totals here instead of pending
	 * deltas. NOT session-scoped by itself (it is simply "the latest
	 * known XP per skill, full stop") -- it only becomes session-boundary
	 * data at the exact moment a real switch is detected, when its
	 * current contents are snapshotted into ClassifierContext (see
	 * resolveAndApplyBatches()'s own call to
	 * classifierContext.noteSessionSwitchXpBaseline()). Reset on account
	 * switch (see ensureAccountLoaded()) so a brand-new account never
	 * inherits another account's absolute XP figures.
	 */
	private final Map<String, Long> lastKnownAbsoluteXpBySkill = new HashMap<>();

	// Live in SessionRuntimeCoordinatorTest.java (a real,
	// extensive existing test suite -- device-tree inspection found
	// two call sites, `new SessionRuntimeCoordinator(store)`) --
	// changing this signature outright would have broken that whole
	// file's compilation. Kept exactly as-is, no longer @Inject
	// (Guice only ever uses ONE constructor; the new two-arg one below
	// is what production wiring now uses), delegating to a null
	// archive -- LoadoutResolver treats that as "always unavailable"
	// rather than throwing (see its own javadoc), so every existing
	// test using this constructor keeps compiling and behaving exactly
	// as before.
	public SessionRuntimeCoordinator(LocalStateStore store)
	{
		this(store, null);
	}

	// Purely mechanical constructor-injection wiring so
	// SessionPersistence's starting/ending loadout resolution (see its
	// own javadoc) has real archive data to resolve against in
	// production. One new constructor parameter threaded straight
	// through to SessionPersistence's own (already backward-compatible)
	// two-arg constructor. No lifecycle/classifier/hysteresis/Slayer
	// logic anywhere in this class is touched; every synchronized
	// method, every field below, and the entire threading model
	// described in this class's own javadoc are unchanged.
	@Inject
	public SessionRuntimeCoordinator(LocalStateStore store, LoadoutArchive loadoutArchive)
	{
		this.persistence = new SessionPersistence(store, loadoutArchive);
	}

	/**
	 * Rehydration entry point. Called
	 * from OsrsTelemetryPlugin.handleLogin() on every LOGGED_IN
	 * transition; a same-account call (fresh start already loaded, or a
	 * world hop/relog) is a deliberate no-op (see class javadoc).
	 *
	 * ACCOUNT-SWITCH PENDING BATCH: a real switch away from account A now FLUSHES (not
	 * silently discards) anything still pending for A first -- that
	 * telemetry genuinely already occurred under A before the switch was
	 * observed, so finishing A's own already-occurred batch and
	 * persisting A's resulting state is the honest, no-fabrication
	 * choice, and it can never be applied to B's session (B's engine/
	 * context/pendingSignals do not exist yet at the point this runs).
	 */
	public synchronized void ensureAccountLoaded(long accountHash)
	{
		if (accountHash == currentAccountHash)
		{
			return;
		}
		ensureAccountLoadedCore(accountHash);
		// A different account's (or no) session must not linger on screen.
		notifyCurrentSessionChanged();
	}

	private void ensureAccountLoadedCore(long accountHash)
	{

		if (currentAccountHash != NO_ACCOUNT)
		{
			flushAllPendingSignals();
			// CASE C (never-resolved boss-task candidate) -- account
			// switch: a pending self-consumption candidate that never got
			// to confirm/abort before this switch must not be silently
			// discarded by the fresh ClassifierContext below -- commit
			// its buffered metric(s) once, as a normal contextual metric,
			// to whatever session is legitimately current for the OLD
			// account right now (see flushAbandonedBossTaskCandidateIfMatching()'s
			// own javadoc).
			flushAbandonedBossTaskCandidateIfMatching(engine.getCurrentSession());
			persistence.persistCurrent(currentAccountHash, engine.getCurrentSession());

			// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): "no
			// candidate may disappear silently" -- an account switch is
			// exactly the account boundary this rule targets. The OLD
			// account's ONE parked interrupted candidate, if any, is
			// unconditionally resolved now, AT ITS OWN ORIGINAL
			// INTERRUPTION INSTANT (never `now`), and persisted under the
			// OLD accountHash ONLY -- never carried into, or attributed
			// to, the new account below.
			Session flushedInterruptedCandidate = engine.flushInterruptedCandidateForAccountBoundary();
			if (flushedInterruptedCandidate != null)
			{
				persistence.persistAdditionalFinalized(currentAccountHash, flushedInterruptedCandidate);
			}
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
		else
		{
			pendingSignals = new ArrayList<>();
		}

		currentAccountHash = accountHash;
		classifierContext = new ClassifierContext();
		lastObservedAssignment = null;
		slayerTaskCancelledSinceLastAssignment = false;
		nativeInitialAssignmentKey = null;
		nativeInitialAmount = null;
		// A brand-new account must never inherit
		// a stale live-XP owner/pending amount left over from whichever
		// account was previously loaded -- see LiveXpTracker.reset()'s
		// own javadoc.
		liveXpTracker.reset();
		// A brand-new account must never inherit
		// another account's absolute XP figures as a stale session-
		// boundary baseline -- see lastKnownAbsoluteXpBySkill's own
		// javadoc.
		lastKnownAbsoluteXpBySkill.clear();

		Session persisted = persistence.loadCurrent(accountHash);
		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): loaded
		// independently of `persisted` above -- the two have completely
		// separate lifecycle clocks (see class/feature javadoc), so one
		// missing/expiring never affects how the other rehydrates. Null
		// interruptedCandidateRecord (the common case -- most accounts
		// never have one parked) means "nothing to restore," fully
		// backward compatible with an account that predates this
		// feature.
		InterruptedCandidateRecord interruptedCandidateRecord = persistence.loadInterruptedCandidate(accountHash);
		SessionLifecycleEngine.RehydrationResult rehydrated;
		try
		{
			rehydrated = SessionLifecycleEngine.rehydrate(persisted, Instant.now(),
				interruptedCandidateRecord == null ? null : interruptedCandidateRecord.getSession(),
				interruptedCandidateRecord == null ? null : interruptedCandidateRecord.interruptedAtInstant(),
				interruptedCandidateRecord == null ? null : interruptedCandidateRecord.expiresAtInstant());
		}
		catch (RuntimeException e)
		{
			// A parseable but incomplete saved state (e.g. hand-edited or from
			// a newer version) must not leave the PREVIOUS account's engine
			// live under this account or abort login handling. Start with no
			// current session; the files are left exactly as they are.
			log.warn("Could not restore the saved session state for account {}; starting with no current session", accountHash, e);
			engine = SessionLifecycleEngine.rehydrate(null, Instant.now(), null, null, null).getEngine();
			return;
		}
		engine = rehydrated.getEngine();

		// SMART SLAYER: a pre-ledger Slayer session (current or parked) gets
		// its single bootstrapped record now, so the task ledger renders
		// right after restart. Persisted by the persistCurrent()/
		// syncInterruptedCandidatePersistence() calls below.
		for (Session restored : new Session[] {engine.getCurrentSession(), engine.getInterruptedCandidate()})
		{
			if (restored != null)
			{
				SessionAggregateUpdater.ensureSlayerAssignmentLedger(restored.getAggregates(), restored.getActivityIdentity(),
					restored.getAccumulatedActiveDurationMillis());
			}
		}

		if (rehydrated.getFinalizedDuringRehydration() != null)
		{
			persistence.persistFinalized(accountHash, rehydrated.getFinalizedDuringRehydration(), engine.getCurrentSession());
		}
		else
		{
			persistence.persistCurrent(accountHash, engine.getCurrentSession());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): if the
		// restored candidate's own window had already elapsed by now,
		// rehydrate() already finalized it (never resurrected) --
		// persist that exactly once and make sure no stale candidate
		// record lingers. Otherwise it is now restored onto `engine` as
		// the ONE resumable prior candidate -- re-persist it verbatim so
		// the on-disk record and the in-memory engine agree (a pure
		// no-op write when nothing changed).
		if (rehydrated.getFinalizedInterruptedCandidateDuringRehydration() != null)
		{
			persistence.persistAdditionalFinalized(accountHash, rehydrated.getFinalizedInterruptedCandidateDuringRehydration());
			persistence.clearInterruptedCandidate(accountHash);
		}
		else
		{
			syncInterruptedCandidatePersistence();
		}
	}

	/**
	 * TelemetryEventListener: called synchronously by EventLedger from
	 * inside append()/appendAndWait(), AFTER the durable write has
	 * already been accepted (see EventLedger's own ordering javadoc) --
	 * on whatever thread called append() (see class javadoc's THREADING
	 * MODEL). Deliberately cheap and in-memory only: builds a
	 * SessionSignal (or drops the event, if session-irrelevant) and
	 * queues it. No disk I/O, no lifecycle mutation happens here.
	 */
	@Override
	public synchronized void onEvent(long accountHash, EventType type, Object payload, Instant observedAt)
	{
		if (accountHash != currentAccountHash)
		{
			// A stray event for an account this coordinator is no longer
			// (or not yet) tracking -- e.g. a late off-thread flush racing
			// an account switch. Conservatively dropped rather than
			// misattributed.
			return;
		}

		SessionSignal signal = SessionEventMapper.map(type, payload, observedAt);
		if (signal == null)
		{
			return;
		}

		Long tick = safeTickCount();
		if (tick != null)
		{
			signal = signal.withGameTick(tick);
		}

		pendingSignals.add(signal);
	}

	private Long safeTickCount()
	{
		try
		{
			if (client.isClientThread())
			{
				return (long) client.getTickCount();
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read game tick while ingesting a session signal", e);
		}
		return null;
	}

	/**
	 * The deterministic per-tick flush
	 * point. Reads the CURRENT tick from the client thread (this method
	 * is only ever invoked from onGameTick(), always on the client
	 * thread), then: (1) resolves and applies every pending signal
	 * belonging to a now-PROVABLY-CLOSED tick (strictly less than the
	 * current one -- see class javadoc's TICK-BATCH CLOSURE section);
	 * (2) advances the timeout clock. Step (1) always runs before step
	 * (2) -- events before a timeout boundary are applied before
	 * finalization, for every tick that is actually closed as of this
	 * call.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		processTick(client.getTickCount(), Instant.now());
	}

	synchronized void processTick(long currentTick, Instant now)
	{
		String before = visibleStamp();
		processTickCore(currentTick, now);
		if (!before.equals(visibleStamp()))
		{
			notifyCurrentSessionChanged();
		}
	}

	private void processTickCore(long currentTick, Instant now)
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}

		// TIMEOUT WATERMARK + SKIP-ADVANCE-AFTER-RESOLVE: two DIFFERENT
		// concerns addressing the same underlying principle -- EVENT-TIME ORDERING, NOT
		// PROCESSING-TIME ORDERING must govern a suspend/resume/finalize
		// decision whenever real qualifying evidence is already known.
		//
		// (a) flushClosedBatches() resolves every signal from a tick
		// that is now provably closed. If any of those batches actually
		// applied a real lifecycle transition (RESOLVED -- see
		// resolveAndApplyBatches()'s own javadoc), that transition
		// already used the BATCH's own event-time timestamp (via
		// SessionLifecycleEngine.onQualifyingActivity()/refineIdentity(),
		// which have their own correct, event-time-driven suspend/
		// resume/finalize logic built in). Calling advanceTime() again
		// immediately afterward, in this SAME call, using this call's
		// raw wall-clock `now`, would re-evaluate suspend/finalize using
		// PROCESSING time instead -- and if this tick's own processing
		// happened to run late (a slow tick, a delayed batch), that
		// stale `now` could immediately re-suspend/re-finalize a session
		// that the batch itself had just correctly resumed/extended from
		// its own true occurrence time. So when a real transition was
		// just applied, advanceTime() is deliberately NOT called here
		// -- any further idle-time evaluation is deferred to the
		// NEXT processTick() call, whose own `now` will by then be
		// genuinely current (at most one more tick, ~600ms, later under
		// ordinary play -- see class javadoc's TICK-BATCH CLOSURE
		// section for the same accepted latency trade-off).
		//
		// (b) When nothing was just resolved, timeoutWatermark() still
		// guards the ordinary advanceTime() call below against a
		// DIFFERENT case: a signal already sitting pending for the
		// CURRENT (still-open) tick that hasn't closed yet -- see its
		// own javadoc.
		boolean lifecycleTransitionJustApplied = flushClosedBatches(currentTick);
		if (lifecycleTransitionJustApplied)
		{
			return;
		}

		Instant watermark = timeoutWatermark(currentTick, now);

		Session before = engine.getCurrentSession();
		SessionState beforeState = before == null ? null : before.getState();

		LifecycleResult timeoutResult = engine.advanceTime(watermark);

		// Unconfirmed-candidate metrics duplicated across
		// sessions, Case 4: a pending weak-evidence candidate whose original
		// session's resume window simply expired here still had real,
		// never-confirmed metrics buffered against it -- commit them once,
		// as contextual metrics, to whichever session is finalizing as a
		// result of this same call, BEFORE that session is persisted, so
		// the immutable finalized record actually contains them.
		if (timeoutResult.getContextualMetricsTarget() != null)
		{
			applyMetrics(timeoutResult.getContextualMetricsTarget(), timeoutResult.getContextualMetrics());
		}

		// CASE C (never-resolved boss-task candidate) -- pure idle
		// timeout: a pending self-consumption candidate (an entirely
		// different, classifier-layer mechanism from the weak-evidence
		// candidate just above) is armed only while its boss session is ACTIVE. If
		// that session times out here (ACTIVE -> SUSPENDED, or, on a
		// later call, an already-SUSPENDED session's resume window
		// expiring to FINALIZED) with STILL no same-boss BOSS_KILL or
		// confirming loot ever having arrived, the candidate's buffered
		// metric(s) must not simply evaporate -- commit them once to
		// whichever of `beforeState`'s own session identities is still
		// legitimately current after this call (see
		// flushAbandonedBossTaskCandidateIfMatching()'s own javadoc),
		// BEFORE that session is persisted/finalized below.
		if (timeoutResult.getFinalized() != null)
		{
			flushAbandonedBossTaskCandidateIfMatching(timeoutResult.getFinalized());
		}
		else if (beforeState == SessionState.ACTIVE && timeoutResult.getCurrent() != null
			&& timeoutResult.getCurrent().getState() == SessionState.SUSPENDED)
		{
			flushAbandonedBossTaskCandidateIfMatching(timeoutResult.getCurrent());
		}

		if (timeoutResult.getFinalized() != null)
		{
			persistence.persistFinalized(currentAccountHash, timeoutResult.getFinalized(), timeoutResult.getCurrent());
		}
		else if (timeoutResult.getCurrent() != null && timeoutResult.getCurrent().getState() != beforeState)
		{
			persistence.persistCurrent(currentAccountHash, timeoutResult.getCurrent());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): independent of
		// timeoutResult.getFinalized() above -- "handle the edge case
		// where candidate expiry and current-session lifecycle work occur
		// on the same processing call/tick." advanceTime() never parks or
		// resumes anything itself (only onQualifyingActivity()'s real-
		// switch sites do), so the ONLY way the interrupted candidate
		// changes here is by quietly expiring in the background -- a
		// completely independent event from whatever `current`/B did this
		// same tick, and neither one is ever lost or duplicated.
		if (timeoutResult.getAdditionalFinalized() != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, timeoutResult.getAdditionalFinalized());
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
	}

	/**
	 * Caps `now` at the earliest observedAt among signals still pending
	 * for the CURRENT, not-yet-closed tick (gameTick == currentTick) --
	 * i.e. signals that are already known to have occurred, are already
	 * enqueued, and will be resolved the instant this tick closes (the
	 * very next processTick() call), but have not been applied yet.
	 * Intentionally scoped to gameTick == currentTick only, NOT to
	 * every pending signal: an untagged (off-client-thread) signal is a
	 * separate, pre-existing, documented case (see class javadoc's
	 * OFF-CLIENT-THREAD note) that is deliberately left pending until an
	 * unconditional flush (shutdown/account-switch) rather than ordinary
	 * tick closure, and folding it into this watermark would let one
	 * stray off-thread signal freeze timeout advancement indefinitely
	 * during otherwise-idle ordinary play -- a strictly worse outcome
	 * than the bug being fixed here. A signal tagged with an OLDER tick
	 * (< currentTick) is excluded too: flushClosedBatches() above has
	 * already resolved and applied it before this method is ever called,
	 * so it can no longer affect the watermark.
	 *
	 * STRICT INEQUALITY, NOT EQUALITY: the cap is the pending signal's own observedAt
	 * MINUS ONE NANOSECOND, not the observedAt itself. SessionLifecycleEngine
	 * deliberately treats "exactly at" a suspend/resume-expiry boundary
	 * as belonging to a REAL qualifying event arriving at that instant
	 * (onQualifyingActivity()'s inclusive !isAfter(resumeExpiry) check --
	 * see its own class javadoc's EXACT-BOUNDARY ASYMMETRY note), while
	 * advanceTime() alone reaching that same instant with no accompanying
	 * activity treats it as already-expired (its own inclusive
	 * !isBefore(expiry) check). If this watermark were allowed to equal
	 * the pending signal's observedAt exactly, advanceTime() would apply
	 * the "no accompanying activity" boundary rule at the very instant
	 * real, already-known, still-pending activity actually occurred --
	 * finalizing/suspending a session ahead of the qualifying event that
	 * was about to legitimately resume or extend it. Backing off by one
	 * nanosecond keeps advanceTime() strictly on the "before" side of
	 * that instant, leaving the exact-boundary decision entirely to the
	 * eventual onQualifyingActivity()/refineIdentity() call once the
	 * tick actually closes -- which is the only place that decision is
	 * allowed to be made from event-time.
	 *
	 * When nothing is pending for the current tick, returns `now`
	 * unchanged -- an idle session with no open activity times out on
	 * ordinary wall-clock time exactly as before this fix.
	 */
	/**
	 * A manual re-evaluate is stamped strictly BEFORE every still-pending
	 * signal: those signals were observed before the click but resolve at the
	 * next tick close, and the engine rejects anything older than the
	 * session's lastActiveAt -- stamping the click at wall-clock `now` would
	 * silently drop the pending XP window / task progress / loot.
	 */
	private Instant beforePendingSignals(Instant now)
	{
		Instant stamp = now;
		for (SessionSignal signal : pendingSignals)
		{
			Instant cap = signal.getObservedAt().minusNanos(1);
			if (cap.isBefore(stamp))
			{
				stamp = cap;
			}
		}
		return stamp;
	}

	private Instant timeoutWatermark(long currentTick, Instant now)
	{
		Instant watermark = now;
		for (SessionSignal signal : pendingSignals)
		{
			Long tick = signal.getGameTick();
			if (tick != null && tick == currentTick)
			{
				Instant cap = signal.getObservedAt().minusNanos(1);
				if (cap.isBefore(watermark))
				{
					watermark = cap;
				}
			}
		}
		return watermark;
	}

	/**
	 * Splits off and resolves every pending signal belonging to a tick
	 * strictly before currentTick -- i.e. a tick RuneLite has already
	 * fully finished dispatching, including every subscriber's own
	 * onGameTick()-driven telemetry for it (see class javadoc). Signals
	 * tagged with currentTick itself (still open -- this very GameTick
	 * dispatch may not be done yet) and any signal with no tick at all
	 * (the rare off-thread case -- see safeTickCount()) are left pending
	 * for a later call; an untagged signal is conservatively treated the
	 * same as "not yet provably closed" rather than flushed immediately,
	 * so it still gets at least one full tick to be joined by anything
	 * else from the same real game action before being resolved.
	 *
	 * @return true if any batch resolved here actually applied a real
	 * lifecycle transition (a RESOLVED outcome -- see
	 * resolveAndApplyBatches()'s own return-value javadoc). processTick()
	 * uses this to decide whether it is safe to also run advanceTime()
	 * in the same call -- see its own javadoc for why it must not.
	 */
	private boolean flushClosedBatches(long currentTick)
	{
		List<SessionSignal> closed = new ArrayList<>();
		List<SessionSignal> stillOpen = new ArrayList<>();
		for (SessionSignal signal : pendingSignals)
		{
			Long tick = signal.getGameTick();
			if (tick != null && tick < currentTick)
			{
				closed.add(signal);
			}
			else
			{
				stillOpen.add(signal);
			}
		}
		pendingSignals = stillOpen;
		return resolveAndApplyBatches(closed);
	}

	/**
	 * Unconditional flush of everything pending, regardless of tick
	 * closure -- used only when nothing more can possibly arrive for any
	 * tick (plugin disable, real account switch, client shutdown). See
	 * class javadoc's TICK-BATCH CLOSURE section for why the ordinary
	 * per-GameTick path (flushClosedBatches()) must NOT do this. Return
	 * value intentionally ignored by every caller of this method (none
	 * of them ever call advanceTime() afterward).
	 */
	private boolean flushAllPendingSignals()
	{
		List<SessionSignal> toProcess = pendingSignals;
		pendingSignals = new ArrayList<>();
		return resolveAndApplyBatches(toProcess);
	}

	/**
	 * @return true if at least one batch in `toProcess` had a RESOLVED
	 * outcome -- i.e. actually called engine.onQualifyingActivity()/
	 * refineIdentity() and mutated the session's lifecycle state (ACTIVE/
	 * SUSPENDED/FINALIZED, lastActiveAt, or activityIdentity). false for
	 * an empty input, or when every batch was NO_EVIDENCE/AMBIGUOUS
	 * (metrics may still have been applied to an already-current
	 * session in that case, but no lifecycle transition occurred).
	 */
	private boolean resolveAndApplyBatches(List<SessionSignal> toProcess)
	{
		if (toProcess.isEmpty())
		{
			return false;
		}

		boolean anyLifecycleTransitionApplied = false;

		List<List<SessionSignal>> batches = SessionSignalBatchResolver.groupIntoBatches(toProcess);
		for (List<SessionSignal> batch : batches)
		{
			// SMART SLAYER TASK STATE: installed BEFORE this batch's own
			// lifecycle resolution, so a same-batch SLAYER_TASK_PROGRESS for
			// the new task already matches the retained session's (re-keyed)
			// assignment instead of looking like a brand-new activity. Never
			// itself a lifecycle transition -- see applySlayerAssignmentUpdates().
			applySlayerAssignmentUpdates(batch);

			Session preBatchCurrent = engine.getCurrentSession();
			SessionSignalBatchResolver.BatchResolution resolution =
				SessionSignalBatchResolver.resolve(batch, preBatchCurrent, classifier, classifierContext);

			// LOOT-WHILE-ACTIVE OWNERSHIP: applied directly to the pre-batch
			// `current` session, unconditionally, BEFORE any lifecycle
			// transition below -- see SessionSignalBatchResolver.resolve()'s
			// own comment for the full rationale. Whatever preBatchCurrent
			// goes on to become in this same call (unchanged `current`,
			// re-keyed via refineIdentity(), or finalized by a same-tick
			// switch) already carries this loot once this mutates it, so
			// it is never lost and never rides onto an unrelated new
			// session purely because that session happened to win this
			// batch's lifecycle decision.
			if (preBatchCurrent != null && !resolution.getPreBatchCurrentMetricUpdates().isEmpty())
			{
				applyMetrics(preBatchCurrent, resolution.getPreBatchCurrentMetricUpdates());
			}

			if (resolution.getOutcome() == BatchLifecycleOutcome.RESOLVED)
			{
				SignalClassification winning = resolution.getLifecycleClassification();
				// EVIDENCE STRENGTH: only
				// onQualifyingActivity() ever gates a transition behind the
				// weak-evidence candidate mechanism (see
				// SessionLifecycleEngine's own javadoc) -- refineIdentity()
				// never gates (it re-keys the SAME continuous activity, not
				// a competing one), so it has no strength parameter to
				// receive.
				LifecycleResult result = winning.getDecisionKind() == SignalDecisionKind.REFINE
					? engine.refineIdentity(winning.getIdentity(), resolution.getLifecycleTimestamp(), resolution.getMetricUpdates())
					: engine.onQualifyingActivity(winning.getIdentity(), resolution.getLifecycleTimestamp(), resolution.getMetricUpdates(), resolution.getLifecycleEvidenceStrength());
				anyLifecycleTransitionApplied = true;

				// A GENUINE session-identity switch
				// -- result.getCurrent() is a different session id than
				// whatever was current immediately before this batch
				// (never true for refineIdentity(), which always re-keys
				// the SAME continuous session/id) -- captures an exact
				// per-skill absolute-XP baseline for the brand-new
				// session, from whatever this coordinator has most
				// recently observed via SkillsCollector's raw StatChanged
				// stream. This is what lets a LATER XP_CHANGE, whose own
				// aggregation window spans this exact switch, be split
				// exactly into its pre-switch and post-switch portions --
				// see ClassifierContext.noteSessionSwitchXpBaseline()'s
				// own javadoc and classifyXpChange()'s boundary-ownership
				// rule for the full mechanism this baseline enables.
				if (result.getCurrent() != null
					&& (preBatchCurrent == null || !preBatchCurrent.getSessionId().equals(result.getCurrent().getSessionId())))
				{
					classifierContext.noteSessionSwitchXpBaseline(result.getCurrent().getSessionId(), lastKnownAbsoluteXpBySkill);
				}

				// CASE C (never-resolved boss-task candidate) -- an
				// UNRELATED real switch (a different boss's BOSS_KILL, a
				// SKILLING switch, any other authoritative evidence that
				// has nothing to do with this candidate) just finalized
				// the boss session a self-consumption candidate is still
				// pending for, without ever going through
				// classifyBossKill()/classifyServerNpcLoot()'s own
				// confirm/abort branches (those already clear the
				// candidate themselves -- this is a pure no-op whenever
				// they already ran). The candidate's buffered metric(s)
				// belong to real activity that genuinely occurred during
				// THAT now-finalizing session, so they are committed
				// there, once, BEFORE it is persisted -- never onto the
				// new, unrelated session this batch just started.
				if (result.getFinalized() != null)
				{
					flushAbandonedBossTaskCandidateIfMatching(result.getFinalized());
				}
				else if (result.getCurrent() != null
					&& (preBatchCurrent == null || !preBatchCurrent.getSessionId().equals(result.getCurrent().getSessionId()))
					&& engine.getInterruptedCandidate() != null)
				{
					// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): a
					// genuine switch just happened (result.getCurrent() is
					// a different session id than preBatchCurrent) but
					// result.getFinalized() is null -- the ONLY way that
					// combination arises is applyRealSwitch()'s PARK
					// outcome (see its own javadoc: RESUME and LEGACY
					// IMMEDIATE FINALIZE both always populate
					// result.getFinalized()). preBatchCurrent was just
					// parked as engine.getInterruptedCandidate() rather
					// than finalized -- exactly the same "stopped being
					// current for some other reason" case
					// flushAbandonedBossTaskCandidateIfMatching()'s own
					// javadoc already covers, just via parking instead of
					// finalizing.
					flushAbandonedBossTaskCandidateIfMatching(engine.getInterruptedCandidate());
				}

				// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A):
				// independent of result.getFinalized() above -- see
				// LifecycleResult's own javadoc on the dual-finalization
				// edge case. Never touches session_state.json (the
				// interrupted candidate, whether displaced or resumed-
				// away-from, is never what `current` is right now).
				if (result.getAdditionalFinalized() != null)
				{
					persistence.persistAdditionalFinalized(currentAccountHash, result.getAdditionalFinalized());
				}

				// Unconfirmed-candidate metrics duplicated
				// across sessions: this batch's own metrics no longer go
				// unconditionally to result.getCurrent() -- while a
				// weak-evidence candidate is merely being armed/replaced,
				// result.getCurrent() is still the OLD established
				// session, not any kind of holding area for this batch.
				// The engine now tells us exactly where this batch's own
				// metrics belong (metricsForCurrent -- empty when they
				// were only buffered as a pending candidate) and,
				// separately, whether an ABANDONED candidate's previously-
				// buffered metrics must be committed once, as contextual
				// metrics, to whichever session they actually occurred
				// during (contextualMetricsTarget/contextualMetrics --
				// see LifecycleResult's own javadoc). Applying both here,
				// to their own correct targets, is what makes every real
				// metric land exactly once.
				applyMetrics(result.getCurrent(), result.getMetricsForCurrent());
				if (result.getContextualMetricsTarget() != null)
				{
					applyMetrics(result.getContextualMetricsTarget(), result.getContextualMetrics());
				}

				if (result.getFinalized() != null)
				{
					// Immutable finalized record written before the
					// pointer is cleared/replaced -- SessionPersistence's
					// own existing write-then-callback ordering guarantee
					// (unchanged finalization ordering). The contextual-metrics apply
					// above already ran before this write whenever its
					// target was this same finalized session, so the
					// committed-once contextual metrics are included in
					// the immutable record.
					persistence.persistFinalized(currentAccountHash, result.getFinalized(), result.getCurrent());
				}
				else
				{
					persistence.persistCurrent(currentAccountHash, result.getCurrent());
				}
				syncInterruptedCandidatePersistence();
			}
			else
			{
				// NO_EVIDENCE or AMBIGUOUS: no lifecycle transition, but
				// every metric in the batch is still credited to whatever
				// session is ALREADY current -- never fabricated a place
				// to put it if there is none. preBatchCurrentMetricUpdates
				// (if any) were already applied to this exact same session
				// object above, so persistence just needs to fire whenever
				// EITHER list was non-empty.
				Session target = engine.getCurrentSession();
				boolean hasOrdinaryMetrics = !resolution.getMetricUpdates().isEmpty();
				boolean hasPreBatchCurrentMetrics = preBatchCurrent != null && !resolution.getPreBatchCurrentMetricUpdates().isEmpty();
				if (target != null && hasOrdinaryMetrics)
				{
					applyMetrics(target, resolution.getMetricUpdates());
				}
				if (target != null && (hasOrdinaryMetrics || hasPreBatchCurrentMetrics))
				{
					persistence.persistCurrent(currentAccountHash, target);
				}
			}
			attachStructuredLiveXp(batch, preBatchCurrent);
		}

		return anyLifecycleTransitionApplied;
	}

	/**
	 * SMART SLAYER TASK STATE. For every authoritative SLAYER_TASK_ASSIGNED
	 * in `batch` (SlayerCollector emits it for no-task -&gt; task and for a
	 * direct task-A -&gt; task-B replacement; never for plain progress),
	 * installs the new assignment on the RETAINED broader Slayer session,
	 * if any, via SessionLifecycleEngine.reassignSlayerTask() -- see that
	 * method for exactly which session is eligible and why this can never
	 * create, resume, or steal a session. The signal itself still reaches
	 * the classifier afterwards unchanged (ClassifierContext's tracked
	 * task/family context is updated there, exactly as before).
	 *
	 * When the assignment actually changed, or the target was AWAITING a
	 * task (remaining == 0 -- e.g. the same task name assigned again),
	 * the new assignment's amount becomes the live remaining count
	 * (AWAITING_TASK -&gt; ACTIVE_TASK; the "Grab a new task" card goes
	 * away on the next render) and the per-assignment XP-estimate
	 * baselines are recorded. Session-wide totals (task units, XP, loot,
	 * kills, duration) are never touched. A duplicate observation of the
	 * assignment already installed and in progress is a pure no-op.
	 */
	private void applySlayerAssignmentUpdates(List<SessionSignal> batch)
	{
		for (SessionSignal signal : batch)
		{
			if (signal.getKind() == SignalKind.SLAYER_TASK_COMPLETED)
			{
				slayerTaskCancelledSinceLastAssignment = signal.isSlayerTaskCancelled();
				continue;
			}
			if (signal.getKind() == SignalKind.SLAYER_TASK_PROGRESS)
			{
				noteNativeInitialAmount(signal);
				noteAssignmentMaster(signal);
				continue;
			}
			if (signal.getKind() != SignalKind.SLAYER_TASK_ASSIGNED || signal.getSlayerTaskName() == null)
			{
				continue;
			}
			boolean previousTaskCancelled = slayerTaskCancelledSinceLastAssignment;
			slayerTaskCancelledSinceLastAssignment = false;
			ActivityIdentity assignment = ActivitySignalClassifier.slayerIdentity(signal.getSlayerTaskName(), signal.getSlayerTaskLocation());
			lastObservedAssignment = signal;
			SessionLifecycleEngine.SlayerAssignmentUpdate update = engine.reassignSlayerTask(assignment, signal.getObservedAt());
			Session target = update.getTarget();
			if (target == null)
			{
				continue;
			}

			SessionAggregates aggregates = target.getAggregates();
			// A pre-ledger session (mid-task start / older file) gets its
			// instance #1 under the assignment it held BEFORE this update,
			// seeded with all loot it already owns -- never the new task.
			SessionAggregateUpdater.ensureSlayerAssignmentLedger(aggregates, update.getPreviousAssignment(),
				target.getAccumulatedActiveDurationMillis());
			Integer remaining = aggregates.getLatestSlayerCurrentRemaining();
			boolean awaitingTask = (remaining != null && remaining == 0) || previousTaskCancelled;
			if (!update.isIdentityChanged() && !awaitingTask)
			{
				// Duplicate observation of the assignment already installed
				// and in progress: idempotent -- no bucket, no count reset.
				continue;
			}

			// A genuinely new assignment INSTANCE (new task, direct
			// replacement, or the same task name assigned again after
			// completion): exactly one new ledger bucket, starting at 0 loot.
			aggregates.setSlayerAssignmentBaselineProgressDelta(
				aggregates.getSlayerProgressDelta() == null ? 0 : aggregates.getSlayerProgressDelta());
			aggregates.setSlayerAssignmentBaselineSlayerXp(slayerXpOf(aggregates));
			SessionAggregates.SlayerAssignmentRecord begun = SessionAggregateUpdater.beginSlayerAssignment(aggregates, assignment,
				signal.getObservedAt(), signal.getSlayerInitialAmount(),
				// A parked candidate's time is frozen while it is parked: never add live time for it.
				update.isTargetCurrent() ? activeDurationAt(target, signal.getObservedAt()) : target.getAccumulatedActiveDurationMillis());
			begun.setMasterId(signal.getSlayerMasterId());
			if (signal.getSlayerInitialAmount() != null)
			{
				applyMetrics(target, Collections.singletonList(MetricUpdate.slayerProgress(0, signal.getSlayerInitialAmount())));
			}

			if (update.isTargetCurrent())
			{
				visibleMutations++;
				persistence.persistCurrent(currentAccountHash, target);
			}
			else
			{
				syncInterruptedCandidatePersistence();
			}
		}
	}

	/**
	 * The session's ACTIVE duration as of instant `t`, with exactly the
	 * semantics the panel uses for the live session timer: the
	 * accumulated active time, plus -- only while the session is ACTIVE --
	 * the time since its last qualifying activity up to `t`, capped at the
	 * idle-suspend timeout. Suspended time and time while the session is
	 * parked/not current are never included (such a session is not
	 * ACTIVE, or does not accumulate). `t` null = accumulated only.
	 */
	static long activeDurationAt(Session session, Instant t)
	{
		long accumulated = session.getAccumulatedActiveDurationMillis();
		if (t == null || session.getState() != SessionState.ACTIVE || session.getLastActiveAt() == null)
		{
			return accumulated;
		}
		long live = java.time.Duration.between(session.lastActiveAtInstant(), t).toMillis();
		live = Math.max(0L, Math.min(live, SessionLifecycleEngine.SUSPEND_TIMEOUT.toMillis()));
		return accumulated + live;
	}

	/**
	 * SMART SLAYER: the latest authoritative SLAYER_TASK_ASSIGNED observed
	 * for the current account (whether or not a session was retained to
	 * receive it). Lets a Slayer session that is only created later, by real
	 * gameplay, record that FIRST assignment as fully observed (its real
	 * amount and start) instead of "bootstrapped mid-task". Account-scoped:
	 * cleared on every account change.
	 */
	private SessionSignal lastObservedAssignment;
	/**
	 * A Slayer task was CANCELLED (cleared without finishing; see
	 * SessionSignal#isSlayerTaskCancelled) and no assignment has been seen
	 * since. Its record keeps its real remaining (&gt; 0), so the next
	 * assignment -- even the SAME task name again -- must still start a new
	 * instance instead of being taken for a duplicate observation.
	 * Transient: reset on account switch.
	 */
	private boolean slayerTaskCancelledSinceLastAssignment;

	/**
	 * A just-bootstrapped first ledger record whose assignment is exactly
	 * the last authoritatively observed ASSIGNED (same task + location key)
	 * becomes a fully observed record: its real initial amount and
	 * assignment time. Otherwise it stays bootstrapped (Spyglass genuinely
	 * joined mid-task, e.g. the task predates this login).
	 */
	/**
	 * SMART SLAYER: the latest native original task size (SLAYER_COUNT_ORIGINAL
	 * +/- modifier) observed on a SLAYER_TASK_PROGRESS, keyed by that task's
	 * assignment key. Account-scoped; cleared on every account change. See
	 * retainNativeInitialAmount().
	 */
	private String nativeInitialAssignmentKey;
	private Integer nativeInitialAmount;

	/**
	 * A current assignment record with no known master (Spyglass joined
	 * mid-task, or an older record) adopts the master varbit carried by a
	 * progress observation of the SAME assignment key. Metadata only; set
	 * at most once.
	 */
	private void noteAssignmentMaster(SessionSignal progress)
	{
		Integer masterId = progress.getSlayerMasterId();
		if (masterId == null || progress.getSlayerTaskName() == null)
		{
			return;
		}
		String key = ActivitySignalClassifier.slayerIdentity(progress.getSlayerTaskName(), progress.getSlayerTaskLocation()).getActivityKey();
		for (Session session : new Session[] {engine.getCurrentSession(), engine.getInterruptedCandidate()})
		{
			if (session == null)
			{
				continue;
			}
			SessionAggregates.SlayerAssignmentRecord record = SessionAggregateUpdater.currentSlayerAssignment(session.getAggregates());
			if (record != null && record.getMasterId() == null && record.getEndReason() == null && key.equals(record.getAssignmentKey()))
			{
				record.setMasterId(masterId);
			}
		}
	}

	private void noteNativeInitialAmount(SessionSignal progress)
	{
		Integer amount = progress.getSlayerInitialAmount();
		if (progress.getSlayerTaskName() == null || amount == null || amount <= 0)
		{
			return;
		}
		nativeInitialAssignmentKey = ActivitySignalClassifier.slayerIdentity(progress.getSlayerTaskName(), progress.getSlayerTaskLocation())
			.getActivityKey();
		nativeInitialAmount = amount;
		Session current = engine.getCurrentSession();
		if (retainNativeInitialAmount(current))
		{
			persistence.persistCurrent(currentAccountHash, current);
		}
		if (retainNativeInitialAmount(engine.getInterruptedCandidate()))
		{
			syncInterruptedCandidatePersistence();
		}
	}

	/**
	 * A BOOTSTRAPPED current assignment record (Spyglass joined mid-task)
	 * whose key matches the latest native original size records it as
	 * assignedInitialAmount -- authoritative assignment METADATA only. The
	 * record stays bootstrapped and its initialAmount, unitsCompleted, XP and
	 * active-duration fields are untouched, so nothing Spyglass did not
	 * observe is ever credited. Set at most once. Rejected when inconsistent
	 * with what this record already observed (original size smaller than the
	 * remaining it had when Spyglass attached: latestRemaining + its own
	 * observed units), which means the native value belongs to a different
	 * instance of a same-named task.
	 *
	 * @return true when the record changed
	 */
	private boolean retainNativeInitialAmount(Session session)
	{
		if (session == null || nativeInitialAssignmentKey == null || nativeInitialAmount == null)
		{
			return false;
		}
		SessionAggregates.SlayerAssignmentRecord record = SessionAggregateUpdater.currentSlayerAssignment(session.getAggregates());
		if (record == null || !record.isBootstrapped() || record.getAssignedInitialAmount() != null
			|| !nativeInitialAssignmentKey.equals(record.getAssignmentKey()))
		{
			return false;
		}
		if (record.getLatestRemaining() == null)
		{
			// Nothing observed yet to check it against -- retried on the next progress.
			return false;
		}
		int remainingWhenAttached = record.getLatestRemaining() + (record.getUnitsCompleted() == null ? 0 : record.getUnitsCompleted());
		if (nativeInitialAmount < remainingWhenAttached)
		{
			return false;
		}
		record.setAssignedInitialAmount(nativeInitialAmount);
		return true;
	}

	private void adoptObservedAssignment(Session target)
	{
		SessionSignal observed = lastObservedAssignment;
		SessionAggregates.SlayerAssignmentRecord first = SessionAggregateUpdater.currentSlayerAssignment(target.getAggregates());
		if (observed == null || first == null || !first.isBootstrapped())
		{
			return;
		}
		String key = ActivitySignalClassifier.slayerIdentity(observed.getSlayerTaskName(), observed.getSlayerTaskLocation()).getActivityKey();
		if (!key.equals(first.getAssignmentKey()))
		{
			return;
		}
		first.setBootstrapped(false);
		first.setInitialAmount(observed.getSlayerInitialAmount());
		first.setAssignedAt(observed.getObservedAt().toString());
		if (first.getMasterId() == null)
		{
			first.setMasterId(observed.getSlayerMasterId());
		}
	}

	private static long slayerXpOf(SessionAggregates aggregates)
	{
		long total = 0L;
		if (aggregates.getXpGainedBySkill() != null)
		{
			for (Map.Entry<String, Long> e : aggregates.getXpGainedBySkill().entrySet())
			{
				if ("SLAYER".equalsIgnoreCase(e.getKey()) && e.getValue() != null)
				{
					total += e.getValue();
				}
			}
		}
		return total;
	}

	private void applyMetrics(Session target, List<MetricUpdate> metrics)
	{
		if (target == null)
		{
			return;
		}
		// SMART SLAYER: a Slayer session gets its first assignment record the
		// moment it genuinely owns metrics (created, resumed, or established
		// mid-task) -- before this batch's loot is applied, so it lands there.
		if (!metrics.isEmpty() && target == engine.getCurrentSession())
		{
			visibleMutations++;
		}
		boolean ledgerCreated = SessionAggregateUpdater.ensureSlayerAssignmentLedger(target.getAggregates(), target.getActivityIdentity(),
			target.getAccumulatedActiveDurationMillis());
		if (ledgerCreated)
		{
			adoptObservedAssignment(target);
		}
		for (MetricUpdate metric : metrics)
		{
			if (metric.getActivityStatsKey() != null
				&& (target.getActivityIdentity().getActivityType() != ActivityType.STRUCTURED_ACTIVITY
					|| !metric.getActivityStatsKey().equals(target.getActivityIdentity().getActivityKey())))
			{
				// Activity stats belong to that activity's own session only --
				// never ride a batch onto any other session.
				continue;
			}
			SessionAggregateUpdater.apply(target.getAggregates(), metric);
			// This durable application, the
			// instant it happens, now represents the raw StatChanged gains
			// its window carried for this (session, skill) pair -- so that
			// much of the live, not-yet-represented portion is removed here,
			// in the SAME call that just made it durable (gains already
			// pending from after the window closed stay visible). See
			// LiveXpTracker.reconcile()'s own javadoc for why this is
			// what guarantees an exact-once DISPLAY total (never double-
			// counts once XP_CHANGE catches up). A no-op for any metric
			// that isn't an XP metric (getXpSkill() null), and a no-op
			// whenever `target` isn't this tracker's current live-XP
			// owner (an abandoned/finalized session's own delayed
			// XP_CHANGE landing here via the contextual-metrics path --
			// never this tracker's live view of whatever is current now).
			if (metric.getXpSkill() != null)
			{
				liveXpTracker.reconcile(target.getSessionId(), metric.getXpSkill(), metric.getXpDelta());
			}
		}
		// After this batch's metrics: a just-bootstrapped record must already
		// hold the remaining it was attached at before retainNativeInitialAmount()
		// can check the native original size against it.
		retainNativeInitialAmount(target);
		// SMART SLAYER: a just-ended assignment's task-local active time
		// freezes at its own completion instant, so post-completion travel
		// never dilutes its XP/hr.
		SessionAggregates.SlayerAssignmentRecord justEnded = SessionAggregateUpdater.currentSlayerAssignment(target.getAggregates());
		if (justEnded != null && justEnded.getEndReason() != null && justEnded.getActiveDurationEndMillis() == null)
		{
			justEnded.setActiveDurationEndMillis(
				activeDurationAt(target, justEnded.getCompletedAt() == null ? null : Instant.parse(justEnded.getCompletedAt())));
		}
	}

	/**
	 * CASE C (never-resolved boss-task candidate) -- the deterministic
	 * fallback DESIRED RESOLUTION C asks for: a pending self-consumption
	 * candidate (see ClassifierContext's own javadoc) that never got to
	 * confirm (a same-boss BOSS_KILL) or abort (a real-switch-confirming
	 * loot) before its own boss session stops being current for ANY
	 * OTHER reason -- a pure idle timeout suspending/finalizing it, an
	 * unrelated authoritative switch finalizing it, or an account switch
	 * -- must not silently lose that candidate's buffered metric(s).
	 *
	 * `target` is always one of: the SAME session object the candidate
	 * was armed against (now merely SUSPENDED, still "legitimately
	 * current"), or that same session having just been FINALIZED this
	 * same call (about to be persisted as an immutable record). Never a
	 * brand-new, unrelated session -- this is exactly what "commit to
	 * whatever session is legitimately current at that point, never to a
	 * session that's already been finalized and persisted with
	 * different, already-locked-in contents" means: the flush always
	 * happens strictly BEFORE the persist/finalize call that makes
	 * `target` immutable, so there is never any retroactive mutation of
	 * an already-durable record -- mirroring exactly how
	 * SessionLifecycleEngine's own unrelated SUSPENDED
	 * weak-evidence candidate mechanism commits its own abandoned
	 * candidate's pendingCandidateMetrics.
	 *
	 * A no-op whenever `target` is null (nothing to attach to) or
	 * classifierContext holds no candidate for EXACTLY `target`'s own
	 * activity identity -- in particular, whenever
	 * classifyBossKill()/classifyServerNpcLoot() already resolved
	 * (confirmed or aborted) the candidate themselves during
	 * classification, this is already a no-op by the time it is called
	 * (the candidate is already cleared), so it never double-applies
	 * anything.
	 */
	private void flushAbandonedBossTaskCandidateIfMatching(Session target)
	{
		if (target == null || !classifierContext.hasBossTaskCandidateFor(target.getActivityIdentity()))
		{
			return;
		}
		List<MetricUpdate> buffered = classifierContext.getPendingBossTaskCandidateMetrics();
		classifierContext.clearBossTaskCandidate();
		applyMetrics(target, buffered);
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A). Keeps the
	 * persisted interrupted-candidate record (see
	 * TelemetryPaths.interruptedCandidateFile()) in sync with
	 * engine.getInterruptedCandidate()'s own in-memory state for the
	 * CURRENT account -- called after any lifecycle-mutating engine call
	 * that could have parked, resumed, or displaced the ONE resumable
	 * candidate, so a client crash immediately afterward can never lose
	 * or resurrect stale candidate state ("persist the ONE interrupted
	 * candidate additively"). A pure no-op write (persist the same
	 * candidate again, or clear an already-absent one) whenever nothing
	 * actually changed -- correctness over write-avoidance here, since
	 * this file is small and this call site is not a hot per-tick path
	 * (see processTick()'s own comment for why THAT path does its own,
	 * narrower thing instead of calling this).
	 */
	private void syncInterruptedCandidatePersistence()
	{
		Session candidate = engine.getInterruptedCandidate();
		if (candidate != null)
		{
			persistence.persistInterruptedCandidate(currentAccountHash, candidate,
				engine.getInterruptedCandidateInterruptedAt(), engine.getInterruptedCandidateExpiresAt());
		}
		else
		{
			persistence.clearInterruptedCandidate(currentAccountHash);
		}
	}

	/**
	 * Called from OsrsTelemetryPlugin.shutDown() -- see the fixed
	 * ordering note there: this MUST
	 * run, with the EventLedger listener still registered, AFTER every
	 * collector flush able to emit final telemetry (Bank, XP window).
	 * Flushes unconditionally (flushAllPendingSignals(), not the
	 * closed-tick-only path -- there is no further GameTick coming) and
	 * persists current state exactly as it is, WITHOUT calling
	 * advanceTime(): disabling the plugin is not itself a real
	 * inactivity gap.
	 */
	public synchronized void flushPendingAndShutdown()
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		flushAllPendingSignals();
		persistence.persistCurrent(currentAccountHash, engine.getCurrentSession());

		if (clientShutdownBegun)
		{
			// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): this
			// Plugin.shutDown() is part of a REAL client shutdown -- the
			// candidate is being preserved for the next process's
			// rehydrate(), never finalized/cleared here. Re-persisted
			// (not skipped) so the on-disk record is correct even if
			// this ran before ClientShutdown's own blocking write got
			// the monitor; LocalStateStore.shutdown() drains this write.
			syncInterruptedCandidatePersistence();
			return;
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): MANUAL plugin
		// disable (no ClientShutdown). Spyglass cannot observe gameplay
		// while disabled, so continuity with the parked candidate is
		// unknown -- it must not survive into a later re-enable.
		// Finalized exactly once AT ITS OWN ORIGINAL INTERRUPTION
		// INSTANT and cleared, exactly like the account-switch boundary.
		Session flushedInterruptedCandidate = engine.flushInterruptedCandidateForAccountBoundary();
		if (flushedInterruptedCandidate != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, flushedInterruptedCandidate);
		}
		persistence.clearInterruptedCandidate(currentAccountHash);
	}

	/**
	 * Mirrors
	 * ContainerCollector's own already-proven ClientShutdown durability
	 * pattern. Entirely separate from ContainerCollector's own hook --
	 * does not touch Bank's path.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		event.waitFor(beginClientShutdownFinalization());
	}

	CompletableFuture<Void> beginClientShutdownFinalization()
	{
		markClientShutdownBegun();
		return CompletableFuture.runAsync(this::finalizeForClientShutdownBlocking, scheduledExecutor);
	}

	/**
	 * Runs on RuneLite's shared scheduledExecutor thread, NOT the client
	 * thread -- this is exactly why every field this touches is guarded
	 * by this instance's monitor (see class javadoc's THREADING MODEL).
	 * The single persistCurrentAndWait() call blocks (bounded, 5s) while
	 * holding that monitor; nothing it calls can ever need the monitor
	 * back, so this cannot deadlock against onGameTick()/onEvent() --
	 * they simply wait if they happen to be called during this window.
	 */
	/** Records, synchronously on the thread delivering ClientShutdown,
	 * that this is a real client shutdown -- before the async
	 * finalization below is even scheduled, so a Plugin.shutDown()
	 * racing it can never mistake this for a manual disable. */
	synchronized void markClientShutdownBegun()
	{
		clientShutdownBegun = true;
	}

	synchronized void finalizeForClientShutdownBlocking()
	{
		clientShutdownBegun = true;
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		flushAllPendingSignals();
		persistence.persistCurrentAndWait(currentAccountHash, engine.getCurrentSession(), 5000);

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A) -- RESTART
		// DURABILITY FIX. Real client shutdown is exactly the restart
		// this feature must survive, so the parked candidate is NOT
		// finalized here (that previously made "A -> B -> close ->
		// restart -> A" always mint a fresh A whenever the async
		// finalize/clear writes happened to land before JVM exit). It is
		// instead durably re-persisted, BLOCKING like session_state.json
		// above (the JVM may exit as soon as this future completes), and
		// the next startup's rehydrate() restores it if still eligible or
		// finalizes it exactly once at its own T1 if not.
		persistence.persistInterruptedCandidateAndWait(currentAccountHash, engine.getInterruptedCandidate(),
			engine.getInterruptedCandidateInterruptedAt(), engine.getInterruptedCandidateExpiresAt(), 5000);
	}

	// =====================================================================
	// Test-only hooks (package-private; same "no Mockito, drive the real
	// production object directly" convention as every other test in this
	// package).
	// =====================================================================

	/** Bypasses onEvent()'s account filter and Client-dependent gameTick
	 * tagging -- tests build already-tick-tagged SessionSignal instances
	 * directly via its public static factories + withGameTick(). */
	synchronized void testEnqueueSignal(SessionSignal signal)
	{
		pendingSignals.add(signal);
	}

	/** Test hook: a live StatChanged gain as it arrives on client tick {@code tick} (null = off-thread). */
	synchronized void testRecordLiveXp(String skillName, long delta, Long absoluteXpAfter, Long tick, Instant observedAt)
	{
		recordLiveXpDeltaAt(skillName, delta, absoluteXpAfter, tick, observedAt);
	}

	/** Drives the same closed-tick-flush-then-advance-time pipeline
	 * onGameTick() does, without requiring a real GameTick event or
	 * Client. `currentTick` plays the role of client.getTickCount() --
	 * pass a value strictly greater than any pending signal's own
	 * gameTick to make it eligible for this call to resolve. */
	void testProcessTick(long currentTick, Instant now)
	{
		processTick(currentTick, now);
	}

	/**
	 * See SessionSnapshot's
	 * own javadoc for the exact defect this replaces. The panel's ONLY
	 * read path into runtime session state: builds and returns a fully
	 * immutable, defensively-copied {@link SessionSnapshot} of whatever
	 * session is currently ACTIVE/SUSPENDED (or {@link SessionSnapshot#absent()}
	 * if none), with the copy itself happening INSIDE this synchronized
	 * method -- i.e. under the exact same monitor every runtime-mutating
	 * method in this class (onEvent()/processTick()/ensureAccountLoaded()/
	 * finalizeForClientShutdownBlocking()) already holds while mutating
	 * this same Session/its aggregates. That is what makes the copy
	 * atomic with respect to concurrent runtime mutation: no client-
	 * thread/scheduledExecutor-thread mutation can be interleaved with
	 * {@link SessionSnapshot#capture(Session)}'s field-by-field reads,
	 * because both would require this same monitor.
	 *
	 * This deliberately supersedes the earlier {@code getCurrentSession()},
	 * which handed the UI the SAME live, mutable {@link Session} object
	 * the engine keeps mutating after the synchronized call returned --
	 * a genuine data race the moment the EDT read more than one field off
	 * it (see SessionSnapshot's javadoc for the full explanation). Once
	 * this method returns, the caller holds zero references to any live
	 * mutable Session/SessionAggregates/collection this coordinator owns.
	 *
	 * @return an immutable snapshot of the current session, or
	 * {@link SessionSnapshot#absent()} if none. Never reflects a
	 * FINALIZED session (see {@link SessionLifecycleEngine#getCurrentSession()}).
	 */
	public synchronized SessionSnapshot getCurrentSessionSnapshot()
	{
		Session current = engine.getCurrentSession();
		String sessionId = current == null ? null : current.getSessionId();
		// Threads a
		// defensive copy of lastKnownAbsoluteXpBySkill through the same
		// synchronized capture call as the live-pending-XP map above --
		// see SessionSnapshot#getAbsoluteXpBySkill()'s own javadoc for why
		// this is the one extra piece of state the Current Session panel's
		// level/progress display needs and nothing else already carries.
		return SessionSnapshot.capture(
			current,
			liveXpTracker.getPendingForSession(sessionId),
			new HashMap<>(lastKnownAbsoluteXpBySkill));
	}

	/**
	 * The separate live-XP notification path raw
	 * StatChanged feeds (see SkillsCollector.onStatChanged()'s own
	 * evaluateLiveXpDelta()) -- deliberately NOT routed through
	 * EventLedger/TelemetryEventListener/SessionSignal/the classifier at
	 * all: this is purely cosmetic, in-memory, non-durable bookkeeping
	 * for the player-facing panel, never lifecycle evidence and never a
	 * second XP MetricUpdate. `skillName` is attributed to whichever
	 * session is current AT THE MOMENT this is called (see
	 * LiveXpTracker.recordDelta()'s own javadoc for the exact ownership/
	 * session-switch rule) -- silently dropped if there is no current
	 * session yet to attach it to. `delta` must already be a genuine,
	 * positive gain (SkillsCollector's own evaluateLiveXpDelta() is
	 * responsible for filtering out first-observation reseeds and any
	 * decrease/reset before ever calling this); this method also
	 * independently ignores delta &lt;= 0 as defense in depth (see
	 * LiveXpTracker.recordDelta()).
	 */
	public synchronized void recordLiveXpDelta(String skillName, long delta)
	{
		recordLiveXpDelta(skillName, delta, null);
	}

	/**
	 * As above, plus STRUCTURED ACTIVATION: when the gain is in a skill the
	 * ARMED structured activity expects, inside its location, and that
	 * activity is not already the ACTIVE current session, the gain is also
	 * queued as classification-only evidence (SignalKind#STRUCTURED_LIVE_XP)
	 * for this tick's batch, and is attached to the live display only after
	 * that batch decides which session it belongs to (see
	 * attachStructuredLiveXp()) -- so it never shows under the stale session
	 * it is about to displace. Durable XP accounting is unchanged.
	 * {@code absoluteXpAfter}: the skill's absolute XP with this gain (nullable).
	 */
	public synchronized void recordLiveXpDelta(String skillName, long delta, Long absoluteXpAfter)
	{
		recordLiveXpDeltaAt(skillName, delta, absoluteXpAfter, safeTickCount(), Instant.now());
	}

	/**
	 * {@code tick}: the client tick the gain arrived on. Activation evidence
	 * is only ever queued TICK-TAGGED (StatChanged is a client-thread event,
	 * so in practice always): an untagged signal would wait for an
	 * unconditional flush, which is exactly the delay this fixes -- so an
	 * off-thread gain simply falls back to the display-only path.
	 */
	private void recordLiveXpDeltaAt(String skillName, long delta, Long absoluteXpAfter, Long tick, Instant observedAt)
	{
		if (delta > 0 && skillName != null && tick != null && isStructuredActivationEvidence(skillName))
		{
			pendingSignals.add(SessionSignal.structuredLiveXp(observedAt, skillName, delta, absoluteXpAfter).withGameTick(tick));
			return;
		}
		Session current = engine.getCurrentSession();
		String sessionId = current == null ? null : current.getSessionId();
		liveXpTracker.recordDelta(sessionId, skillName, delta);
		if (sessionId != null && skillName != null && delta > 0)
		{
			// Visible immediately: pending XP is part of the current snapshot.
			notifyCurrentSessionChanged();
		}
	}

	private boolean isStructuredActivationEvidence(String skill)
	{
		com.osrstelemetry.plugin.activity.StructuredActivityTracker tracker = classifierContext.getStructuredActivity();
		com.osrstelemetry.plugin.activity.StructuredActivityDefinition armed = tracker.getDefinition();
		if (armed == null || tracker.getPolicy() == com.osrstelemetry.plugin.activity.LocationPolicy.NON_EXCLUSIVE
			|| !armed.isExpectedSkill(skill))
		{
			return false;
		}
		Session current = engine.getCurrentSession();
		return current == null
			|| current.getState() != SessionState.ACTIVE
			|| !current.getActivityIdentity().equals(ActivitySignalClassifier.structuredActivityIdentity(armed));
	}

	/**
	 * After a batch is resolved: every STRUCTURED_LIVE_XP gain in it joins
	 * the live display of whatever session is now current. When that is a
	 * structured session this very batch switched to, the session's exact
	 * XP boundary is moved back to before the gain, so the durable window
	 * credits it there (and the live pending is reconciled against it).
	 */
	private void attachStructuredLiveXp(List<SessionSignal> batch, Session preBatchCurrent)
	{
		Session current = engine.getCurrentSession();
		if (current == null)
		{
			return;
		}
		boolean switchedThisBatch = preBatchCurrent == null || !preBatchCurrent.getSessionId().equals(current.getSessionId());
		boolean structuredCurrent = current.getActivityIdentity().getActivityType() == ActivityType.STRUCTURED_ACTIVITY;
		boolean attached = false;
		for (SessionSignal signal : batch)
		{
			if (signal.getKind() != SignalKind.STRUCTURED_LIVE_XP || signal.getXpDelta() == null)
			{
				continue;
			}
			if (switchedThisBatch && structuredCurrent && signal.getXpNewValue() != null)
			{
				classifierContext.lowerXpAtSessionStart(current.getSessionId(), signal.getSkill(), signal.getXpNewValue() - signal.getXpDelta());
			}
			liveXpTracker.recordDelta(current.getSessionId(), signal.getSkill(), signal.getXpDelta());
			attached = true;
		}
		if (attached)
		{
			visibleMutations++;
		}
	}

	// =====================================================================
	// PRESENTATION INVALIDATION (UI latency pass). Downstream, best effort:
	// a listener only learns "the visible current session changed" and
	// decides itself when to redraw. Nothing here depends on a listener
	// existing or succeeding -- telemetry/session correctness never does.
	// =====================================================================

	private volatile Runnable currentSessionListener;

	/**
	 * Counts accepted mutations of the CURRENT session's visible aggregates
	 * (metrics, Slayer assignment ledger); together with the session's
	 * id/state/identity it forms {@link #visibleStamp()}, so a processed
	 * batch that changed nothing a player can see (e.g. rejected off-task
	 * loot) never notifies.
	 */
	private long visibleMutations;

	/** Called (on whichever thread mutated state) when the visible current session changed. */
	public void setCurrentSessionListener(Runnable listener)
	{
		this.currentSessionListener = listener;
	}

	/** Best-effort notification that a finalized session file reached disk (History). */
	public void setFinalizedSessionListener(Runnable listener)
	{
		persistence.setFinalizedWriteListener(listener);
	}

	private String visibleStamp()
	{
		Session current = engine.getCurrentSession();
		return current == null
			? "none|" + currentAccountHash
			: current.getSessionId() + '|' + current.getState() + '|' + current.getActivityIdentity() + '|' + visibleMutations;
	}

	private void notifyCurrentSessionChanged()
	{
		Runnable listener = currentSessionListener;
		if (listener == null)
		{
			return;
		}
		try
		{
			listener.run();
		}
		catch (RuntimeException e)
		{
			log.debug("current-session listener failed; session state is unaffected", e);
		}
	}

	/**
	 * Called by SkillsCollector.onStatChanged() for EVERY
	 * skill on every raw StatChanged observation -- deliberately
	 * UNCONDITIONALLY, unlike recordLiveXpDelta() above (which is gated
	 * on a positive live delta): this is not a display concern, it is
	 * "the latest known absolute XP for this skill, full stop," and even
	 * a skill's very first (seed-only, zero-delta) observation is a
	 * genuine, exact absolute baseline worth keeping. See
	 * lastKnownAbsoluteXpBySkill's own javadoc for how this feeds the
	 * exact session-boundary split; a no-op for a null skill name.
	 */
	public synchronized void noteAbsoluteXp(String skillName, long absoluteXp)
	{
		if (skillName == null)
		{
			return;
		}
		lastKnownAbsoluteXpBySkill.put(skillName, absoluteXp);
	}

	/**
	 * The single backend hook
	 * behind the Current Session header's "Re-evaluate Session" button --
	 * "look at what I am doing RIGHT NOW and classify it again," never
	 * "forget all session rules." Called from CurrentSessionView's button
	 * handler via a non-blocking ClientThread.invokeLater() dispatch (see
	 * OsrsTelemetryPanel's own wiring) -- never directly on the EDT.
	 *
	 * EVIDENCE SOURCE: `currentNpcName`/`currentNpcId` are expected to be
	 * read by the caller, on the calling thread, from
	 * NpcInteractionTargetCollector.getCurrentNpcName()/getCurrentNpcId()
	 * immediately before this call (that collector's own javadoc documents
	 * both as safe off the client thread) -- the genuine, live, right-now
	 * interaction target, never a replayed/stale signal. `now` is expected
	 * to be Instant.now() at the same moment.
	 *
	 * INSUFFICIENT EVIDENCE -&gt; SAFE NO-OP: no current attackable NPC
	 * target at all (`currentNpcName` null/blank), or no account loaded
	 * yet, leaves the current session (if any) completely untouched -- no
	 * identity is ever invented or guessed. Likewise, whenever
	 * ActivitySignalClassifier.classifyManualNpcTarget() itself determines
	 * this observation makes no safe identity claim right now (its own
	 * METRIC_ONLY carve-out for generic combat evidence against a
	 * SUSPENDED specific session -- see decideCombatBranch()'s own
	 * javadoc), this is honored exactly like the ordinary pipeline does:
	 * no lifecycle mutation.
	 *
	 * REUSES EXISTING RULES, NEVER A COMPETING CLASSIFIER: identity
	 * construction and the refine-vs-switch-vs-ignore decision are both
	 * delegated entirely to ActivitySignalClassifier.classifyManualNpcTarget()
	 * (see its own javadoc) -- this method only threads the result through
	 * SessionLifecycleEngine exactly the way resolveAndApplyBatches() does
	 * for an ordinary RESOLVED batch (same applyMetrics()/
	 * flushAbandonedBossTaskCandidateIfMatching()/persistence calls). The
	 * ONLY thing manual about this call is EvidenceStrength.SPECIFIC,
	 * which is what lets it bypass SessionLifecycleEngine's ORDINARY-only
	 * weak-evidence candidate/stickiness gate for this one observation
	 * (see EvidenceStrength's own javadoc) -- every other safety rule
	 * (never fabricate SLAYER from bare task assignment; never downgrade a
	 * more-specific ACTIVE session via generic evidence; Slayer
	 * task-family membership; boss/task affinity) remains fully enforced,
	 * completely unchanged. Using SPECIFIC strength also means any
	 * still-pending weak-evidence candidate (stale candidate-activity
	 * state) is unconditionally ABANDONED by this call exactly as any
	 * other authoritative/specific arrival would abandon it -- its
	 * buffered metrics are safely, honestly committed once as contextual
	 * metrics to whichever session they actually occurred during (see
	 * SessionLifecycleEngine's own "AUTHORITATIVE/SPECIFIC evidence ...
	 * immediate switch" branches), never lost and never duplicated. This
	 * call also unconditionally refreshes the recent-NPC-target watch (see
	 * ClassifierContext.onNpcInteractionTarget()) to this exact
	 * observation, clearing any staleness there too.
	 *
	 * NEVER REWRITES HISTORY: this call always carries an EMPTY metrics
	 * list -- it can start/refine/switch session IDENTITY, but can never
	 * itself add a single point of XP/loot to any session's aggregates.
	 * Combined with SessionLifecycleEngine's own transition rules (a real
	 * switch finalizes the OLD session exactly as it stood and starts a
	 * brand-new one from `now` forward; an already-FINALIZED session is
	 * never touched by any later call), this can only ever affect the
	 * session current AT `now`, going forward -- never earlier XP, loot,
	 * duration, or an already-finalized record.
	 */
	public synchronized void reEvaluateCurrentSession(String currentNpcName, Integer currentNpcId, Instant now)
	{
		String before = visibleStamp();
		reEvaluateCurrentSessionCore(currentNpcName, currentNpcId, beforePendingSignals(now));
		if (!before.equals(visibleStamp()))
		{
			notifyCurrentSessionChanged();
		}
	}

	private void reEvaluateCurrentSessionCore(String currentNpcName, Integer currentNpcId, Instant now)
	{
		if (currentAccountHash == NO_ACCOUNT)
		{
			return;
		}
		if (currentNpcName == null || currentNpcName.trim().isEmpty())
		{
			// No current live combat-target evidence -- never invent an
			// activity. Safe no-op.
			return;
		}

		Session before = engine.getCurrentSession();
		SignalClassification classification = classifier.classifyManualNpcTarget(currentNpcName, before, EvidenceStrength.SPECIFIC);

		if (classification.getDecisionKind() != SignalDecisionKind.START_OR_HEARTBEAT
			&& classification.getDecisionKind() != SignalDecisionKind.REFINE)
		{
			// e.g. METRIC_ONLY (generic combat evidence against a
			// SUSPENDED specific session) -- no safe identity claim right
			// now. Honor that exactly like the ordinary pipeline does:
			// nothing invented, nothing mutated. This call never carries
			// metrics of its own, so there is nothing to apply here even
			// for METRIC_ONLY.
			return;
		}

		SessionState beforeState = before == null ? null : before.getState();
		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A):
		// allowInterruptedResume=false -- a manual identity correction
		// must never manufacture a hidden resumable prior session/History
		// entry (see onQualifyingActivity()'s 5-arg overload javadoc).
		// This preserves this method's own pre-existing, unchanged
		// corrective semantics byte-for-byte: a real switch here still
		// finalizes the old session immediately, exactly as it always
		// has.
		LifecycleResult result = classification.getDecisionKind() == SignalDecisionKind.REFINE
			? engine.refineIdentity(classification.getIdentity(), now, Collections.<MetricUpdate>emptyList())
			: engine.onQualifyingActivity(classification.getIdentity(), now, Collections.<MetricUpdate>emptyList(), classification.getEvidenceStrength(), false);

		if (result.getCurrent() != null
			&& (before == null || !before.getSessionId().equals(result.getCurrent().getSessionId())))
		{
			classifierContext.noteSessionSwitchXpBaseline(result.getCurrent().getSessionId(), lastKnownAbsoluteXpBySkill);
		}

		// Same metric-routing discipline as resolveAndApplyBatches()'s own
		// RESOLVED branch: metricsForCurrent is always empty for this call
		// (see method javadoc's NEVER REWRITES HISTORY section), but an
		// abandoned candidate's own previously-buffered, real metrics
		// (contextualMetricsTarget/contextualMetrics) must still be
		// committed exactly once, never dropped.
		applyMetrics(result.getCurrent(), result.getMetricsForCurrent());
		if (result.getContextualMetricsTarget() != null)
		{
			applyMetrics(result.getContextualMetricsTarget(), result.getContextualMetrics());
		}

		if (result.getFinalized() != null)
		{
			flushAbandonedBossTaskCandidateIfMatching(result.getFinalized());
			persistence.persistFinalized(currentAccountHash, result.getFinalized(), result.getCurrent());
		}
		else if (result.getCurrent() != null && result.getCurrent().getState() != beforeState)
		{
			persistence.persistCurrent(currentAccountHash, result.getCurrent());
		}

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): even with
		// allowInterruptedResume=false above, the background candidate-
		// expiry housekeeping every timestamped entry point performs is
		// NOT gated by that flag (see expireInterruptedCandidateIfNeeded()'s
		// own javadoc) -- an already-parked, already-decided candidate can
		// still legitimately expire exactly during a manual re-evaluate
		// call, and must not be dropped.
		if (result.getAdditionalFinalized() != null)
		{
			persistence.persistAdditionalFinalized(currentAccountHash, result.getAdditionalFinalized());
			persistence.clearInterruptedCandidate(currentAccountHash);
		}

		classifierContext.onNpcInteractionTarget(currentNpcId, currentNpcName, safeTickCount(), now);
	}

	synchronized Session testCurrentSession()
	{
		return engine.getCurrentSession();
	}

	synchronized Session testInterruptedCandidate()
	{
		return engine.getInterruptedCandidate();
	}

	synchronized long testPendingSignalCount()
	{
		return pendingSignals.size();
	}
}

package com.osrstelemetry.plugin.session;

import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * A small, immutable, typed input model for ActivitySignalClassifier --
 * deliberately NOT a raw RuneLite EventBus class and NOT an untyped
 * Map<String,Object>. A future RuneLite router is responsible for
 * translating real events into these pure signals; this class only
 * defines the shape, the classifier that consumes it, and the pure
 * batch resolver (SessionSignalBatchResolver) that groups and resolves
 * a tick's worth of them.
 *
 * GAME TICK: observedAt remains the historical wall-clock
 * timestamp used by lifecycle/persistence (unchanged meaning). gameTick
 * is a SEPARATE, OPTIONAL field representing RuneLite's own tick
 * counter (conceptually `client.getTickCount()`), because several real
 * events belonging to one game action/tick can be observed at slightly
 * different wall-clock Instants -- exact Instant equality is no longer
 * assumed to be a reliable batch key (see SessionSignalBatchResolver).
 * This class never imports net.runelite.api.Client or any RuneLite
 * event class -- the future thin router is what will call
 * withGameTick(client.getTickCount()) when constructing a signal; pure
 * tests can supply arbitrary tick values directly. gameTick is null
 * for any signal that was never tagged with one, in which case the
 * batch resolver falls back to exact observedAt equality as its key.
 *
 * SLAYER CURRENT REMAINING: a SEPARATE,
 * OPTIONAL field on SLAYER_TASK_PROGRESS signals ONLY, carrying
 * EventPayloads.SlayerTaskProgress's own authoritative currentRemaining
 * for THIS one observed event -- never previousRemaining/initialAmount,
 * and never re-derived from slayerUnitsConsumed. Deliberately additive:
 * the original 4-arg slayerTaskProgress() factory below still exists
 * and now simply delegates with a null currentRemaining, so every
 * existing caller/test is completely unaffected. Nullable because older
 * or synthetic callers may not have this value; consumers must never
 * invent one when absent (see SessionAggregateUpdater/SessionSnapshot/
 * CurrentSessionSnapshot's own javadoc for how "latest observed value,
 * or nothing displayed" is honored end to end).
 *
 * Every field beyond kind/observedAt is nullable -- only the fields
 * relevant to a given SignalKind are ever populated (see the static
 * factory methods below, one per kind, which is the only supported way
 * to construct an instance so an impossible combination, e.g. a
 * BOSS_KILL signal with a slayerTaskName, can never be built).
 */
public final class SessionSignal
{
	private final SignalKind kind;
	private final Instant observedAt;

	private final String skill;
	private final Long xpDelta;

	/**
	 * The XP_CHANGE aggregation window's own START --
	 * i.e. when SkillsCollector actually BEGAN accumulating this delta
	 * (EventPayloads.XpChange#getWindowStart(), previously discarded
	 * entirely by SessionEventMapper) -- deliberately DIFFERENT from
	 * getObservedAt() above, which for XP_CHANGE is the FLUSH/processing
	 * time (when the ~30s-aggregated window finally closed), not when
	 * the underlying XP was actually earned. A real session switch can
	 * happen strictly BETWEEN this window's own start and its eventual
	 * flush -- see classifyXpChange()'s own ownership-guard javadoc for
	 * exactly how this is used to keep a delayed XP_CHANGE from ever
	 * being credited to a session that did not even exist yet when the
	 * XP was earned. Null for every signal built via the legacy 3-arg
	 * xpChange() factory (every other existing caller/test) -- the
	 * ownership guard is a no-op whenever this is null, so nothing about
	 * this field is required for any signal kind/caller that does not
	 * opt into it.
	 */
	private final Instant xpWindowStart;

	/**
	 * This XP_CHANGE window's own ABSOLUTE new XP value at
	 * the moment it closed (EventPayloads.XpChange#getNewXp(), previously
	 * discarded entirely, exactly like xpWindowStart used to be) --
	 * DELIBERATELY an absolute skill total, never a delta. Together with
	 * ClassifierContext's own per-session "XP at session start" baseline
	 * (see ClassifierContext.noteSessionSwitchXpBaseline()), this is what
	 * lets classifyXpChange() EXACTLY separate a window that SPANS a
	 * session switch into its pre-switch and post-switch portions,
	 * without ever guessing a proportional time-based split (see
	 * classifyXpChange()'s own javadoc for the full boundary-ownership
	 * rule this enables). Null for every signal built via the 3-arg or
	 * 4-arg xpChange() overloads (every pre-existing caller/test) -- the
	 * boundary-split logic simply cannot attempt an exact split without
	 * it and falls back to the conservative whole-window ignore, so
	 * nothing about this field is required for any caller that does not
	 * opt into it.
	 */
	private final Long xpNewValue;

	private final String slayerTaskName;
	private final String slayerTaskLocation;
	private final Integer slayerUnitsConsumed;
	private final Integer slayerInitialAmount;
	private final Integer slayerCurrentRemaining;

	private final String bossOrActivitySource;
	private final Integer reliableCount;

	private final List<LootDrop> lootDrops;

	private final Long gameTick;

	// See SignalKind.NPC_INTERACTION_TARGET's own javadoc. Both nullable --
	// populated only for that one kind; every other kind leaves them
	// null, exactly like every other kind-specific field on this class.
	private final Integer npcId;
	private final String npcName;

	/** Structured-activity key for the STRUCTURED_* kinds (null = outside, for a location signal). */
	private final String structuredActivityKey;
	/** Template region id of a STRUCTURED_ACTIVITY_LOCATION signal. */
	private final Integer regionId;
	/**
	 * SLAYER_TASK_COMPLETED only: the task was cleared WITHOUT being
	 * finished (cancelled/blocked for points) -- see
	 * EventPayloads.SlayerTaskCompleted#cancelled. False otherwise.
	 */
	private final boolean slayerTaskCancelled;
	/**
	 * STRUCTURED_ACTIVITY_SCORE: the game's final score (null = unknown).
	 * STRUCTURED_ACTIVITY_CURRENCY: the positive amount gained.
	 */
	private final Long activityAmount;
	/** STRUCTURED_ACTIVITY_SCORE only: the game was observed from its start (see TemporossGameTracker). */
	private final boolean activityAmountTrusted;

	private SessionSignal(
		SignalKind kind,
		Instant observedAt,
		String skill,
		Long xpDelta,
		String slayerTaskName,
		String slayerTaskLocation,
		Integer slayerUnitsConsumed,
		Integer slayerInitialAmount,
		String bossOrActivitySource,
		Integer reliableCount,
		List<LootDrop> lootDrops,
		Long gameTick,
		Integer slayerCurrentRemaining,
		Integer npcId,
		String npcName,
		Instant xpWindowStart,
		Long xpNewValue,
		String structuredActivityKey,
		Integer regionId)
	{
		this(kind, observedAt, skill, xpDelta, slayerTaskName, slayerTaskLocation, slayerUnitsConsumed, slayerInitialAmount,
			bossOrActivitySource, reliableCount, lootDrops, gameTick, slayerCurrentRemaining, npcId, npcName, xpWindowStart,
			xpNewValue, structuredActivityKey, regionId, false, null, false);
	}

	private SessionSignal(
		SignalKind kind,
		Instant observedAt,
		String skill,
		Long xpDelta,
		String slayerTaskName,
		String slayerTaskLocation,
		Integer slayerUnitsConsumed,
		Integer slayerInitialAmount,
		String bossOrActivitySource,
		Integer reliableCount,
		List<LootDrop> lootDrops,
		Long gameTick,
		Integer slayerCurrentRemaining,
		Integer npcId,
		String npcName,
		Instant xpWindowStart,
		Long xpNewValue,
		String structuredActivityKey,
		Integer regionId,
		boolean slayerTaskCancelled,
		Long activityAmount,
		boolean activityAmountTrusted)
	{
		this.kind = Objects.requireNonNull(kind, "kind");
		this.observedAt = Objects.requireNonNull(observedAt, "observedAt");
		this.skill = skill;
		this.xpDelta = xpDelta;
		this.slayerTaskName = slayerTaskName;
		this.slayerTaskLocation = slayerTaskLocation;
		this.slayerUnitsConsumed = slayerUnitsConsumed;
		this.slayerInitialAmount = slayerInitialAmount;
		this.bossOrActivitySource = bossOrActivitySource;
		this.reliableCount = reliableCount;
		this.lootDrops = lootDrops == null ? null : Collections.unmodifiableList(lootDrops);
		this.gameTick = gameTick;
		this.slayerCurrentRemaining = slayerCurrentRemaining;
		this.npcId = npcId;
		this.npcName = npcName;
		this.xpWindowStart = xpWindowStart;
		this.xpNewValue = xpNewValue;
		this.structuredActivityKey = structuredActivityKey;
		this.regionId = regionId;
		this.slayerTaskCancelled = slayerTaskCancelled;
		this.activityAmount = activityAmount;
		this.activityAmountTrusted = activityAmountTrusted;
	}

