		FAMILY_MEMBERS_NORMALIZED = Collections.unmodifiableMap(table);
	}

	/**
	 * Registers `taskName` with the union of its explicit `aliases` and
	 * its own singular form (trailing "s" stripped) -- see class javadoc
	 * ALGORITHM section. Both are always combined, exactly mirroring
	 * RuneLite's own `SlayerPlugin.rebuildTargetNames()`.
	 */
	private static void register(Map<String, Set<String>> table, String taskName, String... aliases)
	{
		String normalizedTask = normalize(taskName);
		Set<String> members = new HashSet<>();
		members.add(singularize(normalizedTask));
		for (String alias : aliases)
		{
			members.add(normalize(alias));
		}
		table.put(normalizedTask, Collections.unmodifiableSet(members));
	}

	/**
	 * @return true if `npcName` is a legitimate member of the NPC family
	 * `taskName` covers -- either an explicitly known alternative/
	 * superior/boss-form NPC (from the catalogued table above) or the
	 * task's own singular form. Never true for an NPC merely
	 * "similar-looking" to the task name; every comparison is an exact,
	 * normalized string match. False for a null taskName/npcName.
	 */
	static boolean belongsToTaskFamily(String taskName, String npcName)
	{
		if (taskName == null || npcName == null)
		{
			return false;
		}
		String normalizedNpc = normalize(npcName);
		String normalizedTask = normalize(taskName);
		Set<String> members = FAMILY_MEMBERS_NORMALIZED.get(normalizedTask);
		if (members != null)
		{
			return members.contains(normalizedNpc);
		}
		// UNCATALOGUED task (not in the table above -- see class javadoc's
		// "known coverage gaps" note, and the classifier report's own
		// coverage-gaps section). No explicit alias list exists to pair
		// with a singular-suffix strip, so -- and ONLY here, never for a
		// catalogued task -- that one fixed, deterministic transform
		// (identical to RuneLite's own unconditional
		// `taskName.replaceAll("s$", "")`) is applied alone. This is
		// still not fuzzy matching: it is one exact string comparison
		// against one exact, fixed transform of the task name, never an
		// approximate or scored match.
		return normalizedNpc.equals(singularize(normalizedTask));
	}

	private static String singularize(String normalizedTaskName)
	{
		return normalizedTaskName.endsWith("s")
			? normalizedTaskName.substring(0, normalizedTaskName.length() - 1)
			: normalizedTaskName;
	}

	/** See {@link #lootSourceCompatibility}. */
	enum LootSourceCompatibility
	{
		MATCH,
		KNOWN_MISMATCH,
		UNKNOWN
	}

	/**
	 * OFF-TASK LOOT ATTRIBUTION: is a SERVER_NPC_LOOT source NPC (its
	 * authoritative sourceName) compatible with Slayer task `taskName`?
	 *
	 * MATCH: RuneLite's own Slayer-target semantics -- the source name
	 * CONTAINS one of the task's target names in this table (so "Undead
	 * chicken" matches Zombies' "undead", "Kalphite Worker" matches
	 * "kalphite", listed superiors/variants match), or the source is a
	 * boss confirmed to consume this task (BossTaskAffinity).
	 *
	 * KNOWN_MISMATCH: the source is positively identified as ANOTHER
	 * task's Slayer target (it contains, as a whole word, a target name
	 * of some other catalogued task) and does not match this one -- e.g.
	 * an Undead chicken (Zombies/Birds) on a Turoth task.
	 *
	 * UNKNOWN: anything this table cannot prove is off task -- no source
	 * name or task, or a source that is no catalogued task's target (a
	 * summoned/subordinate NPC such as a Nechryael's Death Spawn, or an
	 * NPC no Slayer task covers). Callers keep the existing behavior for
	 * UNKNOWN: a false rejection would silently drop legitimate loot.
	 */
	static LootSourceCompatibility lootSourceCompatibility(String taskName, String sourceName)
	{
		if (taskName == null || sourceName == null || sourceName.trim().isEmpty())
		{
			return LootSourceCompatibility.UNKNOWN;
		}
		String task = normalize(taskName);
		String source = normalize(sourceName);
		Set<String> members = FAMILY_MEMBERS_NORMALIZED.get(task);
		if (source.contains(singularize(task)))
		{
			return LootSourceCompatibility.MATCH;
		}
		if (members != null)
		{
			for (String member : members)
			{
				if (!member.isEmpty() && source.contains(member))
				{
					return LootSourceCompatibility.MATCH;
				}
			}
		}
		if (BossTaskAffinity.isBossOwnTask(source, taskName))
		{
			return LootSourceCompatibility.MATCH;
		}
		for (Map.Entry<String, Set<String>> other : FAMILY_MEMBERS_NORMALIZED.entrySet())
		{
			if (other.getKey().equals(task))
			{
				continue;
			}
			for (String member : other.getValue())
			{
				if (containsWord(source, member))
				{
					return LootSourceCompatibility.KNOWN_MISMATCH;
				}
			}
		}
		return LootSourceCompatibility.UNKNOWN;
	}

	/** `phrase` appears in `text` bounded by start/end or a non-letter on both sides. */
	private static boolean containsWord(String text, String phrase)
	{
		if (phrase.isEmpty())
		{
			return false;
		}
		int from = 0;
		while (true)
		{
			int i = text.indexOf(phrase, from);
			if (i < 0)
			{
				return false;
			}
			int end = i + phrase.length();
			boolean startOk = i == 0 || !Character.isLetter(text.charAt(i - 1));
			boolean endOk = end == text.length() || !Character.isLetter(text.charAt(end));
			if (startOk && endOk)
			{
				return true;
			}
			from = i + 1;
		}
	}

	private static String normalize(String s)
	{
		return s.trim().toLowerCase(Locale.ROOT);
	}
}

package com.osrstelemetry.plugin.session;

import com.osrstelemetry.plugin.activity.LocationPolicy;
import com.osrstelemetry.plugin.activity.RecognitionState;
import com.osrstelemetry.plugin.activity.StructuredActivityDefinition;
import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.activity.StructuredActivityTracker;
import com.osrstelemetry.plugin.activity.StructuredRewardSource;
import java.util.Collections;
import java.util.List;

/**
 * Generic structured-activity layer in front of ActivitySignalClassifier.
 * It only turns signals into ordinary SignalClassifications -- the existing
 * SessionLifecycleEngine still owns start / resume / suspend / interrupted
 * recovery / finalize / active duration. No activity is named here: every
 * activity-specific fact comes from its StructuredActivityDefinition.
 *
 * Returns null whenever a signal is not structured-activity business, so
 * the ordinary classifier decides exactly as before.
 *
 * Rules (see StructuredActivityTracker for ARMED/ACTIVE/LOCKED):
 *  - Location signals only arm/disarm. Never a session, never a confirmation.
 *  - In an armed location, compatible evidence (expected-skill XP outside a
 *    NON_EXCLUSIVE region, a subordinate boss kill, a completion, a declared
 *    reward) confirms the activity and is SPECIFIC START_OR_HEARTBEAT for the
 *    activity's identity -- the engine switches to / heartbeats it at once.
 *  - While the session IS the activity and the player is in its location,
 *    unexpected XP is incidental (metric-only) under EXCLUSIVE, or under
 *    STRONG_CONTEXT once LOCKED; a Slayer task's progress never steals it;
 *    subordinate boss context never switches it.
 *  - Outside the location nothing is reinforced: ordinary rules apply, so
 *    other activities take over through the normal evidence gate. Only the
 *    activity's own completions/rewards still land (metric-only) on its
 *    own session; they never land on any other session.
 */
final class StructuredActivityClassifier
{
	private final StructuredActivityRegistry registry;

	StructuredActivityClassifier(StructuredActivityRegistry registry)
	{
		this.registry = registry;
	}

	SignalClassification classify(SessionSignal signal, Session current, ClassifierContext context)
	{
		StructuredActivityTracker tracker = context.getStructuredActivity();
		if (signal.getKind() == SignalKind.STRUCTURED_ACTIVITY_LOCATION)
		{
			StructuredActivityDefinition def = registry.byKey(signal.getStructuredActivityKey());
			LocationPolicy policy = def == null || signal.getRegionId() == null ? null : def.policyFor(signal.getRegionId());
			tracker.onLocation(policy == null ? null : def, policy);
			return SignalClassification.ignore();
		}

		StructuredActivityDefinition armed = tracker.getDefinition();
		StructuredActivityDefinition owning = owningDefinition(current);
		if (armed == null && owning == null)
		{
			return null;
		}
		boolean inOwnActivity = armed != null && owning != null && armed.getKey().equals(owning.getKey());

		switch (signal.getKind())
		{
			case XP_CHANGE:
				return classifyXp(signal, current, tracker, armed, inOwnActivity);
			case STRUCTURED_LIVE_XP:
				return classifyLiveXp(signal, tracker, armed);
			case RAW_COMBAT_XP_OBSERVED:
				// The XP_CHANGE that follows carries the evidence; never let the
				// early per-NPC combat heuristic open a competing session.
				return armed != null && tracker.getPolicy() != LocationPolicy.NON_EXCLUSIVE && armed.isExpectedSkill(signal.getSkill())
					? SignalClassification.ignore()
					: null;
			case BOSS_KILL:
				return classifyBossKill(signal, tracker, armed, owning);
			case BOSS_ACTIVITY_CONTEXT:
				return armed != null && armed.isSubordinate(signal.getBossOrActivitySource()) ? SignalClassification.ignore() : null;
			case ACTIVITY_COMPLETION:
				return classifyNamedCompletion(signal, tracker, armed, owning);
			case STRUCTURED_ACTIVITY_COMPLETION:
				return classifyKeyedCompletion(signal, tracker, armed, owning);
			case STRUCTURED_REWARD:
				return classifyReward(signal, tracker, armed, owning);
			case STRUCTURED_ACTIVITY_SCORE:
			case STRUCTURED_ACTIVITY_CURRENCY:
			case STRUCTURED_ACTIVITY_PRODUCTION:
				return classifyStats(signal, owning);
			case SLAYER_TASK_PROGRESS:
				if (inOwnActivity && tracker.getState() != RecognitionState.ARMED)
				{
					// Keep the task state current, but a task never steals an
					// established structured activity.
					context.onSlayerTaskProgress(signal.getSlayerTaskName(), signal.getSlayerTaskLocation(), signal.getSlayerCurrentRemaining());
					return SignalClassification.ignore();
				}
				return null;
			case SERVER_NPC_LOOT:
				if (inOwnActivity && tracker.getState() != RecognitionState.ARMED
					&& signal.getLootDrops() != null && !signal.getLootDrops().isEmpty())
				{
					return SignalClassification.metricOnly(MetricUpdate.loot(signal.getBossOrActivitySource(), signal.getObservedAt(), signal.getLootDrops()));
				}
				return null;
			default:
				return null;
		}
	}

	private SignalClassification classifyXp(SessionSignal signal, Session current, StructuredActivityTracker tracker,
		StructuredActivityDefinition armed, boolean inOwnActivity)
	{
		if (armed == null || ActivitySignalClassifier.spansSessionStart(signal, current))
		{
			return null;
		}
		MetricUpdate metric = ActivitySignalClassifier.xpMetric(signal);
		LocationPolicy policy = tracker.getPolicy();
		if (policy != LocationPolicy.NON_EXCLUSIVE && armed.isExpectedSkill(signal.getSkill()))
		{
			return evidence(armed, tracker, signal, Collections.singletonList(metric));
		}
		if (inOwnActivity && absorbsIncidentalXp(policy, tracker.getState()))
		{
			return SignalClassification.metricOnly(metric);
		}
		return null;
	}

	/**
	 * LIVE XP (classification only, no metric): an expected-skill gain in
	 * the armed location makes the activity current right away. It
	 * activates recognition (ARMED -&gt; ACTIVE) but never advances it
	 * further: locking still needs the same durable-window / completion
	 * evidence as before, so incidental-XP absorption is unchanged.
	 */
	private SignalClassification classifyLiveXp(SessionSignal signal, StructuredActivityTracker tracker, StructuredActivityDefinition armed)
	{
		if (armed == null || tracker.getPolicy() == LocationPolicy.NON_EXCLUSIVE || !armed.isExpectedSkill(signal.getSkill()))
		{
			return SignalClassification.ignore();
		}
		if (tracker.getState() == RecognitionState.ARMED)
		{
			tracker.confirm(tickKey(signal));
		}
		return SignalClassification.startOrHeartbeat(ActivitySignalClassifier.structuredActivityIdentity(armed),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
	}

	private SignalClassification classifyBossKill(SessionSignal signal, StructuredActivityTracker tracker,
		StructuredActivityDefinition armed, StructuredActivityDefinition owning)
	{
		String boss = signal.getBossOrActivitySource();
		if (armed != null && armed.isCompletionBoss(boss))
		{
			return completion(armed, tracker, signal, signal.getReliableCount());
		}
		if (armed != null && armed.isSubordinate(boss))
		{
			return evidence(armed, tracker, signal, Collections.<MetricUpdate>emptyList());
		}
		if (armed == null && owning != null && owning.isCompletionBoss(boss))
		{
			return completionMetricOnly(owning, signal.getReliableCount());
		}
		return null;
	}

	private SignalClassification classifyNamedCompletion(SessionSignal signal, StructuredActivityTracker tracker,
		StructuredActivityDefinition armed, StructuredActivityDefinition owning)
	{
		String name = signal.getBossOrActivitySource();
		if (armed != null && armed.isCompletionCount(name))
		{
			return completion(armed, tracker, signal, signal.getReliableCount());
		}
		if (owning != null && owning.isCompletionCount(name))
		{
			return completionMetricOnly(owning, signal.getReliableCount());
		}
		return null;
	}

	private SignalClassification classifyKeyedCompletion(SessionSignal signal, StructuredActivityTracker tracker,
		StructuredActivityDefinition armed, StructuredActivityDefinition owning)
	{
		String key = signal.getStructuredActivityKey();
		if (armed != null && armed.getKey().equals(key))
		{
			return completion(armed, tracker, signal, signal.getReliableCount());
		}
		if (owning != null && owning.getKey().equals(key))
		{
			return completionMetricOnly(owning, signal.getReliableCount());
		}
		// Not this location's activity and not the session's: never fabricate.
		return SignalClassification.ignore();
	}

	private SignalClassification classifyReward(SessionSignal signal, StructuredActivityTracker tracker,
		StructuredActivityDefinition armed, StructuredActivityDefinition owning)
	{
		// Ownership follows the reward SOURCE: only a declared source of the
		// matching activity can be owned -- an unknown or mismatched source is
		// never credited just because some structured session is active.
		StructuredRewardSource source = registry.rewardSource(signal.getBossOrActivitySource());
		if (source == null || !source.getActivityKey().equals(signal.getStructuredActivityKey())
			|| signal.getLootDrops() == null || signal.getLootDrops().isEmpty())
		{
			return SignalClassification.ignore();
		}
		String key = source.getActivityKey();
		MetricUpdate loot = MetricUpdate.loot(source.getDisplayName(), signal.getObservedAt(), signal.getLootDrops());
		boolean armedMatches = armed != null && armed.getKey().equals(key);
		if (owning != null && owning.getKey().equals(key))
		{
			return armedMatches
				? evidence(armed, tracker, signal, Collections.singletonList(loot))
				: SignalClassification.metricOnly(loot);
		}
		if (armedMatches && tracker.getPolicy() != LocationPolicy.NON_EXCLUSIVE)
		{
			return evidence(armed, tracker, signal, Collections.singletonList(loot));
		}
		// A reward for an activity that is not the current session never
		// lands anywhere else (in particular never in a parked Slayer session).
		return SignalClassification.ignore();
	}

	/**
	 * Session-summary stats land ONLY on the activity's own (non-finalized)
	 * session -- never evidence, never a new session, never another
	 * session's metric (SessionRuntimeCoordinator re-checks the target).
	 */
	private static SignalClassification classifyStats(SessionSignal signal, StructuredActivityDefinition owning)
	{
		String key = signal.getStructuredActivityKey();
		if (owning == null || key == null || !owning.getKey().equals(key))
		{
			return SignalClassification.ignore();
		}
		if (signal.getKind() == SignalKind.STRUCTURED_ACTIVITY_PRODUCTION)
		{
			List<SessionSignal.LootDrop> produced = signal.getProducedItems();
			return produced == null || produced.isEmpty()
				? SignalClassification.ignore()
				: SignalClassification.metricOnly(MetricUpdate.activityProduction(key, produced));
		}
		Long amount = signal.getActivityAmount();
		if (signal.getKind() == SignalKind.STRUCTURED_ACTIVITY_CURRENCY)
		{
			return amount == null || amount <= 0
				? SignalClassification.ignore()
				: SignalClassification.metricOnly(MetricUpdate.activityCurrency(key, signal.getActivityCurrencyKey(), amount));
		}
		Integer score = amount == null ? null : (int) Math.min(Integer.MAX_VALUE, amount);
		return SignalClassification.metricOnly(
			MetricUpdate.activityScore(key, signal.getReliableCount(), score, signal.isActivityAmountTrusted()));
	}

	private SignalClassification completion(StructuredActivityDefinition def, StructuredActivityTracker tracker,
		SessionSignal signal, Integer authoritativeCount)
	{
		List<MetricUpdate> metrics = def.hasCompletionSource()
			? Collections.singletonList(MetricUpdate.activityCompletion(def.getKey(), authoritativeCount))
			: Collections.<MetricUpdate>emptyList();
		return evidence(def, tracker, signal, metrics);
	}

	private static SignalClassification completionMetricOnly(StructuredActivityDefinition def, Integer authoritativeCount)
	{
		return def.hasCompletionSource()
			? SignalClassification.metricOnly(MetricUpdate.activityCompletion(def.getKey(), authoritativeCount))
			: SignalClassification.ignore();
	}

	private static SignalClassification evidence(StructuredActivityDefinition def, StructuredActivityTracker tracker,
		SessionSignal signal, List<MetricUpdate> metrics)
	{
		tracker.confirm(tickKey(signal));
		return SignalClassification.startOrHeartbeat(ActivitySignalClassifier.structuredActivityIdentity(def), metrics, EvidenceStrength.SPECIFIC);
	}

	private static boolean absorbsIncidentalXp(LocationPolicy policy, RecognitionState state)
	{
		return policy == LocationPolicy.EXCLUSIVE
			|| (policy == LocationPolicy.STRONG_CONTEXT && state == RecognitionState.LOCKED);
	}

	private StructuredActivityDefinition owningDefinition(Session current)
	{
		if (current == null || current.getState() == SessionState.FINALIZED
			|| current.getActivityIdentity().getActivityType() != ActivityType.STRUCTURED_ACTIVITY)
		{
			return null;
		}
		return registry.byKey(current.getActivityIdentity().getActivityKey());
	}

	/** Same game tick = same confirmation; tick-less signals fall back to a 600 ms bucket. */
	static long tickKey(SessionSignal signal)
	{
		return signal.getGameTick() != null ? signal.getGameTick() : -1L - signal.getObservedAt().toEpochMilli() / 600L;
	}
}

package com.osrstelemetry.plugin.storage;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Writes state documents to disk.
 *
 * CORRECTNESS NOTE: write() serializes the document to a String synchronously,
 * on the calling thread, before returning. Only the cheap "write this
 * already-built String to a file" step happens on the background
 * executor. This guarantees the persisted document reflects exactly
 * the logical state at the moment write() was called, even if the
 * caller's collector goes on to mutate the same object afterward (e.g.
 * SkillsState.skills is a live map a collector keeps updating). Gson
 * serialization of these small documents is on the order of tens of
 * microseconds — cheap enough that doing it on the client thread is
 * the correct tradeoff (correctness over avoiding client-thread work),
 * per the project's own stated priority.
 *
 * LIFECYCLE NOTE: the executor is created in start() and torn down in
 * shutdown(), not in
 * the constructor — Guice creates this as a singleton once per client
 * process, but the plugin itself can be toggled on and off many times
 * within that process, and each toggle needs a live executor. Calling
 * write() before start() or after shutdown() is a caller bug, not a
 * state this class tries to paper over.
 *
 * SHUTDOWN IS NON-INTERRUPTING (Plugin Hub maintainer review): shutdown()
 * never forcibly terminates the executor or re-asserts this thread's own
 * interrupt status -- both are forms of thread interruption this
 * project's Plugin Hub review disallows outright. A write that is still
 * running when the graceful drain window elapses is left to finish on
 * its own, in the background, on its own (already-daemon) thread rather
 * than being forcibly interrupted -- see shutdown()'s own javadoc.
 */
@Slf4j
@Singleton
public class LocalStateStore
{
	private final Gson gson;
	private ExecutorService writeExecutor;

	/**
	 * @param injectedGson RuneLite's shared, DI-managed Gson. Derived
	 * (never replaced) via {@link Gson#newBuilder()} to add pretty-
	 * printing for these on-disk documents, per the terminal-API rule
	 * against ever constructing a fresh {@code Gson}/{@code GsonBuilder}
	 * of this class's own.
	 */
	@Inject
	public LocalStateStore(Gson injectedGson)
	{
		this.gson = injectedGson.newBuilder().setPrettyPrinting().create();
	}

	public synchronized void start()
	{
		if (writeExecutor != null && !writeExecutor.isShutdown())
		{
			return;
		}
		ExecutorService previous = writeExecutor;
		writeExecutor = Executors.newSingleThreadExecutor(r ->
		{
			Thread t = new Thread(r, "osrs-telemetry-writer");
			t.setDaemon(true);
			return t;
		});
		if (previous != null && !previous.isTerminated())
		{
			// A re-enable right after a shutdown() whose drain outlived its
			// window: the old writer may still hold queued writes. The new
			// writer's first task waits for it (on the writer thread, never
			// the caller's), so writes stay in submission order and two
			// writers never share one .tmp file.
			writeExecutor.submit(() -> awaitPreviousWriter(previous));
		}
	}

	private static void awaitPreviousWriter(ExecutorService previous)
	{
		try
		{
			if (!previous.awaitTermination(PREVIOUS_WRITER_WAIT_SECONDS, TimeUnit.SECONDS))
			{
				log.warn("Previous LocalStateStore writer still draining after {}s; continuing", PREVIOUS_WRITER_WAIT_SECONDS);
			}
		}
		catch (InterruptedException e)
		{
			// Same Plugin Hub rule as shutdown(): never re-assert interrupts.
			log.warn("Interrupted while waiting for the previous LocalStateStore writer to drain");
		}
	}

	private static final long PREVIOUS_WRITER_WAIT_SECONDS = 30;

	public void write(Filepath target, Object document)
	{
		write(target, document, () -> { });
	}

	/**
	 * onWritten only runs if the write actually succeeded — see
	 * writeNow()'s boolean return. This matters because a dependent
	 * write (e.g. a BANK_SNAPSHOT event) must never be triggered when
	 * its file never reached disk. A caller building a dependency chain
	 * (write A, then on success
	 * write B, then on success append an event) should nest calls to
	 * this method — each level only proceeds if the one before it
	 * actually succeeded.
	 */
	public void write(Filepath target, Object document, Runnable onWritten)
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("write() called while LocalStateStore is not started; dropping write to {}", target);
			return;
		}

		String json = gson.toJson(document);
		try
		{
			executor.submit(() ->
			{
				if (writeNow(target, json))
				{
					onWritten.run();
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			// shutdown() raced the check above: same outcome as a write after shutdown.
			log.warn("write() raced LocalStateStore shutdown; dropping write to {}", target);
		}
	}

	/**
	 * Two dependent documents as ONE queued task: {@code first}, then --
	 * only if it succeeded -- {@code second}, then {@code afterFirst}
	 * (which runs once {@code first} is durable, even if {@code second}
	 * fails). Both are serialized HERE, on the caller's thread, so a
	 * document the caller keeps mutating is never read by the writer
	 * thread, and nothing submitted later can land between the two.
	 */
	public void writeChained(Filepath first, Object firstDocument, Filepath second, Object secondDocument, Runnable afterFirst)
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("writeChained() called while LocalStateStore is not started; dropping writes to {} and {}", first, second);
			return;
		}

		String firstJson = gson.toJson(firstDocument);
		String secondJson = gson.toJson(secondDocument);
		try
		{
			executor.submit(() ->
			{
				if (!writeNow(first, firstJson))
				{
					return;
				}
				try
				{
					writeNow(second, secondJson);
				}
				finally
				{
					afterFirst.run();
				}
			});
		}
		catch (RejectedExecutionException e)
		{
			log.warn("writeChained() raced LocalStateStore shutdown; dropping writes to {} and {}", first, second);
		}
	}

	/**
	 * Blocking variant, used only where a caller genuinely needs to
	 * know a write finished (and whether it succeeded) before
	 * proceeding — currently just the shutdown-time bank-snapshot
	 * finalization (see ContainerCollector.flushPendingAndWait()).
	 * Ordinary collectors should use the async write() above; blocking
	 * on the calling thread is only acceptable here because it's used
	 * exclusively from the plugin's own shutDown(), never from an
	 * event handler on the client thread.
	 */
	public boolean writeAndWait(Filepath target, Object document, long timeoutMs)
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null || executor.isShutdown())
		{
			log.warn("writeAndWait() called while LocalStateStore is not started; dropping write to {}", target);
			return false;
		}

		String json = gson.toJson(document);
		try
		{
			java.util.concurrent.Future<Boolean> future = executor.submit(() -> writeNow(target, json));
			return future.get(timeoutMs, TimeUnit.MILLISECONDS);
		}
		catch (Exception e)
		{
			log.warn("writeAndWait timed out or failed for {}", target, e);
			return false;
		}
	}

	/** @return true if the file was successfully and durably written. */
	private boolean writeNow(Filepath target, String json)
	{
		Filepath tmp = target.getParent().joinSegment(target.getFileName() + ".tmp");
		try
		{
			tmp.write(json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("Failed writing telemetry state to {}", target, e);
			return false;
		}

		try
		{
			// ATOMIC_MOVE where the filesystem supports it (all major
			// filesystems on Linux/macOS; NTFS on Windows for
			// same-volume moves, which this always is since tmp and
			// target share a parent directory). Falls back to a
			// plain (non-atomic) replace only where the OS/filesystem
			// genuinely cannot do better.
			tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			return true;
		}
		catch (AtomicMoveNotSupportedException e)
		{
			try
			{
				tmp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
				return true;
			}
			catch (IOException e2)
			{
				log.warn("Non-atomic fallback move also failed for {}", target, e2);
				return false;
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to move {} into place at {}", tmp, target, e);
			return false;
		}
	}

	/**
	 * Graceful drain: stop accepting new work, wait briefly for
	 * queued writes to finish, and only log a warning if they don't --
	 * this never forcibly terminates the executor and never
	 * re-asserts this thread's own interrupt status if it is itself
	 * interrupted while waiting, per this project's Plugin Hub review
	 * requirement against any active thread interruption. A write that
	 * outlives the drain window keeps running to completion in the
	 * background on its own (already-daemon, so it can never keep the
	 * JVM alive) thread instead of being forcibly killed mid-write --
	 * a slower worst case than before, but one that can never leave a
	 * half-written file, and never interrupts I/O that may itself be
	 * mid-syscall.
	 */
	public void shutdown()
	{
		ExecutorService executor = this.writeExecutor;
		if (executor == null)
		{
			return;
		}
		executor.shutdown();
		try
		{
			if (!executor.awaitTermination(2, TimeUnit.SECONDS))
			{
				log.warn("LocalStateStore writer did not drain within the graceful window; it will keep draining in the background rather than being forcibly interrupted");
			}
		}
		catch (InterruptedException e)
		{
			log.warn("Interrupted while awaiting graceful drain of the LocalStateStore writer; leaving it to keep draining in the background");
		}
	}

	/**
	 * Best-effort synchronous read. Added for the bank-snapshot
	 * deduplication feature (seeding an in-memory baseline from
	 * previously-persisted state) — not used by the write path at all.
	 *
	 * Returns null on ANY failure — missing file, malformed JSON, IO
	 * error — by design: this is a fail-open primitive. It does not
	 * depend on the write executor's started/shut-down state, since
	 * reads have no threading concerns of their own; it's the caller's
	 * responsibility to decide whether it's appropriate to call this
	 * from the client thread (see ContainerCollector's bank-baseline
	 * loading for why that's an accepted, bounded, one-time cost
	 * rather than something this method tries to offload itself).
	 */
	public <T> T readIfExists(Filepath file, Class<T> type)
	{
		if (!file.exists())
		{
			return null;
		}
		try (InputStream in = file.openInputStream())
		{
			String json = new String(in.readAllBytes(), StandardCharsets.UTF_8);
			return gson.fromJson(json, type);
		}
		catch (Exception e)
		{
			log.warn("Failed reading {}; treating as absent (fail-open)", file, e);
			return null;
		}
	}
}

package com.osrstelemetry.plugin.storage;

import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * All telemetry files live under this plugin's own RuneLite-managed
 * plugin-data directory, keyed by accountHash (not display name) so a
 * rename never orphans history:
 *
 *   .runelite/plugin-data/{internalName}/{accountHash}/
 *
 * MIGRATION (Plugin Hub maintainer review -- Filepath API): this used to
 * be a plain java.io.File tree rooted directly at
 * .runelite/osrs-telemetry/{accountHash}/ (built off RuneLite.RUNELITE_DIR).
 * RuneLite's Filepath model replaces that with a per-plugin root obtained
 * from Plugin.getPluginDirectory() -- see OsrsTelemetryPlugin.startUp(),
 * which calls init() below exactly once, before anything else touches
 * storage, with the Filepath that method returns.
 *
 * EXISTING USER DATA IS NOT LOST: @PluginDescriptor.legacyDataDirectory
 * on OsrsTelemetryPlugin is set to "osrs-telemetry" (the exact old root
 * directory name). RuneLite's own Plugin.getPluginDirectory() implementation
 * already contains a one-time automatic migration for exactly this
 * situation: the first time it is called after this update, if the NEW
 * plugin-data directory does not exist yet AND the OLD
 * .runelite/osrs-telemetry directory does exist, RuneLite itself moves
 * (renames) the entire old directory -- every accountHash subfolder and
 * everything under it -- into the new location before returning it. No
 * custom migration code was written here; this class and
 * OsrsTelemetryPlugin only need to point at the new root and declare the
 * old one's name for RuneLite's own core mechanism to find.
 *
 * ROOT LIFECYCLE: init() must be called exactly once (repeat calls with
 * the same value are harmless) before any other method on this class is
 * used -- from a real Plugin's startUp() in production, or from a
 * throwaway Filepath rooted at a JVM temp directory in tests (see
 * TestFilepaths). Every method below throws IllegalStateException if
 * called before init().
 */
@Slf4j
public final class TelemetryPaths
{
	private TelemetryPaths()
	{
	}

	private static volatile Filepath root;

	/**
	 * Called exactly once from OsrsTelemetryPlugin.startUp(), with the
	 * Filepath its own getPluginDirectory() returns -- never touched
	 * again for the lifetime of the client process. A plugin
	 * disable/re-enable cycle calls startUp() again, but
	 * getPluginDirectory() resolves to the exact same location every
	 * time (it depends only on RuneLite's own static PLUGIN_DATA
	 * directory and this plugin's fixed internalName), so re-calling
	 * init() on every startUp() is harmless and deliberately not
	 * guarded against.
	 */
	public static void init(Filepath pluginDirectory)
	{
		root = pluginDirectory;
	}

	private static Filepath root()
	{
		Filepath r = root;
		if (r == null)
		{
			throw new IllegalStateException("TelemetryPaths.init() must be called before any storage path is resolved.");
		}
		return r;
	}

	public static Filepath accountDir(long accountHash)
	{
		Filepath dir = root().joinSegment(Long.toString(accountHash));
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath stateFile(long accountHash, String category)
	{
		return accountDir(accountHash).joinSegment(category + ".json");
	}

	public static Filepath collectionLogDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("collection_log");
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath activitiesDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("activities");
		createDirectoriesQuietly(dir);
		return dir;
	}

	/**
	 * ADDED (Filepath migration audit): closes the one call site
	 * (ActivityKillCountCollector) that previously built this exact path
	 * itself via {@code activitiesDir(...).joinSegment(activityId + ".json")}
	 * instead of going through TelemetryPaths like every sibling file
	 * accessor here -- see the migration's file-I/O audit list.
	 */
	public static Filepath activityFile(long accountHash, String activityId)
	{
		return activitiesDir(accountHash).joinSegment(activityId + ".json");
	}

	/**
	 * Immutable historical bank snapshot -- never overwritten. The
	 * current-state bank.json (via stateFile) is a mutable pointer
	 * that references the latest snapshotId; this file, once written,
	 * is never touched again.
	 */
	public static Filepath bankSnapshotFile(long accountHash, String snapshotId)
	{
		return bankSnapshotsDir(accountHash).joinSegment(snapshotId + ".json");
	}

	/** The directory itself, for BankSnapshotRetention to list/prune. */
	public static Filepath bankSnapshotsDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("bank_snapshots");
		createDirectoriesQuietly(dir);
		return dir;
	}

	/**
	 * Single append-only file per account. Not split by day/session --
	 * at this data volume there is no need for log rotation.
	 */
	public static Filepath eventsFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("events.jsonl");
	}

	/**
	 * Mutable pointer to whatever session is currently in progress
	 * (ACTIVE or SUSPENDED) for this account. Overwritten on every
	 * lifecycle transition; never itself an append-only or historical
	 * record.
	 */
	public static Filepath sessionStateFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("session_state.json");
	}

	/**
	 * Directory of immutable, one-per-finalized-session records -- same
	 * role bank_snapshots/ plays for bank history.
	 */
	public static Filepath sessionsDir(long accountHash)
	{
		Filepath dir = accountDir(accountHash).joinSegment("sessions");
		createDirectoriesQuietly(dir);
		return dir;
	}

	public static Filepath sessionFile(long accountHash, String sessionId)
	{
		return sessionsDir(accountHash).joinSegment(sessionId + ".json");
	}

	/**
	 * INTERRUPTED-ACTIVITY RESUME (A -&gt; brief B -&gt; A): the ONE
	 * additive, account-scoped persistence record for the interrupted/
	 * resumable prior session, if any -- see InterruptedCandidateRecord's
	 * own javadoc. Deliberately a small SEPARATE file rather than a
	 * change to session_state.json's own shape (a different plugin
	 * version, or an account that predates this feature, simply has no
	 * such file -- SessionPersistence treats that identically to "no
	 * candidate parked," never an error).
	 */
	public static Filepath interruptedCandidateFile(long accountHash)
	{
		return accountDir(accountHash).joinSegment("interrupted_candidate.json");
	}

	/**
	 * Mirrors the old File-based "mkdirs() if missing" convention --
	 * Filepath.createDirectories() is idempotent exactly like mkdirs()
	 * (a no-op success if the directory already exists), the one
	 * difference being that it can throw IOException where mkdirs()
	 * returned a boolean nobody checked. Logged and swallowed here
	 * rather than propagated: a directory that fails to create will
	 * surface anyway, immediately and more specifically, the moment a
	 * caller tries to write into it (see LocalStateStore's own warn
	 * logging on write failure) -- this is purely defensive, not a new
	 * failure mode.
	 */
	private static void createDirectoriesQuietly(Filepath dir)
	{
		try
		{
			dir.createDirectories();
		}
		catch (IOException e)
		{
			log.warn("Failed creating telemetry directory {}", dir, e);
		}
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.activity.StructuredActivityDefinition;
import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.SessionAggregates;
import java.util.Locale;

/**
 * Generic structured-activity completion metric text ("Games: 8",
 * "Games/hr: 11.4"), shared by Current Session and History so both render
 * it identically in their existing secondary lines. No activity-specific
 * wording lives here: the label comes from the activity registry.
 */
public final class CompletionMetricText
{
	/** The one shared rate floor (see {@link com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot#MIN_DURATION_FOR_RATE_MILLIS}). */
	public static final long MIN_DURATION_FOR_RATE_MILLIS = com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot.MIN_DURATION_FOR_RATE_MILLIS;

	private CompletionMetricText()
	{
	}

	/**
	 * The label for a session's completion metric, or null when the session is
	 * not a structured activity with a known completion source.
	 */
	public static String labelFor(ActivityType type, String activityKey)
	{
		if (type != ActivityType.STRUCTURED_ACTIVITY)
		{
			return null;
		}
		StructuredActivityDefinition def = StructuredActivityRegistry.defaults().byKey(activityKey);
		return def == null || !def.hasCompletionSource() ? null : def.getCompletionLabel();
	}

	/** Completions this session (0 when none were observed yet). */
	public static int countOf(SessionAggregates.ActivityCompletionCount completions)
	{
		return completions == null ? 0 : completions.getSessionCompletions();
	}

	/** Null below the rate threshold or with no completions. */
	public static Double perHour(int count, long activeMillis)
	{
		if (count <= 0 || activeMillis < MIN_DURATION_FOR_RATE_MILLIS)
		{
			return null;
		}
		return count * 3_600_000d / activeMillis;
	}

	public static String countText(String label, int count)
	{
		return label + ": " + count;
	}

	/** The activity's native currency label ("Permits"), or null. */
	public static String currencyLabelFor(String activityKey)
	{
		StructuredActivityDefinition def = activityKey == null ? null : StructuredActivityRegistry.defaults().byKey(activityKey);
		return def == null ? null : def.getCurrencyLabel();
	}

	/** Player-facing label of one currency key ("Elemental", "Catalytic", "Permits"), or null when unknown. */
	public static String currencyLabelForKey(String currencyKey)
	{
		if (currencyKey == null)
		{
			return null;
		}
		switch (currencyKey)
		{
			case "elemental_points":
				return "Elemental";
			case "catalytic_points":
				return "Catalytic";
			case "reward_permits":
				return "Permits";
			default:
				return null;
		}
	}

	/** The activity's currency keys in display order (empty when it has a single unkeyed currency or none). */
	public static java.util.List<String> currencyKeysFor(String activityKey)
	{
		return com.osrstelemetry.plugin.activity.StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(activityKey)
			? java.util.Arrays.asList("elemental_points", "catalytic_points")
			: java.util.Collections.<String>emptyList();
	}

	/** What Avg / Best measure for the activity (tooltip wording). */
	public static String scoreNoun(String activityKey)
	{
		return com.osrstelemetry.plugin.activity.StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(activityKey)
			? "Total energy" : "Final points";
	}

	/**
	 * Activities whose History shows a dedicated SESSION block (games, rate,
	 * currencies, Avg/Best) instead of inline header text. Barrows keeps its
	 * accepted header presentation.
	 */
	public static boolean hasHistorySessionBlock(String activityKey)
	{
		return com.osrstelemetry.plugin.activity.StructuredActivityCatalog.TEMPOROSS.equals(activityKey)
			|| com.osrstelemetry.plugin.activity.StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT.equals(activityKey);
	}

	/** "+11" -- earned this session (never a balance). */
	public static String currencyText(long gained)
	{
		return "+" + String.format(Locale.ROOT, "%,d", gained);
	}

	public static String pointsText(long points)
	{
		return String.format(Locale.ROOT, "%,d", points);
	}

	/**
	 * History's one-line session summary of an activity's stats:
	 * "Permits +11   •   Avg pts 4,920   •   Best pts 5,670" (parts only
	 * when present), or null when there is nothing to say.
	 */
	public static String statsSummary(String activityKey, SessionAggregates.ActivitySessionStats stats)
	{
		if (stats == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder();
		String currency = currencyLabelFor(activityKey);
		if (currency != null && stats.getCurrencyGained() > 0)
		{
			sb.append(currency).append(' ').append(currencyText(stats.getCurrencyGained()));
		}
		Long avg = stats.averageScore();
		if (avg != null && stats.getBestScore() != null)
		{
			if (sb.length() > 0)
			{
				sb.append("   \u2022   ");
			}
			sb.append("Avg pts ").append(pointsText(avg)).append("   \u2022   Best pts ").append(pointsText(stats.getBestScore()));
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	/** The same facts as {@link #summary}, as a wrapping {@link FactLine} ("Games: 8  •  Games/hr: 11.4"). */
	static FactLine factLine(String label, int count, long activeMillis)
	{
		FactLine line = new FactLine(net.runelite.client.ui.FontManager.getRunescapeSmallFont(), SpyglassTheme.TEXT_SECONDARY);
		line.fact(countText(label, count));
		Double rate = perHour(count, activeMillis);
		if (rate != null)
		{
			line.fact(label + "/hr: " + String.format(Locale.ROOT, "%.1f", rate));
		}
		return line;
	}

	/** "Games: 8" or "Games: 8   •   Games/hr: 11.4". */
	public static String summary(String label, int count, long activeMillis)
	{
		String text = countText(label, count);
		Double rate = perHour(count, activeMillis);
		return rate == null ? text : text + "   •   " + label + "/hr: " + String.format(Locale.ROOT, "%.1f", rate);
	}
}

