				limiting == null
					? "Both point types are even: no search points are going to waste"
					: limiting.getLabel() + " is " + wallet.imbalance() + " behind: " + wallet.imbalance() + " "
						+ (limiting == GotrAltar.Type.ELEMENTAL ? "catalytic" : "elemental") + " point"
