	private static String toTitleCase(String enumName)
	{
		if (enumName == null || enumName.isEmpty())
		{
			return "";
		}
		String[] parts = enumName.split("_");
		StringBuilder sb = new StringBuilder();
		for (String part : parts)
		{
			if (part.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(part.substring(0, 1).toUpperCase()).append(part.substring(1).toLowerCase());
		}
		return sb.toString();
	}

	private static String formatNumber(long value)
	{
		return String.format("%,d", value);
	}

	private static String formatDuration(long millis)
	{
		long totalSeconds = millis / 1000L;
		long hours = totalSeconds / 3600L;
		long minutes = (totalSeconds % 3600L) / 60L;
		long seconds = totalSeconds % 60L;
		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, seconds);
		}
		return String.format("%d:%02d", minutes, seconds);
	}

	private static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Best-effort local-time formatting of an ISO-8601 instant string; returns null (never throws) on anything unparseable so a malformed timestamp never blanks out the whole header. */
	private static String formatAbsoluteTime(String isoInstant)
	{
		if (isoInstant == null)
		{
			return null;
		}
		try
		{
			Instant instant = Instant.parse(isoInstant);
			return DateTimeFormatter.ofLocalizedDateTime(FormatStyle.MEDIUM, FormatStyle.SHORT)
				.withZone(ZoneId.systemDefault())
				.format(instant);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.session.Session;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.time.ZoneId;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * The top-level component wired into {@code OsrsTelemetryPanel}'s own
 * Session/Loot/History tab row as the single "History" card -- owns its
 * OWN internal {@link CardLayout} switching between a recent-sessions
 * LIST card and a {@link HistoryDetailView} DETAIL card, so
 * {@code OsrsTelemetryPanel} itself never needs to know History has any
 * internal navigation at all (it only ever sees one component, exactly
 * like {@code CurrentSessionView}/{@code LootTrackerView}).
 *
 * ARCHITECTURE (matches CurrentSessionView's own established pattern):
 * this class has NO reference to {@code HistoryCoordinator} -- it is
 * handed already-built {@link HistoryEntry} summaries via {@link #render}
 * (called when the History list changed or the tab is shown -- a cheap
 * cached read, see {@code HistoryCoordinator#getRecentEntries()}'s own
 * javadoc) and reports "the player opened this session" purely via
 * the constructor-supplied {@code onEntryOpened} callback, exactly the
 * same opaque-Runnable/Consumer shape {@code CurrentSessionView}'s
 * "Re-evaluate Session" button already uses. {@code OsrsTelemetryPanel}
 * is the only class that actually calls
 * {@code HistoryCoordinator.loadDetail(...)}, and it does so entirely
 * off this class's own knowledge -- see that class's own wiring.
 *
 * LAZY DETAIL LOADING: clicking a row does NOT eagerly
 * pre-fetch anything -- it calls {@code onEntryOpened} once, which
 * triggers exactly one background {@code loadDetail()} call in
 * {@code OsrsTelemetryPanel}. {@link #showDetailLoading} is shown
 * immediately (so the click feels responsive even though the real
 * detail read is asynchronous), then {@link #showDetail}/
 * {@link #showDetailUnavailable} replaces it once that background read
 * completes and is marshalled back onto the EDT by the caller.
 *
 * RENDER-KEY SKIP (list card only -- mirrors LootTrackerView's own
 * mechanism): a render whose entry set is identical to what is
 * already on screen (same session ids, same order) is a pure string
 * comparison, no Swing tree rebuild.
 *
 * NO OWN JScrollPane -- see CurrentSessionView/LootTrackerView's own
 * SCROLLING notes; RuneLite's outer sidebar scrollpane does all
 * scrolling for both the list and detail cards here too.
 *
 * VISUAL DIRECTION: the list card is a flat, dark
 * {@link SpyglassTheme#BACKGROUND_MAIN} background, matching
 * {@link OsrsTelemetryPanel}'s dark-bronze tab header above it. Row
 * chrome, text colors, and hover feedback all draw from the same
 * shared {@link SpyglassTheme} palette (a warm
 * {@link SpyglassTheme#SURFACE_CARD} card face, {@link SpyglassTheme#BORDER_SOFT}
 * border, {@link SpyglassTheme#TEXT_PRIMARY}/{@link SpyglassTheme#TEXT_SECONDARY}
 * text, lifting to {@link SpyglassTheme#SURFACE_RAISED}/{@link SpyglassTheme#BORDER_PRIMARY}
 * on hover).
 *
 * VERTICAL STRETCH: {@link #buildRow} deliberately does NOT declare an
 * unbounded {@code Short.MAX_VALUE} maximum height -- that pattern is
 * what causes a BoxLayout row to stretch once its CardLayout card
 * becomes the tallest of the three tabs (see LootTrackerView's own
 * {@code heightBoundedPanel} javadoc for the full root-cause writeup);
 * {@link #heightBoundedPanel} is the guard against it.
 */
final class HistoryView extends JPanel
{
	private static final String CARD_LIST = "list";
	private static final String CARD_DETAIL = "detail";

	private final Consumer<String> onEntryOpened;

	private final CardLayout cardLayout = new CardLayout();
	private final JPanel cards = new JPanel(cardLayout);
	private final JPanel listContent = new JPanel();
	private final HistoryDetailView detailView;

	private String lastRenderKey;
	/**
	 * The session whose detail was opened and not yet left, or null. A
	 * detail result for any other session (a late load after Back, or from
	 * before an account switch) is ignored, and the detail closes when its
	 * session is no longer in the list (another account's list, or aged out).
	 */
	private String openDetailSessionId;

	HistoryView(SkillIconManager skillIconManager, ItemManager itemManager, ClientThread clientThread, OsrsTelemetryConfig config, Consumer<String> onEntryOpened)
	{
		this.onEntryOpened = onEntryOpened;

		setLayout(new BorderLayout());
		setBackground(SpyglassTheme.BACKGROUND_MAIN);

		listContent.setLayout(new BoxLayout(listContent, BoxLayout.Y_AXIS));
		listContent.setBackground(SpyglassTheme.BACKGROUND_MAIN);
		listContent.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		this.detailView = new HistoryDetailView(skillIconManager, itemManager, clientThread, config, this::showList);

		cards.add(listContent, CARD_LIST);
		cards.add(detailView, CARD_DETAIL);
		add(cards, BorderLayout.CENTER);

		render(java.util.Collections.emptyList());
	}

	/** Called when History changed or is shown (see class javadoc) -- cheap, skips rebuilding when nothing changed. */
	void render(List<HistoryEntry> entries)
	{
		String key = computeRenderKey(entries);
		if (key.equals(lastRenderKey))
		{
			return;
		}
		lastRenderKey = key;

		listContent.removeAll();

		if (entries.isEmpty())
		{
			renderEmptyState();
		}
		else
		{
			for (HistoryEntry entry : entries)
			{
				listContent.add(buildRow(entry));
				listContent.add(Box.createVerticalStrut(6));
			}
		}

		listContent.revalidate();
		listContent.repaint();

		if (openDetailSessionId != null && !containsSession(entries, openDetailSessionId))
		{
			showList();
		}
	}

	private static boolean containsSession(List<HistoryEntry> entries, String sessionId)
	{
		for (HistoryEntry entry : entries)
		{
			if (sessionId.equals(entry.getSessionId()))
			{
				return true;
			}
		}
		return false;
	}

	private void showList()
	{
		openDetailSessionId = null;
		cardLayout.show(cards, CARD_LIST);
	}

	/**
	 * Re-values the open detail once prices resolved or GE/HA changed since
	 * it was drawn (cheap no-op otherwise). The detail is loaded once; its
	 * item values come from its own price cache, which resolves later.
	 */
	void refreshDetailValues()
	{
		if (openDetailSessionId != null)
		{
			detailView.refreshValuesIfChanged();
		}
	}

	/** Called (any thread) when the detail's own price cache resolves new prices. */
	void setValuationListener(Runnable listener)
	{
		detailView.setValuationListener(listener);
	}

	/** Package-private, pure, testable -- see LootTrackerView.computeRenderKey()'s own javadoc for why this pattern exists. */
	static String computeRenderKey(List<HistoryEntry> entries)
	{
		StringBuilder key = new StringBuilder(entries.size() * 24);
		for (HistoryEntry entry : entries)
		{
			key.append(entry.getSessionId()).append('|').append(entry.getFinalizedAt()).append('\n');
		}
		return key.toString();
	}

	/** Immediately switches to the detail card showing a loading placeholder -- see class javadoc's LAZY DETAIL LOADING note. */
	void showDetailLoading()
	{
		detailView.showLoading();
		cardLayout.show(cards, CARD_DETAIL);
	}

	/** Called once OsrsTelemetryPanel's background loadDetail() call completes with a real Session. */
	void showDetail(Session session)
	{
		if (openDetailSessionId == null || (session != null && !openDetailSessionId.equals(session.getSessionId())))
		{
			// Stale result: the player went Back, opened another session, or
			// the account changed while this detail was loading.
			return;
		}
		HistoryDetailModel model = HistoryDetailModel.from(session);
		if (model == null)
		{
			showDetailUnavailable();
			return;
		}
		detailView.render(model);
		cardLayout.show(cards, CARD_DETAIL);
	}

	/** Called when loadDetail() failed or returned a malformed/missing session -- see HistoryDetailModel.from()'s fail-open contract. */
	void showDetailUnavailable()
	{
		if (openDetailSessionId == null)
		{
			return;
		}
		detailView.showUnavailable();
		cardLayout.show(cards, CARD_DETAIL);
	}

	static final String EMPTY_TITLE = "No sessions yet";
	static final String EMPTY_TEXT = "Finished sessions from the last 10 days appear here automatically.";

	private void renderEmptyState()
	{
		JLabel title = new JLabel(EMPTY_TITLE);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(SpyglassTheme.TEXT_PRIMARY);
		title.setAlignmentX(Component.CENTER_ALIGNMENT);

		// Wraps to the ACTUAL available width -- see WrappingHtmlLabel's
		// javadoc (the old fixed CSS width:180px was ~233px in Swing and clipped).
		JLabel subtitle = new WrappingHtmlLabel(EMPTY_TEXT, true);
		subtitle.setFont(FontManager.getRunescapeSmallFont());
		subtitle.setForeground(SpyglassTheme.TEXT_SECONDARY);
		subtitle.setAlignmentX(Component.CENTER_ALIGNMENT);

		listContent.add(Box.createVerticalStrut(24));
		listContent.add(title);
		listContent.add(Box.createVerticalStrut(6));
		listContent.add(subtitle);
	}

	/**
	 * See this class's own javadoc VERTICAL STRETCH note and
	 * LootTrackerView's {@code heightBoundedPanel()} for the full
	 * root-cause writeup. A plain {@code JPanel} whose maximum height always equals its own
	 * current preferred height, so a BoxLayout parent with more height
	 * to give away than this row actually needs can never stretch it.
	 *
	 * Package-private (not {@code private}) so {@code HistoryViewTest}
	 * can directly regression-test its dynamic-height behavior -- same
	 * convention {@code LootTrackerViewTest} already establishes for its
	 * own equivalent factory.
	 */
	static JPanel heightBoundedPanel(LayoutManager layout)
	{
		return new JPanel(layout)
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
	}

	private JPanel buildRow(HistoryEntry entry)
	{
		JPanel row = heightBoundedPanel(new BorderLayout(6, 2));
		row.setOpaque(true);
		row.setBackground(SpyglassTheme.SURFACE_CARD);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(rowBorder(SpyglassTheme.BORDER_SOFT));
		row.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));

		String headline = HistoryEntry.displayTitle(entry.getActivityIdentity(), entry.getSlayerAssignmentCount());

		JPanel textColumn = new JPanel();
		textColumn.setLayout(new BoxLayout(textColumn, BoxLayout.Y_AXIS));
		textColumn.setOpaque(false);

		JLabel headlineLabel = new JLabel(headline);
		headlineLabel.setName(ROW_TITLE_NAME);
		headlineLabel.setFont(FontManager.getRunescapeBoldFont());
		headlineLabel.setForeground(SpyglassTheme.TEXT_PRIMARY);
		headlineLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		textColumn.add(headlineLabel);

		// RELEASE CANDIDATE: two short fact lines that wrap between facts,
		// instead of one long line that was truncated at every sidebar width.
		// Plain-label FactLines, not HTML: see FactLine's javadoc (cost).
		// Line 1 -- when, and for how long.
		FactLine whenLine = new FactLine(FontManager.getRunescapeSmallFont(), SpyglassTheme.TEXT_SECONDARY);
		whenLine.setName(ROW_WHEN_NAME);
		String compactWhen = formatCompact(entry.getFinalizedAt());
		if (compactWhen != null)
		{
			whenLine.fact(compactWhen);
		}
		whenLine.fact(formatDuration(entry.getAccumulatedActiveDurationMillis()));
		textColumn.add(whenLine);

		// Line 2 -- what it produced: task/game count first, then XP and drops.
		FactLine statsLine = new FactLine(FontManager.getRunescapeSmallFont(), SpyglassTheme.TEXT_SECONDARY);
		statsLine.setName(ROW_STATS_NAME);
		if (entry.getSlayerAssignmentCount() > 1)
		{
			statsLine.fact(HistoryEntry.taskCountText(entry.getSlayerAssignmentCount()));
		}
		String completionLabel = entry.getActivityCompletionCount() == null ? null
			: CompletionMetricText.labelFor(entry.getActivityIdentity().getActivityType(), entry.getActivityIdentity().getActivityKey());
		if (completionLabel != null)
		{
			statsLine.fact(CompletionMetricText.countText(completionLabel, entry.getActivityCompletionCount()));
		}
		if (entry.getTotalXpGained() > 0)
		{
			statsLine.fact(formatNumber(entry.getTotalXpGained()) + " XP");
		}
		if (entry.getLootDropCount() > 0)
		{
			statsLine.fact(entry.getLootDropCount() + (entry.getLootDropCount() == 1 ? " drop" : " drops"));
		}
		if (!statsLine.isEmpty())
		{
			textColumn.add(statsLine);
		}

		// On the ROW, not a child label: a label with a tooltip would swallow
		// the click that opens this entry.
		String fullWhen = formatRelativeOrAbsolute(entry.getFinalizedAt());
		row.setToolTipText(fullWhen == null ? headline : headline + " \u2014 " + fullWhen);

		row.add(textColumn, BorderLayout.CENTER);

		JLabel chevron = new JLabel("›");
		chevron.setFont(FontManager.getRunescapeBoldFont());
		chevron.setForeground(SpyglassTheme.TEXT_MUTED);
		row.add(chevron, BorderLayout.EAST);

		String sessionId = entry.getSessionId();
		row.addMouseListener(new ClickListener(() ->
		{
			openDetailSessionId = sessionId;
			showDetailLoading();
			if (onEntryOpened != null)
			{
				onEntryOpened.accept(sessionId);
			}
		}));

		// Raised-surface hover feedback (background AND border lift
		// together) while the cursor is over a row, reverting to the
		// row's normal card colors on exit. A second, separate
		// MouseListener on the same row -- purely
		// visual, does not affect the click behavior registered above.
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(SpyglassTheme.SURFACE_RAISED);
				row.setBorder(rowBorder(SpyglassTheme.BORDER_PRIMARY));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(SpyglassTheme.SURFACE_CARD);
				row.setBorder(rowBorder(SpyglassTheme.BORDER_SOFT));
			}
		});

		return row;
	}

	/** Small shared helper -- the row card's compound border (colored line + inner padding), reused for both its normal and hover states (see {@link #buildRow}) so the two never drift out of sync with each other. */
	private static javax.swing.border.Border rowBorder(java.awt.Color lineColor)
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(lineColor),
			BorderFactory.createEmptyBorder(6, 8, 6, 8));
	}

	private static String formatNumber(long value)
	{
		return String.format("%,d", value);
	}

	private static String formatDuration(long millis)
	{
		long totalSeconds = millis / 1000L;
		long hours = totalSeconds / 3600L;
		long minutes = (totalSeconds % 3600L) / 60L;
		long seconds = totalSeconds % 60L;
		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, seconds);
		}
		return String.format("%d:%02d", minutes, seconds);
	}

	static final String ROW_TITLE_NAME = "historyRowTitle";
	static final String ROW_WHEN_NAME = "historyRowWhen";
	static final String ROW_STATS_NAME = "historyRowStats";

	private static final DateTimeFormatter COMPACT_DATE = DateTimeFormatter.ofPattern("MMM d", java.util.Locale.getDefault());

	/** "Sep 20, 11:00 AM" -- History only spans ~10 days, so no year; null (never throws) when unparseable. */
	static String formatCompact(String isoInstant)
	{
		if (isoInstant == null)
		{
			return null;
		}
		try
		{
			java.time.ZonedDateTime at = Instant.parse(isoInstant).atZone(ZoneId.systemDefault());
			return COMPACT_DATE.format(at) + ", " + DateTimeFormatter.ofLocalizedTime(FormatStyle.SHORT).format(at);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Best-effort; returns null (never throws) on anything unparseable so a malformed timestamp never blanks out the row. */
	private static String formatRelativeOrAbsolute(String isoInstant)
	{
		if (isoInstant == null)
		{
			return null;
		}
		try
		{
			Instant instant = Instant.parse(isoInstant);
			return DateTimeFormatter.ofLocalizedDateTime(FormatStyle.MEDIUM, FormatStyle.SHORT)
				.withZone(ZoneId.systemDefault())
				.format(instant);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Mirrors LootTrackerView's own private ClickListener -- see that class's javadoc. */
	private static final class ClickListener extends MouseAdapter
	{
		private final Runnable action;

		ClickListener(Runnable action)
		{
			this.action = action;
		}

		@Override
		public void mouseClicked(MouseEvent e)
		{
			action.run();
		}
	}
}

package com.osrstelemetry.plugin.ui;

import java.util.function.LongSupplier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Resolves Grand Exchange and High Alch unit prices for item IDs without ever calling
 * {@link ItemManager#getItemPrice(int)} or
 * {@link ItemManager#getItemComposition(int)} off RuneLite's client
 * thread.
 *
 * ROOT CAUSE this class fixes: those two ItemManager lookups call
 * into raw {@code Client} state and assert (via
 * {@code AssertionError}) that they run on RuneLite's client thread.
 * {@link CurrentSessionView#unitValue(int, com.osrstelemetry.plugin.LootValuationMode)}
 * used to call them directly from {@code render()}, which runs on the
 * Swing EDT (driven by {@code OsrsTelemetryPanel}'s
 * {@code javax.swing.Timer}) -- every render threw and aborted,
 * freezing the panel on its last successfully-rendered snapshot. This
 * is unlike {@link ItemManager#getImage(int, int, boolean)}, which is
 * already safe to call from any thread: it synchronously returns an
 * {@code AsyncBufferedImage} placeholder and dispatches its own pixel
 * loading onto the client thread internally -- confirmed by
 * inspecting RuneLite's own bytecode, and left untouched here.
 *
 * FIX: the Swing EDT only ever reads already-resolved values from
 * {@link #getGePrice(int)} / {@link #getHighAlchPrice(int)}, which
 * are backed by a {@link ResolvingCache} keyed by item ID. A cache
 * miss returns 0 immediately (never blocks the EDT) and schedules a
 * one-time resolution via {@link ClientThread#invokeLater(Runnable)}
 * -- RuneLite's own established, non-blocking mechanism for marshalling
 * work onto the client thread, the same primitive
 * {@code ItemManager.getImage(...)} uses internally. Once that
 * resolution runs (on the client thread, where the ItemManager calls
 * are legal) and stores the result, {@link #setOnResolved} asks the owning
 * view for one coalesced refresh, which reads the real value and re-sorts
 * the loot row into its correct total-value position. A failed
 * resolution clears its pending state so a later render can retry
 * rather than being stuck at a permanent zero.
 */
final class ItemValuationCache
{
	private final java.util.function.IntToLongFunction gePriceLookup;
	private final java.util.function.IntToLongFunction haPriceLookup;
	/** Runs a lookup on the client thread (ClientThread#invokeLater in production). */
	private final java.util.concurrent.Executor clientThreadExecutor;
	private final ResolvingCache<Integer, Long> gePrices = new ResolvingCache<>();
	private final ResolvingCache<Integer, Long> haPrices = new ResolvingCache<>();

	/**
	 * Bumped every time a
	 * price actually resolves (a real {@link ResolvingCache#put} below),
	 * never on a miss or a failure. A view that skips its expensive
	 * rebuild when nothing else has visibly changed (see
	 * LootTrackerView's own render-key mechanism) still needs to notice
	 * "a price I'm showing as 0/stale just resolved to a real value" --
	 * this counter is that signal, compared cheaply (a single long) rather
	 * than needing the view to re-walk every item id on every tick to
	 * check for a change. {@code volatile}: read from the EDT, written
	 * from the client thread (inside {@link ClientThread#invokeLater}).
	 */
	private volatile long version = 0L;

	/**
	 * Optional: runs (client thread) after each newly resolved price, so the
	 * owning view can request one coalesced refresh instead of waiting for
	 * the next poll. Many resolutions in one burst still coalesce into one
	 * EDT pass (see UiRefreshCoalescer).
	 */
	private volatile Runnable onResolved;

	void setOnResolved(Runnable onResolved)
	{
		this.onResolved = onResolved;
	}

	ItemValuationCache(ItemManager itemManager, ClientThread clientThread)
	{
		// No client thread (headless tests): prices simply stay unresolved.
		this(clientThread == null ? runnable -> { } : clientThread::invokeLater,
			itemId -> itemManager.getItemPrice(itemId),
			itemId -> itemManager.getItemComposition(itemId).getHaPrice());
	}

	/** Seam for tests: explicit client-thread executor and raw price lookups. */
	ItemValuationCache(java.util.concurrent.Executor clientThreadExecutor, java.util.function.IntToLongFunction gePriceLookup,
		java.util.function.IntToLongFunction haPriceLookup)
	{
		this.clientThreadExecutor = clientThreadExecutor;
		this.gePriceLookup = gePriceLookup;
		this.haPriceLookup = haPriceLookup;
	}

	/**
	 * Returns the cached Grand Exchange price for {@code itemId}, or
	 * 0 if not yet resolved. Safe to call from the Swing EDT. A miss
	 * schedules resolution on the client thread; a later render will
	 * see the real value.
	 */
	long getGePrice(int itemId)
	{
		return resolve(gePrices, itemId, () -> Math.max(0L, gePriceLookup.applyAsLong(itemId)));
	}

	/**
	 * Returns the cached High Alch price for {@code itemId}, or 0 if
	 * not yet resolved. Safe to call from the Swing EDT. A miss
	 * schedules resolution on the client thread; a later render will
	 * see the real value.
	 */
	long getHighAlchPrice(int itemId)
	{
		return resolve(haPrices, itemId, () -> Math.max(0L, haPriceLookup.applyAsLong(itemId)));
	}

	/** See {@link #version}'s own javadoc. Safe to call from the EDT. */
	long getVersion()
	{
		return version;
	}

	private long resolve(ResolvingCache<Integer, Long> cache, int itemId, LongSupplier lookup)
	{
		Long cached = cache.getIfResolved(itemId);
		if (cached != null)
		{
			return cached;
		}

		// resolveIfAbsent is a no-op if a resolution for this item ID is
		// already resolved or already in flight -- callers never pile up
		// duplicate ClientThread round-trips for the same item ID.
		cache.resolveIfAbsent(itemId, id -> clientThreadExecutor.execute(() ->
		{
			try
			{
				cache.put(id, lookup.getAsLong());
				version++;
				Runnable listener = onResolved;
				if (listener != null)
				{
					listener.run();
				}
			}
			catch (RuntimeException e)
			{
				// Leave it unresolved rather than caching a permanent 0 --
				// a later render is allowed to retry.
				cache.clearPending(id);
			}
		}));

		return 0L;
	}
}

package com.osrstelemetry.plugin.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.QuantityFormatter;

/**
 * A shared top-level {@code ui}-package class so LootTrackerView can
 * render item cells IDENTICALLY to Current Session's own loot grid
 * instead of duplicating this widget a second time.
 *
 * A single fixed-size loot slot: the authentic item sprite (always
 * {@link ItemManager#getImage(int)} via the caller -- never a
 * placeholder/fake icon) centered in a bank/inventory-style bordered
 * cell, with the stack quantity painted directly on top, and a hover
 * tooltip carrying the full item/value detail.
 */
final class LootGridCell extends JPanel
{
	private static final int CELL_SIZE = 40;

	/**
	 * SHARED LOOT-GRID GEOMETRY -- the one column count/gap every loot
	 * item grid (Current Session's LOOT card and the Loot tab's Grouped
	 * AND Individual source cards) builds its {@link GridLayout} from, via
	 * {@link #newGridLayout()}, so the two surfaces can never drift apart
	 * again. {@code GridLayout} divides the ACTUAL available width evenly
	 * among its columns -- CELL_SIZE is only each cell's preferred size,
	 * not a floor -- so at the normal sidebar width a 5-column grid
	 * renders ~33px cells (exactly what Current Session has always
	 * shown), and a narrower/wider container shrinks/grows the cells
	 * rather than clipping or scrolling horizontally.
	 */
	static final int GRID_COLUMNS = 5;

	/** Horizontal and vertical gap between cells, in pixels. */
	static final int GRID_GAP = 4;

	/** A fresh layout per grid (LayoutManagers are not shared between containers). */
	static GridLayout newGridLayout()
	{
		return new GridLayout(0, GRID_COLUMNS, GRID_GAP, GRID_GAP);
	}

	private final AsyncBufferedImage icon;
	private final String quantityText;
	private final Color quantityColor;

	LootGridCell(AsyncBufferedImage icon, long quantity, String tooltip)
	{
		this.icon = icon;
		this.quantityText = quantity > 1 ? QuantityFormatter.quantityToStackSize(quantity) : null;
		this.quantityColor = stackColor(quantity);
		setPreferredSize(new Dimension(CELL_SIZE, CELL_SIZE));
		// Background/border use SpyglassTheme's shared chrome tokens
		// rather than local color literals, so this cell never drifts
		// from the rest of the plugin's palette. The item sprite and the
		// per-stack-size quantity color below (see stackColor()) are
		// semantic/authentic-OSRS colors, not chrome, and stay local.
		setBackground(SpyglassTheme.BACKGROUND_PANEL);
		setBorder(BorderFactory.createLineBorder(SpyglassTheme.BORDER_SOFT));
		setToolTipText(tooltip);
		if (icon != null)
		{
			// The sprite loads asynchronously -- repaint once RuneLite
			// finishes decoding it, exactly like AsyncBufferedImage's own
			// addTo(JLabel) convenience does internally.
			icon.onLoaded(this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (icon != null)
		{
			int x = (getWidth() - icon.getWidth()) / 2;
			int y = (getHeight() - icon.getHeight()) / 2;
			g.drawImage(icon, x, y, null);
		}
		if (quantityText != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			g.setColor(Color.BLACK);
			// Four-offset outline (not one) -- legible over any sprite,
			// even a bright/busy backdrop that would wash out a single
			// shadow offset.
			g.drawString(quantityText, 2, 11);
			g.drawString(quantityText, 4, 11);
			g.drawString(quantityText, 2, 13);
			g.drawString(quantityText, 4, 13);
			g.setColor(quantityColor);
			g.drawString(quantityText, 3, 12);
		}
	}

	private static Color stackColor(long quantity)
	{
		if (quantity >= 10_000_000L)
		{
			return new Color(80, 220, 90);
		}
		if (quantity >= 100_000L)
		{
			return new Color(255, 193, 37);
		}
		return new Color(255, 224, 130);
	}

	/** Shared clamp -- ItemManager#getImage()'s quantity argument is an int; a loot total can exceed Integer.MAX_VALUE in extreme cases. */
	static int clampToInt(long value)
	{
		return (int) Math.max(1, Math.min(value, Integer.MAX_VALUE));
	}
}

package com.osrstelemetry.plugin.ui;

import java.util.ArrayList;
import java.util.List;
import java.util.function.ToLongFunction;

/**
 * Pure loot valuation/sorting for the Current Session loot section. Resolving an
 * actual unit price (GE or High Alch) is the CALLER's job
 * (CurrentSessionView, via RuneLite's own ItemManager/ItemComposition)
 * -- this class only does the arithmetic and ordering, so it stays
 * directly unit-testable with a plain lambda, no ItemManager mock
 * needed (this project has no Mockito dependency -- same
 * pure-core/RuneLite-boundary split this codebase already uses
 * elsewhere, e.g. NpcInteractionTargetCollector.decide()).
 *
 * SORT ORDER: by TOTAL stack value descending (unit price
 * times quantity), never unit price alone -- a cheap-per-unit stack
 * can still be worth more in total than one expensive item (the
 * task's own "rune platebody vs. coins" example). Ties are broken by
 * item name ascending for a stable, deterministic order.
 *
 * PUBLIC: this class itself, and the nested
 * {@link Priceable} interface, were widened from package-private to
 * public so that {@code ui.model.CurrentSessionSnapshot.LootEntry} AND
 * {@code ui.model.LootTrackerSnapshot.ItemEntry} (a different package)
 * can both implement {@link Priceable} and share this ONE valuation/
 * sort implementation -- the spec's explicit "reuse existing
 * LootPricing, no second pricing system" requirement for the new
 * persistent Loot Tracker. Every other member here ({@link ValuedLootRow},
 * {@link #valueAndSort}, {@link #buildTooltipHtml}, etc.) deliberately
 * stays package-private, exactly as before -- only callers within the
 * {@code ui} package (CurrentSessionView, LootTrackerView) can use the
 * actual valuation logic; {@code ui.model} classes only ever see the
 * {@link Priceable} shape they implement, never the pricing/sorting
 * code itself.
 */
public final class LootPricing
{
	private LootPricing()
	{
	}

	/**
	 * The minimal shape {@link #valueAndSort}
	 * needs from any lootable item entry -- see class javadoc for why
	 * this exists and stays public while everything else here does not.
	 */
	public interface Priceable
	{
		Integer getItemId();

		String getItemName();

		long getQuantity();
	}

	/** One loot row with its resolved unit/total value already applied. */
	static final class ValuedLootRow
	{
		private final Integer itemId;
		private final String itemName;
		private final long quantity;
		private final long unitValue;
		private final long totalValue;

		ValuedLootRow(Integer itemId, String itemName, long quantity, long unitValue, long totalValue)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
			this.unitValue = unitValue;
			this.totalValue = totalValue;
		}

		Integer getItemId()
		{
			return itemId;
		}

		String getItemName()
		{
			return itemName;
		}

		long getQuantity()
		{
			return quantity;
		}

		long getUnitValue()
		{
			return unitValue;
		}

		long getTotalValue()
		{
			return totalValue;
		}
	}

	/**
	 * Resolves each entry's unit value via {@code unitValueLookup}
	 * (called with the entry's itemId), computes each row's total value
	 * (unit value * quantity), and returns a NEW list sorted by total
	 * value descending, item name ascending as a tie-break. Never
	 * mutates {@code entries}. An entry with a null itemId, or whose
	 * lookup throws, is priced at zero (still included, just sorted
	 * last) rather than skipped or crashing the panel -- see
	 * safeLookup().
	 */
	static List<ValuedLootRow> valueAndSort(List<? extends Priceable> entries, ToLongFunction<Integer> unitValueLookup)
	{
		List<ValuedLootRow> rows = new ArrayList<>();
		for (Priceable entry : entries)
		{
			long unitValue = entry.getItemId() == null ? 0L : safeLookup(unitValueLookup, entry.getItemId());
			long totalValue = unitValue * entry.getQuantity();
			rows.add(new ValuedLootRow(entry.getItemId(), entry.getItemName(), entry.getQuantity(), unitValue, totalValue));
		}

		rows.sort((a, b) ->
		{
			int byValue = Long.compare(b.getTotalValue(), a.getTotalValue());
			if (byValue != 0)
			{
				return byValue;
			}
			String nameA = a.getItemName() == null ? "" : a.getItemName();
			String nameB = b.getItemName() == null ? "" : b.getItemName();
			return nameA.compareTo(nameB);
		});

		return rows;
	}

	/** Sum of every row's total value -- the compact "Loot   1.42m gp" header figure. */
	static long sumTotalValue(List<ValuedLootRow> rows)
	{
		long sum = 0L;
		for (ValuedLootRow row : rows)
		{
			sum += row.getTotalValue();
		}
		return sum;
	}

	private static long safeLookup(ToLongFunction<Integer> lookup, int itemId)
	{
		try
		{
			return Math.max(0L, lookup.applyAsLong(itemId));
		}
		catch (RuntimeException e)
		{
			// Defensive only -- an unresolvable/unpriced item (e.g. a
			// quest item with no GE listing) must never take the panel
			// down; it is priced at zero instead.
			return 0L;
		}
	}

	/**
	 * The one shared loot-item tooltip builder -- factored out here so
	 * the full Loot Tracker and Session History views can build the
	 * exact same tooltip shape without re-deriving it. {@code hiddenNote}
	 * is appended as an extra line only when non-null/non-empty -- pass
	 * null from any caller with no hidden-item concept (Current Session
	 * has none; the Loot Tracker does).
	 */
	static String buildTooltipHtml(String itemName, long quantity, String modeLabel, long unitValue, long totalValue, String hiddenNote)
	{
		String name = itemName == null ? "Unknown item" : itemName;
		StringBuilder html = new StringBuilder("<html><b>").append(escapeHtml(name)).append("</b><br>")
			.append("Qty: ").append(formatNumber(quantity)).append("<br>")
			.append(modeLabel).append(" (each): ").append(formatNumber(unitValue)).append(" gp<br>")
			.append("Total: ").append(formatNumber(totalValue)).append(" gp");
		if (hiddenNote != null && !hiddenNote.isEmpty())
		{
			html.append("<br>").append(escapeHtml(hiddenNote));
		}
		html.append("</html>");
		return html.toString();
	}

	private static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private static String formatNumber(long value)
	{
		return String.format("%,d", value);
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.LootValuationMode;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
