package com.osrstelemetry.plugin.ui;

import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

/**
 * A generic, RuneLite-free thread-safe cache that separates "read an
 * already-resolved value" (safe from any thread, including the Swing
 * EDT) from "resolve a missing value" (expected to run exactly once
 * per key, typically on a privileged thread such as RuneLite's client
 * thread).
 *
 * This class has no knowledge of ItemManager, prices, or Swing -- it
 * is the pure/testable half. {@link
 * ItemValuationCache} is the thin RuneLite-coupled half that wires
 * this cache up to ItemManager and ClientThread.
 *
 * Safe publication between the resolving thread and reading threads
 * is provided by {@link ConcurrentHashMap} (a put on one thread is
 * guaranteed visible to a get on another thread with no external
 * locking needed).
 */
final class ResolvingCache<K, V>
{
	private final Map<K, V> resolved = new ConcurrentHashMap<>();
	private final Set<K> pending = ConcurrentHashMap.newKeySet();

	/**
	 * Returns the resolved value for {@code key}, or {@code null} if
	 * it has not been resolved yet. Safe to call from any thread.
	 */
	V getIfResolved(K key)
	{
		return resolved.get(key);
	}

	/**
	 * If {@code key} is not yet resolved and is not already pending
	 * resolution, marks it pending and invokes {@code resolver} for
	 * it exactly once. Returns {@code true} if this call triggered
	 * the resolver, {@code false} if a value was already resolved or
	 * a resolution was already in flight for this key.
	 *
	 * {@code resolver} is expected to eventually call {@link #put}
	 * for {@code key} (typically asynchronously, e.g. after a
	 * ClientThread round-trip) or {@link #clearPending} if resolution
	 * failed and a later call should be allowed to retry.
	 */
	boolean resolveIfAbsent(K key, Consumer<K> resolver)
	{
		if (resolved.containsKey(key))
		{
			return false;
		}

		if (!pending.add(key))
		{
			return false;
		}

		resolver.accept(key);
		return true;
	}

	/**
	 * Stores the resolved value for {@code key} and clears its
	 * pending state. Safe to call from any thread.
	 */
	void put(K key, V value)
	{
		resolved.put(key, value);
		pending.remove(key);
	}

	/**
	 * Clears {@code key}'s pending state without resolving it, so a
	 * later {@link #resolveIfAbsent} call is allowed to retry. Used
	 * when a resolution attempt fails.
	 */
	void clearPending(K key)
	{
		pending.remove(key);
	}
}

package com.osrstelemetry.plugin.ui;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/**
 * View-local expand/collapse state for Current Session's Slayer task
 * ledger cards, keyed by the assignment instance's stable per-session
 * ordinal -- never persisted, never part of session data.
 *
 * Defaults: the CURRENT (latest) assignment is expanded, every older one
 * collapsed. A player click stores an override that survives the panel's
 * ordinary 1-second re-renders. When a NEW assignment becomes current,
 * the previous current card drops its override (so it falls back to
 * collapsed) and the new one starts expanded; overrides on older cards
 * are kept. A different sessionId resets everything.
 */
final class SlayerLedgerCollapseState
{
	private String sessionId;
	private Integer currentOrdinal;
	private final Map<Integer, Boolean> overrides = new HashMap<>();

	/** Call once per render, before any isExpanded() query. */
	void sync(String sessionId, Integer currentOrdinal)
	{
		if (!Objects.equals(sessionId, this.sessionId))
		{
			this.sessionId = sessionId;
			this.currentOrdinal = currentOrdinal;
			overrides.clear();
			return;
		}
		if (!Objects.equals(currentOrdinal, this.currentOrdinal))
		{
			if (this.currentOrdinal != null)
			{
				overrides.remove(this.currentOrdinal);
			}
			if (currentOrdinal != null)
			{
				overrides.remove(currentOrdinal);
			}
			this.currentOrdinal = currentOrdinal;
		}
	}

	boolean isExpanded(int ordinal)
	{
		Boolean override = overrides.get(ordinal);
		return override != null ? override : Objects.equals(ordinal, currentOrdinal);
	}

	void toggle(int ordinal)
	{
		overrides.put(ordinal, !isExpanded(ordinal));
	}
}

package com.osrstelemetry.plugin.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * The Smart Slayer six-stat dashboard: KILLS / KILLS/HR / LOOT/KILL over
 * POINTS / STREAK / NEXT BONUS. One quiet shared surface with hairline
 * separators -- never six bordered boxes -- each cell a small muted caption
 * over a bold value, centered.
 *
 * RESPONSIVE: 3 columns x 2 rows whenever the columns' natural widths fit
 * the real sidebar width (spare space shared evenly); otherwise 2 x 3, and
 * 1 x 6 only as a last resort for extreme values at the narrowest width --
 * same six cells, same row-major order. Text is never shrunk.
 */
final class SlayerStatGrid extends JPanel
{
	static final int PAD_X = 4;
	static final int PAD_Y = 3;
	static final int FALLBACK_WIDTH = 200;
	static final String CELL_PREFIX = "slayerCell:";
	static final String VALUE_PREFIX = "slayerCellValue:";

	private final List<JPanel> cells = new ArrayList<>();
	/** Widest layout allowed (3 for the six-stat dashboards; 2 for a 2 x 2 grid). */
	private int maxColumns = 3;

	SlayerStatGrid()
	{
		super(null);
		setName("slayerStatGrid");
		setOpaque(true);
		setBackground(SpyglassTheme.BACKGROUND_PANEL);
		setAlignmentX(LEFT_ALIGNMENT);
		setBorder(BorderFactory.createLineBorder(SpyglassTheme.BORDER_SOFT));
	}

	/** Caps the column count (default 3); the grid still steps down to fewer columns when narrow. */
	void setMaxColumns(int maxColumns)
	{
		this.maxColumns = Math.max(1, maxColumns);
	}

	/** A cell whose lines are stacked and centered (caption over value, or any short lines). */
	private static JPanel stackedCell()
	{
		return new JPanel(null)
		{
			@Override
			public void doLayout()
			{
				int total = 0;
				for (Component c : getComponents())
				{
					total += c.getPreferredSize().height;
				}
				int y = Math.max(0, (getHeight() - total) / 2);
				for (Component c : getComponents())
				{
					Dimension d = c.getPreferredSize();
					c.setBounds((getWidth() - d.width) / 2, y, d.width, d.height);
					y += d.height;
				}
			}

			@Override
			public Dimension getPreferredSize()
			{
				int w = 0;
				int h = 0;
				for (Component c : getComponents())
				{
					Dimension d = c.getPreferredSize();
					w = Math.max(w, d.width);
					h += d.height;
				}
				return new Dimension(w + 2 * PAD_X, h + 2 * PAD_Y);
			}
		};
	}

	/** Adds one cell of arbitrary stacked lines (e.g. altar / mark / reason), named CELL_PREFIX + key. */
	JPanel addLinesCell(String key, String tooltip, JLabel... lines)
	{
		JPanel cell = stackedCell();
		cell.setName(CELL_PREFIX + key);
		cell.setOpaque(false);
		for (JLabel line : lines)
		{
			if (line != null)
			{
				if (tooltip != null)
				{
					line.setToolTipText(tooltip);
				}
				cell.add(line);
			}
		}
		if (tooltip != null)
		{
			cell.setToolTipText(tooltip);
		}
		cells.add(cell);
		add(cell);
		return cell;
	}

	/** Adds one cell; `value` null renders a quiet dash (the cell itself always exists). */
	JLabel addCell(String caption, String value, Color valueColor, String tooltip)
	{
		JPanel cell = stackedCell();
		cell.setName(CELL_PREFIX + caption);
		cell.setOpaque(false);
		JLabel captionLabel = new JLabel(caption);
		captionLabel.setFont(FontManager.getRunescapeSmallFont());
		captionLabel.setForeground(SpyglassTheme.TEXT_MUTED);
		JLabel valueLabel = new JLabel(value == null ? "-" : value);
		valueLabel.setName(VALUE_PREFIX + caption);
		valueLabel.setFont(FontManager.getRunescapeBoldFont());
		valueLabel.setForeground(value == null ? SpyglassTheme.TEXT_MUTED : valueColor);
		cell.add(captionLabel);
		cell.add(valueLabel);
		if (tooltip != null)
		{
			cell.setToolTipText(tooltip);
			valueLabel.setToolTipText(tooltip);
		}
		cells.add(cell);
		add(cell);
		return valueLabel;
	}

	int availableWidth()
	{
		if (getWidth() > 0)
		{
			return getWidth();
		}
		Container parent = getParent();
		if (parent == null || parent.getWidth() <= 0)
		{
			return FALLBACK_WIDTH;
		}
		Insets in = parent.getInsets();
		return Math.max(1, parent.getWidth() - in.left - in.right);
	}

	private int cellHeight()
	{
		int h = 0;
		for (JPanel cell : cells)
		{
			h = Math.max(h, cell.getPreferredSize().height);
		}
		return h;
	}

	/** Natural width of each column when the cells flow row-major into `cols` columns. */
	private int[] naturalColumnWidths(int cols)
	{
		int[] widths = new int[cols];
		for (int i = 0; i < cells.size(); i++)
		{
			widths[i % cols] = Math.max(widths[i % cols], cells.get(i).getPreferredSize().width);
		}
		return widths;
	}

	private static int sum(int[] values)
	{
		int total = 0;
		for (int v : values)
		{
			total += v;
		}
		return total;
	}

	/**
	 * 3 when the three columns' natural widths fit `width` (inside the
	 * border), else 2, and 1 only as a last resort for extreme values in the
	 * narrowest sidebar -- text is never shrunk instead.
	 */
	int columnsFor(int width)
	{
		Insets in = getInsets();
		int inner = width - in.left - in.right;
		for (int cols = Math.min(maxColumns, Math.max(1, cells.size())); cols > 1; cols--)
		{
			if (sum(naturalColumnWidths(cols)) <= inner)
			{
				return cols;
			}
		}
		return 1;
	}

	int columns()
	{
		return columnsFor(availableWidth());
	}

	/** Column x-boundaries for `width`: natural widths plus an even share of the spare space. */
	private int[] columnEdges(int width)
	{
		Insets in = getInsets();
		int cols = columnsFor(width);
		int[] natural = naturalColumnWidths(cols);
		int spare = Math.max(0, width - in.left - in.right - sum(natural));
		int[] edges = new int[cols + 1];
		edges[0] = in.left;
		for (int c = 0; c < cols; c++)
		{
			edges[c + 1] = edges[c] + natural[c] + spare * (c + 1) / cols - spare * c / cols;
		}
		return edges;
	}

	@Override
	public Dimension getPreferredSize()
	{
		Insets in = getInsets();
		int width = availableWidth();
		int cols = columnsFor(width);
		int rows = (cells.size() + cols - 1) / cols;
		return new Dimension(Math.min(width, sum(naturalColumnWidths(cols)) + in.left + in.right),
			rows * cellHeight() + in.top + in.bottom);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(0, getPreferredSize().height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	@Override
	public void setBounds(int x, int y, int width, int height)
	{
		int before = getWidth() > 0 ? columnsFor(getWidth()) : -1;
		super.setBounds(x, y, width, height);
		if (getWidth() > 0 && columnsFor(getWidth()) != before)
		{
			revalidate();
		}
	}

	@Override
	public void doLayout()
	{
		Insets in = getInsets();
		int[] edges = columnEdges(getWidth());
		int cols = edges.length - 1;
		int h = cellHeight();
		for (int i = 0; i < cells.size(); i++)
		{
			int col = i % cols;
			int row = i / cols;
			cells.get(i).setBounds(edges[col], in.top + row * h, edges[col + 1] - edges[col], h);
		}
	}

	/** Hairline separators between cells -- territory without boxes. */
	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		Insets in = getInsets();
		int[] edges = columnEdges(getWidth());
		int cols = edges.length - 1;
		int rows = (cells.size() + cols - 1) / cols;
		int h = cellHeight();
		g.setColor(SpyglassTheme.BORDER_SOFT);
		for (int c = 1; c < cols; c++)
		{
			g.drawLine(edges[c], in.top + 4, edges[c], in.top + rows * h - 4);
		}
		for (int r = 1; r < rows; r++)
		{
			int y = in.top + r * h;
			g.drawLine(in.left + 6, y, getWidth() - in.right - 7, y);
		}
	}
}

package com.osrstelemetry.plugin.ui;

import com.osrstelemetry.plugin.session.SlayerAssignmentEndReason;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Stateless building blocks for one Slayer assignment card, shared by
 * Current Session's live task ledger and History's per-task loot cards so
 * both say the same thing the same way ("Task xN", "· Skipped", tooltip
 * detail). Each view owns its own expand/collapse state and passes the
 * toggle action in -- nothing here couples live and historical views.
 */
final class SlayerTaskCards
{
	private SlayerTaskCards()
	{
	}

	static String taskName(String taskName)
	{
		return taskName == null ? "Slayer task" : taskName;
	}

	/**
	 * "Task name xN" plus " · Skipped" for REPLACED_EARLY only (COMPLETED and
	 * unfinished assignments carry no badge). xN is omitted when genuinely
	 * unknown (legacy record).
	 */
	static String title(String taskName, Integer unitsCompleted, SlayerAssignmentEndReason endReason)
	{
		StringBuilder sb = new StringBuilder(taskName(taskName));
		if (unitsCompleted != null)
		{
			sb.append(" x").append(unitsCompleted);
		}
		if (endReason == SlayerAssignmentEndReason.REPLACED_EARLY)
		{
			sb.append(" · Skipped");
		}
		return sb.toString();
	}

	/**
	 * Detail kept out of the narrow header: "17 / 75 completed" (the total
	 * only for a fully observed assignment), remaining, end state, then any
	 * view-specific `extraLines`. Only persisted, authoritative values.
	 */
	static String tooltip(String taskName, Integer unitsCompleted, boolean bootstrapped,
		Integer remaining, SlayerAssignmentEndReason endReason, List<String> extraLines)
	{
		// The assignment's original size is never shown: bracelets make kills
		// and task units diverge, so only units done and units remaining are.
		StringBuilder sb = new StringBuilder("<html>").append(escapeHtml(taskName(taskName)));
		if (unitsCompleted != null)
		{
			sb.append("<br>").append(unitsCompleted);
			sb.append(" completed");
			if (bootstrapped)
			{
				sb.append(" (tracked since Spyglass joined mid-task)");
			}
		}
		if (remaining != null)
		{
			sb.append("<br>").append(remaining).append(" remaining");
		}
		if (endReason == SlayerAssignmentEndReason.REPLACED_EARLY)
		{
			sb.append("<br>Skipped");
		}
		else if (endReason == SlayerAssignmentEndReason.COMPLETED)
		{
			sb.append("<br>Completed");
		}
		if (extraLines != null)
		{
			for (String line : extraLines)
			{
				sb.append("<br>").append(escapeHtml(line));
			}
		}
		return sb.append("</html>").toString();
	}

	/**
	 * One collapsible card: "[chevron] title ... value gp" header (click
	 * anywhere on it to toggle), then `expandedContent` below it when
	 * non-null. Sidebar-safe: the title may shrink to 0 and is truncated
	 * with "..." by the label itself, so the value never leaves the card.
	 */
	static JPanel card(String name, boolean expanded, String title, String tooltip, Color titleColor,
		long valueGp, Runnable onToggle, JPanel expandedContent)
	{
		JPanel card = new JPanel();
		card.setName(name);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setOpaque(true);
		card.setBackground(SpyglassTheme.BACKGROUND_PANEL);
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(SpyglassTheme.BORDER_SOFT),
			BorderFactory.createEmptyBorder(3, 5, 3, 5)));

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel titleLabel = new JLabel((expanded ? "▾ " : "▸ ") + title);
		titleLabel.setFont(FontManager.getRunescapeSmallFont());
		titleLabel.setForeground(titleColor);
		titleLabel.setToolTipText(tooltip);
		titleLabel.setMinimumSize(new Dimension(0, titleLabel.getPreferredSize().height));
		header.add(titleLabel, BorderLayout.CENTER);
		JLabel value = new JLabel(QuantityFormatter.quantityToStackSize(valueGp) + " gp");
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(SpyglassTheme.ACCENT_GOLD);
		header.add(value, BorderLayout.EAST);
		MouseAdapter toggle = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onToggle.run();
			}
		};
		header.addMouseListener(toggle);
		// The title carries a tooltip (which registers its own mouse listener
		// and so would swallow clicks) -- give it the toggle too.
		titleLabel.addMouseListener(toggle);
		value.addMouseListener(toggle);
		card.add(header);

		if (expandedContent != null)
		{
			card.add(Box.createVerticalStrut(4));
			card.add(expandedContent);
		}
		return card;
	}

	private static String escapeHtml(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

