package com.osrstelemetry.plugin.ui.model;

import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.loottracker.LootTrackerSource;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * ADDED (Spyglass Phase 2 -- persistent Loot Tracker). The ONE place
 * pure UI-shaped derivation happens for the Loot Tracker -- immutable,
 * built fresh from {@link LootTrackerIndex}/{@link LootTrackerPreferences}
 * at poll time, unit-testable without Swing. Mirrors
 * {@link CurrentSessionSnapshot}'s own architectural role for Current
 * Session exactly (same project convention: a mutable live
 * index/aggregate is never hand	ed to a Swing view directly -- a fresh
 * immutable snapshot is built from it instead, never handed to a Swing
 * view directly).
 *
 * COMBINES two independent inputs that must never be confused with each
 * other: {@link LootTrackerIndex} (pure telemetry-derived truth -- which
 * sources/records/items actually happened) and
 * {@link LootTrackerPreferences} (pure UI preference -- favorites,
 * hidden items, collapsed cards, reset watermarks, show-hidden toggle).
 * Neither of those two classes knows the other exists; this class is
 * where they meet.
 *
 * RESET WATERMARK APPLICATION: each RAW (sourceName, sourceId) source's
 * records are filtered via {@link LootTrackerSource#filteredAfter} using
 * that raw source's own persisted watermark (if any) BEFORE anything
 * else is derived from it (item totals, kill count, individual-drop
 * list, and -- see CANONICAL PLAYER-FACING IDENTITY below -- BEFORE
 * grouping into a player-facing card too). A raw source left with zero
 * records after filtering is omitted entirely (nothing meaningful to
 * show). Resetting one raw variant never resets another, and "reset this
 * NPC" (see below) works by resetting every raw variant currently
 * grouped under it to the same watermark instant -- no separate
 * canonical-watermark storage/migration is needed at all.
 *
 * CANONICAL PLAYER-FACING IDENTITY (Loot Tracker duplicate-card fix
 * pass): {@link LootTrackerIndex} keys raw telemetry by (sourceName,
 * sourceId) -- see its own javadoc -- because OSRS/RuneLite's
 * {@code NPCComposition#getId()} genuinely varies for what is visually
 * ONE logical monster to the player (confirmed live: e.g. "Desert Wolf"/
 * "Goat"-style duplicate cards, each a different composition id under
 * the identical display name). That RAW identity is exactly right for
 * {@link LootTrackerIndex} (telemetry/diagnostics must never lose real
 * source-id information) but is WRONG for what the player sees: spec
 * requires ONE card per logical NPC/activity. This class is therefore
 * the ONE place that raw (sourceName, sourceId) sources get grouped into
 * a single player-facing {@link SourceEntry} by {@link #canonicalDisplayName}
 * (sourceName alone, case-sensitive, exact match -- see that method's
 * own javadoc for why name-only is the right, deliberately simple
 * canonicalization here and why it is safe never to special-case two
 * genuinely-different sources sharing one display name). Every raw
 * sourceKey a canonical entry represents is preserved on it via
 * {@link SourceEntry#getRawSourceKeys()} -- nothing about the raw
 * telemetry identity is lost or merged away in {@link LootTrackerIndex}
 * itself, only in this presentation layer. Preference lookups
 * (favorite/collapsed/hidden) are OR-ed across every raw member of a
 * canonical group -- e.g. a source already favorited under its OLD raw
 * key before this fix shipped is still shown favorited afterward, with
 * no explicit migration/rewrite of the persisted preferences file
 * needed (see {@link SourceEntry#getRawSourceKeys()}'s own javadoc for
 * how the view layer writes new favorite/hide/collapse/reset actions
 * back across the whole group so this stays consistent going forward).
 *
 * VALUATION IS INTENTIONALLY ABSENT: unlike Current Session's
 * equivalent, this snapshot carries only itemId/itemName/quantity (no
 * price/value fields) -- pricing must be resolved off the EDT via
 * {@code ItemValuationCache}/{@code ClientThread} exactly like Current
 * Session's own loot section (see LootPricing's own class javadoc for
 * why valuation can never happen here), so LootTrackerView applies
 * {@code LootPricing.valueAndSort}/{@code buildTooltipHtml} to this
 * snapshot's item lists at render time, the SAME shared valuation/sort
 * code Current Session already uses -- never a second pricing/sorting
 * implementation.
 */
public final class LootTrackerSnapshot
{
	private static final LootTrackerSnapshot EMPTY = new LootTrackerSnapshot(Collections.emptyList(), false);

	/** Null-safe, oldest-first: a null observedAt (should not occur for a real record) sorts last rather than throwing. */
	private static final Comparator<LootTrackerRecord> BY_OBSERVED_AT_ASCENDING = (a, b) ->
	{
		Instant ai = a.getObservedAt();
		Instant bi = b.getObservedAt();
		if (ai == null && bi == null)
		{
			return 0;
		}
		if (ai == null)
		{
			return 1;
		}
		if (bi == null)
		{
			return -1;
		}
		return ai.compareTo(bi);
	};

	private final List<SourceEntry> sources;
	private final boolean showHidden;

	private LootTrackerSnapshot(List<SourceEntry> sources, boolean showHidden)
	{
		this.sources = Collections.unmodifiableList(sources);
		this.showHidden = showHidden;
	}

	public static LootTrackerSnapshot empty()
	{
		return EMPTY;
	}

	public static LootTrackerSnapshot from(LootTrackerIndex index, LootTrackerPreferences preferences)
	{
		if (index == null)
		{
			return empty();
		}

		// Raw (sourceName, sourceId) sources, watermark-filtered -- see
		// class javadoc's RESET WATERMARK APPLICATION note. Grouped by
		// canonical player-facing display name immediately below, in
		// first-observed-raw-source order (a LinkedHashMap, so grouping
		// itself never introduces HashMap-iteration-order nondeterminism
		// -- final presentation order is still entirely decided by
		// LootTrackerSourceOrdering.COMPARATOR at the very end).
		Map<String, List<LootTrackerSource>> rawByCanonicalName = new LinkedHashMap<>();
		// Raw keys of the same card whose records are all behind a reset
		// watermark: they show nothing, but still carry the card's
		// preferences, so a favorite/hide/collapse/reset on the card must
		// keep writing them too (otherwise a raw variant that later returns
		// would bring back stale state).
		Map<String, List<String>> resetRawKeysByCanonicalName = new LinkedHashMap<>();
		for (LootTrackerSource source : index.snapshotSources())
		{
			Instant watermark = preferences == null ? null : preferences.getResetWatermark(source.getSourceKey());
			LootTrackerSource filtered = source.filteredAfter(watermark);
			// A structured reward source is already canonical (its key); it
			// never merges with an NPC that happens to share its display name.
			String canonicalName = filtered.isStructuredReward() ? filtered.getSourceKey() : canonicalDisplayName(filtered.getSourceName());
			if (filtered.getRecords().isEmpty())
			{
				resetRawKeysByCanonicalName.computeIfAbsent(canonicalName, k -> new ArrayList<>()).add(source.getSourceKey());
				continue;
			}
			rawByCanonicalName.computeIfAbsent(canonicalName, k -> new ArrayList<>()).add(filtered);
		}

		List<SourceEntry> entries = new ArrayList<>();
		for (Map.Entry<String, List<LootTrackerSource>> group : rawByCanonicalName.entrySet())
		{
			entries.add(buildCanonicalEntry(group.getValue(),
				resetRawKeysByCanonicalName.getOrDefault(group.getKey(), Collections.<String>emptyList()), preferences));
		}

		// ADDED (Loot Tracker source-ordering fix); CORRECTED (small
		// UI/loot polish pass). "Most recent activity first" -- the source
		// with the newest POST-WATERMARK lastObservedAt first (so a reset
		// source's ordering reflects only what's actually still visible,
		// exactly like its displayed totals already do), with NO favorite
		// grouping: favorite state must never move a source's position in
		// the All list (product decision -- see
		// LootTrackerSourceOrdering's own javadoc for the corrected
		// ordering and why the old favorites-first behavior was removed).
		// getFavoriteSources() below is a simple filter over this same
		// already-sorted list, so it comes out recent-first among
		// favorites "for free" with no separate sort of its own. Never
		// HashMap iteration/discovery/creation order, never alphabetical
		// -- see LootTrackerSourceOrdering's own javadoc for the
		// deterministic tie-break.
		entries.sort(LootTrackerSourceOrdering.COMPARATOR);

		boolean showHidden = preferences != null && preferences.isShowHidden();
		return new LootTrackerSnapshot(entries, showHidden);
	}

	/**
	 * The player-facing canonical grouping key: the raw sourceName,
	 * exactly as observed (case-sensitive, no trimming/normalization
	 * beyond that -- OSRS composition names are already clean, and
	 * inventing fuzzy normalization here would be exactly the kind of
	 * "clever" canonicalization this fix deliberately avoids). Two raw
	 * sources with the identical display name are, to the player,
	 * visually the SAME logical NPC/activity -- there is no product
	 * concept of two different things that both legitimately look like
	 * "Desert Wolf" and must still be told apart on screen -- so grouping
	 * purely by name is both simple and correct here. A null sourceName
	 * groups together as its own canonical bucket (displayed as
	 * "Unknown" by the view, same as before this fix).
	 */
	private static String canonicalDisplayName(String sourceName)
	{
		return sourceName == null ? "" : sourceName;
	}

	/**
	 * Merges one canonical-name group of raw {@link LootTrackerSource}s
	 * (already watermark-filtered) into the single player-facing
	 * {@link SourceEntry} the view renders as one card. Kill count sums
	 * across every raw member (each is still an honest per-raw-source
	 * SERVER_NPC_LOOT occurrence count -- see LootTrackerSource's own
	 * javadoc -- summing them keeps that same honesty for the merged
	 * total). Individual records are concatenated across every member and
	 * re-sorted oldest-first by observedAt, so the Individual view still
	 * shows one true chronological timeline even when it spans multiple
	 * raw composition ids.
	 */
	private static SourceEntry buildCanonicalEntry(List<LootTrackerSource> group, List<String> resetRawKeys, LootTrackerPreferences preferences)
	{
		List<String> rawSourceKeys = new ArrayList<>(group.size());
		int killCount = 0;
		Instant first = null;
		Instant last = null;
		boolean favorite = false;
		boolean collapsed = false;
		List<LootTrackerRecord> allRecords = new ArrayList<>();

		for (LootTrackerSource member : group)
		{
			rawSourceKeys.add(member.getSourceKey());
			killCount += member.getKillCount();
			Instant memberFirst = member.getFirstObservedAt();
			if (memberFirst != null && (first == null || memberFirst.isBefore(first)))
			{
				first = memberFirst;
			}
			Instant memberLast = member.getLastObservedAt();
			if (memberLast != null && (last == null || memberLast.isAfter(last)))
			{
				last = memberLast;
			}
			if (preferences != null && preferences.isFavorite(member.getSourceKey()))
			{
				favorite = true;
			}
			if (preferences != null && preferences.isCollapsed(member.getSourceKey()))
			{
				collapsed = true;
			}
			allRecords.addAll(member.getRecords());
		}
		for (String resetKey : resetRawKeys)
		{
			rawSourceKeys.add(resetKey);
			favorite |= preferences != null && preferences.isFavorite(resetKey);
			collapsed |= preferences != null && preferences.isCollapsed(resetKey);
		}
		allRecords.sort(BY_OBSERVED_AT_ASCENDING);

		Map<Integer, Long> quantityByItemId = new LinkedHashMap<>();
		Map<Integer, String> nameByItemId = new LinkedHashMap<>();
		for (LootTrackerRecord record : allRecords)
		{
			for (LootTrackerItem item : record.getItems())
			{
				quantityByItemId.merge(item.getItemId(), item.getQuantity(), Long::sum);
				nameByItemId.putIfAbsent(item.getItemId(), item.getItemName());
			}
		}

		List<ItemEntry> itemTotals = new ArrayList<>();
		for (Map.Entry<Integer, Long> entry : quantityByItemId.entrySet())
		{
			int itemId = entry.getKey();
			itemTotals.add(new ItemEntry(itemId, nameByItemId.get(itemId), entry.getValue(), isItemHiddenInGroup(rawSourceKeys, itemId, preferences)));
		}

		List<RecordEntry> individualRecords = new ArrayList<>();
		for (LootTrackerRecord record : allRecords)
		{
			List<ItemEntry> recordItems = new ArrayList<>();
			for (LootTrackerItem item : record.getItems())
			{
				recordItems.add(new ItemEntry(item.getItemId(), item.getItemName(), item.getQuantity(), isItemHiddenInGroup(rawSourceKeys, item.getItemId(), preferences)));
			}
			individualRecords.add(new RecordEntry(record.getObservedAt(), Collections.unmodifiableList(recordItems)));
		}

		LootTrackerSource representative = group.get(0);
		return new SourceEntry(
			representative.isStructuredReward() ? representative.getSourceKey() : canonicalSourceKey(representative.getSourceName()),
			representative.getSourceName(),
			representative.getSourceId(),
			killCount,
			first,
			last,
			favorite,
			collapsed,
			Collections.unmodifiableList(itemTotals),
			Collections.unmodifiableList(individualRecords),
			Collections.unmodifiableList(rawSourceKeys));
	}

	/** An item is treated as hidden for the merged card if hidden under ANY raw variant it was hidden from before grouping -- see class javadoc's preference-migration note. */
	private static boolean isItemHiddenInGroup(List<String> rawSourceKeys, int itemId, LootTrackerPreferences preferences)
	{
		if (preferences == null)
		{
			return false;
		}
		for (String rawKey : rawSourceKeys)
		{
			if (preferences.isItemHidden(rawKey, itemId))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The player-facing canonical entry's own identity string -- DELIBERATELY
	 * a different, unambiguous format ({@code "canon:" + name}) from
	 * {@link LootTrackerIndex#sourceKey}'s raw ({@code "name id"}) format, so
	 * the two can never collide even for a name that happens to end in
	 * something that looks like a trailing id token. Used for ordering
	 * tie-breaks and render-key fingerprinting; NEVER used as a
	 * {@link LootTrackerPreferences} key directly -- preference reads/writes
	 * always go through {@link SourceEntry#getRawSourceKeys()} instead (see
	 * that method's own javadoc), so this format never needs to appear in
	 * the persisted preferences document at all.
	 */
	private static String canonicalSourceKey(String sourceName)
	{
		return "canon:" + (sourceName == null ? "" : sourceName);
	}

	/** Every known source (post reset-watermark filtering, post canonical-identity grouping) -- the "All" sub-tab. */
	public List<SourceEntry> getAllSources()
	{
		return sources;
	}

	/** The subset of {@link #getAllSources()} the player has favorited -- the "Favorites" sub-tab. Never a separate/different data source from All. */
	public List<SourceEntry> getFavoriteSources()
	{
		List<SourceEntry> favorites = new ArrayList<>();
		for (SourceEntry entry : sources)
		{
			if (entry.isFavorite())
			{
				favorites.add(entry);
			}
		}
		return favorites;
	}

	/** Spec: "Show hidden" toggle state, default off -- callers decide whether to render a hidden ItemEntry based on this. */
	public boolean isShowHidden()
	{
		return showHidden;
	}

	public static final class SourceEntry
	{
		private final String sourceKey;
		private final String sourceName;
		private final Integer sourceId;
		private final int killCount;
		private final Instant firstObservedAt;
		private final Instant lastObservedAt;
		private final boolean favorite;
		private final boolean collapsed;
		private final List<ItemEntry> itemTotals;
		private final List<RecordEntry> records;
		private final List<String> rawSourceKeys;

		private SourceEntry(String sourceKey, String sourceName, Integer sourceId, int killCount,
			Instant firstObservedAt, Instant lastObservedAt, boolean favorite, boolean collapsed,
			List<ItemEntry> itemTotals, List<RecordEntry> records, List<String> rawSourceKeys)
		{
			this.sourceKey = sourceKey;
			this.sourceName = sourceName;
			this.sourceId = sourceId;
			this.killCount = killCount;
			this.firstObservedAt = firstObservedAt;
			this.lastObservedAt = lastObservedAt;
			this.favorite = favorite;
			this.collapsed = collapsed;
			this.itemTotals = itemTotals;
			this.records = records;
			this.rawSourceKeys = rawSourceKeys;
		}

		/** The CANONICAL (player-facing) identity -- see class javadoc's CANONICAL PLAYER-FACING IDENTITY note. Never a valid {@link LootTrackerPreferences} key on its own; use {@link #getRawSourceKeys()} for preference reads/writes. */
		/** A structured activity reward source (its records are reward claims, not kills). */
		public boolean isStructuredReward()
		{
			return LootTrackerIndex.isStructuredSourceKey(getSourceKey());
		}

		public String getSourceKey()
		{
			return sourceKey;
		}

		public String getSourceName()
		{
			return sourceName;
		}

		/** The FIRST raw member's sourceId -- representative only (a merged canonical entry can span several raw composition ids); not used for identity or preference keys. */
		public Integer getSourceId()
		{
			return sourceId;
		}

		/** Same authoritative per-raw-source occurrence count as {@link LootTrackerSource#getKillCount()}, summed across every raw variant this canonical entry represents -- see that method's own honest-kill-count javadoc. */
		public int getKillCount()
		{
			return killCount;
		}

		public Instant getFirstObservedAt()
		{
			return firstObservedAt;
		}

		public Instant getLastObservedAt()
		{
			return lastObservedAt;
		}

		public boolean isFavorite()
		{
			return favorite;
		}

		public boolean isCollapsed()
		{
			return collapsed;
		}

		/** Grouped view -- one entry per distinct item, quantity summed across every (post-watermark) record from every raw variant this canonical entry represents. */
		public List<ItemEntry> getItemTotals()
		{
			return itemTotals;
		}

		/** Individual-drop view -- one entry per atomic SERVER_NPC_LOOT record from every raw variant this canonical entry represents, merged into one true oldest-first chronological timeline. */
		public List<RecordEntry> getRecords()
		{
			return records;
		}

		/**
		 * Every raw {@link LootTrackerIndex#sourceKey} (sourceName+sourceId)
		 * this canonical, player-facing entry represents -- almost always
		 * one, sometimes several when OSRS/RuneLite assigns multiple
		 * composition ids to what is visually one logical NPC (see class
		 * javadoc's CANONICAL PLAYER-FACING IDENTITY note). Raw telemetry
		 * identity is NEVER lost -- this list is exactly how a caller finds
		 * it again. {@link LootTrackerPreferences} (favorite/collapsed/
		 * hidden-item/reset-watermark) is keyed ONLY by raw sourceKey, never
		 * by this entry's own canonical {@link #getSourceKey()} -- a UI
		 * action on this card (favorite/hide/collapse/reset) must be applied
		 * to EVERY key in this list so it stays consistent with how this
		 * entry's favorite/collapsed/hidden flags above were themselves
		 * computed (OR across the group), and so a raw variant discovered
		 * later under the same display name inherits the group's already-set
		 * preferences the next time an action is taken on the merged card.
		 */
		public List<String> getRawSourceKeys()
		{
			return rawSourceKeys;
		}
	}

	/**
	 * IMPLEMENTS LootPricing.Priceable (Spyglass Phase 2) -- see that
	 * interface's own javadoc for why this and Current Session's own
	 * {@code CurrentSessionSnapshot.LootEntry} share the one valuation/
	 * sort implementation rather than duplicating it.
	 */
	public static final class ItemEntry implements com.osrstelemetry.plugin.ui.LootPricing.Priceable
	{
		private final int itemId;
		private final String itemName;
		private final long quantity;
		private final boolean hidden;

		private ItemEntry(int itemId, String itemName, long quantity, boolean hidden)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.quantity = quantity;
			this.hidden = hidden;
		}

		/** Never null -- a LootTrackerRecord's itemId is always a real, non-nullable int (see LootTrackerItem). Boxed here only to satisfy LootPricing.Priceable's shared shape. */
		public Integer getItemId()
		{
			return itemId;
		}

		/** The unboxed form, for callers that never need the Priceable-shared shape (e.g. hidden-item lookups by raw id). */
		public int getItemIdValue()
		{
			return itemId;
		}

		public String getItemName()
		{
			return itemName;
		}

		public long getQuantity()
		{
			return quantity;
		}

		/** Spec: hidden is source-specific and presentation-only -- a hidden item still counts toward every total. */
		public boolean isHidden()
		{
			return hidden;
		}
	}

	public static final class RecordEntry
	{
		private final Instant observedAt;
		private final List<ItemEntry> items;

		private RecordEntry(Instant observedAt, List<ItemEntry> items)
		{
			this.observedAt = observedAt;
			this.items = items;
		}

		public Instant getObservedAt()
		{
			return observedAt;
		}

		public List<ItemEntry> getItems()
		{
			return items;
		}
	}
}

package com.osrstelemetry.plugin.ui.model;

import java.time.Instant;
import java.util.Comparator;

/**
 * ADDED (Loot Tracker source-ordering fix pass); CORRECTED (small
 * UI/loot polish pass -- Favorites must not reorder the All list). The
 * single, pure, directly-unit-testable definition of "most recent
 * activity first" for the Loot Tracker's source cards -- factored out of
 * {@link LootTrackerSnapshot#from} so the ordering rule itself can be
 * tested with plain {@link LootTrackerSnapshot.SourceEntry} instances,
 * no index/preferences/Swing required.
 *
 * ORDER (product decision, corrected by this pass): plain recent-first,
 * with NO favorite grouping at all -- the source whose newest (post
 * reset-watermark) record is most recent comes first, regardless of
 * favorite state. Favoriting a source makes it available on the
 * Favorites sub-tab; it must never move that source's position within
 * the All list. Applying this ONE comparator to the full source list is
 * what makes both {@link LootTrackerSnapshot#getAllSources()} (plain
 * recent-first, favorite-state-independent) and
 * {@link LootTrackerSnapshot#getFavoriteSources()} (a plain filter over
 * that same already-sorted list, so it comes out recent-first among
 * favorites "for free," with no separate sort of its own) correct from
 * one place.
 *
 * SUPERSEDED: this comparator previously sorted favorites as a group
 * before non-favorites (see this class's prior javadoc / the live
 * bug-fix report the "small UI/loot polish" pass corrected). That
 * behavior made the All view visibly jump/reorder the instant a card was
 * favorited -- confirmed by product decision to be wrong: the point of
 * Favorites is a separate filtered view, not a mutation of the normal
 * list's ordering. Removing the favorite-first comparison is the entire
 * fix; recency-then-sourceKey below is unchanged from before.
 *
 * TIE-BREAK: sources with an equal (or equally absent) last-activity
 * instant are ordered by sourceKey ascending -- stable source identity,
 * never sourceName alone (two different sourceIds sharing a display name
 * must still sort deterministically relative to each other -- see
 * LootTrackerIndex's own "never merged" javadoc). A null lastObservedAt
 * (should not occur for a real, non-empty source -- defensive only)
 * sorts as LEAST recent, never crashes the comparator and never
 * silently ties with a real timestamp.
 */
final class LootTrackerSourceOrdering
{
	private LootTrackerSourceOrdering()
	{
	}

	static final Comparator<LootTrackerSnapshot.SourceEntry> COMPARATOR = (a, b) ->
	{
		int byRecency = compareRecencyDescending(a.getLastObservedAt(), b.getLastObservedAt());
		if (byRecency != 0)
		{
			return byRecency;
		}
		return a.getSourceKey().compareTo(b.getSourceKey());
	};

	/** Descending by instant -- more recent first; null sorts after every real instant. */
	private static int compareRecencyDescending(Instant a, Instant b)
	{
		if (a == null && b == null)
		{
			return 0;
		}
		if (a == null)
		{
			return 1;
		}
		if (b == null)
		{
			return -1;
		}
		return b.compareTo(a);
	}
}

package com.osrstelemetry.plugin.ui.model;

import com.osrstelemetry.plugin.session.SessionAggregates;
import com.osrstelemetry.plugin.session.SlayerAssignmentEndReason;
import java.util.List;
import java.util.Locale;

/**
 * SMART SLAYER DASHBOARD: pure presentation rules for the Slayer Current
 * Session (and History) -- master names, task progress, streak milestones,
 * the Turael-boosting hint, master-specific context rows and per-task rates.
 * No Swing, no client access; every rule here is unit-tested directly.
 */
public final class SlayerDashboard
{
	private SlayerDashboard()
	{
	}

	/** Zero-point masters whose tasks still extend the streak (Turael/Aya, Spria). */
	private static final int TURAEL = 1;
	private static final int SPRIA = 9;
	public static final int KRYSTILIA = 7;
	public static final int KONAR = 8;
	public static final int MORTIMER = 10;

	/** Consecutive completed zero-point-master tasks this session that count as boosting. */
	static final int BOOSTING_MIN_TASKS = 3;

	/**
	 * Streak bonus cadence (OSRS Wiki, Slayer reward point): bonus points on
	 * EVERY 10th task, with larger multipliers on every 50th / 100th / 250th
	 * / 1,000th (the highest applicable tier wins). So the next bonus task is
	 * always the next multiple of 10; its number itself tells the tier.
	 */
	static final int MILESTONE_STEP = 10;

	/**
	 * Player-facing name for the native SLAYER_MASTER varbit. One varbit value
	 * covers both masters of a quest-replaced pair (the game itself does not
	 * distinguish them), so the pair is named rather than guessed. Null for
	 * 0 (no task) and unknown values -- never an internal id.
	 */
	public static String masterName(Integer masterId)
	{
		if (masterId == null)
		{
			return null;
		}
		switch (masterId)
		{
			case 1:
				return "Turael / Aya";
			case 2:
				return "Mazchna / Achtryn";
			case 3:
				return "Vannaka";
			case 4:
				return "Chaeldar";
			case 5:
				return "Duradel / Kuradal";
			case 6:
				return "Nieve / Steve";
			case 7:
				return "Krystilia";
			case 8:
				return "Konar quo Maten";
			case 9:
				return "Spria";
			case 10:
				return "Mortimer";
			default:
				return null;
		}
	}

	/**
	 * Whole-percent task progress from the assignment's own size and the
	 * native remaining count (task units, so bracelet effects are already
	 * reflected). Floor, so 100% appears only at 0 remaining. Null when the
	 * size is unknown -- the size itself is never displayed.
	 */
	public static Integer progressPercent(Integer remaining, Integer size)
	{
		if (remaining == null || size == null || size <= 0 || remaining < 0 || remaining > size)
		{
			return null;
		}
		return (int) Math.floor((size - remaining) * 100.0 / size);
	}

	/** The assignment's size: the observed ASSIGNED amount, else the native original size (joined mid-task). */
	public static Integer assignmentSize(SessionAggregates.SlayerAssignmentRecord record)
	{
		if (record == null)
		{
			return null;
		}
		if (!record.isBootstrapped() && record.getInitialAmount() != null && record.getInitialAmount() > 0)
		{
			return record.getInitialAmount();
		}
		return record.getAssignedInitialAmount();
	}

	/**
	 * The NEXT BONUS cell: "10th in 8", "50th next", "250th in 2" -- the next
	 * streak task that earns bonus points (every multiple of 10). Null for
	 * Mortimer -- his points come from his task modifier and are not raised
	 * by milestones -- and when the streak source is unknown.
	 */
	public static String milestoneText(Integer streak, String streakLabel)
	{
		Integer away = tasksToNextMilestone(streak, streakLabel);
		if (away == null)
		{
			return null;
		}
		String ordinal = ordinal(streak + away);
		return away == 1 ? ordinal + " next" : ordinal + " in " + away;
	}

	/** Tasks until the next bonus (multiple-of-10) streak task (1 = the next task), or null when not applicable. */
	public static Integer tasksToNextMilestone(Integer streak, String streakLabel)
	{
		if (streak == null || streak < 0 || streakLabel == null || "MORTIMER".equals(streakLabel))
		{
			return null;
		}
		int target = (streak / MILESTONE_STEP + 1) * MILESTONE_STEP;
		return target - streak;
	}

	static String ordinal(int n)
	{
		String number = String.format(Locale.ROOT, "%,d", n);
		int mod100 = n % 100;
		if (mod100 >= 11 && mod100 <= 13)
		{
			return number + "th";
		}
		switch (n % 10)
		{
			case 1:
				return number + "st";
			case 2:
				return number + "nd";
			case 3:
				return number + "rd";
			default:
				return number + "th";
		}
	}

	/**
	 * TURAEL BOOSTING, recognized conservatively: the most recent
	 * {@link #BOOSTING_MIN_TASKS} finished assignments of THIS session were
	 * all COMPLETED (never skipped) tasks from a zero-point master
	 * (Turael/Aya or Spria) with a known master. One Turael task, a skip, an
	 * unknown master or any other master breaks the run. The unfinished
	 * current assignment is ignored either way.
	 */
	public static boolean looksLikeTuraelBoosting(List<SessionAggregates.SlayerAssignmentRecord> ledger)
	{
		if (ledger == null)
		{
			return false;
		}
		int run = 0;
		for (int i = ledger.size() - 1; i >= 0; i--)
		{
			SessionAggregates.SlayerAssignmentRecord r = ledger.get(i);
			if (r == null)
			{
				return false;
			}
			if (r.getEndReason() == null && r.getEndedAt() == null)
			{
				// The live, unfinished assignment.
				continue;
			}
			if (r.getEndReason() != SlayerAssignmentEndReason.COMPLETED || r.getMasterId() == null
				|| (r.getMasterId() != TURAEL && r.getMasterId() != SPRIA))
			{
				break;
			}
			run++;
			if (run >= BOOSTING_MIN_TASKS)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The boosting hint: only when boosting is recognized AND the very next
	 * normal-streak task is a bonus task (any multiple of 10 -- the 10th,
	 * 20th, 50th, 100th ...).
	 */
	public static boolean showPointsMasterHint(boolean boosting, Integer streak, String streakLabel)
	{
		Integer away = tasksToNextMilestone(streak, streakLabel);
		return boosting && "NORMAL".equals(streakLabel) && away != null && away == 1;
	}

	/**
	 * Player-facing text for the native task modifier, only for the ids whose
	 * meaning is confirmed: 2 = task quantity (RuneLite 1.13.1 applies it to
	 * the task size itself, signed by SLAYER_MODIFIER_NEGATIVE) and 1 = Slayer
	 * points on completion. Other ids (clue / XP / superior) are not named --
	 * their ordering differs between sources -- so nothing is shown rather
	 * than a guess. Null when there is no modifier.
	 */
	public static String modifierText(int modifierId, int modifierValue, boolean negative)
	{
		if (modifierValue <= 0)
		{
			return null;
		}
		switch (modifierId)
		{
			case 1:
				return "+" + String.format(Locale.ROOT, "%,d", modifierValue) + " points";
			case 2:
				return "Quantity " + (negative ? "-" : "+") + String.format(Locale.ROOT, "%,d", modifierValue);
			default:
				return null;
		}
	}

	/** Kills per hour over the task's own active time; null until the shared rate floor is reached or with no kills. */
	public static Long perHour(Integer count, long activeMillis)
	{
		if (count == null || count <= 0 || activeMillis < CurrentSessionSnapshot.MIN_DURATION_FOR_RATE_MILLIS)
		{
			return null;
		}
		return Math.round(count * 3_600_000.0 / activeMillis);
	}

	/** Observed loot value per observed kill; null with no kills. */
	public static Long perKill(long value, Integer kills)
	{
		if (kills == null || kills <= 0)
		{
			return null;
		}
		return Math.round(value / (double) kills);
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere (see
 * plugin/README.md / other test files' identical notes).
 *
 * Targets AccountContext directly — this is the exact decision logic
 * that gates OsrsTelemetryPlugin.handleLogin()'s account-switch reset
 * dispatch block (skillsCollector/questCollector/containerCollector/
 * activityKillCountCollector/serverNpcLootCollector/knownBossRegistry/
 * bossActivityContextCollector.resetForAccountSwitch(...) plus
 * eventLedger.startNewSession()): that whole block only runs when
 * accountContext.isRealSwitch(previousAccountHash, newAccountHash) is
 * true, and previousAccountHash always comes from
 * accountContext.update(newAccountHash) — so this class alone decides
 * "first login vs. real switch vs. same-account relog/world hop" for
 * every collector on that list.
 *
 * handleLogin() itself is deliberately NOT targeted here: it also
 * touches client.getAccountHash(), sessionRuntimeCoordinator, and ~10
 * concrete collector fields, all @Inject-wired to real RuneLite types
 * (Client, ClientThread, EventBus) with no interfaces to substitute —
 * this project has no Mockito dependency and never mocks RuneLite's
 * Client anywhere (see e.g. QuestCollectorTest's/
 * OsrsTelemetryPluginLifecycleTest's own identical notes), so
 * constructing a real OsrsTelemetryPlugin here would require either a
 * live RuneLite client or invasive production refactoring (extracting
 * an interface layer over every collector) neither of which is in
 * scope here. This test covers exactly what IS safely
 * testable without them: AccountContext's own pure switch-detection
 * decision, in isolation.
 */
public class AccountContextTest
{
	private static final long ACCOUNT_A = 111L;
	private static final long ACCOUNT_B = 222L;

	@Test
	public void firstObservationIsNotARealSwitch()
	{
		// Property A: first account initialization must not trigger the
		// destructive reset-dispatch block in handleLogin() — update()'s
		// sentinel "no account observed yet" (-1) previous value must
		// make isRealSwitch() return false.
		AccountContext context = new AccountContext();

		long previous = context.update(ACCOUNT_A);

		assertFalse(
			"the very first accountHash observed must be treated as a seed, not a switch",
			context.isRealSwitch(previous, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_A, context.getCurrentAccountHash());
	}

	@Test
	public void switchingToADifferentAccountIsARealSwitch()
	{
		// Property B: account A -> account B must be detected as a real
		// switch, so handleLogin() invokes every collector's
		// resetForAccountSwitch(...) exactly once for this transition.
		AccountContext context = new AccountContext();
		long firstPrevious = context.update(ACCOUNT_A);
		context.isRealSwitch(firstPrevious, ACCOUNT_A); // seed, as above

		long secondPrevious = context.update(ACCOUNT_B);

		assertTrue(
			"a genuinely different accountHash must be treated as a real switch",
			context.isRealSwitch(secondPrevious, ACCOUNT_B)
		);
		assertEquals(ACCOUNT_A, secondPrevious);
		assertEquals(ACCOUNT_B, context.getCurrentAccountHash());
	}

	@Test
	public void sameAccountReloginIsNotARealSwitch()
	{
		// Property C: a same-account relog/world hop (accountHash
		// unchanged) must NOT be treated as a real switch, so the
		// per-account collector state above is never falsely cleared —
		// only slayerCollector/tick-counter resets run unconditionally
		// in handleLogin(), by design (see its own comments), and that
		// unconditional-vs-real-switch-gated split is exactly what this
		// method decides.
		AccountContext context = new AccountContext();
		long firstPrevious = context.update(ACCOUNT_A);
		context.isRealSwitch(firstPrevious, ACCOUNT_A); // seed

		long secondPrevious = context.update(ACCOUNT_A);

		assertFalse(
			"re-observing the same accountHash (relog/world hop) must not be a real switch",
			context.isRealSwitch(secondPrevious, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_A, secondPrevious);
	}

	@Test
	public void switchAwayThenBackToAnEarlierAccountIsStillARealSwitch()
	{
		// A -> B -> A: the second transition back to A must be detected
		// as a real switch too — B's leftovers must never be diffed
		// against, or leak into, A's telemetry.
		AccountContext context = new AccountContext();
		context.update(ACCOUNT_A);
		long previousAtB = context.update(ACCOUNT_B);
		context.isRealSwitch(previousAtB, ACCOUNT_B);

		long previousBackAtA = context.update(ACCOUNT_A);

		assertTrue(
			"switching back to a previously-seen account is still a real switch",
			context.isRealSwitch(previousBackAtA, ACCOUNT_A)
		);
		assertEquals(ACCOUNT_B, previousBackAtA);
	}

	@Test
	public void getCurrentAccountHashReflectsMostRecentUpdate()
	{
		AccountContext context = new AccountContext();
		context.update(ACCOUNT_A);
		assertEquals(ACCOUNT_A, context.getCurrentAccountHash());

		context.update(ACCOUNT_B);
		assertEquals(ACCOUNT_B, context.getCurrentAccountHash());
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.collectors.ActivityKillCountCollector;
import com.osrstelemetry.plugin.collectors.CollectionLogCollector;
import com.osrstelemetry.plugin.collectors.CombatAchievementCollector;
import com.osrstelemetry.plugin.collectors.ContainerCollector;
import com.osrstelemetry.plugin.collectors.LoadoutArchiveCollector;
import com.osrstelemetry.plugin.collectors.LootCollector;
import com.osrstelemetry.plugin.collectors.NpcDeathCollector;
import com.osrstelemetry.plugin.collectors.PotionStorageCollector;
import com.osrstelemetry.plugin.collectors.QuestCollector;
import com.osrstelemetry.plugin.collectors.ServerNpcLootCollector;
import com.osrstelemetry.plugin.collectors.SkillsCollector;
import com.osrstelemetry.plugin.collectors.SlayerCollector;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

/**
 * CORE TELEMETRY IS NOT USER-CONFIGURABLE.
 *
 * The 13 former collect* settings are deleted (not hidden), and no
 * collector has ANY path to OsrsTelemetryConfig -- so an old stored
 * "false" for one of those keys in a player's RuneLite profile has
 * nothing left that could read it, and every collector runs whenever the
 * plugin is enabled.
 */
public class CoreTelemetryCollectionNotConfigurableTest
{
	static final List<String> REMOVED_KEYS = Arrays.asList(
		"collectSkills", "collectInventoryEquipment", "collectBank", "collectSeedVault",
		"collectPotionStorage", "collectGroupStorage", "collectQuests", "collectSlayer",
		"collectCollectionLog", "collectCombatAchievements", "collectBossKc", "collectLoot",
		"collectNpcDeaths");

	/** Every collector that used to be gated by one of those keys. */
	private static final List<Class<?>> FORMERLY_GATED = Arrays.asList(
		SkillsCollector.class, ContainerCollector.class, LoadoutArchiveCollector.class,
		PotionStorageCollector.class, QuestCollector.class, SlayerCollector.class,
		CollectionLogCollector.class, CombatAchievementCollector.class, ActivityKillCountCollector.class,
		LootCollector.class, ServerNpcLootCollector.class, NpcDeathCollector.class);

	// 1 -----------------------------------------------------------------
	@Test
	public void noCollectSettingIsExposed_notEvenAsAHiddenItem()
	{
		for (Method m : OsrsTelemetryConfig.class.getMethods())
		{
			assertFalse("no collect* accessor survives: " + m.getName(), m.getName().startsWith("collect"));
			ConfigItem ci = m.getAnnotation(ConfigItem.class);
			if (ci != null)
			{
				assertFalse("removed key re-exposed: " + ci.keyName(), REMOVED_KEYS.contains(ci.keyName()));
				assertFalse("no hidden config items: " + ci.keyName(), ci.hidden());
			}
		}
	}

	// 2 + 3 -------------------------------------------------------------
	@Test
	public void noCollectorCanReadConfig_soAnOldStoredFalseCannotDisableIt()
	{
		for (Class<?> c : FORMERLY_GATED)
		{
			for (Field f : c.getDeclaredFields())
			{
				assertFalse(c.getSimpleName() + " still holds config field " + f.getName(),
					OsrsTelemetryConfig.class.isAssignableFrom(f.getType()));
			}
			for (Constructor<?> k : c.getDeclaredConstructors())
			{
				for (Class<?> p : k.getParameterTypes())
				{
					assertFalse(c.getSimpleName() + " constructor still takes OsrsTelemetryConfig",
						OsrsTelemetryConfig.class.isAssignableFrom(p));
				}
			}
		}
	}

	@Test
	public void pluginHasNoConfigChangeHandler_thatCouldPauseOrReseedCollection()
	{
		for (Method m : OsrsTelemetryPlugin.class.getDeclaredMethods())
		{
			for (Class<?> p : m.getParameterTypes())
			{
				assertFalse("no ConfigChanged subscriber: " + m.getName(),
					p.getName().equals("net.runelite.client.events.ConfigChanged"));
			}
		}
	}

	// 2 -----------------------------------------------------------------
	/** startUp() registers every formerly-gated collector on the EventBus with no condition around it. */
	@Test
	public void startUp_registersEveryCollectorUnconditionally() throws Exception
	{
		String src = new String(Files.readAllBytes(Paths.get(
			"src/main/java/com/osrstelemetry/plugin/OsrsTelemetryPlugin.java")), StandardCharsets.UTF_8).replace("\r\n", "\n");
		int start = src.indexOf("protected void startUp()");
		int end = src.indexOf("protected void shutDown()");
		assertTrue(start > 0 && end > start);
		String startUp = src.substring(start, end);
		String shutDown = src.substring(end);
		for (Class<?> c : FORMERLY_GATED)
		{
			String field = Character.toLowerCase(c.getSimpleName().charAt(0)) + c.getSimpleName().substring(1);
			if (c == QuestCollector.class)
			{
				// Not an EventBus subscriber: the plugin drives it directly --
				// seeded at login, then polled on its GameTick cadence.
				assertTrue(src.contains("questCollector.captureInitialStateWithoutBaseline();"));
				assertTrue(src.contains("questCollector.checkAndFlush();"));
				continue;
			}
			String line = "\n\t\teventBus.register(" + field + ");";
			assertTrue("startUp() registers " + field + " at method level (not inside a branch)", startUp.contains(line));
			assertTrue("shutDown() unregisters " + field, shutDown.contains("eventBus.unregister(" + field + ");"));
		}
		assertFalse("startUp() consults no collect* setting", startUp.contains("config.collect"));
		assertEquals("no collect* read left anywhere in the plugin", -1, src.indexOf("config.collect"));
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/**
 * Settings organization audit, read from RuneLite's own @ConfigSection /
 * @ConfigItem annotations (exactly what RuneLite's config panel renders
 * from): sections, section membership, deterministic positions, and that
 * every remaining keyName and default survived. Core collection toggles
 * are gone -- see CoreTelemetryCollectionNotConfigurableTest.
 */
public class OsrsTelemetryConfigTest
{
	private static final OsrsTelemetryConfig DEFAULTS = new OsrsTelemetryConfig()
	{
	};

	private static Map<String, String> sectionsByName() throws Exception
	{
		Map<String, String> sections = new LinkedHashMap<>();
		for (Field f : OsrsTelemetryConfig.class.getFields())
		{
			ConfigSection cs = f.getAnnotation(ConfigSection.class);
			if (cs != null)
			{
				sections.put(cs.name(), (String) f.get(null));
			}
		}
		return sections;
	}

	private static Map<String, Method> itemsByKey()
	{
		Map<String, Method> items = new HashMap<>();
		for (Method m : OsrsTelemetryConfig.class.getMethods())
		{
			ConfigItem ci = m.getAnnotation(ConfigItem.class);
			if (ci != null)
			{
				items.put(ci.keyName(), m);
			}
		}
		return items;
	}

	@Test
	public void sections_sharedThenCurrentSession_noEmptyLootTrackerOrHistorySections() throws Exception
	{
		Map<String, String> sections = sectionsByName();
		assertEquals(Arrays.asList("General", "Current Session"), orderedSectionNames());
		assertTrue(!sections.containsKey("Loot Tracker"));
		assertTrue("no setting is exclusively History's, so no History section", !sections.containsKey("History"));
	}

	private static List<String> orderedSectionNames() throws Exception
	{
		Map<Integer, String> byPosition = new java.util.TreeMap<>();
		for (Field f : OsrsTelemetryConfig.class.getFields())
		{
			ConfigSection cs = f.getAnnotation(ConfigSection.class);
			if (cs != null)
			{
				assertTrue("unique section positions", byPosition.put(cs.position(), cs.name()) == null);
			}
		}
		return new java.util.ArrayList<>(byPosition.values());
	}

	@Test
	public void everyExistingKeyNameAndDefault_preserved_andPlacedInTheAuditedSection() throws Exception
	{
		Map<String, String> sections = sectionsByName();
		String shared = sections.get("General");
		String currentSession = sections.get("Current Session");
		Map<String, Method> items = itemsByKey();

		// Shared: only genuinely cross-tab settings. lootValuationMode is read
		// by CurrentSessionView, LootTrackerView and HistoryDetailView.
		Map<String, Object> expectedShared = new LinkedHashMap<>();
		expectedShared.put("lootValuationMode", LootValuationMode.GRAND_EXCHANGE);

		for (Map.Entry<String, Object> e : expectedShared.entrySet())
		{
			Method m = items.get(e.getKey());
			assertNotNull("keyName unchanged: " + e.getKey(), m);
			assertEquals(shared, m.getAnnotation(ConfigItem.class).section());
			assertEquals("default unchanged: " + e.getKey(), e.getValue(), m.invoke(DEFAULTS));
		}

		Method order = items.get("currentSessionSectionOrder");
		assertEquals(currentSession, order.getAnnotation(ConfigItem.class).section());
		assertEquals(CurrentSessionSectionOrder.XP_FIRST, order.invoke(DEFAULTS));

		Method scope = items.get("slayerXpScope");
		assertNotNull(scope);
		assertEquals("Slayer XP scope", scope.getAnnotation(ConfigItem.class).name());
		assertEquals(currentSession, scope.getAnnotation(ConfigItem.class).section());
		assertEquals(SlayerXpScope.ALL_TASKS, scope.invoke(DEFAULTS));

		assertEquals("no settings added or lost", expectedShared.size() + 2, items.size());
		for (Method m : items.values())
		{
			ConfigItem ci = m.getAnnotation(ConfigItem.class);
			if (shared.equals(ci.section()))
			{
				assertTrue("Shared holds only cross-feature settings: " + ci.keyName(), expectedShared.containsKey(ci.keyName()));
			}
		}
	}

	@Test
	public void finalVisibleMenu_exactlyThreeSettings_inAuditedOrder() throws Exception
	{
		Map<String, String> sections = sectionsByName();
		Map<String, java.util.TreeMap<Integer, String>> bySection = new LinkedHashMap<>();
		for (Method m : itemsByKey().values())
		{
			ConfigItem ci = m.getAnnotation(ConfigItem.class);
			assertTrue("no hidden items: " + ci.keyName(), !ci.hidden());
			bySection.computeIfAbsent(ci.section(), k -> new java.util.TreeMap<>()).put(ci.position(), ci.name());
		}
		assertEquals(Arrays.asList("Loot valuation"), new java.util.ArrayList<>(bySection.get(sections.get("General")).values()));
		assertEquals(Arrays.asList("XP / Loot order", "Slayer XP scope"),
			new java.util.ArrayList<>(bySection.get(sections.get("Current Session")).values()));
		assertEquals("every section is non-empty and no other section exists", 2, bySection.size());
	}

	@Test
	public void positions_uniqueAndDeterministicWithinEachSection()
	{
		Map<String, Set<Integer>> seen = new HashMap<>();
		for (Method m : itemsByKey().values())
		{
			ConfigItem ci = m.getAnnotation(ConfigItem.class);
			assertTrue("every setting belongs to a section: " + ci.keyName(), !ci.section().isEmpty());
			assertTrue("duplicate position in section " + ci.section() + ": " + ci.keyName(),
				seen.computeIfAbsent(ci.section(), s -> new HashSet<>()).add(ci.position()));
		}
	}

	@Test
	public void slayerXpScope_labels()
	{
		assertEquals("All tasks", SlayerXpScope.ALL_TASKS.toString());
		assertEquals("Current task", SlayerXpScope.CURRENT_TASK.toString());
		assertEquals(2, SlayerXpScope.values().length);
	}
}

package com.osrstelemetry.plugin;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere (see
 * plugin/README.md / other test files' identical notes).
 *
 * Targets OsrsTelemetryPlugin.StartupHydrationGate directly — the
 * Client/ClientThread-independent piece extracted from the
 * client-thread lifecycle audit (see startUp()/onGameStateChanged()).
 * This project has no Mockito dependency and never mocks RuneLite's
 * Client or ClientThread anywhere (see e.g. QuestCollectorTest's own
 * note) — both are real RuneLite classes whose exact internal
 * threading behavior can't be faithfully faked here, so this test
 * covers exactly what IS safely testable without them: the pure
 * duplicate-initialization guard requirements 2 and 5 asked for.
 *
 * What this does NOT cover (verified instead by source inspection):
 * that startUp() actually calls clientThread.invokeLater() rather than
 * calling handleLogin() directly -- a structural property of the
 * production code, not a decision this gate makes.
 */
public class OsrsTelemetryPluginLifecycleTest
{
	@Test
	public void consumeWithoutArmingReturnsFalse()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		assertFalse("nothing was armed; the deferred callback must not run handleLogin()", gate.consumeIfPending());
	}

	@Test
	public void armThenConsumeReturnsTrueExactlyOnce()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.arm();
		assertTrue("first consume after arm() must run the deferred hydration", gate.consumeIfPending());
		assertFalse("a second consume for the same arm() must not run hydration again", gate.consumeIfPending());
	}

	@Test
	public void realLoginSupersedesStillPendingDeferredHydration()
	{
		// Models: startUp() runs on AWT while already logged in and
		// arms the gate, but a genuine GameStateChanged(LOGGED_IN)
		// (e.g. a fast relog) reaches onGameStateChanged() and calls
		// supersede() BEFORE the deferred ClientThread callback from
		// startUp() gets a chance to run.
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.arm();
		gate.supersede();

		assertFalse(
			"a real login event must make the deferred startup hydration a no-op, "
				+ "since onGameStateChanged()'s own handleLogin() call already covers it",
			gate.consumeIfPending()
		);
	}

	@Test
	public void supersedeBeforeArmIsSafeAndDoesNotArmAnything()
	{
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();
		gate.supersede();
		assertFalse(gate.consumeIfPending());
	}

	@Test
	public void arm_consume_armAgain_consumeAgain_eachEnableGetsExactlyOneHydration()
	{
		// Models plugin disable -> re-enable -> disable -> re-enable:
		// each enable that reaches startUp() while already logged in
		// must independently produce exactly one hydration.
		OsrsTelemetryPlugin.StartupHydrationGate gate = new OsrsTelemetryPlugin.StartupHydrationGate();

		gate.arm();
		assertTrue(gate.consumeIfPending());
		assertFalse(gate.consumeIfPending());

		gate.arm();
		assertTrue(gate.consumeIfPending());
		assertFalse(gate.consumeIfPending());
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.GotrStrategy;
import org.junit.Test;

/**
 * GotR rift advice: a winner only when the open rifts are known, usable and
 * the mechanics say one is meaningfully better -- otherwise EITHER / CAPPED /
 * NONE / INSUFFICIENT_EVIDENCE, never a forced winner.
 */
public class GotrAdviceTest
{
	private static GotrGameState game(int e, int c, GotrAltar elemental, GotrAltar catalytic, Boolean eOk, Boolean cOk)
	{
		return GotrGameState.of(50, e, c, elemental, catalytic, eOk, cOk);
	}

	private static GotrAdvice points(GotrGameState g, GotrRewardWallet w)
	{
		return GotrAdvice.of(GotrStrategy.POINTS, g, w);
	}

	private static GotrAdvice xp(GotrGameState g)
	{
		return GotrAdvice.of(GotrStrategy.XP, g, null);
	}

	// ---- POINTS ------------------------------------------------------------

	@Test
	public void points_catalyticBehind_inTheWallet_focusesTheSide_notAnAltar()
	{
		GotrAdvice a = points(game(200, 200, GotrAltar.AIR, GotrAltar.NATURE, true, true), GotrRewardWallet.of(31, 27));
		assertEquals(GotrAdvice.Outcome.FOCUS_CATALYTIC, a.getOutcome());
		assertEquals(GotrAltar.Type.CATALYTIC, a.getFocus());
		assertNull("which catalytic altar does not matter for points", a.getAltar());
		assertEquals("4 behind", a.getReason());
		assertTrue(a.getDetail().contains("catalytic is 4 points behind"));
	}

	@Test
	public void points_elementalBehind_countingThisGamesEnergyToo()
	{
		// Wallet even, this game 100 catalytic ahead: elemental is one point behind.
		GotrAdvice a = points(game(150, 250, GotrAltar.WATER, GotrAltar.CHAOS, true, true), GotrRewardWallet.of(10, 10));
