	// ---- WALLET / ALTAR TABLE ---------------------------------------------

	@Test
	public void wallet_searchesAreTheSmallerSide_limitingSide_balanced()
	{
		GotrRewardWallet w = GotrRewardWallet.of(31, 27);
		assertEquals(27, w.searches());
		assertEquals(GotrAltar.Type.CATALYTIC, w.limitingSide());
		assertEquals(4, w.imbalance());
		assertNull(GotrRewardWallet.of(9, 9).limitingSide());
		assertNull("both sides must be known", GotrRewardWallet.of(9, null));
		assertNull(GotrRewardWallet.of(-1, 3));
	}

	@Test
	public void altarTable_liveVerifiedIndices_andOutOfRangeIsUnknown()
	{
		assertEquals(GotrAltar.EARTH, GotrAltar.of(GotrAltar.Type.ELEMENTAL, 3));
		assertEquals(GotrAltar.FIRE, GotrAltar.of(GotrAltar.Type.ELEMENTAL, 4));
		assertEquals(GotrAltar.COSMIC, GotrAltar.of(GotrAltar.Type.CATALYTIC, 3));
		assertEquals(GotrAltar.NATURE, GotrAltar.of(GotrAltar.Type.CATALYTIC, 5));
		assertEquals(GotrAltar.DEATH, GotrAltar.of(GotrAltar.Type.CATALYTIC, 7));
		assertNull(GotrAltar.of(GotrAltar.Type.ELEMENTAL, 0));
		assertNull(GotrAltar.of(GotrAltar.Type.ELEMENTAL, 5));
		assertNull(GotrAltar.of(GotrAltar.Type.CATALYTIC, 9));
		assertNull(GotrAltar.of(GotrAltar.Type.CATALYTIC, null));
		double last = 0;
		for (GotrAltar a : new GotrAltar[]{GotrAltar.AIR, GotrAltar.MIND, GotrAltar.WATER, GotrAltar.EARTH, GotrAltar.FIRE, GotrAltar.BODY,
			GotrAltar.COSMIC, GotrAltar.CHAOS, GotrAltar.NATURE, GotrAltar.LAW, GotrAltar.DEATH, GotrAltar.BLOOD})
		{
			assertTrue("standard XP per essence rises with the altar's level", a.getXpPerEssence() > last);
			last = a.getXpPerEssence();
		}
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/** Guardians of the Rift current-game presentation values: never guessed, never out of range. */
public class GotrGameStateTest
{
	@Test
	public void powerPercent_roundsDown_clamps_andNeedsAPositiveMax()
	{
		assertEquals(Integer.valueOf(62), GotrGameState.powerPercent(62, 100));
		assertEquals(Integer.valueOf(33), GotrGameState.powerPercent(333, 1000));
		assertEquals(Integer.valueOf(0), GotrGameState.powerPercent(0, 1000));
		assertEquals(Integer.valueOf(100), GotrGameState.powerPercent(1000, 1000));
		assertEquals(Integer.valueOf(100), GotrGameState.powerPercent(1500, 1000));
		assertEquals(Integer.valueOf(0), GotrGameState.powerPercent(-5, 1000));
		assertNull(GotrGameState.powerPercent(5, 0));
		assertNull(GotrGameState.powerPercent(null, 1000));
		assertNull(GotrGameState.powerPercent(5, null));
	}

	@Test
	public void eachFieldIsIndependentlyOptional_andNothingKnownIsNull()
	{
		assertNull(GotrGameState.of(null, null, null));
		assertNull("negative energy is unknown, not a value", GotrGameState.of(null, -1, -1));
		GotrGameState powerOnly = GotrGameState.of(55, null, null);
		assertEquals(Integer.valueOf(55), powerOnly.getGuardianPowerPercent());
		assertNull(powerOnly.getTotalEnergy());
		GotrGameState energyOnly = GotrGameState.of(null, 280, 310);
		assertNull(energyOnly.getGuardianPowerPercent());
		assertEquals(Integer.valueOf(590), energyOnly.getTotalEnergy());
	}

	@Test
	public void total_onlyWhenBothEnergiesAreKnown()
	{
		assertNull(GotrGameState.of(10, 280, null).getTotalEnergy());
		assertEquals(Integer.valueOf(0), GotrGameState.of(0, 0, 0).getTotalEnergy());
	}

	@Test
	public void equality_drivesChangeOnlyRefresh()
	{
		assertEquals(GotrGameState.of(62, 280, 310), GotrGameState.of(62, 280, 310));
		assertNotEquals(GotrGameState.of(62, 280, 310), GotrGameState.of(63, 280, 310));
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** Final energy and provenance of won GotR games (the Avg / Best population). */
public class GotrGameTrackerTest
{
	@Test
	public void fullyObservedWin_scoresItsFinalTotalEnergy()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(150, 90);
		t.onEnergy(420, 380);
		GotrGameTracker.Result r = t.onCompletion(12, 420, 380);
		assertEquals(Integer.valueOf(12), r.getRiftsClosed());
		assertEquals(Integer.valueOf(800), r.getTotalEnergy());
		assertTrue(r.isObservedFromStart());
	}

	@Test
	public void finalValue_survivesTheVarbitsResettingBeforeTheMessage()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(500, 520);
		GotrGameTracker.Result r = t.onCompletion(3, 0, 0);
		assertEquals(Integer.valueOf(1020), r.getTotalEnergy());
		assertTrue(r.isObservedFromStart());
	}

	@Test
	public void gameFirstSeenAboveZero_isPartial_stillReportsEnergy_neverTrusted()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(300, 200); // login / re-enable mid-game
		t.onEnergy(450, 400);
		GotrGameTracker.Result r = t.onCompletion(4, 450, 400);
		assertEquals(Integer.valueOf(850), r.getTotalEnergy());
		assertFalse(r.isObservedFromStart());
	}

	@Test
	public void energyDroppingWithoutAZeroWeSaw_isANewUnwatchedGame()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(600, 500);
		t.onEnergy(80, 40); // reset while unwatched, then re-earned
		assertFalse(t.onCompletion(5, 80, 40).isObservedFromStart());
	}

	@Test
	public void failedGame_dropsItsTracking_andTheNextGameMustProveItsStart()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(400, 300);
		assertTrue(GotrGameTracker.isFailure("The Great Guardian was defeated!"));
		t.onFailure();
		t.onEnergy(400, 300); // varbits still hold the lost game's energy
		GotrGameTracker.Result r = t.onCompletion(6, 400, 300);
		assertFalse("the lost game's energy can never become a trusted win", r.isObservedFromStart());
		t.onEnergy(0, 0);
		t.onEnergy(200, 210);
		assertTrue(t.onCompletion(7, 200, 210).isObservedFromStart());
	}

	@Test
	public void completionConsumesTheGame_aSecondCompletionWithoutAZeroIsUntrusted()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(300, 300);
		assertTrue(t.onCompletion(8, 300, 300).isObservedFromStart());
		assertFalse(t.onCompletion(9, 300, 300).isObservedFromStart());
	}

	@Test
	public void zeroEnergyWin_hasNoScore()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		GotrGameTracker.Result r = t.onCompletion(10, 0, 0);
		assertNull(r.getTotalEnergy());
		assertFalse(r.isObservedFromStart());
	}

	@Test
	public void reset_forgetsProvenance()
	{
		GotrGameTracker t = new GotrGameTracker();
		t.onEnergy(0, 0);
		t.onEnergy(100, 100);
		t.reset();
		assertFalse(t.onCompletion(11, 100, 100).isObservedFromStart());
	}

	@Test
	public void failureText_isMatchedOnlyForTheGamesOwnMessage()
	{
		assertFalse(GotrGameTracker.isFailure("The Great Guardian successfully closed the rift!"));
		assertFalse(GotrGameTracker.isFailure(null));
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Test;

/**
 * HARD RULE: Spyglass's Guardians of the Rift data comes only from native
 * client state -- the game's own HUD (interface 746) and its update
 * clientscript (5980) arguments, the GotR varbits, game messages, the
 * inventory, Runecraft XP and location -- never from a GotR Plugin Hub
 * plugin, another plugin's overlay or state, or reflection. Native RuneLite
 * API / gameval constants stay allowed.
 */
public class GotrNativeIndependenceTest
{
	private static final String MAIN = "src/main/java/com/osrstelemetry/plugin/";
	private static final String[] GOTR_PATH = {
		"activity/GotrAdvice.java",
		"activity/GotrAltar.java",
		"activity/GotrCandidate.java",
		"activity/GotrPortalTalismans.java",
		"activity/GotrGameState.java",
		"activity/GotrRewardWallet.java",
		"GotrStrategy.java",
		"activity/GotrGameTracker.java",
		"activity/GotrRewardPointTracker.java",
		"activity/GotrRunes.java",
		"activity/ProductionRecipe.java",
		"activity/ProductionTracker.java",
		"collectors/StructuredActivityCollector.java",
		"ui/ProducedItemGrid.java",
		"ui/SlayerStatGrid.java",
		"ui/FactLine.java",
		"ui/CurrentSessionView.java",
		"ui/HistoryDetailView.java",
		"ui/OsrsTelemetryPanel.java",
	};
	private static final String[] FORBIDDEN = {
		"net.runelite.client.plugins.", "PluginManager", "OverlayManager", "InfoBoxManager",
		"setAccessible(", "getDeclaredField(", "getDeclaredMethod(", "Class.forName(", "java.lang.reflect",
		"com.datbear", "gotrprogressbar", "com.hawolt", "gotrrunetracker", "guardiansoftherift", "gotroptimizer",
	};

	private static String code(String relative) throws Exception
	{
		Path p = Paths.get(MAIN + relative);
		String src = new String(Files.readAllBytes(p), StandardCharsets.UTF_8);
		// Code only: prose may name other plugins (e.g. as evidence of the game's text).
		return src.replaceAll("(?s)/\\*.*?\\*/", "").replaceAll("//[^\\n]*", "");
	}

	@Test
	public void gotrPath_importsNoOtherPlugin_andUsesNoReflection() throws Exception
	{
		for (String file : GOTR_PATH)
		{
			String src = code(file);
			for (String forbidden : FORBIDDEN)
			{
				assertFalse(file + " must not use " + forbidden, src.contains(forbidden));
			}
		}
	}

	@Test
	public void collector_readsTheGamesOwnGotrState() throws Exception
	{
		String src = code("collectors/StructuredActivityCollector.java");
		assertTrue(src.contains("InterfaceID.GotrHud.CONTENT"));
		assertTrue(src.contains("VarbitID.GOTR_ELEMENTAL_EARNED_THIS_GAME"));
		assertTrue(src.contains("VarbitID.GOTR_CATALYTIC_EARNED_THIS_GAME"));
		assertTrue(src.contains("VarbitID.GOTR_IS_PLAYING"));
		assertTrue(src.contains("ScriptPreFired"));
		assertTrue("power is read from script arguments, never the HUD's power text",
			!src.contains("GotrHud.ENERGY_TITLE"));
	}

	@Test
	public void openRifts_eligibility_andWallet_comeFromTheGameItself() throws Exception
	{
		String collector = code("collectors/StructuredActivityCollector.java");
		assertTrue("open rifts: the HUD script's own arguments", collector.contains("GOTR_SCRIPT_ARG_ACTIVE_ELEMENTAL")
			&& collector.contains("GOTR_SCRIPT_ARG_ACTIVE_CATALYTIC"));
		assertTrue("eligibility: the player's own level and quest state", collector.contains("getBoostedSkillLevel(Skill.RUNECRAFT)")
			&& collector.contains("getState(client)"));
		String altar = code("activity/GotrAltar.java");
		assertTrue(altar.contains("import net.runelite.api.Quest;"));
		String advice = code("activity/GotrAdvice.java");
		assertFalse("advice is pure: no client, no network", advice.contains("Client") || advice.contains("http"));
	}

	@Test
	public void runeRecipe_usesGamevalItemIds() throws Exception
	{
		String src = code("activity/GotrRunes.java");
		assertTrue(src.contains("ItemID.GOTR_GUARDIAN_ESSENCE"));
		assertTrue(src.contains("import net.runelite.api.gameval.ItemID;"));
	}

	@Test
	public void portalTalismans_andRunePouch_areReadNatively() throws Exception
	{
		String talismans = code("activity/GotrPortalTalismans.java");
		assertTrue("portal talismans: gameval item ids, never guessed numbers",
			talismans.contains("ItemID.GOTR_PORTAL_TALISMAN_BLOOD") && !talismans.matches("(?s).*\\b2689[0-9]\\b.*"));
		String runes = code("activity/GotrRunes.java");
		assertTrue("rune pouch: the game's own slot varbits", runes.contains("VarbitID.RUNE_POUCH_TYPE_1")
			&& runes.contains("VarbitID.RUNE_POUCH_QUANTITY_6"));
		String collector = code("collectors/StructuredActivityCollector.java");
		assertTrue("pouch rune types: the game's RUNEPOUCH_RUNE enum", collector.contains("EnumID.RUNEPOUCH_RUNE"));
		assertTrue("talismans come from the inventory container already observed", collector.contains("GotrPortalTalismans.heldIn(inventory)"));
		assertFalse("no Rune Pouch / Inventory Setup plugin", collector.contains("runepouch.") || collector.contains("inventorysetups"));
		String tracker = code("activity/ProductionTracker.java");
		assertFalse("correlation is pure: no client, no timers, no sleeps",
			tracker.contains("Client") || tracker.contains("Thread.sleep") || tracker.contains("Timer"));
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** GotR reward points EARNED this session: positive-delta accounting over a chat-only balance. */
public class GotrRewardPointTrackerTest
{
	private static final String TOTALS = "Total elemental energy: %s. Total catalytic energy: %s.";

	private static String totals(String e, String c)
	{
		return String.format(TOTALS, e, c);
	}

	@Test
	public void firstObservedBalance_isBaselineOnly_preSessionBalanceNeverCounted()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		GotrRewardPointTracker.Gains g = t.onGameMessage(totals("41", "39"));
		assertEquals(0, g.getElementalGained());
		assertEquals(0, g.getCatalyticGained());
		assertEquals(41, g.getElementalBalance());
		assertEquals(39, g.getCatalyticBalance());
	}

	@Test
	public void nextGame_countsEachCurrencyIndependently()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		t.onGameMessage(totals("41", "39"));
		GotrRewardPointTracker.Gains g = t.onGameMessage(totals("48", "47"));
		assertEquals(7, g.getElementalGained());
		assertEquals(8, g.getCatalyticGained());
	}

	@Test
	public void searches_moveTheBaselineDown_soSpendingNeverReducesEarned()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		t.onGameMessage(totals("41", "39"));
		t.onSearch();
		t.onSearch();
		t.onSearch(); // now 38 / 36
		GotrRewardPointTracker.Gains g = t.onGameMessage(totals("44", "42"));
		assertEquals(6, g.getElementalGained());
		assertEquals(6, g.getCatalyticGained());
	}

	@Test
	public void searchWithUnknownBalance_staysUnknown_andNeverGoesNegative()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		t.onSearch();
		assertNull(t.getElementalBalance());
		t.onGameMessage(totals("0", "1"));
		t.onSearch();
		assertEquals(Integer.valueOf(0), t.getElementalBalance());
		assertEquals(Integer.valueOf(0), t.getCatalyticBalance());
	}

	@Test
	public void checkAnswer_isABaseline_soTheFirstGameAfterItCounts()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		assertTrue(t.onCheckText("You have 39 catalytic energy and 41 elemental energy. You can use this energy to search the Rift for 39 more times."));
		GotrRewardPointTracker.Gains g = t.onGameMessage(totals("45", "43"));
		assertEquals(4, g.getElementalGained());
		assertEquals(4, g.getCatalyticGained());
	}

	@Test
	public void checkAnswerInAMessageBox_withLineBreaks_isRead()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		assertTrue(t.onCheckText("You have 10 catalytic energy and 12<br>elemental energy."));
		assertEquals(Integer.valueOf(12), t.getElementalBalance());
		assertEquals(Integer.valueOf(10), t.getCatalyticBalance());
	}

	@Test
	public void thousandsSeparators_andCaseAreTolerated()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		t.onGameMessage(totals("1,041", "1,039"));
		GotrRewardPointTracker.Gains g = t.onGameMessage("total elemental energy: 1,050. total catalytic energy: 1,045.");
		assertEquals(9, g.getElementalGained());
		assertEquals(6, g.getCatalyticGained());
	}

	@Test
	public void unrelatedMessages_changeNothing()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		assertNull(t.onGameMessage("Amount of rifts you have closed: 12."));
		assertNull(t.onGameMessage(null));
		assertFalse(t.onCheckText("You have 5 coins."));
		assertNull(t.getElementalBalance());
	}

	@Test
	public void reset_forgetsBalances_soLoginNeverFabricatesGains()
	{
		GotrRewardPointTracker t = new GotrRewardPointTracker();
		t.onGameMessage(totals("10", "10"));
		t.reset();
		GotrRewardPointTracker.Gains g = t.onGameMessage(totals("90", "90"));
		assertEquals(0, g.getElementalGained());
		assertEquals(0, g.getCatalyticGained());
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

/**
 * RUNES CRAFTED attribution: only a confirmed GotR altar craft (guardian
 * essence consumed + runes gained in one transition, in context, with
 * Runecraft XP on the same/next tick) produces runes, at exact quantities.
 */
public class ProductionTrackerTest
{
	private static final int ESS = ItemID.GOTR_GUARDIAN_ESSENCE;
	private static final int AIR = ItemID.AIRRUNE;
	private static final int COSMIC = ItemID.COSMICRUNE;
	private static final int NATURE = ItemID.NATURERUNE;
	private static final int DEATH = ItemID.DEATHRUNE;
	private static final int BLOOD = ItemID.BLOODRUNE;

	private ProductionTracker t;
	private long xp;

	@Before
	public void setUp()
	{
		t = new ProductionTracker(GotrRunes.RECIPE);
		xp = 1_000_000;
		t.onSkillXp(xp, 0); // login sync: baseline only
	}

	private static Map<Integer, Long> inv(long... idQty)
	{
		Map<Integer, Long> m = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			if (idQty[i + 1] > 0)
			{
				m.put((int) idQty[i], idQty[i + 1]);
			}
		}
		return m;
	}

	/** Runecraft XP first, then the inventory transition (same tick). */
	private Map<Integer, Long> craft(Map<Integer, Long> after, int tick)
	{
		xp += 500;
		assertTrue(t.onSkillXp(xp, tick).isEmpty());
		return t.onInventory(after, tick, true);
	}

	@Test
	public void firstCraft_countsTheExactRuneGain()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		Map<Integer, Long> out = craft(inv(AIR, 300), 2);
		assertEquals(Long.valueOf(300), out.get(AIR));
		assertEquals(1, out.size());
	}

	@Test
	public void xpArrivingAfterTheInventory_onTheNextTick_stillConfirms()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		assertTrue(t.onInventory(inv(COSMIC, 40), 2, true).isEmpty());
		xp += 300;
		Map<Integer, Long> out = t.onSkillXp(xp, 3);
		assertEquals(Long.valueOf(40), out.get(COSMIC));
	}

	@Test
	public void withoutRunecraftXp_theCandidateExpires_neverCounted()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		assertTrue(t.onInventory(inv(COSMIC, 40), 2, true).isEmpty());
		t.onTick(3);
		t.onTick(4);
		xp += 300;
		assertTrue("too late to corroborate", t.onSkillXp(xp, 5).isEmpty());
	}

	@Test
	public void stackAlreadyHeld_onlyTheAddedAmountCounts()
	{
		t.onInventory(inv(ESS, 20, NATURE, 1_000), 1, true);
		Map<Integer, Long> out = craft(inv(NATURE, 1_046), 2);
		assertEquals(Long.valueOf(46), out.get(NATURE));
	}

	@Test
	public void repeatedCrafts_andMultipleRuneTypes_areSeparateExactAmounts()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		assertEquals(Long.valueOf(300), craft(inv(AIR, 300), 2).get(AIR));
		t.onInventory(inv(AIR, 300, ESS, 24), 4, true); // essence pouch emptied: no craft
		assertEquals(Long.valueOf(360), craft(inv(AIR, 660), 6).get(AIR));
		t.onInventory(inv(AIR, 660, ESS, 18), 8, true);
		Map<Integer, Long> both = craft(inv(AIR, 660, COSMIC, 18, NATURE, 9), 10);
		assertEquals(Long.valueOf(18), both.get(COSMIC));
		assertEquals(Long.valueOf(9), both.get(NATURE));
		assertEquals(2, both.size());
	}

	@Test
	public void runeGainWithoutEssenceConsumed_isNeverProduction()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		xp += 100;
		t.onSkillXp(xp, 2);
		assertTrue("reward / pick-up / withdrawal: no essence used",
			t.onInventory(inv(ESS, 20, NATURE, 50), 2, true).isEmpty());
	}

	@Test
	public void droppingOrSpendingRunesAfterwards_neverProducesOrSubtracts()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		craft(inv(AIR, 300), 2);
		assertTrue(t.onInventory(inv(AIR, 100), 4, true).isEmpty());
		assertTrue("picking the dropped runes back up is not production",
			t.onInventory(inv(AIR, 300), 6, true).isEmpty());
	}

	@Test
	public void essenceConsumedWithoutRunes_isNotProduction()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		xp += 50;
		t.onSkillXp(xp, 2);
		assertTrue(t.onInventory(inv(ESS, 10), 2, true).isEmpty());
	}

	@Test
	public void unrelatedItemsAndOtherConsumables_areIgnored()
	{
		t.onInventory(inv(ESS, 20, 995, 1_000), 1, true);
		xp += 50;
		t.onSkillXp(xp, 2);
		assertTrue(t.onInventory(inv(ESS, 20, 995, 5_000), 2, true).isEmpty());
	}

	@Test
	public void outsideTheGameContext_nothingCounts_butTheBaselineFollows()
	{
		t.onInventory(inv(ESS, 20), 1, false);
		xp += 100;
		t.onSkillXp(xp, 2);
		assertTrue(t.onInventory(inv(AIR, 200), 2, false).isEmpty());
		assertTrue("baseline moved: re-entering does not replay it", t.onInventory(inv(AIR, 200), 3, true).isEmpty());
	}

	@Test
	public void reset_loginOrAccountSwitch_firstInventoryAndXpAreBaselineOnly()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		t.reset();
		assertTrue(t.onInventory(inv(AIR, 300), 2, true).isEmpty());
		assertTrue("first XP after reset is a baseline, not a gain", t.onSkillXp(2_000_000, 2).isEmpty());
		t.onInventory(inv(AIR, 300, ESS, 10), 3, true);
		assertTrue("XP baseline was 2,000,000: no gain seen yet", t.onInventory(inv(AIR, 340), 4, true).isEmpty());
		assertEquals(Long.valueOf(40), t.onSkillXp(2_000_400, 4).get(AIR));
	}

	@Test
	public void twoTransitionsOnOneXpGain_bothCount_exactlyOnce()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		assertEquals(Long.valueOf(10), craft(inv(ESS, 10, AIR, 10), 2).get(AIR));
		assertEquals("a second craft on the same tick is still a craft (essence consumed)",
			Long.valueOf(10), t.onInventory(inv(AIR, 20), 2, true).get(AIR));
		assertTrue("nothing is emitted twice", t.onSkillXp(xp + 1, 2).isEmpty());
	}

	// ---- rapid crafting: craft -> essence-pouch refill -> craft ----------

	private long total(Map<Integer, Long> out, int id)
	{
		return out.getOrDefault(id, 0L);
	}

	@Test
	public void rapidCraft_refillBetween_xpAfterBoth_bothBatchesCount()
	{
		long sum = 0;
		t.onInventory(inv(ESS, 28), 1, true);
		sum += total(t.onInventory(inv(DEATH, 30), 10, true), DEATH);       // craft A, XP not seen yet
		sum += total(t.onInventory(inv(DEATH, 30, ESS, 20), 10, true), DEATH); // refill from the pouch
		sum += total(t.onInventory(inv(DEATH, 52), 11, true), DEATH);       // craft B
		xp += 1_000;
		sum += total(t.onSkillXp(xp, 11), DEATH);                            // one coalesced XP update
		assertEquals(52, sum);
	}

	@Test
	public void rapidCraft_bothXpUpdatesBeforeEitherInventory_bothBatchesCount()
	{
		long sum = 0;
		t.onInventory(inv(ESS, 28), 1, true);
		xp += 500;
		sum += total(t.onSkillXp(xp, 10), DEATH);
		xp += 400;
		sum += total(t.onSkillXp(xp, 11), DEATH);
		sum += total(t.onInventory(inv(DEATH, 30), 11, true), DEATH);
		sum += total(t.onInventory(inv(DEATH, 30, ESS, 20), 11, true), DEATH);
		sum += total(t.onInventory(inv(DEATH, 52), 12, true), DEATH);
		assertEquals("old one-XP-one-transition model counted only 30", 52, sum);
	}

	@Test
	public void threeRapidCrafts_differentRunes_exactTotals()
	{
		Map<Integer, Long> got = new HashMap<>();
		t.onInventory(inv(ESS, 28), 1, true);
		xp += 500;
		t.onSkillXp(xp, 10).forEach((k, v) -> got.merge(k, v, Long::sum));
		t.onInventory(inv(NATURE, 30), 10, true).forEach((k, v) -> got.merge(k, v, Long::sum));
		t.onInventory(inv(NATURE, 30, ESS, 26), 11, true).forEach((k, v) -> got.merge(k, v, Long::sum));
		t.onInventory(inv(NATURE, 58), 12, true).forEach((k, v) -> got.merge(k, v, Long::sum));
		t.onInventory(inv(NATURE, 58, ESS, 12), 13, true).forEach((k, v) -> got.merge(k, v, Long::sum));
		xp += 400;
		t.onSkillXp(xp, 13).forEach((k, v) -> got.merge(k, v, Long::sum));
		t.onTick(14);
		t.onInventory(inv(NATURE, 58, COSMIC, 13), 14, true).forEach((k, v) -> got.merge(k, v, Long::sum));
		xp += 200;
		t.onSkillXp(xp, 14).forEach((k, v) -> got.merge(k, v, Long::sum));
		assertEquals(Long.valueOf(58), got.get(NATURE));
		assertEquals(Long.valueOf(13), got.get(COSMIC));
		assertEquals(2, got.size());
	}

	@Test
	public void rewardRunesAfterACraft_outsideTheWindow_neverCount()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		assertEquals(Long.valueOf(40), craft(inv(COSMIC, 40), 2).get(COSMIC));
		t.onTick(5);
		xp += 10;
		t.onSkillXp(xp, 5);
		assertTrue("reward/pick-up runes later: no essence consumed nearby",
			t.onInventory(inv(COSMIC, 90, NATURE, 25), 6, true).isEmpty());
	}

	@Test
	public void correlationStateIsBounded()
	{
		t.onInventory(inv(ESS, 1_000), 1, true);
		for (int tick = 2; tick < 500; tick++)
		{
			t.onTick(tick);
			t.onInventory(inv(ESS, 1_000 - tick), tick, true);
		}
		assertTrue(t.heldTicks() <= 2 * ProductionTracker.XP_WINDOW_TICKS + 1);
	}

	// ---- rune pouch as a second destination ------------------------------

	@Test
	public void wholeCraftIntoTheRunePouch_countsExactly()
	{
		t.onInventory(inv(ESS, 28), 1, true);
		t.onSecondaryStore(inv(DEATH, 800), 1, true);
		xp += 500;
		assertTrue(t.onSkillXp(xp, 2).isEmpty());
		assertTrue("essence consumed, nothing landed in the inventory", t.onInventory(inv(), 2, true).isEmpty());
		assertEquals(Long.valueOf(56), t.onSecondaryStore(inv(DEATH, 856), 2, true).get(DEATH));
	}

	@Test
	public void craftSplitBetweenInventoryAndPouch_countsOnce_inEitherOrder()
	{
		t.onInventory(inv(ESS, 28), 1, true);
		t.onSecondaryStore(inv(DEATH, 800), 1, true);
		xp += 500;
		t.onSkillXp(xp, 2);
		long sum = total(t.onSecondaryStore(inv(DEATH, 860), 2, true), DEATH)
			+ total(t.onInventory(inv(DEATH, 40), 2, true), DEATH);
		assertEquals(100, sum);

		// Reverse order, XP last, pouch update on the adjacent tick.
		t.onInventory(inv(DEATH, 40, ESS, 28), 4, true);
		sum = total(t.onInventory(inv(DEATH, 80), 5, true), DEATH);
		sum += total(t.onSecondaryStore(inv(DEATH, 920), 6, true), DEATH);
		xp += 500;
		sum += total(t.onSkillXp(xp, 6), DEATH);
		assertEquals(100, sum);
	}

	@Test
	public void newRuneTypeIntoAnEmptyPouchSlot_counts()
	{
		t.onInventory(inv(ESS, 10), 1, true);
		t.onSecondaryStore(inv(DEATH, 800), 1, true);
		xp += 500;
		t.onSkillXp(xp, 2);
		t.onInventory(inv(), 2, true);
		Map<Integer, Long> out = t.onSecondaryStore(inv(DEATH, 800, BLOOD, 12), 2, true);
		assertEquals(Long.valueOf(12), out.get(BLOOD));
		assertEquals(1, out.size());
	}

	@Test
	public void rapidCraftsIntoThePouch_bothCount()
	{
		long sum = 0;
		t.onInventory(inv(ESS, 28), 1, true);
		t.onSecondaryStore(inv(DEATH, 800), 1, true);
		sum += total(t.onInventory(inv(), 10, true), DEATH);
		sum += total(t.onSecondaryStore(inv(DEATH, 830), 10, true), DEATH);
		xp += 500;
		sum += total(t.onSkillXp(xp, 10), DEATH);
		sum += total(t.onInventory(inv(ESS, 20), 11, true), DEATH);
		sum += total(t.onInventory(inv(), 12, true), DEATH);
		xp += 400;
		sum += total(t.onSkillXp(xp, 12), DEATH);
		sum += total(t.onSecondaryStore(inv(DEATH, 852), 12, true), DEATH);
		assertEquals(52, sum);
	}

	@Test
	public void movingRunesBetweenInventoryAndPouch_isNeverProduction()
	{
		t.onInventory(inv(ESS, 20, DEATH, 100), 1, true);
		t.onSecondaryStore(inv(DEATH, 800), 1, true);
		xp += 500;
		t.onSkillXp(xp, 2);
		t.onInventory(inv(ESS, 10, DEATH, 100), 2, true); // essence used (e.g. into an essence pouch)
		assertTrue("inventory -> pouch, same tick", t.onInventory(inv(ESS, 10), 2, true).isEmpty());
		assertTrue(t.onSecondaryStore(inv(DEATH, 900), 2, true).isEmpty());
		assertTrue("pouch -> inventory", t.onSecondaryStore(inv(DEATH, 850), 3, true).isEmpty());
		assertTrue(t.onInventory(inv(ESS, 10, DEATH, 50), 3, true).isEmpty());
	}

	@Test
	public void pouchGainWithoutAnyCraft_isNeverProduction()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		t.onSecondaryStore(inv(), 1, true);
		xp += 100;
		t.onSkillXp(xp, 2);
		assertTrue("reward/picked-up runes put into the pouch", t.onSecondaryStore(inv(NATURE, 50), 2, true).isEmpty());
	}

	@Test
	public void pouchBaseline_afterResetOrLogin_isNeverProduction()
	{
		t.onInventory(inv(ESS, 20), 1, true);
		t.reset();
		t.onSkillXp(xp, 2);
		t.onInventory(inv(ESS, 10), 2, true);
		assertTrue("first pouch snapshot is the baseline", t.onSecondaryStore(inv(DEATH, 900), 2, true).isEmpty());
		xp += 100;
		t.onSkillXp(xp, 3);
		assertTrue(t.onSecondaryStore(inv(DEATH, 900), 3, true).isEmpty());
	}

	@Test
	public void everyRuneTypeIsRecognised_essenceIsTheOnlyInput()
	{
		assertTrue(GotrRunes.RUNE_ITEM_IDS.contains(ItemID.BLOODRUNE));
		assertTrue(GotrRunes.RUNE_ITEM_IDS.contains(ItemID.DEATHRUNE));
		assertTrue(GotrRunes.RUNE_ITEM_IDS.contains(ItemID.LAWRUNE));
		assertTrue(GotrRunes.RUNE_ITEM_IDS.contains(ItemID.MISTRUNE));
		assertEquals(1, GotrRunes.RECIPE.getConsumedItemIds().size());
		assertTrue(GotrRunes.RECIPE.getConsumedItemIds().contains(ESS));
		assertEquals("runecraft", GotrRunes.RECIPE.getCorroboratingSkill());
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

/** Catalog integrity and the indexed lookups the collector/classifier rely on. */
public class StructuredActivityRegistryTest
{
	private final StructuredActivityRegistry registry = StructuredActivityRegistry.defaults();

	@Test
	public void catalogKeysAndRegions_matchAuditedRuneLiteData()
	{
		Set<String> keys = new HashSet<>();
		for (StructuredActivityDefinition d : registry.all())
		{
			keys.add(d.getKey());
		}
		assertEquals(new HashSet<>(Arrays.asList("guardians_of_the_rift", "tempoross", "pest_control",
			"giants_foundry", "barrows", "wintertodt")), keys);

		assertEquals("guardians_of_the_rift", registry.forRegion(14484).getKey());
		assertEquals("tempoross", registry.forRegion(12076).getKey());
		assertEquals("tempoross", registry.forRegion(12588).getKey());
		assertEquals("pest_control", registry.forRegion(10536).getKey());
		assertEquals("giants_foundry", registry.forRegion(13491).getKey());
		assertEquals("barrows", registry.forRegion(14131).getKey());
