package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

import org.junit.Test;

/** ARMED / ACTIVE / LOCKED semantics of the transient recognition tracker. */
public class StructuredActivityTrackerTest
{
	private final StructuredActivityRegistry registry = StructuredActivityRegistry.defaults();
	private final StructuredActivityDefinition gotr = registry.byKey(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT);
	private final StructuredActivityDefinition tempoross = registry.byKey(StructuredActivityCatalog.TEMPOROSS);

	@Test
	public void startsOutside_andConfirmationsOutsideAreIgnored()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		assertEquals(RecognitionState.OUTSIDE, t.getState());
		t.confirm(1L);
		assertEquals(RecognitionState.OUTSIDE, t.getState());
		assertNull(t.getDefinition());
	}

	@Test
	public void locationArmsOnly()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		assertEquals(RecognitionState.ARMED, t.getState());
		assertSame(gotr, t.getDefinition());
		assertEquals(0, t.getDistinctConfirmations());
		// A repeated location observation is not a confirmation.
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		assertEquals(RecognitionState.ARMED, t.getState());
	}

	@Test
	public void firstEvidenceActivates_distinctTicksLock()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		t.confirm(10L);
		assertEquals(RecognitionState.ACTIVE, t.getState());
		t.confirm(11L);
		assertEquals(RecognitionState.ACTIVE, t.getState());
		t.confirm(12L);
		assertEquals(RecognitionState.LOCKED, t.getState());
		assertEquals(StructuredActivityTracker.LOCK_DISTINCT_CONFIRMATIONS, t.getDistinctConfirmations());
	}

	@Test
	public void sameTickDuplicatesCountOnce()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		for (int i = 0; i < 10; i++)
		{
			t.confirm(42L);
		}
		assertEquals(1, t.getDistinctConfirmations());
		assertEquals(RecognitionState.ACTIVE, t.getState());
		t.confirm(43L);
		t.confirm(43L);
		assertEquals(RecognitionState.ACTIVE, t.getState());
	}

	@Test
	public void leavingClears_reEnteringReArmsFromScratch()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		t.confirm(1L);
		t.confirm(2L);
		t.confirm(3L);
		t.onLocation(null, null);
		assertEquals(RecognitionState.OUTSIDE, t.getState());
		assertNull(t.getPolicy());
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		assertEquals(RecognitionState.ARMED, t.getState());
		assertEquals(0, t.getDistinctConfirmations());
	}

	@Test
	public void movingBetweenRegionsOfOneActivityKeepsRecognition_policyFollowsRegion()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(tempoross, LocationPolicy.EXCLUSIVE);
		t.confirm(1L);
		t.confirm(2L);
		t.confirm(3L);
		t.onLocation(tempoross, LocationPolicy.NON_EXCLUSIVE);
		assertEquals(RecognitionState.LOCKED, t.getState());
		assertEquals(LocationPolicy.NON_EXCLUSIVE, t.getPolicy());
	}

	@Test
	public void enteringADifferentActivityReArms()
	{
		StructuredActivityTracker t = new StructuredActivityTracker();
		t.onLocation(gotr, LocationPolicy.EXCLUSIVE);
		t.confirm(1L);
		t.onLocation(tempoross, LocationPolicy.EXCLUSIVE);
		assertEquals(RecognitionState.ARMED, t.getState());
		assertSame(tempoross, t.getDefinition());
	}
}

package com.osrstelemetry.plugin.activity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.collectors.StructuredActivityCollector;
import java.lang.reflect.Constructor;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.Test;

/**
 * HARD RULE: Spyglass's Tempoross data comes only from native client state
 * (Jagex interface 437, varbits, game messages, location) -- never from
 * another RuneLite plugin, its overlay, its state, or reflection. These
 * checks fail the build if the Tempoross path ever grows such a dependency.
 */
public class TemporossNativeIndependenceTest
{
	private static final String MAIN = "src/main/java/com/osrstelemetry/plugin/";
	private static final String[] TEMPOROSS_PATH = {
		"activity/TemporossGameState.java",
		"activity/TemporossGameTracker.java",
		"collectors/StructuredActivityCollector.java",
		"ui/CurrentSessionView.java",
	};
	private static final String[] FORBIDDEN = {
		"net.runelite.client.plugins.", "PluginManager", "OverlayManager", "InfoBoxManager",
		"setAccessible(", "getDeclaredField(", "getDeclaredMethod(", "Class.forName(",
	};

	private static String source(String relative) throws Exception
	{
		Path p = Paths.get(MAIN + relative);
		return new String(Files.readAllBytes(p), StandardCharsets.UTF_8);
	}

	@Test
	public void temporossPath_importsNoOtherPlugin_andUsesNoReflection() throws Exception
	{
		for (String file : TEMPOROSS_PATH)
		{
			// Code only: prose may mention other plugins (e.g. to say why they are NOT used).
			String src = source(file).replaceAll("(?s)/\\*.*?\\*/", "").replaceAll("//[^\\n]*", "");
			for (String forbidden : FORBIDDEN)
			{
				assertFalse(file + " must not use " + forbidden, src.contains(forbidden));
			}
		}
	}

	@Test
	public void collector_readsTheNativeTitleTextAndVarbits()
	{
		String src;
		try
		{
			src = source("collectors/StructuredActivityCollector.java");
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
		assertTrue(src.contains("InterfaceID.TemporossHud.ENERGY_TITLE"));
		assertTrue(src.contains("InterfaceID.TemporossHud.ESSENCE_TITLE"));
		assertTrue(src.contains("InterfaceID.TemporossHud.STORM_INTENSITY_TITLE"));
		assertTrue(src.contains("VarbitID.TEMPOROSS_CURRENT_POINTS"));
		assertTrue(src.contains("VarbitID.TEMPOROSS_REWARDPERMITS"));
	}

	@Test
	public void collector_isConstructedFromClientAndLedgerOnly_noPluginService()
	{
		for (Constructor<?> c : StructuredActivityCollector.class.getDeclaredConstructors())
		{
			for (Class<?> type : c.getParameterTypes())
			{
				assertFalse(c + " takes " + type.getName(), type.getName().startsWith("net.runelite.client.plugins."));
			}
		}
	}

	@Test
	public void tracker_isPure_andParsesOnlyTheKillCountMessage()
	{
		assertEquals(Integer.valueOf(1_234), TemporossGameTracker.killCountOf("Your Tempoross kill count is: 1,234."));
		assertNull(TemporossGameTracker.killCountOf("Your Zulrah kill count is: 5."));
		assertNull(TemporossGameTracker.killCountOf(null));
		TemporossGameTracker t = new TemporossGameTracker();
		assertNull("not a kill count", t.onGameMessage("You have helped to subdue the spirit!", 3_000));
		TemporossGameTracker.Result r = t.onGameMessage("Your Tempoross kill count is: 3.", 3_000);
		assertFalse("nothing was observed before: not trusted", r.isObservedFromStart());
		assertEquals(Integer.valueOf(3_000), r.getPoints());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.events.EventType;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as everywhere else
 * in this project. These specifically target the pure static methods
 * extracted from ActivityKillCountCollector, which need no RuneLite
 * Client and so are the one part of that collector genuinely
 * testable in isolation.
 */
public class ActivityKillCountCollectorTest
{
	@Test
	public void verifiedRaidsClassifyAsRaidCompletion()
	{
		assertEquals(EventType.RAID_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Chambers of Xeric")));
		assertEquals(EventType.RAID_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Theatre of Blood")));
		assertEquals(EventType.RAID_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Tombs of Amascut")));
	}

	@Test
	public void unverifiedActivitiesClassifyAsGenericCompletionNotRaid()
	{
		// This is the exact bug the review flagged: a "completion
		// count" message alone must not become RAID_COMPLETION just
		// because it matched the same regex pattern as a real raid.
		assertEquals(EventType.ACTIVITY_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Corrupted Gauntlet")));
		assertEquals(EventType.ACTIVITY_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Barbarian Assault")));
		assertEquals(EventType.ACTIVITY_COMPLETION,
			ActivityKillCountCollector.classifyCompletion(ActivityKillCountCollector.slugify("Zulrah")));
	}

	@Test
	public void slugifyIsStableAndIdempotentAcrossDuplicateMessages()
	{
		// Simulates the same completion message being observed twice
		// (e.g. two kills in a row) — must slugify identically both
		// times so the activity is updated in place, not duplicated.
		String first = ActivityKillCountCollector.slugify("Tombs of Amascut");
		String second = ActivityKillCountCollector.slugify("Tombs of Amascut");
		assertEquals(first, second);
		assertEquals("tombs_of_amascut", first);
	}

	@Test
	public void slugifyNormalizesPunctuationAndCase()
	{
		assertEquals("chambers_of_xeric", ActivityKillCountCollector.slugify("Chambers of Xeric"));
		assertEquals("theatre_of_blood", ActivityKillCountCollector.slugify("  Theatre of Blood  "));
	}

	@Test
	public void firstObservationOfAnActivityAlwaysAdvances()
	{
		assertTrue(ActivityKillCountCollector.isAdvancing(null, 1));
	}

	@Test
	public void higherCountAdvancesLowerOrEqualDoesNot()
	{
		assertTrue("a strictly higher count is real progress", ActivityKillCountCollector.isAdvancing(42, 43));
		assertFalse("the exact same count observed again is a duplicate, not progress",
			ActivityKillCountCollector.isAdvancing(42, 42));
		assertFalse("a lower count is stale/out-of-order, not progress",
			ActivityKillCountCollector.isAdvancing(42, 41));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as everywhere else
 * in this project.
 *
 * Split deliberately in two, matching BankSnapshotBaseline's own
 * split: pure decision-rule tests (A-F) need no I/O and no Client;
 * persisted-baseline tests (G-J) need only LocalStateStore + real
 * files, still no Client. Test K is not a new test here — see the
 * comment on it below for why the existing
 * LocalStateStoreTest already establishes the guarantee it asks for,
 * structurally, by construction of where recordBankBaseline() was
 * placed in ContainerCollector (inside the write's own onWritten
 * success-only callback) — fabricating a second, redundant
 * integration test for the same guarantee (which would need a full
 * ContainerCollector + a mocked Client, and this project has no
 * Mockito dependency and wasn't asked to add one) would not add real
 * coverage beyond what already exists.
 */
public class BankSnapshotBaselineTest
{
	private static final Duration MAX_AGE = Duration.ofMinutes(10);

	private static StorageState.StorageItem item(int slot, int itemId, String name, int quantity)
	{
		return new StorageState.StorageItem(slot, itemId, name, quantity, null);
	}

	private static List<StorageState.StorageItem> bankOf(StorageState.StorageItem... items)
	{
		return Arrays.asList(items);
	}

	// ---- A-F: pure decision rule, no I/O ----

	@Test
	public void a_firstObservation_noBaseline_alwaysWrites()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(
			BankSnapshotBaseline.absent(), items, Instant.now(), MAX_AGE));
	}

	@Test
	public void b_identicalContents_underTenMinutes_doesNotWrite()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		Instant baselineTime = Instant.now().minus(Duration.ofMinutes(5));
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(items, baselineTime);

		assertFalse(BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, items, Instant.now(), MAX_AGE));
	}

	@Test
	public void c_identicalContents_atOrAfterTenMinutes_writesRefresh()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		Instant now = Instant.now();

		// Exactly 10 minutes — ">= 10 minutes" per spec, boundary included.
		BankSnapshotBaseline exactlyTen = BankSnapshotBaseline.of(items, now.minus(Duration.ofMinutes(10)));
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(exactlyTen, items, now, MAX_AGE));

		BankSnapshotBaseline overTen = BankSnapshotBaseline.of(items, now.minus(Duration.ofMinutes(11)));
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(overTen, items, now, MAX_AGE));
	}

	@Test
	public void d_quantityChange_insideWindow_alwaysWrites()
	{
		List<StorageState.StorageItem> baselineItems = bankOf(item(0, 995, "Coins", 1000));
		List<StorageState.StorageItem> candidateItems = bankOf(item(0, 995, "Coins", 999));
		Instant now = Instant.now();
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(baselineItems, now.minus(Duration.ofSeconds(1)));

		assertTrue("a real quantity change must write even seconds after the last snapshot",
			BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, candidateItems, now, MAX_AGE));
	}

	@Test
	public void e_itemChange_insideWindow_alwaysWrites()
	{
		List<StorageState.StorageItem> baselineItems = bankOf(item(0, 995, "Coins", 1000));
		List<StorageState.StorageItem> candidateItems = bankOf(item(0, 1050, "Iron ore", 1000));
		Instant now = Instant.now();
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(baselineItems, now.minus(Duration.ofSeconds(1)));

		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, candidateItems, now, MAX_AGE));
	}

	@Test
	public void f_slotReorder_insideWindow_alwaysWrites()
	{
		List<StorageState.StorageItem> baselineItems = bankOf(
			item(0, 995, "Coins", 1000),
			item(1, 1050, "Iron ore", 5)
		);
		// Same two items and quantities, but swapped slots — a real
		// bank reorganization, this must count as a
		// changed state.
		List<StorageState.StorageItem> candidateItems = bankOf(
			item(0, 1050, "Iron ore", 5),
			item(1, 995, "Coins", 1000)
		);
		Instant now = Instant.now();
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(baselineItems, now.minus(Duration.ofSeconds(1)));

		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, candidateItems, now, MAX_AGE));
	}

	// ---- G-J: persisted-baseline loading, real files, no Client ----

	private static final long TEST_ACCOUNT_HASH = 888_777_111L;
	private static final long OTHER_ACCOUNT_HASH = 888_777_222L;
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private Path tempRoot;

	/**
	 * A brand-new temp directory per test, rooted via TestFilepaths
	 * (see its own javadoc for why Filepath.Unchecked is justified here
	 * and nowhere else) and installed as TelemetryPaths' shared root
	 * BEFORE the test body runs -- this gives every test full account
	 * isolation for free, without the old fixed-account-hash
	 * delete-before-and-after dance the previous java.io.File-based
	 * version of this test needed.
	 */
	@Before
	public void setUp() throws Exception
	{
		tempRoot = Files.createTempDirectory("bank-snapshot-baseline-test");
		TelemetryPaths.init(TestFilepaths.rooted(tempRoot));
		store = new LocalStateStore(GSON);
		store.start();
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteRecursively(tempRoot);
	}

	private static void deleteRecursively(Path path) throws Exception
	{
		if (!Files.exists(path))
		{
			return;
		}
		try (Stream<Path> walk = Files.walk(path))
		{
			walk.sorted(Comparator.reverseOrder()).forEach(p -> p.toFile().delete());
		}
	}

	/** Writes a fixture snapshot + a bank.json pointer referencing it, exactly matching what ContainerCollector itself produces. */
	private String writeFixtureSnapshot(long accountHash, List<StorageState.StorageItem> items, Instant observedAt)
	{
		String snapshotId = "fixture-" + observedAt.toEpochMilli();
		StorageState snapshot = new StorageState("bank");
		snapshot.setItems(items);
		snapshot.setLastObservedAt(observedAt.toString());
		snapshot.setContinuouslyObservable(false);
		snapshot.setLatestSnapshotId(snapshotId);
		assertTrue(store.writeAndWait(TelemetryPaths.bankSnapshotFile(accountHash, snapshotId), snapshot, 2000));

		StorageState pointer = new StorageState("bank");
		pointer.setItems(items);
		pointer.setLastObservedAt(observedAt.toString());
		pointer.setContinuouslyObservable(false);
		pointer.setLatestSnapshotId(snapshotId);
		assertTrue(store.writeAndWait(TelemetryPaths.stateFile(accountHash, "bank"), pointer, 2000));

		return snapshotId;
	}

	@Test
	public void g_validPersistedBaselineUnderTenMinutes_suppressesDuplicate()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		String snapshotId = writeFixtureSnapshot(TEST_ACCOUNT_HASH, items, Instant.now().minus(Duration.ofMinutes(5)));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertTrue("baseline should have loaded from the fixture files", loaded.isPresent());
		assertFalse(BankSnapshotBaseline.shouldWriteNewSnapshot(loaded, items, Instant.now(), MAX_AGE));
		assertEquals("Phase 1 requirement A: a persisted baseline must retain its snapshotId",
			snapshotId, loaded.getSnapshotId());
	}

	/** Test A (Phase 1): loadFrom() must carry the resolved snapshotId
	 * into the returned baseline, not just items/createdAt — this is
	 * what lets ContainerCollector re-stamp bank.json's latestSnapshotId
	 * on ordinary writes and dedup-skip refreshes without a second disk
	 * read. */
	@Test
	public void a2_loadedBaseline_carriesSnapshotIdSeparatelyFromContents()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		String snapshotId = writeFixtureSnapshot(TEST_ACCOUNT_HASH, items, Instant.now().minus(Duration.ofMinutes(1)));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertTrue(loaded.isPresent());
		assertEquals(snapshotId, loaded.getSnapshotId());

		// A different fixture (different snapshotId, different content)
		// for a second account must not collide. snapshotId is derived from
		// observedAt.toEpochMilli() (see writeFixtureSnapshot), so the two
		// fixture timestamps must be forced at least a second apart -- two
		// bare back-to-back Instant.now() calls can legitimately land in the
		// same millisecond on a fast machine, which made this assertion
		// flaky for a reason that had nothing to do with real collision
		// handling.
		List<StorageState.StorageItem> otherItems = bankOf(item(0, 1050, "Iron ore", 50));
		String otherSnapshotId =
			writeFixtureSnapshot(OTHER_ACCOUNT_HASH, otherItems, Instant.now().minus(Duration.ofMinutes(1)).minusSeconds(1));
		BankSnapshotBaseline otherLoaded = BankSnapshotBaseline.loadFrom(store, OTHER_ACCOUNT_HASH);
		assertEquals(otherSnapshotId, otherLoaded.getSnapshotId());
		assertNotEquals(snapshotId, otherSnapshotId);
	}

	@Test
	public void h_validPersistedBaselineOverTenMinutes_createsRefresh()
	{
		List<StorageState.StorageItem> items = bankOf(item(0, 995, "Coins", 1000));
		writeFixtureSnapshot(TEST_ACCOUNT_HASH, items, Instant.now().minus(Duration.ofMinutes(15)));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertTrue(loaded.isPresent());
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(loaded, items, Instant.now(), MAX_AGE));
	}

	@Test
	public void i_missingBankJson_failsOpen()
	{
		// Nothing written for this account at all.
		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertFalse(loaded.isPresent());
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(
			loaded, bankOf(item(0, 995, "Coins", 1)), Instant.now(), MAX_AGE));
	}

	@Test
	public void i_bankJsonWithoutLatestSnapshotId_failsOpen()
	{
		StorageState pointer = new StorageState("bank");
		pointer.setItems(bankOf(item(0, 995, "Coins", 1000)));
		pointer.setLastObservedAt(Instant.now().toString());
		pointer.setContinuouslyObservable(false);
		// latestSnapshotId deliberately left null — simulates a
		// bank.json written before any immutable snapshot ever
		// succeeded (e.g. the very first debounce window is still
		// pending, or every snapshot attempt so far has failed).
		assertTrue(store.writeAndWait(TelemetryPaths.stateFile(TEST_ACCOUNT_HASH, "bank"), pointer, 2000));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertFalse(loaded.isPresent());
	}

	@Test
	public void i_pointerReferencesMissingSnapshotFile_failsOpen()
	{
		StorageState pointer = new StorageState("bank");
		pointer.setItems(bankOf(item(0, 995, "Coins", 1000)));
		pointer.setLastObservedAt(Instant.now().toString());
		pointer.setContinuouslyObservable(false);
		pointer.setLatestSnapshotId("this-snapshot-id-does-not-exist-on-disk");
		assertTrue(store.writeAndWait(TelemetryPaths.stateFile(TEST_ACCOUNT_HASH, "bank"), pointer, 2000));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertFalse("a dangling latestSnapshotId must fail open, not throw", loaded.isPresent());
	}

	@Test
	public void i_corruptSnapshotFile_failsOpen() throws Exception
	{
		String snapshotId = "corrupt-fixture";
		StorageState pointer = new StorageState("bank");
		pointer.setItems(bankOf(item(0, 995, "Coins", 1000)));
		pointer.setLastObservedAt(Instant.now().toString());
		pointer.setContinuouslyObservable(false);
		pointer.setLatestSnapshotId(snapshotId);
		assertTrue(store.writeAndWait(TelemetryPaths.stateFile(TEST_ACCOUNT_HASH, "bank"), pointer, 2000));

		// Write genuinely malformed JSON directly, bypassing the store,
		// to simulate corruption (a truncated write, a bad upgrade, etc).
		Filepath snapshotFile = TelemetryPaths.bankSnapshotFile(TEST_ACCOUNT_HASH, snapshotId);
		snapshotFile.write("{ this is not valid json".getBytes(StandardCharsets.UTF_8));

		BankSnapshotBaseline loaded = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		assertFalse("malformed JSON must fail open, not throw", loaded.isPresent());
	}

	@Test
	public void j_accountSwitch_neverCrossContaminatesBaselines()
	{
		List<StorageState.StorageItem> accountAItems = bankOf(item(0, 995, "Coins", 1_000_000));
		writeFixtureSnapshot(TEST_ACCOUNT_HASH, accountAItems, Instant.now().minus(Duration.ofMinutes(2)));
		// OTHER_ACCOUNT_HASH deliberately has nothing written at all.

		BankSnapshotBaseline accountABaseline = BankSnapshotBaseline.loadFrom(store, TEST_ACCOUNT_HASH);
		BankSnapshotBaseline accountBBaseline = BankSnapshotBaseline.loadFrom(store, OTHER_ACCOUNT_HASH);

		assertTrue("account A has a real persisted baseline", accountABaseline.isPresent());
		assertFalse("account B must never see account A's baseline", accountBBaseline.isPresent());

		// And account B's first observation must always write, exactly
		// as if it were genuinely the first-ever observation — which,
		// from account B's perspective, it is.
		assertTrue(BankSnapshotBaseline.shouldWriteNewSnapshot(
			accountBBaseline, accountAItems, Instant.now(), MAX_AGE));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.storage.TestFilepaths;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as elsewhere in this
 * project. Thresholds are passed as parameters specifically so these
 * tests can use tiny fixture files (tens of bytes) instead of building
 * real 100MB fixtures — see BankSnapshotRetention.pruneIfNeeded()'s
 * signature.
 */
public class BankSnapshotRetentionTest
{
	private File dir;

	@Before
	public void setUp() throws IOException
	{
		dir = Files.createTempDirectory("bank-snapshots-retention-test").toFile();
	}

	@After
	public void tearDown()
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				f.setWritable(true);
				f.delete();
			}
		}
		dir.delete();
	}

	/** Writes a fixture snapshot file with a body padded to exactly
	 * `size` bytes, with a distinct, controllable mtime so ordering is
	 * deterministic regardless of how fast the test runs. */
	private File fixture(String snapshotId, int size, long mtimeMs) throws IOException
	{
		File f = new File(dir, snapshotId + ".json");
		byte[] body = new byte[size];
		java.util.Arrays.fill(body, (byte) '0');
		Files.write(f.toPath(), body);
		f.setLastModified(mtimeMs);
		return f;
	}

	@Test
	public void underMax_noPruningOccurs() throws Exception
	{
		fixture("a", 100, 1_000);
		fixture("b", 100, 2_000);

		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "b", 1000, 900);

		assertEquals("nothing should be pruned when total is already under max", 2, countFiles());
	}

	@Test
	public void overMax_prunesOldestFirstUntilAtOrUnderTarget() throws Exception
	{
		// Four 100-byte files -> 400 bytes total, well over a tiny
		// max/target pair, forces pruning down to <= target.
		fixture("oldest", 100, 1_000);
		fixture("second", 100, 2_000);
		fixture("third", 100, 3_000);
		fixture("newest", 100, 4_000);

		// max=300 (so 400 > 300 triggers pruning), target=200.
		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "newest", 300, 200);

		assertEquals("must prune down to at or under the 200-byte target", 200, totalBytes());
		assertTrue("the two oldest files must be the ones removed",
			!exists("oldest") && !exists("second"));
		assertTrue(exists("third") && exists("newest"));
	}

	@Test
	public void protectedLatestSnapshot_isNeverDeleted_evenIfOldest() throws Exception
	{
		// The PROTECTED file is deliberately the OLDEST one — a real
		// scenario is rare (the just-written snapshot is normally the
		// newest) but the guarantee must hold unconditionally.
		fixture("protected-oldest", 100, 1_000);
		fixture("b", 100, 2_000);
		fixture("c", 100, 3_000);
		fixture("d", 100, 4_000);

		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "protected-oldest", 300, 100);

		assertTrue("the protected snapshot must survive pruning no matter its age",
			exists("protected-oldest"));
		// Directory is allowed to remain above the 100-byte target
		// specifically because the protected file couldn't be removed
		// — per spec, this is accepted rather than deleting it.
		assertTrue("staying above target to protect the live pointer is acceptable",
			totalBytes() >= 100);
	}

	@Test
	public void nonJsonAndDirectoryEntries_areIgnoredSafely() throws Exception
	{
		fixture("a", 100, 1_000);
		fixture("b", 100, 2_000);

		// An unrelated file that must not be counted or touched.
		File stray = new File(dir, "notes.txt");
		Files.write(stray.toPath(), "not a snapshot".getBytes(StandardCharsets.UTF_8));

		// A subdirectory that happens to end in .json — must not be
		// treated as a snapshot file (would crash length()/delete()
		// semantics for a directory otherwise).
		File weirdDir = new File(dir, "oops.json");
		weirdDir.mkdir();
		Files.write(new File(weirdDir, "inner.json").toPath(), "irrelevant".getBytes(StandardCharsets.UTF_8));

		// max=1 forces an attempt to prune everything possible.
		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "b", 1, 0);

		assertTrue("the stray non-.json file must be left alone", stray.exists());
		assertTrue("the directory entry must be left alone, not crash pruning", weirdDir.exists());
		assertTrue("the protected snapshot must still survive", exists("b"));
	}

	@Test
	public void pruningOrder_isDeterministic_tiedMtimeBrokenByName() throws Exception
	{
		// Identical mtimes — the only way ordering can still be
		// deterministic is the filename tiebreak.
		fixture("zzz", 100, 5_000);
		fixture("aaa", 100, 5_000);
		fixture("mmm", 100, 5_000);

		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "zzz", 200, 100);

		// "aaa" sorts first alphabetically, so with all mtimes tied it
		// must be the one pruned first.
		assertTrue("alphabetically-first name must be pruned first on a full mtime tie", !exists("aaa"));
	}

	@Test
	public void deletionFailure_isNonFatal_andLeavesFileInPlace() throws Exception
	{
		// Windows-oriented assumption (this is a RuneLite/Windows
		// project — see harness notes): a read-only file cannot be
		// deleted by File.delete() there. On a platform where deletion
		// is governed purely by directory permissions instead, this
		// particular file may still get deleted — the assertion that
		// matters either way is the one below: pruning itself must not
		// throw, regardless of whether the individual delete succeeded.
		File locked = fixture("locked", 100, 1_000);
		locked.setReadOnly();
		fixture("also-old", 100, 1_500);
		fixture("newest", 100, 9_000);

		// Must not throw even if some deletes fail.
		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(dir), "newest", 200, 50);

		assertTrue("pruning must complete without throwing regardless of individual delete outcomes", true);
		assertTrue("the protected/newest snapshot must always survive", exists("newest"));

		locked.setWritable(true);
	}

	@Test
	public void emptyOrMissingDirectory_isSafeNoOp()
	{
		File missing = new File(dir, "does-not-exist");
		// Must not throw for a nonexistent directory (listFiles()
		// returns null there).
		BankSnapshotRetention.pruneIfNeeded(TestFilepaths.fromFile(missing), "whatever", 100, 50);
	}

	private boolean exists(String snapshotId)
	{
		return new File(dir, snapshotId + ".json").exists();
	}

	private int countFiles()
	{
		File[] files = dir.listFiles();
		return files == null ? 0 : files.length;
	}

	private long totalBytes()
	{
		File[] files = dir.listFiles();
		if (files == null)
		{
			return 0;
		}
		long total = 0;
		for (File f : files)
		{
			if (f.isFile())
			{
				total += f.length();
			}
		}
		return total;
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.activity.BarrowsBrother;
import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * The Barrows current run is the game's own brother varbits, mirrored for
 * presentation: read on login (so a run in progress is shown as it really
 * is), updated on each brother varbit change, cleared on logout / account
 * switch, and never written to the event log.
 */
public class BarrowsProgressCollectorTest
{
	private static final long ACCOUNT = 700_900_905L;

	private Path testRoot;
	private EventLedger ledger;
	private StructuredActivityCollector collector;
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final List<EventType> events = new ArrayList<>();
	private final AtomicInteger changes = new AtomicInteger();
	private GameState gameState = GameState.LOGGED_IN;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("barrows-progress-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		ledger = new EventLedger(new Gson());
		ledger.start();
		ledger.addListener((TelemetryEventListener) (account, type, payload, at) ->
		{
			synchronized (events)
			{
				events.add(type);
			}
		});
		Client client = (Client) java.lang.reflect.Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getAccountHash":
						return ACCOUNT;
					case "getGameState":
						return gameState;
					case "getVarbitValue":
						return varbits.getOrDefault((Integer) args[0], 0);
					default:
						Class<?> rt = method.getReturnType();
						if (rt == boolean.class)
						{
							return false;
						}
						if (rt.isPrimitive() && rt != void.class)
						{
							return rt == long.class ? (Object) 0L : (Object) 0;
						}
						return null;
				}
			});
		collector = new StructuredActivityCollector(client, id -> "item" + id, ledger, StructuredActivityRegistry.defaults());
		collector.setProgressListener(changes::incrementAndGet);
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void varbit(BarrowsBrother brother, int value)
	{
		varbits.put(brother.getKilledVarbit(), value);
		VarbitChanged e = new VarbitChanged();
		e.setVarbitId(brother.getKilledVarbit());
		e.setValue(value);
		collector.onVarbitChanged(e);
	}

	@Test
	public void unknownUntilRead_thenMidRunAttachShowsTheRealBrothers()
	{
		assertNull(collector.getBarrowsProgress());
		varbits.put(BarrowsBrother.AHRIM.getKilledVarbit(), 1);
		varbits.put(BarrowsBrother.KARIL.getKilledVarbit(), 1);
		collector.onGameTick(new GameTick());
		assertNotNull(collector.getBarrowsProgress());
		assertEquals("mid-run: exactly what the game says, nothing fabricated", 2, collector.getBarrowsProgress().getClearedCount());
		assertEquals(1, changes.get());
		collector.onGameTick(new GameTick());
		assertEquals("no re-read churn once known", 1, changes.get());
	}

	@Test
	public void brotherKills_countUp_duplicatesDoNotDoubleCount_resetStartsANewRun()
	{
		collector.onGameTick(new GameTick());
		assertEquals(0, collector.getBarrowsProgress().getClearedCount());
		varbit(BarrowsBrother.DHAROK, 1);
		assertEquals(1, collector.getBarrowsProgress().getClearedCount());
		varbit(BarrowsBrother.DHAROK, 1); // same evidence again
		assertEquals(1, collector.getBarrowsProgress().getClearedCount());
		int changesAfterDuplicate = changes.get();
		for (BarrowsBrother b : BarrowsBrother.values())
		{
			varbit(b, 1);
		}
		assertEquals(6, collector.getBarrowsProgress().getClearedCount());
		assertEquals("one change per real transition", changesAfterDuplicate + 5, changes.get());
		for (BarrowsBrother b : BarrowsBrother.values())
		{
			varbit(b, 0); // the game resets the run after the chest
		}
		assertEquals(0, collector.getBarrowsProgress().getClearedCount());
	}

	@Test
	public void unrelatedVarbits_areIgnored()
	{
		collector.onGameTick(new GameTick());
		int before = changes.get();
		VarbitChanged e = new VarbitChanged();
		e.setVarbitId(463); // monster points: not a brother
		e.setValue(40);
		collector.onVarbitChanged(e);
		assertEquals(before, changes.get());
	}

	@Test
	public void logoutAndAccountSwitch_forgetTheRun_andNothingIsWrittenToTheLedger()
	{
		collector.onGameTick(new GameTick());
		varbit(BarrowsBrother.TORAG, 1);
		GameStateChanged logout = new GameStateChanged();
		logout.setGameState(GameState.LOGIN_SCREEN);
		gameState = GameState.LOGIN_SCREEN;
		collector.onGameStateChanged(logout);
		assertNull(collector.getBarrowsProgress());
		collector.onGameTick(new GameTick());
		assertNull("not re-read while logged out", collector.getBarrowsProgress());

		gameState = GameState.LOGGED_IN;
		collector.onGameTick(new GameTick());
		assertEquals(1, collector.getBarrowsProgress().getClearedCount());
		collector.resetForAccountSwitch();
		assertNull(collector.getBarrowsProgress());
		synchronized (events)
		{
			assertEquals("presentation state only: no events", 0, events.size());
		}
	}

	@Test
	public void aThrowingListener_neverBreaksCollection()
	{
		collector.setProgressListener(() ->
		{
			throw new IllegalStateException("ui bug");
		});
		collector.onGameTick(new GameTick());
		varbit(BarrowsBrother.VERAC, 1);
		assertEquals(1, collector.getBarrowsProgress().getClearedCount());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Targets
 * BossActivityContextCollector.decide() — the pure, RuneLite-free core
 * of the collector's onInteractingChanged() handler. A plain HashMap
 * stands in for the production ConcurrentHashMap; KnownBossRegistry
 * itself is RuneLite-API-free (see its own class javadoc), so no
 * mocking is needed anywhere in this file, same as every other test
 * in this project (no Mockito dependency).
 */
public class BossActivityContextCollectorTest
{
	private static final long ACCOUNT_A = 555L;

	@Test
	public void nonBossNpc_noEmission()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");
		Map<Long, String> tracked = new HashMap<>();

		String result = BossActivityContextCollector.decide(true, "Chicken", registry, ACCOUNT_A, tracked);

		assertNull(result);
	}

	@Test
	public void confirmedBoss_emitsWithCorrectCanonicalName()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");
		Map<Long, String> tracked = new HashMap<>();

		String result = BossActivityContextCollector.decide(true, "Zulrah", registry, ACCOUNT_A, tracked);

		assertEquals("Zulrah", result);
		assertEquals("Zulrah", tracked.get(ACCOUNT_A));
	}

	@Test
	public void reInteractingSameAlreadyCurrentBoss_isDeduped()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");
		Map<Long, String> tracked = new HashMap<>();

		String first = BossActivityContextCollector.decide(true, "Zulrah", registry, ACCOUNT_A, tracked);
		// Simulates a phase transition / sub-target flicker mid-fight:
		// several InteractingChanged deliveries for the SAME resolved
		// boss in a row.
		String second = BossActivityContextCollector.decide(true, "Zulrah", registry, ACCOUNT_A, tracked);
		String third = BossActivityContextCollector.decide(true, "Zulrah", registry, ACCOUNT_A, tracked);

		assertEquals("Zulrah", first);
		assertNull(second);
		assertNull(third);
	}

	@Test
	public void sourceNotLocalPlayer_isIgnored()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");
		Map<Long, String> tracked = new HashMap<>();

		String result = BossActivityContextCollector.decide(false, "Zulrah", registry, ACCOUNT_A, tracked);

		assertNull(result);
		assertNull(tracked.get(ACCOUNT_A));
	}

	@Test
	public void targetNotNpc_isIgnored()
	{
		// The production caller passes npcName == null whenever
		// event.getTarget() is not an NPC instance at all.
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");
		Map<Long, String> tracked = new HashMap<>();

		String result = BossActivityContextCollector.decide(true, null, registry, ACCOUNT_A, tracked);

		assertNull(result);
	}

	@Test
	public void breakingInteractionThenReEngagingSameBoss_emitsAgain()
	{
		// Not spam — a genuine disengage/re-engage. Matters for
		// resuming a SUSPENDED BOSSING session: fresh specific evidence
		// is what lets ActivitySignalClassifier.decideCombatBranch()'s
		// exact-identity-match fast path resume it.
		KnownBossRegistry registry = new KnownBossRegistry();
