	{
		List<StorageState.StorageItem> items = oneItem("Justiciar legguards");

		collector.scheduleBankSnapshot(accountHash, items);
		// ClientShutdown path runs first and completes fully.
		collector.beginClientShutdownFinalization().get(5, TimeUnit.SECONDS);

		assertEquals(1, bankSnapshotEventLines().size());
		assertEquals(1, countSnapshotFiles());

		// A later Plugin.shutDown()-style call (both shutdown paths are
		// idempotent with respect to bank finalization: nothing is
		// pending any more, and inFlightBankFinalization already holds a
		// completed future, so this must be a safe no-op).
		collector.flushPendingAndWait();

		assertEquals(
			"a later flushPendingAndWait() call after ClientShutdown already finalized must not produce a second event",
			1, bankSnapshotEventLines().size());
		assertEquals(
			"a later flushPendingAndWait() call after ClientShutdown already finalized must not produce a second snapshot",
			1, countSnapshotFiles());
	}

	// --- G. no bank mutation at all: shutdown must not fabricate a snapshot/event ---

	@Test
	public void clientShutdown_g_noBankMutation_doesNotFabricateSnapshotOrEvent() throws Exception
	{
		// No scheduleBankSnapshot()/flushPending() call at all --
		// nothing pending, nothing in flight.
		collector.beginClientShutdownFinalization().get(5, TimeUnit.SECONDS);

		assertEquals("no bank mutation occurred -- ClientShutdown must not fabricate a BANK_SNAPSHOT event", 0, bankSnapshotEventLines().size());
		assertEquals("no bank mutation occurred -- ClientShutdown must not fabricate an immutable snapshot", 0, countSnapshotFiles());

		StorageState pointer = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
		assertNull("no bank mutation occurred -- ClientShutdown must not fabricate a bank.json pointer", pointer);
	}

	// --- I. enable -> disable -> enable still works for the full bank finalization chain ---

	@Test
	public void i_enableDisableEnableCycle_bankFinalizationStillWorksEachTime() throws Exception
	{
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, oneItem("Dragon claws")));
		assertEquals(1, bankSnapshotEventLines().size());
		assertEquals(1, countSnapshotFiles());

		// Simulate plugin disable -> re-enable within the same client
		// process: both executors are torn down and restarted, exactly
		// as OsrsTelemetryPlugin's shutDown()/startUp() do.
		store.shutdown();
		eventLedger.shutdown();

		store.start();
		eventLedger.start();
		eventLedger.startNewSession();

		// A different item (dedup must not suppress this — different
		// content than the baseline recorded before the toggle).
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, oneItem("Twisted bow")));

		assertEquals(
			"both the pre- and post-restart finalizations must have durably produced a BANK_SNAPSHOT event",
			2, bankSnapshotEventLines().size());
		assertEquals(2, countSnapshotFiles());
	}

	// =====================================================================
	// Bank placeholder handling (letters A-G) -- guarding
	// against a bank placeholder left behind
	// after withdrawing the final copy of an item (e.g. real "Grubby
	// key" itemId 23499 -> placeholder "Grubby key" itemId 23501,
	// quantity still reported as 1) was persisted as an owned item.
	// buildBankItemsCore() is the exact pure core buildBankItems() (the
	// real production ItemContainer-facing method) delegates to -- see
	// its own javadoc -- exercised here with plain IntPredicate/
	// IntFunction fakes instead of a mocked ItemManager/ItemComposition
	// (this project has no Mockito dependency).
	// =====================================================================

	private static final IntPredicate NEVER_PLACEHOLDER = itemId -> false;

	private static IntFunction<String> nameLookup(Map<Integer, String> names)
	{
		return names::get;
	}

	// --- A. normal bank item is retained ---

	@Test
	public void placeholder_a_normalBankItem_isRetained()
	{
		Item[] raw = new Item[] { new Item(23499, 1) };
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, NEVER_PLACEHOLDER, nameLookup(names));

		assertEquals(1, items.size());
		StorageState.StorageItem item = items.get(0);
		assertEquals(0, item.getSlot());
		assertEquals(23499, item.getItemId());
		assertEquals("Grubby key", item.getName());
		assertEquals(1, item.getQuantity());
	}

	// --- B. placeholder item is excluded ---

	@Test
	public void placeholder_b_placeholderItem_isExcluded()
	{
		// Exactly the live-bug shape: placeholder itemId (23501),
		// reported quantity 1 -- must still be excluded.
		Item[] raw = new Item[] { new Item(23501, 1) };
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, isPlaceholder, nameLookup(names));

		assertTrue("a placeholder-only slot must produce no owned-item entry at all", items.isEmpty());
	}

	// --- C. real item -> placeholder transition produces an owned-state change ---

	@Test
	public void placeholder_c_realItemToPlaceholderTransition_isAnOwnedStateChange()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");
		IntPredicate isPlaceholder = itemId -> itemId == 23501;

		List<StorageState.StorageItem> before = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		List<StorageState.StorageItem> after = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));

		assertEquals(1, before.size());
		assertTrue("withdrawing the final copy (leaving a placeholder) must remove it from owned items", after.isEmpty());
		assertFalse("the before/after owned-item lists must be genuinely different", before.equals(after));
	}

	// --- D. placeholder-only bank slot is not serialized as ownership ---

	@Test
	public void placeholder_d_placeholderOnlySlot_isNeverSerializedAsOwnership()
	{
		// A slot RuneLite still reserves for the placeholder, alongside
		// unrelated real items in other slots -- only the placeholder
		// slot must be dropped.
		Item[] raw = new Item[] {
			new Item(23499, 1),
			new Item(13797, 5),
			new Item(23501, 1)
		};
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Blood moon chestplate");
		names.put(13797, "Onion seed");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(raw, isPlaceholder, nameLookup(names));

		assertEquals("exactly the two real items must survive, never the placeholder slot", 2, items.size());
		for (StorageState.StorageItem item : items)
		{
			assertFalse("no serialized item may carry the placeholder itemId", item.getItemId() == 23501);
		}
	}

	// --- E. bank snapshot after removing the final copy does not contain the item ---

	@Test
	public void placeholder_e_bankSnapshotAfterRemovingFinalCopy_doesNotContainTheItem() throws Exception
	{
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> withKey = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, withKey));

		StorageState pointerBefore = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
		StorageState snapshotBefore = store.readIfExists(
			TelemetryPaths.bankSnapshotFile(accountHash, pointerBefore.getLatestSnapshotId()), StorageState.class);
		assertEquals(1, snapshotBefore.getItems().size());

		// The final copy is withdrawn, leaving only the placeholder --
		// buildBankItemsCore() (as production's buildBankItems() would)
		// excludes it entirely from the observed owned-item list.
		List<StorageState.StorageItem> withPlaceholderOnly = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));
		assertTrue(collector.finalizeBankSnapshotBlocking(accountHash, withPlaceholderOnly));

		StorageState pointerAfter = store.readIfExists(TelemetryPaths.stateFile(accountHash, "bank"), StorageState.class);
		StorageState snapshotAfter = store.readIfExists(
			TelemetryPaths.bankSnapshotFile(accountHash, pointerAfter.getLatestSnapshotId()), StorageState.class);

		assertTrue("the new immutable snapshot must contain no entry for the withdrawn item at all",
			snapshotAfter.getItems().isEmpty());
		for (StorageState.StorageItem item : snapshotAfter.getItems())
		{
			assertFalse(item.getItemId() == 23499 || item.getItemId() == 23501);
		}
	}

	// --- F. dedup logic sees real-item -> placeholder as changed contents ---

	@Test
	public void placeholder_f_dedupBaseline_seesRealItemToPlaceholderTransitionAsChanged()
	{
		IntPredicate isPlaceholder = itemId -> itemId == 23501;
		Map<Integer, String> names = new HashMap<>();
		names.put(23499, "Grubby key");
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> baselineItems = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23499, 1) }, isPlaceholder, nameLookup(names));
		List<StorageState.StorageItem> candidateItems = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, isPlaceholder, nameLookup(names));

		Instant createdAt = Instant.now();
		BankSnapshotBaseline baseline = BankSnapshotBaseline.of(baselineItems, createdAt);

		assertTrue(
			"a real-item -> placeholder transition must be recognized as removal of the owned item, forcing a new snapshot",
			BankSnapshotBaseline.shouldWriteNewSnapshot(baseline, candidateItems, createdAt.plusSeconds(1), java.time.Duration.ofMinutes(10)));
	}

	// --- G. inventory/equipment behavior is unchanged ---

	@Test
	public void placeholder_g_inventoryAndEquipment_behaviorUnchanged()
	{
		// buildSparseItems()/buildEquipmentItems() (inventory/equipment/
		// seed vault/group storage) are untouched by this fix -- they
		// never call buildBankItemsCore()/isPlaceholder at all, so an
		// itemId that WOULD be treated as a bank placeholder must still
		// be recorded normally everywhere else. This asserts the
		// negative: buildBankItemsCore() applied with a
		// no-op placeholder predicate (equivalent to what
		// buildSparseItems() effectively does -- no placeholder concept)
		// still returns every real, quantity>0 item, confirming the
		// filtering is additive and opt-in per container, not a global
		// itemId denylist that could ever leak into another container's
		// logic.
		Map<Integer, String> names = new HashMap<>();
		names.put(23501, "Grubby key");

		List<StorageState.StorageItem> items = ContainerCollector.buildBankItemsCore(
			new Item[] { new Item(23501, 1) }, NEVER_PLACEHOLDER, nameLookup(names));

		assertEquals(
			"without bank-specific placeholder classification (i.e. exactly how buildSparseItems()/"
				+ "buildEquipmentItems() treat every item id), the same raw item is retained normally",
			1, items.size());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.activity.StructuredRewardSource;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.events.TelemetryEventListener;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Integrity audit continuation (structured collector across disable /
 * re-enable): an armed reward claim never survives into the next enable,
 * while the remembered location does -- so leaving an activity while the
 * plugin was off still produces the exit event.
 */
public class IntegrityAuditContinuationCollectorTest
{
	private static final long ACCOUNT = 700_900_903L;
	private static final int TEMPOROSS_COVE = 12588;
	private static final int OUTSIDE = 12850;

	private Path testRoot;
	private EventLedger ledger;
	private StructuredActivityCollector collector;
	private final List<Object[]> events = new ArrayList<>();
	private final StructuredActivityRegistry registry = StructuredActivityRegistry.defaults();

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("structured-reenable-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		ledger = new EventLedger(new Gson());
		ledger.start();
		ledger.addListener((TelemetryEventListener) (account, type, payload, at) ->
		{
			synchronized (events)
			{
				events.add(new Object[] {type, payload});
			}
		});
		Client client = (Client) java.lang.reflect.Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
			(proxy, method, args) ->
			{
				if ("getAccountHash".equals(method.getName()))
				{
					return ACCOUNT;
				}
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class)
				{
					return false;
				}
				if (rt.isPrimitive() && rt != void.class)
				{
					return rt == long.class ? (Object) 0L : (Object) 0;
				}
				return null;
			});
		collector = new StructuredActivityCollector(client, id -> "item" + id, ledger, registry);
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private List<Object> payloads(EventType type)
	{
		List<Object> out = new ArrayList<>();
		synchronized (events)
		{
			for (Object[] e : events)
			{
				if (e[0] == type)
				{
					out.add(e[1]);
				}
			}
		}
		return out;
	}

	private static Map<Integer, Long> inv(int itemId, long qty)
	{
		Map<Integer, Long> m = new HashMap<>();
		m.put(itemId, qty);
		return m;
	}

	@Test
	public void claimArmedBeforeDisable_cannotConsumeAnInventoryChangeAfterReEnable()
	{
		StructuredRewardSource pool = registry.rewardSource("tempoross_reward_pool");
		collector.armClaim(pool, inv(995, 100));
		collector.disarmPendingClaim(); // plugin startUp after a disable
		collector.onInventoryChanged(inv(995, 5100), id -> "Coins"); // gained while playing on
		assertEquals(0, payloads(EventType.STRUCTURED_REWARD).size());
	}

	@Test
	public void control_armedClaim_isConsumedOnce()
	{
		StructuredRewardSource pool = registry.rewardSource("tempoross_reward_pool");
		collector.armClaim(pool, inv(995, 100));
		collector.onInventoryChanged(inv(995, 5100), id -> "Coins");
		collector.onInventoryChanged(inv(995, 9100), id -> "Coins");
		assertEquals(1, payloads(EventType.STRUCTURED_REWARD).size());
	}

	@Test
	public void leavingTheActivityWhileDisabled_stillSendsTheExitAfterReEnable()
	{
		collector.onRegion(TEMPOROSS_COVE);
		assertEquals(1, payloads(EventType.STRUCTURED_ACTIVITY_STATE).size());
		collector.disarmPendingClaim(); // disable ... walk out ... enable
		collector.onRegion(OUTSIDE);
		List<Object> states = payloads(EventType.STRUCTURED_ACTIVITY_STATE);
		assertEquals("exit event after re-enable", 2, states.size());
		assertNull(((EventPayloads.StructuredActivityState) states.get(1)).getActivityKey());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Targets
 * KnownBossRegistry directly — it is entirely RuneLite-API-free, so
 * every scenario below is a real, driveable unit test, not an
 * architectural note.
 *
 * This file previously contained a test named
 * "aliasTable_aloneIsNotConfirmation" asserting that a FRESH registry
 * (no prior recordConfirmedBoss() call) does NOT resolve "Dawn"/"Dusk"
 * to "Grotesque Guardians" — i.e. it encoded a circular defect
 * (a boss could never be recognized before its own
 * first kill-count message). That test has been corrected below to
 * reflect the fixed behavior: Grotesque Guardians is in the static
 * seed, so Dawn/Dusk now resolve on a fresh registry with zero prior
 * confirmation. See freshRegistry_* tests below for the required
 * regression coverage.
 *
 * Several tests below
 * previously used Zulrah and/or Vorkath — both statically seeded,
 * global, account-independent names — to try to exercise PER-ACCOUNT
 * confirmed-state behavior (isolation, reset). Because the static seed
 * resolves those names for every account regardless of any
 * recordConfirmedBoss()/resetForAccountSwitch() call, those tests
 * rested on an invalid premise and did not actually prove per-account
 * behavior. They have been rewritten below to use deliberately
 * unseeded synthetic boss names ("Test Boss A" / "Test Boss B") so the
 * per-account confirmed-state mechanism is what is actually under
 * test. The static-seed-specific tests (freshRegistry_* below) still
 * correctly use Zulrah and Grotesque Guardians/Dawn/Dusk, since those
 * are intentionally testing seeded/fresh-start recognition.
 */
public class KnownBossRegistryTest
{
	private static final long ACCOUNT_A = 111L;
	private static final long ACCOUNT_B = 222L;

	@Test
	public void unrecognizedNpcName_doesNotResolve()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Chicken"));
	}

	@Test
	public void confirmedBossName_resolvesDirectly()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");

		assertEquals("Zulrah", registry.resolveCandidateBossName(ACCOUNT_A, "Zulrah"));
	}

	@Test
	public void confirmedBossName_resolutionIsCaseAndWhitespaceInsensitive()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Zulrah");

		// The NPC's own name as read off the NPC object may not match
		// the chat message's exact casing/whitespace — matching must
		// still succeed, while the RETURNED display name is always the
		// one originally confirmed via the kill-count message (so it
		// matches BOSS_KILL's own displayName exactly).
		assertEquals("Zulrah", registry.resolveCandidateBossName(ACCOUNT_A, "  zulrah  "));
	}

	@Test
	public void aliasTable_resolvesDawnAndDuskToGrotesqueGuardians_onceConfirmed()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Grotesque Guardians");

		assertEquals("Grotesque Guardians", registry.resolveCandidateBossName(ACCOUNT_A, "Dawn"));
		assertEquals("Grotesque Guardians", registry.resolveCandidateBossName(ACCOUNT_A, "Dusk"));
	}

	@Test
	public void unseededUnconfirmedDirectNameDoesNotResolve()
	{
		// RENAMED/REFRAMED (was "aliasTable_aloneIsNotConfirmation_
		// forABossNotInTheStaticSeed"): that test directly looked up
		// "Vorkath", which IS in the static seed, so it exercised
		// nothing about aliases or non-seeded names and its name was
		// misleading. This test uses a guaranteed-unseeded synthetic
		// name, looked up directly (no alias involved), with zero
		// confirmation, and asserts it does not resolve. Real alias
		// behavior (Dawn/Dusk) is already covered by the
		// aliasTable_resolvesDawnAndDuskToGrotesqueGuardians_onceConfirmed
		// and freshRegistry_dawnAndDusk_* tests.
		KnownBossRegistry registry = new KnownBossRegistry();

		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Test Boss A"));
	}

	// ----------------------------------------------------------------
	// REQUIRED REGRESSION COVERAGE (circular
	// first-boss recognition fix): a freshly-constructed registry, with
	// NO prior recordConfirmedBoss() call and no kill-count message
	// simulated anywhere, must still resolve well-known bosses via the
	// static seed alone.
	// ----------------------------------------------------------------

	@Test
	public void freshRegistry_zulrah_resolvesViaStaticSeed_withNoPriorConfirmation()
	{
		KnownBossRegistry registry = new KnownBossRegistry();

		assertEquals("Zulrah", registry.resolveCandidateBossName(ACCOUNT_A, "Zulrah"));
	}

	@Test
	public void freshRegistry_dawnAndDusk_resolveViaStaticSeed_withNoPriorConfirmation()
	{
		KnownBossRegistry registry = new KnownBossRegistry();

		assertEquals("Grotesque Guardians", registry.resolveCandidateBossName(ACCOUNT_A, "Dawn"));
		assertEquals("Grotesque Guardians", registry.resolveCandidateBossName(ACCOUNT_A, "Dusk"));
	}

	@Test
	public void freshRegistry_unseededUnconfirmedBoss_stillDoesNotResolve()
	{
		// The static seed does not make every boss resolvable — only
		// the curated seed list plus anything actually confirmed. An
		// unseeded, unconfirmed boss name must still return null.
		KnownBossRegistry registry = new KnownBossRegistry();

		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Some Unlisted Boss"));
	}

	@Test
	public void confirmingANonSeededBoss_makesItResolvableGoingForward()
	{
		// Runtime-observed BOSS_KILL messages augment the static seed
		// (second-and-later fights of an unseeded boss get pre-kill
		// recognition too) without ever being a prerequisite for bosses
		// already in the seed.
		KnownBossRegistry registry = new KnownBossRegistry();
		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Obor"));

		registry.recordConfirmedBoss(ACCOUNT_A, "Obor");

		assertEquals("Obor", registry.resolveCandidateBossName(ACCOUNT_A, "Obor"));
	}

	@Test
	public void perAccountIsolation_confirmingForOneAccountDoesNotLeakToAnother()
	{
		// FIXED: previously used "Zulrah" (statically seeded), so
		// account B would resolve it regardless of per-account
		// confirmation — the test did not actually prove isolation.
		// Uses a deliberately unseeded synthetic name instead.
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Test Boss A");

		assertEquals("Test Boss A", registry.resolveCandidateBossName(ACCOUNT_A, "Test Boss A"));
		assertNull(registry.resolveCandidateBossName(ACCOUNT_B, "Test Boss A"));
	}

	@Test
	public void resetForAccountSwitch_clearsThatAccountsConfirmedState()
	{
		// FIXED: previously used "Zulrah" (statically seeded), which
		// survives reset by design and so never actually proved
		// confirmed-state clearing. Uses a deliberately unseeded
		// synthetic name instead.
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Test Boss A");
		assertEquals("Test Boss A", registry.resolveCandidateBossName(ACCOUNT_A, "Test Boss A"));

		registry.resetForAccountSwitch(ACCOUNT_A);

		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Test Boss A"));
	}

	@Test
	public void resetForAccountSwitch_doesNotAffectOtherAccounts()
	{
		// FIXED: previously used "Zulrah" and "Vorkath" (both
		// statically seeded), so neither assertion actually exercised
		// per-account confirmed-state semantics. Uses two deliberately
		// unseeded synthetic names instead.
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "Test Boss A");
		registry.recordConfirmedBoss(ACCOUNT_B, "Test Boss B");

		registry.resetForAccountSwitch(ACCOUNT_A);

		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, "Test Boss A"));
		assertEquals("Test Boss B", registry.resolveCandidateBossName(ACCOUNT_B, "Test Boss B"));
	}

	@Test
	public void blankOrNullDisplayName_isNeverRecorded()
	{
		KnownBossRegistry registry = new KnownBossRegistry();
		registry.recordConfirmedBoss(ACCOUNT_A, "   ");
		registry.recordConfirmedBoss(ACCOUNT_A, null);

		assertNull(registry.resolveCandidateBossName(ACCOUNT_A, ""));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.session.LoadoutResolver;
import java.lang.reflect.Field;
import org.junit.Test;

/**
 * A regression-proof, automatable version of the
 * audit's "no duplicate persisted telemetry" claim (see the project
 * doc claude/history-loadout-capture-path-audit.md) -- rather than
 * relying solely on a one-time manual reading of
 * LoadoutArchiveCollector/LoadoutArchive's source, this test asserts
 * by reflection that NEITHER class (nor any superclass) ever declares
 * a field of a persistence/event-emission type. If a future edit ever
 * wired either class to write telemetry, this test fails immediately.
 *
 * Deliberately checks by FIELD TYPE NAME rather than importing
 * LocalStateStore/EventLedger directly -- this keeps the test honest
 * about what it is actually proving (no reference of that type is
 * held anywhere in the object graph of either class), and avoids the
 * test itself needing to construct either dependency.
 */
public class LoadoutArchiveCollectorNoPersistenceTest
{
	private static final String[] FORBIDDEN_FIELD_TYPE_SIMPLE_NAMES = {
		"LocalStateStore",
		"EventLedger",
	};

	@Test
	public void loadoutArchiveCollector_declaresNoPersistenceOrEventLedgerField()
	{
		assertNoForbiddenFields(LoadoutArchiveCollector.class);
	}

	@Test
	public void loadoutArchive_declaresNoPersistenceOrEventLedgerField()
	{
		assertNoForbiddenFields(LoadoutArchive.class);
	}

	@Test
	public void loadoutArchive_entry_declaresNoPersistenceOrEventLedgerField()
	{
		assertNoForbiddenFields(LoadoutArchive.Entry.class);
	}

	/**
	 * Companion check (not part of the six audit points, but the same
	 * spirit): LoadoutResolver -- the read side of this same capture
	 * path, owned by session.SessionPersistence -- also never writes
	 * telemetry; it only ever reads from the archive it is given.
	 */
	@Test
	public void loadoutResolver_declaresNoPersistenceOrEventLedgerField()
	{
		assertNoForbiddenFields(LoadoutResolver.class);
	}

	private static void assertNoForbiddenFields(Class<?> type)
	{
		Class<?> current = type;
		while (current != null && current != Object.class)
		{
			for (Field field : current.getDeclaredFields())
			{
				String simpleName = field.getType().getSimpleName();
				for (String forbidden : FORBIDDEN_FIELD_TYPE_SIMPLE_NAMES)
				{
					assertTrue(
						"class " + type.getName() + " (via " + current.getName() + ") must never hold a "
							+ forbidden + " field -- found " + field,
						!simpleName.equals(forbidden));
				}
			}
			current = current.getSuperclass();
		}
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.model.StorageState;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Client-independent coverage of LoadoutArchive: query
 * semantics (strictly-before / at-or-after / at-or-before), pruning
 * by age and by count, defensive copying, and account-switch reset.
 * Plain JUnit, no Mockito, matching this project's established test
 * style (see LootTrackerIndexTest).
 */
public class LoadoutArchiveTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");

	private static List<StorageState.StorageItem> oneItem(int itemId)
	{
		return Collections.singletonList(new StorageState.StorageItem(0, itemId, "item-" + itemId, 1, null));
	}

	@Test
	public void record_thenLatestStrictlyBefore_findsEntryStrictlyEarlier()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestStrictlyBefore(T0.plusSeconds(90));

		assertNotNull(found);
		assertEquals(T0.plusSeconds(60), found.getObservedAt());
		assertEquals(2, found.getInventory().get(0).getItemId());
	}

	@Test
	public void latestStrictlyBefore_excludesEntryExactlyAtInstant()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		assertNull("an entry observed exactly AT the query instant must not count as 'strictly before' it",
			archive.latestStrictlyBefore(T0));
	}

	@Test
	public void earliestAtOrAfter_includesEntryExactlyAtInstant()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());

		LoadoutArchive.Entry found = archive.earliestAtOrAfter(T0);

		assertNotNull(found);
		assertEquals(T0, found.getObservedAt());
		assertEquals(1, found.getInventory().get(0).getItemId());
	}

	@Test
	public void earliestAtOrAfter_picksEarliestQualifyingEntry_notLatest()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0.plusSeconds(30), oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(60), oneItem(2), Collections.emptyList());
		archive.record(T0.plusSeconds(90), oneItem(3), Collections.emptyList());

		LoadoutArchive.Entry found = archive.earliestAtOrAfter(T0.plusSeconds(10));

		assertEquals(T0.plusSeconds(30), found.getObservedAt());
	}

	@Test
	public void latestAtOrBefore_includesEntryExactlyAtInstant_picksMostRecentQualifying()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		archive.record(T0.plusSeconds(30), oneItem(2), Collections.emptyList());
		archive.record(T0.plusSeconds(90), oneItem(3), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0.plusSeconds(30));

		assertNotNull(found);
		assertEquals(T0.plusSeconds(30), found.getObservedAt());
	}

	@Test
	public void queries_onEmptyArchive_returnNull()
	{
		LoadoutArchive archive = new LoadoutArchive();

		assertNull(archive.latestStrictlyBefore(T0));
		assertNull(archive.earliestAtOrAfter(T0));
		assertNull(archive.latestAtOrBefore(T0));
	}

	@Test
	public void record_defensivelyCopiesLists_laterMutationNotReflected()
	{
		LoadoutArchive archive = new LoadoutArchive();
		List<StorageState.StorageItem> inventory = new ArrayList<>(oneItem(1));

		archive.record(T0, inventory, Collections.emptyList());
		inventory.clear();

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0);
		assertEquals(1, found.getInventory().size());
	}

	@Test
	public void entryLists_areUnmodifiable()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		LoadoutArchive.Entry found = archive.latestAtOrBefore(T0);
		try
		{
			found.getInventory().add(new StorageState.StorageItem(1, 2, "x", 1, null));
			org.junit.Assert.fail("Entry's inventory list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	@Test
	public void prune_dropsEntriesOlderThanMaxAge()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());

		// A later record() call prunes based on ITS OWN observedAt as "now".
		Instant wellPastMaxAge = T0.plus(LoadoutArchive.MAX_AGE).plusSeconds(1);
		archive.record(wellPastMaxAge, oneItem(2), Collections.emptyList());

		assertNull("the T0 entry must have aged out once MAX_AGE has elapsed -- a query that could ONLY match it must find nothing",
			archive.latestStrictlyBefore(T0.plusSeconds(1)));
		assertNotNull("the fresh entry must still be present",
			archive.latestAtOrBefore(wellPastMaxAge));
	}

	@Test
	public void prune_boundsEntryCountAtMaxEntries()
	{
		LoadoutArchive archive = new LoadoutArchive();
		for (int i = 0; i < LoadoutArchive.MAX_ENTRIES + 20; i++)
		{
			// One-second spacing keeps every entry well within MAX_AGE of
			// the last one recorded, so only the count bound is exercised.
			archive.record(T0.plusSeconds(i), oneItem(i), Collections.emptyList());
		}

		assertEquals(LoadoutArchive.MAX_ENTRIES, archive.size());
		// The oldest entries (0..19) must have been evicted in favor of the newest.
		assertNull(archive.latestAtOrBefore(T0.plusSeconds(5)));
	}

	@Test
	public void resetForAccountSwitch_clearsEverything()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(T0, oneItem(1), Collections.emptyList());
		assertTrue(archive.size() > 0);

		archive.resetForAccountSwitch();

		assertEquals(0, archive.size());
		assertNull(archive.latestAtOrBefore(T0.plusSeconds(1000)));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Locale;
import org.junit.Test;

/**
 * NOTE: written, not run in this file — this project's normal
 * no-network caveat (see plugin/README.md) applies to authoring.
 *
 * Tests the renamed
 * NPC_LOOT_ATTRIBUTED producer (LootCollector / EventPayloads.
 * NpcLootAttributed) — LOOT_DROP/LootDrop was renamed without adding
 * dedicated tests, since the runtime collection logic didn't change.
 * This file closes that gap.
 *
 * Targets LootCollector.buildPayload(), the pure Client/EventLedger/
 * RuneLite-API-independent core of the NPC_LOOT_ATTRIBUTED payload
 * construction — factored out of onNpcLootReceived() for exactly this
 * purpose, mirroring the same pattern already used throughout this
 * project (SlayerCollector.evaluateSlayerTransition(),
 * NpcDeathCollector.buildPayload()). This project has no Mockito
 * dependency, so RuneLite's NPC/Client/ItemManager/NpcLootReceived
 * types are never mocked — buildPayload() takes only primitives/
 * Strings already read off those objects.
 *
 * Guarantees that are architectural rather than
 * unit-testable in isolation without mocking RuneLite's EventBus/
 * NpcLootReceived (this project deliberately avoids depending on that
 * for tests), documented here instead of faked as a test:
 *
 *  - "Producing NPC_LOOT_ATTRIBUTED has no dependency on an
 *    NPC_DEATH event": enforced by construction — LootCollector's
 *    only import from another collector's package is none at all; it
 *    has no reference to NpcDeathCollector, EventType.NPC_DEATH, or
 *    ActorDeath anywhere in its source, and its only @Subscribe
 *    handler is onNpcLootReceived(NpcLootReceived).
 *  - "Producing NPC_LOOT_ATTRIBUTED has no dependency on a
 *    SLAYER_TASK_PROGRESS event": enforced by construction — same
 *    reasoning; LootCollector has no reference to SlayerCollector,
 *    EventType.SLAYER_TASK_PROGRESS, SlayerPluginService, or
 *    VarbitChanged anywhere in its source.
 */
public class LootCollectorTest
{
	private static final Gson GSON = new Gson();

	// --- 1. serializable through an isolated equivalent of the project's actual serialization path ---

	@Test
	public void payload_roundTripsThroughGson_sameSerializerEventLedgerUses()
	{
		// EventLedger.append() serializes the payload with a plain
		// `new Gson()` (see EventLedger.java) — this test uses the same
		// mechanism directly on the payload object, isolated from
		// Client/EventBus/file I/O, rather than duplicating
		// EventLedger's own tested append()/appendNow() logic.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		String json = GSON.toJson(payload);
		EventPayloads.NpcLootAttributed roundTripped = GSON.fromJson(json, EventPayloads.NpcLootAttributed.class);

		assertEquals(payload, roundTripped);
		assertTrue("serialized JSON should carry the item name", json.contains("Abyssal whip"));
	}

	// --- 2. NPC/source identity preserved ---

	@Test
	public void buildPayload_preservesSourceIdentity()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		assertEquals("NPC", payload.getSourceType());
		assertEquals("Gargoyle", payload.getSourceName());
		assertEquals(111, payload.getSourceId());
	}

	// --- 3. item identity preserved ---

	@Test
	public void buildPayload_preservesItemIdentity()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, "Abyssal whip", 1);

		assertEquals(4151, payload.getItemId());
		assertEquals("Abyssal whip", payload.getItemName());
		assertEquals(1, payload.getQuantity());
	}

	@Test
	public void buildPayload_preservesQuantityGreaterThanOne()
	{
		// Stacked items (e.g. runes, coins) are a routine case — confirm
		// quantity is passed through unmodified, not clamped/assumed 1.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Chicken", 41, 995, "Coins", 42);

		assertEquals(42, payload.getQuantity());
	}

	// --- 4/5/6. no ownership, kill-attribution, or Slayer-attribution field exists ---

	@Test
	public void payload_declaresOnlyTheSixExpectedFields_noAttributionOrOwnershipField()
	{
		// Structural check on EventPayloads.NpcLootAttributed itself
		// (not on a specific instance) — the actual contract this test
		// requirement is about is "no such field EXISTS", not "no such
		// field happens to be set." Reflection over the declared field
		// set is a real assertion on the payload's shape, not a
		// duplication of buildPayload()'s pass-through logic.
		Field[] fields = EventPayloads.NpcLootAttributed.class.getDeclaredFields();
		String[] fieldNames = Arrays.stream(fields)
			.map(Field::getName)
			.toArray(String[]::new);

		String[] expected = {"sourceType", "sourceName", "sourceId", "itemId", "itemName", "quantity"};
		String[] sortedActual = fieldNames.clone();
		String[] sortedExpected = expected.clone();
		Arrays.sort(sortedActual);
		Arrays.sort(sortedExpected);
		assertArrayEquals(sortedExpected, sortedActual);

		for (String name : fieldNames)
		{
			String lower = name.toLowerCase(Locale.ROOT);
			assertFalse("field " + name + " must not imply ownership", lower.contains("owner"));
			assertFalse("field " + name + " must not imply local-player ownership", lower.contains("mine") || lower.contains("belongsto"));
			assertFalse("field " + name + " must not imply kill attribution", lower.contains("kill"));
			assertFalse("field " + name + " must not imply Slayer attribution", lower.contains("slayer") || lower.contains("ontask"));
		}
	}

	// --- 9. unavailable metadata is not fabricated ---

	@Test
	public void buildPayload_nullSourceName_passedThroughNotFabricated()
	{
		// npc.getName() can legitimately return null for some NPCs
		// (RuneLite's own NPC/Actor accessors carry no guarantee
		// otherwise). buildPayload() must never substitute a placeholder
		// like "Unknown" — it's a pass-through, not a decision.
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", null, 111, 4151, "Abyssal whip", 1);

		assertEquals(null, payload.getSourceName());
	}

	@Test
	public void buildPayload_nullItemName_passedThroughNotFabricated()
	{
		EventPayloads.NpcLootAttributed payload = LootCollector.buildPayload(
			"NPC", "Gargoyle", 111, 4151, null, 1);

		assertEquals(null, payload.getItemName());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.osrstelemetry.plugin.events.EventPayloads;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as everywhere else
 * in this project's test module (see plugin/README.md).
 *
 * Renamed from NpcKillCollectorTest (event truth-semantics
 * correction) — targets NpcDeathCollector.buildPayload()/
 * formatWorldLocation(), unchanged from the prior NpcKillCollector
 * versions apart from the rename. This is the pure Client/EventLedger/
 * RuneLite-API-independent core of the NPC_DEATH payload decision —
 * factored out for the same reason as
 * SlayerCollector.evaluateSlayerTransition(): unit-testable without
 * mocking RuneLite's NPC/Client/SlayerPluginService (this project has
 * no Mockito dependency — see BankSnapshotBaselineTest's javadoc for
 * the same constraint noted before).
 *
 * The audit's minimum test list for NPC_DEATH is mostly architectural,
 * not unit-testable in isolation without mocking RuneLite's
 * EventBus/ActorDeath/NPC types this project deliberately avoids
 * depending on for tests; where that's the case, the guarantee and
 * where to see it enforced by construction is noted in a comment
 * instead of a fabricated test:
 *
 *  - "ActorDeath with NPC -> NPC_DEATH": enforced by onActorDeath()
 *    calling eventLedger.append(..., EventType.NPC_DEATH, ...) exactly
 *    once per invocation, unconditionally on a successful instanceof
 *    NPC check (see NpcDeathCollector.onActorDeath()).
 *  - "player ActorDeath -> no NPC_DEATH": enforced by the same method's
 *    `if (!(actor instanceof NPC)) { return; }` guard — a Player actor
 *    never reaches the append() call.
 *  - "active Slayer task context does not imply on-task attribution" /
 *    "no dependency on Slayer progress": tested directly below
 *    (scenarios 5-7) — buildPayload() never gates emission on
 *    slayerRemaining, only whether to attach contextual task-name/
 *    location fields, and never produces any onSlayerTask-style
 *    boolean.
 *  - "no dependency on loot": enforced by construction —
 *    NpcDeathCollector has no reference to LootCollector, NpcLootAttributed,
 *    or EventType.NPC_LOOT_ATTRIBUTED anywhere in its source.
 *  - no config gating: core telemetry collection is not
 *    user-configurable, so onActorDeath() runs unconditionally while the
 *    plugin is enabled (see CoreTelemetryCollectionNotConfigurableTest).
 *  - "null/unavailable NPC metadata is not fabricated": tested directly
 *    below (scenarios 2-3).
 */
public class NpcDeathCollectorTest
{
	// --- formatWorldLocation ---

	@Test
	public void formatWorldLocation_buildsCommaSeparatedTriple()
	{
		assertEquals("3210,3424,0", NpcDeathCollector.formatWorldLocation(3210, 3424, 0));
	}

	// --- npcId / combatLevel nullability ("do not fabricate missing values") ---

	@Test
	public void buildPayload_positiveIdAndCombatLevel_areKept()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 89, "1,2,0", 0, null, null);

		assertEquals("Gargoyle", payload.getNpcName());
		assertEquals(Integer.valueOf(111), payload.getNpcId());
		assertEquals(Integer.valueOf(89), payload.getCombatLevel());
	}

	@Test
	public void buildPayload_negativeRawId_isNulledNotFabricated()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", -1, 89, "1,2,0", 0, null, null);

		assertNull(payload.getNpcId());
	}

	@Test
	public void buildPayload_nonPositiveCombatLevel_isNulledNotFabricated()
	{
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 0, "1,2,0", 0, null, null);

		assertNull(payload.getCombatLevel());
	}

	// --- Slayer correlation: contextual only, never a death-emission gate, never on-task attribution ---

	@Test
	public void buildPayload_noActiveTask_slayerFieldsNull()
	{
		// A non-task NPC death while no Slayer assignment exists at all.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Chicken", 41, 1, "1,2,0", 0, null, null);

		assertNull(payload.getActiveSlayerTaskName());
		assertNull(payload.getActiveSlayerTaskLocation());
	}

	@Test
	public void buildPayload_activeTask_attachesContextualTaskFieldsOnly()
	{
		// Normal on-task death: Gargoyles active, remaining > 0. Context
		// only — this test does not (and the payload cannot) assert any
		// "this death counted toward the task" claim, because no such
		// field exists.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Gargoyle", 111, 89, "1,2,0", 138, "Gargoyles", "Wilderness Slayer Cave");

		assertEquals("Gargoyles", payload.getActiveSlayerTaskName());
		assertEquals("Wilderness Slayer Cave", payload.getActiveSlayerTaskLocation());
	}

	@Test
	public void buildPayload_unrelatedNpcWhileTaskActive_stillAttachesTaskContextOnly()
	{
		// The audit's own worked example: a chicken dies while Gargoyles
		// is assigned. Task context is attached (it is genuinely active),
		// but nothing on this payload claims the chicken IS on-task —
		// there is no onSlayerTask field at all, and the dead NPC's own
		// identity (npcName) is completely independent of the attached
		// task fields.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Chicken", 2854, 1, "1,2,0", 138, "Gargoyles", "Wilderness Slayer Cave");

		assertEquals("Chicken", payload.getNpcName());
		assertEquals("Gargoyles", payload.getActiveSlayerTaskName());
	}

	@Test
	public void buildPayload_zeroRemaining_treatedAsNoActiveTask()
	{
		// Mirrors SlayerCollector.resolveCurrent()'s own "only set task
		// fields when remaining > 0" convention — a just-completed task
		// (remaining == 0) must not leak stale task name/location onto
		// an unrelated death.
		EventPayloads.NpcDeath payload = NpcDeathCollector.buildPayload(
			"Cow", 81, 2, "1,2,0", 0, "Gargoyles", "Wilderness Slayer Cave");

		assertNull(payload.getActiveSlayerTaskName());
		assertNull(payload.getActiveSlayerTaskLocation());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Targets
 * NpcInteractionTargetCollector.isAttackableNpc() and .decide() — the
 * pure, RuneLite-free core of the collector's onInteractingChanged()
 * handler. Mirrors BossActivityContextCollectorTest's exact structure
 * and precedent: a plain HashMap stands in for the production
 * ConcurrentHashMap, no mocking is needed anywhere in this file (no
 * Mockito dependency in this project), and both methods are exercised
 * purely through primitives (String[] / String / long / Map), never
 * through real RuneLite NPCComposition/NPC/Actor instances.
 *
 * This file directly satisfies REQUIRED TEST COVERAGE item 3 ("a
 * non-attackable NPC interaction does not establish generic combat
 * identity") at the collector layer: isAttackableNpc() returning false
 * for banker/shopkeeper/talk-to-style action sets is what stops such
 * NPCs from ever reaching decide() with a non-null attackableNpcName in
 * the first place, and decide() itself never fabricates a name when
 * given null.
 */
public class NpcInteractionTargetCollectorTest
{
	private static final long ACCOUNT_A = 555L;

	// ----------------------------------------------------------------
	// isAttackableNpc()
	// ----------------------------------------------------------------

	@Test
	public void actionsContainingAttack_isAttackable()
	{
		assertTrue(NpcInteractionTargetCollector.isAttackableNpc(new String[] { "Attack", "Examine" }));
	}

	@Test
	public void attackNotFirstElement_stillAttackable()
	{
		assertTrue(NpcInteractionTargetCollector.isAttackableNpc(new String[] { null, "Examine", "Attack" }));
	}

	@Test
	public void bankerStyleActions_bankAndCollect_isNotAttackable()
	{
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(new String[] { "Bank", "Collect", "Examine" }));
	}

	@Test
	public void shopkeeperStyleActions_tradeAndExchange_isNotAttackable()
	{
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(new String[] { "Trade", "Exchange", "Examine" }));
	}

	@Test
	public void randomTalkToNpc_isNotAttackable()
	{
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(new String[] { "Talk-to", "Examine" }));
	}

	@Test
	public void nullActionsArray_isNotAttackable()
	{
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(null));
	}

	@Test
	public void emptyActionsArray_isNotAttackable()
	{
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(new String[0]));
	}

	@Test
	public void actionsArrayOfAllNulls_isNotAttackable()
	{
		// Real RuneLite NPCComposition#getActions() arrays commonly
		// contain null slots for unused menu-entry positions.
		assertFalse(NpcInteractionTargetCollector.isAttackableNpc(new String[] { null, null, null, null, null }));
	}

	// ----------------------------------------------------------------
	// decide()
	// ----------------------------------------------------------------

	@Test
	public void sourceNotLocalPlayer_isIgnored_noStateMutation()
	{
		Map<Long, String> tracked = new HashMap<>();

		String result = NpcInteractionTargetCollector.decide(false, "Abyssal spectre", ACCOUNT_A, tracked);

		assertNull(result);
		assertNull(tracked.get(ACCOUNT_A));
	}

	@Test
	public void nonAttackableTarget_nullName_clearsTrackedStateAndEmitsNothing()
	{
		Map<Long, String> tracked = new HashMap<>();
		tracked.put(ACCOUNT_A, "Hill Giant");

		String result = NpcInteractionTargetCollector.decide(true, null, ACCOUNT_A, tracked);

		assertNull(result);
		assertNull(tracked.get(ACCOUNT_A));
	}

	@Test
	public void firstAttackableEncounter_emitsAndTracks()
	{
		Map<Long, String> tracked = new HashMap<>();

		String result = NpcInteractionTargetCollector.decide(true, "Abyssal spectre", ACCOUNT_A, tracked);

		assertEquals("Abyssal spectre", result);
		assertEquals("Abyssal spectre", tracked.get(ACCOUNT_A));
	}

	@Test
	public void repeatedSameName_isDedupedAcrossMultipleCalls()
	{
		Map<Long, String> tracked = new HashMap<>();

		String first = NpcInteractionTargetCollector.decide(true, "Abyssal spectre", ACCOUNT_A, tracked);
		String second = NpcInteractionTargetCollector.decide(true, "Abyssal spectre", ACCOUNT_A, tracked);
		String third = NpcInteractionTargetCollector.decide(true, "Abyssal spectre", ACCOUNT_A, tracked);

		assertEquals("Abyssal spectre", first);
		assertNull(second);
		assertNull(third);
	}

	@Test
	public void reEngagingSameNpcAfterABreak_emitsAgain()
	{
		Map<Long, String> tracked = new HashMap<>();

		String first = NpcInteractionTargetCollector.decide(true, "Hill Giant", ACCOUNT_A, tracked);
		// Interaction ends (target becomes null / non-attackable).
		String duringBreak = NpcInteractionTargetCollector.decide(true, null, ACCOUNT_A, tracked);
		// Player re-engages the SAME NPC.
		String reEngaged = NpcInteractionTargetCollector.decide(true, "Hill Giant", ACCOUNT_A, tracked);

		assertEquals("Hill Giant", first);
		assertNull(duringBreak);
		assertEquals("Hill Giant", reEngaged);
	}

	@Test
	public void switchingToADifferentAttackableNpc_emitsTheNewOne()
	{
		Map<Long, String> tracked = new HashMap<>();

		String first = NpcInteractionTargetCollector.decide(true, "Hill Giant", ACCOUNT_A, tracked);
		String second = NpcInteractionTargetCollector.decide(true, "Moss Giant", ACCOUNT_A, tracked);

		assertEquals("Hill Giant", first);
		assertEquals("Moss Giant", second);
		assertEquals("Moss Giant", tracked.get(ACCOUNT_A));
	}

	@Test
	public void differentAccountsTrackedIndependently()
	{
		Map<Long, String> tracked = new HashMap<>();
		long accountB = 777L;

		String forA = NpcInteractionTargetCollector.decide(true, "Zygomite", ACCOUNT_A, tracked);
		String forB = NpcInteractionTargetCollector.decide(true, "Zygomite", accountB, tracked);
		// Repeating for A alone is still deduped independently of B.
		String forARepeat = NpcInteractionTargetCollector.decide(true, "Zygomite", ACCOUNT_A, tracked);

		assertEquals("Zygomite", forA);
		assertEquals("Zygomite", forB);
		assertNull(forARepeat);
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere. Targets
 * QuestCollector.justFinished(), the pure Client-independent piece of
 * the collector, using two real Quest enum constants (Quest itself
 * has no Client dependency, so this compiles and runs without mocking
 * RuneLite's Client at all).
 */
public class QuestCollectorTest
{
	@Test
	public void firstObservationNeverReportsAnythingAsJustFinished()
	{
		// This is the account-switch/first-login safety property:
		// a null "previous" snapshot (freshly reset,
		// or never seen before) must not cause every already-finished
		// quest to be reported as newly completed.
		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		current.put(Quest.DEMON_SLAYER, QuestState.FINISHED);

		List<Quest> result = QuestCollector.justFinished(null, current);

		assertTrue("first observation must report zero transitions", result.isEmpty());
	}

	@Test
	public void reportsOnlyQuestsThatTransitionedIntoFinished()
	{
		Map<Quest, QuestState> previous = new HashMap<>();
		previous.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		previous.put(Quest.DEMON_SLAYER, QuestState.IN_PROGRESS);

		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // unchanged
		current.put(Quest.DEMON_SLAYER, QuestState.FINISHED); // just finished

		List<Quest> result = QuestCollector.justFinished(previous, current);

		assertEquals(1, result.size());
		assertEquals(Quest.DEMON_SLAYER, result.get(0));
	}

	@Test
	public void reportsNothingWhenNoQuestChangedState()
	{
		Map<Quest, QuestState> previous = new HashMap<>();
		previous.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);

		Map<Quest, QuestState> current = new HashMap<>();
		current.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);

		assertTrue(QuestCollector.justFinished(previous, current).isEmpty());
	}

	@Test
	public void accountSwitchSimulation_doesNotFabricateCompletionsFromDifferentAccount()
	{
		// Account A's snapshot before switching away.
		Map<Quest, QuestState> accountASnapshot = new HashMap<>();
		accountASnapshot.put(Quest.COOKS_ASSISTANT, QuestState.NOT_STARTED);

		// resetForAccountSwitch() sets lastKnown = null — simulated
		// directly here since this test targets justFinished(), not
		// the collector's field mutation.
		Map<Quest, QuestState> afterReset = null;

		// Account B's actual (very different) quest list.
		Map<Quest, QuestState> accountBSnapshot = new HashMap<>();
		accountBSnapshot.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED);
		accountBSnapshot.put(Quest.DEMON_SLAYER, QuestState.FINISHED);

		List<Quest> result = QuestCollector.justFinished(afterReset, accountBSnapshot);

		assertTrue(
			"account B's pre-existing completions must never be reported as new just because account A's leftover state was different",
			result.isEmpty()
		);
	}

	// Login reseed contract: captureInitialStateWithoutBaseline() persists
	// state but never sets lastKnown, so an unsettled post-login read can
	// never become the diff baseline (the root cause of a confirmed live
	// false-QUEST_COMPLETED bug). Modeled against the Client-independent
	// justFinished() core.

	@Test
	public void silentLoginReseed_thenNextPeriodicCheck_onlyReportsQuestsFinishedAfterTheReseed()
	{
		// captureInitialStateWithoutBaseline() leaves lastKnown null (see
		// its javadoc), so the plugin's first periodic checkAndFlush()
		// starts from previous == null and reseeds silently...
		Map<Quest, QuestState> reseedRead = new HashMap<>();
		reseedRead.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // finished before login
		reseedRead.put(Quest.DEMON_SLAYER, QuestState.IN_PROGRESS);

		assertTrue(
			"captureInitialStateWithoutBaseline() must never establish lastKnown itself",
			QuestCollector.justFinished(null, reseedRead).isEmpty()
		);

		// ...and only a quest that transitions to FINISHED strictly
		// AFTER that silent reseed (i.e. once a real baseline exists)
		// is ever reported -- proving the silent-hydration contract
		// doesn't also suppress genuine future completions.
		Map<Quest, QuestState> genuineBaseline = reseedRead;
		Map<Quest, QuestState> nextCheck = new HashMap<>();
		nextCheck.put(Quest.COOKS_ASSISTANT, QuestState.FINISHED); // unchanged
		nextCheck.put(Quest.DEMON_SLAYER, QuestState.FINISHED); // genuinely just finished

		List<Quest> result = QuestCollector.justFinished(genuineBaseline, nextCheck);
		assertEquals(1, result.size());
		assertEquals(Quest.DEMON_SLAYER, result.get(0));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import org.junit.Test;

/**
 * NOTE: written, not run in this file — same "written, not run" caveat
 * this project applies to every Java test (no JDK/RuneLite client jar
 * available in the cloud sandbox that authored this file; see plugin/
 * README.md and LootCollectorTest's identical note). The actual
 * `./gradlew test` run is Josh's to perform on his own machine.
 *
 * Targets ServerNpcLootCollector's pure, Client/EventLedger/RuneLite-
 * API-independent helpers (buildPayload(), isPickpocketMessage(),
 * shouldSuppress()) — this project has no Mockito dependency, so
 * NPCComposition/ItemStack/Client/ServerNpcLoot/ChatMessage are never
 * mocked, mirroring LootCollectorTest/NpcDeathCollectorTest's existing
 * pattern exactly.
 *
 * Guarantees that are architectural rather than
 * unit-testable in isolation without mocking RuneLite's EventBus (this
 * project deliberately avoids depending on that for tests), documented
 * here instead of faked as a test — see points 14/15 below.
 */
public class ServerNpcLootCollectorTest
{
	private static final Gson GSON = new Gson();

	private static EventPayloads.ServerNpcLootItem item(int itemId, String itemName, int quantity)
	{
		return new EventPayloads.ServerNpcLootItem(itemId, itemName, quantity);
	}

	// --- 1/8. one notification -> one payload containing all item stacks, original grouping preserved ---

	@Test
	public void buildPayload_oneNotification_preservesAllItemStacksTogether()
	{
		List<EventPayloads.ServerNpcLootItem> items = Arrays.asList(
			item(4151, "Abyssal whip", 1),
			item(995, "Coins", 42),
			item(1631, "Ensouled goblin head", 1)
		);

		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload("Gargoyle", 111, items);

		assertEquals(3, payload.getItems().size());
		assertEquals(items, payload.getItems());
	}

	// --- 2. source name preserved ---

	@Test
	public void buildPayload_preservesSourceName()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertEquals("Gargoyle", payload.getSourceName());
	}

	// --- 3. source id preserved when valid ---

	@Test
	public void buildPayload_preservesValidSourceId()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertEquals(Integer.valueOf(111), payload.getSourceId());
	}

	// --- 4. unavailable/invalid source id not fabricated ---

	@Test
	public void buildPayload_negativeSourceId_leftNullNotFabricated()
	{
		// NPCComposition#getId() carries no documented guarantee of
		// always returning a real value — mirroring NpcDeathCollector.
		// buildPayload()'s identical treatment of NPC#getId().
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", -1, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceId());
	}

	@Test
	public void buildPayload_zeroSourceId_leftNullNotFabricated()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 0, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceId());
	}

	// --- 5/6/7. item id/name/quantity preserved ---

	@Test
	public void buildPayload_preservesItemIdNameAndQuantity()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Chicken", 41, Collections.singletonList(item(995, "Coins", 42)));

		EventPayloads.ServerNpcLootItem only = payload.getItems().get(0);
		assertEquals(995, only.getItemId());
		assertEquals("Coins", only.getItemName());
		assertEquals(42, only.getQuantity());
	}

	@Test
	public void buildPayload_itemNameNull_passedThroughNotFabricated()
	{
		// An ItemManager lookup that fails to resolve a name must not be
		// papered over with a placeholder like "Unknown" — pass-through,
		// not a decision, same discipline as LootCollector.buildPayload().
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.singletonList(item(4151, null, 1)));

		assertNull(payload.getItems().get(0).getItemName());
	}

	// --- 9. empty/null-shaped input does not fabricate loot ---

	@Test
	public void buildPayload_emptyItemList_notFabricatedIntoNonEmptyLoot()
	{
		// A ServerNpcLoot notification with no items is not RuneLite
		// behavior this collector invented a workaround for — whatever
		// the notification actually carried (including nothing) is what
		// the payload carries; an empty items list must stay empty, not
		// be treated as "no event" (that decision belongs to the caller
		// deciding whether to call buildPayload() at all, not to this
		// pure function) and never padded with an invented item.
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Collections.emptyList());

		assertTrue(payload.getItems().isEmpty());
	}

	@Test
	public void buildPayload_nullSourceName_passedThroughNotFabricated()
	{
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			null, 111, Collections.singletonList(item(4151, "Abyssal whip", 1)));

		assertNull(payload.getSourceName());
	}

	// --- 10. serializes through the project's actual Gson mechanism ---

	@Test
	public void payload_roundTripsThroughGson_sameSerializerEventLedgerUses()
	{
		// EventLedger.append() serializes the payload with a plain
		// `new Gson()` (see EventLedger.java) — this test uses the same
		// mechanism directly on the payload object, isolated from
		// Client/EventBus/file I/O, mirroring LootCollectorTest's
		// identical pattern.
		EventPayloads.ServerNpcLoot payload = ServerNpcLootCollector.buildPayload(
			"Gargoyle", 111, Arrays.asList(item(4151, "Abyssal whip", 1), item(995, "Coins", 42)));

		String json = GSON.toJson(payload);
		EventPayloads.ServerNpcLoot roundTripped = GSON.fromJson(json, EventPayloads.ServerNpcLoot.class);

		assertEquals(payload, roundTripped);
		assertTrue("serialized JSON should carry the item name", json.contains("Abyssal whip"));
		assertTrue("serialized JSON should carry the source name", json.contains("Gargoyle"));
	}

	// --- helper: build an "armed" suppression state for a given tick/identity ---

	private static ServerNpcLootCollector.PickpocketSuppressionState armed(int tick, Integer npcId, String npcName)
	{
		return ServerNpcLootCollector.PickpocketSuppressionState.armed(tick, npcId, npcName);
	}

	private static ServerNpcLootCollector.PickpocketSuppressionState notArmed()
	{
		return ServerNpcLootCollector.PickpocketSuppressionState.notArmed();
	}

	// --- 11. same tick + SAME NPC identity (by id) => duplicate pickpocket-style loot stays suppressed ---

	@Test
	public void shouldSuppress_sameTickSameNpcIdById_suppressed()
	{
		// The pickpocket message was observed while interacting with NPC
		// id 41 ("Chicken"); the ServerNpcLoot notification on the same
		// tick is for the same id — this is the ordinary "avoid a
		// duplicate pickpocket-loot notification" case and must stay
		// suppressed exactly as RuneLite's own tick-only guard already
		// suppressed it.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(12345, 41, "Chicken");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 12345, "Chicken", 41));
	}

	@Test
	public void shouldSuppress_sameTickSameNpcNameOnly_suppressed_whenIdsUnavailable()
	{
		// Neither side has a resolvable positive id (e.g. getId()
		// returned an unresolved/non-positive value) — falls back to a
		// normalized name comparison and still suppresses the duplicate.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(500, null, "Man");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 500, "Man", 0));
	}

	// --- 12. same tick + DIFFERENT NPC/source kill loot => NOT suppressed (the actual fix) ---

	@Test
	public void shouldSuppress_sameTickDifferentNpcById_notSuppressed()
	{
		// This is the live defect being guarded against: an unrelated
		// pickpocket message (e.g. for a "Man") landing on the same
		// tick as a genuine, different NPC's ("Gargoyle") kill loot must
		// not silently discard that kill's ServerNpcLoot. Applies
		// uniformly to any NPC name — nothing Bandit-specific here.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(777, 41, "Man");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 777, "Gargoyle", 111));
	}

	@Test
	public void shouldSuppress_sameTickDifferentNpcByNameOnly_notSuppressed()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(900, null, "Man");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 900, "Gargoyle", 0));
	}

	@Test
	public void shouldSuppress_idsDiffer_evenWhenNamesHappenToMatch_notSuppressed()
	{
		// Id comparison takes precedence over name when both sides have
		// a resolvable id — two different-id sources sharing a display
		// name (a generic/common NPC name) must not be treated as the
		// same NPC merely because the names happen to match.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(42, 41, "Guard");
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 42, "Guard", 99));
	}

	// --- 13. ordinary NPC kill with no pickpocket signal at all => SERVER_NPC_LOOT emitted (not suppressed) ---

	@Test
	public void shouldSuppress_noPickpocketSignalAtAll_ordinaryKillLootNotSuppressed()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = notArmed();
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 0, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 1, "Gargoyle", 111));
	}

	// --- 14. no identity captured at pickpocket time (interaction target unresolvable) => safe tick-only fallback ---

	@Test
	public void shouldSuppress_noIdentityCapturedAtArmTime_fallsBackToTickOnlySuppression()
	{
		// getInteracting() returned null/non-NPC at the exact moment the
		// pickpocket message was observed -- both npcId and npcName are
		// null on the armed state. The original "never allow duplicate
		// pickpocket loot" guarantee still holds in this narrow case: a
		// same-tick ServerNpcLoot for ANY source is suppressed, exactly
		// as the pre-fix tick-only guard behaved.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(2024, null, null);
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 2024, "Gargoyle", 111));
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 2024, "Chicken", 41));
	}

	// --- 15. tick rollover / stale suppression state cannot suppress a later unrelated kill ---

	@Test
	public void shouldSuppress_staleArmedStateFromEarlierTick_neverSuppressesLaterUnrelatedKill()
	{
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(100, 41, "Chicken");
		// Even for the SAME NPC identity, a different (later, or
		// wrapped-around) tick must never be treated as "still armed" --
		// the tick check is the first, unconditional gate.
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 101, "Chicken", 41));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, Integer.MAX_VALUE, "Chicken", 41));
	}

	// --- 16. multiple NPCs on the same tick do not contaminate each other's suppression state ---

	@Test
	public void shouldSuppress_multipleNpcsSameTick_noCrossContamination()
	{
		// Suppression state captured for one NPC ("Man") on a given tick
		// must resolve independently per candidate ServerNpcLoot source
		// checked against it: the matching NPC stays suppressed, every
		// other NPC checked on that same tick is not.
		ServerNpcLootCollector.PickpocketSuppressionState state = armed(55, 41, "Man");
		assertTrue(ServerNpcLootCollector.shouldSuppress(state, 55, "Man", 41));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 55, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 55, "Chicken", 7));
	}

	@Test
	public void shouldSuppress_notArmedSentinel_neverEqualsRealTick()
	{
		// NOT_ARMED_TICK (-1) must never accidentally suppress a
		// legitimate tick-0 (or any other real, non-negative)
		// ServerNpcLoot — see ServerNpcLootCollector's NOT_ARMED_TICK
		// javadoc for why -1 (not RuneLite's own implicit-0 default) was
		// chosen.
		ServerNpcLootCollector.PickpocketSuppressionState state = notArmed();
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 0, "Gargoyle", 111));
		assertFalse(ServerNpcLootCollector.shouldSuppress(state, 1, "Gargoyle", 111));
	}

	@Test
	public void isPickpocketMessage_matchesRuneLitesOwnPattern()
	{
		// Exact same pattern/match-style as current LootTrackerPlugin's
		// PICKPOCKET_REGEX — see class javadoc's verbatim quote.
		assertTrue(ServerNpcLootCollector.isPickpocketMessage("You pick the Man's pocket."));
		assertTrue(ServerNpcLootCollector.isPickpocketMessage("You pick Hard hitter's pocket and get some coins."));
	}

	@Test
	public void isPickpocketMessage_ordinaryLootMessage_doesNotMatch()
	{
		assertFalse(ServerNpcLootCollector.isPickpocketMessage("Valuable drop: Abyssal whip"));
		assertFalse(ServerNpcLootCollector.isPickpocketMessage("You have a funny feeling like you're being followed."));
	}

	// --- 17. no config gating (core telemetry is not user-configurable) ---
	//
	// onChatMessage()/onServerNpcLoot() run unconditionally while the
	// plugin is enabled: this collector has no OsrsTelemetryConfig
	// dependency at all -- enforced structurally by
	// CoreTelemetryCollectionNotConfigurableTest.

	// --- 18/19. no dependency on NPC_DEATH or NPC_LOOT_ATTRIBUTED ---
	//
	// Enforced by construction — ServerNpcLootCollector has no reference
	// to NpcDeathCollector, EventType.NPC_DEATH, ActorDeath,
	// LootCollector, EventType.NPC_LOOT_ATTRIBUTED, or NpcLootReceived
	// anywhere in its source; its only @Subscribe handlers are
	// onChatMessage(ChatMessage) and onServerNpcLoot(ServerNpcLoot).

	// --- 20. no Slayer/kill ownership field on the payload ---

	@Test
	public void payload_declaresOnlyTheThreeExpectedFields_noOwnershipKillOrSlayerField()
	{
		Field[] fields = EventPayloads.ServerNpcLoot.class.getDeclaredFields();
		String[] fieldNames = Arrays.stream(fields)
			.map(Field::getName)
			.toArray(String[]::new);

		String[] expected = {"sourceName", "sourceId", "items"};
		String[] sortedActual = fieldNames.clone();
		String[] sortedExpected = expected.clone();
		Arrays.sort(sortedActual);
		Arrays.sort(sortedExpected);
		assertArrayEquals(sortedExpected, sortedActual);

		assertNoOwnershipKillOrSlayerField(fieldNames);
		assertNoOwnershipKillOrSlayerField(
			Arrays.stream(EventPayloads.ServerNpcLootItem.class.getDeclaredFields())
				.map(Field::getName)
				.toArray(String[]::new));
	}

	private static void assertNoOwnershipKillOrSlayerField(String[] fieldNames)
	{
		for (String name : fieldNames)
		{
			String lower = name.toLowerCase(Locale.ROOT);
			assertFalse("field " + name + " must not imply ownership", lower.contains("owner"));
			assertFalse("field " + name + " must not imply local-player ownership", lower.contains("mine") || lower.contains("belongsto"));
			assertFalse("field " + name + " must not imply kill attribution", lower.contains("kill"));
			assertFalse("field " + name + " must not imply death attribution", lower.contains("death"));
			assertFalse("field " + name + " must not imply Slayer attribution", lower.contains("slayer") || lower.contains("ontask"));
		}
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as elsewhere in this
 * test module (see plugin/README.md). Targets
 * SkillsCollector.evaluateXpWindow(), the pure Client/EventLedger-
 * independent core of the "seed-once-then-diff" XP window decision —
 * factored out for the exact same reason QuestCollector.justFinished()
 * was: unit-testable without mocking RuneLite's Client.
 *
 * This covers the fix for the
 * startup XP_CHANGE flood (see
 * SkillsCollector's own javadoc for the full
 * root-cause trace) — every test below maps to one of the "BASELINE /
 * EVENT TESTS" scenarios for that fix.
 */
public class SkillsCollectorTest
{
	@Test
	public void firstObservationForASkillAlwaysSeedsNeverEmitsADelta()
	{
		// Scenario C/G: a session begins with no baseline for this
		// skill (fresh session, or just reset for an account switch) —
		// the null baseline must always mean "seed silently," never
		// "compare against zero," no matter how large currentXp is.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(null, 5_000_000);
		assertTrue("a null baseline must always seed", result.shouldSeed);
	}

	@Test
	public void firstObservationSeedsRegardlessOfMagnitude_neverFabricatesAHistoricalDelta()
	{
		// Scenario I: an account with a LOT of pre-existing XP (the
		// "initial/default/incomplete state followed by real state"
		// case) must not have that real, large XP value misread as a
		// gain the moment it's first observed — the null-baseline path
		// has no notion of "previous" to compare against at all, so it
		// cannot fabricate a delta regardless of the value's size.
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(null, xp);
			assertTrue("xp=" + xp + " must still seed, never emit a delta on first observation", result.shouldSeed);
		}
	}

	@Test
	public void secondIdenticalObservationComputesZeroDelta()
	{
		// Scenario D: once seeded, an unchanged read must compute a
		// zero delta (closeXpWindowsFor() only emits when delta > 0,
		// so this is what "emits nothing" reduces to at the pure-logic
		// level).
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(273_742, 273_742);
		assertFalse("an existing baseline must never re-seed", result.shouldSeed);
		assertEquals(0, result.delta);
	}

	@Test
	public void genuineIncreaseAfterSeedComputesTheCorrectPositiveDelta()
	{
		// Scenario F: a real XP gain after the baseline is established
		// must compute exactly the real delta.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(273_742, 300_000);
		assertFalse(result.shouldSeed);
		assertEquals(300_000 - 273_742, result.delta);
	}

	@Test
	public void decreaseAgainstBaselineIsNeverTreatedAsAGain()
	{
		// XP cannot genuinely decrease, but this pins the sign
		// convention explicitly: closeXpWindowsFor() only emits when
		// delta > 0, so a negative delta (which should never actually
		// occur) is still handled safely by the >0 guard at the call
		// site rather than this pure function needing to clamp it.
		SkillsCollector.XpWindowResult result = SkillsCollector.evaluateXpWindow(300_000, 273_742);
		assertFalse(result.shouldSeed);
		assertEquals(273_742 - 300_000, result.delta);
	}

	// --- evaluateLevelTransition() ---
	//
	// Confirmed live-validation bug: LEVEL_UP fired for every skill
	// within milliseconds of login, all with previousLevel=0, because
	// the old comparison baseline (state.getSkills(), seeded by
	// captureInitialState()'s own unsynced login-time read) could hold
	// a wrong 0 the moment the first genuine, correctly-synced
	// StatChanged arrived. evaluateLevelTransition() is the pure core
	// of the fix: a null baseline must ALWAYS mean "seed silently,"
	// regardless of the observed level's value, exactly mirroring
	// evaluateXpWindow()'s contract. These five tests map directly to
	// the requested regression scenarios A-E.

	@Test
	public void scenarioA_firstLevelObservationSilentlySeeds_neverEmitsLevelUp()
	{
		// A. first level observation 0/unset -> 87 silently seeds, NO
		// LEVEL_UP — an existing level 87 must never be reported as a
		// fabricated 0 -> 87 transition just because it's the first
		// time this skill has been observed this session.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(null, 87);
		assertFalse("a null baseline must never emit LEVEL_UP", result.shouldEmit);
	}

	@Test
	public void scenarioB_secondIdenticalObservationEmitsNothing()
	{
		// B. second observation 87 -> 87 emits nothing.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(87, 87);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void scenarioC_realIncreaseEmitsExactlyOneLevelUp()
	{
		// C. real 87 -> 88 emits exactly one LEVEL_UP (shouldEmit=true;
		// the call site emits at most once per StatChanged, so "exactly
		// one" reduces to "shouldEmit is true here and nowhere else").
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(87, 88);
		assertTrue(result.shouldEmit);
	}

	@Test
	public void scenarioD_resetProducesANewSilentSeed()
	{
		// D. reset/session change (SkillsCollector.resetForAccountSwitch()
		// clears lastKnownLevel, which is exactly the null-baseline
		// input this pure function receives afterward) causes a new
		// silent seed, not a diff against the old account's level —
		// same null-in/no-emit behavior as scenario A, applied after a
		// reset instead of a fresh session.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(null, 42);
		assertFalse("post-reset baseline is null, so this must reseed silently, not diff", result.shouldEmit);
	}

	@Test
	public void scenarioE_accountABaselineCannotLeakIntoAccountB()
	{
		// E. account A's level baseline cannot leak into account B.
		// resetForAccountSwitch() clears lastKnownLevel per-skill (see
		// SkillsCollector), so by the time account B is observed, the
		// call site always passes null here regardless of what account
		// A's level was — pinned directly: a high account-A baseline
		// must never suppress or distort account B's own first
		// observation.
		SkillsCollector.LevelTransitionResult accountALeftover = SkillsCollector.evaluateLevelTransition(99, 99);
		assertFalse(accountALeftover.shouldEmit);

		SkillsCollector.LevelTransitionResult accountBFirstObservation = SkillsCollector.evaluateLevelTransition(null, 3);
		assertFalse("account B's first observation must seed silently regardless of account A's leftover level",
			accountBFirstObservation.shouldEmit);
	}

	@Test
	public void decreaseInLevelIsNeverTreatedAsALevelUp()
	{
		// A real level cannot genuinely decrease outside an account
		// switch (which resets the baseline to null first, covered by
		// scenario E), but this pins the strict-greater-than convention
		// explicitly, mirroring decreaseAgainstBaselineIsNeverTreatedAsAGain()
		// above.
		SkillsCollector.LevelTransitionResult result = SkillsCollector.evaluateLevelTransition(88, 87);
		assertFalse(result.shouldEmit);
	}

	// --- evaluateRawCombatXpPulse() -- universal generic NPC
	// recognition, temporal-design follow-up fix ---
	//
	// The pure core of the IMMEDIATE (per-StatChanged, not aggregated)
	// raw-combat-XP-pulse decision that backs EventType.RAW_COMBAT_XP_OBSERVED
	// -- see that constant's own javadoc for why this exists (closing
	// the gap between a fresh NPC interaction and XP_CHANGE's slow,
	// ~30s-aggregated flush cadence). Mirrors evaluateLevelTransition()'s
	// exact seed-once-then-diff contract, on its own SEPARATE baseline
	// map (lastKnownXpForRawPulse) so this new code path can never alter
	// XP_CHANGE's own accounting (windowBaselineXp is untouched by any
	// of this).

	@Test
	public void firstRawObservationForASkillAlwaysSeedsNeverEmitsAPulse()
	{
		// A session begins with no raw-pulse baseline for this skill
		// (fresh session or account switch) -- the
		// null baseline must always mean "seed silently," never "compare
		// against zero," no matter how large currentXp is (an existing
		// account's real XP total must never be misread as an
		// instantaneous gain the moment it is first observed).
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, 5_000_000);
		assertFalse("a null baseline must always seed, never emit", result.shouldEmit);
	}

	@Test
	public void firstRawObservationSeedsRegardlessOfMagnitude()
	{
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, xp);
			assertFalse("xp=" + xp + " must still seed, never emit on first observation", result.shouldEmit);
		}
	}

	@Test
	public void secondIdenticalRawObservationEmitsNoPulse()
	{
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(273_742, 273_742);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void genuineIncreaseAfterSeedEmitsExactlyOnePulse()
	{
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(273_742, 273_780);
		assertTrue(result.shouldEmit);
	}

	@Test
	public void decreaseAgainstRawBaselineIsNeverTreatedAsAPulse()
	{
		// XP cannot genuinely decrease, but pins the sign convention
		// explicitly, mirroring decreaseAgainstBaselineIsNeverTreatedAsAGain()
		// above.
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(300_000, 273_742);
		assertFalse(result.shouldEmit);
	}

	@Test
	public void resetProducesANewSilentRawSeed()
	{
		// resetForAccountSwitch() clears lastKnownXpForRawPulse, which is exactly the
		// null-baseline input this pure function receives afterward --
		// a new silent seed, never a diff against a stale account's XP.
		SkillsCollector.RawCombatXpPulseResult result = SkillsCollector.evaluateRawCombatXpPulse(null, 42);
		assertFalse("post-reset baseline is null, so this must reseed silently, not diff", result.shouldEmit);
	}

	@Test
	public void accountARawBaselineCannotLeakIntoAccountB()
	{
		SkillsCollector.RawCombatXpPulseResult accountALeftover = SkillsCollector.evaluateRawCombatXpPulse(99_999, 99_999);
		assertFalse(accountALeftover.shouldEmit);

		SkillsCollector.RawCombatXpPulseResult accountBFirstObservation = SkillsCollector.evaluateRawCombatXpPulse(null, 3);
		assertFalse("account B's first observation must seed silently regardless of account A's leftover baseline",
			accountBFirstObservation.shouldEmit);
	}

	// ------------------------------------------------------------------
	// evaluateLiveXpDelta() -- immediate
	// Current Session XP display. Same seed-once-then-diff, positive-
	// only discipline as evaluateRawCombatXpPulse() above, but
	// deliberately generic across every skill (not just
	// RAW_COMBAT_SKILLS) -- these tests deliberately use both combat
	// (Strength) and non-combat (Woodcutting) skill names to pin that
	// genericity, even though the pure function itself takes no skill
	// name at all (SkillsCollector.onStatChanged() is what makes it
	// generic, by calling this for every skill unconditionally).
	// ------------------------------------------------------------------

	@Test
	public void firstLiveObservationForASkillAlwaysSeedsReturnsZero()
	{
		// Test 1/9 (required list): a null baseline (fresh session,
		// account switch) must always mean "seed silently," never
		// "compare against zero" -- an existing large XP total must
		// never be misread as an instantaneous live gain the moment it
		// is first observed.
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(null, 5_000_000));
	}

	@Test
	public void firstLiveObservationSeedsRegardlessOfMagnitude()
	{
		int[] values = {0, 1, 1_000, 273_742, 200_000_000};
		for (int xp : values)
		{
			assertEquals("xp=" + xp + " must still seed (return 0), never emit a delta on first observation",
				0L, SkillsCollector.evaluateLiveXpDelta(null, xp));
		}
	}

	@Test
	public void noChangeInLiveXpProducesZeroDelta()
	{
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(273_742, 273_742));
	}

	@Test
	public void genuineIncreaseAfterSeedProducesExactPositiveDelta()
	{
		// Test 2/5 (required list): works for combat XP (Strength is a
		// stand-in here -- the function itself is skill-name-agnostic).
		assertEquals(38L, SkillsCollector.evaluateLiveXpDelta(273_742, 273_780));
	}

	@Test
	public void genuineIncreaseForANonCombatSkillProducesExactPositiveDeltaToo()
	{
		// Test 4 (required list): Woodcutting/Agility must work exactly
		// like a combat skill -- evaluateLiveXpDelta() takes no skill
		// name at all, proving there is no combat-only special-casing.
		assertEquals(120L, SkillsCollector.evaluateLiveXpDelta(4_500, 4_620));
	}

	@Test
	public void multipleSuccessiveIncreasesEachProduceTheirOwnCorrectDelta()
	{
		// Test 2 (required list): "multiple raw XP gains accumulate
		// correctly" -- accumulation itself is LiveXpTracker's own job
		// (see LiveXpTrackerTest), this pins that each individual
		// SkillsCollector-level reading against its own immediately-
		// prior baseline produces the correct incremental delta.
		assertEquals(50L, SkillsCollector.evaluateLiveXpDelta(1_000, 1_050));
		assertEquals(25L, SkillsCollector.evaluateLiveXpDelta(1_050, 1_075));
	}

	@Test
	public void decreaseAgainstLiveBaselineNeverProducesAPositiveDelta()
	{
		// XP decrease/reset/reseed must never fabricate positive live XP.
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(300_000, 273_742));
	}

	@Test
	public void resetProducesANewSilentLiveSeed()
	{
		// Test 9 (required list): resetForAccountSwitch() clears
		// lastKnownXpForLiveDelta, which is exactly the null-baseline
		// input this pure function receives afterward -- a new silent
		// seed, never a diff against a stale account's XP, so no fake
		// live XP is ever produced across an account switch.
		assertEquals("post-reset baseline is null, so this must reseed silently (return 0), not diff",
			0L, SkillsCollector.evaluateLiveXpDelta(null, 42));
	}

	@Test
	public void accountALiveBaselineCannotLeakIntoAccountB()
	{
		assertEquals(0L, SkillsCollector.evaluateLiveXpDelta(99_999, 99_999));
		assertEquals("account B's first observation must seed silently (return 0) regardless of account A's leftover baseline",
			0L, SkillsCollector.evaluateLiveXpDelta(null, 3));
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.model.SlayerState;
import org.junit.Test;

/** A task that disappears is only called cancelled on positive evidence (points down, streak not advanced). */
public class SlayerCancellationRuleTest
{
	private static SlayerState state(int points, int streak, String label)
	{
		SlayerState s = new SlayerState();
		s.setPoints(points);
		s.setStreak(streak);
		s.setStreakLabel(label);
		return s;
	}

	@Test
	public void pointsDownAndStreakUnchanged_isCancellation()
	{
		assertTrue(SlayerCollector.looksCancelled(state(100, 5, "NORMAL"), state(70, 5, "NORMAL")));
	}

	@Test
	public void completion_isNeverCancellation()
	{
		assertFalse(SlayerCollector.looksCancelled(state(100, 5, "NORMAL"), state(115, 6, "NORMAL")));
		// Early tasks award no points: streak still advances.
		assertFalse(SlayerCollector.looksCancelled(state(0, 2, "NORMAL"), state(0, 3, "NORMAL")));
	}

	@Test
	public void unsettledOrIncomparableState_staysACompletion()
	{
		assertFalse(SlayerCollector.looksCancelled(state(100, 5, "NORMAL"), state(100, 5, "NORMAL")));
		assertFalse(SlayerCollector.looksCancelled(state(100, 5, "NORMAL"), state(70, 1, "WILDERNESS")));
		assertFalse(SlayerCollector.looksCancelled(null, state(70, 5, "NORMAL")));
	}
}

package com.osrstelemetry.plugin.collectors;


import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.collectors.SlayerCollector.SlayerBaselineHydration;

import com.osrstelemetry.plugin.collectors.SlayerCollector.SlayerTransitionResult;
import com.osrstelemetry.plugin.collectors.SlayerCollector.SlayerTransitionResult.Kind;
import com.osrstelemetry.plugin.model.SlayerState;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-network caveat as elsewhere in this
 * test module (see plugin/README.md). Targets
 * SlayerCollector.evaluateSlayerTransition(), the pure Client/
 * EventLedger-independent core of the transition decision — factored
 * out for the same reason QuestCollector.justFinished() and
 * SkillsCollector.evaluateXpWindow()/evaluateLevelTransition() were:
 * unit-testable without mocking RuneLite's Client. SlayerState has no
 * Client dependency (plain @Data model), so it's built directly here,
 * per your "no new mocking dependencies" instruction.
 *
 * Task IDENTITY
 * (taskName/taskLocation) is explicitly separate from task
 * PROGRESS/METADATA (amountRemaining, initialAmount, points, streak,
 * streakLabel, streakSourceVerified, masterId). Every test below
 * exercises SlayerCollector.evaluateSlayerTransition() directly — the
 * exact function emitTransitionEvents() calls — never a separate
 * approximate copy of its decision logic.
 */
public class SlayerCollectorTest
{
	private static SlayerState task(String name, String location, int remaining)
	{
		SlayerState state = new SlayerState();
		state.setTaskName(name);
		state.setTaskLocation(location);
		state.setAmountRemaining(remaining);
		return state;
	}

	private static SlayerState noTask()
	{
		return task(null, null, 0);
	}

	// --- 1. null baseline + existing task -> silent baseline, no event ---

	@Test
	public void scenario1_nullBaselineWithExistingTask_silentBaseline()
	{
		// Required semantics: LOGIN -> existing Gargoyles task silently
		// becomes baseline -> NO SLAYER_TASK_ASSIGNED event. previous ==
		// null (the state right after captureInitialStateWithoutBaseline()
		// leaves lastKnown untouched) must never be diffed as "no task ->
		// Gargoyles."
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(null, current);
		assertEquals(Kind.NONE, result.kind);
	}

	@Test
	public void scenario1b_nullBaselineWithNoTask_silentBaseline()
	{
		// Same null-baseline guard for the "no task assigned at login"
		// case — must not fabricate ASSIGNED just because amountRemaining
		// transitions from "unobserved" to 0.
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(null, noTask());
		assertEquals(Kind.NONE, result.kind);
	}

	// --- 2. no task -> Gargoyles -> ASSIGNED ---

	@Test
	public void scenario2_noTaskToGargoyles_assigned()
	{
		SlayerState previous = noTask();
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.ASSIGNED, result.kind);
	}

	// --- 3. Gargoyles 138 -> 137 -> PROGRESS only, delta=-1, consumed=1 ---

	@Test
	public void scenario3_gargoyles138to137_progressOnly()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		SlayerState current = task("Gargoyles", "Wilderness", 137);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.PROGRESS, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
		assertEquals(138, result.previousRemaining);
		assertEquals(137, result.currentRemaining);
		assertEquals(-1, result.remainingDelta);
		assertEquals(1, result.taskUnitsConsumed);
	}

	// --- 4. Gargoyles 138 -> 136 -> one PROGRESS, delta=-2, consumed=2 ---

	@Test
	public void scenario4_gargoyles138to136_progressOnly()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		SlayerState current = task("Gargoyles", "Wilderness", 136);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.PROGRESS, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
		assertEquals(-2, result.remainingDelta);
		assertEquals(2, result.taskUnitsConsumed);
	}

	// --- 5. Gargoyles 138 -> 138 -> NONE ---

	@Test
	public void scenario5_gargoyles138to138_none()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.NONE, result.kind);
	}

	// --- 6/7/8/9. same task/count, only progress-metadata fields change -> NONE, never ASSIGNED ---

	@Test
	public void scenario6_sameTask_pointsChangeOnly_none()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		previous.setPoints(500);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		current.setPoints(505);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.NONE, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
	}

	@Test
	public void scenario7_sameTask_streakChangeOnly_none()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		previous.setStreak(40);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		current.setStreak(41);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.NONE, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
	}

	@Test
	public void scenario8_sameTask_initialAmountChangeOnly_none()
	{
		// initialAmount changing with everything else fixed shouldn't
		// occur in real play, but identity/progress classification must
		// not be sensitive to it either way — it is explicitly
		// progress/metadata, not identity.
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		previous.setInitialAmount(140);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		current.setInitialAmount(150);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.NONE, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
	}

	@Test
	public void scenario9_sameTaskAndCount_unrelatedMetadataChanges_none()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		previous.setMasterId(7);
		previous.setStreakLabel("WILDERNESS");
		previous.setStreakSourceVerified(true);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		current.setMasterId(9);
		current.setStreakLabel("NORMAL");
		current.setStreakSourceVerified(false);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.NONE, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
	}

	// --- 10. Gargoyles -> no task -> existing COMPLETED behavior ---

	@Test
	public void scenario10_gargoylesToNoTask_completed()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 1);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, noTask());
		assertEquals(Kind.COMPLETED, result.kind);
	}

	// --- 11. Gargoyles -> different task -> ASSIGNED, never PROGRESS ---

	@Test
	public void scenario11_gargoylesToDifferentTask_assignedNotProgress()
	{
		// "Gargoyles 1 remaining -> Nechryaels 160 remaining is NOT +159
		// Slayer progress. It is a task lifecycle change." — even though
		// both previous and current have a nonzero remaining amount
		// (e.g. the old task's last kill also completed it and a new one
		// was handed out in the same settle window), a changed identity
		// must always win over any remaining-count arithmetic.
		SlayerState previous = task("Gargoyles", "Wilderness", 1);
		SlayerState current = task("Nechryaels", "Slayer Tower", 160);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.ASSIGNED, result.kind);
		assertNotEquals(Kind.PROGRESS, result.kind);
	}

	// --- 12. same task, remaining count increasing -> PROGRESS, positive delta, never ASSIGNED ---

	@Test
	public void scenario12_sameTaskRemainingIncreasing_progressPositiveDelta()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 137);
		SlayerState current = task("Gargoyles", "Wilderness", 138);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.PROGRESS, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
		assertEquals(1, result.remainingDelta);
		assertEquals(0, result.taskUnitsConsumed);
	}

	// --- 13. same task identity, very large decrement -> PROGRESS, never ASSIGNED ---

	@Test
	public void scenario13_sameTaskLargeDecrement_progress()
	{
		SlayerState previous = task("Gargoyles", "Wilderness", 138);
		SlayerState current = task("Gargoyles", "Wilderness", 120);
		SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
		assertEquals(Kind.PROGRESS, result.kind);
		assertNotEquals(Kind.ASSIGNED, result.kind);
		assertEquals(-18, result.remainingDelta);
		assertEquals(18, result.taskUnitsConsumed);
	}

	// --- 14. same task identity, only amountRemaining changes across several values -> never ASSIGNED ---

	@Test
	public void scenario14_sameTaskIdentity_onlyAmountRemainingVaries_neverAssigned()
	{
		int[][] transitions = {
			{138, 137}, {200, 1}, {50, 50}, {1, 2}, {999, 1}, {5, 999},
		};
		for (int[] transition : transitions)
		{
			SlayerState previous = task("Gargoyles", "Wilderness", transition[0]);
			SlayerState current = task("Gargoyles", "Wilderness", transition[1]);
			SlayerTransitionResult result = SlayerCollector.evaluateSlayerTransition(previous, current);
			assertNotEquals(
				"remaining " + transition[0] + " -> " + transition[1] + " must never be ASSIGNED",
				Kind.ASSIGNED, result.kind);
		}
	}

