	@Test
	public void ordinaryAndMultiUnitDecrements_thenFinalKill_thenCompletion()
	{
		run(() ->
		{
			game.setTask(5, GARGOYLES_TARGET, 0, AREA_TOWER, 180);
			runelite.loginSync();
			assertParity("start");
			int[] counts = {4, 2, 1, 0};
			for (int c : counts)
			{
				game.varps.put(VarPlayerID.SLAYER_COUNT, c);
				runelite.varbitUpdate();
				assertParity("remaining " + c);
			}
			assertEquals(SlayerNativeTask.Status.NO_TASK, reader.read().getStatus());
			// Duplicate / same-tick repeat of the completed state stays parity.
			runelite.varbitUpdate();
			assertParity("duplicate zero");
		});
	}

	@Test
	public void directReplacementAtoB_andRapidNextAssignmentAfterCompletion()
	{
		run(() ->
		{
			game.setTask(40, GARGOYLES_TARGET, 0, AREA_TOWER, 180);
			runelite.loginSync();
			game.setTask(150, ABERRANT_TARGET, 0, AREA_CATACOMBS, 150);
			runelite.varbitUpdate();
			assertParity("direct A->B");
			game.varps.put(VarPlayerID.SLAYER_COUNT, 0);
			runelite.varbitUpdate();
			game.setTask(170, GARGOYLES_TARGET, 0, 0, 170);
			runelite.varbitUpdate();
			assertParity("rapid next assignment");
		});
	}

	@Test
	public void bossTask_resolvesThroughBossSublistOnBothSides()
	{
		run(() ->
		{
			game.setTask(8, SlayerNativeTaskResolver.BOSS_TASK_TARGET, BOSS_ID_KRAKEN, 0, 8);
			runelite.loginSync();
			assertParity("boss task");
			assertEquals("Kraken", reader.read().getTaskName());
			game.varps.put(VarPlayerID.SLAYER_COUNT, 7);
			runelite.varbitUpdate();
			assertParity("boss kill");
		});
	}

	@Test
	public void quantityModifier_appliedIdentically()
	{
		run(() ->
		{
			game.setTask(100, GARGOYLES_TARGET, 0, 0, 150);
			game.varbits.put(VarbitID.SLAYER_MODIFIER_ID, 2);
			game.varbits.put(VarbitID.SLAYER_MODIFIER_VALUE, 30);
			game.varbits.put(VarbitID.SLAYER_MODIFIER_NEGATIVE, 1);
			runelite.loginSync();
			assertParity("negative modifier");
			assertEquals(120, reader.read().getInitialAmount());
		});
	}

	@Test
	public void missingCacheRow_runeliteKeepsPreviousState_nativeIsUnresolvedNotNoTask()
	{
		run(() ->
		{
			game.setTask(30, GARGOYLES_TARGET, 0, 0, 180);
			runelite.loginSync();
			game.setTask(25, 999, 0, 0, 25);
			runelite.varbitUpdate();
			assertEquals("RuneLite kept its previous task", "Gargoyles", runelite.taskName());
			assertTrue(reader.read().isUnresolved());
		});
	}

	/**
	 * The one documented divergence: RuneLite refreshes initialAmount only
	 * when the task name/location changes (or on a login sync). If
	 * SLAYER_COUNT_ORIGINAL arrives after the task was first resolved,
	 * RuneLite keeps the stale 0 while the native reader reports the real
	 * value -- the exact login transient SlayerCollector's
	 * preserveTrustworthyInitialAmount() was written around.
	 */
	@Test
	public void lateOriginalCount_nativeIsCurrent_runeliteStaysStale()
	{
		run(() ->
		{
			game.setTask(116, GARGOYLES_TARGET, 0, 0, 0);
			runelite.loginSync();
			assertParity("before original syncs");
			game.varps.put(VarPlayerID.SLAYER_COUNT_ORIGINAL, 137);
			runelite.varbitUpdate();
			assertEquals("RuneLite stays stale", 0, runelite.service.getInitialAmount());
			assertEquals("native reflects the varp", 137, reader.read().getInitialAmount());
			assertEquals("initial amount", parityMismatch(runelite.taskName(),
				runelite.service.getTaskLocation(), runelite.remaining(), runelite.service.getInitialAmount(), reader.read()));
		});
	}

	@Test
	public void accountSwitch_newAccountWithoutTask_bothClear()
	{
		run(() ->
		{
			game.setTask(60, GARGOYLES_TARGET, 0, AREA_TOWER, 180);
			runelite.loginSync();
			game.setTask(0, 0, 0, 0, 0);
			runelite.loginSync();
			assertParity("switched to account with no task");
		});
	}

	private interface Step
	{
		void run() throws Exception;
	}

	private static void run(Step step)
	{
		try
		{
			step.run();
		}
		catch (RuntimeException | Error e)
		{
			throw e;
		}
		catch (java.lang.reflect.InvocationTargetException e)
		{
			throw new AssertionError(e.getCause());
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Every resolution branch of RuneLite 1.13.1's SlayerPlugin.updateTask(),
 * reproduced by Spyglass's own pure resolver. The cache is a map-backed
 * fake (no Mockito in this project).
 */
public class SlayerNativeTaskResolverTest
{
	static final int GARGOYLES_TARGET = 46;
	static final int GARGOYLES_ROW = 9046;
	static final int BOSS_ID_KRAKEN = 3;
	static final int KRAKEN_ROW = 9300;
	static final int AREA_SLAYER_TOWER = 12;

	static final class FakeLookup implements SlayerTaskLookup
	{
		final Map<Integer, Integer> taskRows = new HashMap<>();
		final Map<Integer, Integer> bossRows = new HashMap<>();
		final Map<Integer, String> names = new HashMap<>();
		final Map<Integer, String> areas = new HashMap<>();

		@Override
		public Integer taskRowForTaskId(int taskId)
		{
			return taskRows.get(taskId);
		}

		@Override
		public Integer taskRowForBossId(int bossId)
		{
			return bossRows.get(bossId);
		}

		@Override
		public String taskName(int taskRow)
		{
			return names.get(taskRow);
		}

		@Override
		public String areaName(int areaId)
		{
			return areas.get(areaId);
		}
	}

	static FakeLookup standardCache()
	{
		FakeLookup l = new FakeLookup();
		l.taskRows.put(GARGOYLES_TARGET, GARGOYLES_ROW);
		l.names.put(GARGOYLES_ROW, "Gargoyles");
		l.bossRows.put(BOSS_ID_KRAKEN, KRAKEN_ROW);
		l.names.put(KRAKEN_ROW, "Kraken");
		l.areas.put(AREA_SLAYER_TOWER, "Slayer Tower");
		return l;
	}

	static SlayerNativeTaskResolver.RawVars raw(int count, int target, int boss, int area, int original)
	{
		return new SlayerNativeTaskResolver.RawVars(count, target, boss, area, original, 0, 0, 0);
	}

	@Test
	public void activeTask_resolvesNameRemainingInitial_noLocationWhenAreaZero()
	{
		SlayerNativeTask t = SlayerNativeTaskResolver.resolve(raw(137, GARGOYLES_TARGET, 0, 0, 180), standardCache());
		assertTrue(t.isActive());
		assertEquals("Gargoyles", t.getTaskName());
		assertNull(t.getTaskLocation());
		assertEquals(137, t.getRemaining());
		assertEquals(180, t.getInitialAmount());
	}

	@Test
	public void areaTask_resolvesLocationFromSlayerAreaTable()
	{
		SlayerNativeTask t = SlayerNativeTaskResolver.resolve(raw(50, GARGOYLES_TARGET, 0, AREA_SLAYER_TOWER, 60), standardCache());
		assertEquals("Slayer Tower", t.getTaskLocation());
	}

	@Test
	public void bossTask_target98_resolvesThroughBossSublist()
	{
		SlayerNativeTask t = SlayerNativeTaskResolver.resolve(
			raw(10, SlayerNativeTaskResolver.BOSS_TASK_TARGET, BOSS_ID_KRAKEN, 0, 10), standardCache());
		assertTrue(t.isActive());
		assertEquals("Kraken", t.getTaskName());
	}

	@Test
	public void zeroOrNegativeCount_isNoTask_evenWithStaleTargetAndArea()
	{
		assertEquals(SlayerNativeTask.Status.NO_TASK,
			SlayerNativeTaskResolver.resolve(raw(0, GARGOYLES_TARGET, 0, AREA_SLAYER_TOWER, 180), standardCache()).getStatus());
		assertEquals(SlayerNativeTask.Status.NO_TASK,
			SlayerNativeTaskResolver.resolve(raw(-1, GARGOYLES_TARGET, 0, 0, 180), standardCache()).getStatus());
		SlayerNativeTask none = SlayerNativeTaskResolver.resolve(raw(0, 0, 0, 0, 0), standardCache());
		assertNull(none.getTaskName());
		assertEquals(0, none.getRemaining());
		assertEquals(0, none.getInitialAmount());
	}

	@Test
	public void missingCacheRows_areUnresolved_neverNoTask()
	{
		FakeLookup cache = standardCache();
		assertTrue("unknown task id", SlayerNativeTaskResolver.resolve(raw(5, 999, 0, 0, 5), cache).isUnresolved());
		assertTrue("unknown boss id", SlayerNativeTaskResolver.resolve(
			raw(5, SlayerNativeTaskResolver.BOSS_TASK_TARGET, 77, 0, 5), cache).isUnresolved());
		assertTrue("unknown area", SlayerNativeTaskResolver.resolve(raw(5, GARGOYLES_TARGET, 0, 404, 5), cache).isUnresolved());
		cache.names.remove(GARGOYLES_ROW);
		assertTrue("row without a name", SlayerNativeTaskResolver.resolve(raw(5, GARGOYLES_TARGET, 0, 0, 5), cache).isUnresolved());
	}

	@Test
	public void quantityModifier_adjustsInitialAmount_onlyForModifierId2()
	{
		SlayerNativeTaskResolver.RawVars plus = new SlayerNativeTaskResolver.RawVars(100, GARGOYLES_TARGET, 0, 0, 150, 2, 25, 0);
		SlayerNativeTaskResolver.RawVars minus = new SlayerNativeTaskResolver.RawVars(100, GARGOYLES_TARGET, 0, 0, 150, 2, 25, 1);
		SlayerNativeTaskResolver.RawVars otherModifier = new SlayerNativeTaskResolver.RawVars(100, GARGOYLES_TARGET, 0, 0, 150, 1, 25, 0);
		assertEquals(175, SlayerNativeTaskResolver.resolve(plus, standardCache()).getInitialAmount());
		assertEquals(125, SlayerNativeTaskResolver.resolve(minus, standardCache()).getInitialAmount());
		assertEquals(150, SlayerNativeTaskResolver.resolve(otherModifier, standardCache()).getInitialAmount());
	}

	@Test
	public void initialAmount_mayBeZeroWhileOriginalVarpStillSyncing_neverGuessed()
	{
		SlayerNativeTask t = SlayerNativeTaskResolver.resolve(raw(116, GARGOYLES_TARGET, 0, 0, 0), standardCache());
		assertTrue(t.isActive());
		assertEquals(0, t.getInitialAmount());
	}

	@Test
	public void resolver_isStateless_sameInputSameResult()
	{
		FakeLookup cache = standardCache();
		SlayerNativeTaskResolver.RawVars r = raw(20, GARGOYLES_TARGET, 0, AREA_SLAYER_TOWER, 40);
		assertEquals(SlayerNativeTaskResolver.resolve(r, cache), SlayerNativeTaskResolver.resolve(r, cache));
		assertFalse(SlayerNativeTaskResolver.resolve(r, cache).equals(
			SlayerNativeTaskResolver.resolve(raw(19, GARGOYLES_TARGET, 0, AREA_SLAYER_TOWER, 40), cache)));
	}

	@Test
	public void rawCountOriginal_isRetainedForDiagnostics()
	{
		assertEquals(180, SlayerNativeTaskResolver.resolve(raw(137, GARGOYLES_TARGET, 0, 0, 180), standardCache())
			.getRaw().getCountOriginal());
	}
}

package com.osrstelemetry.plugin.collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.activity.GotrGameState;
import com.osrstelemetry.plugin.activity.StructuredActivityCatalog;
import com.osrstelemetry.plugin.activity.StructuredActivityRegistry;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;

/**
 * Guardians of the Rift through the real collector: native HUD / varbit /
 * script / chat / inventory inputs in, Spyglass events out. No other plugin.
 */
public class StructuredActivityCollectorGotrTest
{
	private static final long ACCOUNT = 4242L;
	private static final int GOTR_REGION = 14484;
	private static final int ESS = ItemID.GOTR_GUARDIAN_ESSENCE;

	private final List<Object[]> events = new ArrayList<>();
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final Map<Integer, String> widgetTexts = new HashMap<>();
	private boolean hudLoaded;
	private int tick = 100;
	private Map<Integer, Long> inventory = new HashMap<>();
	private StructuredActivityCollector collector;

	@Before
	public void setUp()
	{
		EventLedger ledger = new EventLedger(new Gson())
		{
			@Override
			public void append(long accountHash, EventType type, Object payload)
			{
				events.add(new Object[]{type, payload});
			}
		};
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (p, m, a) ->
		{
			switch (m.getName())
			{
				case "getAccountHash":
					return ACCOUNT;
				case "getTickCount":
					return tick;
				case "getGameState":
					return GameState.LOGGED_IN;
				case "getVarbitValue":
					return a.length == 1 ? varbits.getOrDefault((Integer) a[0], 0) : 0;
				case "getWidget":
					if (a.length == 1 && a[0] instanceof Integer)
					{
						int id = (Integer) a[0];
						if (id == InterfaceID.GotrHud.CONTENT)
						{
							return hudLoaded ? widget(null) : null;
						}
						return widgetTexts.containsKey(id) ? widget(widgetTexts.get(id)) : null;
					}
					return null;
				case "getItemContainer":
					return container(inventory);
				default:
					return defaultValue(m.getReturnType());
			}
		});
		collector = new StructuredActivityCollector(client, id -> "item" + id, ledger, StructuredActivityRegistry.defaults());
		varbits.put(VarbitID.GOTR_ELEMENTAL_EARNED_THIS_GAME, 0);
		varbits.put(VarbitID.GOTR_CATALYTIC_EARNED_THIS_GAME, 0);
	}

	private static Object defaultValue(Class<?> t)
	{
		if (t == boolean.class)
		{
			return false;
		}
		if (t == long.class)
		{
			return 0L;
		}
		if (t.isPrimitive() && t != void.class)
		{
			return 0;
		}
		return null;
	}

	private static Widget widget(String text)
	{
		return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class},
			(p, m, a) -> "getText".equals(m.getName()) ? text : defaultValue(m.getReturnType()));
	}

	private static ItemContainer container(Map<Integer, Long> items)
	{
		Item[] arr = new Item[items.size()];
		int i = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			arr[i++] = new Item(e.getKey(), (int) (long) e.getValue());
		}
		return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(), new Class<?>[]{ItemContainer.class},
			(p, m, a) -> "getItems".equals(m.getName()) ? arr : defaultValue(m.getReturnType()));
	}

	private void enterGotr()
	{
		collector.onRegion(GOTR_REGION);
		events.clear();
	}

	private void energy(int elemental, int catalytic)
	{
		varbits.put(VarbitID.GOTR_ELEMENTAL_EARNED_THIS_GAME, elemental);
		varbits.put(VarbitID.GOTR_CATALYTIC_EARNED_THIS_GAME, catalytic);
		tick++;
		collector.trackGotrTick();
	}

	private void inventory(long... idQty)
	{
		inventory = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			if (idQty[i + 1] > 0)
			{
				inventory.put((int) idQty[i], idQty[i + 1]);
			}
		}
		collector.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, container(inventory)));
	}

	private void runecraftXp(int xp)
	{
		collector.onStatChanged(new StatChanged(Skill.RUNECRAFT, xp, 77, 77));
	}

	@SuppressWarnings("unchecked")
	private <T> List<T> payloads(EventType type)
	{
		List<T> out = new ArrayList<>();
		for (Object[] e : events)
		{
			if (e[0] == type)
			{
				out.add((T) e[1]);
			}
		}
		return out;
	}

	// ---- CURRENT GAME ----------------------------------------------------

	@Test
	public void currentGame_powerFromTheHudScript_energyFromTheVarbits_keptThroughAShortGap_clearedAfterLeaving()
	{
		enterGotr();
		hudLoaded = true;
		collector.onGotrHudScript(new Object[]{5980, 280, 310, 620, 1000, 0, 0, 0, 0, 0, 0, 0});
		energy(280, 310);
		GotrGameState g = collector.getGotrGame();
		assertNotNull(g);
		assertEquals(Integer.valueOf(62), g.getGuardianPowerPercent());
		assertEquals(Integer.valueOf(280), g.getElementalEnergy());
		assertEquals(Integer.valueOf(310), g.getCatalyticEnergy());
		assertEquals(Integer.valueOf(590), g.getTotalEnergy());

		// Region load (stepping into an altar): the HUD is briefly absent.
		hudLoaded = false;
		energy(280, 310);
		assertEquals("a short HUD gap never collapses the current game", g, collector.getGotrGame());
		for (int i = 0; i < StructuredActivityCollector.GOTR_IN_GAME_GRACE_TICKS + 1; i++)
		{
			energy(280, 310);
		}
		assertNull("really left the game: never kept as stale state", collector.getGotrGame());
		hudLoaded = true;
		energy(0, 0);
		assertNull("power is unknown again until the HUD script reports it",
			collector.getGotrGame().getGuardianPowerPercent());
	}


	@Test
	public void hudScript_malformedArguments_areIgnored_otherScriptsNeverRead()
	{
		enterGotr();
		hudLoaded = true;
		collector.onGotrHudScript(new Object[]{5980, 1, 2});
		collector.onGotrHudScript(null);
		collector.onGotrHudScript(new Object[]{5980, 1, 2, "x", "y"});
		energy(5, 5);
		assertNull(collector.getGotrGame().getGuardianPowerPercent());
		assertEquals(Integer.valueOf(7), StructuredActivityCollector.intArg(new Object[]{"7"}, 0));
		assertNull(StructuredActivityCollector.intArg(new Object[]{"7"}, 3));
	}

	// ---- COMPLETION / FAILURE / SCORE ------------------------------------

	@Test
	public void wonGame_scoreThenCompletion_once_duplicateIgnored()
	{
		enterGotr();
		hudLoaded = true;
		energy(0, 0);
		energy(420, 380);
		collector.onGameMessage("Amount of rifts you have closed: 12.");
		collector.onGameMessage("Amount of rifts you have closed: 12.");
		List<EventPayloads.StructuredActivityScore> scores = payloads(EventType.STRUCTURED_ACTIVITY_SCORE);
		List<EventPayloads.StructuredActivityCompletion> done = payloads(EventType.STRUCTURED_ACTIVITY_COMPLETION);
		assertEquals(1, scores.size());
		assertEquals(1, done.size());
		assertEquals(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT, scores.get(0).getActivityKey());
		assertEquals(Integer.valueOf(800), scores.get(0).getPoints());
		assertTrue(scores.get(0).isObservedFromStart());
		assertEquals(Integer.valueOf(12), done.get(0).getCompletionCount());
	}

	@Test
	public void failedGame_neverCompletes_andItsEnergyNeverBecomesATrustedScore()
	{
		enterGotr();
		hudLoaded = true;
		energy(0, 0);
		energy(300, 300);
		collector.onGameMessage("The Great Guardian was defeated!");
		assertTrue(payloads(EventType.STRUCTURED_ACTIVITY_COMPLETION).isEmpty());
		assertTrue(payloads(EventType.STRUCTURED_ACTIVITY_SCORE).isEmpty());
		energy(300, 300);
		collector.onGameMessage("Amount of rifts you have closed: 13.");
		EventPayloads.StructuredActivityScore s = (EventPayloads.StructuredActivityScore) payloads(EventType.STRUCTURED_ACTIVITY_SCORE).get(0);
		assertFalse(s.isObservedFromStart());
	}

	// ---- REWARD POINTS ---------------------------------------------------

	@Test
	public void rewardPoints_baselineThenPerCurrencyGains_searchesNeverReduceEarned()
	{
		enterGotr();
		collector.onGameMessage("Total elemental energy: 41. Total catalytic energy: 39.");
		assertTrue("first balance is a baseline", payloads(EventType.STRUCTURED_ACTIVITY_CURRENCY).isEmpty());
		collector.onGameMessage("You found some loot: 3 x Nature rune");
		collector.onGameMessage("Total elemental energy: 47. Total catalytic energy: 46.");
		List<EventPayloads.StructuredActivityCurrency> c = payloads(EventType.STRUCTURED_ACTIVITY_CURRENCY);
		assertEquals(2, c.size());
		assertEquals(StructuredActivityCollector.GOTR_ELEMENTAL_POINTS, c.get(0).getCurrency());
		assertEquals(7, c.get(0).getGained());
		assertEquals(47, c.get(0).getBalance());
		assertEquals(StructuredActivityCollector.GOTR_CATALYTIC_POINTS, c.get(1).getCurrency());
		assertEquals(8, c.get(1).getGained());
	}

	@Test
	public void checkMessageBox_inTheTemple_isABaseline()
	{
		enterGotr();
		widgetTexts.put(InterfaceID.Messagebox.TEXT, "You have 39 catalytic energy and 41 elemental energy.");
		energy(0, 0);
		hudLoaded = true;
		energy(0, 0);
		widgetTexts.clear();
		collector.onGameMessage("Total elemental energy: 45. Total catalytic energy: 44.");
		List<EventPayloads.StructuredActivityCurrency> c = payloads(EventType.STRUCTURED_ACTIVITY_CURRENCY);
		assertEquals(2, c.size());
		assertEquals(4, c.get(0).getGained());
		assertEquals(5, c.get(1).getGained());
	}

	// ---- RUNES CRAFTED ---------------------------------------------------

	@Test
	public void altarCraft_essenceConsumedPlusRunesPlusRunecraftXp_isExactProduction()
	{
		enterGotr();
		hudLoaded = true;
		energy(0, 0);
		runecraftXp(1_000_000);
		inventory(ESS, 24, ItemID.NATURERUNE, 500);
		tick++;
		runecraftXp(1_000_480);
		inventory(ItemID.NATURERUNE, 548);
		List<EventPayloads.StructuredActivityProduction> p = payloads(EventType.STRUCTURED_ACTIVITY_PRODUCTION);
		assertEquals(1, p.size());
		assertEquals(StructuredActivityCatalog.GUARDIANS_OF_THE_RIFT, p.get(0).getActivityKey());
		assertEquals(1, p.get(0).getItems().size());
		assertEquals(ItemID.NATURERUNE, p.get(0).getItems().get(0).getItemId());
		assertEquals(48, p.get(0).getItems().get(0).getQuantity());
	}

	@Test
	public void rewardRunes_areLoot_neverCraftedRunes()
	{
		enterGotr();
		hudLoaded = true;
		energy(0, 0);
		runecraftXp(1_000_000);
		inventory(ESS, 10);
		collector.onGameMessage("You found some loot: 50 x Nature rune");
		inventory(ESS, 10, ItemID.NATURERUNE, 50);
		assertTrue(payloads(EventType.STRUCTURED_ACTIVITY_PRODUCTION).isEmpty());
		assertEquals(1, payloads(EventType.STRUCTURED_REWARD).size());
	}

	@Test
	public void arbitraryRunePickup_inTheGame_isNotProduction()
	{
		enterGotr();
		hudLoaded = true;
		energy(0, 0);
		runecraftXp(1_000_000);
