package com.osrstelemetry.plugin.events;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project.
 *
 * Covers TelemetryEventListener registration/notification directly
 * against the real EventLedger -- no mocking. This is also test letter
 * S from the wiring task's own list ("malformed/failed session
 * persistence -> telemetry ledger remains unaffected"), verified here
 * at its true source: a listener that throws must never affect the
 * durable write, since EventLedger is the one place that guarantee is
 * actually implemented.
 */
public class EventLedgerListenerTest
{
	private static final long TEST_ACCOUNT_HASH = 999_222_333L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("event-ledger-listener-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	@Test
	public void addedListener_isNotifiedSynchronouslyOnAppend()
	{
		List<EventType> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(type));

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		// No sleep/await at all -- notifyListeners() runs synchronously on
		// the calling thread, before append() even returns (see
		// EventLedger's own javadoc); this must already be true the
		// instant append() returns, unlike the durable disk write below.
		assertEquals(1, seen.size());
		assertEquals(EventType.QUEST_COMPLETED, seen.get(0));
	}

	@Test
	public void addedListener_isNotifiedOnAppendAndWaitToo()
	{
		List<EventType> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(type));

		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.BOSS_KILL,
			new EventPayloads.BossKill("zulrah", "Zulrah", 1, "AUTHORITATIVE"), 2000);

		assertEquals(1, seen.size());
	}

	@Test
	public void removedListener_receivesNoFurtherEvents()
	{
		AtomicInteger count = new AtomicInteger();
		TelemetryEventListener listener = (accountHash, type, payload, observedAt) -> count.incrementAndGet();

		ledger.addListener(listener);
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));
		assertEquals(1, count.get());

		ledger.removeListener(listener);
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 2, 3, 20));
		assertEquals("a removed listener must never be notified again", 1, count.get());
	}

	@Test
	public void reAddingAfterRemove_stillReceivesExactlyOneNotificationPerEvent()
	{
		// Regression coverage for the exact class of bug this project's
		// own client-thread lifecycle audit already found for EventBus
		// registration: addListener() on every re-enable without a
		// matching removeListener() on disable would silently accumulate
		// duplicate listeners.
		AtomicInteger count = new AtomicInteger();
		TelemetryEventListener listener = (accountHash, type, payload, observedAt) -> count.incrementAndGet();

		ledger.addListener(listener);
		ledger.removeListener(listener);
		ledger.addListener(listener);

		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals("re-adding after a proper removal must never result in double notification", 1, count.get());
	}

	@Test
	public void listenerThatThrows_neverPreventsOrCorruptsTheDurableWrite() throws Exception
	{
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated session-persistence failure");
		});

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("the durable telemetry event must be written regardless of a failing listener", 1, lines.size());
	}

	@Test
	public void oneListenerThrowing_neverPreventsOtherListenersFromRunning()
	{
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated failure in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void listenerReceivesTheSameAccountHashTypeAndPayloadPassedToAppend()
	{
		List<Object[]> seen = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seen.add(new Object[] {accountHash, type, payload, observedAt}));

		EventPayloads.QuestCompleted payload = new EventPayloads.QuestCompleted(42, "A_QUEST", "A Quest");
		Instant before = Instant.now();
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED, payload);
		Instant after = Instant.now();

		assertEquals(1, seen.size());
		Object[] call = seen.get(0);
		assertEquals(TEST_ACCOUNT_HASH, call[0]);
		assertEquals(EventType.QUEST_COMPLETED, call[1]);
		assertTrue("the exact same payload instance must be passed through, never a copy", call[2] == payload);
		Instant observedAt = (Instant) call[3];
		assertTrue(!observedAt.isBefore(before) && !observedAt.isAfter(after));
	}

	@Test
	public void appendBeforeStart_neverNotifiesListeners()
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		AtomicInteger count = new AtomicInteger();
		neverStarted.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		neverStarted.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals(
			"an event that was never durably queued must never be reported to a session listener either",
			0, count.get());
	}

	@Test
	public void appendAfterShutdown_neverNotifiesListeners()
	{
		// ADVERSARIAL HARDENING PASS, item 13.B -- this is the structural
		// proof of the enforced order, not just an exception-catching
		// test. EventLedger.append() now submits the durable write FIRST
		// and only calls notifyListeners() if that submission succeeds
		// (see EventLedger's own ordering comment). Once shutdown() has
		// been called, executor.submit() throws RejectedExecutionException
		// and append() returns before notifyListeners() is ever reached.
		// If the old (buggy) order were still in place -- notify first,
		// submit second -- this listener WOULD still fire even though the
		// write itself is rejected, since nothing about calling the
		// listener depends on the executor at all. This test can only
		// pass under the fixed order.
		AtomicInteger count = new AtomicInteger();
		ledger.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		ledger.shutdown();

		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP, new EventPayloads.LevelUp("FISHING", 1, 2, 10));

		assertEquals(
			"a durable write that was rejected (executor shut down) must never reach a session listener either -- "
				+ "proves submit-then-notify ordering, not just that exceptions are caught",
			0, count.get());
	}

	@Test
	public void appendAndWaitAfterShutdown_neverNotifiesListenersAndReturnsFalse()
	{
		// Same structural proof as above, for appendAndWait(): the
		// RejectedExecutionException path returns false immediately,
		// before notifyListeners() is reached.
		AtomicInteger count = new AtomicInteger();
		ledger.addListener((accountHash, type, payload, observedAt) -> count.incrementAndGet());

		ledger.shutdown();

		boolean result = ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 10), 2000);

		assertEquals("a rejected durable write must report failure to the caller", false, result);
		assertEquals(
			"a durable write that was rejected (executor shut down) must never reach a session listener either",
			0, count.get());
	}

	@Test
	public void listenerObservesEventBeforeAppendReturns_confirmingSynchronousNotificationAfterAcceptance()
	{
		// Confirms the OTHER half of the contract: when durable acceptance
		// DOES succeed (the normal case), notification is still
		// synchronous on the calling thread -- a session listener does
		// not need to poll or wait for a separate async callback. This
		// combined with the two tests above pins down the full order:
		// build envelope -> durable accept (submit) -> notify, all before
		// append()/appendAndWait() return to the caller.
		List<EventType> seenBeforeReturnCheck = new ArrayList<>();
		ledger.addListener((accountHash, type, payload, observedAt) -> seenBeforeReturnCheck.add(type));

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(7, "B_QUEST", "B Quest"));

		assertEquals("notification must have already happened by the time append() returns",
			1, seenBeforeReturnCheck.size());
	}

	@Test
	public void listenerThatThrowsAssertionError_neverPropagatesOutOfAppend() throws Exception
	{
		// TARGETED CORRECTNESS AUDIT, item 2: AssertionError extends
		// Error, NOT RuntimeException -- the original bug description
		// specifically called out that the old `catch (RuntimeException
		// e)` would NOT have caught this. This project has hit real
		// AssertionErrors during RuneLite development (per the audit
		// request), so this is not a theoretical case. If
		// notifyListeners() only caught RuntimeException, this
		// append() call would throw AssertionError right back out to
		// US -- the simulated collector -- which is exactly the failure
		// this test proves does not happen: append() must return
		// normally, and the durable write must still land on disk.
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated session-runtime bug, not a RuntimeException");
		});

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("an AssertionError thrown by a listener must never prevent the durable write either",
			1, lines.size());
	}

	@Test
	public void listenerThatThrowsAssertionError_neverPropagatesOutOfAppendAndWaitAndDurableResultUnaffected()
	{
		// Same proof as above, for appendAndWait() specifically: the
		// listener's AssertionError must not propagate to the collector
		// AND must not change the durable result the collector is
		// waiting on (the future's own outcome was already decided in
		// step (1), before notifyListeners() ever ran -- see
		// EventLedger's own updated ordering javadoc).
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated session-runtime bug in a shutdown-critical caller's listener");
		});

		boolean result = ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.BOSS_KILL,
			new EventPayloads.BossKill("zulrah", "Zulrah", 1, "AUTHORITATIVE"), 2000);

		assertEquals("a listener's AssertionError must never affect the durable write's own success result",
			true, result);
	}

	@Test
	public void oneListenerThrowingAssertionError_neverPreventsOtherListenersFromRunning()
	{
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new AssertionError("simulated bug in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void laterListenerStillRunsAfterAnEarlierOneThrowsRuntimeException()
	{
		// FINAL CORRECTION PASS: explicit "later listeners still run"
		// coverage for the RuntimeException case, matching the same
		// already-existing coverage for AssertionError below.
		AtomicInteger secondListenerCount = new AtomicInteger();

		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new RuntimeException("simulated failure in the first listener");
		});
		ledger.addListener((accountHash, type, payload, observedAt) -> secondListenerCount.incrementAndGet());

		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));

		assertEquals(1, secondListenerCount.get());
	}

	@Test
	public void listenerThatThrowsAFatalVirtualMachineError_isNotSwallowed()
	{
		// FINAL CORRECTION PASS: proves the narrowed catch boundary.
		// notifyListeners() now deliberately re-throws VirtualMachineError/
		// ThreadDeath rather than logging-and-swallowing them (see
		// EventLedger's own updated javadoc for the reasoning). A real
		// OutOfMemoryError/StackOverflowError can't be safely triggered
		// on demand in a test, so this uses a minimal anonymous
        // VirtualMachineError subclass -- a real, genuine instance of the
		// exact type the boundary is defined against, without actually
		// destabilizing the test JVM -- as the representative fatal case.
		ledger.addListener((accountHash, type, payload, observedAt) ->
		{
			throw new VirtualMachineError("simulated fatal JVM condition") {};
		});

		boolean propagated;
		try
		{
			ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
				new EventPayloads.QuestCompleted(1, "A_QUEST", "A Quest"));
			propagated = false;
		}
		catch (VirtualMachineError expected)
		{
			propagated = true;
		}

		assertTrue("a genuine VirtualMachineError thrown by a listener must propagate out of append(), "
			+ "not be logged and silently suppressed", propagated);
	}

	private void awaitQuiescence() throws InterruptedException
	{
		TimeUnit.MILLISECONDS.sleep(200);
	}
}

package com.osrstelemetry.plugin.events;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — this environment has no network access to
 * pull the RuneLite client jar this test compiles against (see
 * plugin/README.md). Run with `./gradlew test` locally as part of the
 * verification pass.
 *
 * Covers what's actually feasible to unit-test here: file-level
 * behavior of the ledger itself (unique IDs, one valid JSON object per
 * line, session ID stability within a run). It deliberately does not
 * try to test collector -> event routing, since that needs a live
 * Client/EventBus, which belongs in integration/manual testing instead
 * of being mocked into a false sense of coverage here.
 *
 * appendAndWait() TESTS: added
 * alongside the new synchronous/waitable append primitive introduced to
 * fix a bug where a fire-and-forget append() could be
 * dropped if EventLedger.shutdown() ran before its graceful drain
 * window got a chance to complete the queued write. These exercise
 * appendAndWait()'s actual success/rejection lifecycle end to end
 * (real file I/O, real executor), not just its return type.
 */
public class EventLedgerTest
{
	private static final long TEST_ACCOUNT_HASH = 999_000_111L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("event-ledger-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		// EventLedger now requires
		// start() before append() will do anything (see its
		// lifecycle javadoc) — this test was calling append() against
		// a ledger that had never been started, which is not how the
		// plugin actually uses it (start() is called from
		// OsrsTelemetryPlugin.startUp()).
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	@Test
	public void appendedEventsHaveUniqueIds() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332));
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 70, 71, 737627));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(2, lines.size());

		JsonObject first = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		JsonObject second = new JsonParser().parse(lines.get(1)).getAsJsonObject();

		assertNotEquals(
			"Two distinct events must never share an eventId — this is the entire idempotency mechanism",
			first.get("eventId").getAsString(),
			second.get("eventId").getAsString()
		);
	}

	@Test
	public void everyLineIsExactlyOneValidJsonObjectWithRequiredEnvelopeFields() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2343, "DESERT_TREASURE_II__THE_FALLEN_EMPIRE", "Desert Treasure II - The Fallen Empire"));

		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());

		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		assertTrue(event.has("eventId"));
		assertTrue(event.has("accountHash"));
		assertTrue(event.has("eventType"));
		assertTrue(event.has("occurredAt"));
		assertTrue(event.has("sessionId"));
		assertTrue(event.has("schemaVersion"));
		assertEquals("QUEST_COMPLETED", event.get("eventType").getAsString());
	}

	@Test
	public void sessionIdIsStableWithinARunAndChangesOnNewSession() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "QUEST_A", "Quest A"));
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2, "QUEST_B", "Quest B"));
		awaitQuiescence();

		ledger.startNewSession();
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(3, "QUEST_C", "Quest C"));
		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		String sessionA = new JsonParser().parse(lines.get(0)).getAsJsonObject().get("sessionId").getAsString();
		String sessionB = new JsonParser().parse(lines.get(1)).getAsJsonObject().get("sessionId").getAsString();
		String sessionC = new JsonParser().parse(lines.get(2)).getAsJsonObject().get("sessionId").getAsString();

		assertEquals("Events within one session must share a sessionId", sessionA, sessionB);
		assertNotEquals("startNewSession() must actually produce a new session id", sessionB, sessionC);
	}

	@Test
	public void appendBeforeStartIsSafeNoOp() throws Exception
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		neverStarted.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332));
		awaitQuiescence();

		assertTrue(
			"append() before start() must not produce a file",
			!TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH).exists()
		);
	}

	@Test
	public void enableDisableEnableCycleProducesAWorkingLedgerEachTime() throws Exception
	{
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 100));
		ledger.shutdown();

		// Re-start (simulates plugin disable -> re-enable within one
		// client process) — must not throw and must still work.
		ledger.start();
		ledger.append(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 2, 3, 300));
		awaitQuiescence();

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("both the pre- and post-restart appends must have been written", 2, lines.size());
	}

	// =====================================================================
	// appendAndWait() — synchronous/waitable append primitive
	// (bank-snapshot shutdown-durability pass)
	// =====================================================================

	@Test
	public void appendAndWait_returnsTrueAndEventIsOnDiskBeforeItReturns() throws Exception
	{
		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("MINING", 50, 51, 123456), 2000);

		assertTrue("appendAndWait() must report success for a normal append", success);

		// No awaitQuiescence() sleep here at all — the entire point of
		// appendAndWait() is that the event is already durable the
		// instant it returns.
		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());
		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();
		assertEquals("LEVEL_UP", event.get("eventType").getAsString());
	}

	@Test
	public void appendAndWait_buildsTheSameEnvelopeShapeAsAppend() throws Exception
	{
		ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(9001, "A_QUEST", "A Quest"), 2000);

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(1, lines.size());
		JsonObject event = new JsonParser().parse(lines.get(0)).getAsJsonObject();

		assertTrue(event.has("eventId"));
		assertTrue(event.has("accountHash"));
		assertTrue(event.has("eventType"));
		assertTrue(event.has("occurredAt"));
		assertTrue(event.has("sessionId"));
		assertTrue(event.has("schemaVersion"));
	}

	@Test
	public void appendAndWait_beforeStartReturnsFalseAndWritesNothing() throws Exception
	{
		EventLedger neverStarted = new EventLedger(TEST_GSON);
		boolean success = neverStarted.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 1, 2, 10), 2000);

		assertFalse("appendAndWait() before start() must report failure, not success", success);
		assertFalse(
			"appendAndWait() before start() must not produce a file",
			TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH).exists()
		);
	}

	@Test
	public void appendAndWait_afterShutdownReturnsFalseAndWritesNothing() throws Exception
	{
		ledger.shutdown();

		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 10), 2000);

		assertFalse("appendAndWait() must report failure once the ledger has been shut down", success);
	}

	@Test
	public void appendAndWait_ordersConsistentlyWithOrdinaryAppendOnTheSameLedger() throws Exception
	{
		// append() (async) followed immediately by appendAndWait() —
		// both go through the SAME single-writer executor, so
		// appendAndWait() returning must mean append()'s event landed
		// first (submission order == disk order for one writer thread).
		ledger.append(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "FIRST", "First"));
		boolean success = ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(2, "SECOND", "Second"), 2000);

		assertTrue(success);

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals(2, lines.size());
		JsonObject firstPayload = new JsonParser().parse(lines.get(0)).getAsJsonObject().getAsJsonObject("payload");
		JsonObject secondPayload = new JsonParser().parse(lines.get(1)).getAsJsonObject().getAsJsonObject("payload");
		assertEquals("First", firstPayload.get("questName").getAsString());
		assertEquals("Second", secondPayload.get("questName").getAsString());
	}

	@Test
	public void appendAndWait_enableDisableEnableCycleStillWorksEachTime() throws Exception
	{
		assertTrue(ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 1, 2, 100), 2000));

		ledger.shutdown();
		ledger.start();
		ledger.startNewSession();

		assertTrue(ledger.appendAndWait(
			TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("FISHING", 2, 3, 300), 2000));

		List<String> lines = Files.readAllLines(TestFilepaths.path(TelemetryPaths.eventsFile(TEST_ACCOUNT_HASH)));
		assertEquals("both the pre- and post-restart appendAndWait() calls must have succeeded and persisted", 2, lines.size());
	}

	private void awaitQuiescence() throws InterruptedException
	{
		// The ledger's writer executor is a single background thread;
		// give it a moment to drain rather than asserting immediately
		// after a fire-and-forget append().
		TimeUnit.MILLISECONDS.sleep(200);
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Integrity audit (History): a scan started for one account can never
 * publish into, or be indexed under, another account; no refresh request is
 * lost; a rejected submit never wedges refreshes; newest-first is by instant.
 */
public class HistoryAuditRaceTest
{
	private static final long ACCOUNT_A = 700_900_111L;
	private static final long ACCOUNT_B = 700_900_222L;
	private static final Gson GSON = new Gson();

	/** Runs submitted tasks only when the test says so. */
	private static final class ManualExecutor extends AbstractExecutorService
	{
		final List<Runnable> tasks = new ArrayList<>();
		boolean rejecting;

		@Override
		public void execute(Runnable command)
		{
			if (rejecting)
			{
				throw new RejectedExecutionException("rejecting");
			}
			tasks.add(command);
		}

		void runAll()
		{
			while (!tasks.isEmpty())
			{
				tasks.remove(0).run();
			}
		}

		@Override
		public void shutdown()
		{
		}

		@Override
		public List<Runnable> shutdownNow()
		{
			return Collections.emptyList();
		}

		@Override
		public boolean isShutdown()
		{
			return false;
		}

		@Override
		public boolean isTerminated()
		{
			return false;
		}

		@Override
		public boolean awaitTermination(long timeout, TimeUnit unit)
		{
			return true;
		}
	}

	private Path testRoot;
	private LocalStateStore store;
	private HistoryCoordinator history;
	private final ManualExecutor executor = new ManualExecutor();

	static Session finalized(String id, Instant finalizedAt)
	{
		return GSON.fromJson(("{'sessionId':'" + id + "','activityIdentity':{'activityType':'SKILLING','activityKey':'mining','displayName':'Mining'},"
			+ "'state':'FINALIZED','startedAt':'" + finalizedAt.minusSeconds(600) + "','lastActiveAt':'" + finalizedAt.minusSeconds(60)
			+ "','finalizedAt':'" + finalizedAt + "','accumulatedActiveDurationMillis':60000,'aggregates':{'xpGainedBySkill':{'MINING':100}}}")
			.replace('\'', '"'), Session.class);
	}

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("history-audit-race-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(GSON);
		store.start();
		SessionPersistence persistence = new SessionPersistence(store);
		Instant now = Instant.now();
		persistence.persistAdditionalFinalized(ACCOUNT_A, finalized("a-1", now.minusSeconds(300)));
		persistence.persistAdditionalFinalized(ACCOUNT_A, finalized("a-2", now.minusSeconds(200)));
		persistence.persistAdditionalFinalized(ACCOUNT_B, finalized("b-1", now.minusSeconds(100)));
		store.shutdown(); // drain: the files exist before any scan
		store.start();

		history = new HistoryCoordinator(store);
		java.lang.reflect.Field f = HistoryCoordinator.class.getDeclaredField("executor");
		f.setAccessible(true);
		f.set(history, executor);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private List<String> ids()
	{
		List<String> out = new ArrayList<>();
		for (HistoryEntry e : history.getRecentEntries())
		{
			out.add(e.getSessionId());
		}
		return out;
	}

	@Test
	public void accountSwitchBeforeTheQueuedScanRuns_showsAndIndexesOnlyTheNewAccount()
	{
		history.ensureAccountLoaded(ACCOUNT_A); // scan queued (worker busy from here)
		history.ensureAccountLoaded(ACCOUNT_B); // switch while it is in flight
		executor.runAll();
		assertEquals(Collections.singletonList("b-1"), ids());

		// B's index was never polluted with A's sessions.
		history.requestRefresh();
		executor.runAll();
		assertEquals(Collections.singletonList("b-1"), ids());
	}

	@Test
	public void accountSwitchDuringARunningScan_neverPublishesTheOldAccountIntoTheNewOne()
	{
		history.ensureAccountLoaded(ACCOUNT_A);
		AtomicInteger notifications = new AtomicInteger();
		history.setChangeListener(() ->
		{
			if (notifications.incrementAndGet() == 1)
			{
				// The first publication (account A) triggers the switch while
				// the worker is still running.
				history.ensureAccountLoaded(ACCOUNT_B);
			}
		});
		executor.runAll();
		assertEquals(Collections.singletonList("b-1"), ids());
		history.requestRefresh();
		executor.runAll();
		assertEquals(Collections.singletonList("b-1"), ids());
	}

	@Test
	public void manyRequestsWhileBusy_areServedByOneMoreScan_noneLost()
	{
		history.ensureAccountLoaded(ACCOUNT_A);
		for (int i = 0; i < 10; i++)
		{
			history.requestRefresh();
		}
		assertEquals("one worker at a time", 1, executor.tasks.size());
		executor.runAll();
		assertEquals(2, ids().size());
		assertEquals("worker released", 0, executor.tasks.size());
		history.requestRefresh();
		assertEquals("a later request starts a new scan", 1, executor.tasks.size());
		executor.runAll();
	}

	@Test
	public void rejectedSubmit_neverWedgesLaterRefreshes()
	{
		executor.rejecting = true;
		history.ensureAccountLoaded(ACCOUNT_A); // must not throw into login handling
		executor.rejecting = false;
		history.requestRefresh();
		assertEquals("a later request still starts a scan", 1, executor.tasks.size());
		executor.runAll();
		assertEquals(2, ids().size());
	}

	@Test
	public void rejectedDetailLoad_answersNull()
	{
		history.ensureAccountLoaded(ACCOUNT_A);
		executor.runAll();
		executor.rejecting = true;
		AtomicReference<Object> result = new AtomicReference<>("unset");
		history.loadDetail("a-1", result::set);
		assertNull(result.get());
	}

	@Test
	public void requestsBeforeAnyAccountIsLoaded_scanNothing()
	{
		history.requestRefresh();
		assertTrue(executor.tasks.isEmpty());
	}

	@Test
	public void newestFirst_isByInstant_evenWithinOneSecond()
	{
		Instant second = Instant.now().truncatedTo(ChronoUnit.SECONDS).minusSeconds(30);
		HistoryIndex index = new HistoryIndex();
		SessionPersistence persistence = new SessionPersistence(store);
		persistence.persistAdditionalFinalized(ACCOUNT_B + 1, finalized("whole", second));
		persistence.persistAdditionalFinalized(ACCOUNT_B + 1, finalized("later", second.plusMillis(500)));
		store.shutdown();
		store.start();
		List<HistoryEntry> entries = index.refresh(ACCOUNT_B + 1, persistence, Duration.ofDays(10), Instant.now());
		assertEquals("later", entries.get(0).getSessionId());
		assertEquals("whole", entries.get(1).getSessionId());
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import java.time.Instant;
import org.junit.Test;

/**
 * Pure
 * coverage of HistoryEntry.from()'s summary-building and its
 * fail-open null-return contract. Uses only PUBLIC
 * session-package API (SessionLifecycleEngine, Session's getters,
 * SessionAggregates' live map) -- this test class deliberately lives
 * in the history package, the same package HistoryEntry/HistoryIndex/
 * HistoryCoordinator live in, and never needs Session's
 * package-private setters.
 */
public class HistoryEntryTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static Session buildFinalizedSession()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		return engine.advanceTime(expiry).getFinalized();
	}

	@Test
	public void from_validFinalizedSession_buildsSummary()
	{
		Session session = buildFinalizedSession();

		HistoryEntry entry = HistoryEntry.from(session);

		assertNotNull(entry);
		assertEquals(session.getSessionId(), entry.getSessionId());
		assertEquals(GARGOYLES, entry.getActivityIdentity());
		assertEquals(session.getFinalizedAt(), entry.getFinalizedAt());
		assertEquals(session.getStartedAt(), entry.getStartedAt());
		assertEquals(session.getAccumulatedActiveDurationMillis(), entry.getAccumulatedActiveDurationMillis());
		assertFalse("no loadout was ever attached to this session", entry.isHasStartingLoadout());
		assertFalse(entry.isHasEndingLoadout());
	}

	@Test
	public void from_nullSession_returnsNull()
	{
		assertNull(HistoryEntry.from(null));
	}

	@Test
	public void from_sessionMissingFinalizedAt_returnsNull()
	{
		// An ACTIVE session -- finalizedAt is null. HistoryEntry.from()
		// must refuse it rather than fabricate a "finalized" summary.
		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();

		assertNull(HistoryEntry.from(session));
	}

	@Test
	public void from_sumsXpAcrossAllSkills()
	{
		Session session = buildFinalizedSession();
		session.getAggregates().getXpGainedBySkill().put("SLAYER", 500L);
		session.getAggregates().getXpGainedBySkill().put("STRENGTH", 120L);

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(620L, entry.getTotalXpGained());
	}

	@Test
	public void from_countsLootDropGroups()
	{
		Session session = buildFinalizedSession();
		session.getAggregates().getLootDrops().add(new com.osrstelemetry.plugin.session.SessionAggregates.LootDropGroup());
		session.getAggregates().getLootDrops().add(new com.osrstelemetry.plugin.session.SessionAggregates.LootDropGroup());

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(2, entry.getLootDropCount());
	}

	@Test
	public void from_emptyAggregates_totalXpZero_noException()
	{
		Session session = buildFinalizedSession();

		HistoryEntry entry = HistoryEntry.from(session);

		assertEquals(0L, entry.getTotalXpGained());
		assertEquals(0, entry.getLootDropCount());
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Real-file
 * coverage of HistoryIndex.refresh() -- discovery, the ~10 day display
 * window filter, newest-first ordering, never-re-parse-once-indexed,
 * and fail-open skipping of a malformed file.
 * Matches SessionPersistenceTest/SessionLoadoutBackwardCompatibilityTest's
 * own established real-file, no-Client style.
 */
public class HistoryIndexTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_222L;
	private static final Instant NOW = Instant.parse("2026-01-15T12:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");
	private static final Gson TEST_GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("history-index-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(TEST_GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	/** Writes a real finalized session file directly (bypassing the async store) so tests don't need to wait on it. */
	private static void writeSessionFileDirect(long accountHash, String sessionId, String finalizedAt) throws Exception
	{
		String json = "{"
			+ "\"sessionId\":\"" + sessionId + "\","
			+ "\"activityIdentity\":{\"activityType\":\"SLAYER\",\"activityKey\":\"gargoyles:catacombs\",\"displayName\":\"Gargoyles\"},"
			+ "\"state\":\"FINALIZED\","
			+ "\"startedAt\":\"2026-01-01T10:00:00Z\","
			+ "\"finalizedAt\":\"" + finalizedAt + "\","
			+ "\"accumulatedActiveDurationMillis\":60000,"
			+ "\"aggregates\":{\"xpGainedBySkill\":{},\"lootDrops\":[]}"
			+ "}";
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(accountHash, sessionId)), json.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void refresh_discoversRealFinalizedSession() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-1", "2026-01-15T11:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(1, result.size());
		assertEquals("session-1", result.get(0).getSessionId());
	}

	@Test
	public void refresh_emptyDirectory_returnsEmptyList()
	{
		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertTrue(result.isEmpty());
	}

	@Test
	public void refresh_ordersNewestFirst() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-old", "2026-01-10T10:00:00Z");
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-new", "2026-01-15T10:00:00Z");
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-mid", "2026-01-12T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(3, result.size());
		assertEquals("session-new", result.get(0).getSessionId());
		assertEquals("session-mid", result.get(1).getSessionId());
		assertEquals("session-old", result.get(2).getSessionId());
	}

	@Test
	public void refresh_excludesSessionsOutsideDisplayWindow_butKeepsThemIndexedForCount() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-recent", "2026-01-14T10:00:00Z");
		// 20 days before NOW -- outside a 10-day window.
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-ancient", "2025-12-26T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals(1, result.size());
		assertEquals("session-recent", result.get(0).getSessionId());
		// The old file was never deleted, and IS still tracked internally
		// (display-only retention: old files are never deleted) --
		// it is simply excluded from the returned display snapshot.
		assertEquals(2, index.indexedCount());
		assertTrue(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-ancient").exists());
	}

	@Test
	public void refresh_malformedFile_skippedWithoutCrashingOtherEntries() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-good", "2026-01-15T10:00:00Z");
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-corrupt")),
			"{ not valid json at all".getBytes(StandardCharsets.UTF_8));

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("a malformed session file must be skipped, never crash the whole refresh",
			1, result.size());
		assertEquals("session-good", result.get(0).getSessionId());
	}

	@Test
	public void refresh_calledTwice_doesNotReParseAlreadyIndexedFiles() throws Exception
	{
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-1", "2026-01-15T10:00:00Z");

		HistoryIndex index = new HistoryIndex();
		index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);
		assertEquals(1, index.indexedCount());

		// Corrupt the already-indexed file on disk -- if refresh() were
		// re-parsing it, this second call would now fail to find it (or
		// throw); since it must never re-read an already-indexed file,
		// the cached entry is untouched and still present.
		Files.write(TestFilepaths.path(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-1")),
			"{ corrupted after first index".getBytes(StandardCharsets.UTF_8));

		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("an already-indexed session must never be re-parsed from disk",
			1, result.size());
		assertEquals("session-1", result.get(0).getSessionId());
	}

	@Test
	public void refresh_realSessionPersistenceWrite_discoveredCorrectly() throws Exception
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, NOW.minusSeconds(3600));
		Instant suspendedAt = NOW.minusSeconds(3600).plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), expiry.plusSeconds(60));

		assertEquals(1, result.size());
		assertEquals(finalized.getSessionId(), result.get(0).getSessionId());
	}

	@Test
	public void refresh_differentAccounts_neverCrossContaminate() throws Exception
	{
		long otherAccountHash = 888_777_111L;
		deleteAccountDir(otherAccountHash);
		try
		{
			writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-a", "2026-01-15T10:00:00Z");
			writeSessionFileDirect(otherAccountHash, "session-b", "2026-01-15T10:00:00Z");

			HistoryIndex index = new HistoryIndex();
			List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

			assertEquals(1, result.size());
			assertEquals("session-a", result.get(0).getSessionId());
		}
		finally
		{
			deleteAccountDir(otherAccountHash);
		}
	}

	@Test
	public void refresh_skippedMalformedFile_retriedOnNextRefresh() throws Exception
	{
		File corruptFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "session-fixable"));
		Files.write(corruptFile.toPath(), "{ not valid json".getBytes(StandardCharsets.UTF_8));

		HistoryIndex index = new HistoryIndex();
		List<HistoryEntry> first = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);
		assertTrue(first.isEmpty());

		// The file "heals" (e.g. a retried write completes) between polls.
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "session-fixable", "2026-01-15T10:00:00Z");

		List<HistoryEntry> second = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);

		assertEquals("a file that was skipped for being malformed must be retried, not permanently blacklisted",
			1, second.size());
	}

	@Test
	public void refresh_corruptFile_isReadOnce_untilItChangesOnDisk() throws Exception
	{
		Path file = TestFilepaths.path(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "broken"));
		Files.write(file, "{ not json".getBytes(StandardCharsets.UTF_8));
		java.nio.file.attribute.FileTime stamp = java.nio.file.attribute.FileTime.fromMillis(1_700_000_000_000L);
		Files.setLastModifiedTime(file, stamp);

		HistoryIndex index = new HistoryIndex();
		assertTrue(index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW).isEmpty());

		// Same file, same timestamp, now valid content: a re-scan must NOT re-read it
		// (before this fix every History open re-parsed and re-logged a bad file).
		writeSessionFileDirect(TEST_ACCOUNT_HASH, "broken", "2026-01-15T11:00:00Z");
		Files.setLastModifiedTime(file, stamp);
		assertTrue("unchanged rejected file is skipped", index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW).isEmpty());

		// Once it changes on disk it is retried -- a repaired file is never lost.
		Files.setLastModifiedTime(file, java.nio.file.attribute.FileTime.fromMillis(1_700_000_100_000L));
		List<HistoryEntry> result = index.refresh(TEST_ACCOUNT_HASH, persistence, Duration.ofDays(10), NOW);
		assertEquals(1, result.size());
		assertEquals("broken", result.get(0).getSessionId());
	}
}

package com.osrstelemetry.plugin.history;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionPersistence;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * History is refreshed when a finalized session file actually reaches disk
 * -- not by polling -- and announces a changed list once.
 */
public class HistoryInvalidationTest
{
	private static final long ACCOUNT = 700_900_970L;
	private static final Gson GSON = new Gson();

	private Path testRoot;
	private LocalStateStore store;
	private HistoryCoordinator history;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("history-invalidation-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(GSON);
		store.start();
		history = new HistoryCoordinator(store);
		history.start();
	}

	@After
	public void tearDown() throws Exception
	{
		history.shutdown();
		store.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static Session finalized(String id)
	{
		return GSON.fromJson(("{'sessionId':'" + id + "','activityIdentity':{'activityType':'SKILLING','activityKey':'mining','displayName':'Mining'},"
			+ "'state':'FINALIZED','startedAt':'" + java.time.Instant.now().minusSeconds(600) + "','lastActiveAt':'" + java.time.Instant.now().minusSeconds(60)
			+ "','finalizedAt':'" + java.time.Instant.now() + "','accumulatedActiveDurationMillis':60000,'aggregates':{'xpGainedBySkill':{'MINING':100}}}")
			.replace('\'', '"'), Session.class);
	}

	@Test
	public void finalizedFileWritten_refreshesHistory_andNotifiesOnce() throws Exception
	{
		history.ensureAccountLoaded(ACCOUNT);
		Thread.sleep(200);
		AtomicInteger changes = new AtomicInteger();
		CountDownLatch changed = new CountDownLatch(1);
		history.setChangeListener(() ->
		{
			changes.incrementAndGet();
			changed.countDown();
		});

		for (int i = 0; i < 5; i++)
		{
			history.getRecentEntries(); // pure reads never scan the sessions directory
		}
		assertEquals(0, history.getRecentEntries().size());

		SessionPersistence persistence = new SessionPersistence(store);
		persistence.setFinalizedWriteListener(history::requestRefresh);
		persistence.persistAdditionalFinalized(ACCOUNT, finalized("s-1"));

		assertTrue("History refreshed once the file was written", changed.await(5, TimeUnit.SECONDS));
		assertEquals(1, history.getRecentEntries().size());
		assertEquals("s-1", history.getRecentEntries().get(0).getSessionId());
		Thread.sleep(200);
		assertEquals("one changed list, one notification", 1, changes.get());

		history.requestRefresh();
		Thread.sleep(300);
		assertEquals("an unchanged re-scan does not notify", 1, changes.get());
	}

	@Test
	public void refreshRequestedWhileOneRuns_isNotLost() throws Exception
	{
		history.ensureAccountLoaded(ACCOUNT);
		SessionPersistence persistence = new SessionPersistence(store);
		persistence.setFinalizedWriteListener(history::requestRefresh);
		for (int i = 0; i < 5; i++)
		{
			persistence.persistAdditionalFinalized(ACCOUNT, finalized("s-" + i));
		}
		long deadline = System.currentTimeMillis() + 5000;
		while (history.getRecentEntries().size() < 5 && System.currentTimeMillis() < deadline)
		{
			Thread.sleep(50);
		}
		assertEquals(5, history.getRecentEntries().size());
	}

	@Test
	public void initialScanFlag_unknownUntilTheCurrentAccountHasBeenScanned() throws Exception
	{
		// Logged out / nothing loaded: "unknown", never "this player has no history".
		org.junit.Assert.assertFalse(history.isInitialScanComplete());
		history.ensureAccountLoaded(ACCOUNT);
		long deadline = System.currentTimeMillis() + 5000;
		while (!history.isInitialScanComplete() && System.currentTimeMillis() < deadline)
		{
			Thread.sleep(20);
		}
		assertTrue("scanned once: an empty list now really means no sessions", history.isInitialScanComplete());
		assertTrue(history.getRecentEntries().isEmpty());
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** Integrity audit continuation: the persisted collapse state is always the newest action, bulk or single. */
public class LootPreferenceSequenceTest
{
	private static final long ACCOUNT = 700_900_904L;
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-pref-sequence-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	@Test
	public void openAll_collapseAll_openOne_persistsExactlyThat()
	{
		List<String> keys = Arrays.asList("k1", "k2", "k3");
		LocalStateStore store = new LocalStateStore(new Gson());
		store.start();
		LootTrackerPreferences prefs = new LootTrackerPreferences(store);
		prefs.loadForAccount(ACCOUNT);
		prefs.setCollapsed(keys, false);
		prefs.setCollapsed(keys, true);
		prefs.setCollapsed(Collections.singletonList("k2"), false);
		store.shutdown();

		LocalStateStore again = new LocalStateStore(new Gson());
		again.start();
		LootTrackerPreferences reloaded = new LootTrackerPreferences(again);
		reloaded.loadForAccount(ACCOUNT);
		assertTrue(reloaded.isCollapsed("k1"));
		assertFalse(reloaded.isCollapsed("k2"));
		assertTrue(reloaded.isCollapsed("k3"));
		again.shutdown();
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Swing-independent coverage of {@link LootTrackerIndex} --
 * dedup, stable source identity (never merged), honest kill-count
 * semantics, and atomic per-record item-stack preservation. Plain
 * JUnit, no Mockito, matching this project's established test style.
 */
public class LootTrackerIndexTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");

	private static LootTrackerRecord record(String eventId, String sourceName, Integer sourceId, Instant at, LootTrackerItem... items)
	{
		return new LootTrackerRecord(eventId, sourceName, sourceId, at, Arrays.asList(items));
	}

	@Test
	public void apply_newRecord_createsSourceWithOneRecord()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		boolean applied = index.apply(record("e1", "Zulrah", 2042, T0,
			new LootTrackerItem(2444, "Zulrah's scales", 100)));

		assertTrue(applied);
		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(1, sources.size());
		assertEquals("Zulrah", sources.get(0).getSourceName());
		assertEquals(Integer.valueOf(2042), sources.get(0).getSourceId());
		assertEquals(1, sources.get(0).getKillCount());
	}

	@Test
	public void apply_duplicateEventId_dedupedAndSkipped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		LootTrackerRecord first = record("dup-1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 100));
		LootTrackerRecord duplicate = record("dup-1", "Zulrah", 2042, T0.plusSeconds(5), new LootTrackerItem(2444, "Zulrah's scales", 999));

		assertTrue(index.apply(first));
		assertFalse(index.apply(duplicate));

		LootTrackerSource source = index.snapshotSources().get(0);
		assertEquals(1, source.getKillCount());
		assertEquals(100L, source.getItemTotals().get(0).getQuantity());
	}

	@Test
	public void apply_nullEventId_neverDedupSkipped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		LootTrackerRecord a = record(null, "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 50));
		LootTrackerRecord b = record(null, "Zulrah", 2042, T0.plusSeconds(1), new LootTrackerItem(2444, "Zulrah's scales", 50));

		assertTrue(index.apply(a));
		assertTrue(index.apply(b));

		assertEquals(2, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void differentSourceIds_sameName_neverMerged()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Cave krystilia", 100, T0, new LootTrackerItem(1, "Bones", 1)));
		index.apply(record("e2", "Cave krystilia", 200, T0, new LootTrackerItem(1, "Bones", 1)));

		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(2, sources.size());
		assertFalse(sources.get(0).getSourceKey().equals(sources.get(1).getSourceKey()));
	}

	@Test
	public void nullSourceId_isItsOwnStableIdentity_distinctFromAnyRealId()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Goblin", null, T0, new LootTrackerItem(1, "Bones", 1)));
		index.apply(record("e2", "Goblin", 42, T0, new LootTrackerItem(1, "Bones", 1)));

		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(2, sources.size());
	}

	@Test
	public void sameSourceIdentity_recordsAccumulateAcrossMultipleApplyCalls()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Gargoyle", 412, T0, new LootTrackerItem(561, "Nature rune", 5)));
		index.apply(record("e2", "Gargoyle", 412, T0.plusSeconds(60), new LootTrackerItem(561, "Nature rune", 3)));
		index.apply(record("e3", "Gargoyle", 412, T0.plusSeconds(120), new LootTrackerItem(9, "Granite dust", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		// Honest kill count -- one per atomic SERVER_NPC_LOOT record, exactly RuneLite's own Loot Tracker semantics.
		assertEquals(3, source.getKillCount());
		// Individual-drop view preserves the exact atomic event boundaries, in observation order.
		assertEquals(3, source.getRecords().size());
		assertEquals(1, source.getRecords().get(0).getItems().size());

		// Grouped view sums quantities across records for the same item.
		List<LootTrackerItem> totals = source.getItemTotals();
		assertEquals(2, totals.size());
		LootTrackerItem natureRuneTotal = totals.get(0);
		assertEquals("Nature rune", natureRuneTotal.getItemName());
		assertEquals(8L, natureRuneTotal.getQuantity());
	}

	@Test
	public void snapshotSource_byKey_returnsNullWhenUnknown()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		assertNull(index.snapshotSource("nothing here"));
	}

	@Test
	public void snapshotSource_byKey_matchesSnapshotSourcesEntry()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Vorkath", 8061, T0, new LootTrackerItem(1, "Dragonbone", 1)));

		String key = index.snapshotSources().get(0).getSourceKey();
		LootTrackerSource bySingleLookup = index.snapshotSource(key);
		assertEquals("Vorkath", bySingleLookup.getSourceName());
		assertEquals(1, bySingleLookup.getKillCount());
	}

	@Test
	public void snapshotSources_isAFreshImmutableCopy_neverAffectedByLaterApply()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(2444, "Zulrah's scales", 100)));

		List<LootTrackerSource> before = index.snapshotSources();
		index.apply(record("e2", "Zulrah", 2042, T0.plusSeconds(1), new LootTrackerItem(2444, "Zulrah's scales", 50)));

		assertEquals(1, before.get(0).getKillCount());
		assertEquals(2, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void filteredAfter_null_returnsSameUnfilteredContent()
	{
		LootTrackerSource source = new LootTrackerSource("k", "Zulrah", 2042,
			Collections.singletonList(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(1, "x", 1))));
		LootTrackerSource same = source.filteredAfter(null);
		assertEquals(1, same.getKillCount());
	}

	@Test
	public void filteredAfter_excludesRecordsAtOrBeforeWatermark()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, T0, new LootTrackerItem(1, "x", 1)));
		index.apply(record("e2", "Zulrah", 2042, T0.plusSeconds(30), new LootTrackerItem(1, "x", 1)));
		index.apply(record("e3", "Zulrah", 2042, T0.plusSeconds(90), new LootTrackerItem(1, "x", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		LootTrackerSource filtered = source.filteredAfter(T0.plusSeconds(30));

		// e1 (at T0) and e2 (exactly at the watermark) are both excluded; only e3 remains.
		assertEquals(1, filtered.getKillCount());
	}

	@Test
	public void filteredAfter_recordWithNullObservedAt_isNeverDropped()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("e1", "Zulrah", 2042, null, new LootTrackerItem(1, "x", 1)));

		LootTrackerSource source = index.snapshotSources().get(0);
		LootTrackerSource filtered = source.filteredAfter(T0.plusSeconds(90));

		assertEquals(1, filtered.getKillCount());
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Integrity audit (Loot Tracker data side): recency independent of apply
 * order, account isolation of live events, and preference write ordering.
 */
public class LootTrackerIntegrityAuditTest
{
	private static final Instant T = Instant.parse("2026-09-20T12:00:00Z");
	private static final long ACCOUNT_A = 11L;
	private static final long ACCOUNT_B = 22L;

	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-integrity-audit-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static LootTrackerRecord record(String id, Instant at)
	{
		return new LootTrackerRecord(id, "Zulrah", 2042, at, Collections.singletonList(new LootTrackerItem(995, "Coins", 100)));
	}

	@Test
	public void liveRecordAppliedBeforeTheRebuildsOlderRecords_keepsTrueFirstAndLastObserved()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(record("live", T));                         // live drop lands first
		index.apply(record("old1", T.minusSeconds(5 * 86400))); // rebuild then appends history
		index.apply(record("old2", T.minusSeconds(86400)));
		LootTrackerSource source = index.snapshotSources().get(0);
		assertEquals(T.minusSeconds(5 * 86400), source.getFirstObservedAt());
		assertEquals(T, source.getLastObservedAt());
		assertEquals(T, source.filteredAfter(T.minusSeconds(2 * 86400)).getLastObservedAt());
	}

	@Test
	public void liveEventForAnotherAccount_neverLandsInTheLoadedAccountsIndex()
	{
		LootTrackerCoordinator coordinator = new LootTrackerCoordinator(new Gson());
		coordinator.start();
		coordinator.ensureAccountLoaded(ACCOUNT_A);
		coordinator.shutdown(); // drain the (empty) rebuild
		coordinator.start();
		EventPayloads.ServerNpcLoot loot = new EventPayloads.ServerNpcLoot("Zulrah", 2042,
			Collections.singletonList(new EventPayloads.ServerNpcLootItem(995, "Coins", 100)));

		coordinator.onEvent(ACCOUNT_B, EventType.SERVER_NPC_LOOT, loot, T, "b-1");
		assertTrue(coordinator.getIndex().snapshotSources().isEmpty());

		coordinator.onEvent(ACCOUNT_A, EventType.SERVER_NPC_LOOT, loot, T, "a-1");
		assertEquals(1, coordinator.getIndex().snapshotSources().size());
		coordinator.shutdown();
	}

	@Test
	public void openAllThenCollapseAll_finalPersistedStateIsTheLastAction() throws Exception
	{
		List<String> keys = Arrays.asList("k1", "k2", "k3");
		LocalStateStore store = new LocalStateStore(new Gson());
		store.start();
		LootTrackerPreferences prefs = new LootTrackerPreferences(store);
		prefs.loadForAccount(ACCOUNT_A);
		for (int i = 0; i < 25; i++)
		{
			prefs.setCollapsed(keys, false); // Open All
			prefs.setCollapsed(keys, true);  // Collapse All
		}
		store.shutdown();

		LocalStateStore reopened = new LocalStateStore(new Gson());
		reopened.start();
		LootTrackerPreferences reloaded = new LootTrackerPreferences(reopened);
		reloaded.loadForAccount(ACCOUNT_A);
		for (String key : keys)
		{
			assertTrue(key, reloaded.isCollapsed(key));
		}
		reloaded.setCollapsed(keys, false);
		reopened.shutdown();

		LocalStateStore third = new LocalStateStore(new Gson());
		third.start();
		LootTrackerPreferences again = new LootTrackerPreferences(third);
		again.loadForAccount(ACCOUNT_A);
		assertFalse(again.isCollapsed("k1"));
		third.shutdown();
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Arrays;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Exercises
 * {@link LootTrackerPersistence#rebuild} against a REAL events.jsonl
 * file, written by the real {@link EventLedger} -- the same
 * "real file I/O, real executor" integration-style coverage
 * EventLedgerTest already established for this project's telemetry
 * ledger, extended here to the read-back/rebuild side nothing
 * previously exercised. Confirms: only SERVER_NPC_LOOT lines are
 * picked up (every other event type in the same file is correctly
 * ignored), eventId-based dedup survives a real rebuild, and the
 * retention cutoff excludes lines observed before it.
 */
public class LootTrackerPersistenceTest
{
	private static final long TEST_ACCOUNT_HASH = 999_222_444L;
	private static final Gson TEST_GSON = new Gson();

	private EventLedger ledger;
	private final LootTrackerPersistence persistence = new LootTrackerPersistence(TEST_GSON);

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-tracker-persistence-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir();
		ledger = new EventLedger(TEST_GSON);
		ledger.start();
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		deleteAccountDir();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void deleteAccountDir() throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		if (dir.exists())
		{
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	private static EventPayloads.ServerNpcLoot loot(String sourceName, Integer sourceId, int itemId, String itemName, int qty)
	{
		return new EventPayloads.ServerNpcLoot(sourceName, sourceId,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(itemId, itemName, qty)));
	}

	@Test
	public void rebuild_onlyPicksUpServerNpcLootLines_ignoringEveryOtherEventType() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.LEVEL_UP,
			new EventPayloads.LevelUp("WOODCUTTING", 89, 90, 5346332), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.QUEST_COMPLETED,
			new EventPayloads.QuestCompleted(1, "QUEST_A", "Quest A"), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(1, applied);
		List<LootTrackerSource> sources = index.snapshotSources();
		assertEquals(1, sources.size());
		assertEquals("Zulrah", sources.get(0).getSourceName());
	}

	@Test
	public void rebuild_missingEventsFile_yieldsEmptyIndex_noException()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(0, applied);
		assertTrue(index.snapshotSources().isEmpty());
	}

	@Test
	public void rebuild_preservesMultipleRecordsForTheSameSource_asDistinctAtomicEvents() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Gargoyle", 412, 561, "Nature rune", 5), 2000);
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Gargoyle", 412, 561, "Nature rune", 3), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(2, applied);
		LootTrackerSource source = index.snapshotSources().get(0);
		assertEquals(2, source.getKillCount());
		assertEquals(8L, source.getItemTotals().get(0).getQuantity());
	}

	@Test
	public void rebuild_runTwiceAgainstTheSameIndex_isIdempotentViaEventIdDedup() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Vorkath", 8061, 1, "Dragonbone", 1), 2000);

		LootTrackerIndex index = new LootTrackerIndex();
		int firstRun = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);
		int secondRun = persistence.rebuild(TEST_ACCOUNT_HASH, index, null);

		assertEquals(1, firstRun);
		assertEquals(0, secondRun);
		assertEquals(1, index.snapshotSources().get(0).getKillCount());
	}

	@Test
	public void rebuild_retentionCutoff_excludesRecordsObservedBeforeIt() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);

		// A cutoff strictly in the future excludes everything ever
		// appended so far -- confirms the retention bound actually
		// takes effect, without a fragile real-clock timing assumption.
		Instant farFuture = Instant.now().plusSeconds(3600);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, farFuture);

		assertEquals(0, applied);
		assertTrue(index.snapshotSources().isEmpty());
	}

	@Test
	public void rebuild_retentionCutoff_includesRecordsObservedAtOrAfterIt() throws Exception
	{
		ledger.appendAndWait(TEST_ACCOUNT_HASH, EventType.SERVER_NPC_LOOT,
			loot("Zulrah", 2042, 2444, "Zulrah's scales", 100), 2000);

		Instant longAgo = Instant.now().minusSeconds(3600);

		LootTrackerIndex index = new LootTrackerIndex();
		int applied = persistence.rebuild(TEST_ACCOUNT_HASH, index, longAgo);

		assertEquals(1, applied);
	}
}

package com.osrstelemetry.plugin.loottracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.Arrays;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * STRUCTURED_REWARD as a first-class Loot Tracker input: canonical source
 * keys, alias canonicalization, unknown sources skipped, eventId dedup,
 * and the events.jsonl rebuild (mixed / legacy / NPC-only files).
 */
public class StructuredRewardLootTrackerTest
{
	private static final long ACCOUNT = 999_222_777L;
	private static final Gson GSON = new Gson();
	private static final Instant T0 = Instant.parse("2026-09-01T10:00:00Z");

	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("structured-reward-loot-tracker-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static EventPayloads.StructuredReward reward(String activity, String sourceKey, String name, int itemId, String itemName, int qty)
	{
		return new EventPayloads.StructuredReward(activity, sourceKey, name,
			Arrays.asList(new EventPayloads.StructuredRewardItem(itemId, itemName, qty)));
	}

	private static String envelope(String eventId, EventType type, Instant at, Object payload)
	{
		return GSON.toJson(new com.osrstelemetry.plugin.events.TelemetryEvent(eventId, Long.toString(ACCOUNT), type, at.toString(), "s", payload));
	}

	private void writeEvents(String... lines) throws Exception
	{
		StringBuilder sb = new StringBuilder();
		for (String l : lines)
		{
			sb.append(l).append('\n');
		}
		TelemetryPaths.eventsFile(ACCOUNT).write(sb.toString().getBytes(StandardCharsets.UTF_8),
			StandardOpenOption.CREATE, StandardOpenOption.APPEND);
	}

	private LootTrackerCoordinator live()
	{
		LootTrackerCoordinator c = new LootTrackerCoordinator(GSON);
		c.start();
		c.ensureAccountLoaded(ACCOUNT);
		c.shutdown();
		c.start();
		return c;
	}

	@Test
	public void liveReward_recordedUnderItsCanonicalSource_withTheEnvelopeEventId()
	{
		LootTrackerCoordinator c = live();
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("barrows", "barrows", "Barrows", 4708, "Ahrim's hood", 1), T0, "ev-1");
		LootTrackerSource src = c.getIndex().snapshotSource("structured:barrows");
		assertEquals("Barrows", src.getSourceName());
		assertNull(src.getSourceId());
		assertTrue(src.isStructuredReward());
		assertEquals("ev-1", src.getRecords().get(0).getEventId());
		assertEquals(4708, src.getRecords().get(0).getItems().get(0).getItemId());
		// The same envelope delivered again (e.g. live + concurrent rebuild) is one record.
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("barrows", "barrows", "Barrows", 4708, "Ahrim's hood", 1), T0, "ev-1");
		assertEquals(1, c.getIndex().snapshotSource("structured:barrows").getRecords().size());
		c.shutdown();
	}

	@Test
	public void sameCausalSource_underDifferentNames_isOneSource()
	{
		LootTrackerCoordinator c = live();
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("tempoross", "tempoross_reward_pool", "Tempoross Reward Pool", 995, "Coins", 1), T0, "a");
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("tempoross", null, "Reward pool (Tempoross)", 995, "Coins", 2), T0.plusSeconds(1), "b");
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("guardians_of_the_rift", null, "Rewards Guardian", 565, "Blood rune", 3), T0, "c");
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("guardians_of_the_rift", "guardians_of_the_rift", "Guardians of the Rift", 565, "Blood rune", 4), T0, "d");
		List<LootTrackerSource> sources = c.getIndex().snapshotSources();
		assertEquals(2, sources.size());
		LootTrackerSource pool = c.getIndex().snapshotSource("structured:tempoross_reward_pool");
		assertEquals("Tempoross Reward Pool", pool.getSourceName());
		assertEquals(2, pool.getRecords().size());
		assertEquals("Guardians of the Rift", c.getIndex().snapshotSource("structured:guardians_of_the_rift").getSourceName());
		c.shutdown();
	}

	@Test
	public void unknownSources_andNpcLootNames_areNeverGuessed()
	{
		LootTrackerCoordinator c = live();
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward(null, null, "Brimstone Chest", 995, "Coins", 1), T0, "x");
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("tempoross", null, "Casket (Tempoross)", 995, "Coins", 1), T0, "y");
		c.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, reward("wintertodt", null, "Supply crate (Wintertodt)", 995, "Coins", 1), T0, "z");
		assertTrue(c.getIndex().snapshotSources().isEmpty());
		c.shutdown();
	}

	@Test
	public void npcKeysUnchanged_andNamespacesNeverCollide()
	{
		String npc = LootTrackerIndex.sourceKey("Barrows", null);
		assertNotEquals(npc, LootTrackerIndex.structuredSourceKey("barrows"));
		assertFalse(LootTrackerIndex.isStructuredSourceKey(npc));
		assertFalse("an NPC literally named like a structured key is still an NPC key",
			LootTrackerIndex.isStructuredSourceKey(LootTrackerIndex.sourceKey("structured:barrows", 1)));
		assertEquals("Zulrah" + '\u0000' + "2042", LootTrackerIndex.sourceKey("Zulrah", 2042));
	}

	@Test
	public void rebuild_includesStructuredRewards_legacyPayloads_retention_andDedup() throws Exception
	{
		writeEvents(
			envelope("n1", EventType.SERVER_NPC_LOOT, T0, new EventPayloads.ServerNpcLoot("Zulrah", 2042,
				Arrays.asList(new EventPayloads.ServerNpcLootItem(2444, "Zulrah's scales", 100)))),
			envelope("r1", EventType.STRUCTURED_REWARD, T0.plusSeconds(10), reward("barrows", "barrows", "Barrows", 4708, "Ahrim's hood", 1)),
			// Written by the earlier build: no sourceKey, RuneLite's event name.
			"{\"eventId\":\"r2\",\"accountHash\":\"1\",\"eventType\":\"STRUCTURED_REWARD\",\"occurredAt\":\"" + T0.plusSeconds(20)
				+ "\",\"payload\":{\"activityKey\":\"tempoross\",\"sourceName\":\"Reward pool (Tempoross)\",\"items\":[{\"itemId\":995,\"itemName\":\"Coins\",\"quantity\":5}]}}",
			envelope("r3", EventType.STRUCTURED_REWARD, T0.plusSeconds(30), reward(null, null, "Brimstone Chest", 995, "Coins", 9)),
			envelope("r0", EventType.STRUCTURED_REWARD, T0.minusSeconds(3600 * 24 * 400), reward("barrows", "barrows", "Barrows", 995, "Coins", 1)),
			envelope("r1", EventType.STRUCTURED_REWARD, T0.plusSeconds(10), reward("barrows", "barrows", "Barrows", 4708, "Ahrim's hood", 1)));
		LootTrackerIndex index = new LootTrackerIndex();
		int applied = new LootTrackerPersistence(GSON).rebuild(ACCOUNT, index, T0.minusSeconds(3600 * 24 * 365));
		assertEquals("npc + barrows + legacy tempoross; unknown skipped, too-old skipped, duplicate eventId skipped", 3, applied);
		assertEquals(1, index.snapshotSource("structured:barrows").getRecords().size());
		assertEquals("Tempoross Reward Pool", index.snapshotSource("structured:tempoross_reward_pool").getSourceName());
		assertEquals(1, index.snapshotSource(LootTrackerIndex.sourceKey("Zulrah", 2042)).getRecords().size());
	}

	@Test
	public void rebuild_npcOnlyFile_isExactlyAsBefore() throws Exception
	{
