}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import org.junit.Test;

/**
 * Integrity audit continuation (session side): a cancelled task followed by
 * the SAME task is two instances; a corrupt saved state never leaves the
 * previous account's session live or aborts the account load.
 */
public class IntegrityAuditContinuationSessionTest extends SlayerCoordinatorTestSupport
{
	private static List<SessionAggregates.SlayerAssignmentRecord> ledger(Session s)
	{
		return s.getAggregates().getSlayerAssignments();
	}

	private Instant nechryaelTask(Instant start, int amount, int kills)
	{
		feed(SessionSignal.slayerTaskAssigned(start, NECH, NECH_LOC, amount), start);
		Instant t = start;
		int remaining = amount;
		for (int i = 0; i < kills; i++)
		{
			t = t.plusSeconds(60);
			remaining--;
			feed(SessionSignal.slayerTaskProgress(t, NECH, NECH_LOC, 1, remaining), t);
		}
		return t;
	}

	@Test
	public void cancelledTaskThenTheSameTaskAgain_isANewInstance_andThePriorIsSkipped()
	{
		Instant t = nechryaelTask(T0, 75, 3);
		feed(SessionSignal.slayerTaskCompleted(t.plusSeconds(10), NECH, null, true), t.plusSeconds(10));
		feed(SessionSignal.slayerTaskAssigned(t.plusSeconds(40), NECH, NECH_LOC, 120), t.plusSeconds(40));

		List<SessionAggregates.SlayerAssignmentRecord> records = ledger(current());
		assertEquals("same task after a cancel is a second instance", 2, records.size());
		assertEquals(SlayerAssignmentEndReason.REPLACED_EARLY, records.get(0).getEndReason());
		assertEquals(Integer.valueOf(3), records.get(0).getUnitsCompleted());
		assertEquals(Integer.valueOf(120), records.get(1).getInitialAmount());
		assertEquals(Integer.valueOf(120), records.get(1).getLatestRemaining());
		assertEquals(Integer.valueOf(0), records.get(1).getUnitsCompleted());
	}

	@Test
	public void duplicateAssignedObservationWithoutACancel_isStillIdempotent()
	{
		Instant t = nechryaelTask(T0, 75, 3);
		feed(SessionSignal.slayerTaskAssigned(t.plusSeconds(5), NECH, NECH_LOC, 72), t.plusSeconds(5));
		assertEquals(1, ledger(current()).size());
		assertEquals(Integer.valueOf(3), ledger(current()).get(0).getUnitsCompleted());
	}

	@Test
	public void cancelFlagDoesNotLeakPastTheAssignmentItPrecedes()
	{
		Instant t = nechryaelTask(T0, 75, 3);
		feed(SessionSignal.slayerTaskCompleted(t.plusSeconds(10), NECH, null, true), t.plusSeconds(10));
		feed(SessionSignal.slayerTaskAssigned(t.plusSeconds(40), NECH, NECH_LOC, 120), t.plusSeconds(40));
		feed(SessionSignal.slayerTaskProgress(t.plusSeconds(100), NECH, NECH_LOC, 1, 119), t.plusSeconds(100));
		// A repeated observation of the new assignment is a duplicate again.
		feed(SessionSignal.slayerTaskAssigned(t.plusSeconds(110), NECH, NECH_LOC, 119), t.plusSeconds(110));
		assertEquals(2, ledger(current()).size());
		assertEquals(Integer.valueOf(1), ledger(current()).get(1).getUnitsCompleted());
	}

	@Test
	public void corruptSavedStateForTheNextAccount_neverKeepsThePreviousAccountsSessionLive() throws Exception
	{
		nechryaelTask(T0, 75, 2);
		assertNotNull(current());
		long other = ACCOUNT + 1;
		Path file = TestFilepaths.path(TelemetryPaths.sessionStateFile(other));
		Files.createDirectories(file.getParent());
		String corrupt = "{\"sessionId\":\"broken\",\"state\":\"ACTIVE\"}";
		Files.write(file, corrupt.getBytes(StandardCharsets.UTF_8));

		coordinator.ensureAccountLoaded(other); // must not throw

		assertNull("no session carried over from the previous account", current());
		assertEquals("the unreadable file is left as it was", corrupt, new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
		// The coordinator really is on the new account now: its events are accepted.
		Instant later = T0.plusSeconds(3600);
		feed(SessionSignal.slayerTaskAssigned(later, KALPHITES, KALPHITE_LOC, 40), later);
		feed(SessionSignal.slayerTaskProgress(later.plusSeconds(60), KALPHITES, KALPHITE_LOC, 1, 39), later.plusSeconds(60));
		assertNotNull(current());
		assertEquals(KALPHITES, current().getActivityIdentity().getDisplayName());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * Regressions from the final integrity audit (session side): a cancelled
 * Slayer task is never a completion, a same-tick kill's loot follows the
 * session that kill creates, and a manual re-evaluate never drops signals
 * that were still pending when it was clicked.
 */
public class IntegrityAuditSessionTest extends SlayerCoordinatorTestSupport
{
	private static final int COINS = 995;

	private static List<SessionAggregates.SlayerAssignmentRecord> ledger(Session s)
	{
		return s.getAggregates().getSlayerAssignments();
	}

	private static SessionSignal loot(Instant at, String source, long qty)
	{
		List<SessionSignal.LootDrop> drops = new ArrayList<>();
		drops.add(new SessionSignal.LootDrop(COINS, "Coins", qty));
		return SessionSignal.serverNpcLoot(at, source, drops);
	}

	private static long coins(Session s)
	{
		long total = 0;
		for (SessionAggregates.LootDropGroup g : s.getAggregates().getLootDrops())
		{
			for (SessionAggregates.LootItemAggregate i : g.getItems())
			{
				if (i.getItemId() != null && i.getItemId() == COINS)
				{
					total += i.getQuantity();
				}
			}
		}
		return total;
	}

	private Instant nechryaelTask(Instant start, int amount, int kills)
	{
		feed(SessionSignal.slayerTaskAssigned(start, NECH, NECH_LOC, amount), start);
		Instant t = start;
		int remaining = amount;
		for (int i = 0; i < kills; i++)
		{
			t = t.plusSeconds(60);
			remaining--;
			feed(SessionSignal.slayerTaskProgress(t, NECH, NECH_LOC, 1, remaining), t);
		}
		return t;
	}

	/** Several signals as ONE closed game tick. */
	private void feedSameTick(Instant at, SessionSignal... signals)
	{
		for (SessionSignal s : signals)
		{
			coordinator.testEnqueueSignal(s.withGameTick(tick));
		}
		coordinator.testProcessTick(++tick, at);
	}

	// ------------------------------------------------------------ cancellation

	@Test
	public void cancelledTask_creditsNoUnseenUnits_isNeverCompleted_andNextAssignmentMarksItSkipped()
	{
		Instant t = nechryaelTask(T0, 75, 3);
		SessionAggregates.SlayerAssignmentRecord before = ledger(current()).get(0);
		assertEquals(Integer.valueOf(3), before.getUnitsCompleted());
		Integer deltaBefore = current().getAggregates().getSlayerProgressDelta();

		feed(SessionSignal.slayerTaskCompleted(t.plusSeconds(10), NECH, null, true), t.plusSeconds(10));

		SessionAggregates.SlayerAssignmentRecord r = ledger(current()).get(0);
		assertNull("a cancelled task is not COMPLETED", r.getEndReason());
		assertEquals("no fabricated units", Integer.valueOf(3), r.getUnitsCompleted());
		assertEquals("real remaining kept", Integer.valueOf(72), r.getLatestRemaining());
		assertEquals(deltaBefore, current().getAggregates().getSlayerProgressDelta());

		feed(SessionSignal.slayerTaskAssigned(t.plusSeconds(30), KALPHITES, KALPHITE_LOC, 100), t.plusSeconds(30));
		assertEquals(2, ledger(current()).size());
		assertEquals(SlayerAssignmentEndReason.REPLACED_EARLY, ledger(current()).get(0).getEndReason());
		assertEquals(Integer.valueOf(3), ledger(current()).get(0).getUnitsCompleted());
	}

	@Test
	public void realCompletion_stillReconcilesTheFinalUnit()
	{
		Instant t = nechryaelTask(T0, 3, 2);
		feed(SessionSignal.slayerTaskCompleted(t.plusSeconds(10), NECH, null, false), t.plusSeconds(10));
		SessionAggregates.SlayerAssignmentRecord r = ledger(current()).get(0);
		assertEquals(SlayerAssignmentEndReason.COMPLETED, r.getEndReason());
		assertEquals(Integer.valueOf(3), r.getUnitsCompleted());
	}

	@Test
	public void cancellationFlag_survivesTheEventMapperAndTickTagging()
	{
		EventPayloads.SlayerTaskCompleted cancelled = new EventPayloads.SlayerTaskCompleted(NECH, 5, "NORMAL", 70);
		cancelled.setCancelled(Boolean.TRUE);
		SessionSignal s = SessionEventMapper.map(EventType.SLAYER_TASK_COMPLETED, cancelled, T0);
		assertTrue(s.isSlayerTaskCancelled());
		assertTrue(s.withGameTick(9L).isSlayerTaskCancelled());

		// Old events (no field) and real completions stay completions.
		EventPayloads.SlayerTaskCompleted old = new Gson().fromJson(
			"{\"monster\":\"Nechryael\",\"streak\":5,\"streakLabel\":\"NORMAL\",\"points\":70}", EventPayloads.SlayerTaskCompleted.class);
		assertNull(old.getCancelled());
		assertTrue(!SessionEventMapper.map(EventType.SLAYER_TASK_COMPLETED, old, T0).isSlayerTaskCancelled());
		// A real completion serializes exactly as before (no new field in the JSON).
		String json = new Gson().toJson(new EventPayloads.SlayerTaskCompleted(NECH, 6, "NORMAL", 85));
		assertTrue(json, !json.contains("cancelled"));
	}

	// ------------------------------------------------------------ same-tick switch loot

	@Test
	public void offTaskLootRejectedBySlayerSession_followsTheSameTickBossKillIntoTheNewBossSession()
	{
		Instant t = nechryaelTask(T0, 50, 2);
		String slayerSessionId = current().getSessionId();
		assertEquals(ActivityType.SLAYER, current().getActivityIdentity().getActivityType());

		Instant kill = t.plusSeconds(20);
		feedSameTick(kill, SessionSignal.bossKill(kill, "Zulrah", 10), loot(kill, "Zulrah", 5000));

		Session now = current();
		assertTrue("the boss kill switched sessions", !slayerSessionId.equals(now.getSessionId()));
		assertEquals(ActivityType.BOSSING, now.getActivityIdentity().getActivityType());
		assertEquals("the kill's own loot belongs to the session it created", 5000L, coins(now));
		// Never copied into the old task's bucket.
		for (SessionAggregates.SlayerAssignmentRecord r : ledger(now) == null ? new ArrayList<SessionAggregates.SlayerAssignmentRecord>() : ledger(now))
		{
			assertTrue(r.getItems() == null || r.getItems().isEmpty());
		}
	}

	@Test
	public void offTaskLootAlone_isStillRejectedFromTheSlayerSession()
	{
		Instant t = nechryaelTask(T0, 50, 2);
		Instant at = t.plusSeconds(20);
		feed(loot(at, "Zulrah", 5000), at);
		assertEquals(ActivityType.SLAYER, current().getActivityIdentity().getActivityType());
		assertEquals(0L, coins(current()));
	}

	// ------------------------------------------------------------ manual re-evaluate

	@Test
	public void manualReEvaluate_neverDropsSignalsStillPendingForTheOpenTick()
	{
		Instant start = T0;
		coordinator.reEvaluateCurrentSession("Hill Giant", 2098, start);
		Session s = current();
		assertNotNull(s);
		assertEquals(ActivityType.COMBAT, s.getActivityIdentity().getActivityType());

		// A combat XP window and this NPC's loot are observed on the still-open tick...
		Instant observed = start.plusSeconds(40);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(observed, "ATTACK", 120L, start.plusSeconds(10)).withGameTick(tick));
		coordinator.testEnqueueSignal(loot(observed, "Hill Giant", 77).withGameTick(tick));
		// ...the player clicks Re-evaluate a moment later...
		coordinator.reEvaluateCurrentSession("Hill Giant", 2098, observed.plusMillis(300));
		assertTrue("re-evaluate is stamped before the pending signal",
			current().lastActiveAtInstant().isBefore(observed));
		// ...and the tick closes: nothing that was pending is dropped.
		coordinator.testProcessTick(++tick, observed.plusMillis(600));
		assertEquals(s.getSessionId(), current().getSessionId());
		assertEquals(Long.valueOf(120L), current().getAggregates().getXpGainedBySkill().get("ATTACK"));
		assertEquals(77L, coins(current()));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Dedicated full-stack (SessionRuntimeCoordinator + SessionPersistence +
 * LocalStateStore + real disk I/O) coverage for the INTERRUPTED-ACTIVITY
 * RESUME (A -> brief B -> A) feature's PERSISTENCE contract: restart
 * safety, the account-switch/orderly-shutdown boundaries ("no candidate
 * may disappear silently"), and the manual "Re-evaluate Session" path's
 * preserved corrective semantics (it must never manufacture a hidden
 * resumable prior session). See InterruptedActivityResumeEngineTest for
 * the pure engine-level lifecycle/metric-ownership/boundary coverage
 * this file deliberately does not re-prove.
 */
public class InterruptedActivityResumeCoordinatorTest
{
	private static final long ACCOUNT_A = 810_200_300L;
	private static final long ACCOUNT_B = 810_200_400L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionRuntimeCoordinator coordinator;
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("interrupted-activity-resume-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));

		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
	}

	@After
	public void tearDown() throws Exception
	{
		if (store != null)
		{
			store.shutdown();
		}
		if (testRoot != null)
		{
			TestFilepaths.rooted(testRoot).deleteRecursively();
		}
	}

	private Session readFinalizedFile(String sessionId) throws Exception
	{
		return store.readIfExists(TelemetryPaths.sessionFile(ACCOUNT_A, sessionId), Session.class);
	}

	// A genuine, confirmed ACTIVE Slayer(Gargoyles) -> Agility switch, via
	// the SAME real, two-observation-confirmed hysteresis path already
	// exhaustively proved elsewhere (see SessionRuntimeCoordinatorTest's
	// own liveBug_incidentalAgilityXpWhileActiveGargoyles... test, which
	// this mirrors) -- exists purely to set up "A parked, B current"
	// state with the minimum ceremony, not to re-prove that decision
	// itself.
	private String establishActiveGargoylesThenSwitchToAgility(Instant confirmingAt) throws Exception
	{
		coordinator.ensureAccountLoaded(ACCOUNT_A);
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(T0, "Gargoyles", "Catacombs", 1).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		String gargoylesSessionId = coordinator.testCurrentSession().getSessionId();

		Instant firstAgility = T0.plusSeconds(34);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(firstAgility, "AGILITY", 6L).withGameTick(2L));
		coordinator.testProcessTick(3L, firstAgility);

		coordinator.testEnqueueSignal(SessionSignal.xpChange(confirmingAt, "AGILITY", 4L).withGameTick(3L));
		coordinator.testProcessTick(4L, confirmingAt);

		return gargoylesSessionId;
	}

	// =====================================================================
	// REQUIRED TEST 12: restart AFTER the candidate has already expired
	// -- A finalizes exactly once, at T1, and no resumability remains.
	// T0 is a fixed point far in the past relative to whenever this test
	// actually executes, so ensureAccountLoaded()'s own real
	// Instant.now() is guaranteed to already be long past the
	// candidate's 5-minute window -- a completely realistic "restarted
	// the client long afterward" scenario, deterministic by construction
	// without needing to inject a fake clock.
	// =====================================================================
	@Test
	public void restartAfterCandidateExpiry_aFinalizesExactlyOnceAtT1_noResumabilityRemains() throws Exception
	{
		Instant confirmingAt = T0.plusSeconds(70);
		String gargoylesSessionId = establishActiveGargoylesThenSwitchToAgility(confirmingAt);
		Thread.sleep(300);

		InterruptedCandidateRecord beforeRestart = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNotNull("the parked Gargoyles candidate must be durably persisted before restart", beforeRestart);
		assertNull("A must not yet be finalized anywhere before restart", readFinalizedFile(gargoylesSessionId));

		// Simulate a client restart: a brand-new coordinator against the
		// SAME on-disk store/account.
		SessionRuntimeCoordinator restarted = new SessionRuntimeCoordinator(store);
		restarted.ensureAccountLoaded(ACCOUNT_A);

		Thread.sleep(300);
		Session finalizedA = readFinalizedFile(gargoylesSessionId);
		assertNotNull("A must finalize exactly once, durably, during rehydration", finalizedA);
		assertEquals(SessionState.FINALIZED, finalizedA.getState());
		assertEquals("A must finalize AT ITS OWN ORIGINAL interruption instant, never at restart time",
			confirmingAt.toString(), finalizedA.getFinalizedAt());

		InterruptedCandidateRecord afterRestart = new SessionPersistence(store).loadInterruptedCandidate(ACCOUNT_A);
		assertNull("no resumability may remain once the candidate has finalized", afterRestart);
	}

	// =====================================================================
	// REQUIRED TEST 13: account switch -- the parked candidate finalizes
	// under the OLD account only, never leaking into the new account.
	// =====================================================================
