		engine.onQualifyingActivity(COOKING, firstReturn, Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		Instant secondReturn = firstReturn.plusSeconds(10);
		LifecycleResult confirmed = engine.onQualifyingActivity(COOKING, secondReturn,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);

		assertEquals("C gets a brand new session", COOKING, confirmed.getCurrent().getActivityIdentity());
		assertFalse("C must never reuse A's own sessionId",
			aSessionId.equals(confirmed.getCurrent().getSessionId()));
		assertEquals("B must still finalize normally, at its own candidate-first-seen instant",
			bSessionId, confirmed.getFinalized().getSessionId());
		assertEquals(firstReturn.toString(), confirmed.getFinalized().getFinalizedAt());

		assertEquals("parked A must be finalized EXACTLY ONCE, via the additionalFinalized slot",
			SessionState.FINALIZED, confirmed.getAdditionalFinalized().getState());
		assertEquals(aSessionId, confirmed.getAdditionalFinalized().getSessionId());
		assertEquals("A's finalizedAt must be its ORIGINAL interruption timestamp (t1), never firstReturn/secondReturn",
			t1.toString(), confirmed.getAdditionalFinalized().getFinalizedAt());

		assertNull("the interrupted candidate slot must become null -- A is permanently gone",
			engine.getInterruptedCandidate());

		// A can never later resume -- a subsequent return to Woodcutting is a
		// brand new session, exactly like the pre-existing A -> B -> C test.
		Instant laterReturn = secondReturn.plusSeconds(10);
		LifecycleResult laterAttempt = engine.onQualifyingActivity(WOODCUTTING, laterReturn,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
		assertFalse("A cannot resurrect once permanently superseded by a second real switch",
			aSessionId.equals(laterAttempt.getCurrent().getSessionId()));
		assertFalse("the later session must not merely coincide with A's own startedAt either",
			aStartedAt.equals(laterAttempt.getCurrent().getStartedAt()));
	}

	// EQUIVALENT COVERAGE (per explicit follow-up instruction): the
	// AUTHORITATIVE/SPECIFIC-evidence immediate-switch call site (while
	// SUSPENDED, still within B's OWN resume window) must apply the
	// identical "non-matching real switch permanently kills parked A"
	// rule. (The MATCHING/resume half of this call site is already
	// covered by restartInsideWindow_bReloadsConservativelySuspended_
	// returningAStillResumesOriginalSessionId above.)
	@Test
	public void authoritativeImmediateSwitchWhileSuspended_notMatchingParkedA_finalizesAAndCreatesNewC()
	{
		SessionLifecycleEngine liveEngine = new SessionLifecycleEngine();
		String aSessionId = liveEngine.onQualifyingActivity(WOODCUTTING, T0).getCurrent().getSessionId();

		Instant t1 = T0.plusSeconds(60);
		LifecycleResult toB = liveEngine.onQualifyingActivity(CRAFTING, t1,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
		String bSessionId = toB.getCurrent().getSessionId();
		Session persistedCurrent = liveEngine.getCurrentSession();
		Session persistedCandidate = liveEngine.getInterruptedCandidate();
		Instant persistedInterruptedAt = liveEngine.getInterruptedCandidateInterruptedAt();
		Instant persistedExpiresAt = liveEngine.getInterruptedCandidateExpiresAt();

		Instant restartAt = t1.plusSeconds(120);
		SessionLifecycleEngine engine = SessionLifecycleEngine.rehydrate(
			persistedCurrent, restartAt, persistedCandidate, persistedInterruptedAt, persistedExpiresAt).getEngine();
		assertEquals(SessionState.SUSPENDED, engine.getCurrentSession().getState());

		// AUTHORITATIVE/SPECIFIC evidence for a non-matching identity (Zulrah,
		// BOSSING) -- an immediate switch, no confirmation needed.
		Instant switchAt = restartAt.plusSeconds(10);
		LifecycleResult switched = engine.onQualifyingActivity(ZULRAH, switchAt,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);

		assertEquals(ZULRAH, switched.getCurrent().getActivityIdentity());
		assertFalse(aSessionId.equals(switched.getCurrent().getSessionId()));
		assertEquals("B finalizes normally at the authoritative event's own timestamp",
			bSessionId, switched.getFinalized().getSessionId());
		assertEquals(switchAt.toString(), switched.getFinalized().getFinalizedAt());

		assertEquals("parked A must be finalized exactly once, via the additionalFinalized slot",
			SessionState.FINALIZED, switched.getAdditionalFinalized().getState());
		assertEquals(aSessionId, switched.getAdditionalFinalized().getSessionId());
		assertEquals("A's finalizedAt must be its ORIGINAL interruption instant (t1), never switchAt",
			t1.toString(), switched.getAdditionalFinalized().getFinalizedAt());
		assertNull("A must be permanently gone -- cannot later resume", engine.getInterruptedCandidate());
	}

	// EQUIVALENT COVERAGE, matching half: an event whose own timestamp is
	// PAST B's own (much longer, 30-minute) resume window, while a
	// matching parked A candidate is still eligible, must still resume A.
	// NOTE ON REACHABILITY: with the current fixed constants
	// (RESUME_WINDOW = 30 minutes, always > INTERRUPTED_RESUME_WINDOW =
	// SUSPEND_TIMEOUT = 5 minutes, and B always starts at-or-after A's own
	// interruption instant T1), B's own resume-window-elapsed boundary is
	// structurally ALWAYS at least 30 minutes later than A's own candidate
	// boundary -- so this exact call site can never see a still-eligible A
	// through ordinary elapsed real time; the top-level
	// expireInterruptedCandidateIfNeeded() housekeeping always resolves A
	// first. This test constructs the combination directly via
	// rehydrate()'s own raw candidate-expiry parameter (already an
	// established, legitimate technique in this file -- see the restart
	// tests above) purely to prove the DISPLACEMENT/RESUME code at this
	// third call site is itself correct, defensively, in case that
	// constant ordering ever changes.
	@Test
	public void resumeWindowElapsedSwitchWhileSuspended_matchingParkedA_resumesA()
	{
		SessionLifecycleEngine liveEngine = new SessionLifecycleEngine();
		String aSessionId = liveEngine.onQualifyingActivity(WOODCUTTING, T0).getCurrent().getSessionId();
		String aStartedAt = liveEngine.getCurrentSession().getStartedAt();

		Instant t1 = T0.plusSeconds(60);
		liveEngine.onQualifyingActivity(CRAFTING, t1, Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
		Session persistedCurrent = liveEngine.getCurrentSession();
		Session persistedCandidate = liveEngine.getInterruptedCandidate();
		Instant persistedInterruptedAt = liveEngine.getInterruptedCandidateInterruptedAt();
		// Artificially extended candidate expiry -- see this test's own
		// reachability note above.
		Instant extendedExpiresAt = t1.plusSeconds(3600);

		Instant restartAt = t1.plusSeconds(120);
		SessionLifecycleEngine engine = SessionLifecycleEngine.rehydrate(
			persistedCurrent, restartAt, persistedCandidate, persistedInterruptedAt, extendedExpiresAt).getEngine();
		assertEquals(SessionState.SUSPENDED, engine.getCurrentSession().getState());
		String bSessionId = engine.getCurrentSession().getSessionId();
		Instant bResumeExpiry = engine.getCurrentSession().resumeWindowExpiresAtInstant();

		// Strictly past B's OWN resume window, but still within A's
		// (artificially extended) candidate window.
		Instant elapsedReturn = bResumeExpiry.plusSeconds(1);
		LifecycleResult resumed = engine.onQualifyingActivity(WOODCUTTING, elapsedReturn,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);

		assertEquals("the ORIGINAL A sessionId must return", aSessionId, resumed.getCurrent().getSessionId());
		assertEquals("the ORIGINAL A startedAt must return", aStartedAt, resumed.getCurrent().getStartedAt());
		assertEquals(SessionState.ACTIVE, resumed.getCurrent().getState());
		assertEquals("B finalizes at its own deterministic resume-window-expiry instant, never elapsedReturn",
			bSessionId, resumed.getFinalized().getSessionId());
		assertEquals(bResumeExpiry.toString(), resumed.getFinalized().getFinalizedAt());
		assertNull("A's candidate slot must be fully consumed by the resume", engine.getInterruptedCandidate());
	}

	// EQUIVALENT COVERAGE, non-matching half of the same call site -- see
	// the reachability note on the matching test just above (identical
	// construction technique and rationale).
	@Test
	public void resumeWindowElapsedSwitchWhileSuspended_notMatchingParkedA_finalizesAAndCreatesNewC()
	{
		SessionLifecycleEngine liveEngine = new SessionLifecycleEngine();
		String aSessionId = liveEngine.onQualifyingActivity(WOODCUTTING, T0).getCurrent().getSessionId();

		Instant t1 = T0.plusSeconds(60);
		LifecycleResult toB = liveEngine.onQualifyingActivity(CRAFTING, t1,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
		String bSessionId = toB.getCurrent().getSessionId();
		Session persistedCurrent = liveEngine.getCurrentSession();
		Session persistedCandidate = liveEngine.getInterruptedCandidate();
		Instant persistedInterruptedAt = liveEngine.getInterruptedCandidateInterruptedAt();
		Instant extendedExpiresAt = t1.plusSeconds(3600);

		Instant restartAt = t1.plusSeconds(120);
		SessionLifecycleEngine engine = SessionLifecycleEngine.rehydrate(
			persistedCurrent, restartAt, persistedCandidate, persistedInterruptedAt, extendedExpiresAt).getEngine();
		Instant bResumeExpiry = engine.getCurrentSession().resumeWindowExpiresAtInstant();

		Instant elapsedReturn = bResumeExpiry.plusSeconds(1);
		LifecycleResult switched = engine.onQualifyingActivity(ZULRAH, elapsedReturn,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);

		assertEquals(ZULRAH, switched.getCurrent().getActivityIdentity());
		assertFalse(aSessionId.equals(switched.getCurrent().getSessionId()));
		assertEquals(bSessionId, switched.getFinalized().getSessionId());
		assertEquals(bResumeExpiry.toString(), switched.getFinalized().getFinalizedAt());

		assertEquals("parked A must be finalized exactly once, via the additionalFinalized slot",
			SessionState.FINALIZED, switched.getAdditionalFinalized().getState());
		assertEquals(aSessionId, switched.getAdditionalFinalized().getSessionId());
		assertEquals("A's finalizedAt must be its ORIGINAL interruption instant (t1), never elapsedReturn",
			t1.toString(), switched.getAdditionalFinalized().getFinalizedAt());
		assertNull("A must be permanently gone", engine.getInterruptedCandidate());
	}

	// REQUIRED TEST: a single, first weak observation alone must never
	// resume A and must never mutate the interrupted candidate at all --
	// B remains current (still SUSPENDED). This is the direct converse
	// half of the two tests above, isolated on its own.
	@Test
	public void firstWeakObservationAlone_neverResumesA_neverMutatesInterruptedCandidate_bRemainsCurrent()
	{
		SessionLifecycleEngine liveEngine = new SessionLifecycleEngine();
		String aSessionId = liveEngine.onQualifyingActivity(WOODCUTTING, T0).getCurrent().getSessionId();

		Instant t1 = T0.plusSeconds(60);
		LifecycleResult toB = liveEngine.onQualifyingActivity(CRAFTING, t1,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);
		String bSessionId = toB.getCurrent().getSessionId();
		Session persistedCurrent = liveEngine.getCurrentSession();
		Session persistedCandidate = liveEngine.getInterruptedCandidate();
		Instant persistedInterruptedAt = liveEngine.getInterruptedCandidateInterruptedAt();
		Instant persistedExpiresAt = liveEngine.getInterruptedCandidateExpiresAt();

		Instant restartAt = t1.plusSeconds(120);
		SessionLifecycleEngine engine = SessionLifecycleEngine.rehydrate(
			persistedCurrent, restartAt, persistedCandidate, persistedInterruptedAt, persistedExpiresAt).getEngine();

		Instant firstReturn = restartAt.plusSeconds(10);
		LifecycleResult armed = engine.onQualifyingActivity(WOODCUTTING, firstReturn,
			Arrays.asList(MetricUpdate.xp("woodcutting", 7)), EvidenceStrength.ORDINARY);

		assertNull(armed.getFinalized());
		assertNull(armed.getAdditionalFinalized());
		assertEquals("B must remain current -- unresumed", bSessionId, armed.getCurrent().getSessionId());
		assertEquals(SessionState.SUSPENDED, armed.getCurrent().getState());
		assertEquals("the parked A candidate must be completely untouched by a single arming observation",
			aSessionId, engine.getInterruptedCandidate().getSessionId());
		assertEquals(WOODCUTTING, engine.getInterruptedCandidate().getActivityIdentity());
		assertEquals(persistedInterruptedAt, engine.getInterruptedCandidateInterruptedAt());
		assertEquals(persistedExpiresAt, engine.getInterruptedCandidateExpiresAt());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Full-pipeline coverage proving SessionRuntimeCoordinator.
 * recordLiveXpDelta() -&gt; LiveXpTracker -&gt; getCurrentSessionSnapshot() -&gt;
 * CurrentSessionSnapshot.from() actually closes the player-visible
 * latency gap end to end, and that the reconciliation with the real,
 * durable XP_CHANGE path (via testEnqueueSignal()/testProcessTick(),
 * exactly like GenericNpcCombatRecognitionTest's own pipeline tests)
 * never double-counts. Deliberately kept in its own file, mirroring
 * GenericNpcCombatRecognitionTest's own precedent, so these
 * changes are reviewable independently of the large, already-green
 * SessionRuntimeCoordinatorTest suite.
 *
 * No mocking anywhere (this project has no Mockito dependency) -- every
 * test drives the real SessionRuntimeCoordinator/SessionLifecycleEngine/
 * CurrentSessionSnapshot classes directly.
 */
public class LiveXpDisplayIntegrationTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T00:00:00Z");
	private static final long ACCOUNT_LIVE_XP_TEST = 701_100_200L;
	private static final long ACCOUNT_LIVE_XP_TEST_B = 701_100_201L;
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionRuntimeCoordinator coordinator;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("live-xp-display-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir(ACCOUNT_LIVE_XP_TEST);
		deleteAccountDir(ACCOUNT_LIVE_XP_TEST_B);
		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(ACCOUNT_LIVE_XP_TEST);
		deleteAccountDir(ACCOUNT_LIVE_XP_TEST_B);
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void deleteAccountDir(long accountHash) throws Exception
	{
		File dir = TestFilepaths.file(TelemetryPaths.accountDir(accountHash));
		if (dir.exists())
		{
			File sessionsDir = new File(dir, "sessions");
			if (sessionsDir.exists())
			{
				File[] sessionFiles = sessionsDir.listFiles();
				if (sessionFiles != null)
				{
					for (File f : sessionFiles)
					{
						Files.deleteIfExists(f.toPath());
					}
				}
				Files.deleteIfExists(sessionsDir.toPath());
			}
			File[] files = dir.listFiles();
			if (files != null)
			{
				for (File f : files)
				{
					Files.deleteIfExists(f.toPath());
				}
			}
			Files.deleteIfExists(dir.toPath());
		}
	}

	// 1: a live XP delta updates the Current Session snapshot
	// immediately, before any XP_CHANGE has ever been processed.
	@Test
	public void liveXpDelta_showsImmediatelyInSnapshot_beforeXpChangeExists()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.npcInteractionTarget(T0, 601, "Goat").withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.testEnqueueSignal(SessionSignal.rawCombatXpObserved(T0.plusMillis(600), "Strength").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusMillis(600));

		// A COMBAT/Goat session now exists (established by the raw
		// lifecycle path) with zero durable XP yet -- exactly the
		// scenario the live XP layer exists to improve on.
		assertEquals(ActivitySignalClassifier.genericNpcCombatIdentity("Goat"), coordinator.testCurrentSession().getActivityIdentity());
		assertTrue(coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().isEmpty());

		coordinator.recordLiveXpDelta("STRENGTH", 40L);

		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(70));
		assertEquals(1, snapshot.getXpEntries().size());
		assertEquals("STRENGTH", snapshot.getXpEntries().get(0).getSkill());
		assertEquals(40L, snapshot.getXpEntries().get(0).getXpGained());
	}

	// 2: multiple live gains for the same skill accumulate correctly in the display.
	@Test
	public void multipleLiveGains_accumulateInTheDisplayedTotal()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.npcInteractionTarget(T0, 601, "Goat").withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.testEnqueueSignal(SessionSignal.rawCombatXpObserved(T0.plusMillis(600), "Strength").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusMillis(600));

		coordinator.recordLiveXpDelta("STRENGTH", 40L);
		coordinator.recordLiveXpDelta("STRENGTH", 15L);

		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(2));
		assertEquals(55L, snapshot.getXpEntries().get(0).getXpGained());
	}

	// 3: a later real XP_CHANGE covering the same underlying gains does
	// NOT double the displayed total -- the T0/T1/T2 worked example
	// (canonical 0 -> +40 live shows 40 -> XP_CHANGE flushes +40,
	// canonical becomes 40, display MUST remain 40, never 80).
	@Test
	public void laterXpChange_reconciles_neverDoublesTheDisplayedTotal()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.npcInteractionTarget(T0, 601, "Goat").withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.testEnqueueSignal(SessionSignal.rawCombatXpObserved(T0.plusMillis(600), "Strength").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusMillis(600));

		coordinator.recordLiveXpDelta("STRENGTH", 40L);
		CurrentSessionSnapshot beforeFlush = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(2));
		assertEquals(40L, beforeFlush.getXpEntries().get(0).getXpGained());

		// The same +40 now arrives via the real, durable XP_CHANGE path.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(30), "STRENGTH", 40).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(30));

		assertEquals(Long.valueOf(40L), coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().get("STRENGTH"));

		CurrentSessionSnapshot afterFlush = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(31));
		assertEquals("the displayed total must remain 40, never jump to 80", 40L, afterFlush.getXpEntries().get(0).getXpGained());
	}

	// 4/5: works identically for a non-combat skill (Woodcutting) and a
	// combat skill (Strength) in the same session's own snapshot.
	@Test
	public void liveXp_worksForNonCombatAndCombatSkillsTogether()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.npcInteractionTarget(T0, 601, "Goat").withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.testEnqueueSignal(SessionSignal.rawCombatXpObserved(T0.plusMillis(600), "Strength").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusMillis(600));

		coordinator.recordLiveXpDelta("STRENGTH", 40L);
		coordinator.recordLiveXpDelta("WOODCUTTING", 25L);

		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(2));
		assertEquals(2, snapshot.getXpEntries().size());
		long woodcutting = snapshot.getXpEntries().stream()
			.filter(e -> e.getSkill().equals("WOODCUTTING")).findFirst().get().getXpGained();
		long strength = snapshot.getXpEntries().stream()
			.filter(e -> e.getSkill().equals("STRENGTH")).findFirst().get().getXpGained();
		assertEquals(25L, woodcutting);
		assertEquals(40L, strength);
	}

	// 6: a genuine session switch must not carry the old session's
	// pending live XP into the new one's own display.
	@Test
	public void sessionSwitch_doesNotLeakOldSessionsLiveXpIntoTheNewOne()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);

		// Establish a first session (via the existing, unrelated boss-kill
		// lifecycle path -- Woodcutting has no dedicated lifecycle signal
		// in this codebase, but a genuine session-identity switch is a
		// session-identity switch regardless of activity type: this
		// exercises the SAME sessionId-keyed discard rule LiveXpTracker
		// implements -- see LiveXpTrackerTest for the isolated,
		// lower-level proof of the exact mechanism) and give it +100 live XP.
		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Zulrah", 5).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		String firstSessionId = coordinator.testCurrentSession().getSessionId();
		coordinator.recordLiveXpDelta("RANGED", 100L);
		assertEquals(100L, CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(2))
			.getXpEntries().get(0).getXpGained());

		// A genuinely different boss kill starts a brand-new session (a
		// real switch, not a heartbeat) -- its own live XP must start
		// from zero, never inheriting the old session's +100.
		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0.plusSeconds(10), "Vorkath", 3).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(10));
		String secondSessionId = coordinator.testCurrentSession().getSessionId();

		assertFalse("this must be a genuinely different session for this test to be meaningful",
			firstSessionId.equals(secondSessionId));

		CurrentSessionSnapshot afterSwitch = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(11));
		assertTrue("the new session must never display the old session's own live-pending XP",
			afterSwitch.getXpEntries().isEmpty());
	}

	// 7: a delayed XP_CHANGE for the OLD (abandoned) session, arriving
	// after a switch, must not cause the NEW current session's own live
	// display to double-count or otherwise disturb it.
	@Test
	public void delayedXpChangeAfterSwitch_doesNotDisturbTheNewSessionsLiveDisplay()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Zulrah", 5).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.recordLiveXpDelta("RANGED", 100L);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0.plusSeconds(10), "Vorkath", 3).withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusSeconds(10));
		coordinator.recordLiveXpDelta("MAGIC", 60L);

		CurrentSessionSnapshot beforeDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(11));
		assertEquals(60L, beforeDelayed.getXpEntries().get(0).getXpGained());

		// A stray, very-delayed XP_CHANGE for the OLD Zulrah fight lands
		// now, well after the switch to Vorkath. Its windowStart (T0) is
		// when SkillsCollector actually opened this XP-collection window
		// for the Zulrah fight -- well before Vorkath's own startedAt
		// (T0+10) -- which is exactly the timing information production
		// code (SessionEventMapper, fed by EventPayloads.XpChange's own
		// windowStart) will now actually supply. This is what the new
		// ownership guard in ActivitySignalClassifier.classifyXpChange()
		// keys off of to correctly ignore this stale, misattributed event.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(40), "RANGED", 100, T0).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(40));

		CurrentSessionSnapshot afterDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(41));
		// The current (Vorkath) session's own live Magic XP must be
		// completely unaffected by the old session's own delayed flush.
		assertEquals(1, afterDelayed.getXpEntries().size());
		assertEquals("MAGIC", afterDelayed.getXpEntries().get(0).getSkill());
		assertEquals(60L, afterDelayed.getXpEntries().get(0).getXpGained());
	}

	// 9: an account switch resets the live layer -- no fake live XP
	// carries over into a freshly-loaded account.
	@Test
	public void accountSwitch_resetsLiveXp_noFakeLiveXpCarriesOver()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Zulrah", 5).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.recordLiveXpDelta("RANGED", 100L);
		assertEquals(100L, CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(1))
			.getXpEntries().get(0).getXpGained());

		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST_B);
		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Vorkath", 1).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);

		CurrentSessionSnapshot freshAccount = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(1));
		assertTrue("a freshly-loaded account must never inherit another account's live-pending XP",
			freshAccount.getXpEntries().isEmpty());
	}

	// 10: XP/hr uses the immediate (durable + live) total -- see
	// CurrentSessionSnapshotTest.xpPerHour_reflectsTheImmediateLiveTotal_notJustDurable()
	// for the focused, lower-level proof (this full-pipeline file
	// intentionally does not re-derive an hour of real accumulated
	// active duration through raw game-tick pulses, which would risk
	// crossing SessionLifecycleEngine's own SUSPEND_TIMEOUT and testing
	// the wrong thing).

	// Delayed durable-XP
	// session-ownership fix. A delayed XP_CHANGE whose own Slayer
	// task's session has already been left behind by a genuine
	// SLAYER_TASK_PROGRESS-driven task switch (the Pyrefiends ->
	// Banshees real-world scenario from the bug report: finish
	// Pyrefiends, accept/start a new Banshees task, kill zero
	// Banshees, THEN the old Pyrefiend fight's own delayed XP_CHANGE
	// finally arrives) must never be credited to the new Banshees
	// session -- neither its durable aggregates nor its own live
	// display, which must remain exactly what recordLiveXpDelta()
	// established for Banshees alone.
	@Test
	public void delayedXpAfterSlayerTaskSwitch_doesNotContaminateTheNewTasksSession()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);

		// Establish a SLAYER/Pyrefiends session (same-tick combat XP +
		// SLAYER_TASK_PROGRESS resolves directly to SLAYER, exactly like
		// SessionRuntimeCoordinatorTest.slayerProgressAndCombatXpSameTick_resolvesDirectlyToSlayer()).
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0, "STRENGTH", 50L).withGameTick(1L));
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(T0, "Pyrefiends", "Catacombs of Kourend", 50).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		String pyrefiendsSessionId = coordinator.testCurrentSession().getSessionId();
		assertEquals(ActivityType.SLAYER, coordinator.testCurrentSession().getActivityIdentity().getActivityType());

		// A genuinely different task name is direct, SPECIFIC evidence
		// that immediately switches to a brand-new SLAYER/Banshees
		// session -- see classifySlayerTaskProgress()'s own javadoc.
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(T0.plusSeconds(10), "Banshees", "Slayer Tower", 1).withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusSeconds(10));
		String bansheesSessionId = coordinator.testCurrentSession().getSessionId();
		assertFalse("this must be a genuinely different session for this test to be meaningful",
			pyrefiendsSessionId.equals(bansheesSessionId));
		assertEquals(ActivityType.SLAYER, coordinator.testCurrentSession().getActivityIdentity().getActivityType());

		// Zero Banshees killed yet -- only its own live XP (Hitpoints
		// from some other incidental source) has been recorded so far.
		coordinator.recordLiveXpDelta("HITPOINTS", 20L);
		CurrentSessionSnapshot beforeDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(11));
		assertEquals(1, beforeDelayed.getXpEntries().size());
		assertEquals("HITPOINTS", beforeDelayed.getXpEntries().get(0).getSkill());
		assertEquals(20L, beforeDelayed.getXpEntries().get(0).getXpGained());

		// The completed Pyrefiend fight's own delayed XP_CHANGE finally
		// arrives, well after the switch to Banshees. Its windowStart
		// (T0) is when that XP was actually earned -- during the
		// Pyrefiends fight, before Banshees's own startedAt (T0+10).
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(40), "STRENGTH", 50, T0).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(40));

		// Banshees's own durable aggregates must never have gained this
		// stale Strength XP.
		assertTrue("the new Slayer task's session must never absorb the old task's own delayed XP",
			coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().isEmpty());

		// Banshees's own live display must remain exactly as it was --
		// only its own Hitpoints gain, never the old Pyrefiends fight's
		// Strength.
		CurrentSessionSnapshot afterDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(41));
		assertEquals(1, afterDelayed.getXpEntries().size());
		assertEquals("HITPOINTS", afterDelayed.getXpEntries().get(0).getSkill());
		assertEquals(20L, afterDelayed.getXpEntries().get(0).getXpGained());
	}

	// Now that SessionEventMapper always
	// threads a real windowStart through for every ordinary XP_CHANGE
	// (previously discarded; see SessionSignal's own xpWindowStart
	// javadoc), a normal, GENUINELY same-session XP_CHANGE -- one whose
	// windowStart falls AFTER (not before) the current session's own
	// startedAt -- must still reconcile exactly as before: the new
	// ownership guard in ActivitySignalClassifier.classifyXpChange() must
	// never suppress legitimate, in-session XP just because it now
	// happens to carry a non-null windowStart.
	// XP_CHANGE window/session-boundary
	// split fix. The general case the guard above was too coarse for:
	// an XP_CHANGE window that SPANS the switch (opens under Zulrah,
	// closes/flushes after Vorkath is already current) must credit
	// EXACTLY the portion earned after the switch to Vorkath -- never
	// the pre-switch portion, never a proportional guess -- and that
	// credit must reconcile Vorkath's own live-pending RANGED exactly
	// once (never causing it to later disappear or double). Also proves
	// a SUBSEQUANT, wholly-normal (non-spanning) flush for the same
	// skill still reconciles correctly afterward.
	@Test
	public void spanningXpChangeWindow_creditsOnlyThePostSwitchPortion_andReconcilesLiveXpExactlyOnce()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Zulrah", 5).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		// RANGED was already at 1000 XP during the Zulrah fight -- this
		// is exactly the absolute value SessionRuntimeCoordinator will
		// snapshot as Vorkath's own "XP at session start" baseline the
		// moment the switch below happens.
		coordinator.noteAbsoluteXp("RANGED", 1000L);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0.plusSeconds(10), "Vorkath", 3).withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusSeconds(10));

		// +25 RANGED genuinely earned under Vorkath, via the live layer.
		coordinator.recordLiveXpDelta("RANGED", 25L);
		coordinator.noteAbsoluteXp("RANGED", 1025L);

		CurrentSessionSnapshot beforeDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(11));
		assertEquals(1, beforeDelayed.getXpEntries().size());
		assertEquals(25L, beforeDelayed.getXpEntries().get(0).getXpGained());

		// The delayed flush's own window spans the switch: it opened at
		// T0 (during Zulrah, previousXp=900 implied by delta=125) and
		// didn't close until well after Vorkath took over, ending at the
		// true current absolute value of 1025. Of that window's own
		// reported delta (125 = 1025 - 900), only 25 (1025 - the 1000
		// baseline captured at the switch) was actually earned under
		// Vorkath -- the other 100 belongs to the already-finalized
		// Zulrah session and must never reach Vorkath.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(40), "RANGED", 125, T0, 1025L).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(40));

		assertEquals("only the exact post-switch portion may ever reach Vorkath's own durable aggregates",
			Long.valueOf(25L), coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().get("RANGED"));

		CurrentSessionSnapshot afterDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(41));
		assertEquals(1, afterDelayed.getXpEntries().size());
		assertEquals("the durable credit must reconcile the live-pending amount exactly once, never leaving it to double and never disappearing",
			25L, afterDelayed.getXpEntries().get(0).getXpGained());

		// A SUBSEQUENT, wholly-normal (non-spanning -- windowStart is
		// now after Vorkath's own startedAt) flush for more RANGED XP
		// earned entirely within Vorkath must still reconcile exactly
		// once, completely unaffected by the earlier spanning-window fix.
		coordinator.recordLiveXpDelta("RANGED", 10L);
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(70), "RANGED", 10, T0.plusSeconds(41), 1035L).withGameTick(4L));
		coordinator.testProcessTick(5L, T0.plusSeconds(70));

		assertEquals(Long.valueOf(35L), coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().get("RANGED"));
		CurrentSessionSnapshot afterSecondFlush = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(71));
		assertEquals(35L, afterSecondFlush.getXpEntries().get(0).getXpGained());
	}

	// Case A (wholly stale), proven this
	// time WITH an exact baseline present (not merely the "no baseline
	// available" fallback) -- the entire window's XP was earned at or
	// before the switch (newXp == the switch's own baseline), so the
	// post-switch portion is exactly zero and nothing may be credited to
	// Vorkath.
	@Test
	public void spanningXpChangeWindow_whollyStaleEvenWithExactBaseline_creditsNothingToTheNewSession()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0, "Zulrah", 5).withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.noteAbsoluteXp("RANGED", 1000L);

		coordinator.testEnqueueSignal(SessionSignal.bossKill(T0.plusSeconds(10), "Vorkath", 3).withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusSeconds(10));

		// No RANGED gain at all under Vorkath -- the delayed window's own
		// newXp (1000) exactly equals the baseline captured at the
		// switch, so the post-switch portion is zero.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(40), "RANGED", 100, T0, 1000L).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(40));

		assertTrue("a wholly-stale spanning window must credit nothing to the new session, even with an exact baseline",
			coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().isEmpty());
		CurrentSessionSnapshot afterDelayed = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(41));
		assertTrue(afterDelayed.getXpEntries().isEmpty());
	}

	@Test
	public void sameSessionXpChange_withPopulatedWindowStart_stillReconcilesNormally()
	{
		coordinator.ensureAccountLoaded(ACCOUNT_LIVE_XP_TEST);
		coordinator.testEnqueueSignal(SessionSignal.npcInteractionTarget(T0, 601, "Goat").withGameTick(1L));
		coordinator.testProcessTick(2L, T0);
		coordinator.testEnqueueSignal(SessionSignal.rawCombatXpObserved(T0.plusMillis(600), "Strength").withGameTick(2L));
		coordinator.testProcessTick(3L, T0.plusMillis(600));

		coordinator.recordLiveXpDelta("STRENGTH", 40L);
		CurrentSessionSnapshot beforeFlush = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(2));
		assertEquals(40L, beforeFlush.getXpEntries().get(0).getXpGained());

		// The same +40 arrives via the real, durable XP_CHANGE path, this
		// time WITH a windowStart -- one that (correctly, for a
		// genuinely same-session gain) falls after this session's own
		// startedAt (T0), so the new ownership guard must not fire.
		coordinator.testEnqueueSignal(SessionSignal.xpChange(T0.plusSeconds(30), "STRENGTH", 40, T0.plusSeconds(1)).withGameTick(3L));
		coordinator.testProcessTick(4L, T0.plusSeconds(30));

		assertEquals(Long.valueOf(40L), coordinator.testCurrentSession().getAggregates().getXpGainedBySkill().get("STRENGTH"));

		CurrentSessionSnapshot afterFlush = CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), T0.plusSeconds(31));
		assertEquals("a genuinely same-session windowStart must never trigger the new ownership guard",
			40L, afterFlush.getXpEntries().get(0).getXpGained());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

/**
 * Integrity audit (live XP): a durable window removes only what it carried.
 * It is resolved one tick after it closes, by which time the next tick's
 * StatChanged gains are already pending -- those must stay visible.
 */
public class LiveXpReconcileTest
{
	@Test
	public void reconcileRemovesOnlyTheAppliedWindow_keepingGainsAfterIt()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("s", "ATTACK", 100); // inside the closed window
		tracker.recordDelta("s", "ATTACK", 7);   // next tick, before the window resolves
		tracker.reconcile("s", "ATTACK", 100L);
		assertEquals("display = durable 100 + pending 7, never a dip", 7L, tracker.getPending("s", "ATTACK"));
	}

	@Test
	public void reconcileNeverGoesNegative_andNullClearsAll()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("s", "ATTACK", 40); // live tracking began mid-window
		tracker.reconcile("s", "ATTACK", 100L);
		assertEquals(0L, tracker.getPending("s", "ATTACK"));
		tracker.recordDelta("s", "STRENGTH", 25);
		tracker.reconcile("s", "STRENGTH", null);
		assertEquals(0L, tracker.getPending("s", "STRENGTH"));
	}

	@Test
	public void otherSkillsAndOtherSessions_untouched()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("s", "ATTACK", 10);
		tracker.recordDelta("s", "HITPOINTS", 4);
		tracker.reconcile("s", "ATTACK", 10L);
		tracker.reconcile("other", "HITPOINTS", 4L);
		assertEquals(4L, tracker.getPending("s", "HITPOINTS"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Direct, isolated coverage of {@link LiveXpTracker}'s own
 * ownership/reconciliation contract -- independent of
 * SessionRuntimeCoordinator/SkillsCollector's own wiring (covered
 * separately by SessionRuntimeCoordinatorTest/GenericNpcCombatRecognitionTest-
 * style full-pipeline tests and SkillsCollectorTest's pure
 * evaluateLiveXpDelta() tests).
 */
public class LiveXpTrackerTest
{
	// 1: a recorded delta is immediately visible via getPending()/getPendingForSession().
	@Test
	public void recordDelta_isImmediatelyVisible()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		assertEquals(40L, tracker.getPending("session-1", "Strength"));
		assertEquals(Long.valueOf(40L), tracker.getPendingForSession("session-1").get("Strength"));
	}

	// 2: multiple deltas for the same (session, skill) accumulate.
	@Test
	public void recordDelta_accumulatesAcrossMultipleCalls()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Strength", 15L);
		assertEquals(55L, tracker.getPending("session-1", "Strength"));
	}

	// delta <= 0 is always ignored -- never fabricates positive live XP.
	@Test
	public void recordDelta_ignoresZeroOrNegativeDeltas()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 0L);
		tracker.recordDelta("session-1", "Strength", -5L);
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
	}

	// null sessionId/skill is always ignored -- no honest owner to attach to.
	@Test
	public void recordDelta_ignoresNullSessionOrSkill()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta(null, "Strength", 40L);
		tracker.recordDelta("session-1", null, 40L);
		assertTrue(tracker.getPendingForSession("session-1").isEmpty());
	}

	// 6: a session switch (a delta for a DIFFERENT sessionId) discards
	// every previously-tracked amount -- the old session's pending XP
	// must never leak into the new one's display.
	@Test
	public void recordDelta_sessionSwitch_discardsThePreviousOwnersPendingXp()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("woodcutting-session", "Woodcutting", 100L);
		assertEquals(100L, tracker.getPending("woodcutting-session", "Woodcutting"));

		tracker.recordDelta("combat-session", "Strength", 10L);

		assertEquals(0L, tracker.getPending("woodcutting-session", "Woodcutting"));
		assertTrue(tracker.getPendingForSession("woodcutting-session").isEmpty());
		assertEquals(10L, tracker.getPending("combat-session", "Strength"));
	}

	// 3: reconcile() (a real XP_CHANGE flush landing) resets the live
	// pending amount for that (session, skill) to zero -- this is what
	// guarantees the exact-once display total (canonical + live never
	// double-counts once XP_CHANGE catches up).
	@Test
	public void reconcile_resetsPendingForThatSkillToZero()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.reconcile("session-1", "Strength");
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
	}

	// reconcile() only clears the skill it names -- an unrelated skill's
	// own pending amount is untouched.
	@Test
	public void reconcile_onlyClearsTheNamedSkill()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Attack", 25L);
		tracker.reconcile("session-1", "Strength");
		assertEquals(0L, tracker.getPending("session-1", "Strength"));
		assertEquals(25L, tracker.getPending("session-1", "Attack"));
	}

	// 7: reconcile() for a sessionId that is NOT the current owner is a
	// no-op -- a delayed XP_CHANGE for an abandoned/finalized session
	// arriving after a real switch must never disturb the NEW current
	// owner's own live view.
	@Test
	public void reconcile_forAnAbandonedSessionAfterASwitch_isANoOp()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("woodcutting-session", "Woodcutting", 100L);
		tracker.recordDelta("combat-session", "Strength", 10L);

		// Delayed XP_CHANGE for the OLD (abandoned) session finally lands.
		tracker.reconcile("woodcutting-session", "Woodcutting");

		// The new current owner's own live pending XP is completely unaffected.
		assertEquals(10L, tracker.getPending("combat-session", "Strength"));
	}

	// getPending()/getPendingForSession() for a sessionId that has never
	// been recorded against (or is not the current owner) return 0/empty.
	@Test
	public void getPending_forUnknownOrStaleSession_returnsZeroOrEmpty()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);

		assertEquals(0L, tracker.getPending("session-2", "Strength"));
		assertTrue(tracker.getPendingForSession("session-2").isEmpty());
		assertEquals(0L, tracker.getPending(null, "Strength"));
	}

	// getPendingForSession() returns a defensive copy -- mutating it
	// never affects the tracker's own internal state.
	@Test
	public void getPendingForSession_returnsADefensiveCopy()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);

		java.util.Map<String, Long> copy = tracker.getPendingForSession("session-1");
		try
		{
			copy.put("Strength", 999L);
		}
		catch (UnsupportedOperationException expected)
		{
			// Also acceptable -- an unmodifiable view throwing on mutation.
		}

		assertEquals(40L, tracker.getPending("session-1", "Strength"));
	}

	// 9: reset() (account switch) clears every tracked owner/amount --
	// no fake live XP survives into the new account.
	@Test
	public void reset_clearsOwnerAndAllPendingAmounts()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.reset();

		assertEquals(0L, tracker.getPending("session-1", "Strength"));
		assertTrue(tracker.getPendingForSession("session-1").isEmpty());

		// A fresh account's own session can now become the owner cleanly.
		tracker.recordDelta("session-1", "Strength", 5L);
		assertEquals(5L, tracker.getPending("session-1", "Strength"));
	}

	// An ordinary suspend/resume (the SAME sessionId recorded again
	// later) is NOT treated as a switch -- pending XP survives across it.
	@Test
	public void recordDelta_sameSessionIdAgainLater_isNotTreatedAsASwitch()
	{
		LiveXpTracker tracker = new LiveXpTracker();
		tracker.recordDelta("session-1", "Strength", 40L);
		tracker.recordDelta("session-1", "Strength", 5L);
		assertEquals(45L, tracker.getPending("session-1", "Strength"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.model.StorageState;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Covers the
 * target-time (startedAt - 30s) redesign of resolveStarting(). Pure,
 * RuneLite/Client-independent coverage of LoadoutResolver's
 * PRE_START / FALLBACK_AT_OR_AFTER_START / UNAVAILABLE resolution
 * ladder, against a real (in-memory)
 * LoadoutArchive. Plain JUnit, no Mockito.
 */
public class LoadoutResolverTest
{
	private static final Instant STARTED_AT = Instant.parse("2026-01-01T10:00:00Z");

	private static List<StorageState.StorageItem> oneItem(int itemId)
	{
		return Collections.singletonList(new StorageState.StorageItem(0, itemId, "item-" + itemId, 1, null));
	}

	// --- null-safety (backward-compat constructor path) ---

	@Test
	public void nullArchive_resolveStarting_alwaysUnavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(null);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
		assertTrue(result.getInventory().isEmpty());
	}

	@Test
	public void nullArchive_resolveEnding_alwaysUnavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(null);

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
	}

	@Test
	public void nullReferenceInstant_alwaysUnavailable_evenWithRealArchive()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(30), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		assertEquals(LoadoutProvenance.UNAVAILABLE, resolver.resolveStarting(null).getProvenance());
		assertEquals(LoadoutProvenance.UNAVAILABLE, resolver.resolveEnding(null).getProvenance());
	}

	// --- resolveStarting: PRE_START ---

	@Test
	public void resolveStarting_observationExactlyAtTarget_producesPreStart()
	{
		// target = STARTED_AT - 30s (LoadoutResolver.STARTING_LOADOUT_TARGET_OFFSET).
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(30), oneItem(995), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(995, result.getInventory().get(0).getItemId());
		assertEquals(STARTED_AT.minusSeconds(30).toString(), result.getCapturedAt());
	}

	@Test
	public void resolveStarting_prefersLatestStateAtOrBeforeTarget_notAnEarlierOne()
	{
		// Both observations are at-or-before target (STARTED_AT - 30s):
		// the resolver must pick the LATER of the two (closest to
		// target), not the earliest.
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(120), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.minusSeconds(45), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(2, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_targetAnchoredNotStartedAtAnchored_observationAfterTargetButBeforeStartIsIgnoredForPreStart()
	{
		// A state change between target (STARTED_AT - 30s) and
		// startedAt itself must NOT be treated as the pre-target state
		// -- resolution is anchored to target, not startedAt. The
		// correct PRE_START pick is the state actually in effect AT
		// target (item 1, recorded at -60s), even though item 2 (at
		// -10s, after target but before startedAt) is "more recent."
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(60), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.minusSeconds(10), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals("the state in effect AT the -30s target (item 1), not a later in-session change (item 2)",
			1, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_stateHistory_oldButStillCurrentObservationCountsAsStartingLoadout()
	{
		// Worked example from spec section 3: gear equipped at T-2min,
		// nothing changes afterward, session begins at T (target =
		// T-30s). The T-2min observation is still the state in effect
		// at T-30s and must be used -- loadout snapshots are treated as
		// state history, not point samples; no observation needs to
		// land exactly on the target instant.
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minus(java.time.Duration.ofMinutes(2)), oneItem(1337), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
		assertEquals(1337, result.getInventory().get(0).getItemId());
		assertEquals(STARTED_AT.minus(java.time.Duration.ofMinutes(2)).toString(), result.getCapturedAt());
	}

	@Test
	public void resolveStarting_preStartObservationOutsideLookback_fallsBackInstead()
	{
		// Well outside PRE_START_LOOKBACK of target (STARTED_AT - 30s).
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minus(LoadoutResolver.PRE_START_LOOKBACK).minusSeconds(60), oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.plusSeconds(5), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals("a state older than the lookback window (relative to target) must not be trusted as PRE_START",
			LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals(2, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveStarting_observationExactlyAtLookbackBoundaryFromTarget_stillCountsAsPreStart()
	{
		// Boundary is relative to target (STARTED_AT - 30s), not
		// startedAt itself: this observation sits exactly
		// PRE_START_LOOKBACK before the TARGET instant.
		LoadoutArchive archive = new LoadoutArchive();
		Instant target = STARTED_AT.minusSeconds(30);
		archive.record(target.minus(LoadoutResolver.PRE_START_LOOKBACK), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.PRE_START, result.getProvenance());
	}

	// --- resolveStarting: FALLBACK_AT_OR_AFTER_START ---

	@Test
	public void resolveStarting_noPreStartObservationAtAll_fallsBackToEarliestAtOrAfter()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT, oneItem(1), Collections.emptyList());
		archive.record(STARTED_AT.plusSeconds(30), oneItem(2), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals("must pick the EARLIEST at-or-after observation, not a later one",
			1, result.getInventory().get(0).getItemId());
	}

	// --- resolveStarting: UNAVAILABLE ---

	@Test
	public void resolveStarting_emptyArchive_unavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(new LoadoutArchive());

		LoadoutSnapshot result = resolver.resolveStarting(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
		assertNull(result.getCapturedAt());
		assertTrue(result.getInventory().isEmpty());
		assertTrue(result.getEquipment().isEmpty());
	}

	// --- resolveEnding ---

	@Test
	public void resolveEnding_observationAtOrBeforeReference_used()
	{
		LoadoutArchive archive = new LoadoutArchive();
		Instant finalizedAt = STARTED_AT.plusSeconds(600);
		archive.record(finalizedAt.minusSeconds(20), oneItem(4151), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveEnding(finalizedAt);

		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
		assertEquals(4151, result.getInventory().get(0).getItemId());
	}

	@Test
	public void resolveEnding_noObservationAtAll_unavailable()
	{
		LoadoutResolver resolver = new LoadoutResolver(new LoadoutArchive());

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals(LoadoutProvenance.UNAVAILABLE, result.getProvenance());
	}

	@Test
	public void resolveEnding_neverProducesPreStart()
	{
		LoadoutArchive archive = new LoadoutArchive();
		archive.record(STARTED_AT.minusSeconds(10), oneItem(1), Collections.emptyList());
		LoadoutResolver resolver = new LoadoutResolver(archive);

		LoadoutSnapshot result = resolver.resolveEnding(STARTED_AT);

		assertEquals("ending-loadout resolution must never claim PRE_START -- see LoadoutProvenance's own javadoc",
			LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, result.getProvenance());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.osrstelemetry.plugin.model.StorageState;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * Pure,
 * RuneLite/Swing/Client-independent coverage of LoadoutSnapshot's
 * data-shape guarantees: defensive copying, unmodifiability, the
 * unavailable() factory, and the fixed inventory slot count. Plain
 * JUnit, no Mockito, matching this project's established test style
 * (see LootTrackerIndexTest).
 */
public class LoadoutSnapshotTest
{
	private static StorageState.StorageItem item(int slot, int itemId, String name, int quantity)
	{
		return new StorageState.StorageItem(slot, itemId, name, quantity, null);
	}

	private static StorageState.StorageItem emptySlot(int slot)
	{
		return new StorageState.StorageItem(slot, -1, null, 0, null);
	}

	private static List<StorageState.StorageItem> twentyEightEmptySlots()
	{
		List<StorageState.StorageItem> slots = new ArrayList<>(LoadoutSnapshot.INVENTORY_SIZE);
		for (int i = 0; i < LoadoutSnapshot.INVENTORY_SIZE; i++)
		{
			slots.add(emptySlot(i));
		}
		return slots;
	}

	@Test
	public void inventorySize_isTwentyEight()
	{
		assertEquals(28, LoadoutSnapshot.INVENTORY_SIZE);
	}

	@Test
	public void constructor_defensivelyCopiesInputLists_laterMutationOfSourceNotReflected()
	{
		List<StorageState.StorageItem> inventory = new ArrayList<>(twentyEightEmptySlots());
		List<StorageState.StorageItem> equipment = new ArrayList<>(Collections.singletonList(item(3, 1127, "Rune platebody", 1)));

		LoadoutSnapshot snapshot = new LoadoutSnapshot(inventory, equipment, "2026-01-01T10:00:00Z", LoadoutProvenance.PRE_START);

		// Mutate the caller's own lists after construction.
		inventory.clear();
		equipment.add(item(4, 1, "extra", 1));

		assertEquals("snapshot must be unaffected by later mutation of the source inventory list",
			28, snapshot.getInventory().size());
		assertEquals("snapshot must be unaffected by later mutation of the source equipment list",
			1, snapshot.getEquipment().size());
	}

	@Test
	public void getters_returnUnmodifiableLists()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot(
			twentyEightEmptySlots(), Collections.emptyList(), "2026-01-01T10:00:00Z", LoadoutProvenance.PRE_START);

		try
		{
			snapshot.getInventory().add(item(0, 1, "x", 1));
			fail("inventory list returned by getInventory() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}

		try
		{
			snapshot.getEquipment().add(item(0, 1, "x", 1));
			fail("equipment list returned by getEquipment() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// expected
		}
	}

	@Test
	public void unavailable_hasEmptyListsNeverNull_nullCapturedAt_unavailableProvenance()
	{
		LoadoutSnapshot snapshot = LoadoutSnapshot.unavailable();

		assertTrue(snapshot.getInventory().isEmpty());
		assertTrue(snapshot.getEquipment().isEmpty());
		assertNull(snapshot.getCapturedAt());
		assertEquals(LoadoutProvenance.UNAVAILABLE, snapshot.getProvenance());
	}

	@Test
	public void preservesSlotIndexAndEmptySlotConvention_itemIdNegativeOne()
	{
		List<StorageState.StorageItem> equipment = Arrays.asList(
			item(0, 1163, "Bronze full helm", 1),
			emptySlot(1),
			emptySlot(2)
		);

		LoadoutSnapshot snapshot = new LoadoutSnapshot(twentyEightEmptySlots(), equipment, "2026-01-01T10:00:00Z", LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);

		assertEquals(3, snapshot.getEquipment().size());
		assertEquals(-1, snapshot.getEquipment().get(1).getItemId());
		assertEquals(1163, snapshot.getEquipment().get(0).getItemId());
		assertEquals(0, snapshot.getEquipment().get(0).getSlot());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.loottracker.LootTrackerCoordinator;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * The runtime side of event-driven UI refresh: the session runtime and the
 * Loot Tracker announce exactly the changes a player can see -- promptly,
 * from the thread that made them -- and never depend on anyone listening.
 */
public class PresentationInvalidationTest
{
	private static final long ACCOUNT = 700_900_960L;
	private static final Gson GSON = new Gson();
	private static final String TUROTH = "Turoth";
	private static final String TUROTH_LOC = "Fremennik Slayer Dungeon";
	private static final int COINS = 995;

	private Path testRoot;
	private LocalStateStore store;
	private EventLedger ledger;
	private SessionRuntimeCoordinator session;
	private LootTrackerCoordinator lootTracker;
	private final AtomicInteger sessionChanges = new AtomicInteger();
	private final AtomicInteger lootChanges = new AtomicInteger();
	private long tick;
	private Instant base;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("presentation-invalidation-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(GSON);
		store.start();
		ledger = new EventLedger(GSON);
		ledger.start();
		session = new SessionRuntimeCoordinator(store);
		installClientThreadClient(session);
		session.ensureAccountLoaded(ACCOUNT);
		lootTracker = new LootTrackerCoordinator(GSON);
		lootTracker.start();
		lootTracker.ensureAccountLoaded(ACCOUNT);
		lootTracker.shutdown();
		lootTracker.start();
		ledger.addListener(session);
		ledger.addListener(lootTracker);
		session.setCurrentSessionListener(sessionChanges::incrementAndGet);
		lootTracker.setChangeListener(lootChanges::incrementAndGet);
		tick = 1L;
		base = Instant.now().minusSeconds(60);
	}

	@After
	public void tearDown() throws Exception
	{
		ledger.shutdown();
		lootTracker.shutdown();
		store.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void installClientThreadClient(SessionRuntimeCoordinator target) throws Exception
	{
		net.runelite.api.Client client = (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "isClientThread":
						return true;
					case "getTickCount":
						return (int) tick;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					default:
						Class<?> rt = method.getReturnType();
						if (rt == boolean.class)
						{
							return false;
						}
						if (rt.isPrimitive() && rt != void.class)
						{
							return rt == long.class ? (Object) 0L : (Object) 0;
						}
						return null;
				}
			});
		java.lang.reflect.Field f = SessionRuntimeCoordinator.class.getDeclaredField("client");
		f.setAccessible(true);
		f.set(target, client);
	}

	private void enqueue(SessionSignal signal)
	{
		session.testEnqueueSignal(signal.withGameTick(tick));
	}

	private void closeTick()
	{
		session.testProcessTick(++tick, Instant.now());
	}

	private void appendLoot(String source, Integer sourceId, long coins)
	{
		assertTrue(ledger.appendAndWait(ACCOUNT, EventType.SERVER_NPC_LOOT, new EventPayloads.ServerNpcLoot(source, sourceId,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(COINS, "Coins", (int) coins))), 2000));
	}

	private void startTurothTask()
	{
		enqueue(SessionSignal.slayerTaskProgress(base, TUROTH, TUROTH_LOC, 1, 163));
		closeTick();
	}

	private long pending(String skill)
	{
		Long v = session.getCurrentSessionSnapshot().getLivePendingXpBySkill().get(skill);
		return v == null ? 0L : v;
	}

	// ------------------------------------------------------------------ XP

	@Test
	public void rawXpWithNoSession_neverFabricatesOwnership_norNotifies()
	{
		session.recordLiveXpDelta("WOODCUTTING", 25);
		assertEquals(0, sessionChanges.get());
		assertTrue(!session.getCurrentSessionSnapshot().isPresent());
	}

	@Test
	public void firstLegitimateSession_notifiesOnceEstablished()
	{
		enqueue(SessionSignal.xpChange(base, "WOODCUTTING", 25, base.minusSeconds(30)));
		assertEquals("queued, not yet visible", 0, sessionChanges.get());
		closeTick();
		assertEquals(1, sessionChanges.get());
		assertNotNull(session.testCurrentSession());
	}

	@Test
	public void rawXp_notifiesImmediately_pendingVisibleBeforeDurable_andReconcilesWithoutDoubleCounting()
	{
		enqueue(SessionSignal.xpChange(base, "WOODCUTTING", 25, base.minusSeconds(30)));
		closeTick();
		sessionChanges.set(0);

		session.recordLiveXpDelta("WOODCUTTING", 40);
		assertEquals("no timer, no durable flush needed", 1, sessionChanges.get());
		assertEquals(40L, pending("WOODCUTTING"));
		assertEquals(Long.valueOf(25), session.getCurrentSessionSnapshot().getXpGainedBySkill().get("WOODCUTTING"));

		// Same tick, several skills (e.g. combat): each still appears.
		session.recordLiveXpDelta("FLETCHING", 5);
		session.recordLiveXpDelta("WOODCUTTING", 10);
		assertEquals(50L, pending("WOODCUTTING"));
		assertEquals(5L, pending("FLETCHING"));

		// Durable XP_CHANGE for the same 50 XP: pending reconciled, never doubled.
		Instant later = base.plusSeconds(30);
		enqueue(SessionSignal.xpChange(later, "WOODCUTTING", 50, base.plusSeconds(1)));
		closeTick();
		assertEquals(0L, pending("WOODCUTTING"));
		assertEquals(Long.valueOf(75), session.getCurrentSessionSnapshot().getXpGainedBySkill().get("WOODCUTTING"));
	}

	// ------------------------------------------------------------------ loot / rewards

	@Test
	public void acceptedNpcLoot_dirtiesBothSurfaces_rejectedOffTaskLoot_onlyTheLootTracker()
	{
		startTurothTask();
		sessionChanges.set(0);
		lootChanges.set(0);

		appendLoot(TUROTH, 426, 10);
		assertEquals("Loot Tracker applied it live", 1, lootChanges.get());
		closeTick();
		assertEquals("accepted into the session", 1, sessionChanges.get());

		appendLoot("Undead chicken", 2993, 7);
		closeTick();
		assertEquals("rejected off-task loot changes nothing visible in Current Session", 1, sessionChanges.get());
		assertEquals("the same canonical loot is still a Loot Tracker change", 2, lootChanges.get());
	}

	@Test
	public void unchangedTicks_andIgnoredSignals_neverNotify()
	{
		startTurothTask();
		sessionChanges.set(0);
		for (int i = 0; i < 5; i++)
		{
			enqueue(SessionSignal.npcInteractionTarget(Instant.now(), 426, TUROTH));
			closeTick();
			closeTick();
		}
		assertEquals(0, sessionChanges.get());
	}

	@Test
	public void structuredReward_dirtiesSessionAndLootTracker()
	{
		enqueue(SessionSignal.structuredActivityLocation(base, "barrows", 14231));
		closeTick();
		enqueue(SessionSignal.xpChange(base.plusSeconds(1), "RANGED", 40, base));
		closeTick();
		sessionChanges.set(0);
		lootChanges.set(0);
		assertTrue(ledger.appendAndWait(ACCOUNT, EventType.STRUCTURED_REWARD, new EventPayloads.StructuredReward("barrows", "barrows", "Barrows",
			Collections.singletonList(new EventPayloads.StructuredRewardItem(COINS, "Coins", 500))), 2000));
		assertEquals(1, lootChanges.get());
		closeTick();
		assertEquals(1, sessionChanges.get());
		assertNotNull(lootTracker.getIndex().snapshotSource(LootTrackerIndex.structuredSourceKey("barrows")));
	}

	@Test
	public void duplicateOrUnknownLoot_doesNotDirtyTheLootTracker()
	{
		lootTracker.onEvent(ACCOUNT, EventType.SERVER_NPC_LOOT, new EventPayloads.ServerNpcLoot("Goblin", 3029,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(COINS, "Coins", 1))), Instant.now(), "same-id");
		lootTracker.onEvent(ACCOUNT, EventType.SERVER_NPC_LOOT, new EventPayloads.ServerNpcLoot("Goblin", 3029,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(COINS, "Coins", 1))), Instant.now(), "same-id");
		lootTracker.onEvent(ACCOUNT, EventType.STRUCTURED_REWARD, new EventPayloads.StructuredReward(null, null, "Brimstone Chest",
			Collections.singletonList(new EventPayloads.StructuredRewardItem(COINS, "Coins", 1))), Instant.now(), "other-id");
		assertEquals(1, lootChanges.get());
	}

	// ------------------------------------------------------------------ Slayer / completions / bosses / state

	@Test
	public void slayerProgress_assignment_completionMetric_bossCount_andStateChanges_allNotify()
	{
		startTurothTask();
		assertEquals("new Slayer session", 1, sessionChanges.get());

		enqueue(SessionSignal.slayerTaskProgress(base.plusSeconds(10), TUROTH, TUROTH_LOC, 1, 162));
		closeTick();
		assertEquals("task remaining", 2, sessionChanges.get());

		enqueue(SessionSignal.slayerTaskAssigned(base.plusSeconds(20), "Kalphites", "Kalphite Lair", 40));
		closeTick();
		assertTrue("new assignment", sessionChanges.get() >= 3);

		int beforeBoss = sessionChanges.get();
		enqueue(SessionSignal.bossKill(base.plusSeconds(30), "Zulrah", 101));
		closeTick();
		assertEquals("boss session / count", beforeBoss + 1, sessionChanges.get());
		enqueue(SessionSignal.bossKill(base.plusSeconds(90), "Zulrah", 102));
		closeTick();
		assertEquals("boss count increment", beforeBoss + 2, sessionChanges.get());

		// ACTIVE -> SUSPENDED by timeout, with no event at all.
		int beforeSuspend = sessionChanges.get();
		session.testProcessTick(++tick, base.plusSeconds(90).plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(5));
		assertEquals(SessionState.SUSPENDED, session.testCurrentSession().getState());
		assertEquals(beforeSuspend + 1, sessionChanges.get());
	}

	@Test
	public void structuredCompletion_notifies()
	{
		enqueue(SessionSignal.structuredActivityLocation(base, "guardians_of_the_rift", 14484));
		closeTick();
		enqueue(SessionSignal.xpChange(base.plusSeconds(1), "RUNECRAFT", 40, base));
		closeTick();
		int before = sessionChanges.get();
		enqueue(SessionSignal.structuredActivityCompletion(base.plusSeconds(2), "guardians_of_the_rift", 55));
		closeTick();
		assertEquals(before + 1, sessionChanges.get());
		assertEquals(1, session.testCurrentSession().getAggregates().getActivityCompletions().getSessionCompletions());
	}

	@Test
	public void accountSwitch_notifies()
	{
		startTurothTask();
		int before = sessionChanges.get();
		session.ensureAccountLoaded(ACCOUNT + 1);
		assertEquals(before + 1, sessionChanges.get());
		assertNull(session.testCurrentSession());
	}

	// ------------------------------------------------------------------ UI independence

	@Test
	public void aThrowingListener_neverBreaksRuntimeProcessing()
	{
		session.setCurrentSessionListener(() ->
		{
			throw new IllegalStateException("UI is gone");
		});
		lootTracker.setChangeListener(() ->
		{
			throw new IllegalStateException("UI is gone");
		});
		startTurothTask();
		appendLoot(TUROTH, 426, 10);
		closeTick();
		session.recordLiveXpDelta("SLAYER", 20);
		assertEquals(10L, session.testCurrentSession().getAggregates().getLootDrops().get(0).getItems().get(0).getQuantity());
		assertEquals(1, lootTracker.getIndex().snapshotSources().size());
	}

	@Test
	public void noListenerAtAll_telemetryIdentical()
	{
		session.setCurrentSessionListener(null);
		lootTracker.setChangeListener(null);
		startTurothTask();
		appendLoot(TUROTH, 426, 10);
		closeTick();
		assertEquals(TUROTH, session.testCurrentSession().getAggregates().getLootDrops().get(0).getSourceName());
		assertEquals(1, lootTracker.getIndex().snapshotSources().size());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project. Josh's own
 * `.\gradlew.bat clean test` run is what actually executes these.
 *
 * Slayer task-unit/physical-kill semantics regression coverage (see
 * SessionAggregates#getSlayerProgressDelta()'s own javadoc and
 * MetricUpdate#slayerProgress()'s own javadoc): every
 * MetricUpdate.slayerProgress() call carries ONE event's own
 * taskUnitsConsumed — the observed decrease in the assignment's
 * authoritative remaining-count value — which is a TASK-UNIT delta,
 * never a physical NPC-kill count, and must be SUMMED, never
 * overwritten, into SessionAggregates.slayerProgressDelta. Directly
 * against the real, pure, production SessionAggregateUpdater.apply() —
 * no mocking.
 */
public class SessionAggregateUpdaterTest
{
	@Test
	public void slayerProgress_singleEventOfTwoUnits_accumulatesExactlyTwoTaskUnits()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));

		assertEquals("taskUnitsConsumed=2 for one event (e.g. an expeditious-bracelet-style proc on a "
			+ "single physical kill) must accumulate to exactly 2 task units, never 1",
			Integer.valueOf(2), aggregates.getSlayerProgressDelta());
		assertEquals("the honestly-named accessor must return the same value as the raw getter",
			Integer.valueOf(2), aggregates.getSlayerTaskUnitsConsumed());
	}

	@Test
	public void slayerProgress_multipleEvents_sumsTaskUnitsAcrossTheWholeSession()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(1, 39));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 37));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(0, 37));

		// 1 + 2 + 0 = 3 task units total. The zero-unit event (e.g. a
		// bracelet-of-slaughter-style save, a physical kill that
		// consumed no task unit at all) contributes nothing -- it must
		// never subtract from, or reset, the running total.
		assertEquals(Integer.valueOf(3), aggregates.getSlayerProgressDelta());
	}

	@Test
	public void slayerProgress_currentRemainingIsOverwrittenNeverSummed_independentOfTaskUnitTotal()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));
		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(1, 37));

		assertEquals("slayerProgressDelta accumulates (2 + 1 = 3 task units)",
			Integer.valueOf(3), aggregates.getSlayerProgressDelta());
		assertEquals("latestSlayerCurrentRemaining is the LATEST authoritative absolute value only, "
			+ "never summed/accumulated -- the authoritative task-remaining figure this project must "
			+ "keep exactly as-is",
			Integer.valueOf(37), aggregates.getLatestSlayerCurrentRemaining());
	}

	@Test
	public void slayerProgress_neverPopulatesReliableCount_taskUnitsAreNotAPhysicalKillSignal()
	{
		SessionAggregates aggregates = new SessionAggregates();

		SessionAggregateUpdater.apply(aggregates, MetricUpdate.slayerProgress(2, 38));

		assertNull("Slayer task-unit progress must never populate reliableCount -- that field is "
			+ "reserved for a genuinely authoritative physical-kill/completion signal (e.g. BOSS_KILL), "
			+ "and this pathway must never manufacture one from task units",
			aggregates.getReliableCount());
	}
}

