		assertNull(engine.getInterruptedCandidate());
	}

	// Owner evidence returning before the third confirmation abandons the
	// challenger and preserves the same sessionId.
	@Test
	public void downrankingCombatChallenge_ownerEvidenceReturnsBeforeThirdConfirmation_abandonsChallengerPreservesSessionId()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		String nechryaelId = engine.onQualifyingActivity(NECHRYAEL, T0).getCurrent().getSessionId();
		ActivityIdentity deathSpawn = ActivitySignalClassifier.genericNpcCombatIdentity("Death Spawn");

		// Two Death Spawn observations -- arms, then repeats, but never
		// reaches the 3-confirmation requirement.
		engine.onQualifyingActivity(deathSpawn, T0.plusSeconds(2),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		engine.onQualifyingActivity(deathSpawn, T0.plusSeconds(4),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);

		// Nechryael's own evidence returns (e.g. another
		// SLAYER_TASK_PROGRESS tick) before a third Death Spawn
		// observation ever arrives.
		LifecycleResult reinforced = engine.onQualifyingActivity(NECHRYAEL, T0.plusSeconds(6));
		assertNull("owner evidence returning must abandon the pending challenger, not finalize anything",
			reinforced.getFinalized());
		assertEquals(NECHRYAEL, reinforced.getCurrent().getActivityIdentity());
		assertEquals(nechryaelId, reinforced.getCurrent().getSessionId());

		// The abandonment must be genuine, not merely delayed: a further
		// Death Spawn observation right after reinforcement is only the
		// candidate's first observation since the reset, so it alone
		// must not confirm either.
		LifecycleResult notYetConfirmed = engine.onQualifyingActivity(deathSpawn, T0.plusSeconds(8),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		assertNull("reinforcement must genuinely reset the downranking challenger's progress -- this is "
			+ "only its first observation since Nechryael's own evidence returned",
			notYetConfirmed.getFinalized());
		assertEquals(NECHRYAEL, notYetConfirmed.getCurrent().getActivityIdentity());
		assertEquals(nechryaelId, notYetConfirmed.getCurrent().getSessionId());
	}

	// Same-rank COMBAT-vs-COMBAT is explicitly NOT a downranking
	// challenge -- an established generic COMBAT session gets no extra
	// inertia against another generic COMBAT candidate, exactly as before
	// this fix (the separately-tuned generic-NPC-recognition system is
	// left completely untouched).
	@Test
	public void sameRankCombatVsCombatChallenge_unaffectedByDownrankTreatment_confirmsAtFlatFloor()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		ActivityIdentity cow = ActivitySignalClassifier.genericNpcCombatIdentity("Cow");
		ActivityIdentity goat = ActivitySignalClassifier.genericNpcCombatIdentity("Goat");
		String cowSessionId = engine.onQualifyingActivity(cow, T0).getCurrent().getSessionId();

		engine.onQualifyingActivity(goat, T0.plusSeconds(2),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		Instant confirmAt = T0.plusSeconds(4);
		LifecycleResult confirmed = engine.onQualifyingActivity(goat, confirmAt,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): PARKED, not
		// finalized, at confirmation.
		assertNull("a same-rank generic-combat challenger must still confirm (park) at the flat floor "
			+ "(2), unaffected by the downranking-challenge decay treatment -- it is never NPC-specific, "
			+ "only rank-based, and COMBAT-vs-COMBAT is same-rank", confirmed.getFinalized());
		assertEquals(cowSessionId, engine.getInterruptedCandidate().getSessionId());
		assertEquals(goat, confirmed.getCurrent().getActivityIdentity());

		LifecycleResult expiry = engine.advanceTime(confirmAt.plus(SessionLifecycleEngine.INTERRUPTED_RESUME_WINDOW).plusSeconds(1));
		assertEquals(SessionState.FINALIZED, expiry.getAdditionalFinalized().getState());
		assertEquals(cowSessionId, expiry.getAdditionalFinalized().getSessionId());
	}

	// isDownrankingCombatChallenge() scope: candidateType == COMBAT AND
	// establishedType in {SLAYER, BOSSING} -- exactly, nothing broader.
	@Test
	public void isDownrankingCombatChallenge_scopedToGenericCombatCandidateAgainstSlayerOrBossing() throws Exception
	{
		Method method = SessionLifecycleEngine.class.getDeclaredMethod(
			"isDownrankingCombatChallenge", ActivityType.class, ActivityType.class);
		method.setAccessible(true);

		assertTrue((Boolean) method.invoke(null, ActivityType.SLAYER, ActivityType.COMBAT));
		assertTrue((Boolean) method.invoke(null, ActivityType.BOSSING, ActivityType.COMBAT));
		assertFalse("same-rank COMBAT vs. COMBAT is not a downranking challenge",
			(Boolean) method.invoke(null, ActivityType.COMBAT, ActivityType.COMBAT));
		assertFalse("a SLAYER candidate is never a downranking challenge, even against BOSSING",
			(Boolean) method.invoke(null, ActivityType.BOSSING, ActivityType.SLAYER));
		assertFalse("a BOSSING candidate is never a downranking challenge, even against SLAYER",
			(Boolean) method.invoke(null, ActivityType.SLAYER, ActivityType.BOSSING));
	}

	// Required regression: "suspended session requires materially less
	// challenger evidence than active session." The exact same
	// weak-evidence challenger pattern (two coherent observations, close
	// together, immediately after the established session's own last
	// reinforcement) confirms against a SUSPENDED session but NOT against
	// a freshly-reinforced ACTIVE one -- SUSPENDED's fixed requirement (2)
	// is strictly less than ACTIVE's peak requirement (3), proving
	// SUSPENDED's ownership is materially weaker by construction, not by
	// coincidence of timing.
	@Test
	public void suspendedSession_requiresMateriallyLessChallengerEvidenceThanActiveSession()
	{
		// SUSPENDED: two close-together coherent observations confirm.
		SessionLifecycleEngine suspendedEngine = new SessionLifecycleEngine();
		suspendedEngine.onQualifyingActivity(ZULRAH, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		suspendedEngine.advanceTime(suspendedAt);
		suspendedEngine.onQualifyingActivity(CRAFTING, suspendedAt.plusSeconds(10),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		LifecycleResult suspendedResult = suspendedEngine.onQualifyingActivity(CRAFTING, suspendedAt.plusSeconds(20),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		assertEquals("SUSPENDED confirms with exactly two close-together coherent observations",
			SessionState.FINALIZED, suspendedResult.getFinalized().getState());

		// ACTIVE, freshly reinforced at its own equivalent T0: the SAME
		// two close-together observations must NOT yet confirm.
		SessionLifecycleEngine activeEngine = new SessionLifecycleEngine();
		activeEngine.onQualifyingActivity(ZULRAH, T0);
		activeEngine.onQualifyingActivity(CRAFTING, T0.plusSeconds(10),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		LifecycleResult activeResult = activeEngine.onQualifyingActivity(CRAFTING, T0.plusSeconds(20),
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);
		assertNull("the SAME two close-together observations must NOT confirm against a freshly-reinforced "
			+ "ACTIVE session -- ACTIVE requires strictly MORE challenger evidence than SUSPENDED",
			activeResult.getFinalized());
		assertEquals(SessionState.ACTIVE, activeResult.getCurrent().getState());
		assertEquals(ZULRAH, activeResult.getCurrent().getActivityIdentity());
	}

	// Case B: the established session's OWN identity returns before
	// confirmation -- the pending ACTIVE candidate is abandoned, its
	// buffered metric committed once as a contextual metric on the
	// still-current (never disturbed) session.
	@Test
	public void weakEvidenceWhileActive_originalIdentityReturnsFirst_candidateAbandonedContextually()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);

		Instant weakAt = T0.plusSeconds(34);
		engine.onQualifyingActivity(AGILITY, weakAt, Arrays.asList(MetricUpdate.xp("agility", 6)),
			EvidenceStrength.ORDINARY);

		Instant realReturnAt = weakAt.plusSeconds(10);
		LifecycleResult afterReturn = engine.onQualifyingActivity(GARGOYLES, realReturnAt);

		assertNull("returning to the established session's own identity must never finalize it",
			afterReturn.getFinalized());
		assertEquals(SessionState.ACTIVE, afterReturn.getCurrent().getState());
		assertEquals(GARGOYLES, afterReturn.getCurrent().getActivityIdentity());
		assertEquals("the abandoned Agility candidate's buffered metric must be committed once, "
			+ "contextually, to the still-current Gargoyles session",
			afterReturn.getCurrent(), afterReturn.getContextualMetricsTarget());
		assertEquals(1, afterReturn.getContextualMetrics().size());
		apply(afterReturn.getCurrent(), afterReturn.getContextualMetrics());
		assertEquals(6L, totalXp(afterReturn.getCurrent(), "agility"));
	}

	// Case D (forward-looking design property -- not yet exercised by any
	// real production signal, since no current classifier branch tags a
	// SKILLING identity SPECIFIC/AUTHORITATIVE): AUTHORITATIVE/SPECIFIC
	// evidence must always switch/refine immediately, never gated by the
	// weak-evidence candidate mechanism, regardless of ACTIVE/SUSPENDED or
	// candidate identity type. Exercises the engine's own strength-gated
	// predicate directly (via the 4-arg overload) to prove the gate keys
	// off EvidenceStrength -- not merely off ActivityType -- so a future
	// generic-NPC-recognition pass can supply SPECIFIC/AUTHORITATIVE
	// evidence for a non-combat-branch identity without any redesign here.
	@Test
	public void authoritativeOrSpecificEvidenceWhileActive_switchesImmediately_neverGatedRegardlessOfIdentityType()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		String originalId = engine.onQualifyingActivity(GARGOYLES, T0).getCurrent().getSessionId();

		Instant observedAt = T0.plusSeconds(34);
		LifecycleResult result = engine.onQualifyingActivity(AGILITY, observedAt,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.SPECIFIC);

		// INTERRUPTED-ACTIVITY RESUME (A -> brief B -> A): "never gated
		// behind confirmation" still holds -- SPECIFIC evidence still
		// switches at this single observation, with no confirmation
		// delay -- it is now PARKED rather than immediately finalized,
		// exactly like every other genuine real switch.
		assertNull("SPECIFIC evidence must never be gated behind confirmation, even against an ACTIVE "
			+ "combat-branch session and even for a non-combat-branch candidate identity",
			result.getFinalized());
		assertEquals(originalId, engine.getInterruptedCandidate().getSessionId());
		assertEquals(AGILITY, result.getCurrent().getActivityIdentity());
		assertEquals("no confirmation delay -- the switch happens at this single observation's own "
			+ "timestamp", observedAt, engine.getInterruptedCandidateInterruptedAt());

		LifecycleResult expiry = engine.advanceTime(observedAt.plus(SessionLifecycleEngine.INTERRUPTED_RESUME_WINDOW).plusSeconds(1));
		assertEquals(SessionState.FINALIZED, expiry.getAdditionalFinalized().getState());
		assertEquals(originalId, expiry.getAdditionalFinalized().getSessionId());
		assertEquals(observedAt.toString(), expiry.getAdditionalFinalized().getFinalizedAt());
	}

	// A pending ACTIVE candidate that never gets its confirming second
	// observation before the established session's own suspend threshold
	// is reached must not leak silently -- it is abandoned here too,
	// committed once as contextual metrics to the now-SUSPENDED session
	// it genuinely occurred during.
	@Test
	public void activeCandidate_abandonedWhenSuspendThresholdReachedBeforeConfirmation()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);

		Instant weakAt = T0.plusSeconds(34);
		engine.onQualifyingActivity(AGILITY, weakAt, Arrays.asList(MetricUpdate.xp("agility", 6)),
			EvidenceStrength.ORDINARY);

		// A LATER event, past the suspend threshold measured from the
		// established session's own lastActiveAt (T0) -- never confirming
		// the pending Agility candidate. This new MINING evidence is
		// itself weak against the now-SUSPENDED Gargoyles session, so it
		// only arms a FRESH SUSPENDED-branch candidate of its own.
		Instant pastThreshold = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(5);
		LifecycleResult result = engine.onQualifyingActivity(MINING, pastThreshold,
			Collections.<MetricUpdate>emptyList(), EvidenceStrength.ORDINARY);

		assertNull(result.getFinalized());
		assertEquals(SessionState.SUSPENDED, result.getCurrent().getState());
		assertEquals(GARGOYLES, result.getCurrent().getActivityIdentity());

		assertEquals("the abandoned ACTIVE Agility candidate's buffered metric must be committed once, "
			+ "contextually, to the now-SUSPENDED Gargoyles session -- never lost",
			result.getCurrent(), result.getContextualMetricsTarget());
		assertEquals(1, result.getContextualMetrics().size());
		apply(result.getCurrent(), result.getContextualMetrics());
		assertEquals(6L, totalXp(result.getCurrent(), "agility"));
	}

	// Case E (SUSPENDED unchanged): the legacy 3-arg overload -- used by
	// every pre-existing test/caller above with no strength to supply --
	// must still default to ORDINARY, so the SUSPENDED branch's own gate
	// (exercised extensively above) continues to fire exactly as it
	// did before, and the SAME default now also extends the
	// gate to ACTIVE: a legacy 3-arg call with
	// weak, non-combat-branch evidence against an ACTIVE combat-branch
	// session must be gated, not switch immediately.
	@Test
	public void legacyThreeArgOverload_defaultsToOrdinaryStrength_gatesWeakEvidenceWhileActive()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		String originalId = engine.onQualifyingActivity(GARGOYLES, T0).getCurrent().getSessionId();

		LifecycleResult result = engine.onQualifyingActivity(AGILITY, T0.plusSeconds(34),
			Collections.<MetricUpdate>emptyList());

		assertNull("the legacy 3-arg overload must default to ORDINARY, so a single incidental "
			+ "observation is gated exactly like a real ORDINARY-tagged signal would be",
			result.getFinalized());
		assertEquals(SessionState.ACTIVE, result.getCurrent().getState());
		assertEquals(GARGOYLES, result.getCurrent().getActivityIdentity());
		assertEquals(originalId, result.getCurrent().getSessionId());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Proves
 * schema backward-compatibility ("extend finalized-session schema
 * conservatively/backward-compatibly") end to end:
 *   1. an OLD sessions/{id}.json (no
 *      startingLoadout/endingLoadout field at all) still deserializes
 *      cleanly, with every pre-existing field intact and both loadout
 *      fields simply null -- never a parse failure, never a
 *      fabricated/default loadout;
 *   2. a NEW session with a real starting+ending loadout attached
 *      round-trips losslessly, both via plain Gson and via the real
 *      SessionPersistence.persistFinalized()/loadFinalized() path
 *      against the real LocalStateStore/TelemetryPaths (matching
 *      SessionPersistenceTest's own established real-file, no-Client,
 *      two-account style);
 *   3. loadFinalized() fails open (returns null, never throws) on a
 *      malformed/partial file, the same contract loadCurrent() already
 *      has, applied to the one new read method here.
 *
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project (see SessionPersistenceTest).
 */
public class SessionLoadoutBackwardCompatibilityTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_444L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("session-loadout-compat-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	// --- 1: old-shape file (no loadout fields at all) ---

	/**
	 * Hand-authored, exactly matching the old field set --
	 * deliberately does NOT include startingLoadout/endingLoadout, the
	 * two fields added here. This is what every
	 * sessions/{id}.json written by the plugin previously
	 * actually looks like on disk today.
	 */
	private static final String OLD_SHAPE_FINALIZED_JSON = "{"
		+ "\"sessionId\":\"old-session-1\","
		+ "\"activityIdentity\":{\"activityType\":\"SLAYER\",\"activityKey\":\"gargoyles:catacombs\",\"displayName\":\"Gargoyles\"},"
		+ "\"state\":\"FINALIZED\","
		+ "\"startedAt\":\"2026-01-01T10:00:00Z\","
		+ "\"lastActiveAt\":\"2026-01-01T10:09:00Z\","
		+ "\"finalizedAt\":\"2026-01-01T10:39:00Z\","
		+ "\"accumulatedActiveDurationMillis\":540000,"
		+ "\"aggregates\":{\"xpGainedBySkill\":{\"SLAYER\":812},\"lootDrops\":[],\"slayerProgressDelta\":6}"
		+ "}";

	@Test
	public void oldShapeJson_deserializesCleanly_loadoutFieldsNullEverythingElseIntact()
	{
		Session reloaded = GSON.fromJson(OLD_SHAPE_FINALIZED_JSON, Session.class);

		assertNotNull(reloaded);
		assertEquals("old-session-1", reloaded.getSessionId());
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertEquals(GARGOYLES, reloaded.getActivityIdentity());
		assertEquals("2026-01-01T10:00:00Z", reloaded.getStartedAt());
		assertEquals("2026-01-01T10:39:00Z", reloaded.getFinalizedAt());
		assertEquals(540000L, reloaded.getAccumulatedActiveDurationMillis());
		assertEquals(Long.valueOf(812L), reloaded.getAggregates().getXpGainedBySkill().get("SLAYER"));
		assertEquals(Integer.valueOf(6), reloaded.getAggregates().getSlayerProgressDelta());

		assertNull("an old session file has no starting loadout -- must deserialize as null, never a fabricated/default snapshot",
			reloaded.getStartingLoadout());
		assertNull("an old session file has no ending loadout -- must deserialize as null, never a fabricated/default snapshot",
			reloaded.getEndingLoadout());
	}

	@Test
	public void oldShapeFile_onRealDisk_loadsThroughSessionPersistence() throws Exception
	{
		File sessionFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "old-session-1"));
		Files.write(sessionFile.toPath(), OLD_SHAPE_FINALIZED_JSON.getBytes(StandardCharsets.UTF_8));

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, "old-session-1");

		assertNotNull("a real pre-Checkpoint-1 file on disk must still load through the new loadFinalized() method", reloaded);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertNull(reloaded.getStartingLoadout());
		assertNull(reloaded.getEndingLoadout());
	}

	// --- 2: new session with a real loadout round-trips losslessly ---

	private static List<StorageState.StorageItem> sampleInventory()
	{
		List<StorageState.StorageItem> items = new ArrayList<>(LoadoutSnapshot.INVENTORY_SIZE);
		items.add(new StorageState.StorageItem(0, 995, "Coins", 12_345, null));
		items.add(new StorageState.StorageItem(1, 1359, "Swordfish", 5, null));
		for (int slot = 2; slot < LoadoutSnapshot.INVENTORY_SIZE; slot++)
		{
			items.add(new StorageState.StorageItem(slot, -1, null, 0, null));
		}
		return items;
	}

	private static List<StorageState.StorageItem> sampleEquipment()
	{
		return Arrays.asList(
			new StorageState.StorageItem(0, 1163, "Bronze full helm", 1, "HEAD"),
			new StorageState.StorageItem(3, -1, null, 0, "WEAPON"),
			new StorageState.StorageItem(4, 1129, "Bronze platebody", 1, "BODY")
		);
	}

	private Session buildFinalizedSessionWithLoadout()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		LoadoutSnapshot starting = new LoadoutSnapshot(
			sampleInventory(), sampleEquipment(), T0.minusSeconds(30).toString(), LoadoutProvenance.PRE_START);
		LoadoutSnapshot ending = new LoadoutSnapshot(
			sampleInventory(), sampleEquipment(), expiry.plusSeconds(5).toString(), LoadoutProvenance.FALLBACK_AT_OR_AFTER_START);

		finalized.setStartingLoadout(starting);
		finalized.setEndingLoadout(ending);
		return finalized;
	}

	@Test
	public void newSessionWithLoadout_plainGsonRoundTrip_preservesEverything()
	{
		Session original = buildFinalizedSessionWithLoadout();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertNotNull(roundTripped.getStartingLoadout());
		assertNotNull(roundTripped.getEndingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, roundTripped.getStartingLoadout().getProvenance());
		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, roundTripped.getEndingLoadout().getProvenance());
		assertEquals(28, roundTripped.getStartingLoadout().getInventory().size());
		assertEquals(995, roundTripped.getStartingLoadout().getInventory().get(0).getItemId());
		assertEquals(-1, roundTripped.getStartingLoadout().getInventory().get(2).getItemId());
		assertEquals(3, roundTripped.getStartingLoadout().getEquipment().size());
		assertEquals("HEAD", roundTripped.getStartingLoadout().getEquipment().get(0).getEquipmentSlot());
	}

	@Test
	public void newSessionWithLoadout_realPersistFinalizedThenLoadFinalized_preservesLoadout() throws Exception
	{
		Session original = buildFinalizedSessionWithLoadout();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, original, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, original.getSessionId());

		assertNotNull(reloaded);
		assertEquals(original.getSessionId(), reloaded.getSessionId());
		assertNotNull("starting loadout must survive a real write-then-read cycle", reloaded.getStartingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, reloaded.getStartingLoadout().getProvenance());
		assertEquals(28, reloaded.getStartingLoadout().getInventory().size());
		assertEquals(1359, reloaded.getStartingLoadout().getInventory().get(1).getItemId());
		assertNotNull("ending loadout must survive a real write-then-read cycle", reloaded.getEndingLoadout());
		assertEquals(LoadoutProvenance.FALLBACK_AT_OR_AFTER_START, reloaded.getEndingLoadout().getProvenance());
	}

	@Test
	public void sessionWithUnavailableLoadout_roundTripsAsExplicitUnavailable_neverNullAfterBeingSet()
	{
		Session original = buildFinalizedSessionWithLoadout();
		original.setEndingLoadout(LoadoutSnapshot.unavailable());

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertNotNull("an explicitly-set unavailable() loadout is a real value, not the same as an old file's null",
			roundTripped.getEndingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, roundTripped.getEndingLoadout().getProvenance());
		assertTrue(roundTripped.getEndingLoadout().getInventory().isEmpty());
		assertTrue(roundTripped.getEndingLoadout().getEquipment().isEmpty());
	}

	// --- 3: loadFinalized() fails open on a malformed/partial file ---

	@Test
	public void loadFinalized_malformedFile_returnsNullRatherThanThrowing() throws Exception
	{
		File sessionFile = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, "corrupt-session"));
		Files.write(sessionFile.toPath(), "{ this is not valid json".getBytes(StandardCharsets.UTF_8));

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, "corrupt-session");

		assertNull("a malformed session file must fail open (null), never throw and never crash a caller iterating many sessions",
			reloaded);
	}

	@Test
	public void loadFinalized_missingFile_returnsNull()
	{
		assertNull(persistence.loadFinalized(TEST_ACCOUNT_HASH, "does-not-exist"));
	}

	@Test
	public void differentAccounts_neverSeeEachOthersLoadoutData() throws Exception
	{
		long otherAccountHash = 888_777_555L;
		deleteAccountDir(otherAccountHash);
		try
		{
			Session original = buildFinalizedSessionWithLoadout();
			persistence.persistFinalized(TEST_ACCOUNT_HASH, original, null);
			awaitAsyncChain();

			Session crossAccountRead = persistence.loadFinalized(otherAccountHash, original.getSessionId());
			assertNull("a finalized session (and its loadout) must never be visible under a different account's hash",
				crossAccountRead);
		}
		finally
		{
			deleteAccountDir(otherAccountHash);
		}
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.collectors.LoadoutArchive;
import com.osrstelemetry.plugin.model.StorageState;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Collections;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * End-to-
 * end coverage of the REAL production wiring path -- the two-arg
 * SessionPersistence(store, loadoutArchive) constructor
 * SessionRuntimeCoordinator now uses -- as opposed to
 * LoadoutResolverTest (the resolution ladder in isolation) or
 * SessionLoadoutBackwardCompatibilityTest (an explicitly
 * pre-attached loadout with a null/no-op archive). Proves:
 *   1. a brand-new session's FIRST persistCurrent() call resolves and
 *      attaches a real starting loadout from live archive data;
 *   2. a second persistCurrent() call for the SAME session object does
 *      NOT re-resolve (identity refinement/repeated
 *      persistence must never replace an already-attached starting
 *      loadout);
 *   3. persistFinalized() resolves and attaches an ending loadout;
 *   4. an account with no archive data at all still finalizes cleanly
 *      with an explicit UNAVAILABLE loadout, never blocking
 *      persistence.
 *
 * Real LocalStateStore/TelemetryPaths, matching
 * SessionPersistenceTest/SessionLoadoutBackwardCompatibilityTest's own
 * established real-file style.
 *
 * Archive
 * observations that exercise a PRE_START starting-loadout resolution
 * are recorded far enough before T0 to land at-or-before the
 * resolver's target instant (T0 - 30s -- see
 * LoadoutResolver.STARTING_LOADOUT_TARGET_OFFSET), not merely before
 * T0 itself.
 */
public class SessionPersistenceLoadoutResolutionTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_333L;
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");
	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private LoadoutArchive archive;
	private SessionPersistence persistence;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("session-persistence-loadout-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir(TEST_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		archive = new LoadoutArchive();
		persistence = new SessionPersistence(store, archive);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	@Test
	public void firstPersistCurrent_resolvesAndAttachesRealStartingLoadout()
	{
		archive.record(T0.minusSeconds(45),
			Collections.singletonList(new StorageState.StorageItem(0, 995, "Coins", 500, null)),
			Collections.emptyList());

		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		assertNull("a freshly-created session must not already have a loadout", session.getStartingLoadout());

		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);

		assertNotNull("persistCurrent() must resolve and attach a starting loadout for a brand-new session",
			session.getStartingLoadout());
		assertEquals(LoadoutProvenance.PRE_START, session.getStartingLoadout().getProvenance());
		assertEquals(995, session.getStartingLoadout().getInventory().get(0).getItemId());
	}

	@Test
	public void secondPersistCurrent_neverReplacesAlreadyAttachedStartingLoadout()
	{
		archive.record(T0.minusSeconds(45),
			Collections.singletonList(new StorageState.StorageItem(0, 995, "Coins", 500, null)),
			Collections.emptyList());

		Session session = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);
		LoadoutSnapshot firstResolved = session.getStartingLoadout();

		// Simulate a later observation arriving (e.g. the player picked
		// something up) that must NOT retroactively become this
		// session's "starting" loadout.
		archive.record(T0.plusSeconds(5),
			Collections.singletonList(new StorageState.StorageItem(0, 1234, "Different item", 1, null)),
			Collections.emptyList());
		persistence.persistCurrent(TEST_ACCOUNT_HASH, session);

		assertEquals("a second persistCurrent() call for the same session object must not re-resolve the starting loadout",
			firstResolved, session.getStartingLoadout());
	}

	@Test
	public void persistFinalized_resolvesAndAttachesEndingLoadout() throws Exception
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		archive.record(expiry.minusSeconds(5),
			Collections.singletonList(new StorageState.StorageItem(0, 1359, "Swordfish", 3, null)),
			Collections.emptyList());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, finalized.getSessionId());
		assertNotNull(reloaded);
		assertNotNull("persistFinalized() must resolve and attach an ending loadout", reloaded.getEndingLoadout());
		assertEquals(1359, reloaded.getEndingLoadout().getInventory().get(0).getItemId());
	}

	@Test
	public void noArchiveData_finalizesCleanlyWithExplicitUnavailableLoadout_neverBlocks() throws Exception
	{
		// archive is real but has never recorded anything for this account.
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session reloaded = persistence.loadFinalized(TEST_ACCOUNT_HASH, finalized.getSessionId());
		assertNotNull("finalization must succeed even with zero archive data", reloaded);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertNotNull(reloaded.getStartingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, reloaded.getStartingLoadout().getProvenance());
		assertNotNull(reloaded.getEndingLoadout());
		assertEquals(LoadoutProvenance.UNAVAILABLE, reloaded.getEndingLoadout().getProvenance());
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — same no-JDK-in-this-cloud-sandbox caveat as
 * every other Java test file in this project.
 *
 * Covers serialization round-trips, restart/rehydration semantics,
 * finalized-record persistence and write ordering, and account
 * isolation — all against the real
 * LocalStateStore/TelemetryPaths, matching BankSnapshotBaselineTest's
 * own G-J section's established pattern (real files, no Client, two
 * distinct account hashes for isolation checks).
 */
public class SessionPersistenceTest
{
	private static final long TEST_ACCOUNT_HASH = 888_777_555L;
	private static final long OTHER_ACCOUNT_HASH = 888_777_666L;

	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static final Gson GSON = new Gson();

	private LocalStateStore store;
	private SessionPersistence persistence;

	// TEST ISOLATION: this class owns its own storage root -- never whatever
	// TelemetryPaths root another test class happened to leave behind.
	private Path testRoot;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("session-persistence-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		deleteAccountDir(TEST_ACCOUNT_HASH);
		deleteAccountDir(OTHER_ACCOUNT_HASH);
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		deleteAccountDir(TEST_ACCOUNT_HASH);
		deleteAccountDir(OTHER_ACCOUNT_HASH);
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static void deleteAccountDir(long accountHash)
	{
		deleteRecursively(TestFilepaths.file(TelemetryPaths.accountDir(accountHash)));
	}

	private static void deleteRecursively(File dir)
	{
		File[] files = dir.listFiles();
		if (files != null)
		{
			for (File f : files)
			{
				if (f.isDirectory())
				{
					deleteRecursively(f);
				}
				else
				{
					f.delete();
				}
			}
		}
	}

	// --- 21/22/23: serialization round-trips ---

	@Test
	public void serializationRoundTrip_active()
	{
		Session original = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.ACTIVE, roundTripped.getState());
		assertEquals(GARGOYLES, roundTripped.getActivityIdentity());
	}

	@Test
	public void serializationRoundTrip_suspended()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session original = engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)).getCurrent();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.SUSPENDED, roundTripped.getState());
		assertNotNull(roundTripped.getSuspendedAt());
		assertNotNull(roundTripped.getResumeWindowExpiresAt());
	}

	@Test
	public void serializationRoundTrip_finalizedRecord()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session original = engine.advanceTime(expiry).getFinalized();

		Session roundTripped = GSON.fromJson(GSON.toJson(original), Session.class);

		assertEquals(original, roundTripped);
		assertEquals(SessionState.FINALIZED, roundTripped.getState());
		assertEquals(expiry.toString(), roundTripped.getFinalizedAt());
	}

	// --- 24/25/26: restart/rehydration semantics ---

	@Test
	public void rehydrate_persistedActive_convertsConservativelyWithoutCountingOfflineTime()
	{
		Session persisted = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		long durationBeforeRehydration = persisted.getAccumulatedActiveDurationMillis();

		// RuneLite was closed for a full day; rehydration happens far later.
		Instant rehydratedAt = T0.plus(java.time.Duration.ofDays(1));
		SessionLifecycleEngine.RehydrationResult result = SessionLifecycleEngine.rehydrate(persisted, rehydratedAt);

		// The offline gap vastly exceeds the 30-minute resume window, so
		// the conservative SUSPENDED reconstruction immediately finalizes.
		assertNotNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.FINALIZED, result.getFinalizedDuringRehydration().getState());
		assertEquals("no offline time may ever be added to active duration",
			durationBeforeRehydration, result.getFinalizedDuringRehydration().getAccumulatedActiveDurationMillis());
		assertNull(result.getEngine().getCurrentSession());
	}

	@Test
	public void rehydrate_persistedSuspendedInsideWindow_remainsResumable()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		Session persisted = engine.advanceTime(suspendedAt).getCurrent();

		// Rehydrated 10 minutes into the 30-minute window.
		SessionLifecycleEngine.RehydrationResult result =
			SessionLifecycleEngine.rehydrate(persisted, suspendedAt.plus(java.time.Duration.ofMinutes(10)));

		assertNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.SUSPENDED, result.getEngine().getCurrentSession().getState());

		// And it genuinely still resumes on a matching heartbeat.
		LifecycleResult resumed = result.getEngine().onQualifyingActivity(
			GARGOYLES, suspendedAt.plus(java.time.Duration.ofMinutes(11)));
		assertEquals(SessionState.ACTIVE, resumed.getCurrent().getState());
	}

	@Test
	public void rehydrate_persistedSuspendedOutsideWindow_finalizes()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		Session persisted = engine.advanceTime(suspendedAt).getCurrent();
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);

		SessionLifecycleEngine.RehydrationResult result =
			SessionLifecycleEngine.rehydrate(persisted, expiry.plus(java.time.Duration.ofMinutes(1)));

		assertNotNull(result.getFinalizedDuringRehydration());
		assertEquals(SessionState.FINALIZED, result.getFinalizedDuringRehydration().getState());
		assertEquals("timeout-driven finalization must use the deterministic expiry, not the rehydration wall time",
			expiry.toString(), result.getFinalizedDuringRehydration().getFinalizedAt());
		assertNull(result.getEngine().getCurrentSession());
	}

	// --- 27: finalized session writes to correct sessions path ---

	/**
	 * NOTE ON WAITING FOR THE ASYNC CHAIN: persistFinalized() chains a
	 * second write() call from inside the first write's onWritten
	 * callback (see SessionPersistence javadoc), both submitted to
	 * LocalStateStore's single-thread executor. Calling shutdown()
	 * immediately after persistFinalized() returns is NOT safe here the
	 * way it is for a single, non-chained write (see
	 * LocalStateStoreTest's "no sleep — shutdown() itself waits"
	 * comment): shutdown() can flip the executor to SHUTDOWN before the
	 * first task's onWritten callback gets a chance to submit the
	 * second task, causing that nested submit() to be silently
	 * rejected. This mirrors LocalStateStore's own javadoc reasoning for
	 * why real shutdown-time chaining uses the blocking writeAndWait()
	 * instead — ordinary runtime chaining (the case here)
	 * does not go through shutdown() at all, so a short sleep here
	 * (not shutdown()) is what correctly waits for both queued tasks to
	 * finish without introducing a race the production code path never
	 * has.
	 */
	private static void awaitAsyncChain() throws InterruptedException
	{
		Thread.sleep(300);
	}

	@Test
	public void persistFinalized_writesToCorrectSessionsPath() throws Exception
	{
		Session finalized = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		finalized.setState(SessionState.FINALIZED);
		finalized.setFinalizedAt(T0.plusSeconds(10).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		File expected = TestFilepaths.file(TelemetryPaths.sessionFile(TEST_ACCOUNT_HASH, finalized.getSessionId()));
		assertTrue("finalized record must exist at sessions/{sessionId}.json", expected.exists());

		Session reloaded = store.readIfExists(TestFilepaths.fromFile(expected), Session.class);
		assertEquals(SessionState.FINALIZED, reloaded.getState());
		assertEquals(finalized.getSessionId(), reloaded.getSessionId());
	}

	@Test
	public void persistFinalized_clearsSessionStateOnlyAfterSuccess() throws Exception
	{
		Session finalized = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		finalized.setState(SessionState.FINALIZED);
		finalized.setFinalizedAt(T0.plusSeconds(10).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, finalized, null);
		awaitAsyncChain();

		Session currentAfter = store.readIfExists(
			TelemetryPaths.sessionStateFile(TEST_ACCOUNT_HASH), Session.class);
		assertNull("session_state.json must no longer represent the finalized session as current",
			currentAfter);
	}

	// --- 28: account isolation ---

	@Test
	public void accountDirectoriesRemainIsolated() throws Exception
	{
		Session accountASession = new SessionLifecycleEngine().onQualifyingActivity(GARGOYLES, T0).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, accountASession);
		store.shutdown(); // single, non-chained write — safe to drain via shutdown(), see LocalStateStoreTest's own convention

		Session loadedForOther = persistence.loadCurrent(OTHER_ACCOUNT_HASH);
		Session loadedForTest = persistence.loadCurrent(TEST_ACCOUNT_HASH);

		assertNull("account B must never see account A's current session", loadedForOther);
		assertNotNull(loadedForTest);
		assertEquals(accountASession.getSessionId(), loadedForTest.getSessionId());
		assertFalse("session directories themselves must be different paths",
			TelemetryPaths.accountDir(TEST_ACCOUNT_HASH).equals(TelemetryPaths.accountDir(OTHER_ACCOUNT_HASH)));
	}

	// --- 29: persistence failure does not silently discard the only current session copy ---

	@Test
	public void persistFinalizedFailure_doesNotClearSessionState() throws Exception
	{
		// Seed session_state.json with a known-good SUSPENDED session first,
		// as if it were the last successfully persisted current state.
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session suspended = engine.advanceTime(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)).getCurrent();
		persistence.persistCurrent(TEST_ACCOUNT_HASH, suspended);
		store.shutdown(); // single, non-chained write — safe to drain via shutdown()
		store = new LocalStateStore(GSON);
		store.start();
		persistence = new SessionPersistence(store);

		// Simulate the finalized-record write itself failing: same technique
		// LocalStateStoreTest uses for its own failure test (a parent
		// directory that cannot be created because a same-named file
		// already occupies that path).
		File accountDir = TestFilepaths.file(TelemetryPaths.accountDir(TEST_ACCOUNT_HASH));
		File sessionsDirBlocker = new File(accountDir, "sessions");
		deleteRecursively(sessionsDirBlocker);
		sessionsDirBlocker.delete();
		java.nio.file.Files.write(sessionsDirBlocker.toPath(), "not a directory".getBytes());

		Session toFinalize = suspended;
		toFinalize.setState(SessionState.FINALIZED);
		toFinalize.setFinalizedAt(T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plus(SessionLifecycleEngine.RESUME_WINDOW).toString());

		persistence.persistFinalized(TEST_ACCOUNT_HASH, toFinalize, null);
		store.shutdown();

		store = new LocalStateStore(GSON);
		store.start();
		Session stillCurrent = store.readIfExists(TelemetryPaths.sessionStateFile(TEST_ACCOUNT_HASH), Session.class);
		assertNotNull("a failed finalized-record write must never clear the only surviving copy of the session",
			stillCurrent);
		assertEquals(SessionState.SUSPENDED, stillCurrent.getState());

		sessionsDirBlocker.delete();
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * LIVE REGRESSION (post native-Slayer migration): a broader Slayer session
 * spanning several assignments reaches a Cave Kraken assignment, the player
 * walks to Kraken Cove and starts killing the Kraken boss. Observed: the
 * broader Slayer session FINALIZED into History (Cave Kraken x1 as its last
 * assignment) and a standalone "Kraken" Current Session started with its own
 * timer, XP and loot.
 *
 * Root cause: ActivitySignalClassifier.decideCombatBranch() treated
 * SLAYER -&gt; BOSSING as a real switch with no task-compatibility check.
 * Against a SUSPENDED Slayer session (idle while travelling) the engine
 * finalizes on specific different-identity evidence -- it only parks from
 * ACTIVE -- hence the History entry. Expected (product rule): when the active
 * Slayer assignment is compatible with the boss (task-family membership),
 * SLAYER owns the encounter: same session id, same elapsed time, kills / loot
 * on the Cave Kraken assignment, XP in the broader session.
 *
 * Real per-kill order: BOSS_ACTIVITY_CONTEXT (first interaction) ...
 * NPC_DEATH -&gt; SLAYER_TASK_PROGRESS -&gt; ~1.8s -&gt; BOSS_KILL -&gt; SERVER_NPC_LOOT.
 */
public class SessionRuntimeCoordinatorBossOnMatchingTaskTest extends SlayerCoordinatorTestSupport
{
	private static final String TASK = "Cave Kraken";
	private static final String LOCATION = "Kraken Cove";

	private long sessionFiles() throws Exception
	{
		Thread.sleep(250);
		Path dir = testRoot.resolve(String.valueOf(ACCOUNT)).resolve("sessions");
		if (!Files.exists(dir))
		{
			return 0;
		}
		try (Stream<Path> files = Files.list(dir))
		{
			return files.count();
		}
	}

	private static SessionSignal loot(Instant at, String source, int itemId, String item, int qty)
	{
		return SessionSignal.serverNpcLoot(at, source, Collections.singletonList(new SessionSignal.LootDrop(itemId, item, qty)));
	}

	private static SessionAggregates.SlayerAssignmentRecord currentRecord(Session s)
	{
		List<SessionAggregates.SlayerAssignmentRecord> records = s.getAggregates().getSlayerAssignments();
		return records.get(records.size() - 1);
	}

	private static long qty(SessionAggregates.SlayerAssignmentRecord r, String item)
	{
		long total = 0;
		for (SessionAggregates.LootItemAggregate i : r.getItems())
		{
			if (item.equals(i.getItemName()))
			{
				total += i.getQuantity();
			}
		}
		return total;
	}

	private static long xp(Session s, String skill)
	{
		Long v = s.getAggregates().getXpGainedBySkill().get(skill);
		return v == null ? 0L : v;
	}

	/**
	 * Broader Slayer session: Nechryael (completed), Kalphites (skipped by a
	 * direct replacement), then Cave Kraken assigned. Returns the instant the
	 * Cave Kraken assignment arrived.
	 */
	private Instant establishMultiAssignmentSessionEndingOnCaveKraken()
	{
		int remaining = 3;
		for (int i = 0; i < 3; i++)
		{
			Instant t = T0.plusSeconds(20L * i);
			remaining--;
			feed(SessionSignal.slayerTaskProgress(t, NECH, NECH_LOC, 1, remaining), t);
			feed(loot(t.plusSeconds(1), "Nechryael", 995, "Coins", 100), t.plusSeconds(1));
		}
		xp("SLAYER", 315L, T0);
		feed(SessionSignal.slayerTaskCompleted(T0.plusSeconds(70), NECH, null), T0.plusSeconds(70));

		Instant kalphAssigned = T0.plusSeconds(120);
		feed(SessionSignal.slayerTaskAssigned(kalphAssigned, KALPHITES, KALPHITE_LOC, 140), kalphAssigned);
		feed(SessionSignal.slayerTaskProgress(kalphAssigned.plusSeconds(30), KALPHITES, KALPHITE_LOC, 1, 139), kalphAssigned.plusSeconds(30));
		feed(loot(kalphAssigned.plusSeconds(31), "Kalphite Worker", 526, "Bones", 1), kalphAssigned.plusSeconds(31));

		Instant krakenAssigned = kalphAssigned.plusSeconds(90);
		feed(SessionSignal.slayerTaskAssigned(krakenAssigned, TASK, LOCATION, 100), krakenAssigned);
		Session s = current();
		assertEquals("cave kraken@kraken cove", s.getActivityIdentity().getActivityKey());
		assertEquals("setup: three assignment instances in one broader session", 3, s.getAggregates().getSlayerAssignments().size());
		return krakenAssigned;
	}

	/** One full Kraken kill in the live order; returns the instant after its loot. */
	private Instant krakenKill(Instant t, int remainingAfter, int kc)
	{
		feed(SessionSignal.npcDeath(t), t);
		feed(SessionSignal.slayerTaskProgress(t.plusMillis(1200), TASK, LOCATION, 1, remainingAfter), t.plusMillis(1200));
		feed(SessionSignal.bossKill(t.plusMillis(3000), "Kraken", kc), t.plusMillis(3000));
		feed(loot(t.plusMillis(3000), "Kraken", 3272, "Kraken tentacle", 1), t.plusMillis(3600));
		return t.plusMillis(3600);
	}

	private void assertSlayerOwnsKraken(String sessionId, String startedAt)
	{
		Session s = current();
		assertEquals("same broader Slayer session id", sessionId, s.getSessionId());
		assertEquals("same broader elapsed-time origin", startedAt, s.getStartedAt());
		assertEquals(ActivityType.SLAYER, s.getActivityIdentity().getActivityType());
		assertEquals("cave kraken@kraken cove", s.getActivityIdentity().getActivityKey());
		assertNull("nothing parked: no standalone boss session displaced Slayer", coordinator.testInterruptedCandidate());
	}

	// ---------------------------------------------------------------- live repro

	@Test
	public void liveRepro_suspendedWhileTravelling_krakenContextKillsLootXp_allStayInTheBroaderSlayerSession() throws Exception
	{
		Instant assigned = establishMultiAssignmentSessionEndingOnCaveKraken();
		Session before = current();
		String id = before.getSessionId();
		String startedAt = before.getStartedAt();
		long nechCoins = qty(before.getAggregates().getSlayerAssignments().get(0), "Coins");
		long filesBefore = sessionFiles();

		// Travel / banking: idle past the suspend threshold.
		Instant travelled = assigned.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(90);
		coordinator.testProcessTick(++tick, travelled);
		assertEquals("setup: the broader session is SUSPENDED while travelling", SessionState.SUSPENDED, current().getState());

		// First evidence at the cove: boss context from interacting with Kraken.
		feed(SessionSignal.bossActivityContext(travelled.plusSeconds(5), "Kraken"), travelled.plusSeconds(5));
		assertSlayerOwnsKraken(id, startedAt);
		assertEquals("resumed, not replaced", SessionState.ACTIVE, current().getState());

		Instant t = travelled.plusSeconds(20);
		int remaining = 100;
		for (int kill = 1; kill <= 4; kill++)
		{
			remaining--;
			t = krakenKill(t, remaining, 200 + kill);
			xp("SLAYER", 255L, t.minusSeconds(29));
			assertSlayerOwnsKraken(id, startedAt);
			t = t.plusSeconds(45);
		}

		Session s = current();
		SessionAggregates.SlayerAssignmentRecord caveKraken = currentRecord(s);
		assertEquals("cave kraken@kraken cove", caveKraken.getAssignmentKey());
		assertEquals("every Kraken kill consumed a Cave Kraken unit", Integer.valueOf(4), caveKraken.getUnitsCompleted());
		assertEquals(Integer.valueOf(96), caveKraken.getLatestRemaining());
		assertEquals("Kraken loot is owned by the Cave Kraken assignment", 4L, qty(caveKraken, "Kraken tentacle"));
		assertEquals("earlier assignments untouched", nechCoins, qty(s.getAggregates().getSlayerAssignments().get(0), "Coins"));
		assertEquals(0L, qty(s.getAggregates().getSlayerAssignments().get(1), "Kraken tentacle"));
		assertEquals("Kraken XP stays in the broader Slayer session", 315L + 4 * 255L, xp(s, "SLAYER"));
		assertEquals("Kraken XP is attributed to the Cave Kraken assignment",
			Long.valueOf(4 * 255L), caveKraken.getXpGainedBySkill().get("SLAYER"));
		assertEquals("no finalized History entry was written", filesBefore, sessionFiles());
	}

	@Test
	public void liveRepro_activeSlayerSession_krakenKills_neverParkSlayerOrStartABossSession() throws Exception
	{
		Instant assigned = establishMultiAssignmentSessionEndingOnCaveKraken();
		String id = current().getSessionId();
		String startedAt = current().getStartedAt();
		long filesBefore = sessionFiles();

		// Regular cave krakens first (session ACTIVE), then the boss.
		feed(SessionSignal.slayerTaskProgress(assigned.plusSeconds(40), TASK, LOCATION, 1, 99), assigned.plusSeconds(40));
		feed(loot(assigned.plusSeconds(41), "Cave kraken", 995, "Coins", 40), assigned.plusSeconds(41));
		assertEquals(SessionState.ACTIVE, current().getState());

		Instant t = assigned.plusSeconds(70);
		int remaining = 99;
		for (int kill = 1; kill <= 3; kill++)
		{
			remaining--;
			t = krakenKill(t, remaining, 10 + kill).plusSeconds(40);
			assertSlayerOwnsKraken(id, startedAt);
		}
		SessionAggregates.SlayerAssignmentRecord caveKraken = currentRecord(current());
		assertEquals(Integer.valueOf(4), caveKraken.getUnitsCompleted());
		assertEquals(3L, qty(caveKraken, "Kraken tentacle"));
		assertEquals(40L, qty(caveKraken, "Coins"));
		assertEquals(filesBefore, sessionFiles());
	}

	@Test
	public void sameTickProgressAndBossKill_staysSlayerOwned_bothOrders() throws Exception
	{
		Instant assigned = establishMultiAssignmentSessionEndingOnCaveKraken();
		String id = current().getSessionId();
		String startedAt = current().getStartedAt();

		Instant t1 = assigned.plusSeconds(30);
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(t1, TASK, LOCATION, 1, 99).withGameTick(tick));
		coordinator.testEnqueueSignal(SessionSignal.bossKill(t1, "Kraken", 50).withGameTick(tick));
		coordinator.testEnqueueSignal(loot(t1, "Kraken", 3272, "Kraken tentacle", 1).withGameTick(tick));
		coordinator.testProcessTick(++tick, t1);
		assertSlayerOwnsKraken(id, startedAt);

		Instant t2 = t1.plusSeconds(40);
		coordinator.testEnqueueSignal(SessionSignal.bossKill(t2, "Kraken", 51).withGameTick(tick));
		coordinator.testEnqueueSignal(SessionSignal.slayerTaskProgress(t2, TASK, LOCATION, 1, 98).withGameTick(tick));
		coordinator.testProcessTick(++tick, t2);
		assertSlayerOwnsKraken(id, startedAt);
		assertEquals(Integer.valueOf(2), currentRecord(current()).getUnitsCompleted());
		assertEquals(1L, qty(currentRecord(current()), "Kraken tentacle"));
	}

	@Test
	public void adjacentTick_bossKillBeforeItsProgress_staysSlayerOwned() throws Exception
	{
		Instant assigned = establishMultiAssignmentSessionEndingOnCaveKraken();
		String id = current().getSessionId();
		String startedAt = current().getStartedAt();
		Instant t = assigned.plusSeconds(30);
		feed(SessionSignal.bossKill(t, "Kraken", 50), t);
		assertSlayerOwnsKraken(id, startedAt);
		feed(SessionSignal.slayerTaskProgress(t.plusMillis(600), TASK, LOCATION, 1, 99), t.plusMillis(600));
		assertSlayerOwnsKraken(id, startedAt);
	}

	@Test
	public void restartWhileOnCaveKrakenTask_rehydratedSuspendedSession_krakenResumesIt() throws Exception
	{
		// Wall-clock based: rehydration judges the resume window against now.
		Instant base = Instant.now().minusSeconds(240);
		feed(SessionSignal.slayerTaskProgress(base, NECH, NECH_LOC, 1, 0), base);
		feed(SessionSignal.slayerTaskCompleted(base.plusSeconds(1), NECH, null), base.plusSeconds(1));
		feed(SessionSignal.slayerTaskAssigned(base.plusSeconds(60), TASK, LOCATION, 100), base.plusSeconds(60));
		feed(SessionSignal.slayerTaskProgress(base.plusSeconds(90), TASK, LOCATION, 1, 99), base.plusSeconds(90));
		String id = current().getSessionId();
		String startedAt = current().getStartedAt();
		coordinator.finalizeForClientShutdownBlocking();

		restartPlugin();
		Instant back = Instant.now().minusSeconds(30);
		feed(SessionSignal.bossActivityContext(back, "Kraken"), back);
		krakenKill(back.plusSeconds(5), 98, 77);
		Session s = current();
		assertEquals("re-enable / login on the task: the same broader session continues", id, s.getSessionId());
		assertEquals(startedAt, s.getStartedAt());
		assertEquals(ActivityType.SLAYER, s.getActivityIdentity().getActivityType());
		assertEquals(1L, qty(currentRecord(s), "Kraken tentacle"));
		assertEquals(2, s.getAggregates().getSlayerAssignments().size());
	}


	@Test
	public void coldStart_bossKillBeforeAnySlayerSession_ownTaskProgressRefinesTheSameSessionIntoSlayer() throws Exception
	{
		Instant t = T0;
		feed(SessionSignal.bossKill(t, "Kraken", 300), t);
		Session boss = current();
		assertEquals(ActivityType.BOSSING, boss.getActivityIdentity().getActivityType());
		feed(loot(t.plusMillis(600), "Kraken", 3272, "Kraken tentacle", 1), t.plusMillis(600));

		feed(SessionSignal.slayerTaskProgress(t.plusSeconds(2), TASK, LOCATION, 1, 50), t.plusSeconds(2));
		Session s = current();
		assertEquals("refined in place: same id", boss.getSessionId(), s.getSessionId());
		assertEquals(boss.getStartedAt(), s.getStartedAt());
		assertEquals("cave kraken@kraken cove", s.getActivityIdentity().getActivityKey());
		assertEquals("the boss loot seen before the refine seeds the assignment ledger", 1L, qty(currentRecord(s), "Kraken tentacle"));

		krakenKill(t.plusSeconds(40), 49, 301);
		assertEquals(boss.getSessionId(), current().getSessionId());
		assertEquals(2L, qty(currentRecord(current()), "Kraken tentacle"));
		assertNull(coordinator.testInterruptedCandidate());
	}

	@Test
	public void duplicateNativeRecheck_zeroUnitProgress_doesNotDisturbOwnership() throws Exception
	{
		Instant assigned = establishMultiAssignmentSessionEndingOnCaveKraken();
		String id = current().getSessionId();
		String startedAt = current().getStartedAt();
		krakenKill(assigned.plusSeconds(30), 99, 50);
		// A coalesced native recheck re-reporting the same assignment.
		feed(SessionSignal.slayerTaskAssigned(assigned.plusSeconds(40), TASK, LOCATION, 100), assigned.plusSeconds(40));
		assertSlayerOwnsKraken(id, startedAt);
		assertEquals("duplicate assignment is a no-op, not a new instance", 3, current().getAggregates().getSlayerAssignments().size());
		krakenKill(assigned.plusSeconds(80), 98, 51);
		assertSlayerOwnsKraken(id, startedAt);
	}

	@Test
	public void otherRegisteredFamilyBosses_cerberusOnHellhounds_vorkathOnBlueDragons_staySlayerOwned() throws Exception
	{
		String[][] pairs = {{"Hellhounds", "Taverley Dungeon", "Cerberus", "Hellhound"}, {"Blue dragons", "Taverley Dungeon", "Vorkath", "Blue dragon"}};
		Instant t = T0;
