package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import java.time.Instant;
import java.util.List;
import org.junit.Test;

/**
 * NATIVE SLAYER MIGRATION, initial amount: the game's own original task size
 * (SLAYER_COUNT_ORIGINAL +/- modifier) is retained on a BOOTSTRAPPED
 * assignment record as authoritative metadata (assignedInitialAmount), while
 * bootstrapped provenance and every observed-only quantity -- units, XP,
 * active duration, initialAmount -- stay exactly as before. "Originally
 * assigned 157" never means Spyglass observed the first 115 kills.
 */
public class SlayerBootstrappedNativeInitialAmountTest extends SlayerCoordinatorTestSupport
{
	private static SessionAggregates.SlayerAssignmentRecord last(Session s)
	{
		List<SessionAggregates.SlayerAssignmentRecord> l = s.getAggregates().getSlayerAssignments();
		return l.get(l.size() - 1);
	}

	private void joinKalphitesMidTask(Instant at, Integer nativeInitial)
	{
		feed(SessionSignal.slayerTaskProgress(at, KALPHITES, KALPHITE_LOC, 1, 42, nativeInitial), at);
		feed(SessionSignal.slayerTaskProgress(at.plusSeconds(30), KALPHITES, KALPHITE_LOC, 1, 41, nativeInitial), at.plusSeconds(30));
	}

	@Test
	public void bootstrappedMidTask_retainsNativeOriginal_asMetadataOnly()
	{
		joinKalphitesMidTask(T0, 157);
		SessionAggregates.SlayerAssignmentRecord r = last(current());
		assertTrue("provenance unchanged", r.isBootstrapped());
		assertEquals(Integer.valueOf(157), r.getAssignedInitialAmount());
		assertNull("observed-assignment amount stays unknown", r.getInitialAmount());
		assertNull("assignment time stays unknown", r.getAssignedAt());
		assertEquals("only observed units", Integer.valueOf(2), r.getUnitsCompleted());
		assertEquals(Integer.valueOf(2), r.observedUnitsCompleted());

		CurrentSessionSnapshot.SlayerAssignmentView v = ui(T0.plusSeconds(30)).getSlayerAssignments().get(0);
		assertTrue(v.isBootstrapped());
		assertEquals(Integer.valueOf(2), v.getUnitsCompleted());
		assertNull("the player-facing total is not invented", v.getInitialAmount());
	}

	@Test
	public void bootstrappedRecord_withAndWithoutNativeOriginal_hasIdenticalObservedMetrics() throws Exception
	{
		joinKalphitesMidTask(T0, null);
		SessionAggregates.SlayerAssignmentRecord without = last(current());
		Integer unitsWithout = without.getUnitsCompleted();
		Long startWithout = without.getActiveDurationStartMillis();
		Object xpWithout = without.getXpGainedBySkill();

		setUpCoordinator();
		joinKalphitesMidTask(T0, 157);
		SessionAggregates.SlayerAssignmentRecord with = last(current());
		assertNull(without.getAssignedInitialAmount());
		assertEquals(Integer.valueOf(157), with.getAssignedInitialAmount());
		assertEquals(unitsWithout, with.getUnitsCompleted());
		assertEquals(startWithout, with.getActiveDurationStartMillis());
		assertEquals(xpWithout, with.getXpGainedBySkill());
		assertEquals(without.getLatestRemaining(), with.getLatestRemaining());
		assertEquals(without.isBootstrapped(), with.isBootstrapped());
	}

	@Test
	public void fullyObservedAssignment_keepsItsObservedInitialAmount_noNativeMetadataNeeded()
	{
		feed(SessionSignal.slayerTaskAssigned(T0, NECH, NECH_LOC, 120), T0);
		feed(SessionSignal.slayerTaskProgress(T0.plusSeconds(60), NECH, NECH_LOC, 1, 119, 120), T0.plusSeconds(60));
		SessionAggregates.SlayerAssignmentRecord r = last(current());
		assertFalse(r.isBootstrapped());
		assertEquals(Integer.valueOf(120), r.getInitialAmount());
		assertNull(r.getAssignedInitialAmount());
	}

	@Test
	public void inconsistentNativeOriginal_smallerThanWhatSpyglassAlreadySaw_isRejected()
	{
		joinKalphitesMidTask(T0, 30); // remaining was 42 when Spyglass attached: 30 cannot be this instance
		assertNull(last(current()).getAssignedInitialAmount());
	}

	@Test
	public void nativeOriginalForADifferentTask_neverFillsThisRecord()
	{
		feed(SessionSignal.slayerTaskProgress(T0, KALPHITES, KALPHITE_LOC, 1, 42), T0);
		// A stray progress for another task key must not label this record.
		SessionSignal other = SessionSignal.slayerTaskProgress(T0.plusSeconds(5), NECH, NECH_LOC, 0, 100, 150);
		feed(other, T0.plusSeconds(5));
		for (SessionAggregates.SlayerAssignmentRecord r : current().getAggregates().getSlayerAssignments())
		{
			if (r.getAssignmentKey().equals(ActivitySignalClassifier.slayerIdentity(KALPHITES, KALPHITE_LOC).getActivityKey()))
			{
				assertNull(r.getAssignedInitialAmount());
			}
		}
	}

	@Test
	public void nativeOriginalArrivingLater_fillsOnce_neverOverwritten()
	{
		joinKalphitesMidTask(T0, null);
		assertNull(last(current()).getAssignedInitialAmount());
		feed(SessionSignal.slayerTaskProgress(T0.plusSeconds(60), KALPHITES, KALPHITE_LOC, 1, 40, 157), T0.plusSeconds(60));
		assertEquals(Integer.valueOf(157), last(current()).getAssignedInitialAmount());
		feed(SessionSignal.slayerTaskProgress(T0.plusSeconds(90), KALPHITES, KALPHITE_LOC, 1, 39, 200), T0.plusSeconds(90));
		assertEquals(Integer.valueOf(157), last(current()).getAssignedInitialAmount());
		assertEquals(Integer.valueOf(4), last(current()).getUnitsCompleted());
	}

	@Test
	public void persistsAcrossRestart_andOlderJsonLoadsWithNull() throws Exception
	{
		Instant base = Instant.now().minusSeconds(300);
		joinKalphitesMidTask(base, 157);
		String id = current().getSessionId();
		coordinator.finalizeForClientShutdownBlocking();
		restartPlugin();
		assertEquals(id, current().getSessionId());
		SessionAggregates.SlayerAssignmentRecord r = last(current());
		assertTrue(r.isBootstrapped());
		assertEquals(Integer.valueOf(157), r.getAssignedInitialAmount());

		SessionAggregates.SlayerAssignmentRecord legacy = GSON.fromJson(
			"{\"ordinal\":1,\"taskName\":\"Kalphites\",\"bootstrapped\":true,\"latestRemaining\":41,\"items\":[]}",
			SessionAggregates.SlayerAssignmentRecord.class);
		assertNull(legacy.getAssignedInitialAmount());
		assertNull(legacy.getInitialAmount());
	}

	@Test
	public void mapper_carriesProgressInitialAmountAsMetadata_zeroMeansNotYetKnown()
	{
		SessionSignal known = SessionEventMapper.map(EventType.SLAYER_TASK_PROGRESS,
			new EventPayloads.SlayerTaskProgress(KALPHITES, KALPHITE_LOC, 42, 41, -1, 1, 157, 2), T0);
		assertEquals(Integer.valueOf(157), known.getSlayerInitialAmount());
		assertEquals(Integer.valueOf(1), known.getSlayerUnitsConsumed());
		assertEquals(Integer.valueOf(41), known.getSlayerCurrentRemaining());

		SessionSignal syncing = SessionEventMapper.map(EventType.SLAYER_TASK_PROGRESS,
			new EventPayloads.SlayerTaskProgress(KALPHITES, KALPHITE_LOC, 42, 41, -1, 1, 0, 2), T0);
		assertNull(syncing.getSlayerInitialAmount());
	}
}

package com.osrstelemetry.plugin.session;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import org.junit.After;
import org.junit.Before;

/**
 * Shared fixture for the Smart Slayer coordinator tests: a real
 * SessionRuntimeCoordinator on a real LocalStateStore rooted in a fresh
 * temp directory, driven one closed game tick per {@link #feed} call.
 */
abstract class SlayerCoordinatorTestSupport
{
	protected static final long ACCOUNT = 700_900_300L;
	protected static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	protected static final Gson GSON = new Gson();
	protected static final String NECH = "Nechryael";
	protected static final String NECH_LOC = "Catacombs of Kourend";
	protected static final String KALPHITES = "Kalphites";
	protected static final String KALPHITE_LOC = "Kalphite Lair";

	protected LocalStateStore store;
	protected SessionRuntimeCoordinator coordinator;
	protected Path testRoot;
	protected long tick;

	@Before
	public void setUpCoordinator() throws Exception
	{
		testRoot = Files.createTempDirectory("smart-slayer-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
		coordinator.ensureAccountLoaded(ACCOUNT);
		tick = 1L;
	}

	@After
	public void tearDownCoordinator() throws Exception
	{
		if (store != null)
		{
			store.shutdown();
		}
		if (testRoot != null)
		{
			TestFilepaths.rooted(testRoot).deleteRecursively();
		}
	}

	/** Simulates a plugin restart on the same storage: fresh store + coordinator, same account. */
	protected void restartPlugin()
	{
		store.shutdown();
		store = new LocalStateStore(GSON);
		store.start();
		coordinator = new SessionRuntimeCoordinator(store);
		coordinator.ensureAccountLoaded(ACCOUNT);
	}

	/** One signal as its own closed game tick. */
	protected void feed(SessionSignal signal, Instant at)
	{
		coordinator.testEnqueueSignal(signal.withGameTick(tick));
		coordinator.testProcessTick(++tick, at);
	}

	/** XP window [windowStart, windowStart+30s], delivered at the window's end. */
	protected void xp(String skill, long delta, Instant windowStart)
	{
		Instant end = windowStart.plusSeconds(30);
		feed(SessionSignal.xpChange(end, skill, delta, windowStart), end);
	}

	protected Session current()
	{
		return coordinator.testCurrentSession();
	}

	protected CurrentSessionSnapshot ui(Instant now)
	{
		return CurrentSessionSnapshot.from(coordinator.getCurrentSessionSnapshot(), now);
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.history.HistoryIndex;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * SMART SLAYER -> PERSISTENCE -> HISTORY, end to end through the real
 * coordinator: a multi-task Slayer session built from real signals, left
 * idle until the engine genuinely finalizes it to disk, then loaded back
 * exactly as History loads it (SessionPersistence.loadFinalized()).
 *
 * Records, oldest first:
 *   #1 Nechryael  -- COMPLETED, loot + XP, fully observed
 *   #2 Kalphites  -- REPLACED_EARLY ("Skipped"), loot
 *   #3 Nechryael  -- same name again, REPLACED_EARLY with zero loot
 *   #4 Turoth     -- unfinished when the session finalized (no status)
 */
public class SlayerHistoryRoundTripTest extends SlayerCoordinatorTestSupport
{
	private static final String TUROTH = "Turoth";
	private static final String TUROTH_LOC = "Fremennik Slayer Dungeon";

	private static SessionSignal loot(Instant at, String source, long coins)
	{
		List<SessionSignal.LootDrop> drops = new ArrayList<>();
		drops.add(new SessionSignal.LootDrop(995, "Coins", coins));
		return SessionSignal.serverNpcLoot(at, source, drops);
	}

	/** Builds the four-assignment session from `base`; returns the instant of its last activity. */
	private Instant buildMultiTaskSession(Instant base)
	{
		feed(SessionSignal.slayerTaskAssigned(base, NECH, NECH_LOC, 2), base);
		feed(SessionSignal.slayerTaskProgress(base.plusSeconds(10), NECH, NECH_LOC, 1, 1), base.plusSeconds(10));
		feed(loot(base.plusSeconds(11), "Nechryael", 100), base.plusSeconds(11));
		xp("SLAYER", 100L, base.plusSeconds(12));
		xp("HITPOINTS", 40L, base.plusSeconds(12));
		feed(SessionSignal.slayerTaskCompleted(base.plusSeconds(60), NECH, null), base.plusSeconds(60));
		feed(loot(base.plusSeconds(61), "Nechryael", 50), base.plusSeconds(61));

		feed(SessionSignal.slayerTaskAssigned(base.plusSeconds(120), KALPHITES, KALPHITE_LOC, 143), base.plusSeconds(120));
		feed(SessionSignal.slayerTaskProgress(base.plusSeconds(150), KALPHITES, KALPHITE_LOC, 1, 142), base.plusSeconds(150));
		feed(loot(base.plusSeconds(151), "Kalphite Worker", 7), base.plusSeconds(151));

		feed(SessionSignal.slayerTaskAssigned(base.plusSeconds(200), NECH, NECH_LOC, 3), base.plusSeconds(200));
		feed(SessionSignal.slayerTaskAssigned(base.plusSeconds(210), TUROTH, TUROTH_LOC, 50), base.plusSeconds(210));
		feed(SessionSignal.slayerTaskProgress(base.plusSeconds(240), TUROTH, TUROTH_LOC, 1, 49), base.plusSeconds(240));
		feed(loot(base.plusSeconds(241), "Turoth", 10), base.plusSeconds(241));
		return base.plusSeconds(241);
	}

	/** Idles past suspend + resume window so the engine finalizes and persists it; returns the loaded file. */
	private Session finalizeAndLoad(Session live, Instant last)
	{
		coordinator.testProcessTick(++tick, last.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(1));
		coordinator.testProcessTick(++tick, last.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)
			.plus(SessionLifecycleEngine.RESUME_WINDOW).plusSeconds(5));
		assertNull("the Slayer session genuinely finalized", current());
		assertNotNull("finalizedAt stamped", live.getFinalizedAt());
		store.shutdown(); // drains the async finalized write
		store = new LocalStateStore(GSON);
		store.start();
		return new SessionPersistence(store).loadFinalized(ACCOUNT, live.getSessionId());
	}

	@Test
	public void newSchema_everyAssignmentField_survivesFinalizeAndLoad_forHistory()
	{
		Instant last = buildMultiTaskSession(T0);
		Session live = current();
		List<SessionAggregates.SlayerAssignmentRecord> liveLedger = live.getAggregates().getSlayerAssignments();
		assertEquals(4, liveLedger.size());

		Session loaded = finalizeAndLoad(live, last);
		assertNotNull("finalized file exists and loads", loaded);
		List<SessionAggregates.SlayerAssignmentRecord> ledger = loaded.getAggregates().getSlayerAssignments();

		// Deep equality (Lombok @Data): ordinal, taskName, assignmentKey, assignedAt,
		// initialAmount, latestRemaining, endedAt, bootstrapped, items, endReason,
		// completedAt, unitsCompleted, xpGainedBySkill, activeDurationStart/EndMillis.
		assertEquals("every field of every record round-trips", liveLedger, ledger);

		// ...and they are real values, not null == null.
		SessionAggregates.SlayerAssignmentRecord nech = ledger.get(0);
		assertEquals(1, nech.getOrdinal());
		assertEquals(NECH, nech.getTaskName());
		assertEquals("nechryael@catacombs of kourend", nech.getAssignmentKey());
		assertEquals(T0.toString(), nech.getAssignedAt());
		assertEquals(Integer.valueOf(2), nech.getInitialAmount());
		assertEquals(Integer.valueOf(0), nech.getLatestRemaining());
		assertFalse(nech.isBootstrapped());
		assertEquals(SlayerAssignmentEndReason.COMPLETED, nech.getEndReason());
		assertNotNull(nech.getCompletedAt());
		assertEquals(T0.plusSeconds(120).toString(), nech.getEndedAt());
		assertEquals(Integer.valueOf(2), nech.getUnitsCompleted());
		assertEquals(150L, nech.getItems().get(0).getQuantity());
		assertEquals(Long.valueOf(100L), nech.getXpGainedBySkill().get("SLAYER"));
		assertNotNull(nech.getActiveDurationStartMillis());
		assertNotNull(nech.getActiveDurationEndMillis());

		SessionAggregates.SlayerAssignmentRecord kal = ledger.get(1);
		assertEquals(SlayerAssignmentEndReason.REPLACED_EARLY, kal.getEndReason());
		assertEquals(Integer.valueOf(142), kal.getLatestRemaining());
		assertEquals(Integer.valueOf(1), kal.getUnitsCompleted());
		assertEquals(7L, kal.getItems().get(0).getQuantity());

		SessionAggregates.SlayerAssignmentRecord nech2 = ledger.get(2);
		assertEquals(NECH, nech2.getTaskName());
		assertEquals("same-name task is its own instance", 3, nech2.getOrdinal());
		assertEquals(SlayerAssignmentEndReason.REPLACED_EARLY, nech2.getEndReason());
		assertTrue("zero-loot record kept", nech2.getItems().isEmpty());

		SessionAggregates.SlayerAssignmentRecord turoth = ledger.get(3);
		assertNull("unfinished at finalize: never a guessed status", turoth.getEndReason());
		assertNull(turoth.getEndedAt());
		assertEquals(10L, turoth.getItems().get(0).getQuantity());

		// Partition invariant survives on disk.
		long sessionCoins = 0;
		for (SessionAggregates.LootDropGroup g : loaded.getAggregates().getLootDrops())
		{
			sessionCoins += g.getItems().get(0).getQuantity();
		}
		assertEquals(167L, sessionCoins);
	}

	@Test
	public void historyEntry_multiTaskTitle_isPresentationOnly_identityAndIdUnchanged()
	{
		Instant last = buildMultiTaskSession(T0);
		Session live = current();
		String id = live.getSessionId();
		Session loaded = finalizeAndLoad(live, last);

		HistoryEntry entry = HistoryEntry.from(loaded);
		assertEquals(4, entry.getSlayerAssignmentCount());
		assertEquals("Slayer Session", HistoryEntry.displayTitle(entry.getActivityIdentity(), entry.getSlayerAssignmentCount()));
		assertEquals("session ID is canonical", id, entry.getSessionId());
		assertEquals("persisted identity untouched (still the final assignment)", TUROTH, loaded.getActivityIdentity().getDisplayName());
		assertTrue("file name is the session ID", TelemetryPaths.sessionFile(ACCOUNT, id).exists());

		List<HistoryEntry> indexed = new HistoryIndex().refresh(ACCOUNT, new SessionPersistence(store), Duration.ofDays(3650), Instant.now());
		assertEquals(1, indexed.size());
		assertEquals(id, indexed.get(0).getSessionId());
		assertEquals(4, indexed.get(0).getSlayerAssignmentCount());
	}

	@Test
	public void restartMidSession_sessionStateJson_preservesEveryAssignmentField()
	{
		// Relative to now: a restore after a long gap would (correctly) finalize it instead.
		buildMultiTaskSession(Instant.now().minusSeconds(300));
		List<SessionAggregates.SlayerAssignmentRecord> before = new ArrayList<>(current().getAggregates().getSlayerAssignments());
		coordinator.finalizeForClientShutdownBlocking();
		restartPlugin();
		assertEquals("session_state.json round trip", before, current().getAggregates().getSlayerAssignments());
	}

	@Test
	public void singleTaskSlayerSession_keepsTaskTitle()
	{
		feed(SessionSignal.slayerTaskAssigned(T0, NECH, NECH_LOC, 2), T0);
		feed(SessionSignal.slayerTaskProgress(T0.plusSeconds(10), NECH, NECH_LOC, 1, 1), T0.plusSeconds(10));
		feed(loot(T0.plusSeconds(11), "Nechryael", 100), T0.plusSeconds(11));
		Session live = current();
		Session loaded = finalizeAndLoad(live, T0.plusSeconds(11));
		HistoryEntry entry = HistoryEntry.from(loaded);
		assertEquals(1, entry.getSlayerAssignmentCount());
		assertEquals(NECH, HistoryEntry.displayTitle(entry.getActivityIdentity(), entry.getSlayerAssignmentCount()));
	}

	@Test
	public void krakenOnCaveKrakenTask_finalizesAsTheSlayerSession_withTheBossLootInTheTaskCard()
	{
		feed(SessionSignal.slayerTaskProgress(T0, "Cave Kraken", "Kraken Cove", 1, 99), T0);
		feed(loot(T0.plusSeconds(1), "Cave kraken", 50), T0.plusSeconds(1));
		Instant t = T0.plusSeconds(60);
		feed(SessionSignal.npcDeath(t), t);
		feed(SessionSignal.slayerTaskProgress(t.plusMillis(1200), "Cave Kraken", "Kraken Cove", 1, 98), t.plusMillis(1200));
		feed(SessionSignal.bossKill(t.plusMillis(3000), "Kraken", 11), t.plusMillis(3000));
		feed(loot(t.plusMillis(3000), "Kraken", 1000), t.plusMillis(3600));
		Session s = current();
		assertEquals(ActivityType.SLAYER, s.getActivityIdentity().getActivityType());

		HistoryEntry entry = HistoryEntry.from(copyFinalized(s));
		assertEquals("one task card: the Cave Kraken assignment", 1, entry.getSlayerAssignmentCount());
		assertEquals("Kraken boss loot sits in the Cave Kraken card with the regular cave kraken loot",
			java.util.Arrays.asList(1050L),
			quantities(copyFinalized(s).getAggregates().getSlayerAssignments().get(0).getItems()));
	}


	private static Session copyFinalized(Session s)
	{
		Session copy = GSON.fromJson(GSON.toJson(s), Session.class);
		copy.setFinalizedAt(Instant.now().toString());
		return copy;
	}

	private static List<Long> quantities(List<SessionAggregates.LootItemAggregate> items)
	{
		List<Long> q = new ArrayList<>();
		for (SessionAggregates.LootItemAggregate i : items)
		{
			q.add(i.getQuantity());
		}
		return q;
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;

import com.osrstelemetry.plugin.session.SlayerTaskFamilyRegistry.LootSourceCompatibility;
import org.junit.Test;

/** SERVER_NPC_LOOT source vs current Slayer assignment: MATCH / KNOWN_MISMATCH / UNKNOWN. */
public class SlayerLootSourceCompatibilityTest
{
	private static LootSourceCompatibility c(String task, String source)
	{
		return SlayerTaskFamilyRegistry.lootSourceCompatibility(task, source);
	}

	@Test
	public void match_familyMembersVariantsAndRuneLiteContainsSemantics()
	{
		assertEquals(LootSourceCompatibility.MATCH, c("Turoth", "Turoth"));
		assertEquals(LootSourceCompatibility.MATCH, c("Turoth", "Spiked turoth"));
		assertEquals("Zombies' 'undead' target", LootSourceCompatibility.MATCH, c("Zombies", "Undead chicken"));
		assertEquals(LootSourceCompatibility.MATCH, c("Kalphites", "Kalphite Worker"));
		assertEquals(LootSourceCompatibility.MATCH, c("Cave Slimes", "Cave slime"));
		assertEquals(LootSourceCompatibility.MATCH, c("Abyssal Demons", "Greater abyssal demon"));
		assertEquals(LootSourceCompatibility.MATCH, c("Nechryael", "Nechryarch"));
		assertEquals("case-insensitive task names", LootSourceCompatibility.MATCH, c("Black Demons", "Black demon"));
	}

	@Test
	public void knownMismatch_sourceIsAnotherTasksTarget()
	{
		assertEquals(LootSourceCompatibility.KNOWN_MISMATCH, c("Turoth", "Undead chicken"));
		assertEquals(LootSourceCompatibility.KNOWN_MISMATCH, c("Turoth", "Goblin"));
		assertEquals(LootSourceCompatibility.KNOWN_MISMATCH, c("Bloodveld", "Cow"));
	}

	@Test
	public void unknown_cannotProveOffTask_existingOwnershipKept()
	{
		assertEquals("summoned/subordinate NPC is no task's target", LootSourceCompatibility.UNKNOWN, c("Nechryael", "Death Spawn"));
		assertEquals(LootSourceCompatibility.UNKNOWN, c("Turoth", null));
		assertEquals(LootSourceCompatibility.UNKNOWN, c("Turoth", "  "));
		assertEquals(LootSourceCompatibility.UNKNOWN, c(null, "Goblin"));
		assertEquals("an uncatalogued task + an NPC no task targets", LootSourceCompatibility.UNKNOWN, c("Foobars", "Mysterious stranger"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.osrstelemetry.plugin.events.EventLedger;
import com.osrstelemetry.plugin.events.EventPayloads;
import com.osrstelemetry.plugin.events.EventType;
import com.osrstelemetry.plugin.loottracker.LootTrackerCoordinator;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerPersistence;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.loottracker.LootTrackerSource;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * SMART SLAYER OFF-TASK LOOT -- PIPELINE SEPARATION.
 *
 * Wires the REAL EventLedger to the REAL SessionRuntimeCoordinator and the
 * REAL LootTrackerCoordinator exactly as OsrsTelemetryPlugin.startUp()
 * does (two independent addListener() registrations), then drives
 * SERVER_NPC_LOOT through EventLedger.appendAndWait() -- the same entry
 * point ServerNpcLootCollector uses. Proves the off-task KNOWN_MISMATCH
 * rule is a Current Session ownership decision ONLY:
 *
 *   - events.jsonl keeps the canonical event (written before fan-out),
 *   - the Loot Tracker records it once under its real source NPC, live
 *     and on rebuild,
 *   - the Slayer session / current assignment bucket never own it -- also
 *     when it shares a tick with combat XP or task progress (the
 *     same-tick promotion leak fixed alongside this test).
 */
public class SlayerOffTaskLootPipelineSeparationTest
{
	private static final long ACCOUNT = 700_900_500L;
	private static final Gson GSON = new Gson();
	private static final String TUROTH = "Turoth";
	private static final String TUROTH_LOC = "Fremennik Slayer Dungeon";
	private static final int COINS = 995;

	private Path testRoot;
	private LocalStateStore store;
	private EventLedger ledger;
	private SessionRuntimeCoordinator session;
	private LootTrackerCoordinator lootTracker;
	private long tick;
	private Instant base;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("offtask-loot-pipeline-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(GSON);
		store.start();
		ledger = new EventLedger(GSON);
		ledger.start();

		session = new SessionRuntimeCoordinator(store);
		installClientThreadClient(session);
		session.ensureAccountLoaded(ACCOUNT);

		lootTracker = new LootTrackerCoordinator(GSON);
		lootTracker.start();
		lootTracker.ensureAccountLoaded(ACCOUNT);
		// Drain the (empty) account-load rebuild before any live event, so
		// live-vs-rebuild ordering can never be what a test measures.
		lootTracker.shutdown();
		lootTracker.start();

		// Same order as OsrsTelemetryPlugin.startUp().
		ledger.addListener(session);
		ledger.addListener(lootTracker);

		tick = 1L;
		base = Instant.now().minusSeconds(5);
	}

	@After
	public void tearDown() throws Exception
	{
		if (ledger != null)
		{
			ledger.removeListener(session);
			ledger.removeListener(lootTracker);
			ledger.shutdown();
		}
		if (lootTracker != null)
		{
			lootTracker.shutdown();
		}
		if (store != null)
		{
			store.shutdown();
		}
		if (testRoot != null)
		{
			TestFilepaths.rooted(testRoot).deleteRecursively();
		}
	}

	// ------------------------------------------------------------------
	// helpers
	// ------------------------------------------------------------------

	/**
	 * Minimal Client for the coordinator's own onEvent() tick tagging:
	 * reports "on the client thread" with the test's current tick, exactly
	 * what a live SERVER_NPC_LOOT dispatch sees. Without it onEvent() leaves
	 * the signal untagged and it is (correctly) never flushed.
	 */
	private void installClientThreadClient(SessionRuntimeCoordinator target) throws Exception
	{
		net.runelite.api.Client client = (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
			net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "isClientThread":
						return true;
					case "getTickCount":
						return (int) tick;
					case "hashCode":
						return System.identityHashCode(proxy);
					case "equals":
						return proxy == args[0];
					case "toString":
						return "TestClient";
					default:
						Class<?> rt = method.getReturnType();
						if (rt == boolean.class)
						{
							return false;
						}
						if (rt.isPrimitive() && rt != void.class)
						{
							return rt == long.class ? (Object) 0L : rt == double.class ? (Object) 0d : rt == float.class ? (Object) 0f : (Object) 0;
						}
						return null;
				}
			});
		java.lang.reflect.Field f = SessionRuntimeCoordinator.class.getDeclaredField("client");
		f.setAccessible(true);
		f.set(target, client);
	}

	/** Session-only evidence (task progress / XP) straight into the coordinator. */
	private void enqueue(SessionSignal signal)
	{
		session.testEnqueueSignal(signal.withGameTick(tick));
	}

	/** Raw SERVER_NPC_LOOT through the real EventLedger -> both listeners. */
	private void appendLoot(String source, Integer sourceId, long coins)
	{
		EventPayloads.ServerNpcLoot payload = new EventPayloads.ServerNpcLoot(source, sourceId,
			Arrays.asList(new EventPayloads.ServerNpcLootItem(COINS, "Coins", (int) coins)));
		assertTrue("durably written", ledger.appendAndWait(ACCOUNT, EventType.SERVER_NPC_LOOT, payload, 2000));
	}

	/** Processes everything queued since the last call as ONE same-tick batch. */
	private void processTick()
	{
		session.testProcessTick(++tick, Instant.now());
	}

	private void startTurothTask()
	{
		enqueue(SessionSignal.slayerTaskProgress(base, TUROTH, TUROTH_LOC, 1, 163));
		processTick();
		appendLoot("Turoth", 426, 10);
		processTick();
	}

	private Session current()
	{
		return session.testCurrentSession();
	}

	private static long sessionCoins(Session s)
	{
		long t = 0;
		for (SessionAggregates.LootDropGroup g : s.getAggregates().getLootDrops())
		{
			t += coins(g.getItems());
		}
		return t;
	}

	private static long currentBucketCoins(Session s)
	{
		List<SessionAggregates.SlayerAssignmentRecord> l = s.getAggregates().getSlayerAssignments();
		return coins(l.get(l.size() - 1).getItems());
	}

	private static long allBucketsCoins(Session s)
	{
		long t = 0;
		for (SessionAggregates.SlayerAssignmentRecord r : s.getAggregates().getSlayerAssignments())
		{
			t += coins(r.getItems());
		}
		return t;
	}

	private static long coins(List<SessionAggregates.LootItemAggregate> items)
	{
		long t = 0;
		for (SessionAggregates.LootItemAggregate i : items)
		{
			if (i.getItemId() != null && i.getItemId() == COINS)
			{
				t += i.getQuantity();
			}
		}
		return t;
	}

	private static boolean sessionHasSource(Session s, String source)
	{
		for (SessionAggregates.LootDropGroup g : s.getAggregates().getLootDrops())
		{
			if (source.equals(g.getSourceName()))
			{
				return true;
			}
		}
		return false;
	}

	private static LootTrackerSource trackerSource(LootTrackerIndex index, String name, Integer id)
	{
		return index.snapshotSource(LootTrackerIndex.sourceKey(name, id));
	}

	private static long trackerCoins(LootTrackerSource src)
	{
		long t = 0;
		for (LootTrackerRecord r : src.getRecords())
		{
			for (com.osrstelemetry.plugin.loottracker.LootTrackerItem i : r.getItems())
			{
				if (i.getItemId() == COINS)
				{
					t += i.getQuantity();
				}
			}
		}
		return t;
	}

	private static int trackerRecordCount(LootTrackerIndex index)
	{
		int n = 0;
		for (LootTrackerSource s : index.snapshotSources())
		{
			n += s.getRecords().size();
		}
		return n;
	}

	/** Every SERVER_NPC_LOOT envelope in events.jsonl for {@code source}. */
	private List<JsonObject> rawLootLines(String source) throws Exception
	{
		Path events = TestFilepaths.file(TelemetryPaths.eventsFile(ACCOUNT)).toPath();
		List<JsonObject> out = new ArrayList<>();
		for (String line : Files.readAllLines(events, StandardCharsets.UTF_8))
		{
			if (line.isEmpty())
			{
				continue;
			}
			JsonObject env = new JsonParser().parse(line).getAsJsonObject();
			if ("SERVER_NPC_LOOT".equals(env.get("eventType").getAsString())
				&& source.equals(env.getAsJsonObject("payload").get("sourceName").getAsString()))
			{
				out.add(env);
			}
		}
		return out;
	}

	private LootTrackerIndex rebuildFromDisk()
	{
		LootTrackerIndex rebuilt = new LootTrackerIndex();
		new LootTrackerPersistence(GSON).rebuild(ACCOUNT, rebuilt, null);
		return rebuilt;
	}

	// ------------------------------------------------------------------
	// 1 + 2 + 3 + 4 + 7: KNOWN_MISMATCH, drop alone in its tick
	// ------------------------------------------------------------------

	@Test
	public void knownMismatch_rejectedFromSessionAndBucket_butRawEventAndLootTrackerKeepIt_onceUnderRealSource() throws Exception
	{
		startTurothTask();
		Session before = current();
		String id = before.getSessionId();
		assertEquals(10L, sessionCoins(before));
		assertEquals(10L, currentBucketCoins(before));

		appendLoot("Undead chicken", 2993, 7);
		processTick();

		// 1. Current Session: rejected, Slayer / Turoth remains current.
		Session s = current();
		assertEquals("Slayer session remains current", id, s.getSessionId());
		assertEquals(ActivityType.SLAYER, s.getActivityIdentity().getActivityType());
		assertEquals("Slayer session loot unchanged", 10L, sessionCoins(s));
		assertTrue("no Undead chicken group in canonical session loot", !sessionHasSource(s, "Undead chicken"));
		assertEquals("Turoth assignment bucket unchanged", 10L, currentBucketCoins(s));
		assertEquals("partition invariant", sessionCoins(s), allBucketsCoins(s));

		// 2 + 7. Live Loot Tracker: the SAME event, once, under the real NPC.
		LootTrackerIndex live = lootTracker.getIndex();
		LootTrackerSource chicken = trackerSource(live, "Undead chicken", 2993);
		assertNotNull("Loot Tracker recorded the off-task drop", chicken);
		assertEquals("Undead chicken", chicken.getSourceName());
		assertEquals(Integer.valueOf(2993), chicken.getSourceId());
		assertEquals("exactly one record -- no duplicate", 1, chicken.getRecords().size());
		assertEquals(7L, trackerCoins(chicken));
		assertEquals("Turoth drop still its own source", 10L, trackerCoins(trackerSource(live, "Turoth", 426)));
		assertEquals("one tracker record per appended event", 2, trackerRecordCount(live));

		// 3. Raw telemetry: exactly one canonical line in events.jsonl.
		List<JsonObject> raw = rawLootLines("Undead chicken");
		assertEquals("canonical SERVER_NPC_LOOT line kept", 1, raw.size());
		assertEquals(7, raw.get(0).getAsJsonObject("payload").getAsJsonArray("items").get(0).getAsJsonObject().get("quantity").getAsInt());

		// 4. Historical rebuild includes it, once, keyed by its real eventId.
		LootTrackerIndex rebuilt = rebuildFromDisk();
		LootTrackerSource rebuiltChicken = trackerSource(rebuilt, "Undead chicken", 2993);
		assertNotNull("rebuild includes the off-task drop", rebuiltChicken);
		assertEquals(1, rebuiltChicken.getRecords().size());
		assertEquals(raw.get(0).get("eventId").getAsString(), rebuiltChicken.getRecords().get(0).getEventId());
		assertEquals(7L, trackerCoins(rebuiltChicken));
		assertEquals("rebuild totals == live totals", trackerRecordCount(live), trackerRecordCount(rebuilt));
		assertEquals("rebuild is idempotent (eventId dedup)", 0, new LootTrackerPersistence(GSON).rebuild(ACCOUNT, rebuilt, null));
	}

	// ------------------------------------------------------------------
	// 1 (same-tick): the fixed promotion leak
	// ------------------------------------------------------------------

	@Test
	public void knownMismatch_sameTickAsCombatXpOrTaskProgress_neverPromotedOntoTheSlayerSession() throws Exception
	{
		startTurothTask();
		String id = current().getSessionId();

		// Chicken drop in the same tick as ordinary combat XP (the batch
		// resolves to the Slayer session itself).
		Instant t1 = Instant.now();
		enqueue(SessionSignal.xpChange(t1, "ATTACK", 40L, base.plusSeconds(1)));
		enqueue(SessionSignal.xpChange(t1, "HITPOINTS", 13L, base.plusSeconds(1)));
		appendLoot("Undead chicken", 2993, 7);
		processTick();
		assertEquals(id, current().getSessionId());
		assertEquals("not promoted via combat XP", 10L, sessionCoins(current()));
		assertEquals(10L, currentBucketCoins(current()));

		// ...and in the same tick as a real Turoth kill's task progress.
		enqueue(SessionSignal.slayerTaskProgress(Instant.now(), TUROTH, TUROTH_LOC, 1, 162));
		appendLoot("Undead chicken", 2993, 9);
		processTick();
		Session s = current();
		assertEquals(id, s.getSessionId());
		assertEquals(ActivityType.SLAYER, s.getActivityIdentity().getActivityType());
		assertEquals("not promoted via task progress", 10L, sessionCoins(s));
		assertEquals(10L, currentBucketCoins(s));
		assertEquals(sessionCoins(s), allBucketsCoins(s));
		assertEquals(Integer.valueOf(162), s.getAggregates().getSlayerAssignments().get(0).getLatestRemaining());

		// Loot Tracker still has both drops, once each, under the real source.
		LootTrackerSource chicken = trackerSource(lootTracker.getIndex(), "Undead chicken", 2993);
		assertEquals(2, chicken.getRecords().size());
		assertEquals(16L, trackerCoins(chicken));
		assertEquals(2, rawLootLines("Undead chicken").size());
		assertEquals(16L, trackerCoins(trackerSource(rebuildFromDisk(), "Undead chicken", 2993)));
	}

	// ------------------------------------------------------------------
	// 5: MATCH reaches all three consumers
	// ------------------------------------------------------------------

	@Test
	public void match_reachesSession_currentBucket_andLootTracker_once_aloneAndSameTick() throws Exception
	{
		startTurothTask();
		String id = current().getSessionId();

		appendLoot("Spiked turoth", 427, 5); // listed family variant
		processTick();
		Instant t = Instant.now();
		enqueue(SessionSignal.xpChange(t, "ATTACK", 40L, base.plusSeconds(1)));
		appendLoot("Turoth", 426, 3); // same tick as combat XP
		processTick();

		Session s = current();
		assertEquals(id, s.getSessionId());
		assertEquals("session owns every MATCH drop exactly once", 18L, sessionCoins(s));
		assertEquals("current Turoth bucket owns them too", 18L, currentBucketCoins(s));
		assertEquals(sessionCoins(s), allBucketsCoins(s));

		LootTrackerIndex live = lootTracker.getIndex();
		assertEquals(13L, trackerCoins(trackerSource(live, "Turoth", 426)));
		assertEquals(2, trackerSource(live, "Turoth", 426).getRecords().size());
		assertEquals(5L, trackerCoins(trackerSource(live, "Spiked turoth", 427)));
		assertEquals(3, trackerRecordCount(live));
		assertEquals(3, trackerRecordCount(rebuildFromDisk()));
	}

	// ------------------------------------------------------------------
	// 6: UNKNOWN keeps the documented Current Session fallback
	// ------------------------------------------------------------------

	@Test
	public void unknown_keepsExistingSessionOwnership_andLootTrackerStillGetsTheCanonicalEvent() throws Exception
	{
		startTurothTask();
		String id = current().getSessionId();

		// No Slayer task targets this NPC: off-task cannot be proven, so the
		// documented fallback is existing ACTIVE-session ownership.
		appendLoot("Death Spawn", 10, 3);
		processTick();

		Session s = current();
		assertEquals(id, s.getSessionId());
		assertEquals("UNKNOWN kept by the ACTIVE Slayer session", 13L, sessionCoins(s));
		assertEquals("...and its current assignment bucket", 13L, currentBucketCoins(s));
		assertTrue(sessionHasSource(s, "Death Spawn"));

		LootTrackerSource spawn = trackerSource(lootTracker.getIndex(), "Death Spawn", 10);
		assertNotNull(spawn);
		assertEquals(1, spawn.getRecords().size());
		assertEquals(3L, trackerCoins(spawn));
		assertEquals(1, rawLootLines("Death Spawn").size());
		assertEquals(1, trackerSource(rebuildFromDisk(), "Death Spawn", 10).getRecords().size());
	}

	// ------------------------------------------------------------------
	// 7: one canonical event -> one tracker record, across every case
	// ------------------------------------------------------------------

	@Test
	public void everyAppendedLootEvent_isExactlyOneLootTrackerRecord_regardlessOfSessionDecision() throws Exception
	{
		startTurothTask();                       // MATCH
		appendLoot("Undead chicken", 2993, 7);   // KNOWN_MISMATCH
		processTick();
		appendLoot("Death Spawn", 10, 3);        // UNKNOWN
		processTick();
		Instant t = Instant.now();
		enqueue(SessionSignal.xpChange(t, "ATTACK", 40L, base.plusSeconds(1)));
		appendLoot("Goblin", 3029, 1);           // KNOWN_MISMATCH, same tick as XP
		processTick();

		LootTrackerIndex live = lootTracker.getIndex();
		assertEquals("4 events -> 4 records, none dropped, none doubled", 4, trackerRecordCount(live));
		Set<String> liveIds = new HashSet<>();
		for (LootTrackerSource src : live.snapshotSources())
		{
			for (LootTrackerRecord r : src.getRecords())
			{
				assertTrue("distinct record ids", liveIds.add(r.getEventId()));
			}
		}
		assertEquals(4, trackerRecordCount(rebuildFromDisk()));
		assertNull("Goblin never reached session loot", sessionHasSource(current(), "Goblin") ? "leaked" : null);
		assertEquals("session: Turoth 10 + Death Spawn 3 only", 13L, sessionCoins(current()));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Small, representative
 * registry-level tests -- deliberately NOT one test per cataloged task
 * alias (per explicit instruction: "do not add dozens of combinatorial
 * tests for every task alias"). Behavioral pipeline coverage (how
 * membership actually participates in session classification) lives in
 * ActivitySignalClassifierTest and SessionRuntimeCoordinatorTest.
 */
public class SlayerTaskFamilyRegistryTest
{
	// Test 1: the worked example from the task spec itself.
	@Test
	public void pyrefiendBelongsToPyrefiendsFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Pyrefiend"));
	}

	// Test 2: the boss-alternative-name example from the task spec.
	@Test
	public void flamingPyrelordBelongsToPyrefiendsFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Flaming pyrelord"));
	}

	// Test 3: a genuinely unrelated NPC is never hand-waved in.
	@Test
	public void unrelatedNpcDoesNotBelongToPyrefiendsFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Goat"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", "Cow"));
	}

	// Case normalization / whitespace: matching must not be case- or
	// whitespace-sensitive.
	@Test
	public void membershipIsCaseAndWhitespaceInsensitive()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("  PYREFIENDS  ", "flaming PYRELORD"));
	}

	// Multi-NPC task family (Gargoyles/Dawn/Dusk) -- the exact data the
	// boss-precedence regression test relies on NOT flattening
	// Grotesque Guardians (see ActivitySignalClassifierTest).
	@Test
	public void gargoylesFamilyIncludesDawnAndDusk()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Dawn"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Dusk"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Gargoyles", "Gargoyle"));
	}

	// Boss-alternative-target example named directly in the task spec.
	@Test
	public void blueDragonsFamilyIncludesVorkathBossAlternative()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Blue dragons", "Vorkath"));
	}

	// An uncatalogued task (not in the static table at all) falls back
	// ONLY to the exact same deterministic trailing-"s" strip RuneLite's
	// own SlayerPlugin unconditionally applies -- never a fuzzy/
	// approximate match, and never hand-waving an unrelated NPC in.
	@Test
	public void uncataloguedTaskFallsBackToSingularStripOnly()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Totally new task creatures", "Totally new task creature"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Totally new task creatures", "Some other monster"));
	}

	@Test
	public void nullTaskOrNpcNameNeverMatches()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily(null, "Pyrefiend"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Pyrefiends", null));
	}

	// ------------------------------------------------------------------
	// Superior-coverage note: RuneLite's own Task enum does not
	// (yet) list every currently-live Superior slayer monster as a
	// target-name alias -- confirmed by direct source inspection (see
	// this class's own SUPERIOR-COVERAGE SOURCE javadoc). Elder aquanite
	// is the gap this fills.
	// ------------------------------------------------------------------

	// An Elder aquanite kill must stay on-task for an assigned Aquanites
	// task rather than being proposed as an off-task candidate switch.
	@Test
	public void elderAquaniteBelongsToAquanitesFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "Elder aquanite"));
	}

	// A superior alias already present (Nechryael ->
	// Nechryarch) must remain covered -- this registry only ever ADDS
	// entries, never removes/reshapes an existing one.
	@Test
	public void nechryarchStillBelongsToNechryaelFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Nechryarch"));
	}

	// A genuinely unrelated NPC is never hand-waved into a family this
	// pass touched, even one superficially "boss-like" in name.
	@Test
	public void unrelatedNpcNeverBelongsToAquanitesFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "Goat"));
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Aquanites", "General Graardor"));
	}

	// Basilisk Knight is a stronger, still-Basilisks-task-assignable NPC
	// (confirmed via its own OSRS Wiki infobox category, not invented) --
	// it and its own superior (Basilisk sentinel) both belong on the
	// EXISTING Basilisks family, never a separate invented task.
	@Test
	public void basiliskKnightAndItsSuperiorBelongToBasilisksFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Basilisks", "Basilisk Knight"));
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Basilisks", "Basilisk sentinel"));
	}

	// Greater Nechryael is Nechryael's own confirmed OSRS-Wiki "Superior
	// slayer monster" -- a genuine coverage gap this pass closes (see the
	// registry's own "Nechryael" entry javadoc). This is the direct
	// regression test for the live-reported bug: a Greater Nechryael kill
	// during an active Nechryael task must be recognized as on-task-family,
	// exactly like its existing Nechryarch sibling above, never treated as
	// an unrelated NPC.
	@Test
	public void greaterNechryaelBelongsToNechryaelFamily()
	{
		assertTrue(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Greater Nechryael"));
	}

	// Negative control for the SAME live-reported bug: Death Spawn is a
	// combat encounter byproduct of fighting Nechryael-family NPCs, never
	// itself an assignable/on-task Nechryael-family member (no OSRS Wiki
	// "Superior slayer monster" or task-alias listing pairs it with
	// Nechryael) -- it must NOT be hand-waved into this family just
	// because it appears during the same encounter. Its protection against
	// prematurely stealing session ownership comes from a different,
	// generic mechanism (SessionLifecycleEngine's downranking-combat-
	// challenge hysteresis), not from this registry -- see
	// SessionRuntimeCoordinatorTest's Death Spawn coverage.
	@Test
	public void deathSpawnNeverBelongsToNechryaelFamily()
	{
		assertFalse(SlayerTaskFamilyRegistry.belongsToTaskFamily("Nechryael", "Death Spawn"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.activity.RecognitionState;
import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.BiFunction;
import org.junit.Test;

/**
 * Per-adapter behaviour for every implemented structured activity, driven
 * table-style through the real coordinator: location, no session on entry,
 * activation, lock, expected-XP ownership, completion, repeated rounds,
 * reward ownership, leave/switch, restart and History.
 */
public class StructuredActivityAdaptersTest extends StructuredActivityTestSupport
{
	static final class Spec
	{
		final String key;
		final String displayName;
		final int region;
		final String[] expectedSkills;
		/** (time, running count) -> completion signal; null = no completion source. */
		final BiFunction<Instant, Integer, SessionSignal> completion;
		/** Canonical reward-source key (null = no reward source). */
		final String rewardName;
		final String rewardDisplay;
		final int rewardRegion;
		final String label;

		Spec(String key, String displayName, int region, String[] expectedSkills,
			BiFunction<Instant, Integer, SessionSignal> completion, String rewardName, String rewardDisplay, int rewardRegion, String label)
		{
			this.key = key;
			this.displayName = displayName;
			this.region = region;
			this.expectedSkills = expectedSkills;
			this.completion = completion;
			this.rewardName = rewardName;
			this.rewardDisplay = rewardDisplay;
			this.rewardRegion = rewardRegion;
			this.label = label;
		}

		@Override
		public String toString()
		{
			return key;
		}
	}

	static final List<Spec> SPECS = Arrays.asList(
		new Spec("guardians_of_the_rift", "Guardians of the Rift", 14484, new String[] {"RUNECRAFT", "MINING", "CRAFTING"},
			(t, n) -> SessionSignal.structuredActivityCompletion(t, "guardians_of_the_rift", n), "guardians_of_the_rift", "Guardians of the Rift", 14484, "Games"),
		new Spec("tempoross", "Tempoross", 12076, new String[] {"FISHING", "CONSTRUCTION", "COOKING"},
			(t, n) -> SessionSignal.bossKill(t, "Tempoross", n), "tempoross_reward_pool", "Tempoross Reward Pool", 12588, "Games"),
		new Spec("pest_control", "Pest Control", 10536, new String[] {"ATTACK", "HITPOINTS", "MAGIC"},
			(t, n) -> SessionSignal.structuredActivityCompletion(t, "pest_control", null), null, null, 0, "Games"),
		new Spec("giants_foundry", "Giants' Foundry", 13491, new String[] {"SMITHING"}, null, null, null, 0, null),
		new Spec("barrows", "Barrows", 14231, new String[] {"RANGED", "HITPOINTS", "DEFENCE"},
			(t, n) -> SessionSignal.activityCompletion(t, "Barrows chest", n), "barrows", "Barrows", 14231, "Chests"),
		new Spec("wintertodt", "Wintertodt", 6462, new String[] {"FIREMAKING", "WOODCUTTING", "FLETCHING"},
			(t, n) -> SessionSignal.activityCompletion(t, "subdued Wintertodt", n), "wintertodt_reward_cart", "Wintertodt Reward Cart", 6461, "Games"));

	void fresh() throws Exception
	{
		tearDownCoordinator();
		setUpCoordinator();
	}

	boolean is(Spec spec, Session s)
	{
		return s != null && s.getActivityIdentity().getActivityType() == ActivityType.STRUCTURED_ACTIVITY
			&& spec.key.equals(s.getActivityIdentity().getActivityKey());
	}

	/** Enter, then expected XP on three distinct ticks. */
	Session play(Spec spec, Instant base)
	{
		onTick(base, enter(spec.key, spec.region, base));
		for (int i = 0; i < 3; i++)
		{
			Instant t = base.plusSeconds(10L * (i + 1));
			onTick(t, xpAt(spec.expectedSkills[i % spec.expectedSkills.length], 25, t));
		}
		return current();
	}

	static SessionSignal reward(Spec spec, Instant t, long coins)
	{
		return SessionSignal.structuredReward(t, spec.key, spec.rewardName,
			Collections.singletonList(new SessionSignal.LootDrop(995, "Coins", coins)));
	}

	static long lootFrom(Session s, String source)
	{
		long total = 0;
		for (SessionAggregates.LootDropGroup g : s.getAggregates().getLootDrops())
		{
			if (source.equals(g.getSourceName()))
			{
				for (SessionAggregates.LootItemAggregate i : g.getItems())
				{
					total += i.getQuantity();
				}
			}
		}
		return total;
	}

	@Test
	public void a_location_noSessionOnEntry_activation_lock_expectedXpOwnership() throws Exception
	{
		for (Spec spec : SPECS)
		{
			fresh();
			onTick(T0, enter(spec.key, spec.region, T0));
			assertNull(spec + ": entry alone is no session", current());
			assertEquals(spec + ": armed", RecognitionState.ARMED, recognition());

			Session s = play(spec, T0);
			assertTrue(spec + ": activated", is(spec, s));
			assertEquals(spec.displayName, s.getActivityIdentity().getDisplayName());
			assertEquals(spec + ": locked", RecognitionState.LOCKED, recognition());
			for (String skill : spec.expectedSkills)
			{
				Instant t = T0.plusSeconds(60 + 10L * Arrays.asList(spec.expectedSkills).indexOf(skill));
				onTick(t, xpAt(skill, 10, t));
				assertEquals(spec + ": expected " + skill + " never fragments", s.getSessionId(), current().getSessionId());
				assertTrue(spec + ": credited " + skill, current().getAggregates().getXpGainedBySkill().containsKey(skill));
			}
		}
	}

	@Test
	public void b_completion_repeatedRounds_oneSession() throws Exception
	{
		for (Spec spec : SPECS)
		{
			fresh();
			String id = play(spec, T0).getSessionId();
			Instant t = T0.plusSeconds(40);
			for (int round = 1; round <= 3; round++)
			{
				for (int i = 0; i < 4; i++)
				{
					t = t.plusSeconds(15);
					onTick(t, xpAt(spec.expectedSkills[i % spec.expectedSkills.length], 30, t));
				}
				if (spec.completion != null)
				{
					t = t.plusSeconds(2);
					onTick(t, spec.completion.apply(t, 50 + round));
				}
				t = t.plusSeconds(60);
			}
			assertEquals(spec + ": all rounds are one session", id, current().getSessionId());
			assertTrue(spec + ": never a boss/other session", is(spec, current()));
			SessionAggregates.ActivityCompletionCount c = current().getAggregates().getActivityCompletions();
			if (spec.completion == null)
			{
				assertNull(spec + ": no completion source, no fabricated metric", c);
			}
			else
			{
				assertEquals(spec + ": completions", 3, c.getSessionCompletions());
				assertEquals(spec.key, c.getActivityKey());
			}
		}
	}

	@Test
	public void c_rewardOwnership_rewardsLandOnlyOnTheActivity() throws Exception
	{
		for (Spec spec : SPECS)
		{
			if (spec.rewardName == null)
			{
				continue;
			}
			fresh();
			// A Slayer session exists first and is parked by the activity.
			onTick(T0, SessionSignal.slayerTaskAssigned(T0, NECH, NECH_LOC, 100));
			onTick(T0.plusSeconds(5), SessionSignal.slayerTaskProgress(T0.plusSeconds(5), NECH, NECH_LOC, 1, 99));
			String slayerId = current().getSessionId();
			Session activity = play(spec, T0.plusSeconds(20));
			assertTrue(is(spec, activity));
			assertEquals(slayerId, coordinator.testInterruptedCandidate().getSessionId());

			Instant t = T0.plusSeconds(90);
			if (spec.rewardRegion != spec.region)
			{
				onTick(t, enter(spec.key, spec.rewardRegion, t));
			}
			onTick(t.plusSeconds(5), reward(spec, t.plusSeconds(5), 777));
			assertEquals(spec + ": reward on the activity", 777L, lootFrom(current(), spec.rewardDisplay));
			assertEquals(spec + ": still the activity", activity.getSessionId(), current().getSessionId());
			assertTrue(spec + ": parked Slayer session untouched",
				coordinator.testInterruptedCandidate().getAggregates().getLootDrops().isEmpty());
		}
	}

	@Test
	public void c2_rewardWithoutTheActivity_isDropped_neverIntoSlayer() throws Exception
	{
		for (Spec spec : SPECS)
		{
			if (spec.rewardName == null)
			{
				continue;
			}
			fresh();
			onTick(T0, SessionSignal.slayerTaskProgress(T0, NECH, NECH_LOC, 1, 99));
			String slayerId = current().getSessionId();
			onTick(T0.plusSeconds(5), reward(spec, T0.plusSeconds(5), 50));
			assertEquals(slayerId, current().getSessionId());
			assertTrue(spec + ": never into the Slayer session", current().getAggregates().getLootDrops().isEmpty());
		}
	}

	@Test
	public void d_leaveThenSwitch() throws Exception
	{
		for (Spec spec : SPECS)
		{
			fresh();
			String id = play(spec, T0).getSessionId();
			Instant out = T0.plusSeconds(60);
			onTick(out, leave(out));
			for (int i = 1; i <= 12; i++)
			{
				Instant t = out.plusSeconds(10L * i);
				onTick(t, xpAt("THIEVING", 20, t));
			}
			assertNotEquals(spec + ": unrelated activity takes over after leaving", id, current().getSessionId());
			assertEquals("thieving", current().getActivityIdentity().getActivityKey().toLowerCase());
		}
	}

	@Test
	public void e_restartReArmsAndResumes() throws Exception
	{
		for (Spec spec : SPECS)
		{
			fresh();
			Instant base = Instant.now().minusSeconds(200);
			String id = play(spec, base).getSessionId();
			restartPlugin();
			Instant after = base.plusSeconds(80);
			onTick(after, enter(spec.key, spec.region, after));
			assertEquals(spec + ": re-armed", RecognitionState.ARMED, recognition());
			onTick(after.plusSeconds(5), xpAt(spec.expectedSkills[0], 10, after.plusSeconds(5)));
			assertEquals(spec + ": same session after restart", id, current().getSessionId());
		}
	}

	@Test
	public void f_historyPreservesIdentityAndMetric() throws Exception
	{
		for (Spec spec : SPECS)
		{
			fresh();
			Instant base = Instant.now().minusSeconds(3 * 3600);
			Session live = play(spec, base);
			Instant last = base.plusSeconds(40);
			if (spec.completion != null)
			{
				onTick(last, spec.completion.apply(last, 9));
			}
			coordinator.testProcessTick(++tick, last.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT).plusSeconds(1));
			coordinator.testProcessTick(++tick, last.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT)
				.plus(SessionLifecycleEngine.RESUME_WINDOW).plusSeconds(5));
			assertNull(current());
			store.shutdown();
			store = new LocalStateStore(GSON);
			store.start();
			Session loaded = new SessionPersistence(store).loadFinalized(ACCOUNT, live.getSessionId());
			assertNotNull(spec + ": finalized file", loaded);
			HistoryEntry entry = HistoryEntry.from(loaded);
			assertEquals(spec.displayName, entry.getActivityIdentity().getDisplayName());
			assertEquals(spec + ": completion count in History",
				Integer.valueOf(spec.completion == null ? 0 : 1), entry.getActivityCompletionCount());
		}
	}

	// ------------------------------------------------------------------ activity-specific

	@Test
	public void tempoross_bossKillIsACompletion_notABossSession_andSubordinateContextNeverSwitches()
	{
		Spec tempoross = SPECS.get(1);
		String id = play(tempoross, T0).getSessionId();
		onTick(T0.plusSeconds(50), SessionSignal.bossActivityContext(T0.plusSeconds(50), "Tempoross"));
		onTick(T0.plusSeconds(60), SessionSignal.bossKill(T0.plusSeconds(60), "Tempoross", 12));
		assertEquals(id, current().getSessionId());
		assertEquals(ActivityType.STRUCTURED_ACTIVITY, current().getActivityIdentity().getActivityType());
		assertNull("no boss kill-count metric on the activity", current().getAggregates().getReliableCount());
		assertEquals(1, current().getAggregates().getActivityCompletions().getSessionCompletions());
		assertEquals(Integer.valueOf(12), current().getAggregates().getActivityCompletions().getLatestAuthoritativeValue());
	}

	@Test
	public void tempoross_rewardPoolInCoveWithoutAGame_createsNothing()
	{
		onTick(T0, enter("tempoross", 12588, T0));
		onTick(T0.plusSeconds(5), reward(SPECS.get(1), T0.plusSeconds(5), 100));
		onTick(T0.plusSeconds(10), xpAt("FISHING", 50, T0.plusSeconds(10)));
		assertTrue("NON_EXCLUSIVE cove: fishing there is ordinary skilling",
			current() != null && current().getActivityIdentity().getActivityType() == ActivityType.SKILLING);
		assertTrue(current().getAggregates().getLootDrops().isEmpty());
	}

	@Test
	public void wintertodt_campIsNonExclusive_woodcuttingThereIsOrdinary()
	{
		onTick(T0, enter("wintertodt", 6461, T0));
		onTick(T0.plusSeconds(5), xpAt("WOODCUTTING", 50, T0.plusSeconds(5)));
		assertEquals(ActivityType.SKILLING, current().getActivityIdentity().getActivityType());
	}

	@Test
	public void slayerTaskProgressInsideAnActivity_neverStealsIt()
	{
		Spec barrows = SPECS.get(4);
		String id = play(barrows, T0).getSessionId();
		onTick(T0.plusSeconds(45), SessionSignal.slayerTaskProgress(T0.plusSeconds(45), "Skeletons", null, 1, 20));
		onTick(T0.plusSeconds(50), SessionSignal.slayerTaskProgress(T0.plusSeconds(50), "Skeletons", null, 1, 19));
		assertEquals(id, current().getSessionId());
		assertNull(coordinator.testInterruptedCandidate());
	}

	@Test
	public void npcLootInsideAnActivity_staysWithTheActivity()
	{
		Spec pc = SPECS.get(2);
		String id = play(pc, T0).getSessionId();
		onTick(T0.plusSeconds(45), SessionSignal.serverNpcLoot(T0.plusSeconds(45), "Brawler",
			Collections.singletonList(new SessionSignal.LootDrop(995, "Coins", 3))));
		assertEquals(id, current().getSessionId());
		assertEquals(3L, lootFrom(current(), "Brawler"));
	}
}

package com.osrstelemetry.plugin.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.activity.RecognitionState;
import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import java.time.Instant;
import java.util.Collections;
import org.junit.Test;

/**
 * Generic structured-activity framework, end to end through the real
 * SessionRuntimeCoordinator (batching, classifier, lifecycle engine,
 * aggregates, persistence). Guardians of the Rift (single EXCLUSIVE region)
 * and Barrows (STRONG_CONTEXT surface) stand in for "any" activity: nothing
 * asserted here depends on which activity it is.
 */
public class StructuredActivityFrameworkTest extends StructuredActivityTestSupport
{
	// ------------------------------------------------------------------ 1-5: recognition

	@Test
	public void t01_locationArmsButDoesNotStart()
	{
		onTick(T0, enter(GOTR, GOTR_REGION, T0));
		for (int i = 1; i <= 20; i++)
		{
			coordinator.testProcessTick(++tick, T0.plusSeconds(i));
		}
		assertNull("location alone never creates a session", current());
		assertEquals(RecognitionState.ARMED, recognition());
	}

	@Test
	public void t02_leavingArmedLocationWithoutActivity_noSession()
	{
		onTick(T0, enter(GOTR, GOTR_REGION, T0));
		onTick(T0.plusSeconds(30), leave(T0.plusSeconds(30)));
		assertNull(current());
		assertEquals(RecognitionState.OUTSIDE, recognition());
		// Expected-skill XP after leaving is ordinary skilling, not the activity.
		onTick(T0.plusSeconds(40), xpAt("MINING", 50, T0.plusSeconds(40)));
		assertNotNull(current());
		assertEquals(ActivityType.SKILLING, current().getActivityIdentity().getActivityType());
	}

	@Test
	public void t03_firstCompatibleEvidenceActivates()
	{
		onTick(T0, enter(GOTR, GOTR_REGION, T0));
		onTick(T0.plusSeconds(5), xpAt("MINING", 50, T0.plusSeconds(5)));
		assertTrue("first compatible evidence starts the activity at once", isGotr(current()));
		assertEquals("Guardians of the Rift", current().getActivityIdentity().getDisplayName());
		assertEquals(SessionState.ACTIVE, current().getState());
		assertEquals(RecognitionState.ACTIVE, recognition());
		assertEquals(Long.valueOf(50), current().getAggregates().getXpGainedBySkill().get("MINING"));
	}

	@Test
	public void t04_distinctConfirmationsLock()
	{
		onTick(T0, enter(GOTR, GOTR_REGION, T0));
		onTick(T0.plusSeconds(5), xpAt("MINING", 50, T0.plusSeconds(5)));
		assertEquals(RecognitionState.ACTIVE, recognition());
		onTick(T0.plusSeconds(10), xpAt("MINING", 50, T0.plusSeconds(10)));
		assertEquals(RecognitionState.ACTIVE, recognition());
		onTick(T0.plusSeconds(15), xpAt("RUNECRAFT", 200, T0.plusSeconds(15)));
		assertEquals(RecognitionState.LOCKED, recognition());
	}

	@Test
	public void t05_sameTickDuplicatesDoNotOverCount()
	{
		onTick(T0, enter(GOTR, GOTR_REGION, T0));
		Instant t = T0.plusSeconds(5);
		onTick(t, xpAt("MINING", 50, t), xpAt("CRAFTING", 10, t), xpAt("RUNECRAFT", 90, t), gotrGame(10, t));
		assertEquals("four signals on one tick are one confirmation", 1, classifierContext().getStructuredActivity().getDistinctConfirmations());
		assertEquals(RecognitionState.ACTIVE, recognition());
		Instant t2 = t.plusSeconds(5);
		onTick(t2, xpAt("MINING", 50, t2), xpAt("MINING", 5, t2));
		assertEquals(RecognitionState.ACTIVE, recognition());
		assertEquals(2, classifierContext().getStructuredActivity().getDistinctConfirmations());
	}

	// ------------------------------------------------------------------ 6-9: ownership

	@Test
	public void t06_expectedXpDoesNotFragmentALockedActivity()
	{
		String id = lockedGotr(T0).getSessionId();
		// Several minutes of alternating support skills: one session throughout.
		for (int i = 0; i < 18; i++)
		{
			Instant t = T0.plusSeconds(40 + i * 10L);
			onTick(t, xpAt(i % 3 == 0 ? "MINING" : i % 3 == 1 ? "CRAFTING" : "RUNECRAFT", 25, t));
			assertEquals(id, current().getSessionId());
		}
		// Unexpected XP inside the EXCLUSIVE location is incidental, never a challenger.
		for (int i = 0; i < 12; i++)
		{
			Instant t = T0.plusSeconds(240 + i * 15L);
			onTick(t, xpAt("AGILITY", 12, t));
		}
		assertEquals(id, current().getSessionId());
		assertTrue(isGotr(current()));
		assertEquals("incidental XP is still credited to the activity", Long.valueOf(144),
			current().getAggregates().getXpGainedBySkill().get("AGILITY"));
	}

	@Test
	public void t06b_strongContext_unexpectedXpIsAChallengerUntilLocked() throws Exception
	{
		// ACTIVE (one confirmation): sustained unrelated XP can still take over.
		onTick(T0, enter(BARROWS, BARROWS_SURFACE, T0));
		onTick(T0.plusSeconds(5), xpAt("ATTACK", 40, T0.plusSeconds(5)));
		assertEquals(RecognitionState.ACTIVE, recognition());
		String activeId = current().getSessionId();
		for (int i = 1; i <= 12; i++)
		{
			Instant t = T0.plusSeconds(5 + 10L * i);
			onTick(t, xpAt("COOKING", 10, t));
		}
		assertNotEquals("STRONG_CONTEXT before LOCKED does not absorb a genuine challenger", activeId, current().getSessionId());

		// LOCKED: the same unrelated XP is incidental and credited to the activity.
		tearDownCoordinator();
		setUpCoordinator();
		onTick(T0, enter(BARROWS, BARROWS_SURFACE, T0));
		onTick(T0.plusSeconds(5), xpAt("ATTACK", 40, T0.plusSeconds(5)));
		onTick(T0.plusSeconds(15), xpAt("STRENGTH", 40, T0.plusSeconds(15)));
		onTick(T0.plusSeconds(25), xpAt("HITPOINTS", 15, T0.plusSeconds(25)));
		assertEquals(RecognitionState.LOCKED, recognition());
		String lockedId = current().getSessionId();
		for (int i = 1; i <= 12; i++)
		{
			Instant t = T0.plusSeconds(25 + 10L * i);
			onTick(t, xpAt("COOKING", 10, t));
		}
		assertEquals(lockedId, current().getSessionId());
		assertEquals(BARROWS, current().getActivityIdentity().getActivityKey());
		assertEquals(Long.valueOf(120), current().getAggregates().getXpGainedBySkill().get("COOKING"));
	}

	@Test
	public void t07_subordinateNpcDoesNotSwitchIdentity()
	{
		onTick(T0, enter(BARROWS, 14231, T0));
		onTick(T0.plusSeconds(5), xpAt("MAGIC", 60, T0.plusSeconds(5)));
		String id = current().getSessionId();
		onTick(T0.plusSeconds(6), SessionSignal.bossActivityContext(T0.plusSeconds(6), "Dharok the Wretched"),
			SessionSignal.npcInteractionTarget(T0.plusSeconds(6), 1673, "Dharok the Wretched"));
		onTick(T0.plusSeconds(8), xpAt("MAGIC", 60, T0.plusSeconds(8)), xpAt("HITPOINTS", 20, T0.plusSeconds(8)));
		SessionSignal raw = SessionSignal.rawCombatXpObserved(T0.plusSeconds(9), "HITPOINTS");
		onTick(T0.plusSeconds(9), raw);
		assertEquals(id, current().getSessionId());
		assertEquals(ActivityType.STRUCTURED_ACTIVITY, current().getActivityIdentity().getActivityType());
		assertEquals(BARROWS, current().getActivityIdentity().getActivityKey());
	}

	@Test
	public void t08_leavingRemovesLocationReinforcement()
	{
