		String slayerId = current().getSessionId();
		Instant in = T0.plusSeconds(30);
		onTick(in, enter(GOTR, GOTR_REGION, in));
		onTick(in.plusSeconds(5), xpAt("MINING", 40, in.plusSeconds(5)));
