package com.osrstelemetry.plugin.storage;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonParser;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** Integrity audit: chained writes are one ordered task serialized at call time; restarts keep order. */
public class LocalStateStoreOrderingTest
{
	private Path dir;

	@Before
	public void setUp() throws Exception
	{
		dir = Files.createTempDirectory("store-ordering-test");
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(dir).deleteRecursively();
	}

	private static String value(File f) throws Exception
	{
		String json = new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
		return new JsonParser().parse(json).getAsJsonObject().get("v").getAsString();
	}

	@Test
	public void writeChained_writesBoth_serializedAtCallTime_thenRunsCallbackOnce() throws Exception
	{
		File first = dir.resolve("first.json").toFile();
		File second = dir.resolve("second.json").toFile();
		LocalStateStore store = new LocalStateStore(new Gson());
		store.start();
		Map<String, String> a = new LinkedHashMap<>();
		a.put("v", "finalized");
		Map<String, String> b = new LinkedHashMap<>();
		b.put("v", "current-at-call");
		AtomicInteger callbacks = new AtomicInteger();

		store.writeChained(TestFilepaths.fromFile(first), a, TestFilepaths.fromFile(second), b, callbacks::incrementAndGet);
		// The caller keeps mutating its live object: the writer must not see it.
		b.put("v", "mutated-after-call");
		// A later write to the same target can never be overtaken by the chained one.
		Map<String, String> later = new LinkedHashMap<>();
		later.put("v", "later");
		store.write(TestFilepaths.fromFile(second), later);
		store.shutdown();

		assertEquals("finalized", value(first));
		assertEquals("later", value(second));
		assertEquals(1, callbacks.get());
	}

	@Test
	public void restartRightAfterShutdown_keepsWritesInOrder() throws Exception
	{
		File target = dir.resolve("prefs.json").toFile();
		LocalStateStore store = new LocalStateStore(new Gson());
		for (int cycle = 0; cycle < 5; cycle++)
		{
			store.start();
			for (int i = 0; i < 20; i++)
			{
				Map<String, String> doc = new LinkedHashMap<>();
				doc.put("v", cycle + ":" + i);
				store.write(TestFilepaths.fromFile(target), doc);
			}
			store.shutdown();
		}
		store.start();
		store.shutdown();
		assertEquals("4:19", value(target));
		assertTrue(!new File(target.getPath() + ".tmp").exists());
	}
}

package com.osrstelemetry.plugin.storage;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.nio.file.Files;
import java.util.concurrent.TimeUnit;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * NOTE: written, not run — no-network caveat as elsewhere.
 *
 * Covers: the plugin can be enabled, disabled, and
 * re-enabled within one client process without a RejectedExecutionException
 * or a dead writer, and shutdown() actually drains queued writes
 * rather than dropping them.
 */
public class LocalStateStoreTest
{
	/**
	 * FIX: plain Java, no Lombok — the test source set doesn't have
	 * Lombok on its compile classpath (real javac error: "package
	 * lombok does not exist"), and production dependency
	 * configuration is intentionally left alone rather than churned
	 * just to make a test fixture compile.
	 */
	private static class Doc
	{
		private String value;

		public Doc()
		{
		}

		public Doc(String value)
		{
			this.value = value;
		}

		public String getValue()
		{
			return value;
		}

		public void setValue(String value)
		{
			this.value = value;
		}
	}

	private static final Gson TEST_GSON = new Gson();

	private File targetFile;

	@Before
	public void setUp()
	{
		targetFile = new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-test-" + System.nanoTime() + ".json");
	}

	@After
	public void tearDown()
	{
		targetFile.delete();
		new File(targetFile.getParentFile(), targetFile.getName() + ".tmp").delete();
	}

	@Test
	public void writeBeforeStartIsSafeNoOp() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		// Deliberately not calling start() — simulates a caller bug,
		// which must not throw.
		store.write(TestFilepaths.fromFile(targetFile), new Doc("should not be written"));
		TimeUnit.MILLISECONDS.sleep(100);
		assertFalse("write before start() must not produce a file", targetFile.exists());
	}

	@Test
	public void writeAfterShutdownIsSafeNoOp() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();
		store.shutdown();

		store.write(TestFilepaths.fromFile(targetFile), new Doc("should not be written either"));
		TimeUnit.MILLISECONDS.sleep(100);
		assertFalse("write after shutdown() must not produce a file", targetFile.exists());
	}

	@Test
	public void shutdownDrainsQueuedWrites() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("hello"));
		// No sleep — shutdown() itself is what must wait for this
		// queued write to complete before returning.
		store.shutdown();

		assertEquals("hello", readValue(targetFile));
	}

	@Test
	public void enableDisableEnableCycleProducesAWorkingStoreEachTime() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);

		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("first"));
		store.shutdown();
		assertEquals("first", readValue(targetFile));

		// Re-enable — this must not throw RejectedExecutionException,
		// and must produce a live writer again.
		store.start();
		store.write(TestFilepaths.fromFile(targetFile), new Doc("second"));
		store.shutdown();
		assertEquals("second", readValue(targetFile));
	}

	@Test
	public void onWrittenCallbackDoesNotRunWhenTheWriteFails() throws Exception
	{
		// A write to a target whose
		// parent directory does not exist must fail (writeNow()
		// returns false), and the dependent callback must NOT run —
		// this is exactly the bug that could have let a BANK_SNAPSHOT
		// event reference a file that never reached disk.
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();

		File badTarget = new File(
			new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-nonexistent-" + System.nanoTime()),
			"file.json"
		);

		final boolean[] callbackRan = {false};
		store.write(TestFilepaths.fromFile(badTarget), new Doc("irrelevant"), () -> callbackRan[0] = true);
		TimeUnit.MILLISECONDS.sleep(200);

		assertFalse("write to a path with a missing parent directory must fail", badTarget.exists());
		assertFalse("onWritten must not run when the write failed", callbackRan[0]);

		store.shutdown();
	}

	@Test
	public void writeAndWaitReturnsFalseOnFailureAndTrueOnSuccess() throws Exception
	{
		LocalStateStore store = new LocalStateStore(TEST_GSON);
		store.start();

		File badTarget = new File(
			new File(System.getProperty("java.io.tmpdir"), "osrs-telemetry-nonexistent-" + System.nanoTime()),
			"file.json"
		);
		assertFalse(store.writeAndWait(TestFilepaths.fromFile(badTarget), new Doc("irrelevant"), 1000));
		assertTrue(store.writeAndWait(TestFilepaths.fromFile(targetFile), new Doc("ok"), 1000));
		assertEquals("ok", readValue(targetFile));

		store.shutdown();
	}

	private String readValue(File file) throws Exception
	{
		String json = new String(Files.readAllBytes(file.toPath()));
		// Cheap extraction, avoids pulling Gson into the test just to
		// read one field back.
		int start = json.indexOf(':') + 1;
		return json.substring(start).replaceAll("[\"{}\\s]", "");
	}
}

package com.osrstelemetry.plugin.storage;

import java.io.File;
import java.nio.file.Path;
import net.runelite.client.util.Filepath;

/**
 * Test-only Filepath construction/bridging.
 *
 * Filepath.Unchecked is deliberately confined to this test helper.
 * Production code must obtain Filepath instances through RuneLite's
 * supported plugin-directory/Filepath APIs.
 */
public final class TestFilepaths
{
    private TestFilepaths()
    {
    }

    public static Filepath rooted(Path path)
    {
        return Filepath.Unchecked.getRooted(path.toAbsolutePath().normalize());
    }

    public static Path path(Filepath filepath)
    {
        return Filepath.Unchecked.getPath(filepath);
    }

    public static File file(Filepath filepath)
    {
        return Filepath.Unchecked.getFile(filepath);
    }

    /**
     * Wrap an ordinary test-fixture File while keeping its parent as the
     * Filepath root. This allows production code under test to access sibling
     * temp files without exposing anything outside the fixture directory.
     */
    public static Filepath fromFile(File file)
    {
        Path path = file.toPath().toAbsolutePath().normalize();
        Path parent = path.getParent();

        if (parent == null)
        {
            throw new IllegalArgumentException("Test file must have a parent: " + file);
        }

        return Filepath.Unchecked.getRooted(parent)
            .joinSegment(path.getFileName().toString());
    }
}

