	private static String titleOf(JPanel card)
	{
		Container header = (Container) card.getComponent(0);
		for (Component c : header.getComponents())
		{
			if (c instanceof JLabel && ((JLabel) c).getText().startsWith("\u25be") || c instanceof JLabel && ((JLabel) c).getText().startsWith("\u25b8"))
			{
				return ((JLabel) c).getText();
			}
		}
		throw new AssertionError("no title");
	}

	@Test
	public void cardTitles_taskNameXn_skippedOnlyForReplacedEarly_tooltipCarriesDetail()
	{
		CurrentSessionView v = view(CurrentSessionSectionOrder.XP_FIRST);
		v.render(endStateSnapshot());
		List<JPanel> cards = cards(v);
		assertEquals("\u25be Kalphites x0", titleOf(cards.get(0)));
		assertEquals("completed tasks carry no badge", "\u25b8 Scorpions x20", titleOf(cards.get(1)));
		assertEquals("\u25b8 Black Demons x17 \u00b7 Skipped", titleOf(cards.get(2)));

		CurrentSessionSnapshot.SlayerAssignmentView skipped = endStateSnapshot().getSlayerAssignments().get(2);
		String tip = CurrentSessionView.slayerTaskCardTooltip(skipped);
		assertTrue(tip, tip.contains("17 completed"));
		assertTrue("the assignment size is never shown", !tip.contains("/ 75"));
		assertTrue(tip, tip.contains("58 remaining"));
		assertTrue(tip, tip.contains("Skipped"));
	}

	@Test
	public void cardHeader_isSidebarSafe_atNarrowWidth_valueNeverPushedOffCard()
	{
		for (int width : new int[] {150, 213})
		{
			CurrentSessionView v = view(CurrentSessionSectionOrder.XP_FIRST);
			v.setSize(width, 2000);
			v.render(endStateSnapshot());
			layout(v);
			for (JPanel card : cards(v))
			{
				Container header = (Container) card.getComponent(0);
				for (Component c : header.getComponents())
				{
					assertTrue("header child inside the card at " + width, c.getX() >= 0 && c.getX() + c.getWidth() <= header.getWidth());
				}
				assertTrue("card inside the sidebar at " + width, card.getWidth() <= width);
			}
		}
	}

	private static void layout(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layout((Container) child);
			}
		}
	}

	// ---------------------------------------------------------------- Slayer XP scope in the view

	private static final class MutableScopeConfig implements OsrsTelemetryConfig
	{
		com.osrstelemetry.plugin.SlayerXpScope scope = com.osrstelemetry.plugin.SlayerXpScope.ALL_TASKS;

		@Override
		public com.osrstelemetry.plugin.SlayerXpScope slayerXpScope()
		{
			return scope;
		}
	}

	private static Set<String> labelTexts(Container root, Set<String> out)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof JLabel && ((JLabel) c).getText() != null)
			{
				out.add(((JLabel) c).getText());
			}
			if (c instanceof Container)
			{
				labelTexts((Container) c, out);
			}
		}
		return out;
	}

	@Test
	public void xpScope_switchesLive_nonDestructively_andOnlyForSlayer()
	{
		Session s = slayerSession("Kalphites");
		s.getAggregates().getXpGainedBySkill().put("DEFENCE", 120_000L);
		SessionAggregates.SlayerAssignmentRecord r = new SessionAggregates.SlayerAssignmentRecord();
		r.setOrdinal(1);
		r.setTaskName("Kalphites");
		r.setXpGainedBySkill(new java.util.LinkedHashMap<>());
		r.getXpGainedBySkill().put("DEFENCE", 18_000L);
		r.setActiveDurationStartMillis(0L);
		List<SessionAggregates.SlayerAssignmentRecord> ledger = new ArrayList<>();
		ledger.add(r);
		s.getAggregates().setSlayerAssignments(ledger);
		CurrentSessionSnapshot snap = CurrentSessionSnapshot.from(SessionSnapshot.capture(s, null, null), T0);

		MutableScopeConfig cfg = new MutableScopeConfig();
		CurrentSessionView v = new CurrentSessionView(null, null, null, cfg);
		v.render(snap);
		assertTrue(labelTexts(v, new java.util.HashSet<>()).contains("+120,000 XP"));
		cfg.scope = com.osrstelemetry.plugin.SlayerXpScope.CURRENT_TASK;
		v.render(snap);
		assertTrue(labelTexts(v, new java.util.HashSet<>()).contains("+18,000 XP"));
		cfg.scope = com.osrstelemetry.plugin.SlayerXpScope.ALL_TASKS;
		v.render(snap);
		assertTrue("switching back restores the session value", labelTexts(v, new java.util.HashSet<>()).contains("+120,000 XP"));
		assertEquals(Long.valueOf(120_000L), s.getAggregates().getXpGainedBySkill().get("DEFENCE"));

		Session boss = new SessionLifecycleEngine().onQualifyingActivity(new ActivityIdentity(ActivityType.BOSSING, "zulrah", "Zulrah"), T0).getCurrent();
		boss.getAggregates().getXpGainedBySkill().put("RANGED", 5_000L);
		cfg.scope = com.osrstelemetry.plugin.SlayerXpScope.CURRENT_TASK;
		v.render(CurrentSessionSnapshot.from(SessionSnapshot.capture(boss, null, null), T0));
		assertTrue("non-Slayer sessions ignore the scope", labelTexts(v, new java.util.HashSet<>()).contains("+5,000 XP"));
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.CurrentSessionSectionOrder;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import java.awt.Component;
import java.awt.Container;
import java.util.Arrays;
import javax.swing.JLabel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import org.junit.Test;

/**
 * Current Session UI/config regressions: the empty-state text clipping fix
 * (real, headless Swing layout -- no RuneLite client needed, since the empty
 * state touches no ItemManager/SkillIconManager) and the XP / Loot order
 * setting.
 */
public class CurrentSessionViewTest
{
	private static final String EMPTY_TEXT = "Start playing normally and activity will appear here.";

	private static final OsrsTelemetryConfig DEFAULT_CONFIG = new OsrsTelemetryConfig()
	{
	};

	// ------------------------------------------------------------------
	// XP / Loot order
	// ------------------------------------------------------------------

	@Test
	public void sectionOrder_configDefault_isXpFirst_theExistingProductionOrder()
	{
		assertEquals(CurrentSessionSectionOrder.XP_FIRST, DEFAULT_CONFIG.currentSessionSectionOrder());
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(DEFAULT_CONFIG.currentSessionSectionOrder()));
	}

	@Test
	public void sectionOrder_xpFirst_placesXpBeforeLoot()
	{
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(CurrentSessionSectionOrder.XP_FIRST));
	}

	@Test
	public void sectionOrder_lootFirst_placesLootBeforeXp()
	{
		assertEquals(Arrays.asList(CurrentSessionView.Section.LOOT, CurrentSessionView.Section.XP),
			CurrentSessionView.orderedSections(CurrentSessionSectionOrder.LOOT_FIRST));
	}

	@Test
	public void sectionOrder_eachSectionRenderedExactlyOnce_nullFallsBackToProductionOrder()
	{
		for (CurrentSessionSectionOrder order : CurrentSessionSectionOrder.values())
		{
			assertEquals("both sections, each exactly once, for " + order, 2,
				CurrentSessionView.orderedSections(order).stream().distinct().count());
		}
		assertEquals(Arrays.asList(CurrentSessionView.Section.XP, CurrentSessionView.Section.LOOT),
			CurrentSessionView.orderedSections(null));
	}

	private static java.util.List<String> plan(CurrentSessionSectionOrder order, boolean hasXp, boolean hasLoot)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		CurrentSessionView.renderSections(CurrentSessionView.orderedSections(order),
			section -> section == CurrentSessionView.Section.XP ? hasXp : hasLoot,
			section -> out.add(section.name()),
			() -> out.add("GAP"));
		return out;
	}

	@Test
	public void sectionGap_exactlyOneBetweenSections_inBothOrders()
	{
		assertEquals(Arrays.asList("XP", "GAP", "LOOT"), plan(CurrentSessionSectionOrder.XP_FIRST, true, true));
		assertEquals(Arrays.asList("LOOT", "GAP", "XP"), plan(CurrentSessionSectionOrder.LOOT_FIRST, true, true));
		assertEquals(6, CurrentSessionView.SECTION_GAP);
	}

	@Test
	public void sectionGap_neverAddedWhenOnlyOneOrNoSectionRenders()
	{
		for (CurrentSessionSectionOrder order : CurrentSessionSectionOrder.values())
		{
			assertEquals(Arrays.asList("XP"), plan(order, true, false));
			assertEquals(Arrays.asList("LOOT"), plan(order, false, true));
			assertEquals(java.util.Collections.emptyList(), plan(order, false, false));
		}
	}

	@Test
	public void currentSessionLoot_stillUsesTheShared5ColumnGrid()
	{
		assertEquals(LootGridCell.GRID_COLUMNS, CurrentSessionView.LOOT_ITEMS_PER_ROW);
		assertEquals(5, LootGridCell.GRID_COLUMNS);
	}

	// ------------------------------------------------------------------
	// Empty-state clipping
	// ------------------------------------------------------------------

	/** Documents the root cause: Swing HTML scales CSS px by 1.3, so the old 180px div was ~233px wide. */
	@Test
	public void rootCause_oldFixedCssWidthLabel_isWiderThanTheSidebarContent()
	{
		JLabel old = new JLabel("<html><div style='text-align:center;width:180px;'>" + EMPTY_TEXT + "</div></html>");
		assertTrue("old label preferred width " + old.getPreferredSize().width + " exceeds the ~201px sidebar content width",
			old.getPreferredSize().width > 201);
	}

	private static WrappingHtmlLabel find(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof WrappingHtmlLabel)
			{
				return (WrappingHtmlLabel) c;
			}
			if (c instanceof Container)
			{
				WrappingHtmlLabel nested = find((Container) c);
				if (nested != null)
				{
					return nested;
				}
			}
		}
		return null;
	}

	private static void layoutTree(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layoutTree((Container) child);
			}
		}
	}

	@Test
	public void emptyState_textStaysInsideTheCardAndWraps_atRepresentativeSidebarWidths()
	{
		// 213 = RuneLite PluginPanel width (225) minus its 6px+6px padding;
		// plus narrower/wider cases -- behavior depends only on component width.
		for (int width : new int[] {150, 180, 213, 260})
		{
			CurrentSessionView view = new CurrentSessionView(null, null, null, DEFAULT_CONFIG);
			view.setSize(width, 600);
			layoutTree(view);
			layoutTree(view); // second pass: label height recomputed at the now-known width

			WrappingHtmlLabel label = find(view);
			assertNotNull("empty state must use the width-tracking label", label);
			Container content = label.getParent();
			int innerLeft = content.getInsets().left;
			int innerRight = content.getWidth() - content.getInsets().right;

			assertTrue("label must start inside the card at width " + width, label.getX() >= innerLeft);
			assertTrue("label must end inside the card at width " + width + " (x=" + label.getX()
				+ ", w=" + label.getWidth() + ", inner right=" + innerRight + ")", label.getX() + label.getWidth() <= innerRight);

			View html = (View) label.getClientProperty(BasicHTML.propertyKey);
			html.setSize(label.getWidth(), 0);
			assertTrue("wrapped text must fit the label's width at " + width,
				html.getMinimumSpan(View.X_AXIS) <= label.getWidth());
			assertTrue("label height must hold the wrapped text at " + width,
				label.getHeight() >= (int) html.getPreferredSpan(View.Y_AXIS));
		}
	}

	@Test
	public void emptyState_wrapsOntoMultipleLines_whenNarrow()
	{
		CurrentSessionView view = new CurrentSessionView(null, null, null, DEFAULT_CONFIG);
		view.setSize(150, 600);
		layoutTree(view);
		layoutTree(view);
		WrappingHtmlLabel label = find(view);
		JLabel oneLine = new JLabel(EMPTY_TEXT);
		oneLine.setFont(label.getFont());
		assertTrue("at 150px the message must wrap rather than overflow",
			label.getHeight() > oneLine.getPreferredSize().height);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import java.awt.Component;
import java.awt.Container;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;
import org.junit.Test;

/**
 * The remaining sidebar empty/help-state labels (History, Loot tab, Recent
 * Activity) use the shared WrappingHtmlLabel instead of the old fixed CSS
 * width:180px HTML (really ~233px in Swing, which clipped). Real headless
 * Swing layout -- same approach as CurrentSessionViewTest.
 */
public class EmptyStateWrappingTest
{
	private static final int[] WIDTHS = {150, 180, 213, 260};

	private static final OsrsTelemetryConfig DEFAULT_CONFIG = new OsrsTelemetryConfig()
	{
	};

	private static WrappingHtmlLabel find(Container root)
	{
		for (Component c : root.getComponents())
		{
			if (c instanceof WrappingHtmlLabel)
			{
				return (WrappingHtmlLabel) c;
			}
			if (c instanceof Container)
			{
				WrappingHtmlLabel nested = find((Container) c);
				if (nested != null)
				{
					return nested;
				}
			}
		}
		return null;
	}

	private static void layoutTree(Container c)
	{
		c.doLayout();
		for (Component child : c.getComponents())
		{
			if (child instanceof Container)
			{
				layoutTree((Container) child);
			}
		}
	}

	/** Lays the view out at `width` (twice: second pass sees the real parent width) and returns its wrapping label. */
	private static WrappingHtmlLabel layOut(Container view, int width)
	{
		view.setSize(width, 800);
		layoutTree(view);
		layoutTree(view);
		WrappingHtmlLabel label = find(view);
		assertNotNull("empty state must use the shared WrappingHtmlLabel", label);
		return label;
	}

	private static void assertFitsInsideParent(String what, WrappingHtmlLabel label, int width)
	{
		Container parent = label.getParent();
		int innerLeft = parent.getInsets().left;
		int innerRight = parent.getWidth() - parent.getInsets().right;
		assertTrue(what + ": label must start inside its container at " + width, label.getX() >= innerLeft);
		assertTrue(what + ": label must end inside its container at " + width + " (x=" + label.getX()
			+ ", w=" + label.getWidth() + ", inner right=" + innerRight + ")", label.getX() + label.getWidth() <= innerRight);

		View html = (View) label.getClientProperty(BasicHTML.propertyKey);
		html.setSize(label.getWidth(), 0);
		assertTrue(what + ": wrapped text must fit the label width at " + width,
			html.getMinimumSpan(View.X_AXIS) <= label.getWidth());
		assertTrue(what + ": label height must hold the wrapped text at " + width,
			label.getHeight() >= (int) html.getPreferredSpan(View.Y_AXIS));
		assertFalse(what + ": no fixed CSS width may remain in the label HTML", label.getText().contains("width:"));
	}

	private static void assertWrapsWhenNarrow(String what, Supplier<Container> viewFactory, int narrowWidth)
	{
		WrappingHtmlLabel label = layOut(viewFactory.get(), narrowWidth);
		JLabel oneLine = new JLabel("x");
		oneLine.setFont(label.getFont());
		assertTrue(what + ": text must wrap onto more lines (taller) at " + narrowWidth + "px",
			label.getHeight() > oneLine.getPreferredSize().height + label.getInsets().top + label.getInsets().bottom);
	}

	// ------------------------------------------------------------------ History

	private static Container historyEmpty()
	{
		return new HistoryView(null, null, null, DEFAULT_CONFIG, id -> { });
	}

	@Test
	public void historyEmptyState_staysInsideSidebar_atRepresentativeWidths()
	{
		for (int width : WIDTHS)
		{
			assertFitsInsideParent("History", layOut(historyEmpty(), width), width);
		}
	}

	@Test
	public void historyEmptyState_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("History", EmptyStateWrappingTest::historyEmpty, 150);
	}

	// ------------------------------------------------------------------ Loot tab

	/** Hosts the Loot tab's real empty-state label exactly the way render() does: in `content` (BoxLayout Y, 6px border). */
	private static Container lootEmpty(String message)
	{
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		content.add(LootTrackerView.emptyStateLabel(message));
		return content;
	}

	@Test
	public void lootTabEmptyStates_stayInsideSidebar_atRepresentativeWidths()
	{
		for (String message : new String[] {LootTrackerView.EMPTY_NO_LOOT, LootTrackerView.EMPTY_FAVORITES, LootTrackerView.EMPTY_NO_MATCH})
		{
			for (int width : WIDTHS)
			{
				WrappingHtmlLabel label = layOut(lootEmpty(message), width);
				assertFitsInsideParent("Loot tab '" + message + "'", label, width);
				assertTrue("Loot tab keeps its 16px top padding", label.getInsets().top == 16);
			}
		}
	}

	@Test
	public void lootTabEmptyState_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("Loot tab", () -> lootEmpty("No items match your search."), 100);
	}

	// ------------------------------------------------------------------ Recent Activity

	@Test
	public void recentActivityPlaceholder_staysInsideSidebar_atRepresentativeWidths()
	{
		for (int width : WIDTHS)
		{
			assertFitsInsideParent("Recent Activity", layOut(new RecentActivityView(), width), width);
		}
	}

	@Test
	public void recentActivityPlaceholder_wrapsWhenNarrow()
	{
		assertWrapsWhenNarrow("Recent Activity", RecentActivityView::new, 100);
	}
}

