package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.LootValuationMode;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.session.Session;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseListener;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * Integrity audit (History detail): a detail result is shown only for the
 * session the player opened and is still looking at; the detail closes when
 * its session leaves the list (e.g. another account's list); a loaded detail
 * re-values itself when prices / GE-HA change.
 */
public class HistoryViewDetailIntegrityTest
{
	private static final Gson GSON = new Gson();
	private LootValuationMode mode = LootValuationMode.GRAND_EXCHANGE;
	private final List<String> opened = new ArrayList<>();
	private HistoryView view;
	private Session x;
	private Session y;

	private static Session finalized(String id, Instant at)
	{
		return GSON.fromJson(("{'sessionId':'" + id + "','activityIdentity':{'activityType':'SKILLING','activityKey':'mining','displayName':'Mining'},"
			+ "'state':'FINALIZED','startedAt':'" + at.minusSeconds(600) + "','lastActiveAt':'" + at.minusSeconds(60)
			+ "','finalizedAt':'" + at + "','accumulatedActiveDurationMillis':60000,'aggregates':{'xpGainedBySkill':{'MINING':100},"
			+ "'lootDrops':[{'sourceName':'Rocks','observedAt':'" + at.minusSeconds(120) + "','items':[{'itemId':440,'itemName':'Iron ore','quantity':3}]}]}}")
			.replace('\'', '"'), Session.class);
	}

	@Before
	public void setUp()
	{
		view = new HistoryView(null, null, null, new OsrsTelemetryConfig()
		{
			@Override
			public LootValuationMode lootValuationMode()
			{
				return mode;
			}
		}, opened::add);
		x = finalized("x", Instant.now().minusSeconds(100));
		y = finalized("y", Instant.now().minusSeconds(200));
		view.render(Arrays.asList(HistoryEntry.from(x), HistoryEntry.from(y)));
	}

	private Object field(String name) throws Exception
	{
		java.lang.reflect.Field f = HistoryView.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(view);
	}

	private Component detail() throws Exception
	{
		return (Component) field("detailView");
	}

	/** Clicks the row for the index-th entry, exactly like the player. */
	private void clickRow(int index) throws Exception
	{
		List<Component> rows = new ArrayList<>();
		for (Component c : ((Container) field("listContent")).getComponents())
		{
			for (MouseListener l : c.getMouseListeners())
			{
				if (l.getClass().getSimpleName().equals("ClickListener"))
				{
					rows.add(c);
				}
			}
		}
		for (MouseListener l : rows.get(index).getMouseListeners())
		{
			l.mouseClicked(null);
		}
	}

	private static Object lastModel(Object detailView) throws Exception
	{
		java.lang.reflect.Field f = HistoryDetailView.class.getDeclaredField("lastModel");
		f.setAccessible(true);
		return f.get(detailView);
	}

	@Test
	public void openedDetail_showsItsOwnResult() throws Exception
	{
		clickRow(0);
		assertTrue(opened.contains("x"));
		view.showDetail(x);
		assertTrue(detail().isVisible());
		assertTrue(lastModel(detail()) != null);
	}

	@Test
	public void lateResultForAnotherSession_isIgnored() throws Exception
	{
		clickRow(1); // opens y
		view.showDetail(x); // a stale load for x arrives
		assertNull("x never replaces the loading y", lastModel(detail()));
	}

	@Test
	public void lateResultAfterBack_doesNotPopTheDetailBackOpen() throws Exception
	{
		clickRow(0);
		java.lang.reflect.Method back = HistoryView.class.getDeclaredMethod("showList");
		back.setAccessible(true);
		back.invoke(view);
		view.showDetail(x);
		assertFalse(detail().isVisible());
		view.showDetailUnavailable();
		assertFalse(detail().isVisible());
	}

	@Test
	public void listWithoutTheOpenSession_closesTheDetail() throws Exception
	{
		clickRow(0);
		view.showDetail(x);
		assertTrue(detail().isVisible());
		// e.g. another account's list after a switch
		view.render(Collections.singletonList(HistoryEntry.from(finalized("other-account", Instant.now().minusSeconds(50)))));
		assertFalse(detail().isVisible());
		view.showDetail(x); // and a late x result cannot reopen it
		assertFalse(detail().isVisible());
	}

	@Test
	public void listStillContainingTheOpenSession_keepsTheDetail() throws Exception
	{
		clickRow(0);
		view.showDetail(x);
		view.render(Arrays.asList(HistoryEntry.from(finalized("newer", Instant.now().minusSeconds(10))), HistoryEntry.from(x), HistoryEntry.from(y)));
		assertTrue(detail().isVisible());
	}

	@Test
	public void geToHighAlch_reValuesTheOpenDetail_andNothingElseRedraws() throws Exception
	{
		clickRow(0);
		view.showDetail(x);
		java.lang.reflect.Field cf = HistoryDetailView.class.getDeclaredField("content");
		cf.setAccessible(true);
		Container content = (Container) cf.get(detail());
		Component before = content.getComponent(0);
		view.refreshDetailValues();
		assertSame("unchanged prices and mode: no redraw", before, content.getComponent(0));
		mode = LootValuationMode.HIGH_ALCH;
		view.refreshDetailValues();
		assertNotSame(before, content.getComponent(0));
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.osrstelemetry.plugin.history.HistoryEntry;
import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import org.junit.Test;

/**
 * Covers
 * {@link HistoryView#computeRenderKey} -- the pure, Swing-free
 * presentation fingerprint {@code render()} uses to skip a full rebuild
 * when the entry set on screen hasn't actually changed -- without
 * constructing the Swing view itself (this project has no Mockito, and
 * HistoryView needs SkillIconManager/ItemManager/ClientThread, none of
 * which can be faked here; same "test only the pure static methods"
 * convention LootTrackerViewTest already establishes).
 *
 * {@link #heightBoundedPanel_maximumHeightTracksPreferredHeight} and
 * {@link #heightBoundedPanel_widthStaysUnbounded} cover
 * {@link HistoryView#heightBoundedPanel}. Unlike the rest of this class,
 * {@code heightBoundedPanel} needs NO RuneLite dependency at all --
 * {@code JPanel}/{@code Dimension} are plain {@code javax.swing}/
 * {@code java.awt}, so this is a real, runnable, non-mocked test of the
 * exact behavior the fix depends on: that the returned panel's maximum
 * height always equals its OWN current preferred height (never a
 * hardcoded constant), while its maximum width stays unbounded so it
 * can still stretch to fill a row's width as before.
 */
public class HistoryViewTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	private static HistoryEntry buildEntry()
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Instant suspendedAt = T0.plus(SessionLifecycleEngine.SUSPEND_TIMEOUT);
		engine.advanceTime(suspendedAt);
		Instant expiry = suspendedAt.plus(SessionLifecycleEngine.RESUME_WINDOW);
		Session finalized = engine.advanceTime(expiry).getFinalized();
		return HistoryEntry.from(finalized);
	}

	@Test
	public void computeRenderKey_emptyList_isStableAndNotNull()
	{
		String key = HistoryView.computeRenderKey(Collections.emptyList());
		assertEquals(key, HistoryView.computeRenderKey(Collections.emptyList()));
	}

	@Test
	public void computeRenderKey_sameEntries_sameKey()
	{
		List<HistoryEntry> entries = Arrays.asList(buildEntry(), buildEntry());
		assertEquals(HistoryView.computeRenderKey(entries), HistoryView.computeRenderKey(entries));
	}

	@Test
	public void computeRenderKey_differentEntryCount_differentKey()
	{
		HistoryEntry entry = buildEntry();
		String keyOne = HistoryView.computeRenderKey(Collections.singletonList(entry));
		String keyTwo = HistoryView.computeRenderKey(Arrays.asList(entry, entry));
		assertNotEquals(keyOne, keyTwo);
	}

	@Test
	public void heightBoundedPanel_maximumHeightTracksPreferredHeight()
	{
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		panel.add(new JLabel("row content"));
		Dimension preferred = panel.getPreferredSize();

		assertEquals("maximum height must equal the panel's own current preferred height, never a hardcoded value",
			preferred.height, panel.getMaximumSize().height);
	}

	@Test
	public void heightBoundedPanel_widthStaysUnbounded()
	{
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		assertEquals(Integer.MAX_VALUE, panel.getMaximumSize().width);
	}

	@Test
	public void heightBoundedPanel_maximumHeightUpdatesWhenContentGrows()
	{
		// Regression guard for the exact bug this fixes: a card's maximum
		// height must track ITS OWN content (e.g. collapsed vs. expanded),
		// never stay pinned to whatever it happened to be at construction.
		JPanel panel = HistoryView.heightBoundedPanel(new BorderLayout());
		int heightBefore = panel.getMaximumSize().height;

		panel.add(new JLabel("<html>a fairly tall<br>multi-line<br>label</html>"));
		int heightAfter = panel.getMaximumSize().height;

		assertTrue("maximum height should grow to match new preferred height once content is added",
			heightAfter >= heightBefore);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

/**
 * Integrity audit continuation (UI invalidation): a surface dirtied again
 * WHILE it is being rendered is rendered again afterwards -- the second
 * mutation is never swallowed by the first render's completion.
 */
public class IntegrityAuditContinuationUiTest
{
	private final List<Runnable> edtQueue = new ArrayList<>();
	private final List<Set<UiSurface>> renders = new ArrayList<>();
	private UiRefreshCoalescer coalescer;

	private void runEdt()
	{
		while (!edtQueue.isEmpty())
		{
			edtQueue.remove(0).run();
		}
	}

	@Test
	public void markDuringRender_isRenderedAgainAfterwards()
	{
		coalescer = new UiRefreshCoalescer(edtQueue::add, dirty ->
		{
			renders.add(dirty);
			if (renders.size() == 1)
			{
				// Another runtime mutation lands mid-render.
				coalescer.markDirty(UiSurface.CURRENT_SESSION);
			}
		});
		coalescer.markDirty(UiSurface.CURRENT_SESSION);
		runEdt();
		assertEquals("the mid-render mark produced a second render", 2, renders.size());
		assertEquals(EnumSet.of(UiSurface.CURRENT_SESSION), renders.get(1));
		assertTrue("and nothing is left queued", edtQueue.isEmpty());
	}

	@Test
	public void markForAnotherSurfaceDuringRender_isNotLostEither()
	{
		coalescer = new UiRefreshCoalescer(edtQueue::add, dirty ->
		{
			renders.add(dirty);
			if (renders.size() == 1)
			{
				coalescer.markDirty(UiSurface.LOOT_TRACKER);
				coalescer.markDirty(UiSurface.CURRENT_SESSION);
			}
		});
		coalescer.markDirty(UiSurface.CURRENT_SESSION);
		runEdt();
		assertEquals(2, renders.size());
		assertEquals(EnumSet.of(UiSurface.CURRENT_SESSION, UiSurface.LOOT_TRACKER), renders.get(1));
	}

	@Test
	public void shutdownDuringRender_dropsTheFollowUp()
	{
		coalescer = new UiRefreshCoalescer(edtQueue::add, dirty ->
		{
			renders.add(dirty);
			coalescer.markDirty(UiSurface.HISTORY);
			coalescer.shutdown();
		});
		coalescer.markDirty(UiSurface.HISTORY);
		runEdt();
		assertEquals(1, renders.size());
	}
}

