 * Narrow-width Loot toolbar/header layout (full Total Loot, caret always
 * visible) and the ONE smart bulk button (decided by the MANUAL state of
 * the displayed cards; one preference write; no full render).
 */
public class LootNarrowWidthAndBulkTest
{
	private static final Instant T0 = Instant.parse("2026-09-01T00:00:00Z");
	private static final int[] WIDTHS = {150, 180, 213, 260};

	private Path testRoot;
	private int writes;
	private int refreshRequests;
	private LootTrackerPreferences prefs;
	private LootTrackerIndex index;
	private LootTrackerView view;

	private final class CountingStore extends LocalStateStore
	{
		CountingStore()
		{
			super(new Gson());
		}

		@Override
		public void write(net.runelite.client.util.Filepath target, Object document, Runnable onWritten)
		{
			writes++;
		}
	}

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-narrow-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		prefs = new LootTrackerPreferences(new CountingStore());
		prefs.loadForAccount(1L);
		index = new LootTrackerIndex();
		view = new LootTrackerView(null, null, new OsrsTelemetryConfig()
		{
		}, prefs);
		// Coins at 1 gp each so the totals are real, resolved synchronously.
		java.lang.reflect.Field cache = LootTrackerView.class.getDeclaredField("itemValuationCache");
		cache.setAccessible(true);
		cache.set(view, new ItemValuationCache(Runnable::run, id -> id == 995 ? 1L : 0L, id -> id == 995 ? 1L : 0L));
		view.setRefreshRequester(() -> refreshRequests++);
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private int ev;

	private void drops(String source, int sourceId, int count, long coinsEach)
	{
		for (int i = 0; i < count; i++)
		{
			index.apply(new LootTrackerRecord("e" + (ev++), source, sourceId, T0.plusSeconds(ev),
				Collections.singletonList(new LootTrackerItem(995, "Coins", coinsEach))));
		}
	}

	private void render()
	{
		view.render(LootTrackerSnapshot.from(index, prefs));
		view.render(LootTrackerSnapshot.from(index, prefs)); // prices resolved on the first pass
	}

	private static List<Component> all(Container c)
	{
		List<Component> out = new ArrayList<>();
		for (Component k : c.getComponents())
		{
			out.add(k);
			if (k instanceof Container)
			{
				out.addAll(all((Container) k));
			}
		}
		return out;
	}

	private static void layout(Container c)
	{
		c.doLayout();
		for (Component k : c.getComponents())
		{
			if (k instanceof Container)
			{
				layout((Container) k);
			}
		}
	}

	private void layoutAt(int width)
	{
		view.setSize(width, 4000);
		for (int pass = 0; pass < 2; pass++)
		{
			view.invalidate();
			layout(view);
		}
	}

	private Rectangle inView(Component c)
	{
		return SwingUtilities.convertRectangle(c.getParent(), c.getBounds(), view);
	}

	private JLabel totalLabel() throws Exception
	{
		java.lang.reflect.Field f = LootTrackerView.class.getDeclaredField("globalTotalHeader");
		f.setAccessible(true);
		return (JLabel) f.get(view);
	}

	private JButton bulk()
	{
		JButton found = null;
		for (Component c : all(view))
		{
			if (c instanceof JButton && (LootTrackerView.BULK_COLLAPSE_TEXT.equals(((JButton) c).getText())
				|| LootTrackerView.BULK_OPEN_TEXT.equals(((JButton) c).getText())))
			{
				assertNull("exactly one bulk button", found);
				found = (JButton) c;
			}
		}
		return found;
	}

	private static void press(JButton b)
	{
		for (ActionListener l : b.getActionListeners())
		{
			l.actionPerformed(null);
		}
	}

	private void search(String text) throws Exception
	{
		java.lang.reflect.Field f = LootTrackerView.class.getDeclaredField("searchField");
		f.setAccessible(true);
		((JTextField) f.get(view)).setText(text);
	}

	private boolean manual(String source, int id)
	{
		return prefs.isCollapsed(LootTrackerIndex.sourceKey(source, id));
	}

	// ------------------------------------------------------------------ Total Loot

	@Test
	public void totalLoot_isNeverClipped_atSidebarWidths() throws Exception
	{
		for (long total : new long[] {999L, 64_012_345L, 1_234_567L, 12_345_678_901L})
		{
			index = new LootTrackerIndex();
			drops("Chest", 1, 1, total);
			render();
			for (int width : WIDTHS)
			{
				layoutAt(width);
				JLabel label = totalLabel();
				Rectangle r = inView(label);
				assertTrue(width + "px " + label.getText() + ": full width", label.getWidth() >= label.getPreferredSize().width);
				assertTrue(width + "px: inside", r.x >= 0 && r.x + r.width <= width);
				assertTrue(label.getText().startsWith("Total Loot: "));
			}
		}
		assertTrue("exact value on hover", totalLabel().getToolTipText().contains("12,345,678,901"));
	}

	// ------------------------------------------------------------------ source header

	@Test
	public void longSourceWithHugeCount_keepsCountAndCaretVisible_grouped_and_individual() throws Exception
	{
		drops("Greater Nechryael", 7278, 2240, 1);
		drops("Imp", 3134, 2, 1);
		prefs.setFavorite(Collections.singletonList(LootTrackerIndex.sourceKey("Greater Nechryael", 7278)), true);
		for (boolean individual : new boolean[] {false, true})
		{
			if (individual)
			{
				for (Component c : all(view))
				{
					if (c instanceof JButton && "Grouped".equals(((JButton) c).getText()))
					{
						press((JButton) c);
					}
				}
			}
			render();
			for (int width : WIDTHS)
			{
				layoutAt(width);
				for (Component c : all(view))
				{
					if (!(c instanceof JLabel))
					{
						continue;
					}
					JLabel l = (JLabel) c;
					boolean caret = "▸".equals(l.getText()) || "▾".equals(l.getText());
					boolean count = LootTrackerView.SOURCE_COUNT_NAME.equals(l.getName());
					if (caret || count)
					{
						Rectangle r = inView(l);
						String what = width + "px " + (individual ? "individual " : "grouped ") + l.getText();
						assertTrue(what + " visible", l.getWidth() > 0 && l.isShowing() || l.getWidth() >= l.getPreferredSize().width);
						assertTrue(what + " not clipped", l.getWidth() >= l.getPreferredSize().width);
						assertTrue(what + " inside the sidebar (" + (r.x + r.width) + ")", r.x >= 0 && r.x + r.width <= width);
					}
				}
			}
		}
	}

	@Test
	public void countIsItsOwnLabel_andTheNameShrinksFirst() throws Exception
	{
		drops("Greater Nechryael", 7278, 2240, 1);
		render();
		layoutAt(150);
		JLabel name = null;
		JLabel count = null;
		for (Component c : all(view))
		{
			if (LootTrackerView.SOURCE_TITLE_NAME.equals(c.getName()))
			{
				name = (JLabel) c;
			}
			if (LootTrackerView.SOURCE_COUNT_NAME.equals(c.getName()))
			{
				count = (JLabel) c;
			}
		}
		assertNotNull(name);
		assertEquals("×2240", count.getText());
		assertEquals("Greater Nechryael", name.getToolTipText());
		assertTrue("the name is what gives way", name.getWidth() < name.getPreferredSize().width);
		assertTrue(count.getWidth() >= count.getPreferredSize().width);
	}

	// ------------------------------------------------------------------ smart bulk button

	private void threeSources()
	{
		drops("Alpha", 1, 3, 10);
		drops("Beta", 2, 3, 10);
		drops("Gamma", 3, 3, 10);
		render();
		writes = 0;
		refreshRequests = 0;
	}

	@Test
	public void allOpen_offersCollapseAll_click_collapses_andFlips() throws Exception
	{
		threeSources();
		assertEquals(LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
		press(bulk());
		assertTrue(manual("Alpha", 1) && manual("Beta", 2) && manual("Gamma", 3));
		assertEquals("flips at once", LootTrackerView.BULK_OPEN_TEXT, bulk().getText());
		assertEquals("one preference write", 1, writes);
		assertEquals("no full render", 0, refreshRequests);
		press(bulk());
		assertFalse(manual("Alpha", 1) || manual("Beta", 2) || manual("Gamma", 3));
		assertEquals(LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
		assertEquals(2, writes);
	}

	@Test
	public void mixed_offersCollapseAll() throws Exception
	{
		prefs.setCollapsed(Collections.singletonList(LootTrackerIndex.sourceKey("Alpha", 1)), true);
		threeSources();
		assertEquals(LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
		press(bulk());
		assertTrue(manual("Alpha", 1) && manual("Beta", 2) && manual("Gamma", 3));
		assertEquals(LootTrackerView.BULK_OPEN_TEXT, bulk().getText());
	}

	@Test
	public void singleCardToggle_updatesTheBulkButton() throws Exception
	{
		threeSources();
		press(bulk()); // all collapsed -> "Open All"
		for (Component c : all(view))
		{
			if (LootTrackerView.SOURCE_TITLE_NAME.equals(c.getName()) && "Beta".equals(((JLabel) c).getText()))
			{
				for (java.awt.event.MouseListener l : c.getMouseListeners())
				{
					l.mouseClicked(null);
				}
			}
		}
		assertFalse(manual("Beta", 2));
		assertEquals("mixed again -> Collapse All", LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
	}

	@Test
	public void favoritesFilter_decidesAndActsOnDisplayedCardsOnly() throws Exception
	{
		prefs.setFavorite(Collections.singletonList(LootTrackerIndex.sourceKey("Alpha", 1)), true);
		prefs.setCollapsed(Collections.singletonList(LootTrackerIndex.sourceKey("Alpha", 1)), true);
		threeSources();
		assertEquals("All tab: mixed", LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
		for (Component c : all(view))
		{
			if (c instanceof JButton && "Favorites".equals(((JButton) c).getText()))
			{
				press((JButton) c);
			}
		}
		render();
		assertEquals("Favorites tab: its one card is collapsed", LootTrackerView.BULK_OPEN_TEXT, bulk().getText());
		press(bulk());
		assertFalse(manual("Alpha", 1));
		assertFalse("filtered-out cards untouched", manual("Beta", 2));
		assertFalse(manual("Gamma", 3));
	}

	@Test
	public void searchExpansion_doesNotFoolTheButton_explicitPressChangesManualState() throws Exception
	{
		drops("Alpha", 1, 2, 10);
		index.apply(new LootTrackerRecord("rune", "Beta", 2, T0.plusSeconds(999), Collections.singletonList(new LootTrackerItem(1127, "Rune platebody", 1))));
		drops("Gamma", 3, 2, 10);
		render();
		press(bulk()); // everything manually collapsed
		search("rune"); // Beta is displayed and temporarily expanded
		render();
		assertEquals("manual state is all collapsed, whatever the search shows", LootTrackerView.BULK_OPEN_TEXT, bulk().getText());
		press(bulk()); // explicit: open the displayed card
		assertFalse(manual("Beta", 2));
		assertTrue("not displayed -> untouched", manual("Alpha", 1) && manual("Gamma", 3));
		assertEquals(LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
		search("");
		render();
		assertFalse("clearing the search keeps the explicit result", manual("Beta", 2));
		assertTrue(manual("Alpha", 1));
		assertEquals("mixed after clearing", LootTrackerView.BULK_COLLAPSE_TEXT, bulk().getText());
	}

	@Test
	public void bulkButton_fitsAndNothingOverflows_atNarrowWidths() throws Exception
	{
		threeSources();
		for (int width : WIDTHS)
		{
			layoutAt(width);
			JButton b = bulk();
			Rectangle r = inView(b);
			assertTrue(width + "px bulk inside", r.x >= 0 && r.x + r.width <= width);
			assertTrue(width + "px bulk not clipped", b.getWidth() >= b.getPreferredSize().width);
			for (Component c : all(view))
			{
				if (c.isVisible() && c.getWidth() > 0)
				{
					Rectangle cr = inView(c);
					assertTrue(width + "px: " + c.getClass().getSimpleName() + " " + c.getName() + " overflows (" + (cr.x + cr.width) + ")",
						cr.x + cr.width <= width + 1);
				}
			}
		}
	}

	@Test
	public void bulkKeepsCardShells_noFullRebuild() throws Exception
	{
		threeSources();
		java.lang.reflect.Field f = LootTrackerView.class.getDeclaredField("displayedCards");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		List<Object> before = new ArrayList<>((List<Object>) f.get(view));
		press(bulk());
		press(bulk());
		@SuppressWarnings("unchecked")
		List<Object> after = (List<Object>) f.get(view);
		for (int i = 0; i < before.size(); i++)
		{
			assertSame(before.get(i), after.get(i));
		}
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;

import com.osrstelemetry.plugin.session.ActivityIdentity;
import com.osrstelemetry.plugin.session.ActivityType;
import com.osrstelemetry.plugin.session.Session;
import com.osrstelemetry.plugin.session.SessionAggregates;
import com.osrstelemetry.plugin.session.SessionLifecycleEngine;
import com.osrstelemetry.plugin.session.SessionSnapshot;
import com.osrstelemetry.plugin.ui.model.CurrentSessionSnapshot;
import java.time.Instant;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * NOTE: written, not run -- same no-JDK-in-this-cloud-sandbox caveat
 * documented across this project's other Java test files (see
 * SessionLifecycleEngineTest). Josh's own `.\gradlew.bat clean test`
 * run is what actually executes these.
 *
 * Pure tests for
 * {@link LootPricing}'s own arithmetic/ordering. Resolving an actual
 * unit price is CurrentSessionView's job (RuneLite's ItemManager,
 * exercised only by the real client) -- these tests supply a plain
 * lambda price lookup instead, exactly the seam LootPricing was split
 * out for (this project has no Mockito dependency). LootEntry
 * instances are obtained the same way CurrentSessionSnapshotTest
 * builds its own fixtures (a real SessionLifecycleEngine +
 * SessionSnapshot.capture()), since LootEntry's own constructor is
 * package-private to ui.model.
 */
public class LootPricingTest
{
	private static final Instant T0 = Instant.parse("2026-01-01T10:00:00Z");
	private static final ActivityIdentity GARGOYLES =
		new ActivityIdentity(ActivityType.SLAYER, "gargoyles:catacombs", "Gargoyles");

	// ------------------------------------------------------------------
	// Sorting is by TOTAL stack value, never unit price alone
	// -- the task's own "rune platebody (38k x 2 = 76k) outranks coins
	// (50k total)" example, under GE-sourced prices.
	// ------------------------------------------------------------------
	@Test
	public void valueAndSort_ordersByTotalStackValueDescending_underGeMode()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(995, "Coins", 50_000L),
			item(1127, "Rune platebody", 2L));

		Map<Integer, Long> gePrices = new HashMap<>();
		gePrices.put(995, 1L);
		gePrices.put(1127, 38_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> gePrices.getOrDefault(id, 0L));

		assertEquals(2, rows.size());
		assertEquals("Rune platebody", rows.get(0).getItemName());
		assertEquals(76_000L, rows.get(0).getTotalValue());
		assertEquals("Coins", rows.get(1).getItemName());
		assertEquals(50_000L, rows.get(1).getTotalValue());
	}

	// Same "total stack value, not unit price" rule, exercised again
	// under a completely different (High Alch) price source, so GE and
	// HA are each covered by their own test.
	@Test
	public void valueAndSort_ordersByTotalStackValueDescending_underHighAlchMode()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(561, "Nature rune", 40L),
			item(1201, "Amulet of glory", 1L));

		Map<Integer, Long> haPrices = new HashMap<>();
		haPrices.put(561, 90L);
		haPrices.put(1201, 3_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> haPrices.getOrDefault(id, 0L));

		// Nature rune: 40 x 90 = 3,600 -- outranks the single Amulet of
		// glory at 3,000.
		assertEquals(2, rows.size());
		assertEquals("Nature rune", rows.get(0).getItemName());
		assertEquals(3_600L, rows.get(0).getTotalValue());
		assertEquals("Amulet of glory", rows.get(1).getItemName());
		assertEquals(3_000L, rows.get(1).getTotalValue());
	}

	@Test
	public void valueAndSort_tiesBrokenByItemNameAscending()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(2, "Zulrah's scales", 100L),
			item(1, "Ancient shard", 100L));

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> 10L);

		assertEquals("Ancient shard", rows.get(0).getItemName());
		assertEquals("Zulrah's scales", rows.get(1).getItemName());
	}

	// ------------------------------------------------------------------
	// The compact total-session-loot-value figure.
	// ------------------------------------------------------------------
	@Test
	public void sumTotalValue_isTheSumOfEveryRow()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(
			item(995, "Coins", 1_000L),
			item(1127, "Rune platebody", 2L));

		Map<Integer, Long> gePrices = new HashMap<>();
		gePrices.put(995, 1L);
		gePrices.put(1127, 38_000L);

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id -> gePrices.getOrDefault(id, 0L));

		assertEquals(77_000L, LootPricing.sumTotalValue(rows));
	}

	// An unresolvable price (e.g. no GE listing) must never crash the
	// panel -- see LootPricing.safeLookup()'s own javadoc.
	@Test
	public void valueAndSort_unresolvableItemIsPricedAtZero_notSkipped()
	{
		List<CurrentSessionSnapshot.LootEntry> entries = lootEntries(item(9999, "Mystery item", 5L));

		List<LootPricing.ValuedLootRow> rows = LootPricing.valueAndSort(entries, id ->
		{
			throw new RuntimeException("no price available");
		});

		assertEquals(1, rows.size());
		assertEquals(0L, rows.get(0).getTotalValue());
	}

	private static List<CurrentSessionSnapshot.LootEntry> lootEntries(SessionAggregates.LootItemAggregate... items)
	{
		SessionLifecycleEngine engine = new SessionLifecycleEngine();
		engine.onQualifyingActivity(GARGOYLES, T0);
		Session session = engine.getCurrentSession();

		SessionAggregates.LootDropGroup group = new SessionAggregates.LootDropGroup();
		group.setSourceName("Gargoyle");
		group.setObservedAt(T0.toString());
		group.setItems(Arrays.asList(items));
		session.getAggregates().getLootDrops().add(group);

		CurrentSessionSnapshot snapshot = CurrentSessionSnapshot.from(SessionSnapshot.capture(session), T0);
		return snapshot.getLootEntries();
	}

	private static SessionAggregates.LootItemAggregate item(int itemId, String itemName, long quantity)
	{
		SessionAggregates.LootItemAggregate aggregate = new SessionAggregates.LootItemAggregate();
		aggregate.setItemId(itemId);
		aggregate.setItemName(itemName);
		aggregate.setQuantity(quantity);
		return aggregate;
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.LootValuationMode;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.LootTrackerSnapshot;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Integrity audit (Loot Tracker view side): a retained card is only correct
 * if the render key covers everything it shows -- GE/HA included -- and a
 * card's preference writes cover every raw variant it stands for.
 */
public class LootTrackerAuditViewTest
{
	private static final Instant T0 = Instant.parse("2026-09-01T00:00:00Z");

	private Path testRoot;
	private LocalStateStore store;
	private LootTrackerPreferences prefs;
	private LootValuationMode mode = LootValuationMode.GRAND_EXCHANGE;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-audit-view-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		store = new LocalStateStore(new Gson());
		store.start();
		prefs = new LootTrackerPreferences(store);
		prefs.loadForAccount(5L);
	}

	@After
	public void tearDown() throws Exception
	{
		store.shutdown();
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private static Object field(Object target, String name) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				java.lang.reflect.Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				return f.get(target);
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}

	private static LootTrackerRecord rec(String id, String name, int sourceId, Instant at)
	{
		return new LootTrackerRecord(id, name, sourceId, at, Collections.singletonList(new LootTrackerItem(995, "Coins", 10)));
	}

	@Test
	public void switchingGeToHighAlch_reRendersTheOpenCards()
	{
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(rec("e1", "Zulrah", 2042, T0));
		LootTrackerView view = new LootTrackerView(null, null, new OsrsTelemetryConfig()
		{
			@Override
			public LootValuationMode lootValuationMode()
			{
				return mode;
			}
		}, prefs);
		view.setSize(225, 2000);
		view.render(LootTrackerSnapshot.from(index, prefs));
		Object bodyBefore;
		try
		{
			@SuppressWarnings("unchecked")
			List<Object> cards = (List<Object>) field(view, "displayedCards");
			bodyBefore = field(cards.get(0), "body");
			assertNotNull(bodyBefore);

			mode = LootValuationMode.HIGH_ALCH;
			view.render(LootTrackerSnapshot.from(index, prefs)); // same data, same price version
			Object bodyAfter = field(cards.get(0), "body");
			assertNotSame("the open card is re-valued, not skipped by the render key", bodyBefore, bodyAfter);
			assertTrue(String.valueOf(field(view, "lastRenderKey")).contains("valuation:" + LootValuationMode.HIGH_ALCH));
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
	}

	@Test
	public void cardPreferenceWrites_coverRawVariantsHiddenBehindAReset()
	{
		String keyA = LootTrackerIndex.sourceKey("Goat", 1);
		String keyB = LootTrackerIndex.sourceKey("Goat", 2);
		LootTrackerIndex index = new LootTrackerIndex();
		index.apply(rec("a1", "Goat", 1, T0));
		index.apply(rec("b1", "Goat", 2, T0.plusSeconds(1)));
		prefs.setFavorite(java.util.Arrays.asList(keyA, keyB), true);
		prefs.resetSource(keyA, T0.plusSeconds(5));
		prefs.resetSource(keyB, T0.plusSeconds(5));
		index.apply(rec("b2", "Goat", 2, T0.plusSeconds(10))); // only variant B comes back

		LootTrackerSnapshot.SourceEntry card = LootTrackerSnapshot.from(index, prefs).getAllSources().get(0);
		assertEquals(1, card.getKillCount());
		assertTrue(card.getRawSourceKeys().contains(keyA));
		assertTrue(card.getRawSourceKeys().contains(keyB));
		assertTrue(card.isFavorite());

		// Unfavorite the card, then variant A returns: the card stays unfavorited.
		prefs.setFavorite(card.getRawSourceKeys(), false);
		index.apply(rec("a2", "Goat", 1, T0.plusSeconds(20)));
		LootTrackerSnapshot.SourceEntry after = LootTrackerSnapshot.from(index, prefs).getAllSources().get(0);
		assertEquals(2, after.getKillCount());
		assertFalse(after.isFavorite());
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.LootValuationMode;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.LootTrackerSnapshot;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.ActionListener;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JTextField;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Loot Tracker INDIVIDUAL = one global chronological stream of loot records
 * (newest first) across every source -- event order wins over source
 * grouping -- in the real (headless) view, with search, hidden items, reset
 * watermarks, GE/HA, Load more and the Grouped view checked around it.
 */
public class LootTrackerIndividualStreamTest
{
	private static final Instant T0 = Instant.parse("2026-09-30T12:00:00Z");

	private Path testRoot;
	private LootTrackerPreferences prefs;
	private LootTrackerIndex index;
	private LootTrackerView view;
	private LootValuationMode mode = LootValuationMode.GRAND_EXCHANGE;

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-individual-stream-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		prefs = new LootTrackerPreferences(new LocalStateStore(new Gson()));
		prefs.loadForAccount(7L);
		index = new LootTrackerIndex();
		// t1 Kraken, t2 Cave kraken, t3 Kraken, t4 Gargoyle, t5 Kraken
		drop("t1", "Kraken", 494, 1, new LootTrackerItem(3272, "Kraken tentacle", 1));
		drop("t2", "Cave kraken", 492, 2, new LootTrackerItem(995, "Coins", 40));
		drop("t3", "Kraken", 494, 3, new LootTrackerItem(995, "Coins", 900), new LootTrackerItem(560, "Death rune", 30));
		drop("t4", "Gargoyle", 412, 4, new LootTrackerItem(1365, "Steel battleaxe", 1));
		drop("t5", "Kraken", 494, 5, new LootTrackerItem(560, "Death rune", 60));
		view = new LootTrackerView(null, null, new OsrsTelemetryConfig()
		{
			@Override
			public LootValuationMode lootValuationMode()
			{
				return mode;
			}
		}, prefs);
		seedPrices();
		view.setSize(225, 4000);
		render();
		press(button("Grouped")); // -> Individual
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	private void drop(String id, String source, int sourceId, long second, LootTrackerItem... items)
	{
		index.apply(new LootTrackerRecord(id, source, sourceId, T0.plusSeconds(second), Arrays.asList(items)));
	}

	private void render()
	{
		view.render(LootTrackerSnapshot.from(index, prefs));
	}

	private void seedPrices() throws Exception
	{
		java.lang.reflect.Field f = LootTrackerView.class.getDeclaredField("itemValuationCache");
		f.setAccessible(true);
		Object cache = f.get(view);
		for (String[] spec : new String[][] {{"gePrices", "200"}, {"haPrices", "100"}})
		{
			java.lang.reflect.Field pf = cache.getClass().getDeclaredField(spec[0]);
			pf.setAccessible(true);
			Object resolving = pf.get(cache);
			java.lang.reflect.Method put = resolving.getClass().getDeclaredMethod("put", Object.class, Object.class);
			put.setAccessible(true);
			for (int id : new int[] {3272, 995, 560, 1365})
			{
				put.invoke(resolving, id, id == 995 ? 1L : Long.parseLong(spec[1]));
			}
		}
	}

	private JButton button(String text)
	{
		for (Component c : all(view))
		{
			if (c instanceof JButton && text.equals(((JButton) c).getText()))
			{
				return (JButton) c;
			}
		}
		return null;
	}

	private static void press(JButton b)
	{
		for (ActionListener l : b.getActionListeners())
		{
			l.actionPerformed(null);
		}
	}

	private void search(String text) throws Exception
	{
		java.lang.reflect.Field f = LootTrackerView.class.getDeclaredField("searchField");
		f.setAccessible(true);
		((JTextField) f.get(view)).setText(text);
	}

	private static List<Component> all(Container root)
	{
		List<Component> out = new ArrayList<>();
		for (Component c : root.getComponents())
		{
			out.add(c);
			if (c instanceof Container)
			{
				out.addAll(all((Container) c));
			}
		}
		return out;
	}

	/** Source headline of every rendered record card, in display order. */
	private List<String> stream()
	{
		List<String> out = new ArrayList<>();
		for (Component c : all(view))
		{
			if (c instanceof JLabel && LootTrackerView.RECORD_SOURCE_NAME.equals(c.getName()))
			{
				out.add(((JLabel) c).getText());
			}
		}
		return out;
	}

	private List<String> recordValues()
	{
		List<String> out = new ArrayList<>();
		for (Component c : all(view))
		{
			if (LootTrackerView.RECORD_CARD_NAME.equals(c.getName()))
			{
				for (Component k : all((Container) c))
				{
					if (k instanceof JLabel && ((JLabel) k).getText() != null && ((JLabel) k).getText().endsWith(" gp"))
					{
						out.add(((JLabel) k).getText());
					}
				}
			}
		}
		return out;
	}

	private static final List<String> CHRONOLOGICAL = Arrays.asList("Kraken", "Gargoyle", "Kraken", "Cave kraken", "Kraken");

	@Test
	public void individual_followsActualEventOrder_newestFirst_notGroupedByNpc()
	{
		assertEquals(CHRONOLOGICAL, stream());
		assertNotEquals("never all Kraken first", Arrays.asList("Kraken", "Kraken", "Kraken", "Cave kraken", "Gargoyle"), stream());
	}

	@Test
	public void eachRecord_isHeadedByItsSource_withTheTimeOnlyInTheTooltip()
	{
		for (Component c : all(view))
		{
			if (c instanceof JLabel && LootTrackerView.RECORD_SOURCE_NAME.equals(c.getName()))
			{
				JLabel l = (JLabel) c;
				assertFalse("source, never a timestamp, is the headline", l.getText().matches(".*\\d{2}:\\d{2}.*"));
				assertTrue(l.getToolTipText().startsWith(l.getText() + " -- "));
			}
		}
	}

	@Test
	public void newDrop_entersAtTheTop_withoutRegroupingAnything()
	{
		drop("t6", "Cave kraken", 492, 6, new LootTrackerItem(995, "Coins", 12));
		render();
		assertEquals(Arrays.asList("Cave kraken", "Kraken", "Gargoyle", "Kraken", "Cave kraken", "Kraken"), stream());
	}

	@Test
	public void search_keepsChronology_andClearingRestoresTheOriginalStream() throws Exception
	{
		search("death RUNE");
		assertEquals("case-insensitive, still chronological, never regrouped", Arrays.asList("Kraken", "Kraken"), stream());
		search("coins");
		assertEquals(Arrays.asList("Kraken", "Cave kraken"), stream());
		search("");
		assertEquals(CHRONOLOGICAL, stream());
	}

	@Test
	public void hiddenItems_respected_showHiddenRestoresThem()
	{
		prefs.setItemHidden(LootTrackerIndex.sourceKey("Gargoyle", 412), 1365, true);
		render();
		assertEquals("a record with only hidden items drops out", Arrays.asList("Kraken", "Kraken", "Cave kraken", "Kraken"), stream());
		prefs.setShowHidden(true);
		render();
		assertEquals(CHRONOLOGICAL, stream());
	}

	@Test
	public void sourceResetWatermark_removesOnlyThatSourcesOlderRecords()
	{
		prefs.resetSource(LootTrackerIndex.sourceKey("Kraken", 494), T0.plusSeconds(4));
		render();
		assertEquals(Arrays.asList("Kraken", "Gargoyle", "Cave kraken"), stream());
	}

	@Test
	public void valuationModeChange_revaluesTheSameStream()
	{
		List<String> ge = recordValues();
		mode = LootValuationMode.HIGH_ALCH;
		render();
		assertEquals(CHRONOLOGICAL, stream());
		assertNotEquals(ge, recordValues());
	}

	@Test
	public void viewToggles_neverCorruptTheOrder_groupedStaysGroupedBySource()
	{
		for (int i = 0; i < 3; i++)
		{
			press(button("Individual")); // -> Grouped
			assertTrue("Grouped renders no record cards", stream().isEmpty());
			List<String> titles = new ArrayList<>();
			for (Component c : all(view))
			{
				if (c instanceof JLabel && LootTrackerView.SOURCE_TITLE_NAME.equals(c.getName()))
				{
					titles.add(((JLabel) c).getText());
				}
			}
			assertEquals("one card per source, most recent first", Arrays.asList("Kraken", "Gargoyle", "Cave kraken"), titles);
			press(button("Grouped")); // -> Individual
			assertEquals(CHRONOLOGICAL, stream());
		}
	}

	@Test
	public void loadMore_extendsTheStreamInOrder_boundedByTheCap()
	{
		for (int i = 0; i < 120; i++)
		{
			drop("x" + i, i % 3 == 0 ? "Gargoyle" : "Kraken", i % 3 == 0 ? 412 : 494, 100 + i, new LootTrackerItem(995, "Coins", 1));
		}
		render();
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL, stream().size());
		List<String> first = stream();
		press(button("Load more"));
		List<String> more = stream();
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL + LootTrackerView.INDIVIDUAL_REVEAL_INCREMENT, more.size());
		assertEquals("older records are appended below", first, more.subList(0, first.size()));
		press(button("Load more"));
		assertEquals("all 125 now shown", 125, stream().size());
		assertEquals(CHRONOLOGICAL, stream().subList(120, 125));
		assertTrue("nothing left to load", button("Load more") == null);
	}
}

package com.osrstelemetry.plugin.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.osrstelemetry.plugin.OsrsTelemetryConfig;
import com.osrstelemetry.plugin.loottracker.LootTrackerIndex;
import com.osrstelemetry.plugin.loottracker.LootTrackerItem;
import com.osrstelemetry.plugin.loottracker.LootTrackerPreferences;
import com.osrstelemetry.plugin.loottracker.LootTrackerRecord;
import com.osrstelemetry.plugin.storage.LocalStateStore;
import com.osrstelemetry.plugin.storage.TelemetryPaths;
import com.osrstelemetry.plugin.storage.TestFilepaths;
import com.osrstelemetry.plugin.ui.model.LootTrackerSnapshot;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.ActionListener;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Loot Tracker interactions are local and bounded: one card toggle touches
 * one card, bulk controls are one batch (one preference write, no full
 * render), the grouped/individual switch keeps card shells, and the
 * Individual view is one bounded global stream (never per-source cards).
 */
public class LootTrackerInteractionTest
{
	private static final Instant T0 = Instant.parse("2026-09-01T00:00:00Z");

	private Path testRoot;
	private int writes;
	private int refreshRequests;
	private LootTrackerPreferences prefs;
	private LootTrackerIndex index;
	private LootTrackerView view;

	private final class CountingStore extends LocalStateStore
	{
		CountingStore()
		{
			super(new Gson());
		}

		@Override
		public void write(net.runelite.client.util.Filepath target, Object document, Runnable onWritten)
		{
			writes++;
		}
	}

	@Before
	public void setUp() throws Exception
	{
		testRoot = Files.createTempDirectory("loot-interaction-test");
		TelemetryPaths.init(TestFilepaths.rooted(testRoot));
		prefs = new LootTrackerPreferences(new CountingStore());
		prefs.loadForAccount(1L);
		index = build(15, 60);
		view = new LootTrackerView(null, null, new OsrsTelemetryConfig()
		{
		}, prefs);
		view.setRefreshRequester(() -> refreshRequests++);
		view.setSize(225, 4000);
		render();
		writes = 0;
		refreshRequests = 0;
	}

	@After
	public void tearDown() throws Exception
	{
		TestFilepaths.rooted(testRoot).deleteRecursively();
	}

	/** {@code sources} sources (Source 0 oldest ... newest last), {@code records} drops each of 3 items. */
	private static LootTrackerIndex build(int sources, int records)
	{
		LootTrackerIndex idx = new LootTrackerIndex();
		int ev = 0;
		for (int s = 0; s < sources; s++)
		{
			for (int r = 0; r < records; r++)
			{
				List<LootTrackerItem> items = new ArrayList<>();
				for (int i = 0; i < 3; i++)
				{
					int id = 1000 + s * 10 + (r + i) % 8;
					items.add(new LootTrackerItem(id, (s % 2 == 0 ? "Rune item " : "Iron item ") + id, 1 + r));
				}
				idx.apply(new LootTrackerRecord("e" + (ev++), "Source " + s, s, T0.plusSeconds(ev), items));
			}
		}
		return idx;
	}

	private void render()
	{
		view.render(LootTrackerSnapshot.from(index, prefs));
	}

	// ------------------------------------------------------------------ reflection helpers

	private static Object field(Object target, String name) throws Exception
	{
		Class<?> c = target.getClass();
		while (c != null)
		{
			try
			{
				java.lang.reflect.Field f = c.getDeclaredField(name);
				f.setAccessible(true);
				return f.get(target);
			}
			catch (NoSuchFieldException e)
			{
				c = c.getSuperclass();
			}
		}
		throw new NoSuchFieldException(name);
	}

	@SuppressWarnings("unchecked")
	private List<Object> displayed() throws Exception
	{
		return new ArrayList<>((List<Object>) field(view, "displayedCards"));
	}

	private Object card(String sourceName) throws Exception
	{
		for (Object card : displayed())
		{
			LootTrackerSnapshot.SourceEntry entry = (LootTrackerSnapshot.SourceEntry) field(card, "entry");
			if (sourceName.equals(entry.getSourceName()))
			{
				return card;
			}
		}
		return null;
	}

	private static Object body(Object card) throws Exception
	{
		return field(card, "body");
	}



	private static Set<Component> all(Container c)
	{
		Set<Component> s = Collections.newSetFromMap(new IdentityHashMap<>());
		collect(c, s);
		return s;
	}

	private static void collect(Container c, Set<Component> s)
	{
		for (Component k : c.getComponents())
		{
			s.add(k);
			if (k instanceof Container)
			{
				collect((Container) k, s);
			}
		}
	}

	private static JLabel label(Container c, String prefix)
	{
		for (Component k : c.getComponents())
		{
			if (k instanceof JLabel && ((JLabel) k).getText() != null && ((JLabel) k).getText().startsWith(prefix))
			{
				return (JLabel) k;
			}
			if (k instanceof Container)
			{
				JLabel r = label((Container) k, prefix);
				if (r != null)
				{
					return r;
				}
			}
		}
		return null;
	}

	private static void click(Component c)
	{
		for (MouseListener l : c.getMouseListeners())
		{
			l.mouseClicked(new MouseEvent(c, MouseEvent.MOUSE_CLICKED, 0, 0, 1, 1, 1, false));
		}
	}

	private void clickTitle(String sourceName)
	{
		for (Component c : all(view))
		{
			if (c instanceof JLabel && LootTrackerView.SOURCE_TITLE_NAME.equals(c.getName()) && sourceName.equals(((JLabel) c).getText()))
			{
				click(c);
				return;
			}
		}
		throw new AssertionError("no title label for " + sourceName);
	}

	private JButton button(String text)
	{
		for (Component c : all(view))
		{
			if (c instanceof JButton && text.equals(((JButton) c).getText()))
			{
				return (JButton) c;
			}
		}
		return null;
	}

	private static void press(JButton b)
	{
		for (ActionListener l : b.getActionListeners())
		{
			l.actionPerformed(null);
		}
	}

	private void toIndividual()
	{
		press(button("Grouped"));
	}

	private void toGrouped()
	{
		press(button("Individual"));
	}

	private void search(String text) throws Exception
	{
		((JTextField) field(view, "searchField")).setText(text);
	}

	private boolean manualCollapsed(String sourceName, int id)
	{
		return prefs.isCollapsed(LootTrackerIndex.sourceKey(sourceName, id));
	}

	private List<Component> contentOrder() throws Exception
	{
		List<Component> out = new ArrayList<>();
		Collections.addAll(out, ((JPanel) field(view, "content")).getComponents());
		return out;
	}

	// ------------------------------------------------------------------ 1-4 single card

	@Test
	public void collapseOne_touchesOnlyThatCard_immediately_oneWrite_noFullRender() throws Exception
	{
		Object target = card("Source 7");
		Map<Object, Object> otherBodies = new IdentityHashMap<>();
		for (Object c : displayed())
		{
			otherBodies.put(c, body(c));
		}
		Set<Component> before = all(view);
		clickTitle("Source 7");
		assertNull("collapsed at once -- no poll wait", body(target));
		assertTrue(manualCollapsed("Source 7", 7));
		assertEquals(1, writes);
		assertEquals("a local toggle requests no full render", 0, refreshRequests);
		for (Object c : displayed())
		{
			if (c != target)
			{
				assertSame("other cards' bodies untouched", otherBodies.get(c), body(c));
			}
		}
		Set<Component> after = all(view);
		for (Component c : after)
		{
			assertTrue("collapsing creates nothing", before.contains(c));
		}
	}

	@Test
	public void expandOne_buildsOnlyThatCardsBody() throws Exception
	{
		clickTitle("Source 7");
		Set<Component> before = all(view);
		clickTitle("Source 7");
		assertNotNull(body(card("Source 7")));
		Set<Component> created = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Component c : all(view))
		{
			if (!before.contains(c))
			{
				created.add(c);
			}
		}
		Set<Component> body = all((Container) body(card("Source 7")));
		body.add((Component) body(card("Source 7")));
		body.add((Component) field(card("Source 7"), "bodyGap")); // the retained gap is re-added, not new
		assertTrue(created.size() > 0);
		for (Component c : created)
		{
			assertTrue("only the reopened body is new: " + c.getClass(), body.contains(c));
		}
	}

	@Test
	public void individualMode_isOneGlobalStream_noSourceCardsAttached() throws Exception
	{
		toIndividual();
		assertTrue("Individual shows records, not source cards", displayed().isEmpty());
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL, view.individualRecordsMaterialized());
		JButton bulk = button(LootTrackerView.BULK_COLLAPSE_TEXT);
		assertTrue("source collapse controls have nothing to act on in Individual", bulk == null || !bulk.isEnabled());
	}


	@Test
	public void sourceCollapse_isAGroupedConcept_neverHidesDropsFromTheStream() throws Exception
	{
		clickTitle("Source 14");
		assertNull(body(card("Source 14")));
		toIndividual();
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL, view.individualRecordsMaterialized());
		toGrouped();
		assertNull("the manual collapse is kept for Grouped", body(card("Source 14")));
		assertTrue(manualCollapsed("Source 14", 14));
	}


	// ------------------------------------------------------------------ 5-12 bulk

	private void assertAllCollapsed(boolean collapsed) throws Exception
	{
		for (Object c : displayed())
		{
			assertEquals(collapsed, body(c) == null);
		}
	}

	@Test
	public void collapseAll_andOpenAll_grouped_oneWriteEach_noFullRender_orderKept() throws Exception
	{
		List<Component> order = contentOrder();
		press(button("▸ All"));
		assertAllCollapsed(true);
		assertEquals("one logical preference write", 1, writes);
		assertEquals("no queued full render", 0, refreshRequests);
		assertEquals(order, contentOrder());
		for (int s = 0; s < 15; s++)
		{
			assertTrue(manualCollapsed("Source " + s, s));
		}
		press(button("▾ All"));
		assertAllCollapsed(false);
		assertEquals(2, writes);
		assertEquals(0, refreshRequests);
		assertEquals(order, contentOrder());
	}

	@Test
	public void individualStream_neverExceedsTheHardBudget() throws Exception
	{
		toIndividual();
		for (int i = 0; i < 30; i++)
		{
			JButton more = button("Load more");
			if (more == null)
			{
				break;
			}
			press(more);
			assertTrue(view.individualRecordsMaterialized() <= LootTrackerView.MAX_TOTAL_INDIVIDUAL_RECORDS_RENDERED);
		}
		assertEquals("15 x 60 records, capped", LootTrackerView.MAX_TOTAL_INDIVIDUAL_RECORDS_RENDERED, view.individualRecordsMaterialized());
		assertNull("no Load more past the cap", button("Load more"));
		assertEquals("Load more never writes preferences", 0, writes);
	}


	@Test
	public void loadMore_extendsTheGlobalStream_byOneStep_keepingTheNewerRecordsInPlace() throws Exception
	{
		toIndividual();
		Set<Component> before = all(view);
		List<Component> firstCards = recordCards();
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL, firstCards.size());
		press(button("Load more"));
		List<Component> after = recordCards();
		assertEquals(LootTrackerView.DEFAULT_INDIVIDUAL_REVEAL + LootTrackerView.INDIVIDUAL_REVEAL_INCREMENT, after.size());
		for (int i = 0; i < firstCards.size(); i++)
		{
			assertSame("existing record cards are retained, in place", firstCards.get(i), after.get(i));
		}
		for (Component c : firstCards)
		{
			assertTrue(before.contains(c));
		}
	}

	private List<Component> recordCards()
	{
		List<Component> out = new ArrayList<>();
		collectRecordCards(view, out);
		return out;
	}

	private static void collectRecordCards(Container c, List<Component> out)
	{
		for (Component k : c.getComponents())
		{
			if (LootTrackerView.RECORD_CARD_NAME.equals(k.getName()))
			{
				out.add(k);
			}
			else if (k instanceof Container)
			{
				collectRecordCards((Container) k, out);
			}
		}
	}


