			LootGridCell.GRID_COLUMNS, LootTrackerView.LOOT_ITEMS_PER_ROW);
		assertEquals(5, LootGridCell.GRID_COLUMNS);
		java.awt.GridLayout layout = LootGridCell.newGridLayout();
		assertEquals(0, layout.getRows());
